window.GSAT_7000_ENRICHMENT = {"version":"2026-09-08","entries":{"l1-0001":[["冠詞：一個（非特定）","無直接同義詞","I packed a sandwich and an apple for lunch.","我帶了一個三明治和一顆蘋果當午餐。","a、an 依後接字的起首發音選用；an 接以母音音素起首的詞，判斷依據是發音而非字母。"]],"l1-0002":[["形容詞：有能力的","capable","Mia is able to swim across the small pool.","米雅能游到這座小泳池的另一端。","be able to + 原形動詞；capable 通常用 capable of + 動名詞。"]],"l1-0003":[["介系詞：關於","concerning / regarding","We talked about our plans for the summer holiday.","我們聊了暑假的計畫。","concerning、regarding 較正式。"]],"l1-0004":[["介系詞：在……上方","over","A round clock hangs above the classroom door.","教室門的上方掛著一座圓鐘。","above 不要求接觸，也不一定在正上方。"]],"l1-0005":[["介系詞片語：根據","無直接同義詞","According to the map, the station is near the river.","根據地圖，車站在河邊附近。","用來交代資訊來源；不等於表達自己看法的 in my opinion。"]],"l1-0006":[["介系詞：橫越；穿過","無直接同義詞","Hold my hand when we walk across this busy road.","走過這條繁忙的馬路時，牽著我的手。","across 指從一邊到另一邊；through 側重穿過內部。"]],"l1-0007":[["及物動詞：扮演","play","Leo will act the part of a king tonight.","里歐今晚將扮演國王。","act the part of、play the part of 都可表示扮演某角色。"]],"l1-0008":[["名詞：行動","steps / measures","The school took action to keep the playground clean.","學校採取了行動，保持操場整潔。","take action、take steps、take measures 都可表示採取行動。"]],"l1-0009":[["名詞：演員；女演員","無直接同義詞","The actor and actress practiced their lines before the show.","這位男演員和女演員在演出前練習台詞。","actor 也可不分性別；performer 範圍更廣，不視為完全同義。"]],"l1-0010":[["及物動詞：添加","put in","Add a little milk if the soup is too thick.","如果湯太濃，就加一點牛奶。",""]],"l1-0011":[["名詞：地址","無直接同義詞","Please include your address so we can mail the tickets.","請填上你的地址，方便我們郵寄門票。",""]],"l1-0012":[["名詞：成年人","grown-up","Each child must visit the museum with an adult.","每個孩子都必須由一位成人陪同參觀博物館。","grown-up 較口語，常用於對孩子說話。"]],"l1-0013":[["形容詞：害怕的","scared / frightened","My little brother is afraid of the dark.","我的小弟弟怕黑。","常用 be afraid of + 名詞。"]],"l1-0014":[["介系詞：在……之後","following","We usually wash the dishes together after dinner.","晚餐後，我們通常一起洗碗。","following 作介系詞時較正式。"]],"l1-0015":[["名詞：下午","無直接同義詞","The children spent the afternoon making paper boats.","孩子們花了一下午做紙船。",""]],"l1-0016":[["副詞：再一次","once more / once again","Please read the last sentence again, a little more slowly.","請把最後一句再讀一次，稍微慢一點。",""]],"l1-0017":[["介系詞：反對","opposed to","Many parents are against closing the school library.","許多家長反對關閉學校圖書館。","opposed to 是形容詞片語，可用於 be opposed to。"]],"l1-0018":[["名詞：年齡","無直接同義詞","Ella learned to ride a bike at the age of six.","艾拉六歲時學會了騎腳踏車。",""]],"l1-0019":[["副詞：以前（從現在回推）","無直接同義詞","We moved into this apartment three years ago.","我們三年前搬進這間公寓。","時間長度 + ago；通常搭配過去式。"]],"l1-0020":[["不及物動詞：同意","concur","I agree with you that the blue curtains look better.","我同意你的看法，藍色窗簾比較好看。","agree 是動詞，agreement 是名詞；agree with someone 表同意某人的看法。concur 較正式。"],["名詞：意見一致；同意","accord","We reached an agreement about sharing the housework.","我們對分擔家事達成了共識。","agreement 是名詞，可指意見一致或達成的協議；reach an agreement 表達成共識或協議。"]],"l1-0021":[["副詞：在前方","in front","The road ahead is narrow, so please drive slowly.","前方的路很窄，請慢慢開。",""]],"l1-0022":[["名詞：空氣","無直接同義詞","Open the window to let some fresh air in.","打開窗戶，讓一些新鮮空氣進來。",""]],"l1-0023":[["名詞：航空郵件服務","無直接同義詞","Grandma sent the birthday card to Australia by airmail.","奶奶用航空郵件把生日卡片寄到澳洲。","常用 by airmail，表示以航空郵件方式寄送。"]],"l1-0024":[["名詞：飛機","airplane / plane / aeroplane","Our airplane landed safely despite the strong wind.","儘管風很強，我們搭的飛機仍安全降落。","plane 是 airplane 的常用簡稱；aeroplane 為英式拼法。"]],"l1-0025":[["名詞：機場","無直接同義詞","We arrived at the airport two hours before our flight.","我們在班機起飛前兩小時抵達機場。",""]],"l1-0026":[["限定詞：所有的","every","All the windows were open on that hot day.","那個炎熱的日子裡，所有窗戶都開著。","every 接單數可數名詞；all 可接複數名詞。"]],"l1-0027":[["及物動詞：允許","permit / let","My parents allow me to stay up late on Saturdays.","爸媽允許我星期六晚睡。","allow someone to do；let someone do，不加 to。"]],"l1-0028":[["副詞：幾乎","nearly","The children had almost finished dinner when Grandma arrived.","奶奶到的時候，孩子們已經快吃完晚餐了。",""]],"l1-0029":[["副詞：獨自","by oneself / on one's own","Sofia walked home alone after the piano lesson.","鋼琴課結束後，蘇菲亞獨自走路回家。","alone 不一定表示孤單難過；那種感受用 lonely。"]],"l1-0030":[["介系詞：沿著","無直接同義詞","We followed a narrow path along the river.","我們沿著河邊的一條小路走。",""]],"l1-0031":[["副詞：已經","無直接同義詞","Don't buy bread; I have already bought two loaves.","不用買麵包了；我已經買了兩條。",""]],"l1-0032":[["副詞：也","too / as well","This shop sells flowers and also delivers them.","這間店賣花，也提供送花服務。","too、as well 通常放句尾。"]],"l1-0033":[["副詞：總是","every time","Dad always checks the door before he goes to bed.","爸爸睡前總會檢查一下門。","every time 通常改接子句，例如 every time he goes to bed。"]],"l1-0034":[["連綴動詞：是（I 的現在式）","無直接同義詞","I am the only student here who can play chess.","我是這裡唯一會下西洋棋的學生。","am 是 be 搭配第一人稱單數 I 的現在式。"]],"l1-0035":[["介系詞：在……之中","amid","I found my keys among the papers on my desk.","我在書桌上的文件堆裡找到了鑰匙。","amid 較書面；among 常用於一群人或物之中。"]],"l1-0036":[["連接詞：和；並且","無直接同義詞","Lily washed the tomatoes and cut them into small pieces.","莉莉把番茄洗乾淨，再切成小塊。",""]],"l1-0037":[["名詞：憤怒","rage / fury","His voice shook with anger when he saw the broken window.","他看見破掉的窗戶時，氣得聲音發抖。","rage、fury 比 anger 更強烈。"]],"l1-0038":[["形容詞：生氣的","mad / furious","Nina was angry because someone had taken her lunch.","妮娜很生氣，因為有人拿走了她的午餐。","mad 表示生氣主要見於美式英語；furious 程度更強。"]],"l1-0039":[["名詞：動物","無直接同義詞","The children watched each animal carefully during the farm visit.","參觀農場時，孩子們仔細觀察每一隻動物。",""]],"l1-0040":[["限定詞：另一個","one more / a further","Could you bring another chair for our new guest?","你能為新來的客人再拿一張椅子嗎？","本句表示額外再一個；another 也可表示不同的一個。"]],"l1-0041":[["名詞：回答","reply / response","Her answer to my question was clear and helpful.","她對我的問題的回答很清楚，也很有幫助。",""],["及物動詞：回答","respond to / reply to","Please answer the last question in a full sentence.","請用完整的句子回答最後一題。","answer 直接接受詞；respond、reply 後通常加 to。"]],"l1-0042":[["名詞：螞蟻","無直接同義詞","An ant carried a crumb across the kitchen floor.","一隻螞蟻搬著麵包屑爬過廚房地板。",""]],"l1-0043":[["限定詞：任何一個","whichever","You can choose any book from this shelf.","你可以從這個書架上任選一本書。","whichever 強調在一組選項中任選，句型需調整。"]],"l1-0044":[["代名詞：任何東西","無直接同義詞","I couldn't see anything through the thick fog.","濃霧中，我什麼也看不見。","anything 是不定代名詞，常見於否定句，也可用於疑問句、條件句等結構。"]],"l1-0045":[["名詞：猿","無直接同義詞","The young ape reached for fruit on a high branch.","那隻年幼的猿伸手去拿高處樹枝上的水果。","ape 泛指猿，並非只指大猩猩；大猩猩是 gorilla。"]],"l1-0046":[["不及物動詞：出現","show up / emerge","A rainbow appeared over the fields after the rain.","雨後，田野上空出現了一道彩虹。","show up 較口語；emerge 常含逐漸出現之意。"]],"l1-0047":[["名詞：蘋果","無直接同義詞","She cut the apple into slices for her son.","她把蘋果切成片給兒子吃。",""]],"l1-0048":[["名詞：四月","無直接同義詞","Our school picnic is on the first Friday in April.","我們學校的野餐活動在四月的第一個星期五。","Apr. 是 April 的縮寫。"]],"l1-0049":[["連綴動詞：是（be 的現在式）","無直接同義詞","You are the first person to arrive this morning.","你是今天早上第一個到的人。","are 不限第二人稱，也搭配 we、they 及複數名詞。"]],"l1-0050":[["名詞：面積","無直接同義詞","The two rooms have the same area but different shapes.","這兩間房間的面積相同，但形狀不同。","此處取面積義；region 只適用於地區義。"]],"l1-0051":[["名詞：手臂","無直接同義詞","He carried the sleeping child in his arms.","他把睡著的孩子抱在懷裡。",""]],"l1-0052":[["名詞：陸軍；軍隊","無直接同義詞","Her older brother joined the army after finishing school.","她哥哥畢業後加入了陸軍。","army 常專指陸軍；armed forces 泛指各軍種。"]],"l1-0053":[["副詞：到處；四處","about","We looked around but couldn't find a place to sit.","我們四處看了看，卻找不到地方坐。","look about 也表示環顧，較常見於英式用法。"]],"l1-0054":[["名詞：藝術","無直接同義詞","The museum has a room full of modern art.","博物館有一個展間，裡面全是現代藝術作品。",""]],"l1-0055":[["介系詞：以……身分；作為","無直接同義詞","She worked as a nurse before becoming a teacher.","她成為老師之前，曾擔任護理師。","as 表示實際身分；like 表示像，不能在此直接替換。"]],"l1-0056":[["及物動詞：詢問","inquire","I asked the driver where I should get off.","我問司機應該在哪裡下車。","inquire 較正式，通常不直接接人作受詞；可改說 inquire of someone 或 inquire where ...。"]],"l1-0057":[["介系詞：在（地點）","無直接同義詞","Meet me at the bus stop outside the library.","在圖書館外面的公車站和我碰面。",""]],"l1-0058":[["名詞：八月","無直接同義詞","We often visit our cousins in August during summer vacation.","暑假期間，我們常在八月去探望堂表親。","Aug. 是 August 的縮寫。"]],"l1-0059":[["名詞：阿姨；姑姑等女性親屬","auntie / aunty","My aunt took me to the zoo for my birthday.","我生日那天，阿姨帶我去動物園。","aunt 不只伯母，也含姨、姑、嬸等；auntie、aunty 是親暱稱呼。"]],"l1-0060":[["名詞：秋天","autumn / fall","The leaves turn yellow and red in autumn.","秋天時，樹葉會變成黃色和紅色。","fall 為常見美式用法，autumn 在英美皆可用。"]],"l1-0061":[["副詞：離開；遠離","無直接同義詞","Keep the hot pan away from the children.","把熱鍋子放在孩子碰不到的地方。","away from 表示與某人或物保持距離。"]],"l1-0062":[["名詞：嬰兒","infant","The baby fell asleep while her father sang softly.","爸爸輕聲唱歌時，寶寶睡著了。","infant 較正式。"]],"l1-0063":[["名詞：背部","無直接同義詞","My back hurts after carrying that heavy box.","搬過那個重箱子後，我的背很痛。",""]],"l1-0064":[["形容詞：不好的；惡劣的","poor / awful","Bad weather kept us indoors for the whole weekend.","惡劣的天氣讓我們整個週末都待在室內。","awful 的負面程度較強。"]],"l1-0065":[["名詞：袋子","sack","She put the dirty clothes into a large bag.","她把髒衣服放進一個大袋子裡。","sack 通常指較大的袋子，不等於所有款式的 bag。"]],"l1-0066":[["名詞：球","無直接同義詞","The ball rolled under a car near the gate.","球滾到大門附近的一輛車底下。",""]],"l1-0067":[["名詞：氣球","無直接同義詞","A red balloon floated above the birthday table.","一顆紅色氣球飄在生日餐桌上方。",""]],"l1-0068":[["名詞：香蕉","無直接同義詞","I sliced a banana and added it to my cereal.","我把一根香蕉切片，加進早餐穀片裡。",""]],"l1-0069":[["名詞：帶子；環帶","strap","A red band around the suitcase made it easy to find.","行李箱上繫著一條紅帶，所以很容易找到。","strap 通常指有固定或捆綁用途的帶子；適合本例圍住行李箱的情境。"]],"l1-0070":[["名詞：銀行","無直接同義詞","I went to the bank to open a savings account.","我去銀行開了一個儲蓄帳戶。",""],["名詞：河岸","riverbank","We sat on the bank and watched the river flow.","我們坐在河岸上，看著河水流動。","riverbank 指河岸；riverside 指河邊地帶，兩者不完全相同。bank 指河兩側的地面，不一定是人工築成的河堤。"]],"l1-0071":[["名詞：棒；條","rod","A metal bar kept the old wooden door shut.","一根金屬棒抵住了那扇老木門。","rod 通常指細長、截面多為圓形的棒。"],["名詞：酒吧","pub","We met at a quiet bar near the station.","我們在車站附近一間安靜的酒吧見面。","pub 指英式酒館，氣氛與服務可能和 bar 不同。"]],"l1-0072":[["名詞：理髮師","無直接同義詞","The barber trimmed my hair before my job interview.","面試前，理髮師替我修了頭髮。","barber 傳統上以剪男士短髮及修鬍鬚為主。"]],"l1-0073":[["名詞：底部；基底","bottom","The lamp has a heavy base to stop it falling over.","這盞燈的底座很重，可防止它倒下。","base 側重支撐作用，bottom 只指最下面部分。"]],"l1-0074":[["名詞：棒球（運動）","無直接同義詞","We played baseball in the park after school.","放學後，我們在公園打棒球。",""]],"l1-0075":[["形容詞：基礎的","elementary","This course teaches basic English for everyday conversations.","這門課教日常會話所需的基礎英語。","elementary 強調入門程度。"]],"l1-0076":[["名詞：籃子","無直接同義詞","Grandma filled the basket with vegetables from her garden.","奶奶把菜園裡採的蔬菜裝滿了籃子。",""]],"l1-0077":[["名詞：籃球（運動）","無直接同義詞","They practice basketball in the gym every Wednesday evening.","他們每週三晚上都在體育館練籃球。",""]],"l1-0078":[["名詞：球棒","無直接同義詞","He held the bat firmly and waited for the pitch.","他緊握球棒，等待投球。",""],["名詞：蝙蝠","無直接同義詞","A small bat flew out of the cave at sunset.","日落時，一隻小蝙蝠飛出洞穴。",""]],"l1-0079":[["名詞：泡澡；洗澡","無直接同義詞","A warm bath helped me relax after the long walk.","走了很長一段路後，泡個溫水澡讓我放鬆下來。","bath 通常指在浴缸裡洗澡；shower 是淋浴。"]],"l1-0080":[["及物動詞：替……洗澡","wash","We bathe the baby before putting her to bed.","我們先幫寶寶洗澡，再讓她上床睡覺。",""]],"l1-0081":[["名詞：浴室","無直接同義詞","I left a clean towel beside the bathroom sink.","我在浴室洗手台旁放了一條乾淨毛巾。","restroom 指洗手間，未必有洗浴設備。"]],"l1-0082":[["連綴動詞：是；處於某狀態","無直接同義詞","Please be quiet while the baby is sleeping.","寶寶睡覺時，請保持安靜。","本例是祈使句，使用 be 原形。"]],"l1-0083":[["名詞：海灘","無直接同義詞","The children built a sandcastle on the beach.","孩子們在海灘上堆了一座沙堡。","shore 指岸邊，不一定有沙灘。"]],"l1-0084":[["名詞：熊","無直接同義詞","We saw a bear beside the river from our bus.","我們從巴士上看見河邊有一隻熊。",""]],"l1-0085":[["及物動詞：反覆敲打","strike / hit","The boy beat the drum as the dancers entered.","舞者進場時，男孩敲起了鼓。","beat 常有反覆敲擊的意思。"]],"l1-0086":[["形容詞：美麗的","lovely / pretty","The garden looks beautiful when the roses are in bloom.","玫瑰盛開時，花園看起來很美。",""]],"l1-0087":[["名詞：美；美麗","loveliness","We stopped to enjoy the beauty of the mountain lake.","我們停下來欣賞山間湖泊的美。",""]],"l1-0088":[["連接詞：因為","since / as","I brought an umbrella because rain was expected this afternoon.","我帶了傘，因為預計今天下午會下雨。","since、as 表原因時通常把原因當成已知背景。"]],"l1-0089":[["連綴動詞：變得；成為","grow / get","The room became warmer after we closed the window.","關上窗戶後，房間變得暖和些了。","grow 常暗示逐漸變化；get 較口語。"]],"l1-0090":[["名詞：床","無直接同義詞","She sat on the bed to put on her socks.","她坐在床上穿襪子。",""]],"l1-0091":[["名詞：蜜蜂","無直接同義詞","A bee landed on a flower beside the window.","一隻蜜蜂停在窗邊的一朵花上。",""]],"l1-0092":[["介系詞：在……之前","prior to","Please wash your hands before lunch, especially after playing outside.","午餐前請洗手，尤其是在外面玩過之後。","prior to 較正式，後接名詞或動名詞。"]],"l1-0093":[["及物動詞：開始","start","Let's begin the lesson with a short reading exercise.","我們先做一個簡短的閱讀練習，開始這堂課。",""]],"l1-0094":[["介系詞：在……後方","at the back of","The cat hid behind the sofa during the storm.","暴風雨來襲時，貓躲在沙發後面。",""]],"l1-0095":[["及物動詞：相信","trust / accept","I believe her story because I saw what happened.","我相信她的說法，因為我親眼看到了事情經過。","accept a story 表示接受說法；trust 側重信任其可靠性。"]],"l1-0096":[["名詞：鈴；鐘","無直接同義詞","The school bell rang just as I reached the gate.","我剛到校門口，上課鐘就響了。",""]],"l1-0097":[["不及物動詞：屬於","be owned by","Does this blue jacket belong to anyone in this room?","這件藍色外套是這個房間裡某人的嗎？","表示所有權時用 belong to；不可說 is belong to。"]],"l1-0098":[["介系詞：在……下方","under / beneath","The village lies below the castle on the hill.","村莊位於山丘上那座城堡的下方。","below 強調高度較低，未必在正下方。"]],"l1-0099":[["介系詞：在……旁邊","next to / alongside","There's an empty seat beside me if you need one.","如果你需要座位，我旁邊有個空位。",""]],"l1-0100":[["形容詞：最好的","finest","This bakery makes the best bread in our town.","這家麵包店做的麵包是我們鎮上最好吃的。","best 是 good 的最高級。"]],"l1-0101":[["形容詞：更好的","superior","The second plan is better because it costs less.","第二個方案比較好，因為花費較少。","better than；superior to，後接介系詞不同。"]],"l1-0102":[["介系詞：在……之間","無直接同義詞","Our house stands between the bakery and the flower shop.","我們家位於麵包店與花店之間。",""]],"l1-0103":[["名詞：腳踏車","bike / bicycle","I ride my bicycle to the park every Sunday.","我每週日騎腳踏車去公園。","bike 較口語；有時也指機車，需看語境。"]],"l1-0104":[["形容詞：大的","large / huge","We need a big table for all twelve guests.","我們需要一張大桌子，才能坐下十二位客人。","huge 表示非常大。"]],"l1-0105":[["名詞：鳥","無直接同義詞","A bird built a nest under our roof.","一隻鳥在我們的屋簷下築了巢。",""]],"l1-0106":[["名詞：出生","無直接同義詞","The whole family celebrated the birth of our baby sister.","全家人都慶祝小妹妹的誕生。",""]],"l1-0107":[["名詞：一點；少量","small amount","There is a bit of cheese left in the fridge.","冰箱裡還剩下一點起司。","a bit of、a small amount of 都可表示少量。"]],"l1-0108":[["及物動詞：咬","nip","The frightened dog tried to bite the man's hand.","受驚的狗試圖咬那名男子的手。","nip 通常指輕咬或快速咬一下。"]],"l1-0109":[["形容詞：黑色的","無直接同義詞","She wore black shoes with her gray school uniform.","她穿灰色校服，搭配黑色鞋子。",""]],"l1-0110":[["名詞：街區","無直接同義詞","The nearest supermarket is two blocks from our apartment.","最近的超市離我們的公寓有兩個街區。",""]],"l1-0111":[["名詞：血液","無直接同義詞","There was a little blood on his scraped knee.","他擦傷的膝蓋上有一點血。",""]],"l1-0112":[["及物動詞：吹","無直接同義詞","A strong wind blew my hat into the river.","一陣強風把我的帽子吹進了河裡。",""]],"l1-0113":[["形容詞：藍色的","無直接同義詞","He chose a blue shirt to match his jacket.","他選了一件藍色襯衫來搭配外套。",""]],"l1-0114":[["名詞：小船","無直接同義詞","We rented a boat and rowed across the lake.","我們租了一艘小船，划過湖面。",""]],"l1-0115":[["名詞：身體","無直接同義詞","Swimming helps me exercise my whole body at once.","游泳能讓我同時鍛鍊全身。",""]],"l1-0116":[["名詞：骨頭","無直接同義詞","Luckily, she didn't break any bones when she fell.","幸好她跌倒時沒有摔斷任何骨頭。",""]],"l1-0117":[["名詞：書","無直接同義詞","I borrowed a book about birds from the library.","我從圖書館借了一本關於鳥類的書。","volume 作書籍義時較正式，也可指成套書的一冊。"],["及物動詞：預訂","reserve","We booked a room near the station for one night.","我們在車站附近訂了一間房間，住一晚。","book 作動詞表示「預訂」；reserve 較正式。"]],"l1-0118":[["過去分詞：出生的（be born）","無直接同義詞","My grandfather was born in a small fishing village.","我的祖父出生在一個小漁村。","出生用 be born；born 是 bear 的過去分詞形式。"]],"l1-0119":[["限定詞：兩者都","the two","Both sisters enjoy swimming, but only one likes diving.","兩姊妹都喜歡游泳，但只有一人喜歡跳水。","both 強調兩者無一例外；the two 須依語境使用。"]],"l1-0120":[["名詞：底部","無直接同義詞","My missing sock was at the bottom of the basket.","我不見的襪子在籃子底部。","base 常指支撐物體的基底，未必能直接代換容器內的 bottom。"]],"l1-0121":[["名詞：碗","無直接同義詞","He filled a bowl with soup for his mother.","他為媽媽盛了一碗湯。",""]],"l1-0122":[["名詞：箱子","carton","Put the books in this box before we move.","搬家前，把書放進這個箱子裡。","carton 通常是紙板箱。"]],"l1-0123":[["名詞：男孩","lad","The boy next door taught me how to skate.","隔壁的男孩教我溜冰。","lad 常見於英式口語。"]],"l1-0124":[["形容詞：勇敢的","courageous / bold","The brave child spoke up when she saw someone being bullied.","那個勇敢的孩子看見有人被霸凌時，挺身發聲。","bold 也含大膽、敢於冒險之意。"]],"l1-0125":[["名詞：麵包","無直接同義詞","Fresh bread was cooling on a tray by the window.","剛出爐的麵包放在窗邊的托盤上冷卻。",""]],"l1-0126":[["及物動詞：打破；弄壞","smash","Be careful not to break the glass when you wash it.","洗玻璃杯時，小心別把它打破。","smash 指猛烈打碎，程度比 break 強。"]],"l1-0127":[["名詞：早餐","無直接同義詞","I had eggs and toast for breakfast this morning.","我今天早餐吃了蛋和吐司。",""]],"l1-0128":[["名詞：橋","無直接同義詞","The wooden bridge connects the village to the main road.","這座木橋連接村莊與主要道路。",""]],"l1-0129":[["形容詞：明亮的","well-lit","The bright classroom has large windows on two sides.","這間明亮的教室有兩面大窗戶。","well-lit 指照明充足。"]],"l1-0130":[["及物動詞：帶來","無直接同義詞","Please bring your notebook to our meeting tomorrow.","明天開會時，請帶上你的筆記本。","bring 指帶來；fetch 另含先去拿再帶回的動作，不能直接套用本句。"]],"l1-0131":[["名詞：兄弟","無直接同義詞","My older brother helps me with my math homework.","哥哥會幫我解答數學作業上的問題。",""]],"l1-0132":[["形容詞：棕色的","無直接同義詞","The puppy has brown ears and a white tail.","這隻小狗的耳朵是棕色的，尾巴是白色的。",""]],"l1-0133":[["名詞：小蟲","insect","A tiny bug was crawling across my notebook.","一隻小蟲正爬過我的筆記本。","bug 是日常泛稱；insect 在科學分類上有較精確的範圍。"]],"l1-0134":[["及物動詞：建造","construct / erect","They plan to build a new school near the park.","他們計畫在公園附近蓋一所新學校。","construct、erect 較正式。"]],"l1-0135":[["名詞：建築物","edifice","The tallest building in town has a restaurant on top.","鎮上最高的建築物頂樓有一間餐廳。","edifice 較正式，常指大型或宏偉的建築。"]],"l1-0136":[["名詞：公車；巴士","無直接同義詞","The bus was full, so we waited for the next one.","公車客滿了，所以我們等下一班。",""]],"l1-0137":[["形容詞：忙碌的","occupied","I'm busy cooking dinner, so could you answer the phone?","我正忙著煮晚餐，你能幫忙接電話嗎？","busy doing；occupied with，搭配不同。"]],"l1-0138":[["連接詞：但是","yet","I wanted to walk home, but it started raining.","我原本想走路回家，但開始下雨了。","yet 作連接詞時語氣較書面，常帶出乎意料的對比。"]],"l1-0139":[["名詞：奶油","無直接同義詞","Spread some butter on the toast while it's warm.","趁吐司還溫熱時，抹上一點奶油。",""]],"l1-0140":[["名詞：蝴蝶","無直接同義詞","A yellow butterfly rested on the garden fence.","一隻黃色蝴蝶停在花園的圍籬上。",""]],"l1-0141":[["及物動詞：購買","purchase","I saved enough money to buy a new bicycle.","我存夠了錢，可以買一輛新腳踏車。","purchase 較正式。"]],"l1-0142":[["介系詞：藉由（方法）","through","You can save water by taking shorter showers.","你可以縮短淋浴時間來節約用水。","by + 動名詞 表示方法。"],["介系詞：在……旁邊","beside / next to","Leave your muddy boots by the door, please.","請把沾滿泥巴的靴子放在門邊。",""]],"l1-0143":[["名詞：籠子","無直接同義詞","The bird's cage needs fresh water and a good cleaning.","鳥籠裡的水該換了，也需要好好清理一下。",""]],"l1-0144":[["名詞：蛋糕","無直接同義詞","She put seven candles on her son's birthday cake.","她在兒子的生日蛋糕上放了七根蠟燭。",""]],"l1-0145":[["及物動詞：呼喊；叫喚","summon","Mom called us inside when dinner was ready.","晚餐準備好時，媽媽叫我們進屋。","summon 較正式，常帶有權威或命令意味。"]],"l1-0146":[["名詞：駱駝","無直接同義詞","The camel knelt down so the rider could get off.","駱駝跪了下來，讓騎乘的人下去。",""]],"l1-0147":[["名詞：相機","無直接同義詞","I forgot my camera, so I used my phone instead.","我忘了帶相機，所以改用手機拍照。",""]],"l1-0148":[["名詞：營地","encampment","We set up camp beside a quiet mountain stream.","我們在一條寧靜的山溪旁搭建營地。","encampment 指臨時營地，較正式。"]],"l1-0149":[["助動詞：能；會","be able to","My younger sister can read a whole book by herself now.","我妹妹現在能自己讀完整本書了。","can + 原形動詞；be able to 須依主詞與時態變化。"],["名詞：罐子；罐裝食品","tin","We opened a can of beans for a quick lunch.","我們開了一罐豆子，簡單吃頓午餐。","tin 是常見英式用法；本義已列於原卡釋義。"]],"l1-0150":[["名詞：糖果","sweet / candy","The dentist asked him to eat less candy.","牙醫請他少吃一點糖果。","美式 candy 多為不可數；英式 sweet 是可數名詞。"]],"l1-0151":[["名詞：有帽簷的便帽","無直接同義詞","He wore a cap to keep the sun off his face.","他戴了頂帽子，避免陽光直曬臉部。","cap 不限棒球帽，也可指其他貼頭便帽。"]],"l1-0152":[["名詞：汽車","automobile","We left the car in a parking lot near the beach.","我們把車停在海灘附近的停車場。","automobile 較正式，常見於美式英語。"]],"l1-0153":[["名詞：紙牌","playing card","She picked a card and placed it on the table.","她挑了一張牌，放在桌上。",""]],"l1-0154":[["不及物動詞：關心；在意","be concerned","Our teacher really cares about how each student feels.","老師很關心每個學生的感受。","care about 與 be concerned about 可對應。"]],"l1-0155":[["形容詞：小心的","cautious","Be careful with that knife; the blade is very sharp.","用那把刀要小心；刀刃很鋒利。","cautious 側重避免危險。"]],"l1-0156":[["及物動詞：提；搬；攜帶","transport","Can you help me carry these bags upstairs?","你能幫我把這些袋子提上樓嗎？","transport 是較廣的搬運，未必用手。"]],"l1-0157":[["名詞：盒；套盒","無直接同義詞","She keeps her glasses in a hard case.","她把眼鏡放在硬殼眼鏡盒裡。",""],["名詞：案件","無直接同義詞","The police found new evidence in the missing child's case.","警方在失蹤兒童案件中找到了新證據。",""]],"l1-0158":[["名詞：貓","無直接同義詞","Our cat sleeps on the warm windowsill every afternoon.","我們家的貓每天下午都睡在溫暖的窗台上。",""]],"l1-0159":[["及物動詞：接住","grab","She caught the falling cup before it hit the floor.","杯子掉到地板前，她及時接住了。","catch 強調接住移動中的物體；grab 側重快速抓取。"]],"l1-0160":[["名詞：原因；成因","reason","The cause of the fire is still unknown.","火災的起因仍不明。","cause 指造成事件的原因；reason 也可指理由或動機。"]],"l1-0161":[["名詞：分（貨幣單位）","無直接同義詞","This postcard costs fifty cents at the museum shop.","這張明信片在博物館商店售價五十美分。",""]],"l1-0162":[["名詞：中心；中央","middle","Place the vase in the center of the table.","把花瓶放在桌子中央。","centre 為英式拼法。"]],"l1-0163":[["形容詞：確定的","sure / convinced","Are you certain that the train leaves at nine?","你確定火車九點出發嗎？","convinced 強調深信，未必有客觀證據。"]],"l1-0164":[["名詞：椅子","無直接同義詞","Please pull up a chair and join us for lunch.","請搬張椅子過來，和我們一起吃午餐。",""]],"l1-0165":[["名詞：機會","opportunity","This trip is a chance to practice my English.","這趟旅行是練習英語的機會。",""]],"l1-0166":[["名詞：圖表","graph","The chart shows how much rain fell each month.","這張圖表顯示每個月的降雨量。","graph 適用於以線、長條等表示數量的圖。"]],"l1-0167":[["及物動詞：追逐","pursue / run after","The dog chased a ball across the grass.","狗追著一顆球跑過草地。","pursue 較正式。"]],"l1-0168":[["及物動詞：檢查","inspect / examine","Please check your bag to make sure you have your keys.","請檢查你的袋子，確認鑰匙有帶著。","inspect、examine 通常指更仔細的檢查。"]],"l1-0169":[["名詞：小雞；雛鳥","無直接同義詞","A yellow chick followed its mother around the yard.","一隻黃色小雞跟著母雞在院子裡走。",""]],"l1-0170":[["名詞：雞","無直接同義詞","We feed the chickens before collecting their eggs.","我們先餵雞，再收雞蛋。","hen 是母雞，不能涵蓋所有 chicken。"]],"l1-0171":[["名詞：首長；主管","head / leader","The fire chief thanked everyone who helped during the storm.","消防隊長感謝每一位在暴風雨期間提供協助的人。",""]],"l1-0172":[["名詞：小孩","kid / youngster","Every child in the class received a new notebook.","班上每個孩子都收到了一本新筆記本。","kid 較口語；child 的複數為 children。"]],"l1-0173":[["名詞：聖誕節","Xmas","Our family decorates a small tree every Christmas.","我們家每年聖誕節都會布置一棵小樹。","Xmas 是 Christmas 的非正式縮寫。"]],"l1-0174":[["名詞：教堂","無直接同義詞","The old church has colorful windows and a tall tower.","那座老教堂有彩色窗戶和一座高塔。",""]],"l1-0175":[["名詞：城市","無直接同義詞","The city is quieter when most shops are closed.","大多數商店關門時，這座城市比較安靜。",""]],"l1-0176":[["名詞：班級","無直接同義詞","Our class is raising money for the school library.","我們班正在為學校圖書館募款。",""]],"l1-0177":[["形容詞：乾淨的","spotless","Use a clean cloth to dry the dishes.","用乾淨的布把碗盤擦乾。","spotless 表示毫無污點，程度比 clean 強。"]],"l1-0178":[["形容詞：清楚易懂的","plain / understandable","Her clear directions helped us find the hotel easily.","她清楚的指示讓我們輕鬆找到了旅館。",""]],"l1-0179":[["及物動詞：攀爬","scale / ascend","The children climbed the hill to see the sunset.","孩子們爬上山丘看日落。","scale 常指攀登較陡或較高的地方；ascend 較正式。"]],"l1-0180":[["名詞：時鐘","無直接同義詞","The kitchen clock stopped because its battery was dead.","廚房的時鐘停了，因為電池沒電了。",""]],"l1-0181":[["形容詞：靠近的","near","Our hotel is close to the main train station.","我們的旅館離主要火車站很近。","close to 可對應 near；改用 near 時不加 to。"],["及物動詞：關閉","shut","Please close the window before the rain comes in.","請關窗，免得雨水飄進來。",""]],"l1-0182":[["名詞：雲","無直接同義詞","A dark cloud covered the sun just before lunch.","午餐前，一片烏雲遮住了太陽。",""]],"l1-0183":[["名詞：海岸","seashore / coastline","We drove along the coast and stopped at a fishing village.","我們沿著海岸開車，在一個漁村停了下來。","coastline 特指海陸交界線；coast 可涵蓋沿海地區。"]],"l1-0184":[["名詞：大衣；外套","overcoat","Hang your wet coat by the door to dry.","把濕外套掛在門邊晾乾。","overcoat 通常指穿在其他衣服外面的厚長大衣。"]],"l1-0185":[["名詞：可可粉","cocoa powder","She added cocoa to the cake batter for a chocolate flavor.","她在蛋糕麵糊裡加了可可粉，增添巧克力風味。","cocoa 可指可可粉或可可飲品；本例指加入蛋糕麵糊的可可粉。"]],"l1-0186":[["名詞：咖啡","無直接同義詞","Would you like milk or sugar in your coffee?","你的咖啡要加牛奶或糖嗎？",""]],"l1-0187":[["名詞：可樂","無直接同義詞","He ordered a cola with his burger and fries.","他點了可樂，搭配漢堡和薯條。","Coke 是 Coca-Cola 的商標稱呼，不泛指所有品牌的 cola。"]],"l1-0188":[["形容詞：寒冷的","icy / freezing","My hands were cold after waiting outside for an hour.","在外面等了一小時後，我的手冷冰冰的。","icy、freezing 都比 cold 強烈，口語中可形容非常冷的手。"]],"l1-0189":[["名詞：顏色","hue / shade","Which color would you like for your bedroom walls?","你的臥室牆壁想用哪種顏色？","hue 較書面；shade 可指同色系中的深淺色調。"]],"l1-0190":[["不及物動詞：來","arrive","Can you come to my house after school?","放學後，你能來我家嗎？","come 帶有朝說話者或指定地點移動之意；arrive 強調抵達。"]],"l1-0191":[["形容詞：常見的；普通的","frequently seen","This common bird often visits gardens in our neighborhood.","這種常見的鳥經常飛到我們社區的花園裡。","本例 common 指經常見到；不必然表示全球分布廣。"]],"l1-0192":[["不及物動詞：繼續","go on / carry on","The rain continued all night and stopped at dawn.","雨下了一整夜，到黎明才停。",""]],"l1-0193":[["及物動詞：烹調","prepare","Dad cooked dinner while I set the table.","爸爸煮晚餐時，我擺好了餐桌。","prepare food 可包含不加熱的備餐；cook 通常涉及加熱。"]],"l1-0194":[["名詞：餅乾","biscuit","She baked a batch of cookies for her neighbors.","她烤了一批餅乾送給鄰居。","biscuit 是常見英式用字；cooky 是較少見的 cookie 變體。"]],"l1-0195":[["形容詞：酷的；很棒的（口語）","great / awesome","That's a cool jacket; where did you buy it?","那件外套很酷耶，你在哪裡買的？","本句取讚賞義；cool 也可表示涼爽。"]],"l1-0196":[["名詞：玉米","maize","We grilled corn and served it with a little butter.","我們烤了玉米，搭配少許奶油食用。","maize 用法較正式；美式 corn 通常指玉米。"]],"l1-0197":[["形容詞：正確的","right","Check the map to make sure this is the correct road.","確認一下地圖，確保這條路是對的。",""]],"l1-0198":[["名詞：費用；成本","expense / price","The cost of lunch is included in the ticket.","票價已包含午餐費用。",""],["不及物動詞：需花費；價值","無直接同義詞","The repairs cost more than we paid for the bicycle.","修理費比我們當初買腳踏車的價錢還高。","本例 cost 作不及物動詞，表示需花費多少；cost 也可作及物動詞，後接人或物表示使……花費……。"]],"l1-0199":[["及物動詞：數數；清點","tally","Count the plates before putting them on the table.","把盤子擺上桌前，先數一數。","tally 側重計算總數，較正式。"]],"l1-0200":[["名詞：國家","nation / state","We learned about food and music from another country.","我們認識了另一個國家的食物與音樂。","state 指主權國家時較正式，也可另指一國之州。"]],"l1-0201":[["名詞：路線；航向","route / path","The boat changed course to avoid the rocks.","船改變了航向，以避開岩石。","course 可強調行進方向，route 側重經過哪些地點。"]],"l1-0202":[["及物動詞：覆蓋","無直接同義詞","Cover the bowl with a plate to keep insects out.","用盤子蓋住碗，避免蟲子跑進去。",""]],"l1-0203":[["名詞：母牛","無直接同義詞","The farmer brought the cow into the barn before sunset.","農夫在日落前把母牛帶進畜舍。",""]],"l1-0204":[["名詞：牛仔","cowhand","The cowboy rode his horse beside the cattle.","牛仔騎著馬走在牛群旁邊。",""]],"l1-0205":[["名詞：烏鴉","無直接同義詞","A crow picked up a nut from the sidewalk.","一隻烏鴉從人行道上叼起了一顆堅果。",""]],"l1-0206":[["不及物動詞：哭泣","weep / sob","The little girl cried when she lost her favorite toy.","小女孩弄丟最喜歡的玩具時哭了。","weep 較書面；sob 指啜泣、抽噎。"]],"l1-0207":[["名詞：幼獸（如熊、獅等）","無直接同義詞","The bear cub stayed close to its mother.","小熊緊跟在母熊身邊。","cub 不適用於所有動物的幼獸。"]],"l1-0208":[["名詞：杯子","無直接同義詞","She warmed her hands around a cup of tea.","她雙手捧著一杯茶取暖。",""]],"l1-0209":[["及物動詞：切；剪","chop","Cut the carrots into small pieces for the soup.","把胡蘿蔔切成小塊來煮湯。","chop 指剁或切塊。"]],"l1-0210":[["形容詞：可愛的","adorable / sweet","The puppy looks cute with one ear folded down.","小狗一隻耳朵垂下來的樣子很可愛。","adorable 語氣較強。"]],"l1-0211":[["名詞：爸爸（親暱稱呼）","dad / daddy / papa","Dad helped me fix the wheel on my bicycle.","爸爸幫我修好了腳踏車的輪子。","daddy、papa、pa、pop 都是 father 的非正式稱呼，地區與家庭習慣不同。"]],"l1-0212":[["不及物動詞：跳舞","無直接同義詞","Everyone danced to the music at the wedding.","婚禮上，大家隨著音樂跳舞。",""]],"l1-0213":[["名詞：舞者","無直接同義詞","The dancer stretched her legs before stepping onto the stage.","舞者上台前先伸展了雙腿。",""]],"l1-0214":[["名詞：危險","risk / peril","The sign warned us of danger near the cliff.","告示牌提醒我們，懸崖附近很危險。","risk 強調發生壞事的可能；peril 較強烈且書面。"]],"l1-0215":[["形容詞：黑暗的","unlit","The hallway was dark because the lights were off.","走廊裡的燈沒開，所以一片漆黑。","unlit 指未照明，適合本句燈沒開的情境。"]],"l1-0216":[["名詞：日期","無直接同義詞","Write the date at the top of your letter.","在信的上方寫上日期。",""]],"l1-0217":[["名詞：女兒","無直接同義詞","Their daughter made them a card for their wedding anniversary.","他們的女兒做了一張卡片，祝賀他們的結婚週年紀念。",""]],"l1-0218":[["名詞：一天；日子","無直接同義詞","We spent the whole day exploring the old town.","我們花了一整天遊覽老城區。",""]],"l1-0219":[["形容詞：死去的；枯死的","lifeless","The gardener removed a dead tree from the yard.","園丁移除了院子裡的一棵枯樹。","deceased 只用於已故的人，不用於此處的枯樹。"]],"l1-0220":[["不及物動詞：處理（deal with）","handle / manage","The manager will deal with your complaint this afternoon.","經理今天下午會處理你的投訴。","deal with + 事情；handle、manage 直接接受詞。"]],"l1-0221":[["形容詞：親愛的；珍愛的","beloved / cherished","She keeps letters from a dear friend in this box.","她把一位摯友的信保存在這個盒子裡。",""]],"l1-0222":[["名詞：死亡","passing","His family planted a tree after his death.","他去世後，家人種了一棵樹。","passing 是較委婉的說法。"]],"l1-0223":[["名詞：十二月","無直接同義詞","The town puts up lights every December for the holidays.","鎮上每年十二月都會掛燈飾過節。","Dec. 是 December 的縮寫。"]],"l1-0224":[["及物動詞：決定","determine / settle","We need to decide which bus to take.","我們得決定要搭哪一班公車。","settle 常用 settle on；determine 較正式。"]],"l1-0225":[["形容詞：深的","無直接同義詞","The water is too deep for children to stand in.","這裡的水太深，孩子站不到底。",""]],"l1-0226":[["名詞：鹿","無直接同義詞","Two deer crossed the road in front of our car.","兩隻鹿從我們車前穿過馬路。","deer 單複數同形。"]],"l1-0227":[["名詞：書桌；辦公桌","無直接同義詞","Keep your desk tidy so you can find your homework.","保持書桌整潔，才能找得到作業。","desk 通常指讀書或工作的桌子。"]],"l1-0228":[["不及物動詞：去世","pass away","His grandfather died peacefully with the family beside him.","他的祖父在家人陪伴下安詳去世了。","pass away 是較委婉的說法。"]],"l1-0229":[["形容詞：不同的","dissimilar","The twins have different tastes in music and clothes.","這對雙胞胎對音樂和衣服的喜好不同。","dissimilar 較正式。"]],"l1-0230":[["形容詞：困難的","hard / challenging","This puzzle is difficult, but we can solve it together.","這個謎題很難，但我們可以一起解開。","challenging 常帶有值得挑戰的正面意味。"]],"l1-0231":[["及物動詞：挖","excavate","We dug a hole to plant the young tree.","我們挖了一個洞來種小樹。","excavate 較正式，常指工程或考古挖掘。"]],"l1-0232":[["名詞：晚餐","supper","Dinner will be ready when Dad gets home.","爸爸回到家時，晚餐就會準備好。","supper 常指晚間較簡單的一餐；dinner 也可指一天的主餐。"]],"l1-0233":[["及物動詞：指揮；引導","guide","A police officer directed traffic around the broken bus.","一名警察指揮車流繞過故障的公車。",""]],"l1-0234":[["形容詞：骯髒的","filthy / unclean","His shoes were dirty after walking through the muddy field.","走過泥濘的田地後，他的鞋子很髒。","filthy 表示非常髒。"]],"l1-0235":[["及物動詞：發現","find","We discovered a small cafe behind the busy market.","我們在熱鬧的市場後方發現了一間小咖啡館。","discover 常含初次發現或意外找到之意。"]],"l1-0236":[["名詞：盤；碟","plate","Put the sliced fruit on a clean dish.","把切好的水果放在乾淨的盤子上。","plate 通常是較平的盤子。"]],"l1-0237":[["及物動詞：做；進行","無直接同義詞","We did a simple experiment to test the water.","我們做了一個簡單的實驗來檢測水質。","perform、carry out 用於執行工作或實驗等較正式語境。"]],"l1-0238":[["名詞：醫生","physician / doc","The doctor listened carefully as I described my cough.","我描述咳嗽情況時，醫生仔細聽著。","doc 較口語；physician 較正式。"]],"l1-0239":[["名詞：狗","無直接同義詞","Our dog waits by the door when we come home.","我們回家時，狗會在門邊等我們。",""]],"l1-0240":[["名詞：娃娃","無直接同義詞","She made a tiny dress for her favorite doll.","她為最喜歡的娃娃做了一件小洋裝。",""]],"l1-0241":[["名詞：元（貨幣單位）","buck","The used book cost me just one dollar.","那本二手書只花了我一美元。","buck 是 dollar 的口語說法。"]],"l1-0242":[["名詞：門","無直接同義詞","Someone knocked on the door while we were eating.","我們吃飯時，有人敲門。",""]],"l1-0243":[["名詞：鴿子","無直接同義詞","A white dove landed on the roof of the church.","一隻白鴿落在教堂屋頂上。",""]],"l1-0244":[["副詞：向下","downward / downwards","Look down carefully before stepping off the bus.","下公車前，先小心看一下腳下。",""]],"l1-0245":[["副詞：到樓下；在樓下","無直接同義詞","I went downstairs when I heard the doorbell ring.","聽到門鈴響，我就下樓了。",""]],"l1-0246":[["名詞：一打；十二個","twelve","We bought a dozen eggs to bake the cakes.","我們買了一打雞蛋來烤蛋糕。","a dozen 可直接接複數名詞；a dozen of 通常接限定詞或代名詞片語，例如 a dozen of them。"]],"l1-0247":[["及物動詞：畫","sketch","She drew a picture of our house with colored pencils.","她用色鉛筆畫了一張我們家的圖。","sketch 通常指速寫或草圖。"]],"l1-0248":[["名詞：夢","無直接同義詞","I had a strange dream about flying over the ocean.","我做了一個奇怪的夢，夢見自己飛越海洋。",""]],"l1-0249":[["及物動詞：喝","sip","Drink some water after running in the hot sun.","在大太陽下跑步後，喝點水吧。","sip 指小口慢慢喝。"]],"l1-0250":[["及物動詞：駕駛","無直接同義詞","She drives a small car to work every day.","她每天開一輛小車去上班。",""]],"l1-0251":[["名詞：司機；駕駛人","無直接同義詞","The driver waited until everyone had found a seat.","司機一直等到每個人都找到了座位。","motorist 通常指汽車駕駛人，不適合直接替代本例搭載多位乘客的司機。"]],"l1-0252":[["形容詞：乾的","無直接同義詞","These towels are dry enough to put away now.","這些毛巾現在夠乾了，可以收起來。",""]],"l1-0253":[["名詞：鴨子","無直接同義詞","A duck swam under the bridge and disappeared from view.","一隻鴨子游到橋下，消失在視線中。",""]],"l1-0254":[["名詞：小鴨","無直接同義詞","The duckling hurried after its mother across the pond.","小鴨趕緊跟著母鴨游過池塘。",""]],"l1-0255":[["介系詞：在……期間","throughout","Please turn off your phone during the performance.","表演期間，請關閉手機。","throughout 強調整段時間；during 不一定涵蓋全程。"]],"l1-0256":[["限定詞：每個（個別看待）","every","Each student brought a different dish to the class party.","每位學生都帶了一道不同的菜來參加班級聚餐。","each 強調逐一個體；every 側重全體無例外。"]],"l1-0257":[["名詞：鷹；鵰","無直接同義詞","An eagle circled high above the mountain valley.","一隻鷹在山谷上空高高盤旋。",""]],"l1-0258":[["名詞：耳朵","無直接同義詞","She covered her ears when the fireworks began.","煙火開始施放時，她摀住了耳朵。",""]],"l1-0259":[["形容詞：提早的；早的","無直接同義詞","We caught an early train to avoid the morning crowds.","我們搭了一班較早的火車，避開早晨的人潮。",""]],"l1-0260":[["名詞：地球","the world","The satellite sends pictures of Earth back to scientists.","這顆衛星把地球的影像傳回給科學家。","Earth 作行星名稱時通常大寫。"]],"l1-0261":[["名詞：輕鬆；不費力","effortlessness","She carried the heavy box with surprising ease.","她出乎意料地輕鬆搬起了重箱子。","with ease 表示輕而易舉。"]],"l1-0262":[["名詞：東方","無直接同義詞","The sun rose in the east as we started hiking.","我們出發健行時，太陽從東方升起。",""]],"l1-0263":[["形容詞：容易的","simple / straightforward","The instructions are easy to follow, even for beginners.","這些說明很容易照著做，即使是初學者也沒問題。",""]],"l1-0264":[["及物動詞：吃","consume","We ate our sandwiches under a tree in the park.","我們在公園的一棵樹下吃了三明治。","consume 較正式，也可指飲用或消耗。"]],"l1-0265":[["名詞：邊緣","無直接同義詞","Don't leave your glass near the edge of the table.","別把玻璃杯放在桌緣附近。","rim 多指圓形物或容器的邊；border 多指區域的界線。"]],"l1-0266":[["名詞：蛋","無直接同義詞","Crack one egg into the bowl and beat it well.","打一顆蛋到碗裡，再充分打勻。",""]],"l1-0267":[["數詞：八","無直接同義詞","Eight children were waiting outside the library this morning.","今天早上有八個孩子在圖書館外等候。","數詞置於名詞前表示數量；原卡統列為 n.。"]],"l1-0268":[["數詞：十八","無直接同義詞","There are eighteen students in our evening English class.","我們晚間英語班有十八位學生。",""]],"l1-0269":[["數詞：八十","無直接同義詞","Grandma invited the whole family when she turned eighty.","奶奶滿八十歲時，邀請了全家人聚會。",""]],"l1-0270":[["限定詞：兩者中的任一個","無直接同義詞","You can use either door to enter the hall.","你可以從兩扇門中的任一扇進入大廳。",""],["副詞：也（用於否定句）","無直接同義詞","I don't like loud music, and my older sister doesn't either.","我不喜歡吵鬧的音樂，我姊姊也不喜歡。","否定句中的也用 either；too 通常用於肯定句。"]],"l1-0271":[["名詞：大象","無直接同義詞","The elephant sprayed water over its back with its trunk.","大象用鼻子把水噴到背上。",""]],"l1-0272":[["數詞：十一","無直接同義詞","Eleven players ran onto the field before the match.","比賽開始前，十一名球員跑進球場。",""]],"l1-0273":[["副詞：其他；另外","other / additional","What else should we pack for our camping trip?","露營還需要帶些什麼？","else 放在 what、someone 等字之後。"]],"l1-0274":[["名詞：結束；末尾","finish / conclusion","Everyone clapped at the end of the concert.","音樂會結束時，大家都鼓掌了。",""]],"l1-0275":[["名詞：英語","無直接同義詞","We spoke English with the visitors from overseas.","我們用英語和海外來訪的客人交談。",""]],"l1-0276":[["限定詞：足夠的","sufficient","Do we have enough chairs for everyone at the party?","我們有足夠的椅子讓派對上的每個人坐嗎？","enough 放名詞前；修飾形容詞或副詞時通常放其後。"]],"l1-0277":[["及物動詞：進入","go into / come into","Please knock before you enter the teacher's office.","進入老師辦公室前，請先敲門。","enter 表進入地點時直接接受詞，不加 into。"]],"l1-0278":[["形容詞：相等的","equally sized","Cut the sandwich into two equal parts for the children.","把三明治切成大小相等的兩份給孩子們。","equal 在此指大小相等，不表示形狀等各方面都相同。"]],"l1-0279":[["副詞：甚至","無直接同義詞","Even my little brother understood the teacher's simple explanation.","連我的小弟弟都聽懂了老師簡單的解釋。",""],["形容詞：偶數的","無直接同義詞","Choose an even number so we can form pairs.","選一個偶數，這樣我們才能分成兩人一組。",""]],"l1-0280":[["名詞：傍晚；晚上","無直接同義詞","We spent the evening playing cards with our grandparents.","我們整個晚上都和祖父母一起玩牌。",""]],"l1-0281":[["副詞：曾經（疑問句）","at any time","Have you ever seen snow falling outside your window?","你曾看過窗外飄雪嗎？","ever 在本句問是否曾有過某種經驗。"]],"l1-0282":[["限定詞：每個","each","Every room in this hotel has a small balcony.","這間旅館的每個房間都有一座小陽台。","every 後接單數可數名詞。"]],"l1-0283":[["名詞：考試","test / exam","The final examination covers everything we learned this term.","期末考涵蓋這學期學過的所有內容。","exam 是 examination 的常用簡稱。"]],"l1-0284":[["及物動詞：檢查；仔細查看","inspect / check","The doctor examined my ankle after I fell.","我跌倒後，醫生檢查了我的腳踝。",""]],"l1-0285":[["名詞：例子","instance / illustration","Could you give us an example of a healthy breakfast?","你能舉一個健康早餐的例子嗎？",""]],"l1-0286":[["介系詞：除了……之外（不包含）","apart from / excluding","Everyone except Ben arrived before the movie started.","除了班以外，大家都在電影開始前到了。","apart from 也可表示此外，須依語境判斷。"]],"l1-0287":[["名詞：眼睛","無直接同義詞","Her eyes hurt after reading in poor light.","在光線不足的地方閱讀後，她的眼睛很不舒服。",""]],"l1-0288":[["名詞：臉","無直接同義詞","He washed his face with cool water before breakfast.","早餐前，他用涼水洗了臉。",""]],"l1-0289":[["名詞：事實","truth","We should check the facts before sharing this story.","我們應該先核實事實，再分享這則消息。","fact 常指個別可查證資訊；truth 可指真相整體。"]],"l1-0290":[["名詞：工廠","plant","The factory makes bicycles that are sold around the world.","這間工廠製造銷往世界各地的腳踏車。","plant 在此指工廠，尤指工業設施。"]],"l1-0291":[["不及物動詞：落下","drop / tumble","Yellow leaves fell onto the path outside our house.","黃色落葉飄落在我們屋外的小路上。","tumble 常帶有翻滾或跌落之意。"]],"l1-0292":[["形容詞：不正確的；虛假的","untrue / incorrect","The story about the school closing turned out to be false.","學校要關閉的傳言後來證實是假的。",""]],"l1-0293":[["名詞：家庭；家人","無直接同義詞","My family eats dinner together whenever everyone is home.","只要大家都在家，我們全家就會一起吃晚餐。","household 指同住一戶的人，未必有親屬關係。"]],"l1-0294":[["名詞：扇子","無直接同義詞","She waved a paper fan to cool herself down.","她搧著紙扇，讓自己涼快些。",""]],"l1-0295":[["副詞：遠","a long way","We didn't walk far because my feet were hurting.","因為我的腳很痛，我們沒有走很遠。",""]],"l1-0296":[["名詞：農場","無直接同義詞","The farm sells fresh eggs and vegetables every Saturday.","這座農場每週六都販售新鮮雞蛋和蔬菜。",""]],"l1-0297":[["名詞：農夫","grower","The farmer checked the fields after the heavy rain.","大雨過後，農夫查看了田地的情況。","grower 指種植作物的人，未必涵蓋畜牧農民。"]],"l1-0298":[["副詞：快速地","quickly / rapidly","Don't run too fast on this slippery path.","在這條濕滑的小路上，別跑得太快。",""]],"l1-0299":[["形容詞：肥胖的","overweight / plump","The fat cat struggled to squeeze through the narrow gap.","那隻胖貓費力地想鑽過狹窄的縫隙。","形容人時 fat 常顯得冒犯；overweight 較中性，plump 指圓潤豐滿。"]],"l1-0300":[["名詞：父親","dad / papa","Her father taught her to ride a bike in the park.","她父親在公園教她騎腳踏車。","dad、papa 是較親暱的稱呼。"]],"l1-0301":[["名詞：恐懼","fright / terror","His fear of heights kept him away from the balcony.","他因為懼高而不敢靠近陽台。","terror 比 fear 強烈；fright 常指突然的驚嚇。"]],"l1-0302":[["名詞：二月","無直接同義詞","Our winter break ends in the middle of February.","我們的寒假在二月中旬結束。","Feb. 是 February 的縮寫。"]],"l1-0303":[["及物動詞：餵食","give food to","Please feed the cat before you leave for school.","去上學前，請先餵貓。",""]],"l1-0304":[["及物動詞：觸摸；摸摸看","touch","Feel this blanket; it's much softer than the old one.","摸摸這條毯子，它比舊的那條柔軟多了。","feel 側重透過觸摸感受質地。"],["及物動詞：感受到","sense / experience","I could feel the cold wind through my thin jacket.","我隔著薄外套仍能感受到冷風。",""]],"l1-0305":[["名詞：感覺；預感","sense / impression","I had a feeling that we had met before.","我有種感覺，我們以前見過面。",""]],"l1-0306":[["複數名詞：感情；情緒","emotions","She wrote about her feelings after moving to a new school.","轉到新學校後，她把自己的心情寫了下來。",""]],"l1-0307":[["限定詞：很少的","not many","Few shops were open when we arrived late at night.","我們深夜抵達時，還開著的店很少。","few 側重少；a few 表示有一些。"]],"l1-0308":[["數詞：十五","無直接同義詞","We walked for fifteen minutes before reaching the beach.","我們走了十五分鐘才到海灘。",""]],"l1-0309":[["數詞：五十","無直接同義詞","The bus can carry fifty passengers at a time.","這輛巴士一次可載五十名乘客。",""]],"l1-0310":[["不及物動詞：打架","brawl / tussle","The two boys fought over a toy in the playground.","那兩個男孩在遊樂場為了玩具打了起來。","brawl 常指吵鬧的打群架；tussle 常指扭打或拉扯。"]],"l1-0311":[["及物動詞：裝滿","fill up","Fill the jug with water before putting it in the fridge.","先把水壺裝滿水，再放進冰箱。",""]],"l1-0312":[["形容詞：最後的","last","The final bus leaves the station at eleven tonight.","今晚最後一班公車十一點離站。",""]],"l1-0313":[["及物動詞：找到","locate / discover","I found my missing glove under the kitchen table.","我在廚房桌子底下找到了不見的手套。","原卡譯尋找；find 強調找到，尋找的過程用 look for。"]],"l1-0314":[["形容詞：身體好的；無恙的","well / okay","She feels fine now and plans to return to school.","她現在身體沒事了，打算回去上學。",""],["名詞：罰款","penalty","He paid a fine for parking in front of the gate.","他因為把車停在大門前而繳了罰款。","penalty 可指各種處罰；本句為金錢罰款。"]],"l1-0315":[["名詞：手指","無直接同義詞","She wore a silver ring on her middle finger.","她的中指上戴著一枚銀戒指。",""]],"l1-0316":[["及物動詞：完成","complete","I want to finish this letter before dinner.","我想在晚餐前把這封信寫完。",""]],"l1-0317":[["名詞：火","無直接同義詞","We sat around the fire to keep warm.","我們圍坐在火邊取暖。",""],["及物動詞：解僱","dismiss / sack","The company fired him for repeatedly missing work.","公司因為他一再曠職而將他解僱。","sack 較口語，常見於英式英語。"],["不及物動詞：開槍；開火","shoot","The soldier fired into the air as a warning.","士兵朝空中開槍示警。",""]],"l1-0318":[["序數詞：第一的","initial","The first chapter introduces the family and their village.","第一章介紹了這家人及他們的村莊。","initial 側重最初階段。"]],"l1-0319":[["名詞：魚","無直接同義詞","We watched small fish swimming between the rocks.","我們看著小魚在岩石之間游動。",""]],"l1-0320":[["數詞：五","無直接同義詞","Five people offered to help clean the park.","有五個人主動提出要幫忙清理公園。",""]],"l1-0321":[["名詞：地板","無直接同義詞","Please wipe the wet floor before someone slips.","請把濕地板擦乾，免得有人滑倒。",""]],"l1-0322":[["名詞：花","bloom / blossom","A single flower stood in a vase on the desk.","書桌上的花瓶裡插著一朵花。","blossom 常指樹木或灌木上的花。"]],"l1-0323":[["名詞：蒼蠅","無直接同義詞","A fly kept landing on the edge of my plate.","一隻蒼蠅不斷停在我的盤緣上。",""],["不及物動詞：飛","soar","The birds flew south as the weather grew colder.","天氣轉冷時，鳥兒往南飛去。","soar 強調高飛或滑翔。"]],"l1-0324":[["名詞：霧","mist","Thick fog hid the hills from view this morning.","今天早上的濃霧遮住了山丘。","mist 通常比 fog 稀薄。"]],"l1-0325":[["及物動詞：跟隨","go after / trail","Follow the guide so you don't get lost in the cave.","跟著導遊走，才不會在洞穴裡迷路。","trail 可指落在後面跟著。"]],"l1-0326":[["名詞：食物","nourishment","We packed enough food for two days of hiking.","我們準備了足夠兩天健行吃的食物。","nourishment 側重維持身體所需的養分，較正式。"]],"l1-0327":[["名詞：腳","無直接同義詞","He hurt his left foot while playing basketball.","他打籃球時傷了左腳。","foot 的複數是 feet。"]],"l1-0328":[["介系詞：為了；供……使用","無直接同義詞","I bought these flowers for my mother's birthday.","我為媽媽的生日買了這些花。",""]],"l1-0329":[["名詞：力量","strength / power","The force of the wind pushed the door open.","風的力量把門推開了。",""]],"l1-0330":[["形容詞：外國的","from another country","The shop sells newspapers from several foreign countries.","這間店販售來自幾個外國的報紙。","overseas 本指海外；foreign 不限隔海的國家。"]],"l1-0331":[["名詞：森林","woods / woodland","A narrow path led us deep into the forest.","一條狹窄的小路把我們帶進森林深處。","woods、woodland 常指較小或較疏的林地。"]],"l1-0332":[["及物動詞：忘記","fail to remember","Don't forget to bring your ticket to the concert.","別忘了帶音樂會門票。",""]],"l1-0333":[["名詞：叉子","無直接同義詞","She used a fork to pick up the pasta.","她用叉子叉起了義大利麵。",""]],"l1-0334":[["數詞：四十","無直接同義詞","The journey takes forty minutes if the traffic is light.","如果交通順暢，這段路程需要四十分鐘。",""]],"l1-0335":[["數詞：四","無直接同義詞","We need four more chairs for the dinner guests.","我們還需要四張椅子給晚餐客人坐。",""]],"l1-0336":[["數詞：十四","無直接同義詞","Fourteen students signed up for the school chess club.","十四名學生報名了學校的西洋棋社。",""]],"l1-0337":[["形容詞：自由的；不受限制的","unrestricted","You are free to leave whenever you want.","你想離開時，隨時都可以走。","free to do 表示可自由做某事。"]],"l1-0338":[["形容詞：新鮮的","newly picked","These fresh strawberries came from a farm nearby.","這些新鮮草莓來自附近的農場。","newly picked 指剛採下，適用本句水果語境。"]],"l1-0339":[["名詞：星期五","無直接同義詞","We usually watch a movie at home on Friday nights.","我們通常在星期五晚上在家看電影。","Fri. 是 Friday 的縮寫。"]],"l1-0340":[["名詞：朋友","pal / buddy","My friend lent me a warm coat for the trip.","朋友借了我一件保暖外套去旅行。","pal、buddy 較口語。"]],"l1-0341":[["名詞：青蛙","無直接同義詞","A green frog jumped from the bank into the pond.","一隻綠色青蛙從岸邊跳進池塘。",""]],"l1-0342":[["介系詞：從；來自","無直接同義詞","The smell of fresh bread came from the kitchen.","新鮮麵包的香味從廚房傳來。",""]],"l1-0343":[["名詞：前面；前部","無直接同義詞","Please write your name on the front of the envelope.","請把你的名字寫在信封正面。",""]],"l1-0344":[["名詞：水果","無直接同義詞","We served fresh fruit after the main meal.","我們在主餐後端上新鮮水果。",""]],"l1-0345":[["形容詞：滿的","filled / packed","The train was full, so we had to stand.","火車客滿了，所以我們只能站著。","packed 表示擠得滿滿的。"]],"l1-0346":[["名詞：樂趣","enjoyment / amusement","We had fun making paper hats for the party.","我們開心地為派對製作紙帽。","have fun doing something。"]],"l1-0347":[["形容詞：好笑的","amusing / humorous","His funny story made everyone at the table laugh.","他好笑的故事讓同桌的人都笑了。",""]],"l1-0348":[["名詞：遊戲","無直接同義詞","Let's play a card game while we wait for dinner.","等晚餐時，我們來玩紙牌遊戲吧。",""]],"l1-0349":[["名詞：花園","無直接同義詞","She grows roses and herbs in her small garden.","她在小花園裡種玫瑰和香草。",""]],"l1-0350":[["名詞：汽油（美式）","gasoline / petrol","We stopped for gas before driving into the mountains.","開車進山之前，我們先停下來加油。","gasoline 常縮為 gas；英式用 petrol。"]],"l1-0351":[["形容詞：一般的；整體的","overall / broad","The teacher gave us a general idea of the project.","老師向我們概略介紹了這項專題。","general 在此表示大致輪廓，不涉及所有細節。"]],"l1-0352":[["及物動詞：得到","receive / obtain","I got a letter from my cousin this morning.","我今天早上收到表親寄來的一封信。","obtain 常含設法取得之意，較正式。"]],"l1-0353":[["名詞：鬼；幽靈","spirit / apparition","The children told a story about a ghost in the castle.","孩子們講了一個城堡鬧鬼的故事。","apparition 偏向顯現出的幽靈形影，較書面。"]],"l1-0354":[["名詞：禮物","present","She wrapped the gift in paper she had painted herself.","她用自己畫過的包裝紙把禮物包起來。",""]],"l1-0355":[["名詞：女孩","無直接同義詞","The girl in the red sweater is my cousin.","穿紅色毛衣的女孩是我表妹。",""]],"l1-0356":[["及物動詞：給","hand / pass","Could you give me the towel beside the sink?","你能把洗手台旁的毛巾拿給我嗎？","hand、pass 適用於此處把物品交給別人的動作。"]],"l1-0357":[["形容詞：高興的","pleased / happy","I'm glad you could join us for dinner tonight.","我很高興你今晚能和我們一起吃晚餐。",""]],"l1-0358":[["名詞：玻璃","無直接同義詞","The vase is made of thick green glass.","這只花瓶是用厚實的綠色玻璃製成的。",""]],"l1-0359":[["複數名詞：眼鏡","spectacles","I need my glasses to read the small print.","我需要戴眼鏡才能看清楚小字。","spectacles 較正式；一副眼鏡用 a pair of glasses。"]],"l1-0360":[["不及物動詞：去","head / travel","We go to the market early to buy fresh fish.","我們一早去市場買新鮮魚。","head to 強調朝某處前往。"]],"l1-0361":[["名詞：神；女神","deity","The painting shows a goddess standing beside the sea.","這幅畫描繪一位站在海邊的女神。","deity 不限定性別；goddess 指女性神祇。"]],"l1-0362":[["名詞：黃金","無直接同義詞","Her wedding ring is made of yellow gold.","她的婚戒是用黃金製成的。",""]],"l1-0363":[["形容詞：好的；有益的","beneficial / helpful","A short walk is good for you after sitting all day.","坐了一整天後，稍微散步對你有好處。","be good for 表示對……有益。"]],"l1-0364":[["名詞：道別","farewell","We said our goodbyes at the station before her train left.","她的火車開走前，我們在車站道別。","goodbye 也可作感嘆詞；bye、bye-bye 較口語。"]],"l1-0365":[["名詞：鵝","無直接同義詞","The goose spread its wings and hissed at the dog.","那隻鵝張開翅膀，朝狗發出嘶聲。","goose 的複數是 geese。"]],"l1-0366":[["形容詞：宏偉的","magnificent / splendid","A grand staircase leads to the hotel's dining room.","一道宏偉的樓梯通往旅館餐廳。",""]],"l1-0367":[["名詞：孫子女；外孫子女","無直接同義詞","Each grandchild brought a drawing for Grandma's birthday.","奶奶生日那天，每個孫子女都帶了一幅畫來。","grandchild 不區分父系、母系或性別。"]],"l1-0368":[["名詞：孫女；外孫女","無直接同義詞","His granddaughter visits every Sunday to play chess with him.","他的孫女每週日都來陪他下西洋棋。",""]],"l1-0369":[["名詞：祖父；外祖父","grandpa","My grandfather still enjoys fishing at the lake.","我的祖父仍喜歡到湖邊釣魚。","grandpa 較親暱；英文不以此詞區分爺爺和外公。"]],"l1-0370":[["名詞：祖母；外祖母","grandma","My grandmother taught me her favorite soup recipe.","我的祖母教我做她最喜歡的湯。","grandma 較親暱；英文不以此詞區分奶奶和外婆。"]],"l1-0371":[["名詞：孫子；外孫","無直接同義詞","She keeps a photo of her grandson on her desk.","她在書桌上放了一張孫子的照片。",""]],"l1-0372":[["名詞：草","無直接同義詞","The grass was wet with dew early this morning.","今天一早，草上沾滿了露水。",""]],"l1-0373":[["形容詞：灰色的","無直接同義詞","Gray clouds covered the sky before the storm.","暴風雨前，灰色雲層布滿天空。","gray 為美式常用拼法；grey 為英式常用拼法。"]],"l1-0374":[["形容詞：很棒的","excellent / wonderful","We had a great time at the beach yesterday.","我們昨天在海灘玩得很開心。",""]],"l1-0375":[["形容詞：綠色的","無直接同義詞","She painted the garden gate a soft green color.","她把花園大門漆成柔和的綠色。",""]],"l1-0376":[["名詞：地面","無直接同義詞","He spread a blanket on the ground for our picnic.","他把毯子鋪在地上，讓我們野餐用。",""]],"l1-0377":[["名詞：一群；小組","party","A group of tourists gathered outside the museum entrance.","一群遊客聚集在博物館入口外。","party 在此可指一同旅行或活動的一群人。"]],"l1-0378":[["不及物動詞：生長","develop","The seedlings grew quickly in the warm sunlight.","幼苗在溫暖的陽光下長得很快。","develop 側重發育或逐漸形成。"]],"l1-0379":[["及物動詞：猜測","make a guess","Can you guess how many buttons are in this jar?","你猜得出這個罐子裡有多少顆鈕扣嗎？","estimate 通常根據部分資訊作估計，比純猜測更有依據。"]],"l1-0380":[["名詞：客人；受邀者","visitor","Each guest received a small gift at the wedding.","婚禮上的每位賓客都收到了一份小禮物。","guest 側重被接待或受邀；visitor 泛指來訪者。"]],"l1-0381":[["名詞：導遊","tour guide","Our guide explained the history of the old bridge.","導遊向我們解說了那座老橋的歷史。",""]],"l1-0382":[["名詞：槍","firearm","The officer kept the gun locked in a secure cabinet.","警官把槍鎖在安全的櫃子裡。","firearm 是較正式的槍械總稱。"]],"l1-0383":[["名詞：頭髮","無直接同義詞","She tied her long hair back before cooking.","她煮飯前把長髮往後綁好。",""]],"l1-0384":[["名詞：理髮；剪髮","trim","I need a haircut before my sister's wedding.","姊姊結婚前，我需要去剪頭髮。","trim 通常只修剪少許。"]],"l1-0385":[["名詞：一半","無直接同義詞","I saved half of my sandwich for later.","我留了一半三明治，打算晚點吃。",""]],"l1-0386":[["名詞：火腿","無直接同義詞","He put ham and cheese between two slices of bread.","他把火腿和起司夾在兩片麵包中間。",""]],"l1-0387":[["名詞：手","無直接同義詞","Raise your hand if you know the answer.","知道答案的人請舉手。",""]],"l1-0388":[["不及物動詞：發生","occur / take place","The accident happened just outside the school gate.","事故就發生在校門外。","occur 較正式；take place 也常用於預定活動。"]],"l1-0389":[["形容詞：高興的","glad / pleased","She was happy to hear that her friend was coming.","聽到朋友要來，她很高興。",""]],"l1-0390":[["形容詞：堅硬的","solid / firm","The ground was too hard to dig with a small shovel.","地面太硬，用小鏟子挖不動。","firm 不像 hard 那麼強調難以穿透或壓變形。"],["副詞：努力地","diligently","She studied hard to prepare for the final exam.","她努力讀書，準備期末考。","hardly 表示幾乎不，不是 hard 的同義副詞。"]],"l1-0391":[["名詞：帽子","無直接同義詞","Wear a hat to protect your face from the sun.","戴上帽子，避免臉部受到日曬。",""]],"l1-0392":[["及物動詞：討厭","dislike / loathe","I hate waiting outside in the cold rain.","我討厭在冰冷的雨中待在外面等。","dislike 較弱；loathe 比 hate 更強烈。"]],"l1-0393":[["及物動詞：擁有","own / possess","They have a small house near the river.","他們在河邊附近有一間小房子。","possess 較正式。"]],"l1-0394":[["代名詞：他（主格）","無直接同義詞","My brother is tired because he worked late last night.","我哥哥很累，因為他昨晚工作到很晚。","原卡標 n.；he 實為人稱代名詞主格。"]],"l1-0395":[["名詞：頭","無直接同義詞","He bumped his head on the low doorway.","他撞到了低矮門框，碰傷了頭。",""]],"l1-0396":[["名詞：健康","well-being","Regular sleep and exercise are important for good health.","規律睡眠和運動對維持健康很重要。","well-being 也含整體生活與心理狀態。"]],"l1-0397":[["及物動詞：聽見；聽清楚","catch","I could barely hear her reply over the traffic.","車流聲中，我幾乎聽不清楚她的回答。","catch 在此指聽清楚話語。"]],"l1-0398":[["名詞：心臟","無直接同義詞","Her heart beat faster as she ran up the stairs.","她跑上樓梯時，心跳加快了。",""]],"l1-0399":[["及物動詞：加熱","warm / warm up","Heat the soup gently and stir it now and then.","用小火加熱湯，並不時攪拌。","warm 通常指加熱到溫暖，未必很燙。"]],"l1-0400":[["形容詞：重的","weighty","This suitcase is too heavy for me to lift alone.","這只行李箱太重，我一個人提不起來。","weighty 較書面。"]],"l1-0401":[["名詞：問候；招呼","greeting","His warm hello made me feel welcome at the party.","他熱情的招呼讓我覺得自己在派對上很受歡迎。","hello 更常作感嘆詞；本句配合原卡採名詞用法。"]],"l1-0402":[["及物動詞：幫助","assist / aid","Could you help me move this table away from the window?","你能幫我把這張桌子搬離窗邊嗎？","assist、aid 較正式。"]],"l1-0403":[["所有格限定詞：她的（her）","無直接同義詞","Her new shoes got wet on the way to school.","她的新鞋在上學途中弄濕了。","her 後接名詞；hers 可單獨使用。"],["所有格代名詞：她的（hers）","無直接同義詞","My coat is dark blue, but hers is bright red.","我的外套是深藍色的，她的是鮮紅色的。","hers 此處代替 her coat。"]],"l1-0404":[["副詞：這裡","in this place","Please wait here while I buy the train tickets.","我買火車票的時候，請在這裡等。",""]],"l1-0405":[["形容詞：高的","tall / lofty","A high wall surrounds the garden behind the house.","房子後面的花園四周有一道高牆。","tall 常用於高而窄的物體；lofty 較書面。"]],"l1-0406":[["名詞：山丘","無直接同義詞","We climbed a small hill to get a better view.","我們爬上一座小山丘，想看得更清楚。",""]],"l1-0407":[["代名詞：他（受格）","無直接同義詞","Ben forgot his umbrella, so I lent him mine.","班忘了帶傘，所以我把自己的借給他。",""]],"l1-0408":[["所有格代名詞：他的","無直接同義詞","This notebook is his, so please don't write in it.","這本筆記本是他的，請不要在上面寫字。","his 也可放名詞前，如 his notebook。"]],"l1-0409":[["名詞：歷史","the past","This museum tells the history of our fishing town.","這座博物館講述我們漁鎮的歷史。","the past 泛指過去；history 常包含對過往事件的記述。"]],"l1-0410":[["及物動詞：擊中；碰撞","strike","The ball hit the window but didn't break it.","球打中了窗戶，但沒有打破玻璃。",""]],"l1-0411":[["及物動詞：握住；拿著","grip / grasp","Hold the rope tightly while I pull you up.","我把你拉上來時，請緊握繩子。","grip、grasp 都強調握緊。"]],"l1-0412":[["名詞：洞；破洞","opening","There's a small hole in the heel of my sock.","我的襪子腳跟處有一個小洞。","opening 較中性，不一定表示破損。"]],"l1-0413":[["名詞：假日","day off","Tomorrow is a holiday, so we can sleep late.","明天放假，所以我們可以晚一點起床。","day off 指個人不用上班或上學的日子，未必是國定假日。"]],"l1-0414":[["名詞：家；住處","residence","Their new home has a small garden at the back.","他們的新家後面有一座小花園。","residence 較正式，不含 home 常有的情感。"]],"l1-0415":[["名詞：家庭作業","無直接同義詞","Our teacher gave us less homework before the holiday.","放假前，老師給我們的作業比較少。","homework 不可數，不加 s。"]],"l1-0416":[["及物動詞：希望","wish","I hope the weather stays dry for our picnic.","我希望野餐時天氣保持乾燥。","wish 側重希望某事發生；hope 後常接子句或不定詞。"]],"l1-0417":[["名詞：馬","無直接同義詞","The horse drank from a bucket after the long ride.","長途騎行後，馬喝了桶子裡的水。",""]],"l1-0418":[["形容詞：熱的；燙的","scalding","Be careful; the soup is still very hot.","小心，湯還很燙。","scalding 指液體非常燙，甚至可能燙傷人。"]],"l1-0419":[["名詞：小時","無直接同義詞","We waited an hour before the doctor could see us.","我們等了一小時，醫生才有空看診。","hour 的 h 不發音，前用 an。"]],"l1-0420":[["名詞：房子","dwelling","They bought a small house near their children's school.","他們在孩子的學校附近買了一間小房子。","dwelling 是正式的住屋稱呼。"]],"l1-0421":[["副詞：如何","in what way","Could you show me how to fold this paper bird?","你能示範這隻紙鳥怎麼摺嗎？",""]],"l1-0422":[["形容詞：巨大的","enormous / immense","A huge tree shaded almost the entire playground.","一棵大樹幾乎遮蔽了整座遊樂場。",""]],"l1-0423":[["名詞：人類；人","human being / person","The rescue dog searched the ruins for any humans still trapped.","搜救犬在瓦礫堆裡尋找仍受困的人。",""]],"l1-0424":[["數詞：一百","無直接同義詞","Nearly a hundred people came to the school concert.","近一百人來參加學校音樂會。",""]],"l1-0425":[["形容詞：飢餓的","starving / famished","We were hungry after walking around the city all morning.","在城裡走了一整個早上後，我們餓了。","starving、famished 在口語中表示非常餓。"]],"l1-0426":[["及物動詞：使受傷；弄傷","injure","She hurt her wrist when she fell off her bike.","她從腳踏車上摔下來時，傷了手腕。",""],["不及物動詞：疼痛","ache","My feet hurt after standing in line for two hours.","排隊站了兩小時後，我的腳很痛。","ache 常指持續的隱痛。"]],"l1-0427":[["名詞：丈夫","無直接同義詞","Her husband brought her lunch at the office.","她丈夫把午餐送到辦公室給她。","spouse 可指丈夫或妻子，範圍較廣。"]],"l1-0428":[["代名詞：我（主格）","無直接同義詞","I left my umbrella on the bus this morning.","我今天早上把傘留在公車上了。","原卡標 n.；I 實為人稱代名詞，永遠大寫。"]],"l1-0429":[["名詞：冰","無直接同義詞","The ice melted quickly in the warm afternoon sun.","冰在午後溫暖的陽光下很快就融化了。",""]],"l1-0430":[["名詞：主意；想法","thought / suggestion","Your idea of having a picnic sounds wonderful.","你提議去野餐，聽起來很棒。",""]],"l1-0431":[["連接詞：如果","provided that","If it rains tomorrow, we'll have the party indoors.","如果明天下雨，我們就改在室內辦派對。","provided that 更明確表示必須滿足的條件，較正式。"]],"l1-0432":[["形容詞：重要的","significant / essential","It's important to lock the door before leaving home.","離家前鎖門很重要。","essential 指不可或缺，語氣更強。"]],"l1-0433":[["介系詞：在……裡面","inside","I found some old photos in the bottom drawer.","我在最下面的抽屜裡找到一些舊照片。",""]],"l1-0434":[["名詞：英吋","無直接同義詞","The shelf is one inch too wide for this space.","這塊層板太寬，比這個空間多了一英吋。",""]],"l1-0435":[["名詞：內部","interior","The inside of the box was lined with soft cloth.","盒子內部襯著柔軟的布。",""]],"l1-0436":[["名詞：興趣","enthusiasm","She showed an interest in music at an early age.","她很小就表現出對音樂的興趣。","enthusiasm 強調熱忱，程度通常更強。"]],"l1-0437":[["介系詞：進入……裡面","無直接同義詞","The cat jumped into the empty cardboard box.","貓跳進了空紙箱裡。","into 強調移動進入；in 常表示已在裡面。"]],"l1-0438":[["名詞：鐵","無直接同義詞","The old gate was made of heavy iron.","那扇舊大門是用厚重的鐵製成的。",""]],"l1-0439":[["連綴動詞：是（第三人稱單數）","無直接同義詞","The woman by the door is our new teacher.","門邊那位女士是我們的新老師。","is 是 be 的現在式，搭配第三人稱單數。"]],"l1-0440":[["代名詞：它","無直接同義詞","I dropped the plate, but luckily it didn't break.","我把盤子掉到地上，但幸好它沒破。",""]],"l1-0441":[["所有格限定詞：它的","無直接同義詞","The dog wagged its tail when we came home.","我們回家時，狗搖起了尾巴。","its 表所有格；it's 是 it is 或 it has 的縮寫。"]],"l1-0442":[["名詞：果醬","preserve","She spread strawberry jam on a slice of toast.","她在一片吐司上抹了草莓果醬。","preserve 指以糖保存的水果製品，可含較大果塊。"],["名詞：堵塞；壅塞","congestion","A traffic jam made us late for the concert.","交通堵塞讓我們看音樂會遲到了。","congestion 是不可數名詞；a traffic jam 是可數表達。"]],"l1-0443":[["名詞：一月","無直接同義詞","The new swimming pool will open in early January.","新游泳池將於一月初開放。","Jan. 是 January 的縮寫。"]],"l1-0444":[["名詞：工作；職位","position / post","He found a job at a bakery near home.","他在住家附近的麵包店找到一份工作。","position、post 指職位，較正式。"]],"l1-0445":[["及物動詞：加入","become a member of","I joined the school choir because I enjoy singing.","我喜歡唱歌，所以加入了學校合唱團。",""]],"l1-0446":[["名詞：笑話","gag","His joke about the missing socks made us laugh.","他講的襪子失蹤笑話讓我們笑了。","gag 是口語的笑話或逗趣橋段。"]],"l1-0447":[["名詞：喜悅","delight / happiness","Her face lit up with joy when she saw the puppy.","她看見小狗時，臉上滿是喜悅。",""]],"l1-0448":[["名詞：果汁","無直接同義詞","We squeezed fresh oranges to make juice for breakfast.","我們榨了新鮮柳橙汁當早餐飲料。",""]],"l1-0449":[["名詞：七月","無直接同義詞","The summer art course starts in the first week of July.","暑期美術課在七月第一週開始。","Jul. 是 July 的縮寫。"]],"l1-0450":[["不及物動詞：跳","leap / hop","The children jumped over puddles on their way home.","孩子們回家途中跳過了水窪。","hop 常指單腳跳或小幅跳躍。"]],"l1-0451":[["名詞：六月","無直接同義詞","My sister finishes school in June and starts work in July.","我姊姊六月畢業，七月開始工作。","Jun. 是 June 的縮寫。"]],"l1-0452":[["形容詞：公正的","fair / impartial","Everyone trusted the judge to make a just decision.","大家都相信法官會作出公正的裁決。",""],["副詞：只是；僅僅","only / merely","I'm not angry; I'm just tired after the long trip.","我沒有生氣，只是長途旅行後很累。",""]],"l1-0453":[["及物動詞：保留；保存","retain / hold on to","You can keep the book until next Friday.","你可以把這本書留到下週五。",""]],"l1-0454":[["名詞：管理員；飼養員","caretaker","The keeper cleaned the animals' sleeping area every morning.","飼養員每天早上都清理動物睡覺的地方。","caretaker 側重照料；動物園飼養員常稱 zookeeper。"]],"l1-0455":[["名詞：鑰匙","無直接同義詞","I keep a spare key in my desk drawer.","我在書桌抽屜裡放了一把備用鑰匙。",""],["形容詞：關鍵的","crucial / essential","Clear communication is a key part of good teamwork.","清楚的溝通是良好團隊合作的關鍵部分。","原卡把關鍵的標為 adv.，實為形容詞。"]],"l1-0456":[["及物動詞：踢","boot","He kicked the ball gently toward his younger sister.","他把球輕輕踢向妹妹。","boot 在此指用腳踢，通常比 kick 更用力，較口語。"]],"l1-0457":[["名詞：小孩（口語）","child / youngster","The kids next door helped us wash the car.","隔壁的孩子幫我們洗車。",""]],"l1-0458":[["及物動詞：使死亡；殺死","destroy","The sudden frost killed most of the young plants.","突如其來的霜凍使大多數幼苗枯死了。","destroy 在此指把植物毀掉。"]],"l1-0459":[["形容詞：善良的；體貼的","caring / considerate","Our kind neighbor brought us soup when we were sick.","我們生病時，好心的鄰居送了湯來。",""],["名詞：種類","type / sort","What kind of music do you listen to while studying?","你讀書時會聽哪一種音樂？",""]],"l1-0460":[["名詞：國王","無直接同義詞","The king welcomed visitors in the palace's largest hall.","國王在宮殿最大的廳堂接待訪客。","monarch 可指國王或女王，範圍較廣。"]],"l1-0461":[["及物動詞：親吻","peck","She kissed her baby gently on the forehead.","她輕輕親了寶寶的額頭。","peck 指快速輕吻。"]],"l1-0462":[["名詞：廚房","無直接同義詞","The kitchen smelled of bread baking in the oven.","廚房裡飄著烤箱中麵包的香味。",""]],"l1-0463":[["名詞：風箏","無直接同義詞","We flew a kite on the beach after lunch.","午餐後，我們在海灘放風箏。",""]],"l1-0464":[["名詞：小貓","kitty","The kitten curled up in a basket of clean towels.","小貓蜷縮在一籃乾淨毛巾裡。","kitty 是貓的親暱稱呼，也可指成貓。"]],"l1-0465":[["名詞：膝蓋","無直接同義詞","He rested his hands on his knees after running.","跑步後，他把手撐在膝蓋上休息。",""]],"l1-0466":[["名詞：刀","無直接同義詞","Use a sharp knife to slice the bread neatly.","用鋒利的刀把麵包切成整齊的薄片。",""]],"l1-0467":[["及物動詞：知道","be aware of","Do you know where the nearest bus stop is?","你知道最近的公車站在哪裡嗎？","be aware of 後通常接名詞或疑問子句。"]],"l1-0468":[["及物動詞：缺少","be short of","The small apartment lacks space for a dining table.","這間小公寓沒有空間放餐桌。","lack 作動詞時直接接受詞；名詞用 a lack of。"]],"l1-0469":[["名詞：女士","woman","The lady at the front desk gave us a map.","櫃台的女士給了我們一張地圖。","lady 帶有禮貌稱呼色彩；woman 較中性。"]],"l1-0470":[["名詞：湖泊","無直接同義詞","Mountains were reflected in the still water of the lake.","山巒倒映在平靜的湖水中。",""]],"l1-0471":[["名詞：小羊；羔羊","無直接同義詞","A lamb followed its mother through the open gate.","一隻小羊跟著母羊穿過敞開的大門。",""]],"l1-0472":[["名詞：燈","light","I switched on the lamp beside my bed to read.","我打開床邊的燈來看書。","lamp 常指可移動或獨立的照明器具。"]],"l1-0473":[["名詞：陸地","dry land","After days at sea, we were glad to see land.","在海上待了幾天後，看見陸地讓我們很高興。",""],["不及物動詞：降落","touch down","The plane landed smoothly despite the heavy rain.","儘管下著大雨，飛機仍平穩降落。",""]],"l1-0474":[["形容詞：大的","big / sizable","They rented a large room for the family gathering.","他們租了一間大房間舉辦家庭聚會。","原卡譯寬的；large 指體積、面積或數量大，寬的通常是 wide。"]],"l1-0475":[["形容詞：最後的","final","She took the last seat on the crowded bus.","她坐上了擁擠公車裡最後一個空位。",""],["不及物動詞：持續","continue / go on","The concert lasted two hours, including a short break.","音樂會持續了兩小時，包括一段短暫休息。",""]],"l1-0476":[["形容詞：遲到的；晚的","delayed / overdue","The late bus made us miss the start of the movie.","公車誤點，讓我們錯過了電影開頭。","overdue 指超過預定時間仍未到。"]],"l1-0477":[["不及物動詞：笑","chuckle / giggle","We laughed when the puppy fell asleep in a shoe.","小狗睡在鞋子裡，我們看了都笑了。","chuckle 是輕笑；giggle 常指咯咯笑。"]],"l1-0478":[["名詞：法律","legislation","The new law aims to protect the river from pollution.","新法律旨在保護河川免受污染。","legislation 常指一套已制定的法律，通常不可數。"]],"l1-0479":[["及物動詞：放置","put / place","Lay the clean towels on the bed, please.","請把乾淨的毛巾放在床上。","lay 需接受詞；過去式與過去分詞均為 laid。"],["及物動詞：下蛋","無直接同義詞","One of our hens laid an egg this morning.","我們的一隻母雞今天早上下了一顆蛋。",""]],"l1-0480":[["形容詞：懶惰的","idle / indolent","He was too lazy to put his dirty clothes away.","他懶得把髒衣服收好。","indolent 較書面；idle 也可只指閒著。"]],"l1-0481":[["名詞：領先","advantage","Our team took the lead with a goal before halftime.","我們隊在中場前進了一球，取得領先。",""],["名詞：線索","clue","The police followed a new lead in the missing bicycle case.","警方循著新線索調查腳踏車失竊案。","lead 常指可繼續追查的線索。"]],"l1-0482":[["名詞：領導者","head / chief","Our group leader made sure everyone understood the task.","組長確認每個人都了解任務。",""]],"l1-0483":[["名詞：葉子","無直接同義詞","A single leaf floated on the surface of the pond.","一片葉子漂浮在池塘水面上。","leaf 的複數是 leaves。"]],"l1-0484":[["及物動詞：學習；學會","master","She learned to cook simple meals while living alone.","她獨居時學會了煮簡單的飯菜。","master 表示熟練掌握，比 learn 更進一步。"]],"l1-0485":[["限定詞：最少的","the smallest amount of","This route takes the least time during rush hour.","尖峰時間走這條路最省時。","least 常修飾不可數名詞，與可數名詞的 fewest 區別。"]],"l1-0486":[["及物動詞：離開","depart from","We left the house early to catch the first train.","我們很早就離家，去搭第一班火車。",""]],"l1-0487":[["形容詞：左邊的","left-hand","Take the left path when you reach the old tree.","走到那棵老樹時，走左邊的小路。",""]],"l1-0488":[["名詞：腿","無直接同義詞","My legs felt tired after climbing all those stairs.","爬完那麼多階梯，我的腿很疲累。",""]],"l1-0489":[["限定詞：較少的","not as much","This recipe uses less sugar than the one we tried yesterday.","這份食譜用的糖比我們昨天試做的少。","less 通常修飾不可數名詞。"]],"l1-0490":[["名詞：課；一堂課","class","My first swimming lesson starts at ten on Saturday.","我的第一堂游泳課週六十點開始。",""]],"l1-0491":[["及物動詞：允許","allow / permit","My parents let me choose the color of my room.","爸媽讓我選擇房間的顏色。","let + 受詞 + 原形動詞，不加 to。"]],"l1-0492":[["名詞：信","無直接同義詞","She wrote a letter to thank her former teacher.","她寫了一封信感謝以前的老師。",""],["名詞：字母","無直接同義詞","Write each letter of your name clearly on the form.","在表格上清楚寫出你名字的每個字母。",""]],"l1-0493":[["名詞：程度；級別","standard / grade","Choose a book that matches your reading level.","選一本符合你閱讀程度的書。","本例為程度義，不是建築樓層義。"]],"l1-0494":[["不及物動詞：躺","recline","I want to lie on the sofa for a few minutes.","我想在沙發上躺幾分鐘。","lie 躺：過去式 lay，過去分詞 lain；不同於 lay 放置。"]],"l1-0495":[["名詞：生命","無直接同義詞","The rescue team saved the child's life after the flood.","洪水過後，救援隊救了那個孩子一命。",""]],"l1-0496":[["及物動詞：抬起","raise / hoist","Help me lift this box onto the top shelf.","幫我把這個箱子抬到最上層架子。","hoist 常指用力或用設備吊起重物。"]],"l1-0497":[["名詞：光","illumination","Light from the window fell across the wooden table.","窗戶透進的光灑在木桌上。","illumination 較正式，常指照明。"],["形容詞：重量輕的","lightweight","This light jacket folds easily into my travel bag.","這件輕薄外套很容易摺好放進旅行袋。",""],["形容詞：淺色的","pale","We chose light blue curtains for the sunny bedroom.","我們替陽光充足的臥室選了淺藍色窗簾。",""]],"l1-0498":[["介系詞：像","similar to","The cloud above the hill looks like a sleeping cat.","山丘上方的雲看起來像一隻睡著的貓。",""],["及物動詞：喜歡","enjoy","I like reading short stories before going to bed.","我喜歡睡前讀短篇故事。",""]],"l1-0499":[["形容詞：可能的","probable","Rain is likely this afternoon, so bring an umbrella.","今天下午可能下雨，所以帶把傘吧。",""]],"l1-0500":[["名詞：百合","無直接同義詞","A white lily opened beside the garden path.","一朵白百合在花園小路旁綻放。",""]],"l1-0501":[["名詞：線條","stroke","Draw a straight line under the title with a ruler.","用尺在標題下方畫一條直線。","stroke 常指一筆畫出的線或筆畫。"]],"l1-0502":[["名詞：獅子","無直接同義詞","The lion rested in the shade during the afternoon heat.","午後炎熱時，獅子在陰涼處休息。",""]],"l1-0503":[["名詞：嘴唇","無直接同義詞","Her lips felt dry after walking in the cold wind.","在冷風中走路後，她的嘴唇很乾。",""]],"l1-0504":[["名詞：清單","無直接同義詞","Make a list of everything we need for the picnic.","把野餐需要的所有東西列成清單。",""]],"l1-0505":[["不及物動詞：聆聽","pay attention","Please listen to the instructions before starting the game.","開始遊戲前，請先聽清楚說明。","原卡標 vt.；listen 為不及物，接對象時需用 to。pay attention 也可含視覺注意。"]],"l1-0506":[["形容詞：小的","small / tiny","A little bird was hiding in the rose bush.","一隻小鳥躲在玫瑰叢裡。","tiny 表示非常小。"]],"l1-0507":[["形容詞：活的","living","The market sells live fish in large water tanks.","市場把活魚養在大水槽裡販售。","形容詞 live 讀 /laɪv/，動詞 live 讀 /lɪv/。"],["不及物動詞：居住；生活","reside","My grandparents live in a quiet village near the sea.","我的祖父母住在海邊一個安靜的村莊。","reside 較正式；本句為居住義。"]],"l1-0508":[["形容詞：長的；耗時的","lengthy","We packed sandwiches for the long journey to the coast.","我們為前往海岸的漫長旅程準備了三明治。","本句 long 指旅程時間長。"],["不及物動詞：渴望","yearn / ache","After months away, she longed to see her family again.","離家數月後，她渴望再次見到家人。","long to do；long for + 名詞。"]],"l1-0509":[["不及物動詞：看","gaze / glance","Look at the map before choosing which road to take.","決定走哪條路之前，先看看地圖。","look at；gaze 指凝視，glance 指瞥一眼。"]],"l1-0510":[["名詞片語：大量（a lot of）","a great deal of","There was a lot of traffic near the stadium.","體育場附近的車流量很大。","a lot of 可接可數或不可數名詞；a great deal of 接不可數名詞。"],["名詞：一塊地","plot","They plan to build a house on this empty lot.","他們打算在這塊空地上蓋房子。",""]],"l1-0511":[["形容詞：大聲的","noisy / deafening","A loud crash from the kitchen woke everyone up.","廚房傳來一聲巨響，把大家都吵醒了。","deafening 表示震耳欲聾。"]],"l1-0512":[["及物動詞：喜愛","adore / enjoy","She loves spending quiet evenings reading with her children.","她喜歡在安靜的夜晚和孩子們一起閱讀。","adore 強調非常喜愛。"],["名詞：愛","affection / devotion","His love for his family shows in the little things he does.","他對家人的愛流露在日常小事裡。","devotion 強調全心投入。"]],"l1-0513":[["形容詞：低的","無直接同義詞","The low ceiling makes the room feel much smaller.","低矮的天花板讓房間感覺小了許多。",""]],"l1-0514":[["形容詞：幸運的","fortunate","We were lucky to find the last available hotel room.","我們很幸運，找到了旅館最後一間空房。",""]],"l1-0515":[["名詞：午餐","luncheon","We had lunch at a small cafe near the museum.","我們在博物館附近的小咖啡館吃午餐。","luncheon 較正式，常指正式午餐聚會。"]],"l1-0516":[["名詞：機器","無直接同義詞","The washing machine stopped halfway through the cycle.","洗衣機洗到一半就停了。",""]],"l1-0517":[["形容詞：生氣的（美式）","angry / furious","Dad was mad when he found paint on the sofa.","爸爸發現沙發沾到油漆時很生氣。","furious 程度更強；mad 在英式英語也常表示瘋狂的。"]],"l1-0518":[["名詞：郵件","post","Could you collect our mail while we're away?","我們不在家時，你能幫忙收信嗎？","post 是常見英式用法。"]],"l1-0519":[["及物動詞：製作","create / produce","We made paper flowers to decorate the classroom.","我們做了紙花來布置教室。",""]],"l1-0520":[["名詞：男人","無直接同義詞","The man carrying a green suitcase is my uncle.","拿著綠色行李箱的那個男人是我叔叔。",""]],"l1-0521":[["限定詞：許多的","numerous / lots of","Many families visit the park on sunny weekends.","晴朗的週末，許多家庭會到公園遊玩。","many 接可數名詞複數；lots of 較口語。"]],"l1-0522":[["名詞：地圖","無直接同義詞","The map shows a walking path beside the river.","地圖上標示了一條河邊步道。",""]],"l1-0523":[["名詞：三月","無直接同義詞","The garden opens to visitors at the beginning of March.","花園在三月初開放遊客參觀。","Mar. 是 March 的縮寫。"]],"l1-0524":[["名詞：市場","marketplace","We bought fresh vegetables at the outdoor market.","我們在露天市場買了新鮮蔬菜。",""]],"l1-0525":[["及物動詞：與……結婚","wed","She married her longtime friend in a small garden ceremony.","她在一場小型花園婚禮上，與相識多年的朋友結婚。","marry someone 不加 with；wed 較正式。"]],"l1-0526":[["名詞：主人（尤指動物的主人）","owner","The dog waited patiently for its master to return.","狗耐心等待主人回來。","master 此用法帶有較傳統的語感。"],["及物動詞：精通；掌握","learn thoroughly","It took months to master the song's difficult piano part.","他花了幾個月，才熟練掌握那首歌困難的鋼琴段落。","learn thoroughly 是解說性近義短語，表示學到熟練。"]],"l1-0527":[["名詞：比賽","contest","The tennis match was postponed because of heavy rain.","網球比賽因為大雨而延期。","網球中 game 指一局，不能視為整場 match。"]],"l1-0528":[["名詞：事情；問題","issue / affair","We can discuss this matter after the children leave.","孩子們離開後，我們可以討論這件事。",""],["不及物動詞：重要；有關係","count / be important","Your opinion matters, so please tell us what you think.","你的意見很重要，請告訴我們你的想法。",""]],"l1-0529":[["名詞：五月","無直接同義詞","The school holds its sports day in May.","學校在五月舉辦運動會。",""]],"l1-0530":[["助動詞：可能","might / could","The store may close early because of the storm.","店家可能因為暴風雨而提早關門。","此處表可能性；may 也可表許可。"]],"l1-0531":[["副詞：也許","perhaps / possibly","Maybe we can take the train instead of driving.","也許我們可以搭火車，不用開車。",""]],"l1-0532":[["代名詞：我（受格）","無直接同義詞","Could you save a seat for me near the window?","你能幫我留一個靠窗的座位嗎？",""]],"l1-0533":[["及物動詞：表示；意味著","signify / indicate","A red flag means the beach is unsafe for swimming.","紅旗表示這片海灘不適合下水游泳。",""],["形容詞：吝嗇的","stingy / miserly","He's too mean to buy his guests a cup of tea.","他很吝嗇，連一杯茶都不肯請客人喝。","吝嗇義較常見於英式英語。"]],"l1-0534":[["名詞：肉；肉類","無直接同義詞","Keep the raw meat separate from the fresh vegetables.","把生肉和新鮮蔬菜分開放。",""]],"l1-0535":[["及物動詞：遇見","encounter / run into","I met an old classmate at the supermarket yesterday.","我昨天在超市遇到一位老同學。","run into 強調偶然遇見；encounter 較正式。"]],"l1-0536":[["形容詞：中間的","central","Put the heavy books on the middle shelf.","把重的書放在中間那層架子上。",""]],"l1-0537":[["名詞：英里","無直接同義詞","The nearest gas station is about three miles away.","最近的加油站大約在三英里外。",""]],"l1-0538":[["名詞：牛奶","無直接同義詞","Put the milk back in the fridge after breakfast.","早餐後，把牛奶放回冰箱。",""]],"l1-0539":[["名詞：心智；頭腦","intellect","Solving puzzles helps keep my grandfather's mind active.","解謎有助於讓祖父的頭腦保持靈活。","intellect 側重理解與推理能力。"]],"l1-0540":[["名詞：分鐘","無直接同義詞","The train leaves in ten minutes, so we should hurry.","火車十分鐘後出發，我們得快一點。",""]],"l1-0541":[["稱謂：小姐","無直接同義詞","Miss Lee asked the class to open their notebooks.","李小姐請全班打開筆記本。","Miss 傳統上用於未婚女性；稱呼應依本人習慣。"]],"l1-0542":[["及物動詞：想念","long for","I miss my family when I travel for work.","因工作出差時，我會想念家人。","long for 更強調渴望相聚。"]],"l1-0543":[["名詞：錯誤","error / slip","I made a mistake when copying your phone number.","我抄你的電話號碼時抄錯了。","slip 常指一時疏忽的小錯。"]],"l1-0544":[["名詞：片刻","instant / second","She paused for a moment before answering the question.","她停頓了片刻，才回答問題。",""]],"l1-0545":[["名詞：媽媽（親暱稱呼）","mom / mommy / momma","Mommy held my hand while we crossed the road.","我們過馬路時，媽媽牽著我的手。","mommy 常見於小孩的稱呼；mom、momma 為美式常見變體。"]],"l1-0546":[["名詞：星期一","無直接同義詞","The library opens an hour later on Monday mornings.","圖書館每週一早上晚一小時開館。","Mon. 是 Monday 的縮寫。"]],"l1-0547":[["名詞：錢","funds / cash","We saved enough money to repair the leaking roof.","我們存夠了錢，可以修理漏水的屋頂。","cash 專指現金；funds 常指可用資金。"]],"l1-0548":[["名詞：猴子","無直接同義詞","A monkey reached through the branches to pick some fruit.","一隻猴子伸手穿過枝葉，摘了些水果。",""]],"l1-0549":[["名詞：月份；一個月","無直接同義詞","She visits her grandmother twice a month after work.","她每個月會利用下班時間探望祖母兩次。",""]],"l1-0550":[["名詞：月亮","無直接同義詞","The full moon shone brightly over the quiet lake.","滿月明亮地照耀著寧靜的湖面。",""]],"l1-0551":[["限定詞：更多的","additional / extra","We need more plates before the guests arrive.","客人到之前，我們需要再多準備一些盤子。",""]],"l1-0552":[["名詞：早晨","無直接同義詞","The streets are quiet early in the morning.","一大早，街道很安靜。",""]],"l1-0553":[["限定詞：最多的","the greatest amount of","This window gets the most sunlight in the afternoon.","這扇窗戶下午得到的陽光最多。","the greatest amount of 是數量最多的解說性片語，接不可數名詞。"]],"l1-0554":[["名詞：母親","mom / mum","Her mother keeps a photo of each birthday celebration.","她母親保存著每次生日慶祝的照片。","mom 為美式常用；mum 為英式常用親暱稱呼。"]],"l1-0555":[["名詞：山","無直接同義詞","Snow covered the mountain long after spring began.","春天開始很久後，山上仍覆著雪。",""]],"l1-0556":[["名詞：老鼠","無直接同義詞","A mouse disappeared behind the cupboard when we entered.","我們進來時，一隻老鼠躲到了櫥櫃後面。","mouse 的複數是 mice；rat 通常較大，不是直接同義詞。"]],"l1-0557":[["名詞：嘴巴","無直接同義詞","Cover your mouth when you cough or sneeze.","咳嗽或打噴嚏時，請遮住嘴巴。",""]],"l1-0558":[["不及物動詞：移動（move）","stir / shift","The curtains moved gently in the evening breeze.","窗簾在晚風中輕輕擺動。","原卡動作是名詞釋義；move 本句為動詞。stir 強調輕微移動。"],["名詞：動作；移動（movement）","motion","A sudden movement in the bushes startled the dog.","灌木叢裡突然有動靜，嚇了狗一跳。","movement 是名詞，不能沿用原卡 vi. 標籤。"]],"l1-0559":[["名詞：電影","film / motion picture","We watched a movie about two brothers traveling across the country.","我們看了一部關於兩兄弟橫越全國旅行的電影。","cinema 常指電影藝術整體或電影院，通常不用 a cinema 指一部電影。"]],"l1-0560":[["稱謂：先生","mister","Mr. Chen will meet us at the hotel entrance.","陳先生會在旅館入口和我們見面。","Mr. 是 mister 的常用書面縮寫。"]],"l1-0561":[["稱謂：太太","無直接同義詞","Mrs. Brown brought fresh flowers for the school office.","布朗太太帶了鮮花來學校辦公室。","Mrs. 傳統上用於已婚女性的稱謂。"]],"l1-0562":[["稱謂：女士（不表婚姻狀態）","無直接同義詞","Ms. Lin will lead the meeting on Friday afternoon.","林女士將主持星期五下午的會議。","Ms. 不限婚姻狀況不明者；已婚、未婚女性皆可使用。"]],"l1-0563":[["限定詞：許多的","a lot of","There isn't much space for a desk in this room.","這個房間沒多少空間可以放書桌。","much 接不可數名詞，常用於否定或疑問句。"]],"l1-0564":[["名詞：泥巴","無直接同義詞","Our boots were covered in mud after the hike.","健行後，我們的靴子上全是泥巴。",""]],"l1-0565":[["名詞：馬克杯","無直接同義詞","He filled his favorite mug with hot coffee.","他把最喜歡的馬克杯裝滿熱咖啡。","mug 通常有把手，杯身較大。"]],"l1-0566":[["名詞：音樂","無直接同義詞","Soft music played in the background during dinner.","晚餐時，背景播放著輕柔的音樂。",""]],"l1-0567":[["助動詞：必須","have to / need to","You must wear a seat belt while the car is moving.","汽車行駛時，你必須繫上安全帶。",""]],"l1-0568":[["所有格限定詞：我的","無直接同義詞","My brother borrowed my camera for his school trip.","我弟弟借了我的相機去校外旅行。","my 後接名詞；可單獨使用的所有格是 mine。"]],"l1-0569":[["名詞：名字","無直接同義詞","Please print your name clearly on the visitor card.","請在訪客卡上用正楷清楚寫出你的名字。",""]],"l1-0570":[["名詞：國家","country / state","The festival brings together dancers from many different nations.","這個節慶匯集了許多不同國家的舞者。",""]],"l1-0571":[["名詞：大自然","the natural world","Spending time in nature helps her relax after work.","下班後親近大自然能幫助她放鬆。",""]],"l1-0572":[["介系詞：靠近","close to / by","There's a small bakery near the bus station.","公車站附近有一間小麵包店。",""]],"l1-0573":[["名詞：脖子","無直接同義詞","She wrapped a warm scarf around her neck.","她在脖子上圍了一條保暖圍巾。",""]],"l1-0574":[["及物動詞：需要","require","The plants need more water during the hot summer months.","這些植物在炎熱的夏季需要更多水。",""]],"l1-0575":[["副詞：從不","not ever","He never leaves home without checking the weather first.","他每次出門前都一定會先查看天氣。",""]],"l1-0576":[["形容詞：新的","brand-new","She bought new boots for her trip to the mountains.","她為這趟山區旅行買了新靴子。","brand-new 強調全新。"]],"l1-0577":[["名詞：新聞；消息","reports","We heard the news of the bridge closure on the radio.","我們從收音機聽到了橋梁封閉的消息。","news 不可數；reports 是複數名詞。"]],"l1-0578":[["名詞：報紙","paper","Grandpa reads the newspaper while drinking his morning coffee.","爺爺一邊喝早晨的咖啡，一邊看報紙。","paper 在此是 newspaper 的口語簡稱。"]],"l1-0579":[["形容詞：下一個的","following","The next train will arrive in twenty minutes.","下一班火車二十分鐘後抵達。",""]],"l1-0580":[["形容詞：令人愉快的","pleasant / lovely","We had a nice walk by the river after dinner.","晚餐後，我們愉快地在河邊散了步。",""]],"l1-0581":[["名詞：夜晚","nighttime","The road is harder to see at night.","晚上比較看不清楚路面。",""]],"l1-0582":[["數詞：九","無直接同義詞","Nine children joined the reading group this week.","這週有九個孩子加入了閱讀小組。",""]],"l1-0583":[["數詞：十九","無直接同義詞","She was nineteen when she moved away from home.","她十九歲時搬離了家。",""]],"l1-0584":[["數詞：九十","無直接同義詞","The film lasts ninety minutes without a break.","這部電影長九十分鐘，中間沒有休息。",""]],"l1-0585":[["應答詞：不；不是","nope","No, I haven't seen your keys since breakfast.","沒有，早餐後我就沒看過你的鑰匙。","nope 是非常口語的 no，正式場合通常用 no。"]],"l1-0586":[["名詞：噪音；聲響","racket / din","The noise from the road kept me awake.","道路傳來的噪音讓我睡不著。","racket、din 都表示吵雜且令人不快的聲音。"]],"l1-0587":[["形容詞：吵鬧的","loud / rowdy","The noisy crowd made it hard to hear the guide.","人群太吵，我們很難聽清楚導遊說話。","rowdy 還帶有喧鬧不守秩序的意思。"]],"l1-0588":[["名詞：中午","midday","The morning tour ends at noon near the main gate.","上午的導覽中午在大門附近結束。",""]],"l1-0589":[["連接詞：也不（neither ... nor）","無直接同義詞","Neither Anna nor her brother knows where the keys are.","安娜和她哥哥都不知道鑰匙在哪裡。",""]],"l1-0590":[["名詞：北方","無直接同義詞","Cold winds came from the north during the night.","夜裡，冷風吹自北方。",""]],"l1-0591":[["名詞：鼻子","無直接同義詞","The puppy pressed its wet nose against my hand.","小狗把濕鼻子貼在我的手上。",""]],"l1-0592":[["副詞：不","無直接同義詞","The store is not open on Sunday mornings.","這間店星期日早上不營業。",""]],"l1-0593":[["名詞：筆記","無直接同義詞","I took notes during the lesson to help me remember.","我上課時做了筆記，幫助自己記住內容。",""]],"l1-0594":[["代名詞：沒有東西；無事物","無直接同義詞","There was nothing in the box except a small key.","盒子裡除了一把小鑰匙，什麼都沒有。","原卡標 n.；本例 nothing 為不定代名詞。"]],"l1-0595":[["及物動詞：注意到","spot / observe","Did you notice the new sign outside the library?","你有注意到圖書館外的新告示牌嗎？",""]],"l1-0596":[["名詞：十一月","無直接同義詞","We start wearing warmer clothes when November arrives.","十一月一到，我們就開始穿保暖些的衣服。","Nov. 是 November 的縮寫。"]],"l1-0597":[["副詞：現在","at present / currently","This shop now sells flowers as well as books.","這間店現在除了賣書，也賣花。","本句 now 指目前情況。"]],"l1-0598":[["名詞：號碼；數字","無直接同義詞","Write your phone number below your name on the form.","在表格上的名字下方寫上電話號碼。",""]],"l1-0599":[["名詞：護理師","無直接同義詞","The nurse brought a blanket because I was cold.","因為我很冷，護理師拿了一條毯子來。",""]],"l1-0600":[["形容詞：可以的；無恙的","fine / all right","Is your knee okay after that fall on the steps?","你在階梯上摔了一跤，膝蓋還好嗎？","OK、O.K.、okay 為不同書寫形式。"]],"l1-0601":[["名詞：海洋","sea","We could see the ocean from our hotel balcony.","從旅館陽台可以看見海洋。","ocean 通常指較大的洋域；sea 也可泛指海。"]],"l1-0602":[["副詞：……點整","無直接同義詞","The bakery opens at six o'clock every morning.","麵包店每天早上六點整開門。","原卡標 n.；o'clock 為副詞，只用在整點後。"]],"l1-0603":[["名詞：十月","無直接同義詞","The village holds an apple festival every October.","村莊每年十月都舉辦蘋果節。","Oct. 是 October 的縮寫。"]],"l1-0604":[["介系詞：……的","無直接同義詞","The roof of the old house needs new tiles.","那棟老房子的屋頂需要換新瓦片。",""]],"l1-0605":[["介系詞：離開；從……下來","無直接同義詞","The cat jumped off the table when it heard us.","貓聽見我們的聲音，就從桌上跳了下來。",""]],"l1-0606":[["名詞：辦公室","無直接同義詞","She left the documents on her desk at the office.","她把文件留在辦公室的書桌上了。",""]],"l1-0607":[["名詞：官員；公務人員","official","The customs officer asked to see inside my suitcase.","海關人員要求查看我的行李箱內部。","officer 不只公務員，也可指警官、軍官或機構職員。"]],"l1-0608":[["副詞：常常","frequently / regularly","We often eat dinner outside when the weather is warm.","天氣溫暖時，我們常在戶外吃晚餐。",""]],"l1-0609":[["名詞：油","無直接同義詞","Heat a little oil in the pan before adding the onions.","先在鍋裡加熱一點油，再放入洋蔥。",""]],"l1-0610":[["形容詞：年老的","elderly / aged","The old man walks his dog in the park each morning.","那位老先生每天早上在公園遛狗。","elderly 語氣較正式；aged 通常也較書面。"]],"l1-0611":[["介系詞：在……上面","upon","Your notebook is on the table beside the window.","你的筆記本在窗邊的桌上。","upon 在空間義上較書面。"]],"l1-0612":[["副詞：一次","one time","I have only visited that museum once before.","我以前只去過那座博物館一次。",""]],"l1-0613":[["數詞：一","無直接同義詞","Only one seat was left on the morning bus.","早班公車上只剩一個座位。",""]],"l1-0614":[["形容詞：唯一的","sole","This bridge is the only way into the village.","這座橋是進入村莊的唯一通道。",""]],"l1-0615":[["形容詞：開著的","unclosed","The open window let a cool breeze into the room.","敞開的窗戶讓涼風進了房間。","unclosed 較少見；日常通常直接用 open。"]],"l1-0616":[["連接詞：或者","無直接同義詞","Would you prefer tea or coffee with your cake?","吃蛋糕時，你想配茶還是咖啡？",""]],"l1-0617":[["名詞：柳橙","無直接同義詞","She peeled an orange and shared it with her brother.","她剝了一顆柳橙，和弟弟分著吃。",""]],"l1-0618":[["名詞：順序","sequence","Put the photos in order from oldest to newest.","把照片依照從舊到新的順序排好。",""]],"l1-0619":[["限定詞：其他的","remaining","Two students stayed behind while the other students went outside.","兩名學生留下來，其他學生則到外面去。","remaining 在本句指其餘成員，不必然表示留在現場。"]],"l1-0620":[["所有格限定詞：我們的（our）","無直接同義詞","Our garden gets plenty of sunlight in the morning.","我們的花園早上有充足的陽光。","our 後接名詞；ours 可單獨使用。"],["所有格代名詞：我們的（ours）","無直接同義詞","Their house has a garage, but ours doesn't.","他們的房子有車庫，我們的沒有。","ours 在此代替 our house。"]],"l1-0621":[["介系詞：從……出去","out of","The children ran out the door when the bus arrived.","公車到達時，孩子們跑出了門。","out the door 常見於美式英語；out of the door 也可。"]],"l1-0622":[["名詞：外部；外側","exterior","The outside of the box was wet from the rain.","盒子外面被雨淋濕了。",""]],"l1-0623":[["介系詞：在……上方","above","A small plane flew over the village this morning.","今天早上，一架小飛機飛過村莊上空。",""],["形容詞：結束的","finished / ended","The concert was over by the time we arrived.","我們抵達時，音樂會已經結束了。",""]],"l1-0624":[["形容詞：自己的","personal","Each student needs their own notebook for the course.","每位學生上這門課都需要自己的筆記本。","own 強調屬於本人；personal 未必能表示同樣的對比。"],["及物動詞：擁有","have / possess","Her family owns a small bakery near the station.","她家在車站附近擁有一間小麵包店。",""]],"l1-0625":[["名詞：頁","無直接同義詞","Turn to the next page to see the map.","翻到下一頁，就能看到地圖。",""]],"l1-0626":[["及物動詞：油漆；上色","coat","We painted the old fence white last weekend.","上週末，我們把舊圍籬漆成白色。","coat 常用 coat something with paint，句型不同。"]],"l1-0627":[["名詞：一對；一雙","無直接同義詞","I bought a pair of warm gloves for winter.","我買了一雙保暖手套，準備冬天戴。",""]],"l1-0628":[["複數名詞：褲子","trousers","These pants are too long, so I need to shorten them.","這條褲子太長，我需要把它改短。","美式 pants 為褲子；英式 pants 也可指內褲。"]],"l1-0629":[["名詞：紙","無直接同義詞","Use both sides of the paper to avoid waste.","使用紙張的兩面，避免浪費。",""]],"l1-0630":[["名詞：父母；家長","無直接同義詞","A parent must sign the form before the school trip.","校外旅行前，必須由一位家長在表格上簽名。","parent 單數指父親或母親之一；parents 是複數。"]],"l1-0631":[["名詞：公園","無直接同義詞","The park has a pond and a path for bicycles.","公園裡有池塘，也有自行車道。",""],["及物動詞：停放車輛","無直接同義詞","Please park your car behind the building, near the gate.","請把車停在大樓後方、靠近大門的地方。",""]],"l1-0632":[["名詞：部分","portion / section","The hardest part of the hike was the final climb.","這趟健行最困難的部分是最後那段爬坡。",""]],"l1-0633":[["名詞：派對；聚會","celebration / gathering","We threw a small party for Grandma's birthday.","我們為奶奶的生日辦了一場小派對。","gathering 未必是慶祝活動。"]],"l1-0634":[["及物動詞：經過","go past","We passed the library on our way to the station.","我們去車站途中經過了圖書館。",""]],"l1-0635":[["介系詞：經過；越過","beyond","Walk past the bank and turn left at the next corner.","走過銀行後，在下一個轉角左轉。","beyond 側重超過某位置；past 可表示經過其旁邊。"],["名詞：過去","former times","These old photos remind us of the village's past.","這些老照片讓我們想起村莊的往昔。",""]],"l1-0636":[["及物動詞：支付","give / hand over","She paid the driver the exact fare for the trip.","她付給司機剛好的車資。","give、hand over 只在交付金錢語境下近義，不必然表示支付。"],["名詞：薪水（pay）","wages / salary","The job offers good pay but requires weekend work.","這份工作薪水不錯，但週末需要上班。",""],["名詞：付款（payment）","remittance","Your first payment is due at the end of the month.","你的第一筆款項應於月底繳付。","payment 是名詞；remittance 特指匯出的款項，較正式。"]],"l1-0637":[["名詞：筆；鋼筆或原子筆","無直接同義詞","May I borrow your pen to sign this form?","我可以借你的筆簽這份表格嗎？",""]],"l1-0638":[["名詞：鉛筆","無直接同義詞","Use a pencil so you can erase any mistakes.","用鉛筆寫，這樣寫錯就可以擦掉。",""]],"l1-0639":[["複數名詞：人們","persons / individuals","Several people were waiting outside the doctor's office.","有幾個人在診間外等候。","persons、individuals 較正式。"]],"l1-0640":[["副詞：也許","maybe / possibly","Perhaps we should ask the driver for directions.","也許我們應該向司機問路。",""]],"l1-0641":[["名詞：人","individual / human being","Each person in the group chose a different dessert.","小組裡的每個人都選了不同的甜點。",""]],"l1-0642":[["名詞：寵物","companion animal","Our first pet was a rabbit with soft gray fur.","我們養的第一隻寵物是一隻灰毛柔軟的兔子。","companion animal 是較正式的伴侶動物稱呼。"]],"l1-0643":[["名詞：鋼琴","無直接同義詞","She practiced the piano for an hour before dinner.","晚餐前，她練了一小時鋼琴。",""]],"l1-0644":[["名詞：圖像；圖畫","image / illustration","The book has a picture of each bird beside its name.","書上每種鳥的名字旁都有一幅圖。",""]],"l1-0645":[["名詞：派","無直接同義詞","The apple pie was still warm when we served it.","蘋果派端上桌時還是溫的。",""]],"l1-0646":[["名詞：一塊；一片","slice / portion","Would you like a small piece of chocolate cake?","你想吃一小塊巧克力蛋糕嗎？","slice 強調切下的片；portion 表一份。"]],"l1-0647":[["名詞：豬","無直接同義詞","The pigs rolled in the mud behind the barn.","豬在畜舍後方的泥巴裡打滾。",""]],"l1-0648":[["名詞：地方","spot / location","We found a quiet place to sit beside the river.","我們在河邊找到一個安靜的地方坐下。",""]],"l1-0649":[["名詞：計畫","scheme / proposal","Our plan is to visit the museum before lunch.","我們的計畫是午餐前去參觀博物館。","scheme 也可能帶負面算計意味；proposal 是尚待考慮的提案。"]],"l1-0650":[["名詞：植物","無直接同義詞","Move the plant closer to the window for more sunlight.","把植物移近窗戶，讓它多曬點太陽。",""],["及物動詞：栽種","put in","We planted three young trees along the garden fence.","我們沿著花園圍籬種了三棵小樹。","put in 在園藝語境可表示栽種，平常含義較廣。"],["名詞：工廠","factory","The new plant will make parts for electric bicycles.","新工廠將製造電動自行車零件。",""]],"l1-0651":[["不及物動詞：玩耍","無直接同義詞","The children played outside until their mother called them in.","孩子們在外面玩，直到媽媽叫他們進屋。",""]],"l1-0652":[["名詞：球員；參賽者","無直接同義詞","Each player shook hands with the opposing team after the match.","比賽後，每位球員都與對手隊員握手。",""]],"l1-0653":[["名詞：遊樂場；操場","play area","The children lined up beside the playground slide.","孩子們在遊樂場的溜滑梯旁排隊。","playground 常指兒童玩耍場地，不只學校運動操場。"]],"l1-0654":[["及物動詞：使高興；使滿意","delight / satisfy","The birthday surprise pleased Grandma more than any expensive gift.","這個生日驚喜比任何昂貴禮物都更讓奶奶開心。",""]],"l1-0655":[["名詞：口袋","無直接同義詞","Check your coat pocket for the missing bus ticket.","看看你的外套口袋裡有沒有不見的公車票。",""]],"l1-0656":[["名詞：詩（總稱）","verse","She enjoys reading poetry aloud on quiet evenings.","她喜歡在安靜的夜晚朗讀詩。","poetry 不可數；一首詩用 a poem。"]],"l1-0657":[["不及物動詞：指向","indicate / direct","He pointed toward the hill where the old castle stood.","他指向那座老城堡所在的山丘。","gesture 泛指做手勢，point 專指指向某處。"],["名詞：尖端","tip","The point of my pencil broke during the test.","考試時，我的鉛筆尖斷了。",""]],"l1-0658":[["集合名詞：警方","the police force","The police asked witnesses to describe the missing car.","警方請目擊者描述失蹤車輛的外觀。","police 通常搭配複數動詞，如 the police are。"]],"l1-0659":[["名詞：警察","police officer / cop","A policeman stopped traffic to help the children cross safely.","一名警察攔下車流，幫孩子們安全過馬路。","policeman 指男性；police officer、cop 不限性別，cop 較口語。"]],"l1-0660":[["名詞：池塘","無直接同義詞","Ducks gathered around the edge of the small pond.","鴨子聚集在小池塘邊。",""]],"l1-0661":[["名詞：水池；游泳池","swimming pool","The hotel pool closes at eight in the evening.","旅館的游泳池晚上八點關閉。","本例特指供游泳的 pool。"]],"l1-0662":[["形容詞：貧窮的","needy / impoverished","The charity provides warm meals for poor families.","這個慈善機構為貧困家庭提供熱食。","impoverished 較正式。"]],"l1-0663":[["名詞：爆米花","無直接同義詞","We shared a large bowl of popcorn during the movie.","看電影時，我們分著吃了一大碗爆米花。",""]],"l1-0664":[["名詞：位置","location / spot","The map shows the exact position of the campsite.","地圖標出了營地的確切位置。",""]],"l1-0665":[["形容詞：可能的；可行的","feasible","Is it possible to reach the station on foot?","有辦法步行到車站嗎？","feasible 側重實際可行，不涵蓋所有可能性用法。"]],"l1-0666":[["名詞：力量","strength / force","The power of the waves damaged the wooden pier.","海浪的力量損壞了木造碼頭。",""]],"l1-0667":[["及物動詞：練習","rehearse","We practiced the song several times before the concert.","音樂會前，我們把那首歌練了好幾次。","英式動詞常拼 practise；rehearse 用於排練表演。"]],"l1-0668":[["及物動詞：準備","get ready","She prepared lunch while the children set the table.","孩子們擺餐桌時，她準備午餐。","get something ready 與 prepare something 可對應，語序不同。"]],"l1-0669":[["形容詞：漂亮的","lovely / attractive","She wore a pretty dress with small yellow flowers.","她穿了一件有黃色小花的漂亮洋裝。",""],["副詞：相當（口語）","quite / rather","The walk was pretty tiring, so we stopped for water.","這段路走起來頗累，所以我們停下來喝水。","pretty 通常表相當，不必然達到原卡非常的強度。"]],"l1-0670":[["名詞：價格","cost","The price of the ticket includes a boat ride.","票價包含一次搭船遊覽。",""]],"l1-0671":[["及物動詞：列印；印刷","無直接同義詞","Please print two copies of the map for our trip.","請為我們的旅行印兩份地圖。",""]],"l1-0672":[["名詞：問題；困難","difficulty / issue","A problem with the engine delayed our bus.","引擎出了問題，讓我們的公車誤點了。",""]],"l1-0673":[["及物動詞：證明","demonstrate / establish","The photos prove that the road was already damaged.","照片證明那條路原本就已損壞。",""]],"l1-0674":[["形容詞：公共的；供大眾使用的","communal","The public library lends books to anyone with a library card.","公共圖書館把書借給任何持有借書證的人。","communal 強調社群共用，範圍通常較小。"]],"l1-0675":[["及物動詞：拉","tug / drag","Pull the rope gently to ring the bell.","輕拉繩子，讓鈴響起。","tug 表短促用力拉；drag 常指沿表面拖動。"]],"l1-0676":[["形容詞：紫色的","無直接同義詞","Purple flowers grow along the path to the house.","通往房子的路旁長著紫色花朵。",""]],"l1-0677":[["名詞：目的","aim / goal","The purpose of this meeting is to plan the school trip.","這場會議的目的是規畫校外旅行。",""]],"l1-0678":[["及物動詞：推","shove","We pushed the broken car to the side of the road.","我們把故障的車推到路邊。","shove 通常比 push 更用力或粗魯。"]],"l1-0679":[["及物動詞：放置","place / set","Put your wet umbrella in the stand by the door.","把濕傘放在門邊的傘架裡。",""]],"l1-0680":[["名詞：女王","無直接同義詞","The queen waved to the crowd from the palace balcony.","女王在宮殿陽台上向群眾揮手。","本例為女性君主；queen 也可指王后。"]],"l1-0681":[["名詞：問題；詢問","query","Do you have a question about tomorrow's homework?","你對明天的作業有問題想問嗎？","query 較正式；不把需解決的 problem 當成直接同義。"]],"l1-0682":[["形容詞：迅速的","fast / rapid","His quick reply helped us finish the booking on time.","他迅速回覆，幫我們及時完成預訂。",""]],"l1-0683":[["形容詞：安靜的","silent / peaceful","The house was quiet after the children fell asleep.","孩子們睡著後，屋子裡很安靜。","silent 指無聲；quiet 可只是聲音很小。"]],"l1-0684":[["副詞：相當","rather / fairly","The room is quite small, but it gets plenty of light.","房間頗小，但採光充足。","quite 的程度依語境與英美用法而異；此句為相當。"]],"l1-0685":[["名詞：競速比賽","無直接同義詞","She won the race by crossing the line a second earlier.","她早了一秒越過終點線，贏得比賽。","contest 泛指比賽，不能完整表達 race 的競速含義。"],["名詞：種族","無直接同義詞","The club welcomes people of every race and background.","這個俱樂部歡迎所有種族和背景的人。","race 不等於 nationality（國籍）。"]],"l1-0686":[["名詞：收音機","無直接同義詞","Dad turned on the radio to hear the weather forecast.","爸爸打開收音機，聽天氣預報。",""]],"l1-0687":[["名詞：鐵路","railway","The railroad runs along the coast beside the ocean.","這條鐵路沿著海岸延伸。","railroad 為美式常用；railway 為英式常用。"]],"l1-0688":[["名詞：雨","rainfall","Heavy rain filled the streets with deep puddles.","大雨讓街上積了一灘灘深水。","rainfall 常指某地一段時間的降雨或降雨量。"]],"l1-0689":[["名詞：彩虹","無直接同義詞","The children stopped jumping in puddles to admire the rainbow.","孩子們不再跳水窪，停下來欣賞彩虹。",""]],"l1-0690":[["及物動詞：舉起；抬高","lift / elevate","Raise your hand when you want to ask a question.","想提問時，請舉手。","raise 需接受詞；rise 是自行上升。"]],"l1-0691":[["名詞：大鼠","無直接同義詞","A rat ran behind the bins outside the restaurant.","一隻大老鼠跑到了餐廳外的垃圾桶後面。","rat 通常比 mouse 大，兩詞不直接互換。"]],"l1-0692":[["及物動詞：抵達","arrive at / get to","We reached the campsite just before the sun went down.","我們在太陽下山前不久抵達營地。","reach 地點時直接接受詞；arrive 需 at 或 in。"],["不及物動詞：伸手","stretch","She reached for the book on the highest shelf.","她伸手去拿最高層架子上的書。","reach for + 想拿到的東西。"]],"l1-0693":[["及物動詞：閱讀","無直接同義詞","Please read the instructions before opening the paint can.","打開油漆罐前，請先閱讀說明。",""]],"l1-0694":[["形容詞：準備好的","prepared / set","Our bags are ready, so we can leave now.","行李都準備好了，我們現在可以出發。",""]],"l1-0695":[["形容詞：真的；真實的","genuine / actual","The flowers looked real, but they were made of silk.","這些花看起來像真的，卻是絲綢做的。",""]],"l1-0696":[["名詞：理由","explanation","She gave us a clear reason for changing the plan.","她清楚說明了更改計畫的理由。",""]],"l1-0697":[["及物動詞：收到","get","We received a postcard from our friends in Canada.","我們收到了加拿大朋友寄來的明信片。","get 較口語。"]],"l1-0698":[["形容詞：紅色的","無直接同義詞","The red scarf stood out against her black coat.","紅圍巾在她的黑色外套襯托下格外顯眼。",""]],"l1-0699":[["及物動詞：記得；想起","recall / recollect","I remember the first time we visited this beach.","我記得我們第一次來這片海灘的情景。",""]],"l1-0700":[["名詞：報告","account","Her report describes how the students reduced food waste.","她的報告描述學生如何減少食物浪費。","account 在此指事情經過的敘述。"]],"l1-0701":[["不及物動詞：休息","relax / take a break","Let's rest in the shade before continuing our walk.","我們先在陰涼處休息，再繼續走吧。",""]],"l1-0702":[["不及物動詞：返回","come back / go back","The fishing boats returned to the harbor before the storm.","暴風雨前，漁船都回到港口了。",""]],"l1-0703":[["名詞：米；飯","無直接同義詞","We served the vegetables over a bowl of hot rice.","我們把蔬菜盛在一碗熱飯上。","本例為煮熟的米飯；rice 也指生米。"]],"l1-0704":[["形容詞：有錢的","wealthy / well-off","A rich couple donated books to every school in town.","一對富有的夫妻捐書給鎮上每所學校。","well-off 常指經濟寬裕，未必非常富有。"]],"l1-0705":[["及物動詞：騎乘","無直接同義詞","She rides her bike to the library every weekend.","她每週末都騎腳踏車去圖書館。",""]],"l1-0706":[["形容詞：右邊的","right-hand","The right door leads to the stairs and the garden.","右邊那扇門通往樓梯和花園。",""]],"l1-0707":[["不及物動詞：發出鐘鈴聲","chime","The church bells rang as the wedding guests arrived.","婚禮賓客抵達時，教堂鐘聲響起。","chime 強調悅耳的鐘鈴聲。"],["及物動詞：打電話給（英式）","call / phone","I'll ring you when I arrive at the station.","我到車站時會打電話給你。",""],["名詞：戒指","band","She took off her ring before washing the dishes.","她洗碗前先取下戒指。","band 常指沒有突出寶石的環形戒指。"]],"l1-0708":[["不及物動詞：上升","go up / ascend","The river began to rise after three days of rain.","下了三天雨之後，河水開始上漲。","ascend 較正式；rise 的過去式為 rose。"]],"l1-0709":[["名詞：河流","無直接同義詞","The river flows through the center of the town.","這條河流經鎮中心。",""]],"l1-0710":[["名詞：道路","無直接同義詞","The road to the village is narrow and winding.","通往村莊的道路狹窄又彎曲。",""]],"l1-0711":[["名詞：機器人","無直接同義詞","A robot moves the heavy boxes across the factory floor.","一台機器人在工廠地板上搬運重箱子。",""]],"l1-0712":[["名詞：岩石；石塊","stone","We sat on a flat rock beside the stream.","我們坐在溪邊的一塊平坦岩石上。","stone 常指較小的石塊；兩者依大小與語境有重疊。"]],"l1-0713":[["不及物動詞：滾動","無直接同義詞","The orange rolled off the table onto the floor.","柳橙從桌上滾落到地板。",""]],"l1-0714":[["名詞：屋頂","無直接同義詞","Rain dripped through a small hole in the roof.","雨水從屋頂的小洞滴了下來。",""]],"l1-0715":[["名詞：房間","chamber","The smallest room in the house is now a study.","屋子裡最小的房間現在用作書房。","chamber 較古典或正式。"]],"l1-0716":[["名詞：公雞","cock","The rooster crowed loudly before the sun came up.","太陽升起前，公雞就大聲啼叫。","rooster 是常見美式稱呼。"]],"l1-0717":[["名詞：根","無直接同義詞","The tree's roots spread beneath the garden path.","樹根延伸到了花園小路底下。",""]],"l1-0718":[["名詞：繩子","cord","Tie the boat to the dock with this rope.","用這條繩子把船繫在碼頭上。","cord 通常比 rope 細。"]],"l1-0719":[["名詞：玫瑰","無直接同義詞","He placed a red rose beside her breakfast plate.","他在她的早餐盤旁放了一朵紅玫瑰。",""]],"l1-0720":[["形容詞：圓的","circular","We sat around a round table in the kitchen.","我們圍坐在廚房裡的一張圓桌旁。",""]],"l1-0721":[["名詞：一排","line","A row of tall trees stands beside the road.","路旁矗立著一排高樹。",""],["及物動詞：划（船）","無直接同義詞","We rowed the small boat back to the shore.","我們把小船划回了岸邊。","row 用槳架上的 oars；paddle 的划槳方式不同。"]],"l1-0722":[["及物動詞：揉；按摩","massage","He rubbed his sore shoulder after carrying the box.","搬完箱子後，他揉了揉痠痛的肩膀。","本句為揉壓身體部位以舒緩痠痛。"]],"l1-0723":[["名詞：橡膠","無直接同義詞","The boots have thick rubber soles for wet paths.","這雙靴子有厚橡膠鞋底，適合走濕滑步道。",""]],"l1-0724":[["名詞：規則","regulation","One rule of the game is that everyone takes turns.","這個遊戲的一項規則是每個人都要輪流。","regulation 較正式，常指組織或官方規定。"]],"l1-0725":[["不及物動詞：跑","jog / sprint","We ran to the bus stop when we saw the bus.","看到公車時，我們跑向公車站。","jog 是慢跑；sprint 是全速短跑。"]],"l1-0726":[["形容詞：難過的","unhappy / sorrowful","He felt sad when his best friend moved away.","最好的朋友搬走時，他很難過。",""]],"l1-0727":[["形容詞：安全的","secure","Keep your passport in a safe place during the trip.","旅行時，把護照放在安全的地方。",""],["名詞：保險櫃","strongbox","The manager locked the cash in the office safe.","經理把現金鎖進辦公室的保險櫃。","strongbox 常指堅固且可上鎖的箱子。"]],"l1-0728":[["不及物動詞：航行","無直接同義詞","The boat sailed across the lake in the morning breeze.","船乘著晨風駛過湖面。",""]],"l1-0729":[["名詞：出售","selling","The sale of the old house took several months.","出售那棟老房子花了好幾個月。","selling 是動名詞，改寫時需調整後續介系詞。"]],"l1-0730":[["名詞：鹽","無直接同義詞","Taste the soup before you add any more salt.","再加鹽之前，先嚐嚐湯的味道。",""]],"l1-0731":[["形容詞：相同的","identical","Both sisters chose the same color for their jackets.","兩姊妹都為外套選了相同的顏色。",""]],"l1-0732":[["名詞：沙","無直接同義詞","Sand got into my shoes while we crossed the beach.","我們走過沙灘時，沙子跑進了我的鞋裡。",""]],"l1-0733":[["名詞：星期六","無直接同義詞","The farmers' market opens early every Saturday morning.","農夫市集每週六早上很早就開始營業。","Sat. 是 Saturday 的縮寫。"]],"l1-0734":[["及物動詞：拯救","rescue","The lifeguard saved a child who had fallen into the pool.","救生員救起了一個掉進泳池的孩子。",""],["及物動詞：儲存；存下","put aside / set aside","She saves part of her pay for a new computer.","她把部分薪水存起來，準備買新電腦。",""]],"l1-0735":[["名詞：鋸子","無直接同義詞","Dad used a saw to cut the wooden shelf.","爸爸用鋸子裁切木層板。",""]],"l1-0736":[["及物動詞：說","state / remark","She said that the meeting would start after lunch.","她說會議會在午餐後開始。","state 較正式；remark 常指提出評論。"]],"l1-0737":[["及物動詞：使害怕","frighten / alarm","The sudden thunder scared the children in the tent.","突然響起的雷聲嚇到了帳篷裡的孩子。",""]],"l1-0738":[["名詞：場景；一幕","無直接同義詞","The final scene shows the family together in their garden.","最後一幕呈現全家人在花園團聚的畫面。",""]],"l1-0739":[["名詞：學校","無直接同義詞","Our school has a new library and a small garden.","我們學校有一座新圖書館和一個小花園。",""]],"l1-0740":[["名詞：海","ocean","The sea was calm when the fishing boats left.","漁船出發時，海面很平靜。",""]],"l1-0741":[["名詞：季節","無直接同義詞","Autumn is my favorite season for walking in the hills.","秋天是我最喜歡到山丘散步的季節。",""]],"l1-0742":[["名詞：座位","無直接同義詞","She offered her seat to an elderly passenger.","她把座位讓給了一位年長的乘客。",""]],"l1-0743":[["序數詞：第二的","無直接同義詞","Our hotel room is on the second floor.","我們的旅館房間在二樓。",""],["名詞：秒","無直接同義詞","The light stayed green for only a few seconds.","綠燈只亮了幾秒鐘。",""]],"l1-0744":[["及物動詞：看見","spot / notice","We could see the island from the top of the hill.","我們從山丘頂上看得見那座島。","spot、notice 較強調注意到，而 see 可只表示視覺上看得見。"]],"l1-0745":[["名詞：種子","無直接同義詞","Plant the seeds in moist soil near a sunny window.","把種子種在向陽窗邊的濕潤土壤裡。",""]],"l1-0746":[["連綴動詞：似乎","appear","The new student seems nervous about speaking in class.","新學生似乎對在課堂上發言感到緊張。",""]],"l1-0747":[["名詞：蹺蹺板","teeter-totter","The two children took turns pushing the seesaw upward.","兩個孩子輪流把蹺蹺板往上推。","teeter-totter 是美式用字。"]],"l1-0748":[["名詞：自己；自我","無直接同義詞","After a good night's sleep, she felt like her old self.","睡了一夜好覺後，她覺得自己恢復了平常的狀態。","one's old self 指一個人平常的狀態。"]],"l1-0749":[["形容詞：自私的","self-centered / inconsiderate","It was selfish of him to take all the cake.","他把蛋糕全部拿走，實在很自私。","inconsiderate 側重不替別人著想。"]],"l1-0750":[["及物動詞：賣","vend","The shop sells fresh bread and homemade jam.","這間店販售新鮮麵包和自製果醬。","vend 較正式且不如 sell 常用。"]],"l1-0751":[["及物動詞：寄送","mail / dispatch","Please send the package to my office address.","請把包裹寄到我的辦公室地址。","dispatch 較正式；mail 特指經郵政寄送。"]],"l1-0752":[["名詞：感覺","feeling","A sense of calm returned when the storm finally passed.","暴風雨終於過去後，平靜的感覺又回來了。",""]],"l1-0753":[["名詞：句子","無直接同義詞","Write one sentence to describe the picture on the page.","寫一句話，描述頁面上的圖片。",""]],"l1-0754":[["名詞：九月","無直接同義詞","The evening classes begin in the first week of September.","晚間課程在九月第一週開始。","Sept. 是 September 的縮寫。"]],"l1-0755":[["及物動詞：為……服務；接待","attend to / wait on","The waiter served the guests with a friendly smile.","服務生面帶親切笑容接待客人。","wait on 常用於餐飲服務。"]],"l1-0756":[["名詞：服務","assistance","The friendly service makes this cafe a pleasant place to visit.","親切的服務讓這間咖啡館成為令人愉快的去處。","assistance 強調協助；service 可涵蓋整體接待品質。"]],"l1-0757":[["及物動詞：訂定；設立","establish","The teacher set clear rules for using the classroom computers.","老師為使用教室電腦訂下明確規則。",""],["名詞：一套；一組","無直接同義詞","She gave me a set of colored pencils for my birthday.","她送我一盒彩色鉛筆當生日禮物。",""]],"l1-0758":[["數詞：七","無直接同義詞","Seven ducks swam together across the quiet pond.","七隻鴨子一起游過寧靜的池塘。",""]],"l1-0759":[["數詞：十七","無直接同義詞","Seventeen people signed up for the weekend painting class.","十七個人報名了週末繪畫課。",""]],"l1-0760":[["數詞：七十","無直接同義詞","The dining room can seat seventy guests at once.","餐廳可同時容納七十位客人入座。",""]],"l1-0761":[["限定詞：幾個的","a few","We stopped at several small shops along the way.","我們沿途在幾間小店停留。","several 通常比 a few 稍多，但沒有固定數目。"]],"l1-0762":[["及物動詞：搖動","jiggle","Shake the bottle gently before pouring the juice.","倒果汁前，先輕輕搖一搖瓶子。","jiggle 常指小幅、快速地搖動。"]],"l1-0763":[["助動詞：將（較正式）","will","We shall return before the last bus leaves.","我們會在末班公車離站前回來。","shall 搭配 I、we 表未來較正式；日常多用 will。"]],"l1-0764":[["名詞：形狀","form / outline","The cookie has the shape of a small star.","這塊餅乾是小星星的形狀。","outline 專指外部輪廓。"]],"l1-0765":[["名詞：鯊魚","無直接同義詞","A shark swam slowly past the aquarium's glass window.","一隻鯊魚緩緩游過水族館的玻璃觀景窗。",""]],"l1-0766":[["形容詞：鋒利的","keen","The sharp knife cut through the thick rope easily.","鋒利的刀輕易切斷了粗繩。","keen 形容刀刃鋒利較書面。"]],"l1-0767":[["代名詞：她（主格）","無直接同義詞","My sister smiled when she opened her birthday gift.","我妹妹打開生日禮物時笑了。",""]],"l1-0768":[["名詞：綿羊","無直接同義詞","The sheep gathered near the gate at feeding time.","餵食時間一到，綿羊就聚在門邊。","sheep 單複數同形。"]],"l1-0769":[["名詞：一張（紙等）","無直接同義詞","Take a fresh sheet of paper for your drawing.","拿一張新紙來畫圖。",""]],"l1-0770":[["不及物動詞：發光；照耀","glow / beam","The sun shone through the leaves above our picnic blanket.","陽光穿過樹葉，照在我們的野餐毯上。","glow 側重持續柔和發光。"]],"l1-0771":[["名詞：大船","vessel","The ship carried passengers and cars to the island.","那艘船載著乘客和汽車前往島上。","vessel 是較正式的船舶稱呼。"]],"l1-0772":[["名詞：襯衫","無直接同義詞","He ironed his shirt before leaving for the interview.","出門面試前，他把襯衫燙平了。",""]],"l1-0773":[["名詞：鞋子","無直接同義詞","Take off your shoes before stepping onto the clean carpet.","踏上乾淨地毯前，請先脫鞋。",""]],"l1-0774":[["名詞：商店","store","The shop on the corner sells bread and milk.","轉角那間商店賣麵包和牛奶。","本卡 shop、store 為商店義的常見英美對應。"]],"l1-0775":[["不及物動詞：購物","無直接同義詞","We shopped for winter clothes before the cold weather arrived.","寒冷天氣到來前，我們去選購冬衣。","shop for 指挑選想買的物品，不保證已經買到。"]],"l1-0776":[["名詞：岸邊；海濱","seashore / coast","We watched the boats from the rocky shore.","我們站在岩石遍布的岸邊看船。","shore 也可指湖岸；本句取海岸義。"]],"l1-0777":[["形容詞：短的；簡短的","brief","The teacher gave a short talk before the concert began.","音樂會開始前，老師做了簡短的致詞。",""]],"l1-0778":[["及物動詞過去式：射出","fired","The archer shot an arrow at the distant target.","射箭者朝遠處的靶射了一箭。","shot 是 shoot 的過去式與過去分詞，不是原形動詞。"]],"l1-0779":[["名詞：肩膀","無直接同義詞","She carried a heavy bag over her left shoulder.","她左肩背著一個重袋子。",""]],"l1-0780":[["不及物動詞：大叫；呼喊","yell / call out","He shouted for help when he saw the fallen cyclist.","他看到摔倒的自行車騎士時，大聲呼救。",""]],"l1-0781":[["及物動詞：展示；給……看","display","Show me the photo you took at the beach.","給我看看你在海灘拍的照片。","show me something；display something to me，句型不同。"],["名詞：表演；演出","performance","The school show included songs, dances, and a short play.","學校演出包含歌曲、舞蹈和一齣短劇。",""]],"l1-0782":[["及物動詞：關上","close","Shut the gate so the dog can't run out.","把大門關上，免得狗跑出去。",""]],"l1-0783":[["形容詞：害羞的","timid / bashful","The shy child hid behind her father at first.","那個害羞的孩子起初躲在爸爸身後。","timid 也可指膽怯；bashful 側重怕羞。"]],"l1-0784":[["形容詞：生病的","ill / unwell","He stayed home from school because he was sick.","他因為生病，留在家裡沒去上學。",""]],"l1-0785":[["名詞：一側；邊","無直接同義詞","The bus stopped on the other side of the road.","公車停在馬路的另一邊。",""]],"l1-0786":[["名詞：視力","eyesight / vision","Grandpa's sight has improved since he got new glasses.","爺爺配了新眼鏡後，看東西清楚多了。","本例取視力義；不是表示視野範圍的 field of vision。"]],"l1-0787":[["形容詞：愚蠢的；傻的","foolish / absurd","It was silly to leave the window open during the storm.","暴風雨時還把窗戶開著，實在很傻。",""]],"l1-0788":[["名詞：銀","無直接同義詞","The small spoon is made of solid silver.","這支小湯匙是實心銀製的。",""]],"l1-0789":[["形容詞：簡單的","easy / straightforward","This simple recipe needs only eggs, milk, and flour.","這份簡單的食譜只需要蛋、牛奶和麵粉。",""]],"l1-0790":[["介系詞：自從……以來","無直接同義詞","I haven't seen my cousin since last summer.","自從去年夏天以來，我就沒見過表親。","since 常搭配完成式，指出持續至今的起點。"],["連接詞：因為","because / as","Since the road was closed, we took another route.","因為道路封閉，我們改走另一條路。",""]],"l1-0791":[["不及物動詞：唱歌","無直接同義詞","The children sang together while waiting for the bus.","等公車時，孩子們一起唱歌。",""]],"l1-0792":[["名詞：歌手","vocalist","The singer thanked the audience after the final song.","唱完最後一首歌後，歌手向觀眾致謝。",""]],"l1-0793":[["名詞稱呼：先生","無直接同義詞","Excuse me, sir, you dropped your ticket near the door.","先生，不好意思，您的票掉在門邊了。","sir 作禮貌稱呼時通常不直接接姓氏；Mr. 則通常接姓名。"]],"l1-0794":[["名詞：姊妹","無直接同義詞","My younger sister wants to learn the violin.","我妹妹想學小提琴。",""]],"l1-0795":[["不及物動詞：坐","take a seat","Let's sit by the window and watch the boats.","我們坐在窗邊看船吧。",""]],"l1-0796":[["數詞：六","無直接同義詞","Six chairs fit comfortably around this dining table.","這張餐桌周圍放六張椅子很寬敞。",""]],"l1-0797":[["數詞：十六","無直接同義詞","There were sixteen candles on her birthday cake.","她的生日蛋糕上有十六根蠟燭。",""]],"l1-0798":[["數詞：六十","無直接同義詞","Sixty students took part in the school art competition.","六十名學生參加了學校美術比賽。","原卡誤譯十六；sixty 是六十，sixteen 才是十六。"]],"l1-0799":[["名詞：尺寸；大小","dimensions","Check the size of the table before ordering a tablecloth.","訂購桌布前，先確認桌子的尺寸。","dimensions 是複數名詞，指長寬等尺寸。"]],"l1-0800":[["名詞：技能；技巧","ability / expertise","Her skill at fixing bicycles saved us a lot of money.","她修腳踏車的技術替我們省了不少錢。","expertise 強調專業熟練程度。"]],"l1-0801":[["名詞：皮膚","無直接同義詞","The cold wind made the skin on my hands feel dry.","冷風讓我手上的皮膚變得乾燥。",""]],"l1-0802":[["名詞：天空","the heavens","Pink clouds filled the sky just before sunset.","日落前，粉紅色雲朵布滿天空。","the heavens 為文學用語。"]],"l1-0803":[["不及物動詞：睡覺","slumber / doze","The baby slept peacefully while rain tapped on the window.","雨滴敲著窗戶時，寶寶安穩地睡著。","slumber 較文學；doze 是打盹或淺眠。"]],"l1-0804":[["形容詞：緩慢的","sluggish / unhurried","The slow bus took an hour to reach the village.","公車速度很慢，花了一小時才到村莊。","sluggish 暗示比正常慢；unhurried 表從容、不急。"]],"l1-0805":[["形容詞：小的","little / tiny","A small table fits neatly beside the kitchen window.","一張小桌子剛好放得進廚房窗邊。","tiny 表示非常小。"]],"l1-0806":[["形容詞：聰明的","clever / intelligent","The smart student found a simpler way to solve the problem.","那名聰明的學生找到更簡單的解題方法。",""]],"l1-0807":[["及物動詞：聞到","detect the scent of","I could smell fresh bread before entering the bakery.","還沒走進麵包店，我就聞到了新鮮麵包的香味。","detect the scent of 是聞到氣味的解說性片語。"],["名詞：氣味","odor / scent","The smell of oranges filled the kitchen as she peeled them.","她剝柳橙時，廚房裡充滿了柳橙香。","scent 常指香氣；odor 較中性或帶不悅氣味。"]],"l1-0808":[["不及物動詞：微笑","grin","She smiled when she saw her son waiting at the gate.","她看見兒子在門口等候時，露出了微笑。","grin 通常指露齒咧嘴笑。"]],"l1-0809":[["名詞：煙","無直接同義詞","Smoke rose from the chimney into the cold air.","煙從煙囪裡升起，飄進冷空氣中。",""]],"l1-0810":[["名詞：蛇","serpent","A small snake slid quietly through the tall grass.","一條小蛇悄悄滑過高草叢。","serpent 較文學。"]],"l1-0811":[["名詞：雪","無直接同義詞","Fresh snow covered the road during the night.","夜裡，新落的雪覆蓋了道路。",""]],"l1-0812":[["連接詞：所以","and therefore","The shop was closed, so we went home without bread.","店已經關門，所以我們沒買到麵包就回家了。",""],["副詞：這麼；非常","very","The soup is so hot; let it cool first.","湯好燙，先讓它放涼吧。","so 在此帶強調語氣；若用 so ... that 結構則不能直接以 very 替換。"]],"l1-0813":[["名詞：肥皂","無直接同義詞","Wash your hands with soap after working in the garden.","在花園工作後，請用肥皂洗手。",""]],"l1-0814":[["名詞：汽水（美式）","soft drink / pop","He ordered a lemon soda with his lunch.","他吃午餐時點了一杯檸檬汽水。","本句為碳酸飲料義；soda 也可指蘇打粉等物質。"]],"l1-0815":[["名詞：沙發","couch / settee","We sat on the sofa to watch the evening news.","我們坐在沙發上看晚間新聞。",""]],"l1-0816":[["形容詞：柔軟的","yielding","The soft pillow helped him sleep more comfortably.","柔軟的枕頭讓他睡得更舒服。","yielding 表受壓會陷下去，較書面。"]],"l1-0817":[["名詞：土壤","earth","Mix some fresh soil into the pot before planting.","種植前，先在盆子裡拌入一些新土。",""]],"l1-0818":[["限定詞：一些","a few","Some students brought their own lunches to the picnic.","一些學生自備午餐參加野餐。","a few 強調數量不多；some 只表示不確定的一部分。"]],"l1-0819":[["代名詞：某人","somebody","Someone left a blue umbrella beside the classroom door.","有人把一把藍傘留在教室門邊。",""]],"l1-0820":[["代名詞：某物；某事","無直接同義詞","There's something moving under the pile of leaves.","那堆落葉底下有東西在動。",""]],"l1-0821":[["副詞：有時候","occasionally / at times","We sometimes walk to the market instead of driving.","我們有時會走路去市場，不開車。","原卡標 pron.；sometimes 實為頻率副詞。"]],"l1-0822":[["名詞：兒子","無直接同義詞","Their son drew a picture of the whole family.","他們的兒子畫了一幅全家人的畫。",""]],"l1-0823":[["名詞：歌曲","tune","The children learned a song about the four seasons.","孩子們學了一首關於四季的歌。","tune 可口語指歌，但也可只指旋律。"]],"l1-0824":[["副詞：不久；很快","shortly / before long","The train should arrive soon, so stay near the platform.","火車應該快到了，請待在月台附近。",""]],"l1-0825":[["形容詞：抱歉的","apologetic","I'm sorry I spilled water on your notebook.","很抱歉，我把水灑在你的筆記本上。",""]],"l1-0826":[["名詞：靈魂；心靈","spirit","The poet believed that music could comfort the soul.","那位詩人相信音樂能撫慰心靈。",""]],"l1-0827":[["名詞：聲音","noise","The sound of thunder frightened the dog under the table.","雷聲嚇到了桌子底下的狗。","noise 常指吵雜或不悅的聲音；sound 較中性。"],["連綴動詞：聽起來","無直接同義詞","Your idea sounds interesting, but we need more details.","你的想法聽起來很有趣，但我們需要更多細節。",""]],"l1-0828":[["名詞：湯","無直接同義詞","She made vegetable soup to use up the leftover carrots.","她用剩下的胡蘿蔔煮了蔬菜湯。",""]],"l1-0829":[["形容詞：酸的","tart / acidic","The yogurt tastes too sour without a little honey.","這份優格不加一點蜂蜜，吃起來太酸。","acidic 可描述酸性；tart 常形容食物帶明顯酸味。"]],"l1-0830":[["名詞：南方","無直接同義詞","Many birds fly to the south when winter arrives.","冬天到來時，許多鳥會飛往南方。",""]],"l1-0831":[["名詞：空間","room","There isn't enough space for another chair at this table.","這張桌子旁沒有足夠空間再放一張椅子。","room 作空間義時不可數，不等於 a room 房間。"]],"l1-0832":[["不及物動詞：說話","talk","Please speak slowly so everyone can understand your directions.","請慢慢說，讓大家都能聽懂你的指示。",""]],"l1-0833":[["形容詞：特別的","distinctive / exceptional","She saved the dress for a special family celebration.","她把這件洋裝留著，準備特別的家庭慶祝活動時穿。","exceptional 強調非比尋常；distinctive 強調特色。"]],"l1-0834":[["名詞：演說","address / talk","The principal gave a short speech at the graduation ceremony.","校長在畢業典禮上發表了簡短演說。","address 較正式。"]],"l1-0835":[["及物動詞：拼寫","spell out","Please spell your last name so I can write it correctly.","請拼出你的姓，讓我能正確寫下來。",""]],"l1-0836":[["及物動詞：花費（金錢）","expend / pay out","We spent most of our money on train tickets.","我們把大部分的錢花在火車票上。","spend money on something；pay for something，句型不同。"]],"l1-0837":[["名詞：湯匙","無直接同義詞","Stir the sauce with a wooden spoon until it thickens.","用木匙攪拌醬汁，直到變濃稠。",""]],"l1-0838":[["名詞：運動","無直接同義詞","Swimming is the only sport my whole family enjoys.","游泳是我們全家都喜歡的唯一一種運動。",""]],"l1-0839":[["名詞：春天","springtime","The garden fills with colorful flowers every spring.","花園每年春天都開滿繽紛的花朵。",""]],"l1-0840":[["名詞：階梯","step","Be careful on the stairs; the top stair is loose.","走樓梯要小心，最上面那一階鬆了。","stairs 通常指整段樓梯；a stair 指一階。"]],"l1-0841":[["不及物動詞：站立","remain upright","Please stand behind the yellow line while waiting for the train.","等火車時，請站在黃線後方。","remain upright 是保持直立的解說性片語，非所有語境都可替換。"]],"l1-0842":[["名詞：星星","無直接同義詞","We could see hundreds of stars above the dark campsite.","我們在漆黑的營地上方看見了數百顆星星。",""]],"l1-0843":[["及物動詞：開始","begin","Let's start the meeting while everyone is here.","趁大家都在，我們開始開會吧。",""]],"l1-0844":[["名詞：狀態","condition","The bike was in a poor state after the accident.","事故過後，那輛腳踏車的狀況很糟。",""]],"l1-0845":[["及物動詞：陳述（state）","say / declare","The notice states that the pool closes at eight.","公告寫明泳池八點關閉。",""],["名詞：陳述（statement）","account / declaration","The witness gave a clear statement about the accident.","目擊者清楚陳述了事故經過。","statement 為名詞；declaration 常指正式聲明。"]],"l1-0846":[["名詞：車站","無直接同義詞","We waited inside the station because it was raining.","因為下雨，我們在車站裡等候。",""]],"l1-0847":[["不及物動詞：停留；留下","remain","Please stay here until your parents come to collect you.","爸媽來接你之前，請留在這裡。",""]],"l1-0848":[["名詞：步伐；一步","pace","She took a careful step onto the wet bridge.","她小心翼翼地踏了一步，上了濕橋面。",""]],"l1-0849":[["形容詞：靜止的","motionless / stationary","Keep still while I take your picture by the tree.","我在樹旁幫你拍照時，請不要動。",""],["副詞：仍然","無直接同義詞","It's late, but the children are still wide awake.","時間很晚了，但孩子們仍然清醒得很。",""]],"l1-0850":[["名詞：石頭","rock","A flat stone skipped across the surface of the lake.","一塊扁石在湖面上彈跳了幾下。",""]],"l1-0851":[["及物動詞：停止","halt","The driver stopped the bus to let an ambulance pass.","司機停下公車，讓救護車通過。",""]],"l1-0852":[["及物動詞：儲藏","keep / put away","We store extra blankets in the cupboard upstairs.","我們把備用毯子收在樓上的櫃子裡。",""]],"l1-0853":[["名詞：故事","tale / narrative","Grandma told us a story about her childhood on the farm.","奶奶講了她小時候在農場生活的故事給我們聽。",""],["名詞：樓層（美式）","floor / storey","The new library has three stories and a rooftop garden.","新圖書館有三層樓和一座屋頂花園。","樓層義的英式拼法為 storey，複數 storeys。"]],"l1-0854":[["形容詞：奇怪的","odd / unusual","A strange sound came from the empty room upstairs.","樓上空房間傳來了一個奇怪的聲音。",""]],"l1-0855":[["名詞：街道","road","The street outside our school is busy every morning.","我們學校外的街道每天早上都很繁忙。","street 通常兩側有建築物；road 的適用範圍更廣。"]],"l1-0856":[["形容詞：強壯的；有力的","powerful / muscular","Her strong arms made carrying the heavy bags look easy.","她強壯的雙臂讓提重袋子看起來毫不費力。","muscular 側重肌肉發達。"]],"l1-0857":[["名詞：學生","pupil","Each student brought a notebook to the science lesson.","每位學生都帶了一本筆記本上自然課。","pupil 常指中小學生。"]],"l1-0858":[["名詞：學習；研讀","learning","Regular study helped him feel ready for the English exam.","規律研讀讓他覺得自己已準備好參加英語考試。","study 強調投入研讀；learning 側重學到知識的過程。"],["及物動詞：研究；仔細觀察","examine / analyze","We studied the map before choosing a path through the forest.","我們仔細研究地圖，再選擇穿越森林的路線。",""]],"l1-0859":[["形容詞：愚蠢的","foolish / senseless","Leaving the keys in the car was a stupid mistake.","把鑰匙留在車裡，是個愚蠢的錯誤。","stupid 直接形容人時帶有侮辱性。"]],"l1-0860":[["限定詞：如此的","無直接同義詞","It was such a cold morning that the pond froze.","那天早上非常冷，連池塘都結冰了。","such + a/an + 形容詞 + 單數名詞。"]],"l1-0861":[["名詞：糖","無直接同義詞","She added a spoonful of sugar to the sour berries.","她在酸莓果裡加了一匙糖。",""]],"l1-0862":[["名詞：夏天","summertime","We swim in the lake every summer when we visit Grandma.","每年夏天去探望奶奶時，我們都會在湖裡游泳。",""]],"l1-0863":[["名詞：太陽","無直接同義詞","The sun warmed the stones beside the garden path.","太陽曬暖了花園小路旁的石頭。",""]],"l1-0864":[["名詞：星期日","無直接同義詞","Our family usually has a long breakfast on Sunday mornings.","我們家通常會在星期日早上悠閒地吃一頓早餐。","Sun. 是 Sunday 的縮寫。"]],"l1-0865":[["形容詞：極好的（口語）","great / excellent","You did a super job on the class poster.","你把班級海報做得很棒。","super 作形容詞常指極好的；原卡極度的不足以說明此用法。"]],"l1-0866":[["名詞：晚餐","dinner","We had a light supper after returning from the beach.","從海灘回來後，我們吃了一頓簡單的晚餐。","supper 常指晚間較輕便的一餐。"]],"l1-0867":[["形容詞：確信的","certain / confident","Are you sure this is the right train to take?","你確定我們該搭的是這班火車嗎？",""]],"l1-0868":[["及物動詞：使驚訝","amaze / astonish","Her quick progress surprised the piano teacher after only two lessons.","才上兩堂課，她快速的進步就讓鋼琴老師驚訝。","amaze、astonish 程度更強。"]],"l1-0869":[["形容詞：甜的","sugary","These strawberries are sweet enough to eat without sugar.","這些草莓很甜，不用加糖就好吃。","sugary 側重糖多或甜味很重。"]],"l1-0870":[["不及物動詞：游泳","無直接同義詞","We swam for half an hour before resting on the beach.","我們游了半小時，再到海灘上休息。",""]],"l1-0871":[["名詞：桌子","無直接同義詞","Please clear the table so we have room for dessert.","請把桌子收拾一下，騰出地方放甜點。",""]],"l1-0872":[["名詞：尾巴","無直接同義詞","The dog wagged its tail when it saw the leash.","狗看到牽繩時，搖起了尾巴。",""]],"l1-0873":[["及物動詞：拿取","pick up / grab","Take a clean towel from the shelf beside the shower.","從淋浴間旁的架子上拿一條乾淨毛巾。","grab 比 take 更強調快速或用力拿。"]],"l1-0874":[["名詞：故事","story / narrative","The old sailor told a tale about a lost island.","老水手講了一個關於失落島嶼的故事。",""]],"l1-0875":[["不及物動詞：說話；交談","speak / chat","We talked about our families while waiting for the train.","等火車時，我們聊了各自的家人。","chat 通常是輕鬆閒聊。"]],"l1-0876":[["形容詞：高的","lofty","The tall trees cast long shadows across the field.","高樹在田野上投下長長的影子。","lofty 較文學，強調高聳。"]],"l1-0877":[["及物動詞：品嚐","sample","Taste the sauce before deciding whether it needs more salt.","先嚐嚐醬汁，再決定要不要加鹽。",""]],"l1-0878":[["名詞：計程車","taxi / cab","We took a taxicab to the station because our bags were heavy.","因為行李很重，我們搭計程車去車站。",""]],"l1-0879":[["名詞：茶","無直接同義詞","She poured hot tea into two small cups.","她把熱茶倒進兩個小杯子裡。",""]],"l1-0880":[["及物動詞：教導","instruct / coach","My uncle taught me how to repair a flat tire.","我叔叔教我如何修補漏氣的輪胎。","instruct 較正式；coach 側重有針對性的指導訓練。"]],"l1-0881":[["名詞：老師","instructor / educator","Our teacher explained the question with a simple drawing.","老師用一張簡單的圖解釋了這道題。",""]],"l1-0882":[["及物動詞：告訴","inform","Please tell the driver where you want to get off.","請告訴司機你想在哪裡下車。",""],["及物動詞：分辨","distinguish","Can you tell the twins apart by their voices?","你能從聲音分辨這對雙胞胎嗎？","tell apart 指區分；distinguish between 的句型不同。"]],"l1-0883":[["數詞：十","無直接同義詞","We waited ten minutes before the doors finally opened.","我們等了十分鐘，門才終於打開。",""]],"l1-0884":[["連接詞：比","無直接同義詞","The river is deeper than it looks from here.","那條河比從這裡看起來的還深。",""]],"l1-0885":[["及物動詞：感謝","express gratitude to","I thanked the driver for helping with my bags.","我感謝司機幫我拿行李。","express gratitude to 是較正式的近義片語。"]],"l1-0886":[["代名詞：那個","無直接同義詞","That is the house where my grandfather grew up.","那就是我祖父長大的房子。",""]],"l1-0887":[["定冠詞：指特定或已知的人事物","無直接同義詞","Please close the door beside you before the cat escapes.","請把你旁邊的門關上，免得貓跑出去。","the 不等於 this；此處指雙方能辨認的那扇門。"]],"l1-0888":[["所有格限定詞：他們的（their）","無直接同義詞","Their parents arrived early to watch the school play.","他們的父母提早到場，觀看學校戲劇演出。","their 後接名詞；theirs 可單獨使用。"],["所有格代名詞：他們的（theirs）","無直接同義詞","Our tent is smaller than theirs, but it stays dry.","我們的帳篷比他們的小，但裡面不會進水。","theirs 在此代替 their tent。"]],"l1-0889":[["代名詞：他們；它們（受格）","無直接同義詞","The children were tired, so we drove them home.","孩子們累了，所以我們開車送他們回家。",""]],"l1-0890":[["副詞：那時","at that time","We lived near the sea then and walked on the beach daily.","我們那時住在海邊，每天都去沙灘散步。",""]],"l1-0891":[["副詞：在那裡","in that place","Leave your bicycle there, beside the blue garden gate.","請把腳踏車停在那裡，就在藍色花園大門旁邊。",""]],"l1-0892":[["限定詞：這些","無直接同義詞","These flowers need fresh water every other day.","這些花每隔一天就需要換新水。",""]],"l1-0893":[["代名詞：他們；它們（主格）","無直接同義詞","My cousins called to say they would arrive after lunch.","我的表親來電說，他們午餐後會到。",""]],"l1-0894":[["名詞：東西；物品","item / object","Put the heavy things at the bottom of the bag.","把重的東西放在袋子底部。",""]],"l1-0895":[["不及物動詞：思考","reflect / ponder","Think carefully before you choose a name for the puppy.","幫小狗取名之前，先仔細想想。","reflect、ponder 較正式；reflect 接思考對象時常加 on。"]],"l1-0896":[["序數詞：第三的","無直接同義詞","The third chapter explains how to care for young plants.","第三章說明如何照顧幼苗。",""]],"l1-0897":[["數詞：十三","無直接同義詞","Thirteen students stayed after class to help paint the scenery.","十三名學生放學後留下來幫忙畫舞台布景。",""]],"l1-0898":[["數詞：三十","無直接同義詞","The bus ride takes thirty minutes on a quiet day.","交通不繁忙時，這趟公車車程需要三十分鐘。",""]],"l1-0899":[["限定詞：這個","無直接同義詞","This old photo shows our street before the bridge was built.","這張老照片呈現了橋梁興建前我們街道的樣子。",""]],"l1-0900":[["限定詞：那些","無直接同義詞","Those shoes by the door belong to my brother.","門邊的那些鞋子是我哥哥的。",""]],"l1-0901":[["連接詞：雖然","although / even though","Though it was raining, we still enjoyed our walk.","雖然下著雨，我們仍然很享受這次散步。",""]],"l1-0902":[["名詞：想法","idea","Her first thought was to ask a neighbor for help.","她第一個念頭是向鄰居求助。",""]],"l1-0903":[["數詞：一千","無直接同義詞","More than a thousand people visited the exhibition last weekend.","上週末有超過一千人參觀展覽。",""]],"l1-0904":[["數詞：三","無直接同義詞","Three kittens were sleeping in a box by the heater.","三隻小貓睡在暖氣機旁的箱子裡。",""]],"l1-0905":[["及物動詞：丟；投擲","toss / hurl","Throw the ball gently so your little sister can catch it.","輕輕把球丟過去，讓你妹妹接得住。","toss 常指輕拋；hurl 指猛力投擲。"]],"l1-0906":[["名詞：星期四","無直接同義詞","The school choir practices after lunch every Thursday.","學校合唱團每週四午餐後練唱。","Thurs.、Thur. 都是 Thursday 的縮寫。"]],"l1-0907":[["副詞：因此","therefore / consequently","The bridge was closed; thus, we had to find another route.","橋梁封閉了，因此我們得另找一條路。","thus 較書面，連接獨立子句時注意標點。"]],"l1-0908":[["名詞：票","pass","Keep your ticket until you leave the station.","離開車站前，請保留車票。","pass 常指特定期間或多次使用的通行票。"]],"l1-0909":[["及物動詞：繫；綁","fasten / secure","Tie your shoes before running onto the playground.","跑進操場前，先把鞋帶綁好。","tie 專指以繩帶打結；fasten、secure 是更廣的固定動作。"],["名詞：領帶","necktie","He chose a dark blue tie for the interview.","他為面試選了一條深藍色領帶。",""]],"l1-0910":[["名詞：老虎","無直接同義詞","The tiger moved silently through the tall grass.","老虎無聲地穿過高草叢。",""]],"l1-0911":[["名詞：時間","無直接同義詞","We have enough time to eat before the train leaves.","火車出發前，我們有足夠時間吃東西。",""]],"l1-0912":[["形容詞：極小的","minute / minuscule","A tiny frog sat on a leaf beside the pond.","一隻極小的青蛙坐在池邊的葉子上。","minute 作極小的時讀 /maɪˈnjuːt/，不同於分鐘。"]],"l1-0913":[["名詞：輪胎","tyre","A nail in the road damaged the bicycle tire.","路上的釘子刺壞了腳踏車輪胎。","tyre 是英式拼法。"],["及物動詞：使疲累","wear out / exhaust","The long climb tired us more than we expected.","長時間爬坡讓我們比預期中還累。","exhaust 表示使筋疲力盡，程度更強。"]],"l1-0914":[["介系詞：到；往","無直接同義詞","We walked to the station carrying our heavy bags.","我們提著重袋子走到車站。",""]],"l1-0915":[["名詞：今天","this day","Today is the last day to return your library books.","今天是歸還圖書館書籍的最後一天。","this day 是解說性對應，日常通常直接用 today。"]],"l1-0916":[["副詞：一起","jointly","We worked together to clean the garden before the party.","派對前，我們一起整理花園。","jointly 較正式。"]],"l1-0917":[["名詞：明天","無直接同義詞","Tomorrow is a holiday, so the office will be closed.","明天放假，所以辦公室不開門。",""]],"l1-0918":[["名詞：語調；口氣","無直接同義詞","Her gentle tone helped the frightened child feel safe.","她溫柔的語氣讓受驚的孩子安心。","本例為說話態度的語調，不是音高的 pitch。"]],"l1-0919":[["名詞：今晚","this evening","Tonight will be our last chance to see the show.","今晚是我們看這場表演的最後機會。","this evening 通常指晚間較早時段；tonight 可延伸至整晚。"]],"l1-0920":[["副詞：也","also / as well","My sister likes this song, and I like it too.","我姊姊喜歡這首歌，我也喜歡。","too、as well 常放句尾；also 位置不同。"]],"l1-0921":[["名詞：工具","implement","Choose the right tool before trying to fix the shelf.","修理層板前，先選好合適的工具。","implement 較正式，泛指用來完成工作的工具或器具。"]],"l1-0922":[["名詞：頂部","summit","We reached the top of the hill just before sunset.","我們在日落前不久抵達山丘頂。","summit 適用於山頂，不指任何物體的頂部。"]],"l1-0923":[["形容詞：總計的","overall / combined","The total cost includes the hotel, meals, and train tickets.","總費用包含旅館、餐食和火車票。",""]],"l1-0924":[["及物動詞：觸摸","feel","Please don't touch the painting; the paint is still wet.","請別碰那幅畫，顏料還沒乾。","feel 側重為了感受質地而觸摸。"]],"l1-0925":[["介系詞：朝向","in the direction of","We walked toward the sea until we could hear the waves.","我們朝海邊走，直到聽得見浪聲。","toward、towards 意思相同。"]],"l1-0926":[["名詞：城鎮","無直接同義詞","The small town has one school and two bakeries.","這個小鎮有一所學校和兩間麵包店。",""]],"l1-0927":[["名詞：玩具","plaything","The puppy carried its favorite toy into the garden.","小狗把最喜歡的玩具叼進花園。","plaything 較少用於日常對話。"]],"l1-0928":[["名詞：火車","無直接同義詞","The train crossed the bridge slowly in the fog.","火車在霧中緩緩駛過橋梁。",""],["及物動詞：訓練","coach / instruct","She trains new staff to use the shop's computer system.","她訓練新員工使用店裡的電腦系統。",""]],"l1-0929":[["名詞：樹","無直接同義詞","We planted a tree to mark our daughter's birth.","我們種了一棵樹，紀念女兒的誕生。",""]],"l1-0930":[["名詞：旅行","journey / outing","Our trip to the coast included a visit to a lighthouse.","我們的海岸之旅包括參觀一座燈塔。","outing 通常是短程出遊。"]],"l1-0931":[["名詞：麻煩；困難","difficulty / problems","We had trouble finding the hotel in the dark.","天黑時，我們很難找到那間旅館。","have trouble doing something；trouble 此處不可數。"]],"l1-0932":[["形容詞：真實的；屬實的","accurate / factual","The story is true, although it sounds hard to believe.","這個故事是真的，雖然聽起來難以置信。",""]],"l1-0933":[["及物動詞：嘗試","attempt","She tried to open the jar, but the lid was stuck.","她試著打開罐子，但蓋子卡住了。",""]],"l1-0934":[["名詞：T恤","tee","He wore a plain T-shirt and jeans to the picnic.","他穿著素色T恤和牛仔褲去野餐。","tee 是 T-shirt 的口語簡稱。"]],"l1-0935":[["名詞：星期二","無直接同義詞","The art class meets every Tuesday in the school library.","美術班每週二在學校圖書館上課。","Tue. 是 Tuesday 的縮寫。"]],"l1-0936":[["名詞：肚子（兒語或口語）","belly / stomach","The little boy said his tummy hurt after lunch.","小男孩說他午餐後肚子痛。","stomach 在日常用法可泛指肚子，解剖上特指胃。"]],"l1-0937":[["及物動詞：轉動","rotate / twist","Turn the key slowly until you hear a click.","慢慢轉動鑰匙，直到聽見喀一聲。",""]],"l1-0938":[["數詞：十二","無直接同義詞","We need twelve plates for the family dinner tonight.","今晚全家聚餐，我們需要十二個盤子。",""]],"l1-0939":[["數詞：二十","無直接同義詞","Twenty children joined the summer reading program at the library.","二十個孩子參加了圖書館的暑期閱讀活動。",""]],"l1-0940":[["副詞：兩次","two times","I checked my bag twice before leaving the hotel.","離開旅館前，我檢查了兩次袋子。",""]],"l1-0941":[["數詞：二","無直接同義詞","We ordered two bowls of soup to share.","我們點了兩碗湯一起分著喝。",""]],"l1-0942":[["名詞：叔伯舅姑丈姨丈等男性親屬","無直接同義詞","My uncle taught me how to fish in the lake.","我叔叔教我如何在湖裡釣魚。","uncle 不區分中文的父母系親屬稱呼。"]],"l1-0943":[["介系詞：在……下面","beneath / below","The cat hid under the bed during the thunderstorm.","雷雨時，貓躲在床底下。",""]],"l1-0944":[["及物動詞：理解","comprehend / grasp","I understand the instructions better when you show me an example.","你示範一個例子後，我更能理解這些說明。",""]],"l1-0945":[["名詞：單元","section","The next unit in our textbook is about food and cooking.","我們課本的下一個單元是食物與烹飪。","本例為教材單元義；計量單位另有用法。"]],"l1-0946":[["介系詞：直到","till","The museum stays open until six on Friday evenings.","博物館星期五晚上開放到六點。",""]],"l1-0947":[["副詞：向上","upward / upwards","Look up and you'll see the nest above the window.","抬頭看，你就會看到窗戶上方的鳥巢。",""]],"l1-0948":[["副詞：在樓上；到樓上","無直接同義詞","The children went upstairs to get ready for bed.","孩子們上樓準備睡覺。",""]],"l1-0949":[["代名詞：我們（受格）","無直接同義詞","The guide showed us a safe path down the hill.","導遊指給我們一條安全的下山小路。",""]],"l1-0950":[["及物動詞：使用","employ","Use a ruler to draw a straight line.","用尺畫一條直線。","employ 表使用工具或方法時較正式。"]],"l1-0951":[["形容詞：有用的","helpful / handy","This small map is useful when we walk around town.","我們在鎮上走動時，這張小地圖很有用。","handy 較口語，強調方便實用。"]],"l1-0952":[["名詞：蔬菜","無直接同義詞","We bought fresh vegetables to make soup for dinner.","我們買了新鮮蔬菜，準備煮湯當晚餐。",""]],"l1-0953":[["副詞：非常","extremely / really","The children were very excited about their first camping trip.","孩子們對第一次露營感到非常興奮。","extremely 程度更強。"]],"l1-0954":[["名詞：景觀；視野","outlook / prospect","The hotel balcony offers a wide view of the mountains.","旅館陽台能眺望開闊的山景。","prospect 作景觀義較文學。"]],"l1-0955":[["及物動詞：參觀；造訪","tour","We visited an old castle during our trip to the coast.","海岸旅行途中，我們參觀了一座老城堡。","tour 常指有行程地周遊參觀。"]],"l1-0956":[["名詞：嗓音；說話聲","無直接同義詞","I recognized my mother's voice before I saw her.","我還沒看見媽媽，就先認出了她的聲音。","voice 指人發出的嗓音；sound 的範圍更廣。"]],"l1-0957":[["不及物動詞：等待","無直接同義詞","We waited under the shelter until the rain stopped.","我們在遮雨棚下等到雨停。","await 是及物動詞，不能直接替換本句不及物的 wait。"]],"l1-0958":[["不及物動詞：步行","go on foot","We walked home together after the evening concert.","晚間音樂會結束後，我們一起走路回家。",""]],"l1-0959":[["名詞：牆","無直接同義詞","He hung the family photo on the living room wall.","他把全家福掛在客廳牆上。",""]],"l1-0960":[["及物動詞：想要","desire / would like","I want a warm coat for the winter trip.","我想要一件保暖外套，冬天旅行時穿。","would like 較客氣；desire 較正式。"]],"l1-0961":[["名詞：戰爭","warfare / armed conflict","The museum shows how the war changed life in the town.","博物館展示戰爭如何改變了鎮上的生活。","warfare 側重戰爭行為與方式。"]],"l1-0962":[["形容詞：溫暖的","mild","The afternoon was warm enough to eat outside.","午後天氣很暖和，可以在戶外吃東西。","mild 指氣候溫和，未必像 warm 那麼暖。"]],"l1-0963":[["及物動詞：清洗","clean / rinse","Wash the apples before cutting them into slices.","先把蘋果洗乾淨，再切成片。","rinse 偏指用清水沖洗。"]],"l1-0964":[["及物動詞：浪費","squander","Don't waste clean water by leaving the tap running.","別一直開著水龍頭，浪費乾淨的水。","squander 較正式，強調揮霍。"]],"l1-0965":[["名詞：手錶","wristwatch","My watch stopped, so I checked the time on my phone.","我的手錶停了，所以我用手機看時間。",""],["及物動詞：觀看","observe","We watched the birds building a nest above the window.","我們看著鳥兒在窗戶上方築巢。","watch 通常持續注意動態；observe 較仔細或正式。"]],"l1-0966":[["名詞：水","無直接同義詞","Fill your bottle with water before starting the hike.","出發健行前，把水壺裝滿水。",""]],"l1-0967":[["名詞：路線；路","route / path","The shortest way to the station is through the park.","去車站最短的路是穿過公園。",""]],"l1-0968":[["代名詞：我們（主格）","無直接同義詞","We took turns reading the story aloud to the children.","我們輪流大聲讀故事給孩子們聽。",""]],"l1-0969":[["形容詞：虛弱的","frail / feeble","He still felt weak after spending a week in bed.","臥床一週後，他仍覺得虛弱。","frail 常指身體長期衰弱；feeble 強調力氣小。"]],"l1-0970":[["及物動詞：穿；戴著","have on","She wears a warm hat when she walks to work.","她走路上班時戴著保暖帽子。","wear 表穿戴狀態；put on 表穿上的動作。"]],"l1-0971":[["名詞：天氣","無直接同義詞","The weather improved, so we decided to visit the beach.","天氣變好了，所以我們決定去海灘。",""]],"l1-0972":[["名詞：婚禮","marriage ceremony","Their wedding took place in a small garden near the sea.","他們的婚禮在海邊一座小花園裡舉行。","marriage 也可指婚姻關係；ceremony 明確指出儀式。"]],"l1-0973":[["名詞：星期三","無直接同義詞","The school library stays open late every Wednesday.","學校圖書館每週三都開放到較晚的時間。","Wed. 是 Wednesday 的縮寫。"]],"l1-0974":[["名詞：週；星期","無直接同義詞","We spent a week visiting small towns along the coast.","我們花了一週走訪沿海的小鎮。",""]],"l1-0975":[["名詞：週末","無直接同義詞","She plans to spend the weekend painting her room.","她打算利用週末粉刷房間。",""]],"l1-0976":[["及物動詞：秤重","measure the weight of","Weigh the flour before adding it to the bowl.","把麵粉加進碗裡之前，先秤重。","measure the weight of 是秤重的解說性片語。"]],"l1-0977":[["名詞：重量","heaviness","The shelf bent under the weight of the books.","層板在書本的重量壓迫下彎曲了。","heaviness 強調重的程度或感受，較少用於精確量測。"]],"l1-0978":[["及物動詞：歡迎；迎接","greet / receive","Our neighbors welcomed us with a basket of fresh fruit.","鄰居用一籃新鮮水果歡迎我們。","welcome 強調友善接納；greet 只是打招呼或迎接。"]],"l1-0979":[["副詞：好地","skillfully","She plays the piano well after years of practice.","經過多年練習，她鋼琴彈得很好。","skillfully 特指有技巧地。"],["名詞：井","無直接同義詞","The old well supplies water to the farm's animals.","這口老井供水給農場的動物喝。",""],["形容詞：健康的；身體好的","healthy / fine","I feel well enough to go back to school now.","我現在身體恢復得夠好了，可以回學校上課。",""]],"l1-0980":[["名詞：西方","無直接同義詞","Dark clouds gathered in the west before the rain.","下雨前，烏雲聚集在西方。",""]],"l1-0981":[["代名詞：什麼","無直接同義詞","What would you like to eat after the concert?","音樂會結束後，你想吃什麼？",""]],"l1-0982":[["疑問副詞：何時","at what time","When does the first bus leave the village?","村裡第一班公車什麼時候出發？",""]],"l1-0983":[["疑問副詞：在哪裡","in what place","Where did you put the map we bought yesterday?","你把我們昨天買的地圖放在哪裡了？",""]],"l1-0984":[["連接詞：是否","if","I don't know whether the shop is open today.","我不知道那間店今天是否有開。","whether 可接 or not，也可用於介系詞後；if 並非所有場合都可替換。"]],"l1-0985":[["代名詞：哪一個","無直接同義詞","Which of these bags belongs to your younger sister?","這些袋子裡，哪個是你妹妹的？",""]],"l1-0986":[["連接詞：當……時","as","I washed the dishes while my brother dried them.","我洗碗時，我弟弟在一旁把碗擦乾。","while 常引出持續一段時間的同時動作。"],["名詞：一段時間；一會兒","a short time","Let's sit here for a while and enjoy the view.","我們在這裡坐一會兒，欣賞風景吧。","a while 可指長短不定的一段時間；本句取短暫休息。"]],"l1-0987":[["形容詞：白色的","無直接同義詞","The white curtains let plenty of sunlight into the room.","白色窗簾讓大量陽光透進房間。",""]],"l1-0988":[["疑問代名詞：誰","無直接同義詞","Who left these muddy shoes in the hallway?","是誰把這些沾泥巴的鞋子留在走廊上？",""]],"l1-0989":[["形容詞：整個的","entire / complete","The whole family came to watch her first concert.","全家人都來看她的第一場音樂會。",""]],"l1-0990":[["疑問代名詞：誰（受格）","who","To whom should I give the completed form?","我該把填好的表格交給誰？","whom 較正式；口語常改說 Who should I give the form to?，不能保留 to who 的正式句型。"]],"l1-0991":[["疑問所有格代名詞：誰的","無直接同義詞","Whose is the blue bicycle beside the gate?","大門旁那輛藍色腳踏車是誰的？","whose 表所有關係；who's 為 who is 或 who has。"]],"l1-0992":[["疑問副詞：為什麼","for what reason","Why did you leave your umbrella at the hotel?","你為什麼把傘留在旅館？",""]],"l1-0993":[["形容詞：寬的","broad","The wide doorway made moving the sofa much easier.","門口很寬，讓搬沙發容易多了。",""]],"l1-0994":[["名詞：妻子","無直接同義詞","His wife packed sandwiches for their long train journey.","他妻子為他們漫長的火車旅程準備了三明治。",""]],"l1-0995":[["名詞：意志；決心","determination / resolve","Her strong will helped her finish the difficult race.","她堅強的意志幫助她完成了艱難的比賽。",""],["名詞：遺囑","testament","He left his house to his daughter in his will.","他在遺囑中把房子留給女兒。","testament 常見於法律片語 last will and testament。"],["助動詞：將會","shall","We will meet you outside the station after lunch.","我們午餐後會在車站外和你見面。","shall 表未來時主要搭配 I、we，且較正式。"]],"l1-0996":[["及物動詞：贏得","take","Our team won the final match by one point.","我們隊以一分之差贏了決賽。","take a match 可表示贏下比賽。"]],"l1-0997":[["名詞：風","無直接同義詞","The wind blew dry leaves across the empty playground.","風吹著乾落葉，掃過空蕩蕩的操場。",""]],"l1-0998":[["名詞：窗戶","無直接同義詞","She opened the window to hear the birds outside.","她打開窗戶，聽外面的鳥叫聲。",""]],"l1-0999":[["名詞：葡萄酒","無直接同義詞","The restaurant serves local wine with its evening meals.","這間餐廳晚餐供應當地葡萄酒。","wine 不只紅酒，也包含白酒等；少數用法也指其他水果酒。"]],"l1-1000":[["名詞：冬天","wintertime","The village gets heavy snow during the winter.","這個村莊冬天會下大雪。",""]],"l1-1001":[["及物動詞：但願；希望（與現實不符）","無直接同義詞","I wish I could spend more time with my grandparents.","我真希望能多花些時間陪祖父母。","wish + 過去式或 could 常表示與現況不同的願望；不能直接換成 hope。"]],"l1-1002":[["介系詞：和……一起","along with","She went to the museum with her two cousins.","她和兩位表親一起去了博物館。","原卡 prpe. 為 prep. 的拼字錯誤。"]],"l1-1003":[["名詞：女人；女性","lady","The woman at the information desk helped us find the bus.","服務台的女士幫我們找到要搭的公車。","lady 帶禮貌稱呼色彩，woman 較中性。"]],"l1-1004":[["名詞：木材（wood）","timber / lumber","The carpenter chose strong wood for the new shelves.","木匠挑選了堅固的木材來做新層架。","timber、lumber 常指建築加工用木材。"],["複數名詞：樹林（woods）","woodland / forest","We followed a narrow path through the woods.","我們沿著一條小路穿過樹林。","woods 不是木材的普通複數義，而是樹林。"]],"l1-1005":[["名詞：字；詞","term","I underlined every word I didn't understand in the story.","我把故事裡每個不懂的字都畫了底線。","term 常指有特定領域或特定含義的詞。"]],"l1-1006":[["不及物動詞：工作；勞作","labor","The farmers worked in the fields from dawn until sunset.","農夫們從黎明到日落都在田裡工作。","labor 強調辛苦勞動，較正式。"],["名詞：工作；需完成的事","tasks","We have a lot of work to finish before Friday.","我們有許多工作要在星期五前完成。","work 此處不可數；tasks 是可數名詞複數。"]],"l1-1007":[["名詞：工人；工作者","employee","The worker repaired the broken window before the rain started.","那名工人在開始下雨前修好了破窗。","employee 特指受僱者；worker 也可包括自僱者。"]],"l1-1008":[["名詞：世界","globe","Her postcards come from friends all around the world.","她的明信片來自世界各地的朋友。",""]],"l1-1009":[["名詞：蠕蟲","無直接同義詞","A worm wriggled through the damp soil in the garden.","一隻蠕蟲在花園潮濕的土壤中蠕動。",""]],"l1-1010":[["及物動詞：使擔心","concern / trouble","The dark clouds worried us as we packed the tent.","收帳篷時，烏雲讓我們感到擔心。",""]],"l1-1011":[["形容詞：更嚴重的；更糟的","more serious / more severe","The damage to the roof was worse than we first thought.","屋頂的損壞比我們起初想的更嚴重。","worse 是 bad 的比較級。"]],"l1-1012":[["形容詞：最嚴重的；最糟的","most severe","This was the worst storm the village had seen in years.","這是村莊多年來遭遇過最嚴重的暴風雨。","worst 是 bad 的最高級。"]],"l1-1013":[["及物動詞：寫下","put down / record","Write the meeting time at the top of your notes.","在筆記最上方寫下會議時間。","record 可泛指記錄，不一定用筆。"]],"l1-1014":[["名詞：作家；作者","author","The writer visited our school to discuss her latest book.","那位作家來到我們學校，分享她的新書。",""]],"l1-1015":[["形容詞：錯誤的","incorrect","I wrote the wrong date on the letter by mistake.","我不小心在信上寫錯了日期。",""]],"l1-1016":[["名詞：地瓜；番薯（sweet potato）","yam","I baked a sweet potato and ate it for breakfast.","我烤了一條地瓜當早餐。","美式飲食語境中 yam 可指橘肉地瓜；真正的 yam 是薯蕷類，植物上不同。"],["名詞：薯蕷類塊莖（yam）","無直接同義詞","She peeled the yam and cut it into pieces for soup.","她把薯蕷去皮，切塊煮湯。","此處取 yam 的本義，與 sweet potato 不同。"]],"l1-1017":[["名詞：年","無直接同義詞","We planted this tree a year after moving into the house.","我們搬進這棟房子一年後，種了這棵樹。",""]],"l1-1018":[["形容詞：黃色的","無直接同義詞","Bright yellow flowers grew beside the old stone wall.","鮮黃色的花朵長在老石牆旁。",""]],"l1-1019":[["應答詞：是；好","yeah","Yes, I can help you carry those bags upstairs.","好，我可以幫你把那些袋子提上樓。","yeah 是 yes 的口語變體，正式場合通常用 yes。"]],"l1-1020":[["名詞：昨天","the previous day","Yesterday was the first sunny day after a week of rain.","下了一週雨之後，昨天是第一個晴天。","the previous day 須有時間參照點；yesterday 以今天為基準。"]],"l1-1021":[["副詞：還（未）","so far / as yet","The bus hasn't arrived yet, so we're still waiting.","公車還沒到，所以我們仍在等候。","yet 在否定句中常帶期待事情之後發生的語氣。"]],"l1-1022":[["代名詞：你；你們","無直接同義詞","You can borrow my umbrella if it starts raining.","如果開始下雨，你可以借用我的傘。","you 可指單數或複數，也可作主格或受格。"]],"l1-1023":[["形容詞：幼小的；未成熟的","juvenile","The young birds stayed in the nest during the storm.","暴風雨時，幼鳥待在巢裡。","juvenile 可形容尚未成年的動物，較正式。"]],"l1-1024":[["所有格限定詞：你的；你們的（your）","無直接同義詞","Please leave your shoes by the door before coming in.","進來前，請把鞋子放在門邊。","your 後接名詞；yours 可單獨使用。"],["所有格代名詞：你的；你們的（yours）","無直接同義詞","My bag is under the table; is yours there too?","我的袋子在桌子底下，你的也在那裡嗎？","yours 可單獨使用，後面不直接接名詞；your 後接名詞。"]],"l1-1025":[["形容詞：噁心的；難吃的（口語）","disgusting / gross","The soup tasted yucky after I added too much salt.","我加了太多鹽之後，湯變得很難喝。","yucky 常見於兒語或非常口語的表達。"]],"l2-0001":[["名詞：能力","capability","Her ability to explain difficult ideas makes her a good teacher.","她能把困難的概念解釋清楚，因此是位好老師。",""]],"l2-0002":[["副詞：在國外","overseas","My older sister studied abroad for a year and learned Spanish.","我姊姊在國外讀了一年書，學會了西班牙文。",""]],"l2-0003":[["名詞：缺席","nonattendance","The teacher asked me to explain my absence yesterday.","老師要我解釋昨天缺席的原因。","nonattendance 較正式，常指未出席活動。"]],"l2-0004":[["形容詞：缺席的","away","Two students were absent from class because they had a cold.","兩名學生因為感冒而缺課。","away 可表示暫時不在；absent from 表示未出席。"]],"l2-0005":[["動詞：接受","take","Mia accepted the job offer after discussing it with her family.","米亞和家人討論後，接受了那份工作邀約。",""]],"l2-0006":[["形容詞：活躍好動的","energetic / lively","Our active puppy needs a long walk every morning.","我們那隻活潑的小狗每天早上都需要散步很久。",""]],"l2-0007":[["名詞：新增的人或物","newcomer","The new coach is a welcome addition to our team.","這位新教練的加入很受我們隊伍歡迎。","newcomer 指新來者；addition 也可指新增的物品。"]],"l2-0008":[["動詞：促進","further / promote","The new training program will advance her career in nursing.","這項新的培訓計畫將促進她的護理職涯發展。",""]],"l2-0009":[["名詞：事情","matter / business","Please stay out of this affair; it concerns my family.","請別介入這件事；這涉及我的家人。",""]],"l2-0010":[["動詞：幫助","help / assist","Volunteers aided the families whose homes were damaged by the storm.","志工幫助了房屋遭暴風雨損壞的家庭。",""]],"l2-0011":[["動詞：瞄準","point","The photographer aimed her camera at the birds on the roof.","攝影師把相機對準屋頂上的鳥。","aim at 強調朝向目標；point 較強調方向。"]],"l2-0012":[["名詞：航空器","無直接同義詞","Only small aircraft can land safely on this short runway.","只有小型航空器能安全降落在這條短跑道上。","aircraft 包括飛機及直升機，單複數同形。"]],"l2-0013":[["名詞：航空公司","air carrier","The airline canceled our flight because of heavy snow.","航空公司因大雪取消了我們的航班。",""]],"l2-0014":[["名詞：警報器","無直接同義詞","The smoke alarm woke us before the fire spread upstairs.","火勢延燒到樓上前，煙霧警報器把我們吵醒了。",""]],"l2-0015":[["名詞：相簿","photo album","Grandma showed us an album full of her wedding photos.","奶奶給我們看了一本裝滿她婚禮照片的相簿。",""]],"l2-0016":[["形容詞：相像的","similar","These two keys look alike, but only one opens the gate.","這兩把鑰匙看起來很像，但只有一把能開大門。","alike 通常放在連綴動詞後，不直接放在名詞前。"]],"l2-0017":[["形容詞：活著的","living","The little tree is still alive despite the dry summer.","儘管夏天很乾燥，那棵小樹還活著。",""]],"l2-0018":[["名詞：杏仁","無直接同義詞","She sprinkled chopped almonds over the cake before serving it.","她把蛋糕端上桌前，在上面撒了切碎的杏仁。",""]],"l2-0019":[["副詞：出聲地","out loud","Please read the instructions aloud so everyone can hear them.","請把說明讀出聲，讓每個人都能聽見。","aloud 指出聲，不一定是大聲喊叫。"]],"l2-0020":[["名詞：字母系統","無直接同義詞","My little brother can write every letter of the alphabet.","我弟弟已經會寫字母表裡的每個字母。",""]],"l2-0021":[["連接詞：雖然","though / even though","Although the soup looked plain, it tasted rich and delicious.","雖然這道湯看起來很普通，喝起來卻濃郁又美味。",""]],"l2-0022":[["副詞：完全地","completely / entirely","After the bridge closed, buses stopped using this road altogether.","橋梁封閉後，公車就完全不走這條路了。",""]],"l2-0023":[["名詞：數量","quantity","Add a small amount of water if the sauce is too thick.","如果醬汁太濃稠，就加少量的水。","amount 通常搭配不可數名詞；可數名詞用 number。"]],"l2-0024":[["形容詞：古代的","無直接同義詞","We saw ancient tools and pottery at the history museum.","我們在歷史博物館看到了古代的工具和陶器。","old 只表示舊或年久，不一定屬於古代。"]],"l2-0025":[["名詞：腳踝","無直接同義詞","Ben hurt his ankle when he stepped off the bus.","班下公車時弄傷了腳踝。",""]],"l2-0026":[["代名詞：任何人","anyone / anybody","Anyone can join the class, even without any cooking experience.","任何人都可以參加這堂課，即使完全沒有烹飪經驗也可以。",""]],"l2-0027":[["副詞：無論如何","anyway / in any case","The tickets were expensive, but we decided to go anyhow.","票價很貴，但我們還是決定要去。",""]],"l2-0028":[["副詞：任何時候","at any time","You can return the library books anytime before Friday.","你可以在星期五之前的任何時間歸還圖書館的書。",""]],"l2-0029":[["副詞：儘管如此；仍然","anyhow / nevertheless","I knew it might rain, but I went hiking anyway.","我知道可能會下雨，但還是去健行了。",""]],"l2-0030":[["副詞：任何地方","anyplace","You can sit anywhere except the seats marked with red signs.","除了標有紅色告示的座位外，你可以坐任何地方。","anyplace 主要用於美式口語。"]],"l2-0031":[["名詞：公寓住宅","flat","Their new apartment has two bedrooms and a small kitchen.","他們的新公寓有兩間臥室和一間小廚房。","flat 主要用於英式英語。"]],"l2-0032":[["名詞：出現","arrival","The singer's surprise appearance at the festival delighted her fans.","這位歌手在音樂節驚喜現身，讓歌迷非常開心。","arrival 偏重抵達；appearance 在此指公開現身。"]],"l2-0033":[["名詞：食慾","hunger","A walk before dinner usually gives me a good appetite.","晚餐前散步通常會讓我胃口大開。","hunger 偏重飢餓感；appetite 是想吃東西的慾望。"]],"l2-0034":[["動詞：塗抹","spread / put on","Apply the cream gently to your hands after washing them.","洗完手後，輕輕地把乳霜塗在手上。",""],["動詞：申請","無直接同義詞","She plans to apply for a job at the bookstore.","她打算應徵那間書店的工作。","apply for a job 申請工作；apply to a company 向公司申請。"]],"l2-0035":[["名詞：圍裙","無直接同義詞","Dad wore an apron to keep flour off his clothes.","爸爸穿著圍裙，避免麵粉沾到衣服。",""]],"l2-0036":[["動詞：爭吵","quarrel / bicker","The children argued about whose turn it was to wash dishes.","孩子們為了輪到誰洗碗而爭吵。","原卡 argue(ment) 合併動詞 argue 與名詞 argument。"],["名詞：爭執（argument）","quarrel / dispute","Their argument about money continued long after dinner ended.","晚餐結束很久後，他們還在為錢的事爭吵。",""]],"l2-0037":[["動詞：武裝","equip with weapons","The guards were armed with rifles outside the palace.","宮殿外的守衛配備了步槍。","equip with weapons 為同義片語；例句使用被動語態。"]],"l2-0038":[["名詞：扶手椅","無直接同義詞","Grandpa reads the newspaper in his favorite armchair every morning.","爺爺每天早上都坐在他最喜歡的扶手椅上看報。",""]],"l2-0039":[["動詞：安排","organize / plan","We arranged a meeting with the landlord for Tuesday afternoon.","我們安排在星期二下午與房東見面。","原卡 arrange(ment) 合併 arrange 與 arrangement。"],["名詞：安排（arrangement）","plan","We made arrangements for someone to feed the cat while we were away.","我們安排了人在我們外出期間餵貓。",""]],"l2-0040":[["動詞：逮捕","apprehend / take into custody","Police arrested the driver after finding stolen goods in his van.","警方在那名駕駛的廂型車裡找到贓物後，將他逮捕。",""]],"l2-0041":[["動詞：抵達","get there","We arrived at the station just before the last train left.","我們趕在末班車開走前抵達車站。","arrive at 小地點；arrive in 城市或國家。get there 不再接 at。"]],"l2-0042":[["名詞：箭","無直接同義詞","The arrow struck the center of the wooden target.","那支箭射中了木製箭靶的正中央。",""]],"l2-0043":[["名詞：文章（article）","piece","I read an article about saving water in the school newspaper.","我在校刊上讀到了一篇關於節約用水的文章。","essay 通常是論說文或作文，不是所有 article 都可改用 essay。"]],"l2-0044":[["名詞：藝術家","無直接同義詞","The artist used old bicycle parts to make a bird sculpture.","那位藝術家用舊自行車零件做了一座鳥的雕塑。",""]],"l2-0045":[["形容詞：睡著的","sleeping","The baby was already asleep when we arrived home.","我們到家時，寶寶已經睡著了。","asleep 通常不用在名詞前。"]],"l2-0046":[["名詞：助手","helper / aide","The dentist's assistant handed her a clean set of tools.","牙醫助理遞給她一套乾淨的工具。",""]],"l2-0047":[["動詞：攻擊","assault","A large dog attacked the delivery worker outside the gate.","一隻大狗在大門外攻擊了送貨員。","assault 常指對人的暴力襲擊，語氣較正式。"]],"l2-0048":[["動詞：出席","go to / be present at","All new students must attend the welcome meeting on Monday.","所有新生都必須參加星期一的迎新說明會。","attend a meeting，attend 後直接接活動。"]],"l2-0049":[["名詞：注意力","concentration / focus","Please pay attention while I explain how to use the machine.","我解釋如何使用機器時，請專心聽。","固定搭配 pay attention；近義詞不能直接放入此片語。"]],"l2-0050":[["動詞：避開","keep away from / steer clear of","We left early to avoid the heavy traffic near the stadium.","我們提早出發，避開體育場附近的壅塞車潮。",""]],"l2-0051":[["動詞：臨時照顧小孩","look after children","Can you baby-sit for us while we go to the concert?","我們去聽演唱會時，你能幫我們顧小孩嗎？","現在也常寫作 babysit。近義片語未限定臨時性。"]],"l2-0052":[["名詞：臨時保母","sitter","We hired a baby-sitter to watch the twins on Saturday evening.","我們請了臨時保母在星期六晚上照顧雙胞胎。","也常寫作 babysitter。"]],"l2-0053":[["形容詞：向後的","rearward","One backward step brought his heel to the edge of the stage.","他向後退了一步，腳跟就來到了舞臺邊緣。",""]],"l2-0054":[["副詞：向後地","back / rearward","She walked backwards to keep the whole building in her photo.","她向後走，好把整棟建築拍進照片裡。","原稿 adj 有誤：表示移動方向的 backward(s) 在此為副詞。Cambridge: https://dictionary.cambridge.org/dictionary/english/backward"]],"l2-0055":[["動詞：烘烤","無直接同義詞","We baked a chocolate cake for our neighbor's birthday.","我們為鄰居的生日烤了一個巧克力蛋糕。","roast 與 grill 的烹調方式不同，不能一概替換 bake。"]],"l2-0056":[["名詞：麵包店","bake shop","The bakery on the corner sells warm rolls every morning.","街角那間麵包店每天早上都賣熱騰騰的小麵包。",""]],"l2-0057":[["名詞：陽臺","無直接同義詞","We grow herbs in pots on our sunny balcony.","我們在陽光充足的陽臺上用盆子種香草。",""]],"l2-0058":[["名詞：竹子；竹材","無直接同義詞","The garden fence is made of bamboo tied together with rope.","花園的圍籬是用繩子綁起來的竹子做成的。",""]],"l2-0059":[["名詞：銀行業者","無直接同義詞","The banker reviewed our business plan before discussing the loan.","那位銀行業者先看了我們的營運計畫，再討論貸款。",""]],"l2-0060":[["名詞：戶外烤肉聚會","cookout","Our neighbors invited us to a barbecue in their backyard.","鄰居邀請我們到他們後院參加烤肉聚會。","cookout 常見於美式英語。"]],"l2-0061":[["動詞：吠叫","woof","The dog barked when someone knocked on the front door.","有人敲前門時，那隻狗叫了起來。",""],["名詞：樹皮","無直接同義詞","The rough bark scraped my hand as I climbed the tree.","我爬樹時，粗糙的樹皮刮傷了我的手。",""]],"l2-0062":[["名詞：地下室","cellar","We keep our camping equipment in boxes in the basement.","我們把露營裝備裝箱，放在地下室。","cellar 常用來儲物；basement 也可能是居住空間。"]],"l2-0063":[["複數名詞：基礎知識","fundamentals / essentials","This short course teaches the basics of taking good photographs.","這門短期課程教授拍好照片的基礎知識。","原稿 basics 標成 adj 有誤；basics 為複數名詞，basic 才是形容詞。https://dictionary.cambridge.org/us/dictionary/english/basics"]],"l2-0064":[["名詞：基礎；依據","foundation / grounds","The witnesses' reports formed the basis of the police investigation.","證人的陳述構成了警方調查的依據。",""]],"l2-0065":[["名詞：戰鬥","fight / combat","The old painting shows a battle between two ships at sea.","那幅古畫描繪兩艘船在海上交戰的情景。",""]],"l2-0066":[["名詞：珠子","無直接同義詞","She threaded colorful beads onto a string to make a bracelet.","她把彩色珠子穿上繩子，做成一條手鍊。",""]],"l2-0067":[["名詞：豆子","無直接同義詞","Soak the dried beans overnight before adding them to the soup.","乾豆要先浸泡一夜，再加進湯裡。",""]],"l2-0068":[["動詞：承受","endure / tolerate","I could not bear the noise and closed the window.","我受不了那個噪音，便關上了窗戶。",""]],"l2-0069":[["名詞：鬍鬚","無直接同義詞","My uncle grew a beard during his month in the mountains.","我叔叔在山裡待了一個月，期間蓄起了鬍鬚。","beard 指下巴及臉頰的鬍鬚；mustache 指上唇的鬍子。"]],"l2-0070":[["名詞：臥室","bedchamber","Our bedroom faces the garden, so it is quiet at night.","我們的臥室朝向花園，所以夜裡很安靜。","bedchamber 是舊式或文學用語。"]],"l2-0071":[["名詞：牛肉","無直接同義詞","The stew contains beef, carrots, potatoes, and a little red wine.","這道燉菜有牛肉、紅蘿蔔、馬鈴薯和少許紅酒。",""]],"l2-0072":[["名詞：嗶聲","bleep","A short beep told me that the washing machine had finished.","一聲短促的嗶聲告訴我，洗衣機已經洗好了。",""]],"l2-0073":[["名詞：啤酒","無直接同義詞","He ordered a glass of beer with his fish and chips.","他點了一杯啤酒，搭配炸魚和薯條。",""]],"l2-0074":[["名詞：甲蟲","無直接同義詞","A shiny green beetle crawled slowly across the picnic table.","一隻閃亮的綠色甲蟲慢慢爬過野餐桌。",""]],"l2-0075":[["動詞：懇求","plead with / implore","The children begged their parents to let them keep the kitten.","孩子們懇求父母讓他們留下那隻小貓。","beg someone to do something；implore 語氣較強。"],["動詞：乞求；乞討","ask for / solicit","The man begged money from people leaving the station.","那名男子向離開車站的人乞討錢。","beg money from someone；solicit 較正式且不一定出於貧困。"]],"l2-0076":[["名詞：初學者","novice","This swimming class is for beginners who are afraid of deep water.","這堂游泳課是為害怕深水的初學者開設的。","novice 指缺乏經驗的初學者；newcomer 只表示新加入的人，不一定是初學者。"]],"l2-0077":[["名詞：信念","conviction","Her belief that everyone deserves respect guides her work as a teacher.","她相信每個人都值得尊重，這個信念指引著她的教學工作。",""]],"l2-0078":[["形容詞：可信的","credible / convincing","His excuse was believable because the buses really were delayed.","他的理由很可信，因為公車的確誤點了。",""]],"l2-0079":[["名詞：腰帶","無直接同義詞","These trousers are too loose, so I need a belt.","這條褲子太鬆了，所以我需要一條腰帶。",""]],"l2-0080":[["名詞：長椅","無直接同義詞","We sat on a bench beside the pond and watched the ducks.","我們坐在池塘邊的長椅上看鴨子。",""]],"l2-0081":[["動詞：使彎曲","flex","Bend your knees slightly before you lift the heavy box.","搬起重箱子前，先把膝蓋稍微彎曲。","本句指彎曲膝關節，可用 flex；curve 常指形成曲線。"]],"l2-0082":[["副詞：此外","moreover / furthermore","The hotel is too expensive; besides, it is far from the station.","那家飯店太貴了；而且離車站很遠。",""]],"l2-0083":[["名詞：賭注","wager","They made a small bet on which team would win the match.","他們小賭了一下，猜哪一隊會贏得比賽。",""]],"l2-0084":[["介系詞：在更遠處","past","There is a small fishing village beyond those hills.","那些山丘的另一邊有一座小漁村。",""]],"l2-0085":[["名詞：餐廳帳單","check","Please check the bill before you pay for the meal.","付餐費前，請先核對帳單。","check 指餐廳帳單為美式用法。"]],"l2-0086":[["動詞：捆綁","tie / fasten","Bind the newspapers with string so they are easier to carry.","用繩子把報紙綁起來，這樣比較好搬。",""]],"l2-0087":[["形容詞：苦的","無直接同義詞","The medicine tastes bitter, so she drinks water immediately afterward.","藥吃起來很苦，所以她吃完立刻喝水。","sour 是酸，不能當成 bitter 的同義詞。"]],"l2-0088":[["名詞：黑板","chalkboard","The teacher drew a large map of Taiwan on the blackboard.","老師在黑板上畫了一幅大大的臺灣地圖。",""]],"l2-0089":[["形容詞：空白的","empty","Leave the last page blank for your teacher's comments.","把最後一頁留白，讓老師寫評語。",""]],"l2-0090":[["形容詞：失明的","sightless","The blind musician learned the entire piece by listening to a recording.","那位失明的音樂家靠聆聽錄音學會了整首曲子。","sightless 較偏文學用語。"]],"l2-0091":[["形容詞：沾有血的","bloodstained","He pressed a clean towel against his bloody knee.","他把乾淨的毛巾按在沾著血的膝蓋上。",""]],"l2-0092":[["名詞：木板","plank","We laid a wide board across the ditch to make a bridge.","我們在水溝上橫放一塊寬木板，搭成一座橋。",""]],"l2-0093":[["動詞：沸騰","come to a boil","Wait for the water to boil before adding the noodles.","等水煮沸後再放入麵條。",""]],"l2-0094":[["名詞：炸彈","無直接同義詞","Workers found an old bomb while repairing the railway bridge.","工人修理鐵路橋時發現了一枚舊炸彈。",""]],"l2-0095":[["形容詞：瘦得見骨的","skinny / scrawny","The rescued dog was so bony that we could see its ribs.","那隻獲救的狗瘦到我們都看得見牠的肋骨。",""],["形容詞：骨質的","osseous","The doctor pointed to a bony ridge on the model skull.","醫師指著頭骨模型上的一道骨質隆起。","osseous 是專業用語。https://dictionary.cambridge.org/dictionary/english/bony"]],"l2-0096":[["名詞：書櫃","無直接同義詞","The tall bookcase holds our novels, dictionaries, and photo albums.","那座高書櫃放著我們的小說、字典和相簿。","bookshelf 指書架的一層或置書架，未必是整座書櫃。"]],"l2-0097":[["動詞：借入","無直接同義詞","May I borrow your umbrella until I get home tonight?","我可以借你的雨傘，用到今晚回家嗎？","borrow 是借入；lend 是借出，方向相反。"]],"l2-0098":[["名詞：上司","supervisor / manager","My boss approved my request to take Friday off.","我的上司批准了我星期五請假的申請。",""]],"l2-0099":[["動詞：打擾","disturb / trouble","Sorry to bother you, but could you help me move this desk?","抱歉打擾你，你能幫我搬這張書桌嗎？",""]],"l2-0100":[["名詞：瓶子","無直接同義詞","Fill your water bottle before we start the long hike.","開始這趟長途健行前，先把水瓶裝滿。",""]],"l2-0101":[["名詞：蝴蝶結","無直接同義詞","She tied a red bow around the box of chocolates.","她在巧克力盒上繫了一個紅色蝴蝶結。","此義讀 /boʊ/；鞠躬義的 bow 讀 /baʊ/。"]],"l2-0102":[["名詞：保齡球運動","無直接同義詞","We went bowling after work and played three games.","我們下班後去打保齡球，玩了三局。",""]],"l2-0103":[["名詞：腦","無直接同義詞","A helmet helps protect your brain if you fall off your bike.","騎自行車摔倒時，安全帽有助於保護你的腦部。",""]],"l2-0104":[["名詞：樹枝","bough / limb","A strong wind broke a large branch off the oak tree.","強風吹斷了橡樹的一根大樹枝。","bough 和 limb 通常指較粗大的樹枝。"]],"l2-0105":[["名詞：品牌","make","Which brand of running shoes fits your feet best?","哪個牌子的跑鞋最合你的腳？","make 常用於車輛或機器的品牌。"]],"l2-0106":[["名詞：磚塊","無直接同義詞","The workers stacked red bricks beside the unfinished wall.","工人把紅磚堆在尚未完成的牆邊。",""]],"l2-0107":[["形容詞：短暫的","short / fleeting","We had a brief conversation before she hurried to her next class.","我們簡短聊了一下，她便趕去上下一堂課。",""]],"l2-0108":[["形容詞：寬闊的","wide","A broad path leads from the parking lot to the beach.","一條寬闊的小徑從停車場通往海灘。",""]],"l2-0109":[["動詞：播送","air / transmit","The local station will broadcast the concert live on Saturday.","當地電臺將在星期六現場轉播這場音樂會。",""]],"l2-0110":[["名詞：早午餐","無直接同義詞","We slept late and met our friends for brunch at eleven.","我們睡到很晚，十一點才和朋友碰面吃早午餐。",""]],"l2-0111":[["動詞：刷","無直接同義詞","Brush the mud off your boots before you come inside.","進屋前，先把靴子上的泥刷掉。",""]],"l2-0112":[["名詞：小麵包","bread roll / bun","The waiter brought a warm roll to go with my soup.","服務生送來一個溫熱的小麵包，搭配我的湯。","bun 常為圓形，也可能是甜麵包；roll 的形狀較多。"]],"l2-0113":[["名詞：一捆","bunch","She carried a bundle of old blankets to the animal shelter.","她抱著一捆舊毛毯，送到動物收容所。","bundle 通常指綁起或包起的一組物品。"]],"l2-0114":[["動詞：燒傷；燙傷","無直接同義詞","Be careful not to burn your fingers on the hot pan.","小心別讓熱鍋燙傷手指。","本句指接觸熱鍋造成燙傷；scald 特指熱液體或蒸氣燙傷，scorch 常指表面燒焦。"]],"l2-0115":[["動詞：爆裂","pop / split open","The balloon burst when it touched the sharp corner of the table.","氣球碰到桌子的尖角時爆開了。",""]],"l2-0116":[["名詞：生意；商業活動","trade / commerce","Business at the ice cream shop improves when the weather gets warmer.","天氣變暖時，冰淇淋店的生意就會變好。",""]],"l2-0117":[["名詞：鈕扣","無直接同義詞","One button fell off my shirt while I was getting dressed.","我穿衣服時，襯衫掉了一顆鈕扣。",""]],"l2-0118":[["名詞：高麗菜；甘藍","無直接同義詞","Cut the cabbage into thin strips for the salad.","把高麗菜切成細絲，拿來做沙拉。",""]],"l2-0119":[["名詞：鋼索","wire rope","Thick steel cables hold the bridge high above the river.","粗鋼索將橋梁支撐在河流上方。",""]],"l2-0120":[["名詞：咖啡館","coffee shop","We found a quiet café where we could study together.","我們找到一間安靜的咖啡館，可以一起讀書。",""]],"l2-0121":[["名詞：自助餐廳","canteen","The school cafeteria serves hot meals from eleven until one.","學校餐廳從十一點到一點供應熱食。","canteen 常見於英式英語，指學校或工作場所的餐廳。"]],"l2-0122":[["名詞：日曆","無直接同義詞","I marked the interview date on the calendar above my desk.","我在書桌上方的日曆上標出了面試日期。",""]],"l2-0123":[["形容詞：鎮定的","composed / relaxed","The nurse stayed calm and helped the frightened child breathe slowly.","護理師保持鎮定，幫助受驚的孩子慢慢呼吸。",""]],"l2-0124":[["動詞：取消","call off / scrap","The school canceled the outdoor concert because of strong winds.","學校因強風取消了戶外音樂會。",""]],"l2-0125":[["名詞：癌症","無直接同義詞","The charity raises money to support families affected by cancer.","這個慈善團體募款，支持受到癌症影響的家庭。",""]],"l2-0126":[["名詞：蠟燭","無直接同義詞","We lit a candle when the electricity went out.","停電時，我們點了一根蠟燭。",""]],"l2-0127":[["名詞：船長","skipper / master","The captain ordered everyone to put on a life jacket.","船長命令大家穿上救生衣。","skipper 較口語；master 用於船長時較正式。"]],"l2-0128":[["名詞：地毯","rug","The thick carpet keeps the bedroom floor warm in winter.","那張厚地毯讓臥室地板在冬天保持溫暖。","rug 通常是可移動的小塊地毯；carpet 可鋪滿房間。"]],"l2-0129":[["名詞：紅蘿蔔","無直接同義詞","Grate a carrot and mix it into the rice.","把一根紅蘿蔔刨成絲，拌進飯裡。",""]],"l2-0130":[["名詞：手推車","trolley","She pushed a cart full of groceries toward the checkout.","她推著裝滿食品雜貨的購物車，走向結帳處。","trolley 主要用於英式英語。"]],"l2-0131":[["名詞：卡通；動畫片","animated film","The children watched a cartoon about a bear learning to dance.","孩子們看了一部關於小熊學跳舞的卡通。","animated film 通常指動畫電影；cartoon 也包括短片及影集。"]],"l2-0132":[["名詞：現金","ready money","This small shop accepts only cash, so bring some coins and notes.","這間小店只收現金，所以請帶些硬幣和紙鈔。","ready money 較少用，指可立即使用的錢。"]],"l2-0133":[["名詞：卡式錄音帶","cassette tape / tape","My father found a cassette of songs he recorded in college.","我爸爸找到了一卷他大學時錄製歌曲的卡式錄音帶。",""]],"l2-0134":[["名詞：城堡","無直接同義詞","The castle stands on a hill overlooking the river.","那座城堡矗立在山丘上，俯瞰河流。","palace 偏重宮殿居所，fortress 偏重防禦要塞，不能全面替換。"]],"l2-0135":[["名詞：洞穴","cavern","We carried flashlights into the cave to see the rock formations.","我們帶著手電筒進入洞穴，觀賞岩石的形狀。","cavern 通常指大型洞穴。"]],"l2-0136":[["名詞：天花板","無直接同義詞","A leak left a brown stain on the kitchen ceiling.","漏水在廚房天花板上留下了一塊褐色污漬。",""]],"l2-0137":[["名詞：細胞","無直接同義詞","We examined onion cells under a microscope in science class.","我們在自然課上用顯微鏡觀察洋蔥細胞。",""]],"l2-0138":[["形容詞：中央的","centrally located","A large fountain stands in the central square of the town.","鎮中央的廣場上有一座大型噴水池。","centrally located 表示位於中央；替換時可說 the centrally located square。"]],"l2-0139":[["名詞：一百年；世紀","a hundred years","The stone bridge has carried traffic for more than a century.","那座石橋供人車通行已超過一個世紀。","a century 可改為 a hundred years；此處需連同冠詞一起替換。"]],"l2-0140":[["名詞：早餐穀片","breakfast cereal","I poured milk over my cereal and sliced a banana on top.","我把牛奶倒在穀片上，再把一根香蕉切片放在上面。",""]],"l2-0141":[["名詞：粉筆","無直接同義詞","The teacher used yellow chalk to underline the important dates.","老師用黃色粉筆在重要日期下畫線。",""]],"l2-0142":[["動詞：改變","alter / modify","We changed our route when we saw the road was closed.","看到道路封閉後，我們改了路線。",""],["名詞：找零","無直接同義詞","The cashier gave me two dollars in change after I paid.","我付錢後，收銀員找了我兩元。",""]],"l2-0143":[["名詞：性格","personality / nature","His quiet kindness is an important part of his character.","他不張揚的善良，是他性格中很重要的一部分。",""]],"l2-0144":[["動詞：收費","bill","The repair shop charged me twenty dollars to fix the wheel.","修理店收了我二十元修輪子。","charge someone an amount；改用 bill 時可說 bill someone an amount for something。"]],"l2-0145":[["形容詞：便宜的","inexpensive / low-cost","We found a cheap hotel within walking distance of the station.","我們找到了一家便宜的旅館，走路就能到車站。",""]],"l2-0146":[["動詞：作弊","無直接同義詞","He cheated on the test by looking at his neighbor's answers.","他在考試時偷看鄰座的答案作弊。","deceive 表示欺騙某人，不能直接取代 cheat on a test。"]],"l2-0147":[["形容詞：化學的","無直接同義詞","The students wore gloves during the chemical experiment in the lab.","學生在實驗室做化學實驗時戴著手套。",""]],"l2-0148":[["名詞：西洋棋","無直接同義詞","My older brother taught me to play chess during the winter holiday.","寒假時，我哥哥教我下西洋棋。",""]],"l2-0149":[["形容詞：幼稚的","immature / silly","Hiding her notebook was a childish way to show your anger.","把她的筆記本藏起來，是一種幼稚的生氣表現。","childish 常含批評意味；childlike 常形容天真等正面特質。"]],"l2-0150":[["形容詞：天真如孩子的","innocent","She watched the fireworks with childlike wonder in her eyes.","她眼中帶著孩子般的驚奇，望著煙火。","childlike 常形容純真；childish 常批評人幼稚。"]],"l2-0151":[["名詞：下巴","無直接同義詞","He rested his chin on his hand while listening.","他聽的時候，用手托著下巴。",""]],"l2-0152":[["名詞：巧克力","無直接同義詞","She melted dark chocolate to pour over the strawberries.","她融化黑巧克力，準備淋在草莓上。",""]],"l2-0153":[["名詞：選擇權","option","You have a choice between taking the bus and walking home.","你可以選擇搭公車或走路回家。",""]],"l2-0154":[["動詞：挑選","select / pick","Choose a photo that clearly shows the front of the building.","挑一張能清楚呈現建築物正面的照片。",""]],"l2-0155":[["名詞：筷子","無直接同義詞","She showed her guest how to hold chopsticks properly.","她示範給客人看如何正確拿筷子。",""]],"l2-0156":[["名詞：圓圈","ring","Draw a circle around the correct answer on your worksheet.","在學習單上，把正確答案圈起來。",""]],"l2-0157":[["名詞：公民","national","She became a Canadian citizen after living there for several years.","她在加拿大住了幾年後，成為加拿大公民。","national 指具有某國國籍者；citizen 也強調公民身分及權利。"]],"l2-0158":[["動詞：要求領取","request / demand","I went online to claim a refund for my canceled flight.","我上網申請退還已取消航班的票款。","claim 常表示主張有權取得；request 較中性，demand 語氣較強。"]],"l2-0159":[["動詞：拍手","applaud","Everyone clapped when the young pianist finished her first concert.","那位年輕鋼琴家完成第一場音樂會時，大家都鼓掌了。",""]],"l2-0160":[["形容詞：典型的","typical / textbook","This painting is a classic example of the artist's early style.","這幅畫是這位藝術家早期風格的典型例子。",""]],"l2-0161":[["名詞：爪子","無直接同義詞","The cat caught the curtain with one sharp claw.","貓用一隻尖爪勾住了窗簾。","猛禽的爪可用 talon，本句的貓爪不適用。"]],"l2-0162":[["名詞：黏土","無直接同義詞","We shaped the wet clay into bowls and left them to dry.","我們把濕黏土捏成碗，放著晾乾。",""]],"l2-0163":[["名詞：清潔工","cleaning worker","The cleaner emptied the bins after everyone had left the office.","大家離開辦公室後，清潔工清空了垃圾桶。",""]],"l2-0164":[["名詞：店員","sales assistant / shop assistant","The store clerk helped me find batteries for my camera.","店員幫我找到了相機適用的電池。",""]],"l2-0165":[["形容詞：聰明的","smart / bright / intelligent","The clever student found a shorter way to solve the problem.","那位聰明的學生找到了更簡便的解題方法。",""]],"l2-0166":[["名詞：氣候","無直接同義詞","The island's warm climate allows farmers to grow bananas.","島上溫暖的氣候讓農民能種植香蕉。","climate 指長期氣候；weather 指較短期的天氣。"]],"l2-0167":[["名詞：衣櫥","wardrobe","Hang your coat in the closet beside the front door.","把外套掛在前門旁的衣櫥裡。","closet 常為內建的小儲物空間；wardrobe 常是獨立家具。"]],"l2-0168":[["名詞：布料","fabric / material","She bought enough cloth to make curtains for both windows.","她買了足夠的布料，要替兩扇窗戶做窗簾。",""]],"l2-0169":[["動詞：提供衣物","dress / outfit","The charity helps feed and clothe children from families in need.","這個慈善團體幫助有需要的家庭，提供孩子食物和衣物。",""]],"l2-0170":[["複數名詞：衣服","clothing / garments","Pack some warm clothes because the nights will be cold.","帶幾件保暖衣物，因為晚上會很冷。","clothes 是複數名詞；clothing 是不可數名詞。"]],"l2-0171":[["不可數名詞：衣物","clothes / garments","All protective clothing must be returned at the end of the tour.","參觀結束時，所有防護衣物都必須歸還。",""]],"l2-0172":[["形容詞：多雲的","overcast","It was cloudy all morning, but the sun appeared after lunch.","整個上午都多雲，但午餐後太陽就出來了。","overcast 通常指天空被雲完全遮住。"]],"l2-0173":[["名詞：小丑","無直接同義詞","The clown made balloon animals for the children at the party.","小丑在派對上為孩子們做氣球動物。",""]],"l2-0174":[["名詞：社團","society / association","I joined the photography club to meet people with similar interests.","我加入攝影社，想認識興趣相近的人。",""]],"l2-0175":[["名詞：教練","trainer","The coach showed us how to pass the ball more accurately.","教練教我們如何把球傳得更準。",""]],"l2-0176":[["名詞：煤","無直接同義詞","The old factory once burned coal to power its machines.","那間老工廠曾經燒煤來驅動機器。",""]],"l2-0177":[["名詞：公雞","rooster","The cock crowed loudly before sunrise and woke the whole family.","公雞在日出前大聲啼叫，把全家都吵醒了。","美式英語較常用 rooster。"]],"l2-0178":[["名詞：蟑螂","roach / cockroach","We found a cockroach under the sink while cleaning the kitchen.","我們打掃廚房時，在水槽下發現一隻蟑螂。","roach 是 cockroach 的常見縮稱。"]],"l2-0179":[["名詞：硬幣","無直接同義詞","I dropped a coin into the machine to buy a drink.","我把一枚硬幣投入機器買飲料。",""]],"l2-0180":[["動詞：收集","gather / assemble","The students collected fallen leaves for their art project.","學生們為了美術作業收集落葉。",""]],"l2-0181":[["形容詞：色彩繽紛的","bright / multicolored","Colorful flags hung above the street during the summer festival.","夏日慶典期間，街道上方掛滿了色彩繽紛的旗子。",""]],"l2-0182":[["動詞：梳理","無直接同義詞","She combed her wet hair gently after taking a shower.","她洗完澡後，輕輕梳理濕髮。","brush 使用刷子；comb 使用梳子，工具不同。"]],"l2-0183":[["形容詞：舒適的","comfy","These shoes are comfortable enough for a full day of sightseeing.","這雙鞋很舒服，適合穿著觀光一整天。","comfy 是較口語的近義詞；cozy 通常形容溫暖、愜意的環境。"]],"l2-0184":[["名詞：公司","firm / business","Her company makes reusable bags from recycled plastic bottles.","她的公司用回收塑膠瓶製作環保袋。",""]],"l2-0185":[["動詞：比較","無直接同義詞","Compare the prices at several shops before buying a new phone.","買新手機前，先比較幾家店的價格。","contrast 專重差異；compare 可同時檢視異同。"]],"l2-0186":[["動詞：抱怨","grumble / protest","Guests complained about the loud music coming from the restaurant.","客人抱怨餐廳傳來的音樂太大聲。",""]],"l2-0187":[["動詞：完成","finish","Please complete the form and return it to the front desk.","請填完表格後交回櫃檯。",""]],"l2-0188":[["名詞：電腦","無直接同義詞","The library has computers that visitors can use for free.","圖書館有電腦，訪客可以免費使用。",""]],"l2-0189":[["動詞：確認","verify","Please call the restaurant to confirm our reservation for six people.","請打電話給餐廳，確認我們六個人的訂位。",""]],"l2-0190":[["名詞：衝突","disagreement / dispute","The manager helped resolve a conflict between two members of the team.","經理協助化解了兩名團隊成員之間的衝突。",""]],"l2-0191":[["專有名詞：孔子","無直接同義詞","Our teacher asked us to discuss a saying by Confucius.","老師要我們討論孔子的一句話。",""]],"l2-0192":[["名詞：祝賀","felicitations","We sent our congratulations when we heard about her promotion.","聽說她升職後，我們向她表達了祝賀。","祝賀通常用複數 congratulations；felicitations 很正式。"]],"l2-0193":[["動詞：考慮","think about / contemplate","We are considering moving closer to our children's school.","我們正在考慮搬到離孩子學校近一點的地方。","consider 後接動名詞，不接 to do。"]],"l2-0194":[["動詞：聯絡","get in touch with / reach","Contact the hotel directly if you need to change your booking.","如果需要更改訂房，請直接聯絡飯店。",""]],"l2-0195":[["動詞：包含","include / hold","This box contains the tools we need to repair the bicycle.","這個箱子裝著我們修理自行車需要的工具。",""]],"l2-0196":[["動詞：控制","regulate / manage","Use this switch to control the speed of the fan.","用這個開關控制風扇的速度。",""]],"l2-0197":[["名詞：管制員","無直接同義詞","The air traffic controller guided the pilot toward a clear runway.","航空管制員引導飛行員前往一條空著的跑道。",""]],"l2-0198":[["形容詞：方便的","easy","The bus stop outside our building makes getting to work convenient.","大樓外的公車站讓我們上班很方便。","本句指通勤容易安排；easy 較廣泛，convenient 強調省時、省事或符合需求。"]],"l2-0199":[["名詞：交談","chat / talk","We had a long conversation about our plans for the summer.","我們聊了很久，談各自的夏季計畫。",""]],"l2-0200":[["名詞：炊具；爐具","stove / range","The new cooker has four burners and a large oven.","新的爐具有四個爐口和一個大烤箱。","英式 cooker 可指爐具；rice cooker 指電鍋。"]],"l2-0201":[["動詞：影印","photocopy / duplicate","Please copy this form and give one copy to each student.","請影印這張表格，發給每位學生一份。","Xerox 原為商標；一般影印常用 photocopy。"]],"l2-0202":[["名詞：角落","無直接同義詞","A small lamp stood in the corner beside the sofa.","沙發旁的角落放著一盞小燈。",""]],"l2-0203":[["形容詞：昂貴的","expensive / pricey","Replacing the damaged roof turned out to be a costly job.","更換受損的屋頂結果是一項昂貴的工程。",""]],"l2-0204":[["名詞：棉；棉布","無直接同義詞","This shirt is made of cotton and feels soft against my skin.","這件襯衫是棉製的，貼著皮膚感覺很柔軟。",""]],"l2-0205":[["動詞：咳嗽","無直接同義詞","He coughed several times after breathing in the dusty air.","吸入滿是灰塵的空氣後，他咳了好幾聲。",""]],"l2-0206":[["名詞：鄉間","country / rural areas","We spent the weekend cycling through the quiet countryside.","我們週末在寧靜的鄉間騎自行車。",""]],"l2-0207":[["名詞：郡；縣","無直接同義詞","The county opened a new library near the bus station.","縣政府在公車站附近開設了一間新圖書館。",""]],"l2-0208":[["名詞：伴侶；夫妻","pair","The married couple celebrated their anniversary at the restaurant where they first met.","那對夫妻在初次相遇的餐廳慶祝週年紀念日。","pair 不一定指戀愛或婚姻關係。"]],"l2-0209":[["名詞：勇氣","bravery / boldness","It took courage to admit his mistake in front of the class.","在全班面前承認自己的錯誤，需要勇氣。",""]],"l2-0210":[["名詞：法院","court of law","The witness told the court what she had seen that night.","證人向法院陳述她那晚看到的事情。",""]],"l2-0211":[["名詞：堂表兄弟姊妹","無直接同義詞","My cousin is staying with us while her parents are abroad.","我表姊的父母出國期間，她暫住我們家。","英文 cousin 不區分堂、表、性別或長幼；本句譯為表姊。"]],"l2-0212":[["名詞：螃蟹","無直接同義詞","A small crab disappeared into a hole in the sand.","一隻小螃蟹鑽進沙中的洞裡，不見了。",""]],"l2-0213":[["名詞：鶴","無直接同義詞","A crane stood on one leg in the shallow water.","一隻鶴單腳站在淺水中。",""]],"l2-0214":[["名詞：蠟筆","無直接同義詞","The child used a blue crayon to color the sea.","那個孩子用藍色蠟筆幫海洋上色。",""]],"l2-0215":[["形容詞：荒唐的","foolish / absurd","Driving through the flood would be a crazy risk to take.","開車穿越淹水區會是荒唐的冒險。",""]],"l2-0216":[["名詞：鮮奶油","無直接同義詞","She whipped the cream until it was thick enough to spread.","她把鮮奶油打發到足夠濃稠，可以塗抹的程度。","此義為鮮奶油，不是 butter（奶油塊）。https://dictionary.cambridge.org/dictionary/english/cream"]],"l2-0217":[["動詞：創作；創造","make / produce","The children created a colorful mural for the school entrance.","孩子們為學校入口創作了一幅色彩繽紛的壁畫。",""]],"l2-0218":[["名詞：犯罪行為","offense / illegal act","The police asked anyone who witnessed the crime to come forward.","警方請所有目睹這起犯罪的人出面提供資訊。",""]],"l2-0219":[["名詞：危機","emergency","The factory's closure created a financial crisis for many local families.","工廠關閉讓許多當地家庭陷入財務危機。","emergency 強調需要立即處理的緊急情況。"]],"l2-0220":[["名詞：農作物","無直接同義詞","Heavy rain damaged the rice crop just before the harvest.","就在收成前，大雨損壞了稻作。",""]],"l2-0221":[["名詞：叉號","無直接同義詞","Put a cross beside each item you have already packed.","在每件已經打包好的物品旁畫一個叉號。","本句指 × 記號；cross 也可指十字形或十字架，須依語境判斷。"]],"l2-0222":[["動詞：雞啼","無直接同義詞","The rooster crowed outside our window at five in the morning.","清晨五點，公雞就在我們窗外啼叫。",""]],"l2-0223":[["名詞：人群","throng","A large crowd gathered outside the theater to see the actors.","一大群人聚集在劇院外，想見到演員。",""]],"l2-0224":[["形容詞：殘忍的","heartless / brutal","It is cruel to leave an animal without food or water.","讓動物沒有食物或水，是殘忍的行為。",""]],"l2-0225":[["名詞：文化","無直接同義詞","Food and music are important parts of every culture.","飲食與音樂是每個文化的重要部分。",""]],"l2-0226":[["動詞：治癒","無直接同義詞","She hoped the new treatment would cure her illness.","她希望新的治療能治好她的病。","本句 cure an illness 指治癒疾病；heal 多指傷口癒合或使受傷部位復原。"]],"l2-0227":[["形容詞：好奇的","inquisitive / interested","The curious child wanted to know how the elevator worked.","那個好奇的孩子想知道電梯如何運作。",""]],"l2-0228":[["名詞：窗簾","drape","Close the curtains so the afternoon sun will not heat the room.","拉上窗簾，免得午後的陽光把房間曬熱。","drapes 通常指較厚、較正式的窗簾。"]],"l2-0229":[["名詞：習俗","tradition / practice","It is a local custom to remove your shoes before entering a home.","進屋前脫鞋是當地的習俗。",""]],"l2-0230":[["名詞：顧客","client / buyer","The customer asked whether the jacket came in a larger size.","那位顧客詢問這件外套是否有大一點的尺寸。","client 常用於接受專業服務的人。"]],"l2-0231":[["形容詞：每日的","everyday","A daily walk helps her relax after hours at her desk.","每天散步能幫助她在伏案數小時後放鬆。","daily 強調每天發生，未必只發生一次；everyday 也可指日常或普通的。"]],"l2-0232":[["動詞：損壞","spoil","Water from the broken pipe damaged several boxes of books.","破裂水管流出的水損壞了好幾箱書。","本句指水使書籍受損；spoil 強調破壞原有品質或可用性。"]],"l2-0233":[["形容詞：危險的","hazardous / unsafe","The icy steps are dangerous, so hold the handrail.","結冰的階梯很危險，所以要扶著扶手。",""]],"l2-0234":[["名詞：資料","information / facts","The students collected weather data every morning for a month.","學生們連續一個月每天早上蒐集天氣資料。",""]],"l2-0235":[["名詞：黎明","daybreak / first light","We left at dawn to reach the mountain before it got hot.","我們黎明時出發，想在天氣變熱前抵達山上。",""]],"l2-0236":[["形容詞：聽不見的；聾的","無直接同義詞","The deaf student asked for written instructions before the activity began.","那位聽不見的學生在活動開始前要求提供書面說明。","hard of hearing 指聽力減退，不等於完全聽不見。"]],"l2-0237":[["動詞：辯論；討論不同立場","discuss / argue about","The class debated whether school uniforms should be required.","全班辯論學校是否應規定穿制服。","debate 比一般 discuss 更強調比較不同立場。"]],"l2-0238":[["名詞：債務","money owed","He took a second job to pay off his debt.","他兼了第二份工作，想把債務還清。",""]],"l2-0239":[["名詞：決定","choice / resolution","Moving to a smaller apartment was a difficult decision for our family.","搬到較小的公寓，對我們家來說是個困難的決定。",""]],"l2-0240":[["動詞：裝飾","adorn","We decorated the hall with paper flowers for the graduation party.","我們用紙花裝飾禮堂，準備舉辦畢業派對。",""]],"l2-0241":[["名詞：度","無直接同義詞","The temperature fell by ten degrees after the sun went down.","太陽下山後，氣溫降了十度。",""]],"l2-0242":[["動詞：延誤","hold up / postpone","Heavy traffic delayed the delivery by almost an hour.","交通壅塞讓送貨延誤了將近一小時。","postpone 常指事先決定改期；delay 也可指意外耽擱。"]],"l2-0243":[["形容詞：美味的","tasty / delectable","The soup was delicious, so I asked for the recipe.","那道湯很好喝，所以我請教了食譜。",""]],"l2-0244":[["動詞：遞送","bring / take","The shop will deliver our new sofa on Friday morning.","店家會在星期五早上把新沙發送來。",""]],"l2-0245":[["名詞：牙醫","dental surgeon","The dentist checked my teeth and found a small cavity.","牙醫檢查我的牙齒，發現了一個小蛀洞。","dental surgeon 為正式或英式稱呼。"]],"l2-0246":[["動詞：否認","無直接同義詞","He denied taking the money and offered to show his bag.","他否認拿了錢，並主動表示可以檢查他的包包。","deny doing something 表示否認做過某事；refute 強調反駁，不能直接替換本句的 denied taking。"]],"l2-0247":[["名詞：部門","division / section","Please send your payment questions to the accounting department.","如有付款問題，請詢問會計部門。",""]],"l2-0248":[["動詞：依靠","rely on / count on","You can depend on Lara to arrive early and help set up.","你可以信賴蘿拉，她會提早到場幫忙布置。","depend on 整組對應 rely on，不要省略 on。"]],"l2-0249":[["名詞：深度","無直接同義詞","Check the water's depth before you jump into the pool.","跳進泳池前，先確認水深。",""]],"l2-0250":[["動詞：描述","depict / portray","Can you describe the bag you left on the train?","你能描述留在火車上的那個包包嗎？",""]],"l2-0251":[["名詞：沙漠","無直接同義詞","We carried extra water for our journey across the desert.","我們帶了額外的水，準備穿越沙漠。","名詞 desert 重音在第一音節；動詞拋棄的重音在第二音節。"]],"l2-0252":[["動詞：設計","plan / devise","The students designed a playground that younger children could use safely.","學生們設計了一座讓年幼孩子能安全使用的遊樂場。",""]],"l2-0253":[["名詞：渴望","wish / longing","Her desire to see the ocean inspired her first trip abroad.","她渴望看見海洋，因此展開了第一次出國旅行。",""]],"l2-0254":[["名詞：甜點","sweet / afters","For dessert, we shared a slice of lemon cake.","甜點我們一起吃了一片檸檬蛋糕。","sweet 作餐後甜點為英式用法；afters 為英式口語。"]],"l2-0255":[["動詞：察覺","notice / discover","The guard detected a strange smell near the storage room.","警衛在儲藏室附近察覺到一股奇怪的氣味。",""]],"l2-0256":[["動詞：發展；培養","build / improve","Reading different kinds of books helps children develop their language skills.","閱讀不同種類的書能幫助孩子培養語言能力。","原卡 develop(ment) 合併動詞 develop 與名詞 development。"]],"l2-0257":[["名詞：露水","無直接同義詞","Morning dew made the grass wet beneath our feet.","晨露把我們腳下的草地弄濕了。",""]],"l2-0258":[["名詞：刻度盤","無直接同義詞","The dial on the oven shows temperatures from fifty to three hundred degrees.","烤箱上的刻度盤標示五十度到三百度的溫度。",""]],"l2-0259":[["名詞：鑽石","無直接同義詞","A tiny diamond sparkled in the center of her ring.","她戒指中央的一顆小鑽石閃閃發光。",""]],"l2-0260":[["名詞：日記","journal","I write in my diary before going to bed each night.","我每天晚上睡前都會寫日記。",""]],"l2-0261":[["名詞：字典","無直接同義詞","Look up the word in a dictionary to check its pronunciation.","查字典確認這個字的發音。",""]],"l2-0262":[["名詞：差異","distinction / contrast","The main difference between these bikes is their weight.","這幾輛自行車的主要差異在於重量。",""]],"l2-0263":[["名詞：困難","trouble / problem","She had difficulty opening the jar because the lid was too tight.","她很難打開罐子，因為蓋子太緊了。","have difficulty doing something，difficulty 後接動名詞。"]],"l2-0264":[["名詞：恐龍","無直接同義詞","The museum displayed a dinosaur skeleton beside a model of its body.","博物館在一具恐龍骨骼旁展示了牠的身體模型。",""]],"l2-0265":[["名詞：方向","way","The wind changed direction and blew smoke toward the village.","風改變了方向，把煙吹向村莊。",""]],"l2-0266":[["名詞：主管","head / manager","The museum director approved our plan for a children's exhibition.","博物館館長核准了我們的兒童展覽計畫。",""]],"l2-0267":[["動詞：意見不同","differ / take issue","We disagree about the cost, but we both support the project.","我們對費用意見不同，但都支持這項計畫。","原卡合併 disagree 與 disagreement；take issue with someone。"]],"l2-0268":[["動詞：消失","vanish","The path disappeared under fallen leaves as we entered the forest.","我們走進森林時，小徑被落葉掩蓋，看不見了。",""]],"l2-0269":[["動詞：討論","talk about","We need to discuss the menu before buying food for the party.","我們需要先討論菜單，再採買派對食物。","discuss 後直接接主題，不加 about。"]],"l2-0270":[["名詞：討論","conversation / talk","After a short discussion, we agreed to meet again next week.","簡短討論後，我們同意下星期再見面。",""]],"l2-0271":[["形容詞：不誠實的","untruthful / deceitful","The seller was dishonest about the car's accident history.","賣家對這輛車的事故紀錄不誠實。",""]],"l2-0272":[["動詞：展示","show / exhibit","The library will display the children's artwork near the entrance.","圖書館將在入口附近展示孩子們的作品。",""]],"l2-0273":[["名詞：距離","無直接同義詞","The distance from our house to the beach is about two kilometers.","我們家到海灘的距離大約是兩公里。",""]],"l2-0274":[["形容詞：遙遠的","faraway / remote","We could see snow on the distant mountains from our hotel.","從飯店可以看見遠方山上的積雪。",""]],"l2-0275":[["動詞：分成","split / separate","Divide the cake into eight equal pieces for the guests.","把蛋糕切成八等份，分給客人。",""]],"l2-0276":[["名詞：分配；分割","split / distribution","A fair division of the work helped us finish before Friday.","公平分工讓我們得以在星期五之前完成。",""]],"l2-0277":[["形容詞：頭暈的","lightheaded / giddy","I felt dizzy after spinning around too many times.","轉了太多圈之後，我覺得頭暈。",""]],"l2-0278":[["名詞：海豚","無直接同義詞","A dolphin swam alongside our boat for several minutes.","一隻海豚在我們的船旁游了好幾分鐘。",""]],"l2-0279":[["名詞：驢","ass","The farmer led a donkey carrying baskets of vegetables.","農夫牽著一隻載著幾籃蔬菜的驢。","ass 是較舊的動物名稱，現代語境也可能有粗俗含義。"]],"l2-0280":[["名詞：點","spot","The red dot on the map marks our current location.","地圖上的紅點標示我們目前的位置。",""]],"l2-0281":[["形容詞：兩倍的","twofold","The larger bottle holds double the amount of the smaller one.","大瓶子的容量是小瓶子的兩倍。","double the amount；twofold 的句法不同，不能直接套入。"]],"l2-0282":[["動詞：懷疑","question","I doubt that the package will arrive before we leave.","我懷疑包裹能否在我們離開前送到。",""]],"l2-0283":[["名詞：甜甜圈","donut","She bought a doughnut and a cup of coffee before work.","她上班前買了一個甜甜圈和一杯咖啡。","donut 為常見變體拼法。"]],"l2-0284":[["名詞：市中心","city center","The city's downtown is full of shops, offices, and restaurants.","這座城市的市中心有許多商店、辦公室和餐廳。",""]],"l2-0285":[["名詞縮寫：醫師","Doctor","Dr. Chen will see you after she finishes with another patient.","陳醫師看完另一位病人後就會為你看診。","Dr. 是 Doctor 的稱謂縮寫；也用於博士。"]],"l2-0286":[["動詞：拖拉","pull / haul","We dragged the heavy suitcase up the narrow staircase.","我們把沉重的行李箱拖上狹窄的樓梯。",""]],"l2-0287":[["名詞：龍","無直接同義詞","The story tells of a dragon guarding a mountain of gold.","這個故事講述一條龍守護著堆積如山的黃金。",""]],"l2-0288":[["名詞：蜻蜓","無直接同義詞","A blue dragonfly landed on a reed beside the pond.","一隻藍色蜻蜓停在池塘旁的蘆葦上。",""]],"l2-0289":[["名詞：戲劇","play","The students performed a short drama about life in a fishing village.","學生們演出了一齣描寫漁村生活的短劇。",""]],"l2-0290":[["名詞：抽屜","無直接同義詞","I keep spare keys in the top drawer of my desk.","我把備用鑰匙放在書桌最上面的抽屜裡。",""]],"l2-0291":[["名詞：圖畫；素描","sketch","Her pencil drawing shows the old bridge on a rainy day.","她的鉛筆畫描繪了雨天裡的那座老橋。","sketch 通常較簡略，可能是草圖。"]],"l2-0292":[["動詞：穿衣","clothe / outfit","She dressed the baby in warm clothes before going outside.","她出門前先替寶寶穿上保暖衣物。",""]],"l2-0293":[["名詞：一滴","droplet","A drop of paint fell from the brush onto my shoe.","一滴油漆從刷子上滴到我的鞋上。",""]],"l2-0294":[["名詞：藥物","medicine / medication","The pharmacist explained how to store the drug safely at home.","藥師說明了如何在家中安全存放這種藥物。",""]],"l2-0295":[["名詞：藥房","pharmacy / chemist's","I stopped at the drugstore to collect my prescription.","我順道去藥房領處方藥。","chemist's 為英式用法；美式 drugstore 往往也販售日用品。"]],"l2-0296":[["名詞：鼓","無直接同義詞","The drummer hit the large drum to start the parade.","鼓手敲響大鼓，為遊行揭開序幕。",""]],"l2-0297":[["名詞：烘衣機","tumble dryer","The towels are still damp, so put them back in the dryer.","毛巾還是濕的，所以把它們放回烘衣機裡。",""]],"l2-0298":[["形容詞：乏味的","boring / tedious","The lecture was dull, and several students struggled to stay awake.","那場演講很乏味，好幾名學生努力撐著不睡著。",""]],"l2-0299":[["形容詞：說不出話的","speechless / mute","The surprising news left him dumb for a moment.","那個驚人的消息讓他一時說不出話來。","此處指暫時震驚；以 dumb 稱呼不能說話的人屬過時且可能冒犯的用法。https://dictionary.cambridge.org/dictionary/english/dumb"]],"l2-0300":[["名詞：餃子","無直接同義詞","We folded dumplings together and cooked them in a large pot.","我們一起包餃子，再用一個大鍋子煮熟。",""]],"l2-0301":[["名詞：義務","responsibility / obligation","It is our duty to return the equipment in good condition.","我們有責任把器材完好地歸還。",""]],"l2-0302":[["動詞：賺得","make","She earns extra money by teaching piano on weekends.","她週末教鋼琴，賺取額外收入。",""]],"l2-0303":[["名詞：地震","quake / tremor","The earthquake shook the shelves and knocked several books onto the floor.","地震搖動了書架，讓好幾本書掉到地上。","tremor 常指較輕微的震動。"]],"l2-0304":[["形容詞：東部的","無直接同義詞","Small fishing villages line the island's eastern coast.","小漁村沿著島嶼的東岸分布。",""]],"l2-0305":[["名詞：教育","schooling","Her parents saved money to pay for her college education.","她的父母存錢，準備支付她的大學教育費用。",""]],"l2-0306":[["名詞：影響","impact / influence","The road closure had a serious effect on local businesses.","道路封閉對當地商家造成嚴重影響。",""]],"l2-0307":[["形容詞：有效的","successful / useful","A clear sign is an effective way to guide visitors.","清楚的指示牌是引導訪客的有效方法。",""]],"l2-0308":[["名詞：努力","exertion","She put a lot of effort into preparing the presentation.","她花了很多心力準備這份簡報。","exertion 常偏重體力或精力的耗費。"]],"l2-0309":[["形容詞：年紀較大的","older","My elder sister taught me to ride a bicycle.","我姊姊教我騎自行車。","elder 常用於家人之間的長幼，放在名詞前。"]],"l2-0310":[["動詞：選舉","choose by vote","The students elected Maya as their class representative.","學生們選出瑪雅擔任班級代表。","這是解釋性近義片語；可改寫為 chose Maya by vote。vote for 只表示投票支持，未必選出。"]],"l2-0311":[["名詞：要素","component / part","Trust is an essential element of a successful team.","信任是成功團隊不可或缺的要素。",""]],"l2-0312":[["名詞：電梯","lift","Take the elevator to the fifth floor, then turn left.","搭電梯到五樓，再向左轉。","lift 為英式用法。"]],"l2-0313":[["名詞：情感","feeling","Her voice shook with emotion as she thanked the rescue workers.","她向救援人員道謝時，聲音因激動而顫抖。",""]],"l2-0314":[["動詞：鼓勵","urge","Our coach encouraged us to keep practicing despite the defeat.","儘管輸了比賽，教練仍鼓勵我們繼續練習。","原卡合併 encourage 與名詞 encouragement；urge someone to do 語氣較強，表示敦促。"]],"l2-0315":[["名詞：結局","conclusion / finish","The film's unexpected ending made everyone in the room fall silent.","電影出人意料的結局，讓房間裡每個人都安靜下來。",""]],"l2-0316":[["名詞：敵人","foe / adversary","The two former enemies finally agreed to meet and discuss peace.","從前敵對的雙方終於同意見面商討和平。",""]],"l2-0317":[["名詞：精力","vigor / vitality","After a good night's sleep, I had enough energy for the hike.","睡了一夜好覺後，我有足夠的精力去健行。",""]],"l2-0318":[["動詞：享受；喜歡","like / take pleasure in","We enjoyed watching the boats return to the harbor at sunset.","我們很享受在日落時看船隻返回港口。","原卡合併 enjoy 與 enjoyment；enjoy 後接動名詞。"]],"l2-0319":[["形容詞：整個的","whole / complete","The entire village gathered to welcome the runners home.","全村的人都聚集起來，歡迎跑者返鄉。",""]],"l2-0320":[["名詞：入口","entry / doorway","Please wait at the main entrance, next to the ticket booth.","請在主要入口的售票亭旁邊等。",""]],"l2-0321":[["名詞：信封","無直接同義詞","Write your address on the back of the envelope.","把你的地址寫在信封背面。",""]],"l2-0322":[["名詞：環境","surroundings / setting","Plants grow better in an environment with enough light and water.","植物在光線和水分充足的環境中生長得比較好。",""]],"l2-0323":[["名詞：橡皮擦","rubber","Use an eraser to remove the pencil marks from your drawing.","用橡皮擦把畫上的鉛筆痕擦掉。","rubber 指橡皮擦為英式用法。"]],"l2-0324":[["名詞：錯誤","mistake","A small error in the address sent the package to another town.","地址裡的一個小錯誤，讓包裹被送到另一個城鎮。",""]],"l2-0325":[["副詞：尤其","particularly / notably","The garden is beautiful, especially when the roses are in bloom.","花園很美，尤其在玫瑰盛開的時候。",""]],"l2-0326":[["名詞：活動","occasion / function","The school is organizing an event to raise money for new books.","學校正在籌辦一場活動，為添購新書募款。",""]],"l2-0327":[["形容詞：確切的","precise / accurate","Please tell me the exact time your train arrives.","請告訴我你的火車抵達的確切時間。",""]],"l2-0328":[["形容詞：極好的","outstanding / superb","The restaurant provides excellent service even when it is very busy.","這家餐廳即使很忙，也提供極好的服務。",""]],"l2-0329":[["動詞：使興奮","thrill","The chance to meet a real astronaut excited the whole class.","有機會見到真正的太空人，讓全班都很興奮。","原卡合併 excite 與名詞 excitement。"]],"l2-0330":[["名詞：藉口","pretext","He used the rain as an excuse to skip football practice.","他以雨天為藉口，缺席了足球練習。","pretext 常暗示用來掩飾真正理由。"]],"l2-0331":[["名詞：運動","physical activity","Swimming is her favorite form of exercise during the summer.","游泳是她夏天最喜歡的運動方式。",""]],"l2-0332":[["動詞：存在","be present","Wild horses still exist in a few remote areas of the country.","這個國家少數偏遠地區仍有野馬存在。",""]],"l2-0333":[["動詞：預期","anticipate","We expect the repairs to take about two weeks.","我們預期修理工作大約需要兩週。",""]],"l2-0334":[["形容詞：昂貴的","costly / pricey","Fresh strawberries are expensive here when they are out of season.","這裡的鮮草莓在非產季時很貴。",""]],"l2-0335":[["名詞：經驗","practice / background","She has ten years of experience working with young children.","她有十年與幼兒共事的經驗。","background 在此指相關資歷；experience 為不可數名詞。"]],"l2-0336":[["名詞：專家","specialist / authority","We asked a gardening expert why our lemon tree had stopped growing.","我們請教園藝專家，為什麼檸檬樹停止生長了。",""]],"l2-0337":[["動詞：解釋","clarify","Could you explain why this answer is different from mine?","你能解釋這個答案為什麼和我的不同嗎？",""]],"l2-0338":[["動詞：表達","convey / communicate","She wrote a letter to express her thanks to the hospital staff.","她寫信向醫院工作人員表達感謝。",""]],"l2-0339":[["形容詞：額外的","additional / spare","Bring an extra sweater in case the weather turns cold.","多帶一件毛衣，以防天氣變冷。",""]],"l2-0340":[["名詞：眉毛","brow","He raised one eyebrow when he heard the surprising price.","他聽到那個驚人的價格時，揚起了一邊的眉毛。",""]],"l2-0341":[["動詞：未能做到","be unsuccessful","We failed to reach the campsite before it got dark.","我們沒能在天黑前到達營地。","fail to do 可改寫為 be unsuccessful in doing；本句可說 were unsuccessful in reaching。"]],"l2-0342":[["名詞：失敗","lack of success","The failure of their first plan led them to try something different.","第一個計畫失敗後，他們轉而嘗試不同的做法。",""]],"l2-0343":[["形容詞：公平的","just / impartial","The coach made a fair decision after hearing both players' accounts.","教練聽過兩位球員的說法後，作出了公平的決定。",""]],"l2-0344":[["形容詞：著名的","well-known / renowned","The town is famous for its handmade pottery and narrow streets.","這個城鎮以手工陶器和狹窄的街道聞名。",""]],"l2-0345":[["名詞：缺點；瑕疵","defect / flaw","A fault in the cable caused the lights to go out.","電纜故障導致燈光熄滅。",""]],"l2-0346":[["動詞：贊成","support / prefer","Most residents favor building a park on the empty land.","多數居民贊成在那塊空地上蓋公園。",""]],"l2-0347":[["形容詞：最喜愛的","best-loved / preferred","My favorite bakery sells bread filled with cheese and onions.","我最喜歡的麵包店販售包著起司和洋蔥的麵包。",""]],"l2-0348":[["形容詞：害怕的","afraid / frightened","The fearful child held his mother's hand tightly during the storm.","暴風雨期間，那個害怕的孩子緊緊握著媽媽的手。","本句示範 fearful 常見的害怕義；原稿只列可怕義。https://dictionary.cambridge.org/dictionary/english/fearful"],["形容詞：可怕的","terrible / dreadful","The sailors faced a fearful storm far from shore.","水手們遠離海岸，面對一場可怕的暴風雨。","此義較少見，現代常用 terrible 或 dreadful；與害怕的 fearful 不同。https://dictionary.cambridge.org/dictionary/english/fearful"]],"l2-0349":[["名詞：費用","charge","The entrance fee includes a guided tour of the castle.","門票費用包含城堡導覽。",""]],"l2-0350":[["名詞：人；傢伙","man / chap","The friendly fellow at the next table offered us his extra chair.","鄰桌那位友善的男士把多出來的椅子讓給我們。","fellow 此處為口語的人、傢伙，非同事專稱。"]],"l2-0351":[["形容詞：女性的","無直接同義詞","The school invited a female scientist to speak about her research.","學校邀請了一位女科學家談她的研究。","feminine 指女性化的特質，不等於 female 的性別義。"]],"l2-0352":[["名詞：圍欄","無直接同義詞","We built a fence to keep the rabbits out of the garden.","我們蓋了一道圍欄，防止兔子跑進花園。",""]],"l2-0353":[["名詞：節慶","celebration","The spring festival fills the streets with music and dancing.","春季慶典讓街道上充滿音樂和舞蹈。",""]],"l2-0354":[["名詞：發燒","high temperature","She stayed home from school because she had a fever.","她因為發燒，留在家裡沒有上學。",""]],"l2-0355":[["名詞：田野","無直接同義詞","We crossed a field of tall grass on our way to the river.","我們前往河邊時，穿過了一片長滿高草的田野。",""]],"l2-0356":[["名詞：奮鬥者；鬥士","campaigner","She was a tireless fighter for better working conditions in factories.","她為了改善工廠工作環境而奮鬥不懈。",""]],"l2-0357":[["名詞：身形","physique / build","The photograph showed his tall, athletic figure standing beside the boat.","照片中，他身形高大健壯，站在船旁。",""]],"l2-0358":[["名詞：電影","movie / motion picture","The film follows a young girl's journey across the mountains.","這部電影描寫一名小女孩翻越群山的旅程。",""]],"l2-0359":[["名詞：消防員","firefighter","The fireman carried the frightened dog out of the burning house.","消防員把受驚的狗抱出失火的房屋。","firefighter 不限定性別；fireman 指男性消防員。"]],"l2-0360":[["形容詞：牢固的","secure / solid","Make sure the ladder has a firm base before climbing.","爬上梯子前，先確認梯子底部支撐穩固。",""]],"l2-0361":[["名詞：漁夫","fisher","The fisherman repaired his net while waiting for the tide to change.","漁夫一邊等待潮汐轉變，一邊修補漁網。","fisher 是不限定性別的稱呼。"]],"l2-0362":[["動詞：合身","無直接同義詞","These gloves fit my hands perfectly and keep them warm.","這副手套非常合我的手，也很保暖。","fit 指尺寸合適；suit 偏重款式等適合。"]],"l2-0363":[["動詞：修理","repair / mend","Can you fix the loose handle on this kitchen drawer?","你能修理這個廚房抽屜鬆掉的把手嗎？",""]],"l2-0364":[["名詞：旗幟","banner","A colorful flag flew above the entrance to the campsite.","營地入口上方飄揚著一面彩色旗幟。","banner 常指有標語或圖案的旗幟、布條。"]],"l2-0365":[["動詞：閃爍","blink / flicker","The red light flashed to warn us that the battery was low.","紅燈閃爍，提醒我們電池電量不足。",""]],"l2-0366":[["名詞：手電筒","torch","She used a flashlight to look for her keys under the car.","她用手電筒尋找掉在車底的鑰匙。","torch 為英式用法；一般手電筒不用原稿併列的 flash 稱呼。https://dictionary.cambridge.org/dictionary/english/flashlight"]],"l2-0367":[["形容詞：平坦的","level / even","Choose a flat piece of ground before setting up the tent.","搭帳篷前，先選一塊平坦的地面。",""]],"l2-0368":[["名詞：航程","air journey","Our flight to the island took less than an hour.","我們飛往那座島的航程不到一小時。",""]],"l2-0369":[["名詞：洪水","inundation","The flood left thick mud on the floors of several houses.","洪水在好幾間房屋的地板上留下了厚厚的泥巴。",""]],"l2-0370":[["名詞：麵粉","無直接同義詞","Dust the table with flour before rolling out the dough.","擀麵團前，先在桌上撒些麵粉。",""]],"l2-0371":[["動詞：流動","run / stream","Rainwater flowed down the steps and into the street.","雨水順著階梯流到街上。",""]],"l2-0372":[["名詞：流行性感冒","influenza","Three people in our office were absent with the flu.","我們辦公室有三個人因流感而缺勤。",""]],"l2-0373":[["名詞：長笛","無直接同義詞","Her flute could be heard clearly above the other instruments.","在其他樂器聲中，仍能清楚聽到她的長笛聲。",""]],"l2-0374":[["名詞：重點","center of attention","The main focus of today's meeting is the new bus route.","今天會議的主要重點是新的公車路線。",""]],"l2-0375":[["形容詞：有霧的","misty","The road was foggy, so we drove slowly with our lights on.","路上有霧，所以我們開著車燈慢慢行駛。","misty 的霧通常比 foggy 薄。"]],"l2-0376":[["形容詞：接下來的","next / subsequent","We arrived on Sunday and visited the museum the following morning.","我們星期天抵達，隔天早上參觀了博物館。",""]],"l2-0377":[["名詞：傻瓜","idiot","I felt like a fool when I realized I had brought the wrong key.","發現帶錯鑰匙時，我覺得自己像個傻瓜。","fool 和 idiot 用來罵別人時具有侮辱性。"]],"l2-0378":[["形容詞：愚蠢的","silly / unwise","It would be foolish to swim here when the waves are so high.","浪這麼高，還在這裡游泳就太不明智了。",""]],"l2-0379":[["名詞：足球（英式）","soccer","We played football in the park using bags as goalposts.","我們在公園踢足球，用袋子當球門柱。","英式 football 通常指足球；美式 football 通常指美式足球。"]],"l2-0380":[["名詞：外國人","foreign national","As a foreigner, he needed extra documents to open a bank account.","他身為外國人，開銀行帳戶時需要額外文件。",""]],"l2-0381":[["動詞：原諒","pardon / excuse","She forgave her friend for forgetting to return the book.","她原諒了朋友忘記還書這件事。","forgive someone for doing something。"]],"l2-0382":[["名詞：形狀","shape","The sculpture has the form of a bird with open wings.","那座雕塑呈現一隻鳥展翅的形狀。",""]],"l2-0383":[["形容詞：正式的","official","We received a formal invitation to the opening ceremony.","我們收到了開幕典禮的正式邀請。",""]],"l2-0384":[["形容詞：以前的","previous / past","Our former neighbor moved back to town last month.","我們以前的鄰居上個月搬回鎮上了。",""]],"l2-0385":[["副詞：向前","ahead / onward","Please move forward so more passengers can get on the bus.","請往前移，讓更多乘客能上公車。",""]],"l2-0386":[["副詞：向前","ahead / onward","The boat moved slowly forwards as we pulled on the ropes.","我們拉動繩索時，船慢慢往前移動。","forward 與 forwards 都可作方向副詞。"]],"l2-0387":[["名詞：狐狸","無直接同義詞","A fox slipped through the fence and vanished into the woods.","一隻狐狸鑽過圍欄，消失在樹林裡。",""]],"l2-0388":[["形容詞：坦率的","candid / honest","Please give me your frank opinion of the first draft.","請坦率地告訴我你對初稿的看法。",""]],"l2-0389":[["名詞：自由","liberty","The course gives students the freedom to choose their own projects.","這門課讓學生能自由選擇自己的專題。",""]],"l2-0390":[["名詞：冷凍櫃","deep freeze","Put the ice cream in the freezer before it melts.","趁冰淇淋還沒融化，先放進冷凍櫃裡。","freezer 冷凍食物；refrigerator 的冷藏空間溫度較高。"]],"l2-0391":[["形容詞：友善的","welcoming / amiable","The friendly shop owner gave us directions to the nearest station.","友善的店主告訴我們最近的車站怎麼走。",""]],"l2-0392":[["名詞：驚嚇","scare / shock","The sudden crash gave me such a fright that I dropped my cup.","突如其來的巨響嚇得我連杯子都掉了。",""]],"l2-0393":[["動詞：使害怕","scare / alarm","The loud thunder frightened the dog, which hid under the bed.","巨大的雷聲嚇到了狗，牠躲進床底下。",""]],"l2-0394":[["名詞：功能","purpose / role","The main function of this button is to stop the machine.","這個按鈕的主要功能是停止機器。",""]],"l2-0395":[["副詞：更遠地","farther","We walked a little further and found a place to rest.","我們再往前走了一小段，找到一個休息的地方。",""]],"l2-0396":[["名詞：未來","time ahead","She is saving money because she wants to travel in the future.","她正在存錢，因為她將來想去旅行。",""]],"l2-0397":[["動詞：獲得","obtain / acquire","He gained valuable experience while working at the small repair shop.","他在那間小修理店工作時獲得了寶貴的經驗。",""]],"l2-0398":[["名詞：車庫","無直接同義詞","We moved the bicycles into the garage before the storm arrived.","暴風雨來臨前，我們把自行車搬進車庫。",""]],"l2-0399":[["名詞：垃圾","trash / rubbish","Tie the garbage bag tightly before putting it outside.","把垃圾袋綁緊，再拿到外面。",""]],"l2-0400":[["名詞：園丁","無直接同義詞","The gardener pruned the roses to help them grow well.","園丁修剪玫瑰，幫助它們長得更好。",""]],"l2-0401":[["名詞：大門","無直接同義詞","Please close the gate so the dog cannot run into the road.","請關好大門，免得狗跑到馬路上。","gate 在本句指可開關的門；gateway 通常指大門所在的出入口，不能直接替換。"]],"l2-0402":[["動詞：收集","collect / assemble","Gather the empty cups and put them on the tray.","把空杯子收集起來，放到托盤上。",""]],"l2-0403":[["名詞：將軍","無直接同義詞","The general ordered the soldiers to protect the village.","將軍命令士兵保護村莊。",""]],"l2-0404":[["形容詞：慷慨的","giving / charitable","A generous neighbor paid for the children's new football uniforms.","一位慷慨的鄰居出錢為孩子們買了新的足球隊服。",""]],"l2-0405":[["形容詞：溫柔的","mild / tender","Her gentle voice helped the nervous child feel safe.","她溫柔的聲音讓緊張的孩子感到安心。",""]],"l2-0406":[["名詞：有禮貌的男士","無直接同義詞","The gentleman offered his seat to a passenger carrying a baby.","那位有禮貌的男士把座位讓給抱著嬰兒的乘客。",""]],"l2-0407":[["名詞：地理學","無直接同義詞","In geography class, we learned why rivers often bend.","地理課上，我們學到了河流為什麼常常彎曲。",""]],"l2-0408":[["名詞：巨人","無直接同義詞","In the story, a giant lifted the entire house with one hand.","故事裡，一個巨人用單手舉起了整棟房子。",""]],"l2-0409":[["名詞：長頸鹿","無直接同義詞","The giraffe stretched its neck to reach the highest leaves.","長頸鹿伸長脖子，去吃最高處的葉子。",""]],"l2-0410":[["名詞：手套","無直接同義詞","Wear thick gloves when you carry the rough wooden boards.","搬運粗糙的木板時，要戴厚手套。",""]],"l2-0411":[["名詞：膠水","adhesive","Let the glue dry before you move the paper model.","先等膠水乾了，再移動紙模型。",""]],"l2-0412":[["名詞：目標","aim / objective","Our goal is to plant a hundred trees this spring.","我們的目標是今年春天種一百棵樹。",""]],"l2-0413":[["名詞：山羊","無直接同義詞","The goat climbed onto a rock beside the fence.","山羊爬上了圍欄旁的一塊岩石。",""]],"l2-0414":[["形容詞：金色的","gold-colored","Golden light filled the room just before sunset.","日落前，金色的光線灑滿了房間。",""]],"l2-0415":[["名詞：高爾夫球運動","無直接同義詞","She learned to play golf at a course near her home.","她在住家附近的球場學打高爾夫球。",""]],"l2-0416":[["動詞：治理","rule / administer","The new council promised to govern the town fairly.","新議會承諾公平治理這個城鎮。",""]],"l2-0417":[["名詞：政府","administration","The government announced plans to build more public housing.","政府宣布了興建更多公共住宅的計畫。",""]],"l2-0418":[["動詞：評分","mark / assess","The teacher graded our essays and returned them on Monday.","老師批改了我們的作文，星期一發還。",""]],"l2-0419":[["名詞：葡萄","無直接同義詞","Wash the grapes and remove them from the stems.","把葡萄洗乾淨，從梗上摘下來。",""]],"l2-0420":[["形容詞：長草的","grass-covered","We spread our picnic blanket on a grassy slope.","我們把野餐墊鋪在長滿草的斜坡上。",""]],"l2-0421":[["形容詞：貪吃的","gluttonous","The greedy dog ate its own dinner and then stole the cat's.","那隻貪吃的狗吃完自己的晚餐，又偷吃貓的晚餐。",""]],"l2-0422":[["動詞：迎接；問候","welcome / say hello to","The receptionist greeted us with a smile when we arrived.","我們抵達時，接待員微笑著迎接我們。",""]],"l2-0423":[["名詞：生長","development","Warm weather encouraged the rapid growth of the young plants.","溫暖的天氣促進了幼苗快速生長。",""]],"l2-0424":[["動詞：守衛","protect / watch over","Two officers guarded the entrance throughout the night.","兩名警員整夜守著入口。",""]],"l2-0425":[["名詞：芭樂","無直接同義詞","She cut a ripe guava into slices for us to share.","她把一顆成熟的芭樂切片，讓大家分著吃。",""]],"l2-0426":[["名詞：吉他","無直接同義詞","He played the guitar while his friends sang around the campfire.","他彈吉他，朋友們則圍著營火唱歌。",""]],"l2-0427":[["名詞：傢伙；男子","fellow / man","The guy in the blue jacket helped me carry my bags.","穿藍色夾克的那名男子幫我提袋子。","guy 較口語。"]],"l2-0428":[["名詞：習慣","routine / practice","She has a habit of checking her bag before leaving home.","她有出門前檢查包包的習慣。",""]],"l2-0429":[["名詞：大廳","lobby","Guests waited in the hall while staff prepared the dining room.","客人在大廳等候，工作人員則準備餐廳。",""]],"l2-0430":[["名詞：漢堡","burger / hamburger","I ordered a hamburger with cheese and extra onions.","我點了一個加起司和額外洋蔥的漢堡。","burger 是 hamburger 的縮稱，也可指其他餡料的漢堡。"]],"l2-0431":[["名詞：鐵鎚","無直接同義詞","Use a hammer to drive the nail into the wood.","用鐵鎚把釘子敲進木頭裡。",""]],"l2-0432":[["名詞：手帕","hanky","Grandpa took a clean handkerchief out of his pocket.","爺爺從口袋裡拿出一條乾淨的手帕。","hanky 較口語。"]],"l2-0433":[["名詞：把手","grip","The handle on my suitcase broke at the airport.","我的行李箱把手在機場斷掉了。",""]],"l2-0434":[["形容詞：英俊的","good-looking / attractive","The handsome actor smiled as he signed his fans' posters.","那位英俊的演員微笑著在影迷的海報上簽名。",""]],"l2-0435":[["動詞：懸掛","suspend","Hang the wet towels outside so they can dry.","把濕毛巾掛到外面，讓它們晾乾。",""]],"l2-0436":[["名詞：衣架","coat hanger","Put the jacket on a hanger to keep it from wrinkling.","把外套掛在衣架上，避免起皺。",""]],"l2-0437":[["副詞：幾乎不","barely / scarcely","I could hardly hear her over the noise of the traffic.","車流太吵，我幾乎聽不見她說話。",""]],"l2-0438":[["形容詞：充滿惡意的","spiteful / malicious","The hateful message upset her, so she reported it.","那則充滿惡意的訊息讓她很難過，所以她提出了檢舉。",""]],"l2-0439":[["形容詞：健康的","well / fit","The rescued puppy is now healthy and full of energy.","獲救的小狗現在很健康，也充滿活力。",""]],"l2-0440":[["名詞：暖氣機","無直接同義詞","We turned on the heater when the room became cold.","房間變冷時，我們打開了暖氣機。",""]],"l2-0441":[["名詞：高度","無直接同義詞","Measure the shelf's height before buying boxes to fit underneath.","買要放在架子下面的箱子前，先量架子的高度。",""]],"l2-0442":[["形容詞：有幫助的","useful / beneficial","The map was helpful when we explored the old town.","我們探索老城區時，那張地圖很有幫助。",""]],"l2-0443":[["名詞：母雞","無直接同義詞","The hen sat quietly on her eggs in the nest.","母雞安靜地坐在巢裡孵蛋。",""]],"l2-0444":[["名詞：英雄","無直接同義詞","The town called him a hero after he rescued two children.","他救了兩名孩子後，鎮上的人稱他為英雄。","原稿詞性欄漏填；原文的 n 表示名詞。"]],"l2-0445":[["名詞：女主角","female protagonist","The heroine of the novel travels alone across the desert.","小說的女主角獨自穿越沙漠。","heroine 也指女英雄；本句示範故事女主角義。"],["名詞：女英雄","hero","The villagers called her a heroine for saving the children from the flood.","她從洪水中救出孩子們，村民稱她為女英雄。","hero 在現代也可不分性別；heroine 明確指女性。"]],"l2-0446":[["動詞：藏起","conceal","She hid the birthday present behind the books on the shelf.","她把生日禮物藏在架上的書後面。",""]],"l2-0447":[["名詞：公路","main road","We left the highway and followed a narrow road to the farm.","我們離開公路，沿著一條窄路前往農場。",""]],"l2-0448":[["名詞：髖部","無直接同義詞","She rested one hand on her hip while waiting.","她等候時，一隻手叉在腰側。","hip 指軀幹側面髖部，不完全等於 buttocks（臀部）。"]],"l2-0449":[["名詞：河馬","hippo / hippopotamus","The hippopotamus opened its huge mouth beside the river.","那隻河馬在河邊張開了大嘴。","hippo 為常用縮稱。"]],"l2-0450":[["動詞：僱用","employ / take on","The restaurant hired two cooks before the busy summer season.","餐廳在忙碌的夏季來臨前僱用了兩名廚師。",""]],"l2-0451":[["名詞：嗜好","pastime","Making small wooden toys became his favorite hobby after retirement.","退休後，製作小木玩具成了他最喜歡的嗜好。",""]],"l2-0452":[["名詞：持有者","possessor","The ticket holder must show identification at the entrance.","持票人必須在入口出示身分證明。","本句指持有票券的人；possessor 較正式，持有不一定代表擁有所有權。"]],"l2-0453":[["形容詞：想家的","無直接同義詞","She felt homesick during her first week at boarding school.","她在寄宿學校的第一週感到很想家。",""]],"l2-0454":[["形容詞：誠實的","truthful","Be honest with me about what happened to the window.","請誠實告訴我，窗戶究竟發生了什麼事。",""]],"l2-0455":[["名詞：蜂蜜","無直接同義詞","He added a spoonful of honey to his warm tea.","他在溫茶裡加了一匙蜂蜜。",""]],"l2-0456":[["動詞：單腳跳","無直接同義詞","She hopped on one foot while trying to remove her boot.","她一邊單腳跳，一邊試著脫下靴子。",""]],"l2-0457":[["名詞：醫院","無直接同義詞","The ambulance took the injured cyclist to the nearest hospital.","救護車把受傷的自行車騎士送到最近的醫院。",""]],"l2-0458":[["名詞：主人","無直接同義詞","Our host served homemade soup and made us feel welcome.","主人端上自製的湯，讓我們感到很受歡迎。","host 可不限定性別；hostess 指女主人。"]],"l2-0459":[["名詞：旅館","inn","The hotel stored our luggage while we explored the city.","我們遊覽城市時，旅館替我們保管行李。","inn 通常規模較小，也可能供應餐飲。"]],"l2-0460":[["副詞：然而","nevertheless / yet","The train was crowded; however, we managed to find two seats.","火車很擁擠；然而，我們還是找到了兩個座位。",""]],"l2-0461":[["動詞：發嗡嗡聲","buzz / drone","The refrigerator hummed softly in the quiet kitchen.","冰箱在安靜的廚房裡輕輕嗡嗡作響。",""]],"l2-0462":[["形容詞：謙遜的","modest / unassuming","Despite winning several awards, she remained humble about her work.","儘管贏得好幾個獎項，她對自己的作品仍很謙虛。",""]],"l2-0463":[["形容詞：潮濕的","muggy / moist","The air was so humid that our clothes dried slowly.","空氣很潮濕，衣服乾得很慢。","muggy 常同時帶有悶熱、不舒服的感覺。"]],"l2-0464":[["名詞：幽默","wit","His gentle humor helped everyone relax before the interview.","他溫和的幽默讓大家在面試前放鬆下來。","wit 常強調機智的言語。"]],"l2-0465":[["名詞：飢餓","無直接同義詞","By noon, hunger made it hard for me to concentrate.","到了中午，飢餓讓我難以專心。",""]],"l2-0466":[["動詞：獵捕","pursue","The owl hunts small animals in the fields at night.","那隻貓頭鷹晚上在田野獵捕小動物。","pursue 偏重追逐，不一定為捕食。"]],"l2-0467":[["名詞：獵人","huntsman","The hunter followed fresh tracks through the snowy forest with his dog.","獵人帶著他的狗，循著新留下的足跡穿過覆雪的森林。","huntsman 通常指男性獵人。"]],"l2-0468":[["動詞：趕忙","rush / hasten","We hurried to the platform when we heard the train arriving.","聽到火車進站時，我們趕忙前往月臺。",""]],"l2-0469":[["動詞：不理會","disregard / pay no attention to","He ignored the warning signs and walked onto the closed bridge.","他無視警告標誌，走上了封閉的橋。",""]],"l2-0470":[["形容詞：生病的","sick / unwell","She felt ill and asked to leave work early.","她覺得不舒服，要求提早下班。",""]],"l2-0471":[["動詞：想像","picture / envision","Imagine living in a house with no electricity or running water.","想像住在一間沒有電或自來水的房子裡。",""]],"l2-0472":[["名詞：重要性","significance","The coach stressed the importance of resting between training sessions.","教練強調訓練之間休息的重要性。",""]],"l2-0473":[["動詞：改善","better / enhance","Regular practice helped her improve her pronunciation and speaking speed.","規律練習幫助她改善發音和說話速度。","原卡合併 improve 與名詞 improvement。"]],"l2-0474":[["動詞：包含","cover","The price includes breakfast and a bus ride to the airport.","價格包含早餐以及前往機場的巴士車程。","價格 cover 某項服務表示費用已包含該項服務。"]],"l2-0475":[["名詞：收入","earnings","She uses part of her monthly income to support her parents.","她用每月收入的一部分供養父母。",""]],"l2-0476":[["動詞：增加","raise / boost","The shop increased its prices when the cost of flour rose.","麵粉成本上漲時，店家調高了售價。",""]],"l2-0477":[["名詞：獨立自主","self-reliance / autonomy","Learning to cook gave him greater independence from his parents.","學會烹飪讓他更能獨立生活，減少依賴父母。",""]],"l2-0478":[["形容詞：獨立自主的","self-reliant / autonomous","Her parents encouraged her to become an independent adult.","她的父母鼓勵她成為能獨立自主的成年人。",""]],"l2-0479":[["動詞：表示","show / signal","The flashing light indicates that the machine needs more paper.","閃爍的燈表示機器需要補紙。",""]],"l2-0480":[["名詞：產業","sector / trade","The fishing industry provides jobs for many families in this town.","漁業為這個鎮上的許多家庭提供工作。",""]],"l2-0481":[["動詞：影響","affect / shape","Her teacher's advice influenced her decision to study engineering.","老師的建議影響了她選擇攻讀工程的決定。",""]],"l2-0482":[["名詞：墨水","無直接同義詞","The printer ran out of ink halfway through the report.","報告印到一半時，印表機沒墨水了。",""]],"l2-0483":[["名詞：昆蟲","bug","A tiny insect landed on the edge of my cup.","一隻小昆蟲停在我的杯緣上。","bug 為口語近義詞，也可能泛指其他小蟲。"]],"l2-0484":[["動詞：堅持要求","demand","The guide insisted that everyone stay on the marked path.","導遊堅持要求大家走在有標示的步道上。",""]],"l2-0485":[["名詞：例子","example / case","This is one instance of how teamwork can save time.","這是團隊合作能節省時間的一個例子。",""]],"l2-0486":[["形容詞：立即的","immediate","The new ticket machine gives an instant refund for canceled tickets.","新的售票機會立即退還取消的票款。",""]],"l2-0487":[["名詞：樂器","musical instrument","Each child chose an instrument to play in the school band.","每個孩子都選了一種要在學校樂團裡演奏的樂器。",""]],"l2-0488":[["形容詞：國際的","multinational","The city hosted an international conference on ocean pollution.","這座城市舉辦了一場海洋污染國際會議。","此處指涉及多國的會議；multinational 也常用於形容跨國企業。"]],"l2-0489":[["動詞：訪問","question","The reporter interviewed local farmers about the lack of rain.","記者訪問當地農民，了解雨量不足的情況。","question 偏重提問；interview 通常有正式訪談目的。"]],"l2-0490":[["動詞：介紹認識","無直接同義詞","Let me introduce you to the artist who painted this mural.","讓我介紹你認識畫這幅壁畫的藝術家。",""]],"l2-0491":[["動詞：發明","devise / create","She invented a simple tool to help open tight jar lids.","她發明了一個簡單工具，幫助打開很緊的罐子蓋。",""]],"l2-0492":[["名詞：邀請","invite","We received an invitation to our neighbor's wedding next month.","我們收到鄰居的邀請，參加下個月的婚禮。","invite 作名詞為口語。"]],"l2-0493":[["動詞：邀請","ask","They invited us to join their family dinner on Sunday.","他們邀請我們參加星期日的家庭晚餐。",""]],"l2-0494":[["名詞：島嶼","isle","A small boat takes visitors to the island twice a day.","每天有兩班小船載訪客前往那座島。","isle 較偏文學或地名用法。"]],"l2-0495":[["名詞：品項","article","The cashier scanned each item before placing it in a bag.","收銀員逐一掃描每件商品，再放進袋子裡。",""]],"l2-0496":[["名詞：夾克","無直接同義詞","He zipped up his jacket as the evening grew colder.","傍晚天氣漸冷，他拉上了夾克拉鍊。",""]],"l2-0497":[["動詞：卡住","stick / become stuck","The printer jammed when two sheets of paper went in together.","兩張紙一起進入印表機，導致機器卡紙。",""]],"l2-0498":[["名詞：爵士樂","無直接同義詞","A small band played jazz in the café on Friday nights.","每到星期五晚上，一個小樂團就在咖啡館演奏爵士樂。",""]],"l2-0499":[["名詞：牛仔褲","blue jeans / denims","After she fell off her bike, her blue jeans had a hole in one knee.","她騎自行車摔倒後，藍色牛仔褲的一邊膝蓋破了個洞。",""]],"l2-0500":[["名詞：吉普車","無直接同義詞","The jeep climbed the rough track leading to the mountain cabin.","吉普車沿著崎嶇山路爬升，前往山中小屋。","Jeep 也用作品牌名；不把所有越野車當作精確同義詞。"]],"l2-0501":[["動詞：慢跑","trot","She jogs around the lake before breakfast every morning.","她每天早飯前都繞著湖慢跑。","trot 偏重小步跑動，jog 常作為運動。"]],"l2-0502":[["名詞：關節","無直接同義詞","My knee joint felt stiff after the long bus ride.","搭了很久的公車後，我的膝關節覺得僵硬。",""]],"l2-0503":[["名詞：法官","無直接同義詞","The judge listened carefully to both sides before making a decision.","法官仔細聽完雙方的說法後，才作出裁決。",""]],"l2-0504":[["形容詞：多汁的","succulent","The peaches were ripe and juicy, perfect for eating fresh.","桃子成熟又多汁，很適合直接吃。",""]],"l2-0505":[["名詞：番茄醬","catsup / ketchup","He dipped each hot french fry into the ketchup.","他把每根熱薯條都沾上番茄醬。","catsup 是 ketchup 的較少見變體拼法。"]],"l2-0506":[["名詞：幼兒園","無直接同義詞","My daughter made her first close friend at kindergarten.","我女兒在幼兒園交到了第一位好朋友。","不同地區的 kindergarten 學制不同；preschool 不一定完全相同。"]],"l2-0507":[["名詞：王國","realm","The old map shows the kingdom surrounded by mountains.","古地圖上，這個王國四周環山。",""]],"l2-0508":[["動詞：敲","rap / tap","Please knock on the door before entering the office.","進辦公室前，請先敲門。",""],["動詞：撞到","bump / bang","I knocked my knee against the table while standing up.","我站起來時，膝蓋撞到了桌子。",""]],"l2-0509":[["名詞：知識","understanding","His knowledge of local plants helped us identify the berries.","他對當地植物的了解，幫助我們辨識了那些莓果。",""]],"l2-0510":[["名詞：無尾熊","無直接同義詞","The koala rested in a tree after eating some leaves.","無尾熊吃了一些葉子後，在樹上休息。",""]],"l2-0511":[["名詞：瓢蟲","ladybird / ladybug","A ladybug crawled across the leaf and spread its wings.","一隻瓢蟲爬過葉片，展開了翅膀。","ladybird 為英式；ladybug 為美式。"]],"l2-0512":[["名詞：小路","alley / narrow road","A narrow lane leads from the church to the river.","一條狹窄的小路從教堂通往河邊。","alley 通常位於建築物之間。"]],"l2-0513":[["名詞：語言","tongue","The tour guide spoke our language, so we understood her easily.","導遊說我們的語言，所以我們很容易聽懂她。","tongue 作語言義較正式或文學化。"]],"l2-0514":[["名詞：燈籠","無直接同義詞","Red lanterns hung above the entrance to the temple.","廟宇入口上方掛著紅燈籠。",""]],"l2-0515":[["動詞：使邊緣重疊","overlap","Lap the edges of the fabric before sewing them together.","先讓布料邊緣重疊，再把它們縫在一起。","此為原稿重疊義，日常較常用 overlap。https://www.merriam-webster.com/dictionary/lap"]],"l2-0516":[["形容詞：最新的","newest / most recent","The library has the latest book by my favorite author.","圖書館有我最喜歡的作家最新出版的書。",""]],"l2-0517":[["名詞：律師","attorney","Her lawyer helped her understand the terms of the contract.","她的律師幫助她理解合約條款。","attorney 尤常用於美式英語。"]],"l2-0518":[["名詞：領導","guidance / direction","Under her leadership, the team completed the project ahead of schedule.","在她的領導下，團隊提前完成了專案。",""]],"l2-0519":[["形容詞：法律方面的","無直接同義詞","We asked for legal advice before signing the agreement.","簽署協議前，我們先尋求法律意見。","lawful 表示合法的，不適用於本句法律方面的義項。"]],"l2-0520":[["名詞：檸檬","無直接同義詞","Squeeze half a lemon over the grilled fish before serving.","上桌前，在烤魚上擠半顆檸檬汁。",""]],"l2-0521":[["名詞：檸檬飲料","無直接同義詞","We made lemonade with fresh lemons, sugar, and cold water.","我們用新鮮檸檬、糖和冷水製作檸檬水。",""]],"l2-0522":[["動詞：借出","loan","Could you lend me your bicycle for the afternoon?","你能把自行車借我用一個下午嗎？","lend 是借出，borrow 是借入。"]],"l2-0523":[["名詞：長度","無直接同義詞","Measure the table's length before buying a new tablecloth.","買新桌布前，先量桌子的長度。",""]],"l2-0524":[["名詞：豹","無直接同義詞","The leopard rested on a thick branch above the path.","豹趴在步道上方的一根粗樹枝上休息。",""]],"l2-0525":[["名詞：萵苣","無直接同義詞","Dry the lettuce leaves before putting them in the salad bowl.","把萵苣葉擦乾，再放進沙拉碗裡。",""]],"l2-0526":[["名詞：圖書館","無直接同義詞","The public library stays open late on Wednesday evenings.","公共圖書館星期三晚上開放到較晚的時間。",""]],"l2-0527":[["動詞：舔","lap up","The puppy licked the spilled milk from the kitchen floor.","小狗把廚房地板上灑出的牛奶舔掉了。","lap up 指舔飲液體；lick 的使用範圍較廣。"]],"l2-0528":[["名詞：蓋子","cover / top","Keep the lid on the pot while the rice cooks.","煮飯時要把鍋蓋蓋著。",""]],"l2-0529":[["名詞：閃電","無直接同義詞","A flash of lightning lit up the dark sky.","一道閃電照亮了黑暗的天空。",""]],"l2-0530":[["名詞：上限","maximum / ceiling","There is a limit of six people in each group.","每一組最多六個人。",""]],"l2-0531":[["動詞：連接","connect / join","A wooden bridge links the two sides of the park.","一座木橋連接公園的兩側。",""]],"l2-0532":[["名詞：液體","fluid","Pour the liquid through a strainer to remove the seeds.","把液體倒入濾網過濾，去除種子。","fluid 在科學上也可包括氣體。"]],"l2-0533":[["名詞：傾聽者","無直接同義詞","A good listener lets others finish before offering advice.","好的傾聽者會讓別人說完，再提供建議。",""]],"l2-0534":[["名詞：一條麵包","無直接同義詞","I bought a fresh loaf from the bakery this morning.","我今天早上在麵包店買了一條新鮮麵包。",""]],"l2-0535":[["形容詞：當地的","nearby / neighborhood","The local market sells fruit grown on nearby farms.","當地市場販售附近農場種的水果。",""]],"l2-0536":[["動詞：找出位置","find / pinpoint","We used the map to locate the nearest water fountain.","我們用地圖找出最近的飲水機位置。",""]],"l2-0537":[["動詞：上鎖","secure","Lock the back door before you leave the house.","離開房子前，先把後門鎖好。",""]],"l2-0538":[["名詞：原木；木柴","無直接同義詞","He added another log to keep the fire burning.","他又加了一塊木柴，讓火繼續燒。",""]],"l2-0539":[["形容詞：孤單一個的","solitary / single","A lone cyclist rode through the empty square at dawn.","黎明時，一名騎士獨自騎車穿過空蕩的廣場。","lone 指單獨存在，不一定有孤寂情緒。"]],"l2-0540":[["形容詞：寂寞的","lonesome","She felt lonely after her best friend moved away.","最好的朋友搬走後，她感到很寂寞。",""]],"l2-0541":[["動詞：遺失","misplace","I lost my wallet somewhere between the station and home.","我在車站到家之間的某個地方弄丟了錢包。","misplace 常指一時放錯地方找不到。"]],"l2-0542":[["名詞：輸家","defeated player","The loser shook the winner's hand after the chess match.","西洋棋比賽後，輸家與贏家握手。",""]],"l2-0543":[["名詞：遺失","無直接同義詞","Report the loss of your passport to the nearest police station.","護照遺失時，請到最近的警察局報案。",""]],"l2-0544":[["形容詞：迷人的","beautiful / charming","The cottage has a lovely garden filled with white roses.","那間小屋有一座美麗的花園，種滿白玫瑰。",""]],"l2-0545":[["名詞：戀人","sweetheart / romantic partner","She kept every letter her lover sent from abroad.","她保存了戀人從國外寄來的每一封信。",""]],"l2-0546":[["形容詞：較低的","無直接同義詞","Keep the heavy books on the lower shelf for safety.","為了安全，把重的書放在較低的架子上。",""]],"l2-0547":[["名詞：運氣","fortune / chance","With a little luck, we will reach home before the rain starts.","運氣好一點的話，我們就能在下雨前到家。",""]],"l2-0548":[["名詞：雜誌","periodical","She reads a travel magazine while waiting for the dentist.","她等候牙醫看診時，讀著一本旅遊雜誌。","periodical 為較正式的定期刊物稱呼。"]],"l2-0549":[["名詞：魔法","sorcery","In the tale, the princess uses magic to open the hidden door.","故事裡，公主用魔法打開了隱藏的門。","sorcery 常用於故事中的魔法，可能帶有較陰暗的語感。"]],"l2-0550":[["名詞：魔術師","conjurer / illusionist","The magician made a coin disappear from his open hand.","魔術師讓一枚硬幣從攤開的手中消失。",""]],"l2-0551":[["形容詞：主要的","chief / primary","The main reason for the delay was a broken engine.","延誤的主要原因是引擎故障。",""]],"l2-0552":[["動詞：保持","keep / preserve","Regular cleaning helps maintain the quality of the equipment.","定期清潔有助於維持設備的品質。",""]],"l2-0553":[["形容詞：雄性的","無直接同義詞","The male bird has brighter feathers than the female.","雄鳥的羽毛比雌鳥鮮豔。","本句指特定觀察對象，不表示所有鳥類都如此。"],["形容詞：男性的","無直接同義詞","Two male nurses helped move the patient into his bed.","兩名男性護理師協助把病人移到床上。","masculine 表示男性化的特質，不等於 male 的性別義。"]],"l2-0554":[["名詞：華語","Mandarin Chinese","She practices Mandarin with her classmates during lunch breaks.","她在午休時和同學練習華語。",""]],"l2-0555":[["名詞：芒果","無直接同義詞","We blended a ripe mango with yogurt for breakfast.","我們把成熟芒果和優格打在一起，當作早餐。",""]],"l2-0556":[["名詞：方式","way / method","Please handle these old books in a careful manner.","請小心翻拿這些舊書。",""]],"l2-0557":[["動詞：標示","label / indicate","Mark the correct route on the map with a red pen.","用紅筆在地圖上標示正確路線。",""]],"l2-0558":[["名詞：婚姻","matrimony","They celebrated twenty years of marriage with a family dinner.","他們以家庭聚餐慶祝結婚二十週年。","matrimony 較正式。"]],"l2-0559":[["名詞：面具","無直接同義詞","The dancer wore a painted mask during the performance.","舞者在表演時戴著彩繪面具。",""]],"l2-0560":[["名詞：一大堆","heap / mound","A mass of old clothes covered the floor beside the bed.","床邊的地板上堆滿了舊衣服。",""]],"l2-0561":[["名詞：墊子","無直接同義詞","Wipe your shoes on the mat before entering the house.","進屋前，先在墊子上擦鞋。",""]],"l2-0562":[["動詞：與……顏色相同","be the same color as","Your blue scarf matches the color of your jacket.","你的藍色圍巾和外套顏色相同。","本句強調顏色相同，可改寫為 Your blue scarf is the same color as your jacket；complement 只表示搭配得宜。"]],"l2-0563":[["名詞：朋友；伙伴","friend / companion","He brought a mate from work to our barbecue.","他帶了一位工作上的朋友來參加我們的烤肉聚會。","mate 作朋友為英式、澳式等口語用法。"]],"l2-0564":[["名詞：材料","無直接同義詞","We need stronger material to repair the tent's torn roof.","我們需要更牢固的材料來修補帳篷破掉的頂部。",""]],"l2-0565":[["名詞：一餐","無直接同義詞","We shared a simple meal of rice, vegetables, and fish.","我們一起吃了一餐簡單的飯菜，有米飯、蔬菜和魚。",""]],"l2-0566":[["名詞：意思","sense / significance","The meaning of this word changes when it is used as a verb.","這個字當動詞使用時，意思會改變。",""]],"l2-0567":[["名詞：方法；手段","method / way","The bus is our only means of reaching the village.","公車是我們前往村莊的唯一交通方式。","means 的單複數形式相同。"]],"l2-0568":[["形容詞：可衡量的","quantifiable","The new lights produced a measurable reduction in electricity use.","新的燈具讓用電量有了可以衡量的下降。",""]],"l2-0569":[["動詞：測量","gauge","Measure the window carefully before ordering the curtains.","訂購窗簾前，先仔細測量窗戶。","原卡合併 measure 與名詞 measurement。"]],"l2-0570":[["名詞：藥物","medication / drug","Keep the medicine in its original bottle with the label attached.","把藥留在原本的瓶子裡，保留瓶身標籤。",""]],"l2-0571":[["名詞：會議","conference / discussion","The meeting ended with an agreement to repair the playground.","會議最後達成了修繕遊樂場的共識。",""]],"l2-0572":[["名詞：旋律","tune","I recognized the melody but could not remember the song's name.","我認得這段旋律，卻想不起歌名。",""]],"l2-0573":[["名詞：瓜","無直接同義詞","She cut the melon in half and removed the seeds.","她把瓜切成兩半，挖掉種子。",""]],"l2-0574":[["名詞：成員","無直接同義詞","Each team member is responsible for one part of the presentation.","每位團隊成員負責簡報的一個部分。",""]],"l2-0575":[["名詞：記憶力","recall","Her excellent memory helps her remember every customer's name.","她出色的記憶力讓她記得每位顧客的名字。",""]],"l2-0576":[["名詞：菜單","無直接同義詞","The waiter brought a menu and explained the daily specials.","服務生拿來菜單，介紹了當日特餐。",""]],"l2-0577":[["名詞：留言","voicemail message","Leave a message on my voicemail if I cannot answer the phone.","如果我無法接電話，請在我的語音信箱留言。","本句明確指電話語音留言；message 本身也可指文字等其他形式的訊息。"]],"l2-0578":[["名詞：金屬","無直接同義詞","The metal spoon felt cold against my fingers.","金屬湯匙碰到手指時，感覺冰冰的。",""]],"l2-0579":[["名詞：計量器","無直接同義詞","The water meter showed unusually high use this month.","水表顯示這個月的用水量異常高。","本句的 water meter 量測用水量；gauge 常量測壓力、液位等，不能直接替換。"]],"l2-0580":[["名詞：方法","way / technique","This method of folding shirts saves space in the suitcase.","這種摺襯衫的方法能節省行李箱空間。",""]],"l2-0581":[["形容詞：軍事的","無直接同義詞","The old military base is now a public park.","那座舊軍事基地現在是一座公園。","原稿 n 與軍事的釋義不符；此義為形容詞。https://dictionary.cambridge.org/dictionary/english/military"]],"l2-0582":[["數詞：一百萬","無直接同義詞","The charity raised a million dollars to rebuild the school.","慈善團體募得一百萬元，用來重建學校。","a million 即 1,000,000。"]],"l2-0583":[["名詞：礦場","無直接同義詞","The old coal mine closed when the village lost its railway.","村莊不再有鐵路運輸後，那座老煤礦便關閉了。",""]],"l2-0584":[["介系詞：減去","less","The teacher asked us to calculate twelve minus five.","老師要我們算出十二減五的答案。",""]],"l2-0585":[["名詞：鏡子","looking glass","She checked her hair in the mirror before the interview.","面試前，她照鏡子檢查頭髮。","looking glass 為舊式用語。"]],"l2-0586":[["動詞：混合","blend / combine","Mix the flour and water until a soft dough forms.","把麵粉和水混合，直到形成柔軟的麵團。",""]],"l2-0587":[["名詞：縮尺模型","miniature / scale model","The architect showed us a small scale model of the new library.","建築師給我們看了新圖書館的小型縮尺模型。","本句明確指縮小的模型；model 也可指等比例大小的模型或其他義項。"]],"l2-0588":[["形容詞：現代的","contemporary / present-day","The museum combines a modern glass entrance with an old stone building.","博物館把現代的玻璃入口和古老石造建築結合在一起。",""]],"l2-0589":[["名詞：怪物","無直接同義詞","The child dreamed of a friendly monster living under his bed.","那個孩子夢見一隻友善的怪物住在他的床底下。",""]],"l2-0590":[["名詞：蚊子","無直接同義詞","A mosquito kept buzzing near my ear while I tried to sleep.","我試著入睡時，一隻蚊子不停在耳邊嗡嗡叫。",""]],"l2-0591":[["名詞：蛾","無直接同義詞","A brown moth flew around the lamp on the porch.","一隻褐色的蛾繞著門廊上的燈飛。",""]],"l2-0592":[["名詞：動作；手勢","gesture / movement","With a quick motion of her hand, she signaled us to stop.","她快速做了個手勢，示意我們停下。",""]],"l2-0593":[["名詞：機車","motorbike","He parked his motorcycle beside the entrance to the shop.","他把機車停在商店入口旁。",""]],"l2-0594":[["形容詞：可移動的","mobile","The classroom has movable walls that create smaller work spaces.","教室有可移動的隔牆，能隔出較小的工作空間。",""]],"l2-0595":[["名詞：捷運系統","metro / rapid transit system","We took the MRT to the museum to avoid traffic.","我們搭捷運去博物館，避開塞車。","MRT 為 mass rapid transit 縮寫；路線可在地下或高架。"]],"l2-0596":[["名詞：騾子","無直接同義詞","The mule carried our bags along the narrow mountain trail.","騾子沿著狹窄山徑馱運我們的行李。",""]],"l2-0597":[["動詞：乘","無直接同義詞","Multiply the number of tables by six to calculate the chairs needed.","把桌數乘以六，算出需要的椅子數量。","multiply A by B，將 A 乘以 B；本句假設每桌六張椅子。"]],"l2-0598":[["名詞：博物館","無直接同義詞","The museum displays tools used by farmers a century ago.","博物館展示一百年前農民使用的工具。",""]],"l2-0599":[["名詞：器樂演奏家","instrumentalist","The musician practiced her violin for hours before her first public performance.","那位音樂家在第一次公開演出前練了好幾個小時的小提琴。","instrumentalist 專指器樂演奏者；musician 也可包括歌手及作曲家。"]],"l2-0600":[["名詞：釘子","無直接同義詞","He pulled the rusty nail out of the wooden fence.","他把生鏽的釘子從木圍欄裡拔出來。",""]],"l2-0601":[["形容詞：裸身的","nude / unclothed","He wrapped a towel around his naked body after his shower.","洗完澡後，他用毛巾裹住裸身。",""]],"l2-0602":[["名詞：餐巾","serviette","She placed a folded napkin beside each dinner plate.","她在每個餐盤旁放了一條摺好的餐巾。","serviette 常見於英式英語。"]],"l2-0603":[["形容詞：狹窄的","constricted","The narrow passage allowed only one person through at a time.","那條狹窄通道一次只能讓一個人通過。",""]],"l2-0604":[["形容詞：全國性的","nationwide","The national competition attracted young musicians from every region.","這場全國比賽吸引了各地的年輕音樂家。",""]],"l2-0605":[["形容詞：天然的","naturally occurring","The cave provides a natural shelter from the wind.","洞穴提供了天然的避風處。",""]],"l2-0606":[["形容詞：頑皮的","mischievous / badly behaved","The naughty puppy chewed a hole in my favorite slipper.","那隻頑皮的小狗把我最喜歡的拖鞋咬出一個洞。",""]],"l2-0607":[["形容詞：附近的","neighboring / local","We bought fresh bread from a nearby shop.","我們在附近的商店買了新鮮麵包。",""]],"l2-0608":[["副詞：幾乎","almost","The bottle is nearly empty, so we need more water.","瓶子幾乎空了，所以我們需要更多水。",""]],"l2-0609":[["形容詞：整齊的","tidy / orderly","She keeps her tools in neat rows inside the drawer.","她把工具整齊地排在抽屜裡。",""]],"l2-0610":[["形容詞：必要的","essential / required","A ticket is necessary to enter the concert hall.","進入音樂廳必須有票。",""]],"l2-0611":[["名詞：項鍊","無直接同義詞","The necklace has a small silver star hanging from it.","這條項鍊上掛著一顆小銀星。",""]],"l2-0612":[["名詞：縫衣針","無直接同義詞","She threaded the needle and repaired the torn pocket.","她穿好針線，補好了破掉的口袋。",""]],"l2-0613":[["形容詞：否定的","unfavorable","We received a negative response to our request for more time.","我們要求延長時間，卻得到否定的答覆。",""]],"l2-0614":[["名詞：鄰居","無直接同義詞","Our neighbor waters our plants whenever we go away.","每次我們外出，鄰居都會替我們澆植物。",""]],"l2-0615":[["限定詞：兩者都不","not either","Neither restaurant was open when we arrived at ten.","我們十點抵達時，兩間餐廳都沒開。","neither 後接單數名詞；not either 需調整句法。"]],"l2-0616":[["名詞：姪子；外甥","無直接同義詞","My nephew sent me a drawing for my birthday.","我姪子在我生日時寄了一幅畫給我。","英文不區分兄弟或姊妹的兒子。"]],"l2-0617":[["名詞：鳥巢","無直接同義詞","The robin built a nest in the tree outside our window.","那隻知更鳥在我們窗外的樹上築巢。",""]],"l2-0618":[["名詞：網子","無直接同義詞","The fisherman lowered his net into the quiet water.","漁夫把網子放進平靜的水裡。",""]],"l2-0619":[["名詞：姪女；外甥女","無直接同義詞","My niece is learning to bake bread with her grandmother.","我外甥女正在跟她奶奶學烤麵包。","英文不區分兄弟或姊妹的女兒；grandmother 也不區分奶奶、外婆。"]],"l2-0620":[["代名詞：沒有人","no one / not anybody","Nobody knew who had left the flowers outside the door.","沒有人知道是誰把花放在門外。","no one 可直接替換 nobody；not anybody 需調整句型，例如 There wasn't anybody who knew。"]],"l2-0621":[["動詞：點頭","無直接同義詞","She nodded when I asked if she wanted more tea.","我問她是否還要茶時，她點了點頭。",""]],"l2-0622":[["代名詞：一個也沒有","not any","None of the keys in this drawer opens the gate.","這個抽屜裡沒有一把鑰匙能開大門。",""]],"l2-0623":[["名詞：麵條","無直接同義詞","The noodles became soft after a few minutes in boiling water.","麵條放進滾水幾分鐘後就變軟了。",""]],"l2-0624":[["形容詞：北部的","無直接同義詞","The northern coast is colder and windier than the southern coast.","北岸比南岸更冷，風也更大。",""]],"l2-0625":[["名詞：筆記本","notepad","He wrote the address in a notebook he carried everywhere.","他把地址寫在隨身攜帶的筆記本裡。",""]],"l2-0626":[["形容詞：新穎的","new / original / innovative","Her novel idea turned old umbrellas into colorful shopping bags.","她的新穎點子把舊雨傘變成了彩色購物袋。",""]],"l2-0627":[["名詞：堅果","無直接同義詞","The squirrel buried a nut beneath a pile of leaves.","松鼠把一顆堅果埋在一堆樹葉下。",""]],"l2-0628":[["動詞：遵守","follow / comply with","All visitors must obey the rules inside the animal park.","所有訪客都必須遵守動物園內的規定。",""]],"l2-0629":[["名詞：物體","thing / item","A shiny object lay half buried in the sand.","一個閃亮的物體半埋在沙裡。",""]],"l2-0630":[["動詞：發生","happen / take place","The accident occurred near the station during the evening rush hour.","事故發生在傍晚尖峰時段，地點在車站附近。",""]],"l2-0631":[["動詞：主動提供","provide / give","The hotel offers a free breakfast to all guests.","飯店提供所有房客免費早餐。",""]],"l2-0632":[["形容詞：官方的","authorized","The official website lists the documents needed for the application.","官方網站列出了申請所需的文件。","official 表示具有官方身分；authorized 強調獲得授權，本句可作近義理解。"]],"l2-0633":[["動詞：省略","leave out / exclude","You can omit the chili if you prefer a milder soup.","如果喜歡清淡不辣的湯，可以不加辣椒。",""]],"l2-0634":[["名詞：洋蔥","無直接同義詞","Fry the onion slowly until it becomes soft and golden.","慢慢炒洋蔥，直到變軟並呈金黃色。",""]],"l2-0635":[["動詞：營運","run / manage","The family operates a small hotel beside the lake.","這家人在湖邊經營一間小旅館。",""]],"l2-0636":[["名詞：意見","view / judgment","In my opinion, the shorter route is safer after dark.","依我看，天黑後走較短的路線比較安全。",""]],"l2-0637":[["形容詞：普通的","usual / normal","The box looked ordinary, but it contained a rare painting.","盒子看起來很普通，裡面卻裝著一幅珍貴的畫。",""]],"l2-0638":[["名詞：器官","無直接同義詞","The model shows where each major organ sits inside the body.","模型顯示身體內各個主要器官的位置。",""]],"l2-0639":[["名詞：組織；機構","association / body","The organization provides free meals for older people living alone.","這個機構為獨居長者提供免費餐點。",""]],"l2-0640":[["動詞：籌辦","arrange / coordinate","The students organized a concert to support the local animal shelter.","學生們籌辦了一場音樂會，支持當地動物收容所。",""]],"l2-0641":[["名詞：烤箱","無直接同義詞","The oven is large enough to bake two cakes at once.","這台烤箱夠大，可以同時烤兩個蛋糕。",""]],"l2-0642":[["名詞：跨線橋；高架橋","flyover","The bus crossed the overpass above the busy highway.","公車駛過橫跨繁忙公路的高架橋。","原稿把名詞釋為越過不準確；overpass 的常見名詞義為跨線橋。https://dictionary.cambridge.org/dictionary/english/overpass"]],"l2-0643":[["副詞：在海外","abroad","Her older brother works overseas and visits the family each winter.","她哥哥在海外工作，每年冬天回來探望家人。",""]],"l2-0644":[["名詞：貓頭鷹","無直接同義詞","We heard an owl calling from the trees after sunset.","日落後，我們聽見樹林裡傳來貓頭鷹的叫聲。",""]],"l2-0645":[["名詞：所有者","無直接同義詞","The owner of the lost bag returned to collect it.","遺失包包的主人回來領取了。","owner 指所有權人；possessor 只表示持有者，proprietor 常指商家或企業業主。"]],"l2-0646":[["名詞：役牛","bullock","The ox pulled a heavy cart along the muddy road.","那頭役牛沿著泥濘的道路拉著重車。","ox 常指用於農務、通常已閹割的公牛，不能全面等同 bull。https://dictionary.cambridge.org/dictionary/english/ox"]],"l2-0647":[["動詞：裝箱打包","box up","Pack the glasses carefully in sturdy boxes before the move.","搬家前，把玻璃杯仔細裝進堅固的箱子裡。","本句明確指裝箱，可用 box up；pack 也可指裝袋或整理行李。"]],"l2-0648":[["名詞：包裹","parcel","The courier left my package with a neighbor while I was out.","我外出時，快遞員把我的包裹交給鄰居代收。",""]],"l2-0649":[["名詞：疼痛","ache / soreness","The pain in my shoulder made carrying the bag difficult.","肩膀的疼痛讓我很難提袋子。",""]],"l2-0650":[["形容詞：疼痛的","sore / aching","His ankle was still painful the morning after the match.","比賽隔天早上，他的腳踝仍然疼痛。",""]],"l2-0651":[["名詞：畫家","無直接同義詞","The painter mixed several colors to capture the evening sky.","畫家混合了好幾種顏色，描繪傍晚的天空。",""]],"l2-0652":[["名詞：畫作","無直接同義詞","The painting above the sofa shows a quiet harbor.","沙發上方的畫描繪了一座寧靜的港口。","painting 使用顏料；drawing 通常使用鉛筆、墨筆等。"]],"l2-0653":[["名詞：睡衣褲","pyjamas","He changed into his pajamas after brushing his teeth.","他刷完牙後換上睡衣褲。","pyjamas 為英式拼法。"]],"l2-0654":[["名詞：手掌","無直接同義詞","She held the tiny shell in the palm of her hand.","她把那個小貝殼放在手掌心。",""]],"l2-0655":[["名詞：平底鍋","frying pan / skillet","The chef flipped the omelet in a nonstick pan without breaking it.","主廚用不沾平底鍋翻動蛋捲，沒有把它弄破。","pan 是用於爐上煎煮食物的平底容器。"]],"l2-0656":[["名詞：貓熊","giant panda","The panda sat beside a tree and chewed bamboo.","那隻貓熊坐在樹旁咀嚼竹子。",""]],"l2-0657":[["名詞：木瓜","pawpaw","She removed the black seeds from the ripe papaya.","她把成熟木瓜裡的黑色種子挖掉。","pawpaw 在某些地區指木瓜，但也指另一種北美水果。"]],"l2-0658":[["動詞：原諒","forgive / excuse","Please pardon my late reply; I was away last week.","請原諒我這麼晚回覆；我上週外出了。",""]],"l2-0659":[["名詞：鸚鵡","無直接同義詞","The parrot repeated the greeting it heard every morning.","鸚鵡重複說著牠每天早上聽到的問候語。",""]],"l2-0660":[["形容詞：特定的","specific / certain","Is there a particular seat you would like to reserve?","你有想預訂哪個特定座位嗎？",""]],"l2-0661":[["名詞：搭檔","無直接同義詞","My dance partner and I practiced the final turn together.","我的舞伴和我一起練習最後的轉身動作。","本句 partner 指一起跳舞的搭檔；teammate 指隊友，companion 指陪伴者，均不完全相同。"]],"l2-0662":[["名詞：乘客","無直接同義詞","Each passenger must keep the aisle clear during the journey.","每位乘客在旅途中都必須保持走道暢通。","traveler 範圍較廣；passenger 不包括駕駛及工作人員。"]],"l2-0663":[["動詞：黏貼","glue / stick","Paste the photos onto the card, leaving room for a message.","把照片貼在卡片上，留些空間寫字。",""]],"l2-0664":[["動詞：輕拍","tap","She patted his shoulder to let him know she was there.","她輕拍他的肩膀，讓他知道她在那裡。",""]],"l2-0665":[["名詞：小徑","trail / track","The path winds through the woods and ends beside a waterfall.","小徑蜿蜒穿過樹林，盡頭在瀑布旁。",""]],"l2-0666":[["形容詞：有耐心的","tolerant / forbearing","The patient teacher explained the steps again without getting upset.","那位有耐心的老師沒有生氣，又解釋了一次步驟。",""]],"l2-0667":[["名詞：圖案","design / motif","The plate has a pattern of blue flowers around its edge.","盤子的邊緣有一圈藍色花朵圖案。",""]],"l2-0668":[["名詞：和平","無直接同義詞","After years of war, both sides agreed to work toward peace.","經過多年戰爭，雙方同意努力促成和平。",""]],"l2-0669":[["形容詞：平靜的","calm / tranquil","We enjoyed a peaceful afternoon reading beside the river.","我們在河邊閱讀，度過了一個寧靜的下午。",""]],"l2-0670":[["名詞：桃子","無直接同義詞","The peach was so ripe that juice ran down my hand.","那顆桃子熟透了，果汁順著我的手流下來。",""]],"l2-0671":[["名詞：花生","groundnut","The vendor roasted peanuts in a large metal pan.","攤販用一個大金屬鍋炒花生。",""]],"l2-0672":[["名詞：梨；西洋梨","無直接同義詞","Leave the pear on the counter until it softens.","把西洋梨放在檯面上，等它變軟。","pear 泛指梨；本句以放軟後食用的西洋梨為情境，不表示所有梨都須等到變軟。"]],"l2-0673":[["名詞：企鵝","無直接同義詞","The penguin slipped into the water and swam quickly away.","企鵝滑進水裡，迅速游走了。",""]],"l2-0674":[["名詞：胡椒粉","ground pepper","Add a little pepper to the soup before tasting it again.","在湯裡加一點胡椒粉，再嚐一次味道。",""]],"l2-0675":[["介系詞：每","for each","The room costs eighty dollars per night, including breakfast.","這間房每晚八十元，含早餐。",""]],"l2-0676":[["形容詞：完美的","flawless / faultless","Her performance was perfect, with every note clear and steady.","她的演出很完美，每個音都清晰穩定。",""]],"l2-0677":[["名詞：一段時間","interval / span","The shop will close for a short period during the repairs.","店家在整修期間會短暫停業。",""],["名詞：句點","full stop","Put a period at the end of this statement.","在這個陳述句的結尾加上句點。","full stop 為英式用法。"]],"l2-0678":[["形容詞：私人的","private","Please do not read the personal letters on my desk.","請不要閱讀我桌上的私人信件。",""]],"l2-0679":[["名詞：照片","photo / picture","This photograph shows my grandparents on their wedding day.","這張照片拍的是我祖父母結婚當天的模樣。",""]],"l2-0680":[["名詞：攝影師","無直接同義詞","The photographer waited for the clouds to move before taking the picture.","攝影師等雲移開後才拍照。",""]],"l2-0681":[["名詞：片語","expression","The teacher explained a useful phrase for asking directions politely.","老師解釋了一個可以禮貌問路的實用片語。",""]],"l2-0682":[["動詞：挑選","choose / select","Pick three photos that best show what happened at the festival.","挑三張最能呈現節慶活動情況的照片。",""]],"l2-0683":[["名詞：野餐","無直接同義詞","We packed sandwiches and fruit for a picnic by the lake.","我們裝好三明治和水果，準備到湖邊野餐。",""]],"l2-0684":[["名詞：鴿子","無直接同義詞","A pigeon landed on the railing outside our kitchen window.","一隻鴿子停在廚房窗外的欄杆上。",""]],"l2-0685":[["名詞：一堆","heap / stack","A pile of dirty plates waited beside the sink.","一堆髒盤子放在水槽旁等著清洗。",""]],"l2-0686":[["名詞：枕頭","無直接同義詞","She placed an extra pillow behind her back while reading.","她閱讀時，在背後多放了一個枕頭。",""]],"l2-0687":[["名詞：大頭針","無直接同義詞","Use a pin to hold the fabric in place before sewing.","縫紉前，用大頭針把布料固定好。",""]],"l2-0688":[["名詞：鳳梨","無直接同義詞","We served fresh pineapple after the spicy main course.","吃完辛辣的主菜後，我們端上了新鮮鳳梨。",""]],"l2-0689":[["名詞：桌球","table tennis / ping-pong","We play ping-pong in the community center on rainy afternoons.","下雨的下午，我們在活動中心打桌球。",""]],"l2-0690":[["形容詞：粉紅色的","rose-colored","She chose pink curtains to match the flowers on her wallpaper.","她選了粉紅色窗簾，搭配壁紙上的花朵。",""]],"l2-0691":[["名詞：管子","tube","Water leaked from a pipe beneath the kitchen sink.","廚房水槽下的一根管子漏水了。",""]],"l2-0692":[["名詞：音高","無直接同義詞","The singer lowered the pitch so the children could sing along.","歌手降低音高，讓孩子們能跟著唱。",""]],"l2-0693":[["名詞：披薩","無直接同義詞","We shared a large pizza topped with mushrooms and cheese.","我們分吃了一個鋪滿蘑菇和起司的大披薩。",""]],"l2-0694":[["形容詞：樸素的","simple / unadorned","He wore a plain white shirt to the interview.","他穿了一件樸素的白襯衫去面試。",""]],"l2-0695":[["名詞：行星","無直接同義詞","The children built models of each planet in our solar system.","孩子們製作了太陽系各行星的模型。",""]],"l2-0696":[["名詞：盤子","dish","Put the warm bread on a plate and bring it to the table.","把溫麵包放在盤子上，端到桌邊。",""]],"l2-0697":[["名詞：平臺","raised stage","The speaker stood on a platform so everyone could see her.","講者站在平臺上，讓大家都看得見她。",""]],"l2-0698":[["形容詞：愛玩的","frisky / lively","The playful kitten chased a paper ball across the floor.","那隻愛玩的小貓在地板上追著紙球跑。",""]],"l2-0699":[["形容詞：舒適宜人的","agreeable / enjoyable","A cool breeze made the evening walk especially pleasant.","涼爽的微風讓傍晚散步格外愜意。",""]],"l2-0700":[["名詞：樂趣","enjoyment / delight","She takes great pleasure in growing vegetables for her family.","為家人種蔬菜帶給她很大的樂趣。",""]],"l2-0701":[["介系詞：加上","added to","The bill is forty dollars plus a small delivery fee.","帳單是四十元，另外加上一筆少量運費。",""]],"l2-0702":[["名詞：詩","verse","She wrote a poem about the first snowfall of winter.","她寫了一首關於冬季第一場雪的詩。","verse 也可指詩的一節或詩體文字。"]],"l2-0703":[["名詞：詩人","bard","The poet read her latest work to a small audience.","那位詩人向少數聽眾朗讀她最新的作品。","bard 是文學或古式稱呼。"]],"l2-0704":[["名詞：毒物","無直接同義詞","The bottle of poison was stored in a locked cabinet.","那瓶毒物存放在上鎖的櫃子裡。","toxin 通常指生物產生的毒素，不能概括所有 poison。"]],"l2-0705":[["名詞：政策；規定","rule / guideline","The store's return policy allows exchanges within thirty days.","這家店的退換貨規定允許三十天內換貨。",""]],"l2-0706":[["形容詞：有禮貌的","courteous / well-mannered","The polite child thanked the driver before getting off the bus.","那位有禮貌的孩子下車前向司機道謝。",""]],"l2-0707":[["形容詞：受歡迎的","well-liked","The new playground is popular with families in the neighborhood.","新的遊樂場很受附近家庭歡迎。",""]],"l2-0708":[["名詞：人口","inhabitants","The town's population grew after the railway station opened.","鐵路車站啟用後，鎮上的人口增加了。","population 可指總人口數；inhabitants 指居民，句法不同。"]],"l2-0709":[["名詞：豬肉","無直接同義詞","She cooked the pork slowly with onions and apples.","她把豬肉和洋蔥、蘋果一起慢慢烹煮。",""]],"l2-0710":[["名詞：港口","harbor / seaport","Trucks carry fresh fish from the port to markets across the city.","卡車把鮮魚從港口運往市內各處的市場。","port 強調船舶裝卸、進出的港口；harbor 偏重供船停泊的水域，兩者此處意思接近。"]],"l2-0711":[["動詞：擺姿勢","無直接同義詞","The family posed beside the lake for a photograph.","那家人在湖邊擺好姿勢拍照。",""]],"l2-0712":[["形容詞：樂觀積極的","optimistic / hopeful","Her positive attitude helped the team through a difficult week.","她樂觀的態度幫助團隊度過了艱難的一週。",""]],"l2-0713":[["名詞：可能性","chance / likelihood","There is a possibility that the concert will move indoors.","音樂會有可能改到室內舉行。",""]],"l2-0714":[["名詞：崗位","station","The guard stayed at his post until the next shift arrived.","警衛留在崗位上，直到接班的人抵達。",""]],"l2-0715":[["名詞：明信片","picture postcard","I sent my parents a postcard showing the city's old castle.","我寄給父母一張印有這座城市古堡的明信片。",""]],"l2-0716":[["名詞：茶壺","teapot","She poured hot tea from the pot into three cups.","她把茶壺裡的熱茶倒進三個杯子。","本句的 pot 指茶壺；pot 也可指鍋子等容器。"]],"l2-0717":[["名詞：馬鈴薯","spud","Bake the potato until its skin is crisp and its center is soft.","把馬鈴薯烤到外皮酥脆、裡面柔軟。","spud 為口語用法。"]],"l2-0718":[["名詞：磅","無直接同義詞","The recipe calls for one pound of chopped vegetables.","這份食譜需要一磅切好的蔬菜。",""]],"l2-0719":[["形容詞：強大的","strong / mighty","A powerful wave knocked the small boat onto the rocks.","一道強大的海浪把小船打到岩石上。",""]],"l2-0720":[["動詞：稱讚","commend / compliment","The teacher praised her for helping the new student.","老師稱讚她幫助了新同學。",""]],"l2-0721":[["動詞：祈禱","無直接同義詞","The family prayed for the safe return of the missing hikers.","那家人祈求失蹤的登山客平安歸來。",""]],"l2-0722":[["動詞：比較喜歡","favor / like better","I prefer tea to coffee, especially in the evening.","比起咖啡，我更喜歡茶，尤其是在晚上。","prefer A to B，喜歡 A 勝過 B。"]],"l2-0723":[["名詞：在場","attendance","Your presence at the meeting would help us make a decision.","你若能出席會議，將有助於我們作決定。",""]],"l2-0724":[["形容詞：在場的","in attendance","All team members were present when the coach announced the results.","教練宣布結果時，所有隊員都在場。",""],["名詞：禮物","gift","She wrapped the present in blue paper and added a ribbon.","她用藍色紙包好禮物，再加上一條緞帶。",""]],"l2-0725":[["名詞：總統","無直接同義詞","The president addressed the nation after the severe earthquake.","大地震後，總統向全國人民發表談話。",""]],"l2-0726":[["名詞：新聞界","news media","The press waited outside the courthouse for a statement.","新聞媒體在法院外等候聲明。",""]],"l2-0727":[["名詞：自豪","satisfaction","He took pride in the garden he had planted himself.","他為自己親手栽種的花園感到自豪。",""]],"l2-0728":[["名詞：王子","無直接同義詞","The prince rode through the village to greet the crowd.","王子騎馬穿過村莊，向群眾致意。",""]],"l2-0729":[["名詞：公主","無直接同義詞","The princess in the story refused to leave her injured horse.","故事裡的公主不肯丟下受傷的馬。",""]],"l2-0730":[["形容詞：主要的","main / chief / primary","The principal aim of the course is to improve speaking skills.","這門課的主要目標是提升口說能力。",""]],"l2-0731":[["名詞：原理","rule / law","The teacher used a simple experiment to explain the principle.","老師用一個簡單實驗解釋那個原理。",""]],"l2-0732":[["名詞：印表機","無直接同義詞","The printer needs more paper before it can finish the report.","印表機需要補紙，才能把報告印完。",""]],"l2-0733":[["名詞：監獄","jail","The old prison has been turned into a history museum.","那座舊監獄已改建成歷史博物館。","美式 jail 常指短期拘留或地方監所，prison 通常收容服刑者。"]],"l2-0734":[["名詞：囚犯","inmate / convict","Each convicted prisoner was allowed to borrow books from the library.","每位已定罪的囚犯都可以向圖書館借書。","convict 指已定罪者；prisoner 也可指遭拘留的人。"]],"l2-0735":[["形容詞：私人的","personal","He keeps his private papers in a locked drawer.","他把私人文件放在上鎖的抽屜裡。",""]],"l2-0736":[["名詞：獎品","award / reward","The first prize in the competition was a new bicycle.","這場比賽的首獎是一輛新自行車。",""]],"l2-0737":[["動詞：生產","make / manufacture","The factory produces wooden furniture for schools and libraries.","這間工廠為學校和圖書館製造木製家具。",""]],"l2-0738":[["名詞：生產商","manufacturer / maker","The local cheese producer sells directly to shops and restaurants.","當地的起司生產商直接供貨給商店和餐廳。",""]],"l2-0739":[["動詞：進展","advance / proceed","Work on the new bridge progressed slowly during the rainy season.","雨季期間，新橋工程進展緩慢。",""]],"l2-0740":[["名詞：專案；計畫","undertaking / scheme","Our school project involves designing a garden for butterflies.","我們的學校專題是設計一座適合蝴蝶的花園。",""]],"l2-0741":[["動詞：承諾","pledge / vow","She promised to return the tools by Friday afternoon.","她答應在星期五下午前歸還工具。",""]],"l2-0742":[["動詞：發音","say / articulate","Can you pronounce the name slowly so I can repeat it?","你能慢慢念這個名字，讓我跟著念嗎？",""]],"l2-0743":[["動詞：提議","suggest","He proposed adding more lights along the path to the station.","他提議在通往車站的小徑上加裝更多燈。","propose doing 與 suggest doing 可用於提出行動建議。"]],"l2-0744":[["動詞：保護","guard / shield","The cover protects the bicycle from rain and dust.","這個罩子保護自行車，避免淋雨和沾染灰塵。",""]],"l2-0745":[["形容詞：自豪的","pleased","Her parents were proud of the kindness she showed her classmates.","她善待同學，讓父母感到自豪。","proud of 強調自豪，比一般滿意更強；用 pleased 時須改為 pleased with。"]],"l2-0746":[["動詞：提供","supply / furnish","The tour company provides helmets for everyone joining the bike ride.","旅行社為所有參加自行車活動的人提供安全帽。",""]],"l2-0747":[["名詞：布丁","無直接同義詞","We chilled the chocolate pudding for an hour before serving it.","我們把巧克力布丁冷藏一小時後才端上桌。",""]],"l2-0748":[["動詞：打氣","inflate","He pumped air into the bicycle tire before the ride.","騎車前，他替自行車輪胎打氣。","pump air into a tire；inflate a tire，句法不同。"]],"l2-0749":[["名詞：南瓜","無直接同義詞","The soup gets its orange color from roasted pumpkin.","這道湯的橘色來自烤過的南瓜。",""]],"l2-0750":[["動詞：處罰","penalize / discipline","The coach punished the players for arriving late to practice.","教練因球員練習遲到而處罰他們。","原卡合併 punish 與名詞 punishment。"]],"l2-0751":[["名詞：學生","student / learner","The teacher gave each pupil a seed to plant.","老師給每位學生一顆種子種植。",""],["名詞：瞳孔","無直接同義詞","Her pupils became smaller when she stepped into the bright sunlight.","她走進明亮的陽光下時，瞳孔縮小了。",""]],"l2-0752":[["名詞：提線木偶","marionette","The performer moved the puppet's arms by pulling thin strings.","表演者拉動細繩，操控戲偶的手臂。","例句以細繩操控，屬於 marionette；puppet 也包含手套偶等其他戲偶。"]],"l2-0753":[["名詞：小狗","pup","The puppy fell asleep with its head on my shoe.","小狗把頭靠在我的鞋上睡著了。",""]],"l2-0754":[["名詞：小錢包","coin purse","She opened her purse and counted the coins inside.","她打開小錢包，數了數裡面的硬幣。","英式 purse 常指錢包；美式 purse 常指手提包。"]],"l2-0755":[["動詞：使困惑","baffle / confuse","The strange noise from the engine puzzled the mechanic.","引擎傳出的奇怪聲音讓技師感到困惑。",""]],"l2-0756":[["名詞：品質","standard","The bakery checks the quality of its flour every week.","麵包店每週都檢查麵粉的品質。",""]],"l2-0757":[["名詞：數量","amount","The recipe makes a large quantity of soup for freezing.","這份食譜能煮出大量的湯，方便冷凍保存。",""]],"l2-0758":[["名詞：四分之一","fourth","She ate a quarter of the pizza and saved the rest.","她吃了四分之一個披薩，把剩下的留起來。",""]],"l2-0759":[["動詞：停止；戒除","stop / give up","He quit smoking after his daughter asked him to stop.","女兒請他停止抽菸後，他就戒菸了。","quit 後可接動名詞。"]],"l2-0760":[["名詞：小考","short test","We had a short quiz on the words we learned yesterday.","我們針對昨天學的單字考了一次小考。",""]],"l2-0761":[["名詞：兔子","bunny","The rabbit nibbled a leaf and hopped under the bush.","兔子啃了一片葉子，跳到灌木叢下面。","bunny 為口語或兒童用語。"]],"l2-0762":[["形容詞：下雨的","wet","We spent the rainy afternoon playing cards inside the tent.","那個下雨的下午，我們在帳篷裡打牌。",""]],"l2-0763":[["名詞：山脈","mountain chain","A high mountain range separates the coast from the desert.","一條高聳的山脈把海岸與沙漠隔開。",""]],"l2-0764":[["形容詞：快速的","fast / swift","The rapid rise in water forced us to leave the riverbank.","水位迅速上升，迫使我們離開河岸。",""]],"l2-0765":[["形容詞：稀有的","uncommon / scarce","The garden grows a rare flower that blooms only at night.","這座花園種著一種只在夜間開花的稀有花卉。",""]],"l2-0766":[["副詞：相當","quite / fairly","The suitcase is rather heavy, so let me help you carry it.","這個行李箱相當重，讓我幫你提吧。",""]],"l2-0767":[["名詞：現實","actuality","The reality of farm life was harder than she had imagined.","農場生活的現實比她想像中辛苦。",""]],"l2-0768":[["動詞：察覺；明白","recognize / understand","I realized I had left my ticket at home.","我發現自己把車票留在家裡了。",""]],"l2-0769":[["形容詞：最近的","無直接同義詞","Recent heavy rain has made the mountain paths muddy.","最近的大雨讓山間步道變得泥濘。","recent 指不久前；latest 專指最近一次或最新的，不能泛指本句這段期間的大雨。"]],"l2-0770":[["名詞：紀錄","account / log","Keep a record of how much water the plants receive.","記錄植物澆了多少水。","原稿詞性欄漏填；本例示範名詞，重音在第一音節。"]],"l2-0771":[["名詞：長方形；矩形","無直接同義詞","Draw a rectangle around the title on the poster.","在海報的標題周圍畫一個長方形。",""]],"l2-0772":[["名詞：冰箱","fridge","The eggs are on the refrigerator shelf above the vegetable drawer.","雞蛋放在冰箱蔬菜抽屜上方的層架上。","fridge 是 refrigerator 的縮稱；icebox 原指用冰塊冷藏的箱櫃。"]],"l2-0773":[["動詞：拒絕","decline / turn down","She refused the offer because the working hours were too long.","她拒絕了那個邀約，因為工時太長。",""]],"l2-0774":[["名詞：顧慮；關心","consideration / concern","He showed little regard for other passengers by playing music loudly.","他大聲播放音樂，幾乎不顧其他乘客的感受。",""]],"l2-0775":[["名詞：地區","area / zone","This region is known for its tea farms and mountain views.","這個地區以茶園和山景聞名。",""]],"l2-0776":[["形容詞：定期的","routine / scheduled","Regular checks help keep the playground equipment safe.","定期檢查有助於維持遊樂器材的安全。",""]],"l2-0777":[["動詞：拒絕接受","refuse / turn down","The editor rejected the article because it contained several factual errors.","編輯拒絕採用這篇文章，因為裡面有好幾處事實錯誤。",""]],"l2-0778":[["名詞：關聯","connection / link","The study examined the relation between sleep and memory.","這項研究探討睡眠與記憶之間的關聯。","原稿詞性欄漏填，原文 n 表示名詞。"]],"l2-0779":[["名詞：人際關係","connection / bond","She has a close relationship with her older sister.","她和姊姊的感情很親密。",""]],"l2-0780":[["動詞：重複","say again","Please repeat the last number; I did not hear it clearly.","請再說一次最後那個號碼；我沒聽清楚。",""]],"l2-0781":[["動詞：回覆","answer / respond","He replied to my email before the end of the day.","他在當天結束前就回覆了我的電子郵件。","reply to an email；answer an email 不加 to。"]],"l2-0782":[["名詞：記者","journalist / correspondent","The reporter spoke to passengers after the train delay.","火車誤點後，記者訪問了乘客。",""]],"l2-0783":[["動詞：需要","need / call for","The recipe requires fresh herbs and a little patience.","這份食譜需要新鮮香草和一點耐心。","原卡合併 require 與名詞 requirement。"]],"l2-0784":[["動詞：尊重","esteem / admire","I respect my coach because she treats every player fairly.","我尊敬教練，因為她公平對待每位球員。",""]],"l2-0785":[["形容詞：可靠負責的","dependable / reliable","The responsible teenager always returns the borrowed tools on time.","那位負責任的青少年總是準時歸還借來的工具。",""]],"l2-0786":[["名詞：餐廳","eatery","The restaurant serves fresh seafood from the nearby harbor.","這家餐廳供應來自附近港口的新鮮海鮮。","eatery 為非正式用法。"]],"l2-0787":[["名詞：洗手間","bathroom / washroom","The restroom is at the end of the hall, on the right.","洗手間在走廊盡頭的右側。",""]],"l2-0788":[["動詞片語：導致","lead to / cause","The broken pipe resulted in water damage throughout the kitchen.","水管破裂導致整間廚房遭到水損。","本句以 result in 整個片語對應 lead to 或 cause；result from 則表示起因於。"]],"l2-0789":[["動詞：複習","revise / go over","Review your notes carefully before tomorrow's history test.","明天歷史考試前，先仔細複習筆記。","revise 作複習義常見於英式英語。"]],"l2-0790":[["複數名詞：財富","wealth / fortune","The explorer dreamed of finding riches in the distant mountains.","那位探險家夢想在遠方山區找到財寶。",""]],"l2-0791":[["動詞：搖動","sway","She rocked the baby's cradle gently until he fell asleep.","她輕輕搖動嬰兒搖籃，直到他睡著。",""]],"l2-0792":[["形容詞：多岩石的","stony","The rocky beach was difficult to cross in thin shoes.","那片多岩石的海灘，穿薄鞋很難走過去。",""]],"l2-0793":[["名詞：角色","part","She practiced her role in the play every evening.","她每天晚上都練習自己在戲裡的角色。",""]],"l2-0794":[["形容詞：王室的","無直接同義詞","Visitors can tour the royal palace on certain days.","遊客可以在特定日子參觀王宮。","royal 在本句表示隸屬王室；regal 常形容有王者氣派，不代表實際隸屬王室。"]],"l2-0795":[["形容詞：無禮的","impolite / discourteous","It is rude to interrupt someone who is still speaking.","打斷還在說話的人很沒禮貌。",""]],"l2-0796":[["名詞：統治者","sovereign / leader","The ruler ordered a bridge built across the river.","統治者下令在河上建橋。","sovereign 通常指君主；leader 是較廣泛的領導者，ruler 強調統治權。"]],"l2-0797":[["名詞：跑者","無直接同義詞","The last runner crossed the finish line to loud cheers.","最後一位跑者在熱烈歡呼中越過終點線。",""]],"l2-0798":[["動詞：急奔","hurry / dash","She rushed out of the house when she heard the alarm.","她聽到警報後，急忙跑出屋子。",""]],"l2-0799":[["名詞：安全","protection from harm","The guide checked the ropes to ensure everyone's safety.","嚮導檢查了繩索，確保每個人的安全。","此為解釋性近義片語，指免於受傷或危險；本句不能只以 security 理解為保全措施。"]],"l2-0800":[["名詞：水手","seaman / mariner","The sailor tied the boat securely to the dock.","水手把船牢牢繫在碼頭上。",""]],"l2-0801":[["名詞：沙拉","無直接同義詞","She made a salad with lettuce, tomatoes, and cucumber.","她用萵苣、番茄和小黃瓜做沙拉。",""]],"l2-0802":[["形容詞：含鹽的","saline","The salty water left white marks on the boat's wooden deck.","鹽水在船的木甲板上留下了白色痕跡。","saline 較正式，常指含鹽的水或溶液。"]],"l2-0803":[["名詞：樣本","specimen","The scientist collected a water sample from the stream.","科學家從溪流中採集了一份水樣。",""]],"l2-0804":[["名詞：三明治","無直接同義詞","I packed a cheese sandwich for the long train journey.","我帶了一個起司三明治，準備在長途火車旅程中吃。",""]],"l2-0805":[["動詞：使滿意","please / content","The simple meal was enough to satisfy the hungry travelers.","這頓簡單的飯菜足以讓飢餓的旅客感到滿足。",""]],"l2-0806":[["名詞：醬汁","無直接同義詞","Spoon the warm sauce over the pasta just before serving.","上桌前，把溫熱的醬汁舀到義大利麵上。",""]],"l2-0807":[["名詞：科學","無直接同義詞","Our science project explores how different soils affect plant growth.","我們的科學專題探討不同土壤如何影響植物生長。",""]],"l2-0808":[["名詞：科學家","無直接同義詞","The scientist spent years studying how sea turtles find their way home.","那位科學家花了多年研究海龜如何找到回家的路。",""]],"l2-0809":[["名詞：剪刀","無直接同義詞","Use sharp scissors to cut the paper along the dotted line.","用鋒利的剪刀沿著虛線剪紙。",""]],"l2-0810":[["動詞：得分","無直接同義詞","She scored the winning goal in the final minute.","她在最後一分鐘攻入了致勝的一球。",""]],"l2-0811":[["名詞：螢幕；銀幕","display","The screen showed a map of our flight over the ocean.","螢幕上顯示了我們飛越海洋的航程地圖。",""]],"l2-0812":[["動詞：搜查","look through / examine","The police searched the empty building for the missing child.","警方在空建築物裡搜尋失蹤的孩子。",""]],"l2-0813":[["形容詞：祕密的","confidential / hidden","We kept our plans for the teacher's birthday party secret.","我們對替老師舉辦慶生派對的計畫保密。",""]],"l2-0814":[["名詞：祕書","administrative assistant","The secretary arranged the meeting and sent everyone an invitation.","祕書安排了會議，並向每個人發出邀請。",""]],"l2-0815":[["名詞：部分","part / portion","Read the final section carefully before you sign the form.","簽表格前，請仔細閱讀最後一部分。",""]],"l2-0816":[["動詞：挑選","choose / pick","Select a date when everyone on the team is available.","選一個團隊裡每個人都有空的日期。",""]],"l2-0817":[["名詞：選拔","choice / choosing","The selection of team leaders took place after the interviews.","面試結束後，才進行組長的選拔。",""]],"l2-0818":[["名詞：學期","term","She is taking a photography course this semester.","她這學期修了一門攝影課。","semester 通常為一年兩學期之一；term 不限定一年分幾期。"]],"l2-0819":[["動詞：分開","divide / sort","Separate the clean towels from the ones that need washing.","把乾淨毛巾和需要清洗的毛巾分開。",""]],"l2-0820":[["形容詞：嚴重的","severe / grave","The storm caused serious damage to the fishing harbor.","暴風雨對漁港造成了嚴重損害。",""]],"l2-0821":[["名詞：僕人","domestic worker","The servant carried fresh water upstairs to the guest rooms.","僕人把乾淨的水提到樓上的客房。","servant 常見於歷史情境，現代職稱依工作可用 domestic worker。"]],"l2-0822":[["動詞：定居","make one's home","They settled in a small town after retiring from teaching.","他們從教職退休後，在一個小鎮定居。","原卡合併 settle 與名詞 settlement。"]],"l2-0823":[["動詞：共同分擔","split / divide","The four friends shared the cost of renting a car.","四位朋友分攤了租車費用。",""]],"l2-0824":[["名詞：架子；層板","無直接同義詞","The lowest shelf holds our heaviest pots and pans.","最下面的架子放著我們最重的鍋具。",""]],"l2-0825":[["名詞：殼","無直接同義詞","The turtle pulled its head back into its shell.","烏龜把頭縮回殼裡。",""]],"l2-0826":[["動詞：使震驚","stun / appall","The news of the bridge collapse shocked the whole town.","橋梁倒塌的消息震驚了整個城鎮。",""]],"l2-0827":[["動詞：射擊","fire","The coach told the archer to shoot only after the signal.","教練告訴弓箭手，只有聽到信號後才能射擊。",""]],"l2-0828":[["名詞：短褲","無直接同義詞","He wore shorts because the afternoon was warm and sunny.","他穿了短褲，因為下午溫暖又晴朗。",""]],"l2-0829":[["動詞：淋浴","take a shower","She showered after the long bicycle ride through the hills.","在山丘間長途騎車後，她洗了個澡。",""]],"l2-0830":[["名詞：蝦","prawn","The noodles came with shrimp, bean sprouts, and green onions.","那碗麵配有蝦、豆芽和蔥。","shrimp/prawn 的日常用法因地區而異，生物分類不完全相同。"]],"l2-0831":[["名詞：人行道","pavement / footpath","Keep your bicycle off the sidewalk when people are walking there.","人行道上有人行走時，請不要把自行車騎上去。","pavement 指人行道為英式用法。"]],"l2-0832":[["名詞：告示牌","notice / signboard","A sign outside the shop says it closes at six.","店外的告示牌寫著六點打烊。",""]],"l2-0833":[["名詞：寂靜","quiet / stillness","A bird's call broke the silence in the empty garden.","一聲鳥鳴打破了空蕩花園裡的寂靜。",""]],"l2-0834":[["形容詞：沉默的","quiet / wordless","He remained silent while the others discussed the problem.","其他人討論問題時，他保持沉默。",""]],"l2-0835":[["名詞：絲綢","無直接同義詞","The silk scarf felt smooth and cool against her neck.","絲巾貼著她的脖子，感覺滑順又涼爽。",""]],"l2-0836":[["形容詞：相似的","alike / comparable","The twins have similar voices, but their laughs are different.","雙胞胎的聲音相似，但笑聲不同。","alike 通常放在連綴動詞後，不能直接作 similar voices 的替換。"]],"l2-0837":[["副詞：簡明地","plainly / clearly","The guide explained the rules simply so the children could understand.","導覽員簡單說明規則，讓孩子們能聽懂。",""]],"l2-0838":[["形容詞：單一的","one / sole","A single lamp lit the small room beside the kitchen.","廚房旁的小房間裡，只有一盞燈照明。",""]],"l2-0839":[["動詞：下沉","go down / submerge","The small boat began to sink after hitting a rock.","小船撞上岩石後開始下沉。",""]],"l2-0840":[["形容詞：熟練的","proficient / expert","The skilled carpenter repaired the chair without replacing the broken leg.","那位熟練的木匠修好了椅子，沒有更換斷掉的椅腳。",""]],"l2-0841":[["形容詞：很瘦的","thin / scrawny","The skinny stray cat began to gain weight after regular meals.","那隻瘦弱的流浪貓規律進食後，開始增加體重。",""]],"l2-0842":[["名詞：裙子","無直接同義詞","Her long skirt brushed the grass as she walked.","她走路時，長裙輕拂著草地。",""]],"l2-0843":[["形容詞：想睡的","drowsy","The warm room made everyone feel sleepy after lunch.","溫暖的房間讓大家午餐後都想睡覺。",""]],"l2-0844":[["形容詞：纖細的","slim / thin","Her slender fingers moved quickly over the piano keys.","她纖細的手指在琴鍵上快速移動。",""]],"l2-0845":[["動詞：滑動","slip","Slide the box under the bed to save space.","把箱子滑推到床底下，節省空間。","slip 在此表示輕巧地放入某處；slide 更強調沿表面滑動。"]],"l2-0846":[["形容詞：苗條的","slender / lean","The slim runner wore a bright yellow racing vest.","那位身材苗條的跑者穿著鮮黃色競賽背心。",""]],"l2-0847":[["動詞：滑倒；打滑","skid","He slipped on the wet floor but caught the railing.","他在濕地板上滑了一下，幸好抓住了欄杆。","skid 常指車輪或腳失去抓地力而滑行。"]],"l2-0848":[["名詞：室內拖鞋","house shoe","She left her slippers beside the bed before going to sleep.","她睡前把拖鞋留在床邊。",""]],"l2-0849":[["名詞：點心","light bite","We stopped for a snack halfway through the hike.","健行到一半時，我們停下來吃點心。",""]],"l2-0850":[["名詞：蝸牛","無直接同義詞","A snail left a shiny trail across the garden path.","蝸牛在花園小徑上留下了一道亮亮的痕跡。",""]],"l2-0851":[["形容詞：積雪的","snow-covered","The children pulled their sleds up the snowy hill.","孩子們把雪橇拉上積雪的山丘。",""]],"l2-0852":[["名詞：足球","football","Our soccer team practices passing before every match.","我們的足球隊在每場比賽前都會練習傳球。","football 在英式英語通常指足球，美式通常指美式足球。"]],"l2-0853":[["形容詞：社會的","societal","The report examines social problems caused by a lack of housing.","報告探討了住宅短缺造成的社會問題。",""]],"l2-0854":[["名詞：社會","community","Public libraries play an important role in society.","公共圖書館在社會中扮演重要角色。","community 可指特定社群，society 常指較廣的社會整體。"]],"l2-0855":[["名詞：襪子","無直接同義詞","Pack dry socks in case your feet get wet.","帶上乾襪子，以防腳弄濕。",""]],"l2-0856":[["名詞：士兵","無直接同義詞","The soldier helped carry supplies to the flooded village.","那名士兵協助把物資搬到淹水的村莊。","service member 包含各軍種服役人員，範圍比陸軍士兵廣。"]],"l2-0857":[["名詞：解決辦法","answer / remedy","We finally found a solution to the leaking roof.","我們終於找到屋頂漏水的解決辦法。",""]],"l2-0858":[["動詞：解決","resolve / work out","The mechanic solved the problem by replacing a loose wire.","技師換掉一條鬆脫的電線，解決了問題。",""]],"l2-0859":[["代名詞：有人","someone","Somebody left an umbrella on the bus this morning.","今天早上有人把雨傘留在公車上。",""]],"l2-0860":[["副詞：某處","someplace","I left my keys somewhere in the kitchen last night.","昨晚我把鑰匙放在廚房的某個地方。",""]],"l2-0861":[["名詞：種類","kind / type","What sort of music would you like at the party?","你希望派對上播放哪一類音樂？",""]],"l2-0862":[["名詞：來源","origin","The spring is the village's main source of drinking water.","那處泉水是村莊主要的飲用水來源。",""]],"l2-0863":[["形容詞：南部的","無直接同義詞","We spent our holiday exploring the island's southern beaches.","我們假期時探索了島嶼南部的海灘。",""]],"l2-0864":[["名詞：大豆","soya bean / soybean","The farmer planted soybeans in the field beside the river.","農夫在河邊的田地裡種了大豆。",""]],"l2-0865":[["名詞：演講者","presenter / orator","The speaker used photographs to explain how the village had changed.","演講者用照片說明村莊如何改變。",""]],"l2-0866":[["名詞：速度","pace / rate","Reduce your speed when you approach the school entrance.","接近學校入口時，請減速。",""]],"l2-0867":[["名詞：拼字","orthography","Check the spelling of each name before printing the invitations.","印邀請函前，先確認每個名字的拼法。","orthography 是較專門的正字法用語。"]],"l2-0868":[["名詞：蜘蛛","無直接同義詞","A spider built its web between two branches of the tree.","一隻蜘蛛在樹的兩根枝條之間結了網。",""]],"l2-0869":[["名詞：菠菜","無直接同義詞","Stir the spinach into the hot soup until it softens.","把菠菜拌進熱湯裡，直到變軟。",""]],"l2-0870":[["名詞：心靈","soul","Listening to the waves brought peace to her troubled spirit.","聆聽海浪聲讓她煩亂的心靈平靜下來。",""]],"l2-0871":[["名詞：斑點","dot / speck","The white puppy has a brown spot above one eye.","那隻白色小狗的一隻眼睛上方有個褐色斑點。",""]],"l2-0872":[["動詞：伸展；展開","extend / unfold","The bird spread its wings and rose above the trees.","鳥展開翅膀，飛到樹梢上方。",""]],"l2-0873":[["名詞：彈簧","coil spring","The mechanic replaced the car's broken coil spring.","技師更換了汽車損壞的螺旋彈簧。","coil spring 特指螺旋彈簧；spring 也可指其他形狀的彈簧。"]],"l2-0874":[["名詞：正方形","無直接同義詞","Fold the paper into a square with four equal sides.","把紙摺成四邊等長的正方形。",""]],"l2-0875":[["名詞：松鼠","無直接同義詞","The squirrel carried an acorn up the tree trunk.","松鼠叼著一顆橡實爬上樹幹。",""]],"l2-0876":[["名詞：舞臺","無直接同義詞","The children lined up behind the stage before their performance.","孩子們在演出前到舞臺後方排隊。",""]],"l2-0877":[["名詞：郵票","postage stamp","Put a stamp on the envelope before mailing the letter.","寄信前，在信封上貼一張郵票。",""]],"l2-0878":[["名詞：標準","criterion / benchmark","All helmets must meet the same safety standard.","所有安全帽都必須符合相同的安全標準。",""]],"l2-0879":[["名詞：牛排","beef steak","He ordered a steak with potatoes and grilled vegetables.","他點了一份牛排，搭配馬鈴薯和烤蔬菜。",""]],"l2-0880":[["動詞：偷竊","swipe","Someone stole her bicycle while she was inside the library.","她在圖書館裡時，有人偷走了她的自行車。","swipe 作偷取義是非正式用法。"]],"l2-0881":[["名詞：蒸氣","water vapor","Steam rose from the pot when she lifted the lid.","她掀起鍋蓋時，蒸氣從鍋裡冒出。","steam 在日常也指熱水上方可見的水霧；嚴格說，水蒸氣本身不可見。"]],"l2-0882":[["名詞：鋼","無直接同義詞","The bridge is supported by thick steel beams.","這座橋由粗大的鋼梁支撐。",""]],"l2-0883":[["名詞：木棍","rod","He used a stick to draw a map in the sand.","他用一根木棍在沙地上畫地圖。","rod 可指木材或金屬等製成的直棒。"]],"l2-0884":[["名詞：胃","無直接同義詞","My stomach felt full after the large meal.","吃完那頓大餐後，我的胃覺得很飽。",""]],"l2-0885":[["名詞：暴風雨","tempest","The storm tore branches from trees along the coast.","暴風雨扯斷了沿海樹木的枝條。","tempest 較偏文學用語。"]],"l2-0886":[["名詞：爐子","無直接同義詞","The wood stove kept the cabin warm throughout the night.","燒木柴的爐子讓小屋整晚保持溫暖。",""]],"l2-0887":[["形容詞：直的","unbent","We need two straight metal rods to support the shelf.","我們需要兩根筆直的金屬桿來支撐層架。",""]],"l2-0888":[["名詞：陌生人","unknown person","A stranger at the station helped us find the correct platform.","車站裡一位陌生人幫我們找到正確的月臺。",""]],"l2-0889":[["名詞：稻草；乾禾稈","無直接同義詞","The farmer spread straw on the barn floor for the animals.","農夫把乾草稈鋪在穀倉地板上，供動物使用。","straw 是穀物收割後的乾莖；hay 是乾燥牧草。"]],"l2-0890":[["名詞：草莓","無直接同義詞","She placed a strawberry on top of each small cake.","她在每個小蛋糕上放了一顆草莓。",""]],"l2-0891":[["名詞：溪流","brook / creek","A clear stream runs through the woods behind our house.","一條清澈的溪流穿過我們屋後的樹林。",""]],"l2-0892":[["名詞：壓力","pressure / strain","Taking short walks helps him deal with stress at work.","短暫散步能幫助他應付工作壓力。",""]],"l2-0893":[["動詞：伸展","extend","She stretched her arms above her head after the long drive.","長途開車後，她把手臂伸到頭頂上方舒展。",""]],"l2-0894":[["形容詞：嚴格的","rigid / stringent","The school has strict rules about using phones during class.","學校對上課使用手機有嚴格的規定。","本句形容規定嚴格；rigid 另有缺乏彈性的語感，stringent 較正式。"]],"l2-0895":[["動詞：擊打","hit / smack","The ball struck the window and cracked the glass.","球打中窗戶，把玻璃撞裂了。",""]],"l2-0896":[["名詞：細繩","cord / twine","Tie the bundle with string so the papers stay together.","用細繩綁好那一捆紙，讓紙張不會散開。",""]],"l2-0897":[["動詞：努力掙扎","strive / fight","She struggled to push the heavy door open against the wind.","她逆著風，費力地試著推開沉重的門。",""]],"l2-0898":[["名詞：主題","topic / theme","The subject of today's talk is protecting local wildlife.","今天演講的主題是保護當地野生動物。",""]],"l2-0899":[["動詞：減去","take away / deduct","Subtract the cost of lunch from the money you have left.","從剩下的錢裡減掉午餐費用。","subtract A from B，從 B 減去 A。"]],"l2-0900":[["名詞：地下鐵","underground / metro","We took the subway because the roads were crowded.","因為道路擁擠，我們搭了地鐵。",""]],"l2-0901":[["動詞：成功","manage / achieve one's aim","She succeeded in growing tomatoes on her tiny balcony.","她成功地在小陽臺上種出了番茄。","succeed in doing；manage to do，句法不同。"]],"l2-0902":[["名詞：成功","achievement / accomplishment","The success of the school concert surprised everyone involved.","學校音樂會的成功讓所有參與者都感到驚喜。",""]],"l2-0903":[["形容詞：成功的","effective","The successful rescue brought all the trapped hikers home safely.","那次成功的救援讓所有受困的登山客平安返家。",""]],"l2-0904":[["形容詞：突然的","abrupt / unexpected","A sudden gust of wind blew my hat into the river.","一陣突如其來的風把我的帽子吹進河裡。",""]],"l2-0905":[["名詞：西裝套裝","無直接同義詞","He wore a dark suit to his first job interview.","他穿著深色西裝，參加第一次求職面試。",""]],"l2-0906":[["形容詞：陽光充足的","sunlit / bright","We chose a sunny spot near the window for the plants.","我們替植物選了一個靠窗、陽光充足的位置。",""]],"l2-0907":[["名詞：超級市場","無直接同義詞","The supermarket sells fresh bread near its main entrance.","超市在主要入口附近販售新鮮麵包。",""]],"l2-0908":[["動詞：供應","provide / furnish","The farm supplies fresh eggs to several local restaurants.","農場供應新鮮雞蛋給當地幾家餐廳。",""]],"l2-0909":[["動詞：支持","back / endorse","Most residents support the plan to build a new library.","多數居民支持興建新圖書館的計畫。",""]],"l2-0910":[["名詞：表面","top / tabletop","Wipe the surface of the table before putting down the plates.","放盤子前，先把桌面擦乾淨。","本句 the surface of the table 可改為 the top of the table 或 the tabletop；tabletop 指整個桌面。"]],"l2-0911":[["動詞：存活","stay alive / live through","The tree survived the storm despite losing several large branches.","那棵樹雖然斷了好幾根大樹枝，仍在暴風雨後存活下來。","survive 可直接接災難等受詞；stay alive 須改為 stayed alive during the storm，live through 可接 the storm。"]],"l2-0912":[["名詞：燕子","無直接同義詞","A swallow flew low over the field, catching insects.","一隻燕子低飛掠過田野，捕捉昆蟲。",""]],"l2-0913":[["名詞：天鵝","無直接同義詞","The white swan glided across the lake toward the reeds.","白天鵝滑行般游過湖面，朝蘆葦叢前進。",""]],"l2-0914":[["名詞：毛衣","jumper / pullover","She pulled on a thick sweater before opening the windows.","她先套上厚毛衣，再打開窗戶。","jumper 為英式；pullover 特指套頭款式。"]],"l2-0915":[["動詞：清掃","brush","Sweep the leaves off the path before the visitors arrive.","訪客抵達前，先把小徑上的落葉掃掉。",""]],"l2-0916":[["動詞：擺動","sway","The lamp swung from side to side as the boat moved.","船移動時，那盞燈左右搖擺。",""]],"l2-0917":[["名詞：象徵","emblem","The dove on the poster is a symbol of peace.","海報上的鴿子是和平的象徵。",""]],"l2-0918":[["名詞：天賦","gift / aptitude","She showed a talent for drawing when she was very young.","她很小的時候就展現了繪畫天賦。",""]],"l2-0919":[["形容詞：健談的","chatty","Our talkative guide shared stories throughout the bus ride.","健談的導遊在整段巴士車程中分享故事。",""]],"l2-0920":[["名詞：橘子","無直接同義詞","He peeled a tangerine and shared the pieces with his older sister.","他剝了一顆橘子，和姊姊分著吃。",""]],"l2-0921":[["名詞：儲水槽","reservoir","The tank behind the house stores rainwater for the garden.","屋後的水槽儲存雨水，供花園使用。","reservoir 可指蓄水池或水庫，形體不一定像 tank。"]],"l2-0922":[["名詞：膠帶","adhesive tape","Seal the cardboard box with tape before carrying it downstairs.","先用膠帶封好紙箱，再搬到樓下。",""]],"l2-0923":[["名詞：目標","goal / objective","Our target is to collect five hundred books for the school.","我們的目標是為學校募集五百本書。",""]],"l2-0924":[["名詞：任務","job / assignment","My first task was to check every window was closed.","我的第一項任務是確認每扇窗戶都已關好。",""]],"l2-0925":[["形容詞：好吃的","delicious / flavorful","The tasty soup was made with vegetables from our garden.","這道好喝的湯用的是我們花園裡的蔬菜。",""]],"l2-0926":[["名詞：隊伍","squad","The team practiced together every evening before the final match.","決賽前，整支隊伍每天晚上都一起練習。",""]],"l2-0927":[["名詞：眼淚","teardrop","A tear rolled down her cheek when she heard the good news.","她聽到好消息時，一滴眼淚滑下臉頰。",""]],"l2-0928":[["名詞：青少年","teenager","The library offers free art classes for teens on Saturdays.","圖書館星期六為青少年開設免費美術課。","teen 指十三至十九歲的人。"]],"l2-0929":[["形容詞：青少年的","adolescent","Her teenage son volunteers at the animal shelter every weekend.","她十幾歲的兒子每週末都到動物收容所當志工。","原稿 teenage 標 n 有誤；常用為形容詞，青少年時期可說 the teenage years。https://dictionary.cambridge.org/dictionary/english/teenage"]],"l2-0930":[["名詞：青少年","teen / adolescent","The teenager saved money from his summer job to buy a bicycle.","那位青少年把暑期打工的錢存下來買自行車。",""]],"l2-0931":[["名詞：電話","phone / telephone","The telephone rang just as we sat down to dinner.","我們剛坐下來吃晚餐，電話就響了。",""]],"l2-0932":[["名詞：電視機","TV / television set","They bought a smaller television for the guest room.","他們買了一台較小的電視機放在客房。",""]],"l2-0933":[["名詞：寺廟","無直接同義詞","The temple courtyard was quiet in the early morning.","清晨的廟宇庭院很安靜。",""]],"l2-0934":[["名詞：網球","無直接同義詞","She plays tennis with her older brother at the public courts.","她和哥哥在公共球場打網球。",""]],"l2-0935":[["名詞：帳篷","無直接同義詞","We put up the tent before the rain started.","我們趕在下雨前搭好了帳篷。",""]],"l2-0936":[["名詞：期限","period / duration","The lease has a term of one year.","這份租約的期限是一年。",""]],"l2-0937":[["動詞：測試","check / try out","Test the flashlight before packing it for the camping trip.","把手電筒裝進露營行李前，先測試一下。",""]],"l2-0938":[["形容詞：糟糕的","awful / dreadful","The terrible smell came from food left in the fridge.","那股難聞的氣味來自留在冰箱裡的食物。",""]],"l2-0939":[["形容詞：極好的","fantastic / excellent","You did a terrific job organizing the school concert.","你把學校音樂會安排得非常出色。",""]],"l2-0940":[["名詞：教科書","coursebook","The textbook includes clear diagrams of the human body.","這本教科書有清楚的人體圖解。",""]],"l2-0941":[["名詞：電影院","cinema / movie theater","We arrived at the theater before the film began.","電影開演前，我們就到電影院了。",""]],"l2-0942":[["副詞：因此","consequently / thus","The bridge is closed; therefore, buses must take a different route.","橋梁封閉了，因此公車必須改走另一條路線。",""]],"l2-0943":[["形容詞：厚的","無直接同義詞","A thick blanket kept the sleeping child warm.","一條厚毛毯讓熟睡的孩子保持溫暖。",""]],"l2-0944":[["名詞：小偷","無直接同義詞","The thief took a wallet from an open bag.","小偷從沒關好的包包裡偷走一個錢包。","robber 常指以威脅或暴力搶劫的人，不完全等同 thief。"]],"l2-0945":[["形容詞：細的","fine / slender","She tied the tag to the gift with a thin string.","她用細繩把標籤繫在禮物上。",""]],"l2-0946":[["形容詞：口渴的","parched","We were thirsty after walking up the hill in the sun.","在太陽下爬上山丘後，我們都很渴。","parched 表示非常口渴。"]],"l2-0947":[["名詞：喉嚨","無直接同義詞","Her throat felt sore after singing for two hours.","唱了兩小時的歌後，她覺得喉嚨痛。",""]],"l2-0948":[["介系詞：穿過","無直接同義詞","The path takes us through the forest to the lake.","這條小徑帶我們穿過森林，抵達湖邊。","through 強調從內部穿過；across 常指跨過表面或區域。"]],"l2-0949":[["介系詞：遍及","all over / across","The festival brings visitors from towns throughout the region.","這場慶典吸引了整個地區各城鎮的訪客。",""]],"l2-0950":[["名詞：拇指","無直接同義詞","He pressed the button firmly with his thumb.","他用拇指用力按下按鈕。",""]],"l2-0951":[["名詞：雷聲","無直接同義詞","A loud clap of thunder woke us during the night.","夜裡一聲巨大的雷響把我們吵醒了。",""]],"l2-0952":[["名詞：小費","gratuity","We left a tip to thank the waiter for his excellent service.","我們留下小費，感謝服務生出色的服務。","gratuity 較正式，tip 較常用於日常對話。"]],"l2-0953":[["名詞：標題","heading","Choose a short title that clearly describes your project.","選一個簡短、能清楚描述專題的標題。",""]],"l2-0954":[["動詞：舉杯祝賀","drink to","We toasted the newly married couple at the end of dinner.","晚餐結束時，我們舉杯祝賀那對新人。",""]],"l2-0955":[["名詞：腳趾","無直接同義詞","I hurt my little toe on the corner of the table.","我的小腳趾撞到桌角，弄傷了。",""]],"l2-0956":[["名詞：豆腐","bean curd / tofu","Add the tofu gently so the soft cubes stay whole.","輕輕放入豆腐，讓柔軟的方塊保持完整。",""]],"l2-0957":[["名詞：廁所","restroom / lavatory","The public toilet is beside the entrance to the park.","公共廁所在公園入口旁。",""]],"l2-0958":[["名詞：番茄","無直接同義詞","Slice the tomato and place it inside the sandwich.","把番茄切片，放進三明治裡。",""]],"l2-0959":[["名詞：舌頭","無直接同義詞","The hot soup burned the tip of my tongue.","熱湯燙到了我的舌尖。",""]],"l2-0960":[["名詞：牙齒","無直接同義詞","The child proudly showed us her first loose tooth.","那個孩子得意地給我們看她第一顆鬆動的牙齒。",""]],"l2-0961":[["名詞：主題","subject / theme","We chose ocean pollution as the topic of our presentation.","我們選擇海洋污染作為簡報的主題。",""]],"l2-0962":[["名詞：參觀行程","guided visit","The museum offers a guided tour of its oldest rooms every afternoon.","博物館每天下午都提供最古老展間的導覽。",""]],"l2-0963":[["名詞：毛巾","無直接同義詞","Dry your hands with a clean towel before handling the bread.","拿麵包前，先用乾淨毛巾把手擦乾。",""]],"l2-0964":[["名詞：塔","無直接同義詞","We climbed the tower to see the city from above.","我們爬上塔，從高處俯瞰城市。",""]],"l2-0965":[["名詞：足跡","footprint / trail","The dog's tracks led us across the snowy field.","狗的足跡引導我們穿過覆雪的田野。",""]],"l2-0966":[["名詞：貿易","commerce","The new bridge increased trade between the two towns.","新橋促進了兩個城鎮之間的貿易。",""]],"l2-0967":[["名詞：傳統","custom","Making dumplings together is a tradition in our family.","一起包餃子是我們家的傳統。",""]],"l2-0968":[["形容詞：傳統的","customary","The dancers wore traditional clothing during the village festival.","村莊慶典期間，舞者穿著傳統服飾。","traditional 強調代代相傳，customary 強調合乎當地或群體習慣。"]],"l2-0969":[["名詞：車流","無直接同義詞","Traffic was heavy near the stadium after the match.","比賽結束後，體育場附近的車流很壅塞。",""]],"l2-0970":[["名詞：陷阱","snare","The ranger freed a fox caught in an illegal wire-loop trap.","巡山員救出了困在非法鋼絲套索陷阱裡的狐狸。","本句明確是套索式陷阱，可用 snare；trap 也可指其他類型的陷阱。"]],"l2-0971":[["動詞：旅行","journey","They traveled along the coast by train during the summer.","他們夏天搭火車沿著海岸旅行。",""]],"l2-0972":[["名詞：財寶","riches / valuables","The divers found treasure inside the remains of an old ship.","潛水員在一艘老船的殘骸裡找到了財寶。",""]],"l2-0973":[["動詞：治療","care for","The nurse treated the small wound and covered it with a bandage.","護理師處理了小傷口，並用繃帶包好。","treat 表示進行治療，不保證已治癒；原卡合併 treat 與 treatment。"]],"l2-0974":[["名詞：試驗","test / tryout","The school began a trial of the new lunch menu.","學校開始試行新的午餐菜單。",""]],"l2-0975":[["名詞：三角形","無直接同義詞","Cut the sandwich into two triangles for the children.","把三明治切成兩個三角形，分給孩子們。",""]],"l2-0976":[["名詞：詭計","deception / ruse","The fake message was a trick to steal people's passwords.","那則假訊息是為了竊取密碼設下的詭計。",""]],"l2-0977":[["名詞：長褲","pants","His trousers were too long, so the tailor shortened them.","他的長褲太長，裁縫替他改短了。","pants 指長褲為美式用法；英式 pants 常指內褲。"]],"l2-0978":[["名詞：卡車","lorry","A truck delivered fresh vegetables to the market before dawn.","一輛卡車在黎明前把新鮮蔬菜送到市場。","lorry 為英式用法。"]],"l2-0979":[["名詞：小號","無直接同義詞","The trumpet player began the melody with a clear, bright note.","小號手以一個清亮的音開始演奏旋律。","此處 trumpet 指樂器小號，不是擴音喇叭。"]],"l2-0980":[["動詞：信任","rely on / have confidence in","I trust her to look after my cat while I am away.","我信任她能在我外出時照顧我的貓。",""]],"l2-0981":[["名詞：真相","facts","He finally told the truth about how the window broke.","他終於說出了窗戶破掉的真相。",""]],"l2-0982":[["名詞：管子","pipe","A narrow tube carries water from the tank to the plants.","一根細管把水從水槽輸送到植物那裡。",""]],"l2-0983":[["名詞：隧道","underground passage","The train entered a long tunnel beneath the mountain.","火車駛入山下一條長長的隧道。",""]],"l2-0984":[["名詞：火雞","無直接同義詞","A turkey walked across the farmyard, spreading its broad tail.","一隻火雞展開寬大的尾巴，走過農家庭院。",""]],"l2-0985":[["名詞：海龜","sea turtle","The turtle came ashore at night to lay its eggs.","那隻海龜夜裡上岸產卵。","本例特指海龜；turtle 也包括其他種類的龜。"]],"l2-0986":[["名詞：類型","kind / sort","What type of soil is best for growing these flowers?","哪種土壤最適合種這些花？",""]],"l2-0987":[["名詞：颱風","無直接同義詞","The typhoon brought strong winds and heavy rain to the island.","颱風為島上帶來強風和豪雨。","hurricane 等名稱依海域而異，tornado 是龍捲風，不能互換。"]],"l2-0988":[["形容詞：難看的","unattractive / unsightly","An ugly stain covered the front of the old sofa.","老沙發正面有一塊難看的污漬。",""]],"l2-0989":[["名詞：雨傘","brolly","Take an umbrella because the sky looks dark.","帶把雨傘吧，天空看起來很陰暗。","brolly 為英式口語。"]],"l2-0990":[["名詞：內衣褲","underclothes / undergarments","Pack clean underwear for each day of the trip.","替旅程的每一天準備乾淨的內衣褲。",""]],"l2-0991":[["名詞：制服","無直接同義詞","The guide's blue uniform made her easy to find in the crowd.","導覽員的藍色制服讓人很容易在人群中找到她。",""]],"l2-0992":[["介系詞：在……上","on","A small bird landed upon the wooden fence.","一隻小鳥停在木圍欄上。","upon 較正式或文學化。"]],"l2-0993":[["形容詞：上方的","higher / top","The upper shelf is too high for the children to reach.","上層架子太高，孩子們搆不到。",""]],"l2-0994":[["形容詞：二手的","secondhand / pre-owned","She bought a used bicycle and repaired it herself.","她買了一輛二手自行車，自己把它修好。",""]],"l2-0995":[["片語：過去曾經","formerly / in the past","We used to visit this beach every summer when I was young.","我小時候，我們每年夏天都會來這個海灘。","used to + 原形動詞；formerly/in the past 為近義時間表達，句法不同。"],["形容詞片語：習慣於","accustomed to","She is used to getting up early for her bakery job.","她已習慣為了麵包店的工作早起。","be used to 後接名詞或動名詞，與過去習慣 used to do 不同。"]],"l2-0996":[["名詞：使用者","無直接同義詞","Each user must create a password before accessing the website.","每位使用者都必須先建立密碼，才能進入網站。",""]],"l2-0997":[["形容詞：平常的","normal / customary","The bus arrived at its usual time this morning.","今天早上，公車在平常的時間抵達。",""]],"l2-0998":[["名詞：假期","holiday / break","We spent our vacation hiking in the mountains.","我們假期時在山裡健行。",""]],"l2-0999":[["名詞：山谷","vale","The road follows a river through a narrow valley.","道路沿著河流穿過一座狹窄的山谷。","vale 較偏文學用語。"]],"l2-1000":[["名詞：價值","worth","The watch has little monetary value but great meaning for my father.","這只手錶不值多少錢，對我父親卻很有意義。",""]],"l2-1001":[["名詞：勝利","win / triumph","The team celebrated its first victory of the season.","球隊慶祝本季的第一場勝利。",""]],"l2-1002":[["名詞：影片","video recording","She made a short video showing how to fold the paper bird.","她拍了一支短片，示範如何摺紙鳥。",""]],"l2-1003":[["名詞：村莊","無直接同義詞","The village has one school and a small medical clinic.","這個村莊有一所學校和一間小診所。",""]],"l2-1004":[["名詞：小提琴","fiddle","The violin sounded clear and warm in the small hall.","小提琴在小廳裡的聲音清晰而溫暖。","fiddle 為非正式用法，也常見於民俗音樂語境。"]],"l2-1005":[["名詞：訪客","guest","Each visitor receives a map at the museum entrance.","每位訪客都會在博物館入口拿到一張地圖。",""]],"l2-1006":[["名詞：字彙量","無直接同義詞","Reading stories helped her expand her English vocabulary.","閱讀故事幫助她增加了英語字彙量。","vocabulary 在此指一個人掌握的字彙；word knowledge 泛指對詞語的了解，不完全相同。"]],"l2-1007":[["名詞：排球","無直接同義詞","We played volleyball on the beach until sunset.","我們在海灘打排球，一直打到日落。",""]],"l2-1008":[["動詞：投票","cast a ballot","Members voted by ballot to choose the date of their next meeting.","會員透過選票決定下次會議的日期。","cast a ballot 指投選票；vote 也可指舉手等其他投票方式。"]],"l2-1009":[["名詞：選民；投票者","elector","Each voter received a ballot paper at the polling station.","每位選民都在投票所領到一張選票。",""]],"l2-1010":[["名詞：腰部","waistline","The belt was too loose around his waist.","那條腰帶繫在他的腰上太鬆了。",""]],"l2-1011":[["名詞：服務生","server","The waiter brought fresh water while we chose our meals.","我們選餐點時，服務生送來了飲用水。","server 不限定性別；waiter 通常指男性，waitress 指女性。"]],"l2-1012":[["動詞：醒來","awaken / wake up","I woke before sunrise and heard birds outside the window.","我在日出前醒來，聽見窗外有鳥叫。",""]],"l2-1013":[["名詞：皮夾","billfold","He keeps a photo of his family inside his wallet.","他把一張全家福放在皮夾裡。","billfold 常見於美式英語。"]],"l2-1014":[["名詞：瀑布","cascade","We could hear the waterfall long before we could see it.","還沒看見瀑布，我們就早已聽到水聲。",""]],"l2-1015":[["名詞：西瓜","無直接同義詞","Cold watermelon was a welcome treat after the long walk.","走了很久之後，冰西瓜是很受歡迎的點心。",""]],"l2-1016":[["名詞：海浪","無直接同義詞","A large wave washed over the rocks beside the pier.","一道大浪沖過碼頭旁的岩石。",""]],"l2-1017":[["名詞：武器","arm","The guard checked that nobody was carrying a weapon.","警衛確認沒有人攜帶武器。","arm 作武器義多用複數 arms。"]],"l2-1018":[["動詞：結婚","marry","The couple wed in a small ceremony beside the lake.","那對新人在湖邊舉行小型婚禮，結為夫妻。","wed 較正式，常用於新聞。"]],"l2-1019":[["名詞：平日","無直接同義詞","The café opens at seven on weekdays and eight on weekends.","咖啡館平日七點開門，週末八點開門。",""]],"l2-1020":[["形容詞：西部的","無直接同義詞","The western side of the island faces the setting sun.","島嶼的西側面向落日。",""]],"l2-1021":[["形容詞：濕的","damp / soaked","My shoes were wet after I walked through the long grass.","走過高草叢後，我的鞋子濕了。","damp 指微濕；soaked 指濕透。"]],"l2-1022":[["名詞：鯨魚","無直接同義詞","A whale rose to the surface near our boat.","一隻鯨魚在我們船旁浮上海面。",""]],"l2-1023":[["代名詞：任何事物","anything that","Choose whatever you would like from the breakfast menu.","早餐菜單上想吃什麼就選什麼。",""]],"l2-1024":[["名詞：輪子","無直接同義詞","The front wheel of my bicycle wobbles when I ride downhill.","我騎自行車下坡時，前輪會搖晃。",""]],"l2-1025":[["連接詞：每當","every time / each time","Whenever it rains, water collects beside the back door.","每次下雨，後門旁都會積水。",""]],"l2-1026":[["連接詞：無論哪裡","anywhere that / no matter where","Take your water bottle wherever you go during the hike.","健行時，無論走到哪裡都要帶著水瓶。",""]],"l2-1027":[["動詞：低聲說話","murmur","She whispered the answer so the baby would not wake.","她低聲回答，免得吵醒寶寶。","whisper 通常不振動聲帶；murmur 偏重輕柔低語。"]],"l2-1028":[["代名詞：無論誰","anyone who","Whoever finishes first can help the others clean their tables.","誰先完成，就可以幫其他人清理桌子。",""]],"l2-1029":[["動詞：拓寬","broaden / expand","The town plans to widen the road near the station.","鎮上計畫拓寬車站附近的道路。",""]],"l2-1030":[["名詞：寬度","breadth","Measure the doorway's width before moving the sofa inside.","把沙發搬進屋前，先量門口的寬度。",""]],"l2-1031":[["形容詞：野生的","undomesticated","Wild deer sometimes enter the garden to eat young plants.","野鹿有時會進入花園吃幼苗。",""]],"l2-1032":[["形容詞：願意的","prepared / ready","She was willing to stay late and help us finish.","她願意留下來，幫我們完成工作。",""]],"l2-1033":[["形容詞：風大的","blustery","It was too windy to eat our lunch outside.","風太大了，我們沒辦法在外面吃午餐。","blustery 常指陣陣強風；breezy 通常表示較和緩的風，不適合本句風太大的情境。"]],"l2-1034":[["名詞：翅膀","無直接同義詞","The injured bird could not lift its left wing.","那隻受傷的鳥抬不起左翅膀。",""]],"l2-1035":[["名詞：贏家","victor","The winner received a medal and thanked her coach.","獲勝者拿到獎牌後，向教練道謝。","victor 較正式；champion 通常指競賽冠軍，並非每一位 winner 都是冠軍。"]],"l2-1036":[["名詞：電線","無直接同義詞","A loose wire caused the lamp to flicker.","一條鬆脫的電線讓燈光忽明忽暗。",""]],"l2-1037":[["形容詞：明智的","sensible / prudent","Saving some money for repairs was a wise decision.","留些錢支付維修費，是個明智的決定。",""]],"l2-1038":[["介系詞：在……以內","inside","Please return the borrowed camera within three days.","請在三天內歸還借用的相機。","inside 加時間長度也可表示期限以內，此處與 within 近義。"]],"l2-1039":[["介系詞：沒有","無直接同義詞","We could not finish the project without your help.","沒有你的幫忙，我們無法完成這個專案。",""]],"l2-1040":[["名詞：狼","無直接同義詞","A wolf called from the forest as the sky grew dark.","天色漸暗時，森林裡傳來一隻狼的叫聲。",""]],"l2-1041":[["動詞：想知道","ask oneself","I wonder how the birds find their way across the ocean.","我很好奇鳥類如何找到飛越海洋的路線。",""]],"l2-1042":[["形容詞：極好的","excellent / marvelous","We had a wonderful evening sharing stories around the fire.","我們圍著火分享故事，度過了一個美好的夜晚。",""]],"l2-1043":[["形容詞：木製的","made of wood","The wooden bridge creaked as we walked across it.","我們走過木橋時，橋發出嘎吱聲。","made of wood 是解釋性片語；改寫為 the bridge made of wood 時，須放在名詞後。"]],"l2-1044":[["名詞：羊毛","無直接同義詞","This blanket is woven from wool and keeps us warm.","這條毛毯由羊毛織成，能讓我們保暖。",""]],"l2-1045":[["形容詞：值得的","worthwhile","The view from the hill is worth the long climb.","山丘上的景色值得我們辛苦爬上來。","worth 後接名詞或動名詞；worthwhile 的句法不同。"]],"l2-1046":[["名詞：割傷的傷口","cut","The nurse cleaned the shallow wound made by the broken glass.","護理師清理了碎玻璃造成的淺傷口。","本句為割傷；wound 也可指其他種類的傷口。"]],"l2-1047":[["名詞：後院","backyard","The children played in the yard behind the house.","孩子們在屋後的庭院裡玩耍。","本句明確在屋後，可用 backyard；courtyard 通常指由建築或牆圍住的院子。"]],"l2-1048":[["名詞：青春時期","younger days","He spent much of his youth helping on his grandparents' farm.","他年少時有很多時間都在祖父母的農場幫忙。",""]],"l2-1049":[["名詞：斑馬","無直接同義詞","The zebra stood beside the water while its herd grazed nearby.","那隻斑馬站在水邊，牠的同伴在附近吃草。",""]],"l3-0001":[["副詞：在交通工具上","on board","Once everyone was aboard, the captain checked the passenger list.","所有人上船後，船長核對了乘客名單。",""]],"l3-0002":[["形容詞：可接受的","satisfactory","The manager said a two-day delay would be acceptable.","經理說延遲兩天可以接受。",""]],"l3-0003":[["名詞：意外事故","mishap","A minor accident blocked the road outside our school this morning.","今天早上一場小事故堵住了學校外的道路。","mishap 通常指較輕微的不幸事故。"]],"l3-0004":[["名詞：事情的敘述","description / report","The witness gave the police a detailed account of the accident.","目擊者向警方詳細敘述了事故經過。","此處 account 指敘述，不是銀行帳戶。"]],"l3-0005":[["動詞片語：解釋原因","explain","Can you account for the missing money in the cash register?","你能解釋收銀機裡少掉的錢是怎麼回事嗎？","account for 後接需要解釋的事情。"]],"l3-0006":[["形容詞：準確的","correct / precise","Check the figures again to make sure the total is accurate.","再核對一次數字，確認總數正確。","precise 著重精確程度。"]],"l3-0007":[["名詞：持續的隱痛","pain","After carrying those heavy boxes, I felt an ache in my back.","搬完那些重箱子後，我感到背部隱隱作痛。","ache 通常指持續的鈍痛；pain 範圍較廣。"]],"l3-0008":[["及物動詞：達成","accomplish / attain","With regular practice, Maya achieved her goal of swimming one kilometer.","透過規律練習，瑪雅達成了游一公里的目標。",""]],"l3-0009":[["名詞：成就","accomplishment","Completing the mountain race was a major achievement for my father.","完成那場山地賽跑是我父親的一大成就。",""]],"l3-0010":[["名詞：活動","pursuit","Painting is a relaxing activity that we can enjoy together.","畫畫是一項我們可以一起享受的放鬆活動。","此義可數；原稿 [U] 不適用於所有義項。pursuit 較正式。"]],"l3-0011":[["形容詞：實際的","real","The actual cost of the repairs was higher than the estimate.","實際維修費用比估價還高。",""]],"l3-0012":[["形容詞：額外的","extra / further","Please contact the library if you need any additional information.","如果你需要更多資訊，請聯絡圖書館。",""]],"l3-0013":[["及物動詞：欽佩","respect / look up to","I admire how patiently our coach works with new players.","我很佩服教練對新球員那麼有耐心。","look up to 後接人，不能直接替換本句 how 子句。"]],"l3-0014":[["及物動詞：承認","acknowledge / confess","Ben admitted breaking the window while he was playing baseball.","班承認打棒球時打破了窗戶。","admit 後可接動名詞；confess 常用 confess to。"]],"l3-0015":[["及物動詞：採用","implement","The school adopted a new system for ordering lunches online.","學校採用了一套新的線上訂午餐系統。","adopt 著重決定採用；implement 著重實施。"]],"l3-0016":[["形容詞：進階的","higher-level","This advanced course requires a basic understanding of computer programming.","這門進階課程要求學員具備基本的程式設計知識。",""]],"l3-0017":[["名詞：有利條件","benefit / strength","Living near the station has the advantage of making travel easier.","住在車站附近的優點是出門搭車更方便。",""]],"l3-0018":[["名詞：冒險經歷","escapade","Our camping adventure began with a long walk through the forest.","我們的露營冒險從穿越森林的長途步行開始。","escapade 常帶刺激或不按常規行事的意味。"]],"l3-0019":[["動詞：刊登廣告宣傳","promote / publicize","The bakery advertises its weekend specials on the station noticeboard.","那家麵包店在車站公布欄上刊登週末特價廣告。",""]],"l3-0020":[["名詞：廣告","ad / advert","I saw an advertisement for guitar lessons in the local newspaper.","我在地方報紙上看到一則吉他課的廣告。","advert 主要用於英式英語。"]],"l3-0021":[["名詞：建議","guidance / counsel","My teacher gave me useful advice about preparing for the interview.","老師就面試準備給了我實用的建議。","advice 不可數，不能說 an advice。"]],"l3-0022":[["及物動詞：勸告","counsel / urge","The guide advised us to carry extra water for the hike.","導遊建議我們健行時多帶一些水。","advise someone to do something；urge 語氣較強。"]],"l3-0023":[["名詞：顧問","consultant / counselor","A careers adviser helped me compare different training programs.","一位職涯顧問協助我比較不同的培訓課程。","adviser 和 advisor 為拼字變體；counselor 常指提供指導的人。"]],"l3-0024":[["及物動詞：影響","influence","Heavy rain could affect the number of visitors at the festival.","大雨可能影響參加慶典的人數。",""]],"l3-0025":[["及物動詞：負擔得起","無直接同義詞","We cannot afford a new sofa until we finish paying for the repairs.","我們得先付完維修費，才買得起新沙發。","常搭配 can 或 cannot；afford to do 表示有能力承擔做某事。"]],"l3-0026":[["副詞：之後","later / subsequently","We watched the concert and went out for noodles afterward.","我們看完演唱會後，出去吃了麵。","afterward 和 afterwards 都可用；subsequently 較正式。"]],"l3-0027":[["名詞：農業","farming","Many families in this valley depend on agriculture for their income.","這個山谷的許多家庭靠務農維生。",""]],"l3-0028":[["名詞：冷氣機","AC unit","The air-conditioner in our classroom stopped working during the afternoon lesson.","下午上課時，我們教室的冷氣機停止運轉了。","AC 為 air conditioning 的常見縮寫。"]],"l3-0029":[["名詞：小巷","alleyway / lane","A narrow alley behind the market leads to a small temple.","市場後方一條狹窄的小巷通往一座小廟。","lane 也可指鄉間小路，範圍較廣。"]],"l3-0030":[["及物動詞：使驚奇","astonish / astound","The young pianist amazed the audience with her confident performance.","那位年輕鋼琴家的自信演出讓觀眾驚豔不已。",""]],"l3-0031":[["名詞：驚奇","astonishment / wonder","To our amazement, the tiny restaurant served the best meal of our trip.","令我們驚訝的是，那家小餐廳端出了整趟旅程最好吃的一餐。",""]],"l3-0032":[["名詞：大使","無直接同義詞","The ambassador attended a reception to celebrate the new trade agreement.","大使出席了慶祝新貿易協議的招待會。","envoy 泛指外交使節，職銜不一定是大使。"]],"l3-0033":[["名詞：抱負","aspiration / aim","Her ambition is to design affordable homes for young families.","她的志向是為年輕家庭設計負擔得起的住宅。",""]],"l3-0034":[["名詞：天使","無直接同義詞","The painting shows an angel with white wings above the sleeping child.","畫中有一位長著白色翅膀的天使，在熟睡的孩子上方。",""]],"l3-0035":[["名詞：角度","無直接同義詞","Hold the mirror at an angle so you can see behind you.","把鏡子斜著拿，這樣就能看到身後。",""]],"l3-0036":[["動詞：宣布","declare / make public","The principal announced the winners at the end of the ceremony.","校長在典禮結束時宣布了得獎者。",""]],"l3-0037":[["名詞：公告","notice / statement","An announcement on the website explains the changes to opening hours.","網站上的一則公告說明了開放時間的調整。",""]],"l3-0038":[["副詞：相隔","away from each other","Plant the young trees several meters apart to allow room for growth.","把幼樹種得相隔數公尺，讓它們有生長空間。",""]],"l3-0039":[["形容詞：明顯的","obvious / evident","It soon became apparent that the suitcase belonged to another passenger.","我們很快便發現，那個行李箱顯然屬於另一位乘客。",""]],"l3-0040":[["不及物動詞：呼籲","plead","The shelter appealed to local residents for blankets and warm clothes.","收容中心呼籲當地居民捐贈毯子和保暖衣物。","appeal to someone for something；plead 常用 plead with someone for something。"]],"l3-0041":[["及物動詞：感謝","be grateful for / value","I really appreciate the time you spent helping me move.","我非常感謝你花時間幫我搬家。",""]],"l3-0042":[["動詞：接近","near / come closer to","As we approached the village, we could hear music from the square.","我們接近村莊時，聽到廣場傳來音樂聲。",""]],"l3-0043":[["及物動詞：批准","authorize / accept","The council approved the plan to build a new public library.","議會批准了興建新公共圖書館的計畫。","approve a plan 指批准；approve of 常指贊同。"]],"l3-0044":[["名詞：水族箱","fish tank","We added a few water plants to the aquarium in the living room.","我們在客廳的水族箱裡加了幾株水草。",""]],"l3-0045":[["名詞：算術","無直接同義詞","My grandfather taught me arithmetic by letting me count coins in his shop.","祖父讓我在他的店裡數硬幣，藉此教我算術。","mathematics 是較廣的上位概念。"]],"l3-0046":[["名詞：抵達","無直接同義詞","Please send me a message on your arrival at the hotel.","你抵達飯店時，請傳個訊息給我。",""]],"l3-0047":[["名詞：灰燼","ashes","A thin layer of ash covered the floor beside the fireplace.","壁爐旁的地板上覆著薄薄一層灰。","ash 可指灰這種物質；ashes 常指燃燒後的殘餘物。"]],"l3-0048":[["副詞：往旁邊","to one side","The passengers stepped aside to let the mother push her stroller through.","乘客們往旁邊讓開，好讓那位母親推著嬰兒車通過。",""]],"l3-0049":[["及物動詞：協助","help / aid","Two volunteers assisted the elderly passengers as they left the train.","兩名志工在年長乘客下火車時協助他們。",""]],"l3-0050":[["名詞：運動員","sportsperson","Each athlete received a bottle of water after crossing the finish line.","每位運動員衝過終點線後都拿到一瓶水。",""]],"l3-0051":[["名詞：嘗試","try / effort","Her first attempt at baking bread produced a surprisingly good loaf.","她第一次嘗試烤麵包，就做出了一條出乎意料好吃的麵包。",""]],"l3-0052":[["名詞：態度","outlook","His positive attitude helped the team stay calm during the delay.","他的積極態度讓團隊在延誤期間保持冷靜。","outlook 偏指整體看法；attitude 可指面對特定事情的態度。"]],"l3-0053":[["及物動詞：吸引","draw","The garden's colorful flowers attract butterflies throughout the summer.","花園裡色彩繽紛的花朵整個夏天都吸引著蝴蝶。",""]],"l3-0054":[["形容詞：有吸引力的","appealing / inviting","The café has an attractive outdoor area beside the river.","那家咖啡館在河邊設有一處很吸引人的戶外座位區。",""]],"l3-0055":[["名詞：聽眾","listeners","The audience remained silent until the last note of the song faded.","聽眾一直靜靜聆聽，直到歌曲最後一個音消逝。","此句採聽眾義；audience 也可指觀眾或讀者。"]],"l3-0056":[["名詞：作者","writer","The author signed copies of her latest novel after the talk.","演講結束後，那位作者為她的新小說簽名。",""]],"l3-0057":[["形容詞：自動的","self-operating","The automatic doors opened as I carried the boxes into the building.","我抱著箱子走進大樓時，自動門開了。",""]],"l3-0058":[["名詞：汽車","car / auto","The museum displays an automobile that was built over a century ago.","博物館展出了一輛一百多年前製造的汽車。","automobile 在日常對話中通常用 car。"]],"l3-0059":[["形容詞：可取得的","obtainable / accessible","Free maps are available at the information desk near the entrance.","入口附近的服務台提供免費地圖。",""]],"l3-0060":[["名詞：大道","boulevard","Tall trees provide shade along the avenue leading to the university.","通往大學的大道兩旁有高大的樹木遮蔭。",""]],"l3-0061":[["名詞：平均數","mean","The average of our three test scores was eighty points.","我們三次測驗成績的平均分數是八十分。",""]],"l3-0062":[["及物動詞：喚醒","wake / awaken","A loud clap of thunder awoke the children before dawn.","黎明前，一聲巨雷把孩子們吵醒了。","awake 作動詞較書面；過去式 awoke。"]],"l3-0063":[["不及物動詞：醒來","wake up / awake","I awakened early and watched the fishing boats leave the harbor.","我一早醒來，看著漁船駛離港口。","awaken 比 wake up 正式。"]],"l3-0064":[["及物動詞：頒給","grant / present","The judges awarded first prize to a photograph of the old market.","評審把首獎頒給了一張老市場的照片。","present 常用 present someone with something。"]],"l3-0065":[["形容詞：察覺的","conscious","We were not aware of the leak until water reached the kitchen.","直到水流到廚房，我們才察覺有漏水。","aware of；conscious of。"]],"l3-0066":[["形容詞：糟糕的","terrible / dreadful","The weather was awful, so we held the picnic indoors.","天氣很糟，所以我們改在室內野餐。",""]],"l3-0067":[["名詞：斧頭","無直接同義詞","He used an axe to split the logs for the fireplace.","他用斧頭劈開壁爐要用的木柴。","ax 是美式拼字變體；hatchet 特指短柄小斧。"]],"l3-0068":[["名詞：背景經歷","experience / history","Her background in nursing helped her understand the patients' concerns.","她的護理背景幫助她理解病人的擔憂。",""]],"l3-0069":[["名詞：培根","無直接同義詞","The sandwich came with crispy bacon, lettuce, and sliced tomatoes.","三明治裡有酥脆的培根、生菜和番茄片。",""]],"l3-0070":[["複數名詞：細菌","無直接同義詞","Students examined bacteria from pond water under a microscope in class.","學生在課堂上用顯微鏡觀察池水中的細菌。","單數是 bacterium；germs 還可涵蓋其他病原，並非所有細菌都致病。"]],"l3-0071":[["副詞：嚴重地","severely / seriously","The old bridge was badly damaged during the winter storm.","那座老橋在冬季暴風雨中嚴重受損。",""]],"l3-0072":[["名詞：羽毛球運動","無直接同義詞","We play badminton in the sports hall every Wednesday evening.","我們每週三晚上都在體育館打羽毛球。",""]],"l3-0073":[["不可數名詞：行李","luggage","Please collect your baggage before leaving the arrivals hall at the airport.","離開機場入境大廳前，請領取你的行李。",""]],"l3-0074":[["名詞：誘餌","lure","The fisherman put fresh bait on his hook before casting again.","漁夫重新拋線前，在魚鉤上放了新鮮的餌。","lure 常指人工擬餌；bait 也可指真的食物。"]],"l3-0075":[["名詞：平衡","stability / equilibrium","She lost her balance when the bus suddenly turned left.","公車突然左轉時，她失去了平衡。",""]],"l3-0076":[["名詞：繃帶","無直接同義詞","The nurse wrapped a clean bandage around the injured runner's knee.","護理師用乾淨的繃帶包住受傷跑者的膝蓋。",""]],"l3-0077":[["不及物動詞：砰地作響","slam","The window banged shut when a strong wind swept through the room.","一陣強風吹過房間，窗戶砰地關上了。",""]],"l3-0078":[["形容詞：裸露的","uncovered / exposed","The children walked across the warm sand with bare feet.","孩子們赤著腳走過溫暖的沙灘。",""]],"l3-0079":[["副詞：幾乎不","hardly / scarcely","We could barely hear the guide above the noise of the waterfall.","瀑布聲太大，我們幾乎聽不見導遊說話。",""]],"l3-0080":[["名詞：穀倉；農用大棚屋","無直接同義詞","The farmer stored hay in the barn before the rainy season began.","雨季開始前，農夫把乾草存放在穀倉裡。",""]],"l3-0081":[["名詞：大桶","cask","Rainwater from the roof collects in a barrel beside the shed.","屋頂流下的雨水收集在棚屋旁的一個大桶裡。","cask 尤常指儲存酒類的木桶。"]],"l3-0082":[["名詞：海灣","inlet","Small fishing boats rested in the sheltered bay below the village.","小漁船停泊在村莊下方避風的海灣裡。","inlet 常指較狹長的水域入口。"]],"l3-0083":[["名詞：光束","ray / shaft of light","A narrow beam of sunlight fell across the dusty wooden floor.","一道細細的陽光斜照在布滿灰塵的木地板上。",""]],"l3-0084":[["名詞：野獸","wild animal","The story describes a huge beast that lives deep in the forest.","這個故事描述一頭住在森林深處的巨大野獸。",""]],"l3-0085":[["名詞：乞討者","panhandler","A beggar outside the station asked passing travelers for spare change.","車站外一名乞討者向路過的旅客討零錢。","panhandler 主要用於北美英語。"]],"l3-0086":[["不及物動詞：舉止；表現","act / conduct oneself","The children behaved well during their first visit to the museum.","孩子們第一次參觀博物館時表現得很守規矩。","conduct oneself 為反身結構，語氣較正式。"]],"l3-0087":[["名詞：生物","creature / living thing","The scientist wondered whether living beings could survive on that distant planet.","那位科學家想知道生物能否在那顆遙遠的行星上存活。",""]],"l3-0088":[["名詞：肚子","tummy / abdomen","The puppy rolled onto its back so I could rub its belly.","小狗翻過身來，好讓我摸摸牠的肚子。","belly、tummy 較口語；abdomen 較正式。"]],"l3-0089":[["名詞：腹部","belly / tummy","The doctor gently pressed the patient's abdomen during the examination.","檢查時，醫師輕輕按壓病人的腹部。","abdomen 是正式的解剖用語。"]],"l3-0090":[["介系詞：在下方","under / below","We found a small wooden box beneath the loose floorboard.","我們在鬆動的地板下面找到一個小木盒。",""]],"l3-0091":[["名詞：好處","advantage / gain","One benefit of cycling to work is saving money on fuel.","騎自行車上班的一個好處是節省油錢。",""]],"l3-0092":[["名詞：莓果","無直接同義詞","She scattered a handful of fresh berries over the yogurt.","她在優格上撒了一把新鮮莓果。",""]],"l3-0093":[["名詞：聖經","the Scriptures","My grandmother keeps a small Bible on the table beside her bed.","祖母把一本小聖經放在床邊的桌上。","指基督教聖經時 Bible 首字母大寫。"]],"l3-0094":[["名詞：十億","one thousand million","The new railway project will cost more than a billion dollars.","新的鐵路工程將耗資超過十億元。",""]],"l3-0095":[["名詞：賓果遊戲","無直接同義詞","The community center holds a bingo game every Friday afternoon.","社區中心每週五下午都舉辦賓果遊戲。",""]],"l3-0096":[["名詞：餅乾（英式用法）","cookie","I dipped a biscuit into my tea while reading the newspaper.","我一邊看報紙，一邊把餅乾浸進茶裡。","美式 biscuit 通常指鬆軟的小麵包，不能一律換成 cookie。"]],"l3-0097":[["及物動詞：責怪","hold responsible / fault","Do not blame your sister for a mistake you made yourself.","不要把自己犯的錯怪到妹妹身上。","blame someone for something；blame something on someone。"]],"l3-0098":[["名詞：毯子","無直接同義詞","She spread a wool blanket over her knees during the bus ride.","搭公車時，她在膝上蓋了一條羊毛毯。","throw 通常指較小的裝飾毯，不適用所有 blanket。"]],"l3-0099":[["不及物動詞：流血","lose blood","His finger began to bleed after he cut it on the broken glass.","他的手指被碎玻璃割到後開始流血。",""]],"l3-0100":[["及物動詞：祝福；祈求神保佑","無直接同義詞","The priest blessed the couple at the end of the wedding ceremony.","婚禮結束時，神父為那對新人祝福。",""]],"l3-0101":[["名詞：女用上衣","無直接同義詞","She wore a white blouse and dark trousers to the interview.","她穿著白色女衫和深色長褲去面試。",""]],"l3-0102":[["形容詞：大膽的","daring / brave","Opening a restaurant without any experience was a bold decision.","毫無經驗就開餐廳，是個大膽的決定。",""]],"l3-0103":[["名詞：靴子","無直接同義詞","These waterproof boots kept my feet dry on the muddy trail.","走在泥濘的小徑上時，這雙防水靴讓我的腳保持乾爽。",""]],"l3-0104":[["名詞：邊界","boundary / frontier","We had to show our passports when we crossed the border.","越過邊境時，我們必須出示護照。",""]],"l3-0105":[["及物動詞：鑽孔","drill","The carpenter bored two holes in the shelf for the screws.","木匠在層板上鑽了兩個孔，用來裝螺絲。","此卡教鑽孔義；使人厭煩是 bore 的另一義。"]],"l3-0106":[["不及物動詞：煞車","apply the brakes","The driver braked sharply when a dog ran into the road.","一隻狗衝上馬路時，駕駛猛踩煞車。",""]],"l3-0107":[["名詞：黃銅","無直接同義詞","The old door had a heavy handle made of brass.","那扇舊門裝著一個厚重的黃銅把手。",""]],"l3-0108":[["名詞：勇氣","courage / valor","The firefighter received a medal for her bravery during the rescue.","那位消防員因救援時的英勇表現獲頒獎章。","valor 較正式，常用於戰鬥或危險情境。"]],"l3-0109":[["名詞：胸部（書面用法）","chest","She held the frightened child close to her breast until he calmed down.","她把受驚的孩子緊抱在胸前，直到他平靜下來。","breast 在此指胸前，不專指乳房。"]],"l3-0110":[["名詞：一次呼吸","無直接同義詞","He took a deep breath before stepping onto the stage.","走上舞台前，他深深吸了一口氣。",""]],"l3-0111":[["不及物動詞：呼吸","respire","After running up the hill, I needed a moment to breathe normally.","跑上山丘後，我需要一點時間才能恢復正常呼吸。","respire 是生物學用語，日常通常用 breathe。"]],"l3-0112":[["名詞：微風","light wind","A cool breeze came through the window as we ate dinner.","我們吃晚餐時，一陣涼風從窗戶吹進來。",""]],"l3-0113":[["名詞：新娘","無直接同義詞","The bride smiled at her family as she entered the garden.","新娘走進花園時，向家人露出微笑。",""]],"l3-0114":[["形容詞：極聰明的；才華出眾的","gifted / exceptionally clever","The brilliant young engineer found a simple solution to the problem.","那位才華出眾的年輕工程師找到了簡單的解決方法。",""]],"l3-0115":[["名詞：小溪","stream / creek","We crossed a shallow brook on our way to the campsite.","前往營地途中，我們涉過一條淺淺的小溪。",""]],"l3-0116":[["名詞：掃帚","無直接同義詞","Dad used a broom to sweep dry leaves off the porch.","爸爸用掃帚掃掉門廊上的枯葉。",""]],"l3-0117":[["名詞：額頭","forehead","She wiped the sweat from her brow after carrying the boxes upstairs.","把箱子搬上樓後，她擦去額頭上的汗。",""]],"l3-0118":[["名詞：氣泡","無直接同義詞","Tiny bubbles rose to the surface when I opened the soda.","我打開汽水時，小氣泡升到了液面。",""]],"l3-0119":[["名詞：水桶","pail","We filled a bucket with water to wash the muddy bicycle.","我們裝了一桶水，要洗掉自行車上的泥巴。",""]],"l3-0120":[["名詞：花蕾","無直接同義詞","Pink buds appeared on the rose bush after several warm days.","幾個暖和的日子過後，玫瑰叢長出了粉紅色花苞。",""]],"l3-0121":[["名詞：預算","spending plan","Our travel budget includes train tickets, meals, and two nights in a hotel.","我們的旅行預算包括火車票、餐費和兩晚的住宿。",""]],"l3-0122":[["名詞：水牛","water buffalo","A buffalo stood in the flooded field while the farmer repaired the fence.","農夫修理圍欄時，一頭水牛站在積水的田裡。","北美口語 buffalo 也可能指 bison；本句採水牛義。"]],"l3-0123":[["名詞：自助餐","無直接同義詞","At the hotel buffet, guests could choose from several hot dishes.","在飯店的自助餐區，房客可以挑選好幾種熱食。",""]],"l3-0124":[["名詞：燈泡","light bulb","The lamp worked again after I replaced the broken bulb.","我換掉壞燈泡後，那盞燈又能亮了。",""]],"l3-0125":[["名詞：公牛","無直接同義詞","The farmer kept the bull in a separate field near the barn.","農夫把公牛養在穀倉附近一塊獨立的田地裡。",""]],"l3-0126":[["名詞：子彈的彈頭","無直接同義詞","Police found a bullet lodged in the wooden frame of the door.","警方發現一枚子彈卡在木製門框裡。","bullet 指射出的彈頭；完整彈藥另有 cartridge 等用語。"]],"l3-0127":[["及物動詞：撞到","knock / hit","I bumped my knee against the coffee table in the dark.","我在黑暗中把膝蓋撞到了茶几。",""]],"l3-0128":[["名詞：一束","bouquet","He brought a bunch of yellow flowers to his grandmother.","他帶了一束黃花給祖母。","bouquet 專指花束，不能替換 a bunch of keys。"]],"l3-0129":[["名詞：負擔","load / strain","The unexpected repair bill placed a heavy burden on our family.","那筆意外的維修費給我們家帶來沉重的負擔。",""]],"l3-0130":[["名詞：入屋竊賊","housebreaker","The burglar entered the house through an unlocked kitchen window.","竊賊從一扇沒鎖的廚房窗戶進入屋內。","burglar 著重非法進入建築物行竊，不限定夜間。"]],"l3-0131":[["及物動詞：埋葬","inter / lay to rest","The family buried their beloved dog beneath the apple tree.","這家人把心愛的狗埋葬在蘋果樹下。","inter 很正式；lay to rest 為委婉說法。"]],"l3-0132":[["名詞：灌木","shrub","A small bird built its nest inside the thick bush.","一隻小鳥在茂密的灌木叢裡築了巢。",""]],"l3-0133":[["不及物動詞：嗡嗡作響","hum","Bees buzzed around the lavender while we sat in the garden.","我們坐在花園裡時，蜜蜂在薰衣草周圍嗡嗡飛舞。",""]],"l3-0134":[["名詞：小木屋","hut","We rented a small cabin beside the lake for the weekend.","我們租了湖邊的一間小木屋過週末。","hut 通常較簡陋；cabin 在此指小型木屋。"]],"l3-0135":[["名詞：校園","university grounds","There is a quiet garden at the eastern edge of campus.","校園東側有一座安靜的花園。",""]],"l3-0136":[["名詞：手杖","walking stick","My grandfather uses a cane when he walks to the market.","祖父走路去市場時會拄手杖。",""]],"l3-0137":[["名詞：獨木舟","無直接同義詞","We paddled a canoe across the lake before the wind grew stronger.","趁風還沒變強，我們划著獨木舟穿過湖面。",""]],"l3-0138":[["名詞：峽谷","gorge","From the bridge, we could see a river flowing through the canyon.","從橋上可以看見一條河流經峽谷。",""]],"l3-0139":[["形容詞：有能力的","competent / able","She is a capable manager who handles difficult situations calmly.","她是位能幹的經理，處理棘手情況時很沉著。",""]],"l3-0140":[["名詞：首都","capital city","The government moved its offices from the coast to the new capital.","政府把辦公室從海岸地區遷到新首都。",""]],"l3-0141":[["及物動詞：捕捉","catch / seize","The rescuers captured the injured bird and took it to a vet.","救援人員捉住那隻受傷的鳥，把牠送去看獸醫。",""]],"l3-0142":[["名詞：木匠","無直接同義詞","A carpenter built custom shelves to fit the space under our stairs.","一位木匠依照樓梯下的空間訂製了層架。","woodworker 指從事木工的人，範圍比 carpenter 廣。"]],"l3-0143":[["名詞：馬車","coach","A horse pulled the carriage slowly along the narrow village street.","一匹馬拉著馬車，緩緩行經狹窄的村莊街道。","coach 通常指較大的四輪馬車。"]],"l3-0144":[["及物動詞：拋出","throw / toss","The fisherman cast his net into the shallow water near the shore.","漁夫把網撒進岸邊的淺水裡。","cast 的過去式和過去分詞仍是 cast。"]],"l3-0145":[["名詞：全體演員","company of actors","The entire cast returned to the stage to thank the audience.","全體演員回到舞台上向觀眾致謝。",""]],"l3-0146":[["形容詞：非正式的；休閒的","informal / relaxed","Wear casual clothes because we will be eating in the garden.","穿休閒服就好，因為我們會在花園裡用餐。",""]],"l3-0147":[["名詞：毛毛蟲","無直接同義詞","A green caterpillar was chewing a leaf on the tomato plant.","一隻綠色毛毛蟲正在啃食番茄植株上的葉子。",""]],"l3-0148":[["複數名詞：牛隻","無直接同義詞","The farmer moved the cattle into the barn before the storm.","暴風雨來臨前，農夫把牛群趕進了牛舍。","cattle 作複數，不能說 a cattle。"]],"l3-0149":[["及物動詞：慶祝","mark","We celebrated my sister's graduation with a dinner at home.","我們在家吃晚餐，慶祝姊姊畢業。","mark 在此指以活動慶賀重要日子。"]],"l3-0150":[["名詞：公分","centimetre","Leave two centimeters between the edge of the paper and the drawing.","在紙張邊緣和圖畫之間留兩公分的空白。","centimetre 為英式拼字。"]],"l3-0151":[["名詞：陶瓷製品（常用複數）","pottery","The museum's collection of ceramics includes bowls from several ancient cities.","博物館的陶瓷收藏包括來自幾座古城的碗。","陶瓷製品統稱常用 ceramics；ceramic 也可作形容詞或指陶瓷材料。"]],"l3-0152":[["名詞：鏈條","無直接同義詞","The bicycle chain slipped off as I rode up the hill.","我騎車上坡時，自行車鏈條掉了。",""]],"l3-0153":[["名詞：難題；挑戰","test / demanding task","Finding enough volunteers was the biggest challenge in organizing the festival.","籌辦慶典時，找到足夠的志工是最大的挑戰。",""]],"l3-0154":[["名詞：冠軍","winner / titleholder","The national champion stayed after the race to sign autographs.","那位全國冠軍在比賽後留下來簽名。",""]],"l3-0155":[["形容詞：多變的","variable","The weather here is changeable, so keep a jacket in your bag.","這裡天氣多變，所以包包裡要放件外套。",""]],"l3-0156":[["名詞：電視頻道","無直接同義詞","This channel shows nature documentaries every evening after the news.","這個頻道每晚新聞播完後都播放自然紀錄片。",""]],"l3-0157":[["名詞：章節","無直接同義詞","The final chapter explains what happened to the missing explorer.","最後一章說明了那位失蹤探險家的遭遇。",""]],"l3-0158":[["名詞：魅力","appeal / attractiveness","Much of the village's charm comes from its old stone houses.","這座村莊的魅力，大部分來自那些古老的石屋。",""]],"l3-0159":[["不及物動詞：閒聊","talk / converse","We chatted about our weekend plans while waiting for the bus.","等公車時，我們聊了聊週末的計畫。","converse 較正式；chat 強調輕鬆的談話。"]],"l3-0160":[["名詞：臉頰","無直接同義詞","The cold wind made the little boy's cheeks turn bright red.","冷風吹得那個小男孩的雙頰通紅。",""]],"l3-0161":[["名詞：歡呼聲","shout of approval","A loud cheer rose from the crowd when the team scored.","球隊得分時，人群中響起一陣熱烈的歡呼。",""]],"l3-0162":[["形容詞：開朗愉快的","happy / upbeat","Her cheerful voice made the long morning at work feel easier.","她開朗的聲音讓漫長的工作早晨輕鬆了些。",""]],"l3-0163":[["名詞：起司","無直接同義詞","Sprinkle some grated cheese over the pasta before serving it.","義大利麵上桌前，撒上一些刨好的起司。",""]],"l3-0164":[["名詞：櫻桃","無直接同義詞","She removed the stones from the cherries before making the pie.","做派之前，她先去掉了櫻桃的果核。",""]],"l3-0165":[["名詞：胸部","breast","He held the heavy box against his chest while opening the door.","他把重箱子抱在胸前，一邊打開門。","breast 指胸部時較書面。"]],"l3-0166":[["及物動詞：咀嚼","masticate","She chewed each bite slowly because the bread was unusually hard.","麵包特別硬，所以她每一口都慢慢咀嚼。","masticate 是咀嚼的正式用語。"]],"l3-0167":[["名詞：童年","early years","I spent most of my childhood in a small town near the coast.","我童年大部分的時光都在海邊的一個小鎮度過。",""]],"l3-0168":[["名詞：寒意","coldness","There was a chill in the air as the sun went down.","太陽下山時，空氣中透著一股寒意。",""]],"l3-0169":[["形容詞：冷颼颼的","cold / cool","The evenings are still chilly, even though the days are warm.","雖然白天暖和，晚上仍然冷颼颼的。","chilly 常帶冷得不太舒服的意味。"]],"l3-0170":[["名詞：煙囪","無直接同義詞","Smoke drifted from the chimney of the cottage across the field.","田野另一頭的小屋，煙囪裡飄出縷縷煙霧。",""]],"l3-0171":[["名詞：晶片","microchip","A tiny chip inside the card stores the passenger's travel information.","卡片裡的一枚小晶片儲存著乘客的乘車資料。",""]],"l3-0172":[["不及物動詞：噎住","無直接同義詞","He began to choke after swallowing a large piece of bread.","他吞下一大塊麵包後開始噎住。","gag 偏指作嘔或咽反射，未必氣道堵塞，不宜當作直接同義詞。"]],"l3-0173":[["及物動詞：切碎","cut up","Chop the onion finely before adding it to the hot pan.","把洋蔥切碎後，再放進熱鍋裡。",""]],"l3-0174":[["名詞：香菸","cig","He put out his cigarette before entering the train station.","他進入火車站前先熄掉了香菸。","cig 是非正式縮略語。"]],"l3-0175":[["名詞：馬戲團","無直接同義詞","The visiting circus set up its striped tent outside the town.","來巡演的馬戲團在鎮外搭起了條紋帳篷。",""]],"l3-0176":[["形容詞：公民權利的","無直接同義詞","The students discussed civil rights during their lesson on modern history.","學生在近代史課上討論了公民權利。","civil rights 是固定搭配；civic 偏指公民責任或城市事務。"]],"l3-0177":[["形容詞：古典音樂的","無直接同義詞","The radio station plays classical music throughout the quiet evening hours.","那家廣播電台在安靜的晚間時段持續播放古典音樂。",""]],"l3-0178":[["名詞：喀噠聲","無直接同義詞","I heard a click as the door locked behind me.","門在我身後鎖上時，我聽到喀噠一聲。",""]],"l3-0179":[["名詞：客戶","customer","The designer showed her client three possible layouts for the shop.","設計師向客戶展示了三種可行的店面配置。","client 常指接受專業服務的客戶。"]],"l3-0180":[["名詞：診所","無直接同義詞","The clinic near our office accepts patients without an appointment.","我們辦公室附近的診所接受未預約的病人。","medical practice 可指醫療執業事業，與診所場所不完全相同。"]],"l3-0181":[["及物動詞：修剪","trim / cut","The gardener clipped the hedge to keep the path clear.","園丁修剪了樹籬，讓小徑保持暢通。",""]],"l3-0182":[["名詞：線索","hint / lead","A muddy footprint gave the detective a clue about the visitor.","一個沾泥的腳印，給了偵探關於訪客的線索。",""]],"l3-0183":[["名詞：雞尾酒","mixed drink","The bartender decorated the cocktail with a thin slice of orange.","酒保用一片薄橙片裝飾那杯雞尾酒。",""]],"l3-0184":[["名詞：椰子","無直接同義詞","The vendor opened a coconut and handed me a straw.","攤販打開一顆椰子，遞給我一根吸管。",""]],"l3-0185":[["名詞：項圈","無直接同義詞","The dog's collar had a tag with its owner's phone number.","狗的項圈上掛著一塊寫有主人電話的牌子。",""]],"l3-0186":[["名詞：收藏品","無直接同義詞","His collection of old postcards fills three large albums now.","他收藏的舊明信片如今已裝滿三大本相簿。",""]],"l3-0187":[["名詞：大學；學院","無直接同義詞","She plans to study engineering at a college near home.","她打算在家附近的一所大學讀工程。","college 的學制含義因地區而異，不一律等於 university。"]],"l3-0188":[["名詞：殖民地","無直接同義詞","The history museum explains how the island became a colony.","歷史博物館說明了這座島嶼如何成為殖民地。","dependency 泛指受另一國管轄的領地，法律地位可能不同。"]],"l3-0189":[["名詞：縱欄","無直接同義詞","Write each student's name in the first column of the table.","把每位學生的姓名寫在表格的第一欄。",""]],"l3-0190":[["及物動詞：混合","mix / blend","Combine the flour and sugar in a large mixing bowl.","把麵粉和糖放入大攪拌碗中混合。",""]],"l3-0191":[["名詞：安慰","consolation / reassurance","Her friend's kind words brought her comfort after the disappointing news.","聽到令人失望的消息後，朋友溫暖的話語給了她安慰。",""]],"l3-0192":[["名詞：逗號","無直接同義詞","Put a comma after the introductory phrase in this sentence.","在這句話的開頭片語後面加一個逗號。",""]],"l3-0193":[["名詞：命令","order / instruction","The soldiers obeyed the command to remain behind the wall.","士兵服從命令，留在牆後。",""]],"l3-0194":[["名詞：影音廣告","advertisement / ad","A funny commercial interrupted the film just before the final scene.","電影最後一幕之前，插播了一則有趣的廣告。",""]],"l3-0195":[["名詞：委員會","panel / board","The committee will meet on Monday to discuss the school budget.","委員會將在星期一開會，討論學校預算。","panel 和 board 的成員任務與權限可能不同。"]],"l3-0196":[["不及物動詞：溝通","exchange information / converse","The two teams communicated regularly to avoid mistakes during the project.","兩個團隊定期溝通，以避免專案進行時出錯。",""]],"l3-0197":[["名詞：比較","無直接同義詞","A comparison of the lunch and dinner menus showed a large price difference.","比較午餐與晚餐菜單後，發現兩者價差很大。",""]],"l3-0198":[["不及物動詞：參加競賽","contend / vie","Students from twelve schools will compete in the regional science fair.","十二所學校的學生將在區域科展中競賽。","vie 常搭配 for，表示爭取獎項或機會。"]],"l3-0199":[["名詞：投訴","grievance / objection","The hotel received a complaint about noise from the upstairs room.","飯店收到一則關於樓上房間噪音的投訴。","grievance 常指認為受到不公待遇的不滿。"]],"l3-0200":[["形容詞：複雜的","complicated / intricate","The instructions were too complex for the children to follow alone.","說明太複雜，孩子們無法自行照著操作。",""]],"l3-0201":[["及物動詞：使擔心","worry / trouble","The recent increase in traffic accidents concerns many parents in our neighborhood.","最近交通事故增加，讓我們社區許多家長感到擔憂。",""]],"l3-0202":[["名詞：音樂會","無直接同義詞","Tickets for the outdoor concert sold out within two hours.","那場戶外音樂會的票在兩小時內就售完了。","musical performance 泛指音樂演出，不一定是整場音樂會。"]],"l3-0203":[["及物動詞：推斷","deduce / determine","The investigators concluded that a damaged wire had caused the fire.","調查人員推斷，火災是由一條破損電線引起的。",""]],"l3-0204":[["名詞：結論","finding / judgment","After comparing the evidence, the students reached the same conclusion.","比較證據之後，學生們得出了相同的結論。",""]],"l3-0205":[["名詞：狀況","state / shape","Despite its age, the old bicycle is still in excellent condition.","儘管車齡已久，那輛舊自行車的狀況仍然很好。","in good shape 是較口語的說法。"]],"l3-0206":[["名詞：冰淇淋甜筒","無直接同義詞","My ice cream started dripping down the cone in the afternoon heat.","下午天氣炎熱，我的冰淇淋開始沿著甜筒往下滴。",""]],"l3-0207":[["形容詞：有信心的","sure / self-assured","After several practice interviews, she felt confident about meeting the manager.","經過幾次模擬面試後，她對與經理面談有了信心。",""]],"l3-0208":[["及物動詞：使困惑","puzzle / bewilder","The unclear signs confused tourists trying to find the main entrance.","不清楚的標示讓尋找正門的遊客感到困惑。",""]],"l3-0209":[["及物動詞：連接","link / join","A wooden bridge connects the island to the eastern shore.","一座木橋把島嶼與東岸連接起來。",""]],"l3-0210":[["名詞：連線","link","The video call ended when we lost our internet connection.","我們的網路連線中斷，視訊通話也隨之結束。",""]],"l3-0211":[["形容詞：有意識的；清醒的","awake","The injured cyclist was conscious and able to answer simple questions.","受傷的自行車騎士意識清醒，能夠回答簡單的問題。","conscious 著重有意識；awake 著重沒有睡著。"]],"l3-0212":[["形容詞：相當多的","substantial / significant","Restoring the old house required considerable time and careful planning.","修復那棟老房子需要相當多的時間與周詳規劃。",""]],"l3-0213":[["名詞：考慮","thought / deliberation","After careful consideration, we decided to postpone the trip until spring.","經過慎重考慮，我們決定把旅行延至春天。",""]],"l3-0214":[["形容詞：固定不變的","steady / unchanging","The room must stay at a constant temperature during the experiment.","實驗期間，房間必須維持固定的溫度。",""]],"l3-0215":[["名詞：洲","無直接同義詞","Her dream is to visit every continent at least once.","她的夢想是每一洲都至少去過一次。",""]],"l3-0216":[["名詞：合約","agreement","Read the contract carefully before agreeing to rent the apartment.","同意租下公寓之前，要仔細閱讀合約。",""]],"l3-0217":[["名詞：長沙發","sofa / settee","The cat was sleeping on the couch beside my grandfather.","那隻貓睡在祖父身旁的沙發上。",""]],"l3-0218":[["形容詞：可數的","無直接同義詞","Our teacher asked us to underline the countable nouns in the paragraph.","老師請我們把段落中的可數名詞畫上底線。",""]],"l3-0219":[["名詞：膽怯者；懦夫","cowardly person","The other boys unfairly called him a coward for refusing the dangerous dare.","他拒絕冒險挑戰，其他男孩卻不公平地罵他是懦夫。","coward 帶貶義，指責他人時須注意語氣。"]],"l3-0220":[["名詞：搖籃","無直接同義詞","The baby fell asleep as her father gently rocked the cradle.","父親輕輕搖動搖籃，寶寶便睡著了。",""]],"l3-0221":[["不及物動詞：當機","stop working / fail","My computer crashed just before I could save the final paragraph.","我還來不及儲存最後一段，電腦就當機了。",""]],"l3-0222":[["不及物動詞：爬行","creep","The baby crawled across the carpet to reach her favorite toy.","寶寶爬過地毯，去拿最喜歡的玩具。",""]],"l3-0223":[["形容詞：有創意的","inventive / imaginative","The students found a creative way to reuse old plastic bottles.","學生們想出了一個富有創意的方法來再利用舊塑膠瓶。",""]],"l3-0224":[["名詞：創作者","maker / originator","The game's creator answered questions from fans at the exhibition.","遊戲的創作者在展覽上回答粉絲的問題。",""]],"l3-0225":[["名詞：生物","living thing / being","We spotted a strange sea creature in a shallow pool.","我們在一處淺水池中發現了一隻奇特的海洋生物。",""]],"l3-0226":[["名詞：功勞；讚許","recognition / praise","The coach gave the whole team credit for the victory.","教練把勝利的功勞歸給了全隊。",""]],"l3-0227":[["不及物動詞：躡手躡足地走","sneak / tiptoe","I crept past the bedroom so I would not wake the baby.","我躡手躡足地走過臥室，免得吵醒寶寶。","creep 的過去式為 crept。"]],"l3-0228":[["名詞：全體機組人員","flight crew","The crew checked every seat belt before the plane took off.","飛機起飛前，機組人員逐一檢查了每條安全帶。",""]],"l3-0229":[["名詞：蟋蟀","無直接同義詞","A cricket chirped somewhere in the grass outside my bedroom window.","我臥室窗外的草叢裡，有一隻蟋蟀正在鳴叫。",""]],"l3-0230":[["名詞：罪犯","offender / lawbreaker","The police caught the criminal after reviewing the store's security footage.","警方查看商店的監視錄影後，抓到了那名罪犯。",""]],"l3-0231":[["形容詞：酥脆的","crispy / crunchy","The roasted potatoes were crisp on the outside and soft inside.","烤馬鈴薯外酥內軟。",""]],"l3-0232":[["名詞：王冠","無直接同義詞","The queen wore a gold crown during the formal ceremony.","女王在正式典禮上戴著一頂金色王冠。",""]],"l3-0233":[["形容詞：咬起來脆的","crisp / crispy","These crunchy crackers taste especially good with a little cheese.","這些脆餅配上一點起司特別好吃。",""]],"l3-0234":[["名詞：拐杖","無直接同義詞","She used crutches for two weeks after injuring her ankle.","腳踝受傷後，她用了兩週的拐杖。","crutch 常為腋下或前臂支撐式，與 cane 不完全相同。"]],"l3-0235":[["形容詞：文化的","無直接同義詞","The festival gives visitors a chance to experience local cultural traditions.","這場慶典讓遊客有機會體驗當地的文化傳統。",""]],"l3-0236":[["名詞：櫥櫃","cabinet","The clean plates are in the cupboard above the kitchen sink.","乾淨的盤子放在廚房水槽上方的櫥櫃裡。",""]],"l3-0237":[["名詞：水流","flow","The strong current carried the empty boat farther down the river.","強勁的水流把空船帶往更下游的地方。",""]],"l3-0238":[["名詞：循環","recurring series","The diagram shows the complete life cycle of a butterfly.","這張圖呈現蝴蝶完整的生命週期。","cycle 表示按次序反覆發生的循環；life cycle 是生命週期。"]],"l3-0239":[["名詞：乳品場","dairy farm","The school arranged a visit to a dairy outside the city.","學校安排參觀市區外的一座乳品場。",""]],"l3-0240":[["名詞：水壩","無直接同義詞","The dam holds back water that supplies several nearby towns.","那座水壩攔蓄的水供應附近幾個城鎮使用。",""]],"l3-0241":[["助動詞：敢","have the courage to","I dare not open the letter while everyone is watching.","大家都在看，我不敢打開那封信。","助動詞 dare 後接原形；一般動詞用法可說 do not dare to。"]],"l3-0242":[["名詞：親愛的人（稱呼）","dear / sweetheart","Come inside, darling, and tell me what happened at school.","親愛的，進來告訴我學校發生了什麼事。",""]],"l3-0243":[["不及物動詞：急奔","rush / sprint","We dashed across the platform just before the train doors closed.","就在火車車門關閉前，我們衝過了月台。",""]],"l3-0244":[["及物動詞：使暫時聽不見","無直接同義詞","The sudden blast deafened him for a moment and left his ears ringing.","突然的爆炸聲讓他一時聽不見，耳朵嗡嗡作響。",""]],"l3-0245":[["名詞：經銷商","trader","The bicycle dealer offered to repair the brakes before delivery.","自行車經銷商主動表示會在交車前修好煞車。",""]],"l3-0246":[["名詞：十年","ten years","The neighborhood has changed greatly over the past decade.","這個社區在過去十年間變化很大。",""]],"l3-0247":[["名詞：甲板","無直接同義詞","Passengers gathered on deck to watch the ship enter the harbor.","乘客聚集在甲板上，看著船駛入港口。",""]],"l3-0248":[["名詞：行為","act / action","Her kind deed inspired other neighbors to help the elderly couple.","她的善行感動了其他鄰居，大家也開始幫助那對老夫妻。",""]],"l3-0249":[["及物動詞：加深","strengthen / intensify","Working together on the garden deepened our friendship over the summer.","那個夏天，一起照料花園讓我們的友誼更加深厚。",""]],"l3-0250":[["及物動詞：為詞語下定義","explain the meaning of","The teacher asked us to define the unfamiliar words in our own language.","老師要我們用自己的語言解釋那些生字的意思。",""]],"l3-0251":[["名詞：定義","explanation of meaning","Look up the definition before using that word in your report.","把那個字用進報告前，先查清楚它的定義。",""]],"l3-0252":[["名詞：配送","shipping","The shop offers free delivery for orders over fifty dollars.","那家店提供滿五十元免運費的服務。","shipping 著重運送；delivery 著重送達。"]],"l3-0253":[["名詞：民主制度","無直接同義詞","The class discussed the role of free elections in a democracy.","班上討論了自由選舉在民主制度中扮演的角色。","self-government 著重自治，不一定採民主制度。"]],"l3-0254":[["形容詞：民主的","無直接同義詞","The club uses a democratic process to choose its new leader.","這個社團透過民主程序選出新領導人。",""]],"l3-0255":[["名詞：訂金","down payment","We paid a deposit to reserve the room for our wedding reception.","我們付了訂金，預訂婚宴用的場地。","本句 deposit 指預訂時先付的一部分款項。down payment 常用於購屋、購車的頭期款；deposit 另可指押金或銀行存款。"]],"l3-0256":[["名詞：描述","account / portrayal","Her description of the village made me want to visit it.","她對那座村莊的描述，讓我也想去看看。",""]],"l3-0257":[["名詞：設計師","無直接同義詞","The designer chose warm colors for the restaurant's new dining area.","設計師為餐廳的新用餐區選用了暖色系。",""]],"l3-0258":[["形容詞：令人嚮往的","attractive / appealing","A short walk to work makes this apartment especially desirable.","走一小段路就能上班，讓這間公寓格外吸引人。",""]],"l3-0259":[["及物動詞：摧毀","ruin","The fire destroyed several wooden buildings near the old railway station.","大火燒毀了老火車站附近的幾棟木造建築。",""]],"l3-0260":[["名詞：細節","particular","Please check every detail of the invitation before we print it.","印製邀請函前，請檢查每個細節。",""]],"l3-0261":[["及物動詞：決定","decide / establish","The number of guests will determine how many tables we need.","賓客人數將決定我們需要多少張桌子。",""]],"l3-0262":[["名詞：惡魔","demon / evil spirit","In the story, a clever farmer tricks the devil into leaving his village.","故事裡，一位聰明農夫設計讓惡魔離開村莊。",""]],"l3-0263":[["名詞：對話","conversation / exchange","The film's natural dialogue makes the characters feel like real people.","電影裡自然的對話讓角色像真實人物一樣。",""]],"l3-0264":[["名詞：日常飲食","無直接同義詞","Fresh vegetables have become a regular part of our family diet.","新鮮蔬菜已成為我們家日常飲食的一部分。","diet 在此指平常吃喝的食物；food intake 著重食物攝取量，不能直接替換。"]],"l3-0265":[["形容詞：勤奮的","hardworking / industrious","The diligent student reviewed her notes after every history lesson.","那位勤奮的學生每次上完歷史課都會複習筆記。",""]],"l3-0266":[["形容詞：昏暗的","faint / subdued","We could hardly read the menu in the restaurant's dim light.","餐廳燈光昏暗，我們幾乎看不清楚菜單。",""]],"l3-0267":[["名詞：美國或加拿大十分硬幣","ten-cent coin","I found a dime under the seat while cleaning the car.","我清理汽車時，在座椅下找到一枚十分硬幣。",""]],"l3-0268":[["不及物動詞：用餐","eat / have dinner","Guests can dine on the terrace when the weather is pleasant.","天氣宜人時，客人可以在露臺上用餐。","dine 較正式，常指吃晚餐。"]],"l3-0269":[["及物動詞：蘸；短暫浸入","dunk","She dipped the brush into the blue paint and began drawing waves.","她把畫筆蘸了藍色顏料，開始畫海浪。","dip 通常指短暫浸入，dunk 較口語。"]],"l3-0270":[["名詞：泥土；髒汙","grime / soil","Please wipe the dirt off your shoes before coming inside.","進屋前，請把鞋子上的泥土擦掉。",""]],"l3-0271":[["及物動詞：使失望","let down","The canceled concert disappointed fans who had traveled a long way.","演唱會取消，讓遠道而來的歌迷很失望。",""]],"l3-0272":[["名詞：失望","dismay","She could not hide her disappointment when the picnic was canceled.","野餐取消時，她掩飾不住自己的失望。","dismay 常多一層驚愕或沮喪。"]],"l3-0273":[["名詞：迪斯可舞廳","discotheque","After dinner, they went to a disco and danced until midnight.","晚餐後，他們去迪斯可舞廳跳舞，直到午夜。",""]],"l3-0274":[["名詞：折扣","price reduction","Students receive a discount when they show their school identification cards.","學生出示學生證便可享有折扣。",""]],"l3-0275":[["名詞：發現","finding","The discovery of old coins delayed construction at the building site.","工地發現了古錢幣，導致施工延誤。",""]],"l3-0276":[["名詞：疾病","illness / disorder","The researchers are studying a disease that affects children's muscles.","研究人員正在研究一種影響兒童肌肉的疾病。","disease 常指特定疾病；illness 也可泛指生病的狀態。"]],"l3-0277":[["名詞：光碟","無直接同義詞","The photographer gave us a disc containing all the wedding pictures.","攝影師給了我們一張存有全部婚禮照片的光碟。","光碟常拼 disc；電腦磁碟通常拼 disk。"]],"l3-0278":[["及物動詞：不喜歡","be averse to / not enjoy","I dislike driving at night because the headlights hurt my eyes.","我不喜歡夜間開車，因為車燈會刺痛我的眼睛。",""]],"l3-0279":[["名詞：溝渠","trench / channel","Rainwater flowed through the ditch beside the road into the pond.","雨水沿著路旁的溝渠流進池塘。",""]],"l3-0280":[["不及物動詞：跳水","plunge","She dived into the pool and swam quickly to the other end.","她跳進泳池，迅速游到另一端。",""]],"l3-0281":[["名詞：碼頭","pier / wharf","The ferry was already waiting at the dock when we arrived.","我們抵達時，渡輪已經在碼頭等候了。","dock、pier、wharf 的構造與地區用法可能不同。"]],"l3-0282":[["及物動詞：閃避","avoid / evade","He dodged a falling branch as he ran toward the shelter.","他跑向避雨處時，閃過了一根掉落的樹枝。",""]],"l3-0283":[["形容詞：國內的","internal","Domestic flights leave from the smaller terminal across the road.","國內線班機從馬路對面較小的航廈出發。",""]],"l3-0284":[["名詞：一劑的用量","無直接同義詞","The label clearly states the recommended dose and when to take it.","標籤清楚標明建議劑量與服用時間。",""]],"l3-0285":[["形容詞：懷疑的","unsure / skeptical","I am doubtful that we can finish painting before sunset.","我懷疑我們能不能在日落前把油漆刷完。",""]],"l3-0286":[["及物動詞：排掉液體","draw off","Drain the water from the pot before adding the sauce.","加入醬汁前，先把鍋裡的水瀝掉。",""]],"l3-0287":[["形容詞：顯著而驚人的","striking / remarkable","There was a dramatic improvement in her speed after several months of training.","經過幾個月的訓練，她的速度有了顯著進步。",""]],"l3-0288":[["不及物動詞：滴下","fall in drops","Water dripped from the wet umbrella onto the kitchen floor.","水從濕雨傘上滴到廚房地板。","trickle 指細流，與一滴滴落下的 drip 不完全相同。"]],"l3-0289":[["及物動詞：使溺斃","無直接同義詞","The sudden flood drowned several sheep trapped in the field.","突如其來的洪水淹死了幾隻困在田裡的羊。",""]],"l3-0290":[["形容詞：昏昏欲睡的","sleepy / dozy","The warm room made me feel drowsy during the afternoon lecture.","溫暖的房間讓我在下午的講課中昏昏欲睡。",""]],"l3-0291":[["形容詞：喝醉的","intoxicated / inebriated","He was too drunk to drive, so his friend called a taxi.","他醉得無法開車，所以朋友幫他叫了計程車。","intoxicated、inebriated 較正式。"]],"l3-0292":[["形容詞：到期應付的","payable / owed","The final payment is due at the end of this month.","最後一筆款項應在本月底支付。",""]],"l3-0293":[["及物動詞：傾倒；丟棄","discard / unload","Someone dumped a pile of old furniture beside the village road.","有人在村莊路邊丟了一堆舊家具。",""]],"l3-0294":[["名詞：灰塵","無直接同義詞","A thick layer of dust covered the books in the empty room.","空房間裡的書上覆著厚厚一層灰塵。",""]],"l3-0295":[["形容詞：熱切的","keen / enthusiastic","The children were eager to try the new playground equipment.","孩子們迫不及待想試試新的遊樂設施。","eager to do；keen to do 或 keen on。"]],"l3-0296":[["複數名詞：工作收入","income / pay","She saves part of her monthly earnings for future travel.","她每月把一部分工作收入存起來，留作以後旅行之用。",""]],"l3-0297":[["名詞：回聲","reverberation","We heard an echo of our voices inside the empty tunnel.","我們在空蕩蕩的隧道裡聽見自己的回聲。","echo 指反射後可辨認的回聲；reverberation 著重延續、迴盪的聲響，並非完全相同。"]],"l3-0298":[["及物動詞：編修","revise / correct","Please edit the article to remove repeated information and unclear sentences.","請編修這篇文章，刪去重複資訊和不清楚的句子。",""]],"l3-0299":[["名詞：版本","version","The latest edition of the guide includes several new walking routes.","最新版旅遊指南收錄了幾條新的步行路線。",""]],"l3-0300":[["名詞：編輯","無直接同義詞","The editor asked the reporter to check the names once more.","編輯請記者再核對一次姓名。",""]],"l3-0301":[["及物動詞：教育","teach / instruct","The program educates children about the importance of protecting local wildlife.","這個計畫教導兒童保護當地野生動物的重要性。",""]],"l3-0302":[["形容詞：具教育意義的","instructive / informative","The museum offers educational activities that let children explore science through play.","博物館提供具教育意義的活動，讓孩子透過遊戲探索科學。",""]],"l3-0303":[["形容詞：有效率的","economical","The new heating system is more efficient and uses less electricity.","新的暖氣系統效率較高，也更省電。","economical 偏指節省資源；efficient 著重以少量投入達成效果。"]],"l3-0304":[["名詞：手肘","無直接同義詞","I hurt my elbow when I fell off my bicycle.","我從自行車上摔下來時撞傷了手肘。",""]],"l3-0305":[["形容詞：年長的","older / aged","The volunteers deliver meals to elderly residents who live alone.","志工送餐給獨居的年長居民。","older 語氣較中性；aged 較正式。"]],"l3-0306":[["名詞：選舉","poll","The school held an election to choose the student council president.","學校舉行選舉，選出學生會會長。","poll 在此指投票選舉，也可另指民意調查。"]],"l3-0307":[["形容詞：電動的","electrically powered","An electric fan kept the air moving in the crowded room.","一台電風扇讓擁擠房間裡的空氣保持流通。",""]],"l3-0308":[["名詞：電力","electric power","The storm cut off electricity to several houses along the coast.","暴風雨讓沿海幾棟房屋停電了。",""]],"l3-0309":[["形容詞：電子的","無直接同義詞","An electronic display above the platform showed the next train's arrival time.","月台上方的電子看板顯示下一班列車的抵達時間。","electronic 指電子技術；electric 偏指用電或電力，不能一律互換。"]],"l3-0310":[["名詞：緊急情況","crisis","During the emergency, staff guided all visitors to the nearest exit.","緊急情況發生時，工作人員引導所有訪客前往最近的出口。","crisis 常指危機階段，範圍與 emergency 不完全相同。"]],"l3-0311":[["名詞：皇帝","無直接同義詞","The emperor ordered a new palace to be built beside the river.","皇帝下令在河邊興建一座新宮殿。","king、monarch 的職銜或範圍不同，非直接同義詞。"]],"l3-0312":[["及物動詞：強調","stress / highlight","The instructor emphasized the need to check our equipment before climbing.","教練強調，攀登前必須檢查裝備。",""]],"l3-0313":[["及物動詞：僱用","hire / take on","The new factory will employ about two hundred local workers.","新工廠將僱用大約兩百名當地工人。",""]],"l3-0314":[["名詞：有酬工作","work / a job","She found employment at a bookstore shortly after finishing college.","大學畢業不久，她便在一家書店找到了工作。","employment 在此不可數。"]],"l3-0315":[["名詞：受僱員工","worker / staff member","Every employee receives training before using the machines on the factory floor.","每位員工使用工廠現場的機器前，都會接受訓練。",""]],"l3-0316":[["名詞：僱主","無直接同義詞","Her employer agreed to let her work from home on Fridays.","她的僱主同意讓她星期五在家工作。","boss 也可只是主管，不一定是僱主。"]],"l3-0317":[["形容詞：空的","vacant / unoccupied","We found an empty table near the back of the café.","我們在咖啡館後方找到一張空桌。",""]],"l3-0318":[["及物動詞：使能夠","allow / make it possible for","The new ramp enables wheelchair users to enter through the main door.","新的斜坡道讓輪椅使用者能從正門進入。","enable someone to do something。"]],"l3-0319":[["形容詞：精力充沛的","lively / vigorous","Our energetic guide led us up the hill without stopping once.","我們精力充沛的導遊一路帶我們上山，中途一次也沒停。",""]],"l3-0320":[["及物動詞：吸引住","capture / hold","The speaker used a surprising story to engage the audience's attention.","講者用一個出人意料的故事吸引觀眾注意。",""]],"l3-0321":[["名詞：訂婚","betrothal","They announced their engagement at a family dinner on Sunday.","他們在星期天的家庭晚餐上宣布訂婚。","betrothal 較正式或古雅。"]],"l3-0322":[["名詞：引擎","motor","The mechanic listened carefully to the strange noise from the engine.","技師仔細聽著引擎傳出的異常聲音。","motor 和 engine 的技術範圍依情境而異。"]],"l3-0323":[["名詞：工程師","無直接同義詞","An engineer inspected the bridge after the heavy rain ended.","大雨停歇後，一位工程師檢查了那座橋。",""]],"l3-0324":[["形容詞：令人愉快的","pleasant / pleasurable","The gentle walk along the river was an enjoyable way to spend the afternoon.","沿著河邊悠閒散步，是度過下午的愉快方式。",""]],"l3-0325":[["名詞：進入","admission / access","Entry to the exhibition is free for children under twelve.","未滿十二歲的兒童可以免費入場參觀展覽。",""]],"l3-0326":[["形容詞：環境的","ecological","The report describes the environmental damage caused by the factory's waste.","報告描述了工廠廢棄物造成的環境破壞。","ecological 著重生態系及生物與環境的關係。"]],"l3-0327":[["及物動詞：羨慕","be envious of","I envy your ability to stay calm when plans suddenly change.","我很羨慕你在計畫突然改變時仍能保持冷靜。",""]],"l3-0328":[["及物動詞：擦去","rub out / remove","Erase the pencil marks after the ink has completely dried.","等墨水完全乾了之後，再擦去鉛筆痕跡。",""]],"l3-0329":[["不及物動詞：逃脫","get away / flee","The rabbit escaped through a small hole in the garden fence.","兔子從花園圍欄上的一個小洞逃走了。",""]],"l3-0330":[["形容詞：邪惡的","wicked / malevolent","The evil ruler ordered his guards to imprison anyone who criticized him.","邪惡的統治者命令衛兵監禁所有批評他的人。",""]],"l3-0331":[["名詞：卓越","outstanding quality","The school received an award for excellence in music education.","學校因音樂教育表現卓越而獲獎。",""]],"l3-0332":[["及物動詞：交換","swap / trade","We exchanged phone numbers so we could arrange another meeting.","我們交換了電話號碼，好安排下次見面。",""]],"l3-0333":[["名詞：展覽","show / display","The art exhibition includes paintings by several local high school students.","這場藝術展展出了幾位當地高中生的畫作。",""]],"l3-0334":[["名詞：存在","being","The old map provides evidence of the village's existence three centuries ago.","那張舊地圖證明，這座村莊在三百年前就已存在。",""]],"l3-0335":[["名詞：出口","way out","A green sign above the door marks the nearest exit.","門上方的綠色標誌標示出最近的出口。",""]],"l3-0336":[["名詞：期待","hopes","The team trained hard, knowing that fans had high expectations for the season.","球隊知道球迷對這個賽季寄予厚望，因此努力訓練。","此處 expectations 指期望達到的結果，常用複數。"]],"l3-0337":[["名詞：開銷","cost / expenditure","Rent has been our biggest monthly expense since we moved to the city.","搬到城市後，房租成了我們每月最大的開銷。",""]],"l3-0338":[["名詞：實驗","test / trial","The students repeated the experiment to check whether the results were consistent.","學生們重做了實驗，確認結果是否一致。",""]],"l3-0339":[["及物動詞：使爆炸","detonate / set off","The demolition team exploded the charges after clearing the area.","拆除小組淨空現場後，引爆了炸藥。",""]],"l3-0340":[["名詞：出口貿易","無直接同義詞","The company grows flowers for export to several neighboring countries.","公司種植花卉，供出口至幾個鄰國。",""]],"l3-0341":[["名詞：表達方式","wording / phrase","The expression she chose sounded too formal for a friendly invitation.","她選用的措辭對一封朋友間的邀請來說太正式了。",""]],"l3-0342":[["形容詞：表情豐富的","animated","His expressive face made it easy to understand the character's feelings.","他豐富的臉部表情，讓人很容易理解角色的感受。",""]],"l3-0343":[["名詞：極端","無直接同義詞","The weather swung from one extreme to another during our mountain trip.","山區旅行期間，天氣從一個極端變到另一個極端。",""]],"l3-0344":[["名詞：寓言","moral tale / parable","The teacher read a fable about a fox who could not reach some grapes.","老師讀了一則狐狸吃不到葡萄的寓言。","parable 常以人類故事傳達道德或宗教教訓；fable 常使用動物角色。"]],"l3-0345":[["名詞：因素","element / consideration","Price was an important factor when we chose our new refrigerator.","挑選新冰箱時，價格是一個重要因素。",""]],"l3-0346":[["不及物動詞：褪色","lose color / pale","The curtains faded after years of hanging in direct sunlight.","窗簾多年受到陽光直射，已經褪色了。",""]],"l3-0347":[["形容詞：暈眩欲倒的","lightheaded / dizzy","She felt faint after standing in the hot sun for an hour.","在烈日下站了一小時後，她感到頭暈，幾乎要昏倒。",""]],"l3-0348":[["副詞：相當；還算","reasonably / quite","The station is fairly close, so we can walk there.","車站還算近，我們可以走過去。","原稿詞性 adj 有誤；fairly 是副詞。本義表示程度中等，並非非常。"]],"l3-0349":[["名詞：仙子；小精靈","sprite / pixie","The fairy in the story hides inside a bright yellow flower.","故事中的小精靈躲在一朵鮮黃色的花裡。","sprite、pixie 在不同傳說中形象可能不同。"]],"l3-0350":[["名詞：信任","trust / confidence","The coach never lost faith in the young goalkeeper's ability.","教練始終相信那位年輕守門員的能力。",""]],"l3-0351":[["及物動詞：假裝","feign / pretend to have","He faked a headache because he wanted to leave the meeting early.","他假裝頭痛，因為想提早離開會議。",""]],"l3-0352":[["形容詞：熟悉的","recognizable / well-known","Her voice sounded familiar, but I could not remember her name.","她的聲音聽來很熟悉，但我想不起她的名字。",""]],"l3-0353":[["名詞：迷；愛好者","enthusiast / admirer","A young fan waited outside the theater hoping to meet the singer.","一位年輕歌迷在劇院外等候，希望能見到那位歌手。","fanatic 通常帶狂熱、過度的意味，不宜一律替換 fan。"]],"l3-0354":[["名詞：喜愛（take a fancy to）","liking / fondness","My daughter took a fancy to the red boots in the window.","女兒看上了櫥窗裡那雙紅色靴子。",""]],"l3-0355":[["名詞：車船等票價","transport charge","The bus fare includes one free transfer within an hour.","公車票價包含一小時內一次免費轉乘。",""]],"l3-0356":[["副詞：更遠地","further","We walked farther along the beach to find a quiet spot.","我們沿著海灘多走了一段，尋找安靜的地方。","farther 常用於實際距離；further 也可用於此義。"]],"l3-0357":[["名詞：時尚","style / vogue","The museum traces changes in fashion through clothing from different decades.","博物館透過不同年代的服裝，呈現時尚的演變。",""]],"l3-0358":[["形容詞：時髦的","stylish / trendy","The shop sells fashionable bags made from recycled materials.","那家店販售以回收材料製成的時髦包款。",""]],"l3-0359":[["及物動詞：扣緊；繫牢","secure","Fasten your helmet strap before you start riding down the hill.","騎車下坡前，先扣好安全帽的帶子。",""]],"l3-0360":[["名詞：命運","destiny","A chance meeting at the station changed the young musician's fate.","車站的一次偶遇改變了那位年輕音樂家的命運。",""]],"l3-0361":[["名詞：水龍頭","tap","Please turn off the faucet while you brush your teeth.","刷牙時，請關掉水龍頭。","faucet 主要用於美式英語，tap 常見於英式英語。"]],"l3-0362":[["名詞：傳真機","fax machine","The office still has a fax beside the old photocopier.","辦公室裡，舊影印機旁還放著一台傳真機。",""]],"l3-0363":[["名詞：羽毛","plume","A white feather floated down from the bird's open wings.","一根白色羽毛從鳥張開的翅膀上飄落。","plume 常指較大或具有裝飾性的羽毛。"]],"l3-0364":[["名詞：特色","無直接同義詞","The apartment's best feature is its large balcony overlooking the park.","這間公寓最大的特色，是能俯瞰公園的大陽臺。",""]],"l3-0365":[["名詞：電腦檔案","無直接同義詞","Save a copy of the file before making any changes.","修改之前，先另存一份檔案。",""]],"l3-0366":[["名詞：煙火","無直接同義詞","A single firework burst above the river, lighting up the boats.","一枚煙火在河面上空綻放，照亮了船隻。",""]],"l3-0367":[["名詞：拳頭","無直接同義詞","The little boy held a smooth stone tightly in his fist.","小男孩把一顆光滑的石頭緊緊握在拳頭裡。",""]],"l3-0368":[["名詞：火焰","無直接同義詞","A small blue flame burned beneath the pot on the stove.","爐上的鍋子下方燃著一簇小小的藍色火焰。",""]],"l3-0369":[["名詞：味道","taste","A little lemon juice gives the soup a fresh flavor.","加一點檸檬汁，湯的味道就會更清新。",""]],"l3-0370":[["名詞：跳蚤","無直接同義詞","The vet found a flea in the kitten's thick fur.","獸醫在小貓濃密的毛裡找到一隻跳蚤。",""]],"l3-0371":[["名詞：果肉","pulp","The ripe peach had soft yellow flesh beneath its thin skin.","那顆熟桃的薄皮下是柔軟的黃色果肉。","本句示範 flesh 的果肉義，不是人體肌肉義。"]],"l3-0372":[["不及物動詞：漂浮","drift","A red balloon floated above the crowd at the festival.","一顆紅色氣球在慶典的人群上方飄浮。","float 著重浮在空中或水面；drift 著重隨氣流或水流移動。"]],"l3-0373":[["名詞：鳥群","無直接同義詞","A flock of geese flew low over the quiet lake.","一群雁低飛掠過平靜的湖面。",""]],"l3-0374":[["及物動詞：摺疊","double over","Fold the paper in half before cutting along the edge.","先把紙對摺，再沿著邊緣剪。",""]],"l3-0375":[["名詞：人們","people","The local folk welcomed us with hot tea and homemade bread.","當地人用熱茶和自製麵包歡迎我們。","folk 較口語，常見於 local folk 或 folks。"]],"l3-0376":[["名詞：追隨者","supporter / disciple","The reformer's followers gathered in the square to hear her speak.","改革者的追隨者聚集在廣場，聆聽她演說。","disciple 常表示接受某人的學說或宗教教導。"]],"l3-0377":[["形容詞：喜愛的","keen on","My uncle is fond of old films with quiet, gentle humor.","叔叔喜歡帶有含蓄溫和幽默的老電影。","fond of 後接名詞或動名詞；近義片語 keen on 對應整個 fond of，替換時不要再加 of。"]],"l3-0378":[["名詞：額頭","brow","He rested a cool cloth on his forehead after the long hike.","長途健行後，他把一條涼毛巾敷在額頭上。",""]],"l3-0379":[["副詞：永遠","always / eternally","She promised to keep the letters forever in a special wooden box.","她答應把那些信永遠保存在一個特別的木盒裡。",""]],"l3-0380":[["副詞：向前；向外（書面用法）","forward / out","At sunrise, the travelers set forth on the next stage of their journey.","日出時，旅人們啟程前往下一段旅途。","set forth 表示出發；forth 單獨使用較書面。"]],"l3-0381":[["名詞：大筆財富","wealth / riches","He made a fortune by developing a popular computer game.","他開發了一款熱門電腦遊戲，賺了一大筆錢。",""]],"l3-0382":[["及物動詞：創立","establish / set up","Three teachers founded the school to serve children in remote villages.","三位老師創辦了這所學校，為偏遠村莊的孩子提供教育。","found 的過去式為 founded，與 find 的過去式 found 不同。"]],"l3-0383":[["名詞：噴泉","無直接同義詞","Children watched the water rise and fall in the square's fountain.","孩子們看著廣場噴泉裡的水柱升起又落下。",""]],"l3-0384":[["不及物動詞：結冰","turn to ice / ice over","The shallow pond froze during the coldest week of winter.","冬天最冷的那一週，淺池塘結冰了。",""]],"l3-0385":[["形容詞：頻繁的","occurring often","Frequent buses make it easy to travel between the campus and downtown.","班次密集的公車讓往返校園與市中心很方便。","frequent 著重發生次數多；regular 著重規律，未必頻繁。"]],"l3-0386":[["名詞：友誼","companionship / fellowship","Their friendship grew stronger during the year they shared an apartment.","合租公寓的那一年，他們的友誼更加深厚。",""]],"l3-0387":[["及物動詞：阻撓","thwart / foil","Heavy snow frustrated our plans to reach the mountain village before dark.","大雪打亂了我們在天黑前抵達山村的計畫。",""]],"l3-0388":[["及物動詞：油煎；油炒","無直接同義詞","Fry the mushrooms in a little butter until they turn golden.","用少許奶油把蘑菇煎到金黃色。","sauté、deep-fry 各指不同油量與方式，不能一律互換。"]],"l3-0389":[["名詞：專用基金","reserve / pool of money","The school created a fund to help students buy musical instruments.","學校設立了一筆基金，協助學生購買樂器。",""]],"l3-0390":[["名詞：動物的毛","coat","The cat's thick fur kept it warm during the cold winter.","那隻貓濃密的毛讓牠在寒冬中保持溫暖。","coat 可指動物身上的毛；pelt 常指連皮的毛皮。"]],"l3-0391":[["不可數名詞：家具","furnishings","We moved the furniture away from the walls before painting the room.","粉刷房間前，我們把家具移離牆邊。","furnishings 也可能包括窗簾等室內用品，範圍較廣。"]],"l3-0392":[["名詞：加侖","無直接同義詞","The large container holds five gallons of water for our camping trip.","那個大容器裝有五加侖的水，供露營時使用。","美制和英制加侖容量不同。"]],"l3-0393":[["不及物動詞：賭博","bet / wager","He used to gamble on horse races every weekend.","他以前每個週末都會賭賽馬。",""]],"l3-0394":[["名詞：幫派","criminal group","The police arrested three members of the gang near the harbor.","警方在港口附近逮捕了三名幫派成員。",""]],"l3-0395":[["名詞：缺口","opening / break","The dog squeezed through a narrow gap in the fence.","那隻狗從圍欄的一個狹窄缺口鑽了過去。",""]],"l3-0396":[["不可數名詞：大蒜","無直接同義詞","Add two cloves of garlic to the soup for extra flavor.","在湯裡加入兩瓣大蒜，增添風味。",""]],"l3-0397":[["不可數名詞：汽油","petrol / gas","We stopped for gasoline before beginning the long drive through the mountains.","開始漫長的山區車程前，我們停下來加汽油。","petrol 主要為英式；gas 是美式口語。"]],"l3-0398":[["名詞：手勢","signal / motion","With a quick gesture, the guide asked us to remain silent.","導遊迅速打了個手勢，要我們保持安靜。",""]],"l3-0399":[["不及物動詞：瞥一眼","look briefly","She glanced at her watch before ordering another cup of coffee.","再點一杯咖啡之前，她先瞥了一眼手錶。","glance at something。"]],"l3-0400":[["形容詞：全球的","worldwide","The company built a global network of suppliers over many years.","那家公司花了多年建立全球供應商網絡。","原稿只列較少用的球狀義；本句補充常用全球義。球狀義近義為 spherical。"]],"l3-0401":[["名詞：榮耀","honor / acclaim","The runners shared the glory of winning their country's first relay medal.","跑者們一同分享為國家贏得首面接力賽獎牌的榮耀。",""]],"l3-0402":[["不及物動詞：發出柔和光芒","shine / gleam","The lanterns glowed softly along the path through the garden.","燈籠沿著穿過花園的小徑，散發柔和的光。",""]],"l3-0403":[["名詞：八卦","rumor / hearsay","Please do not spread gossip about people you hardly know.","請不要散播關於那些你幾乎不認識的人的八卦。","rumor 指未證實的消息；gossip 多關於私人生活。"]],"l3-0404":[["名詞：州長","無直接同義詞","The governor visited the town to inspect damage from the flood.","州長到鎮上視察洪水造成的災情。",""]],"l3-0405":[["名詞：長禮服","evening dress","She chose a dark green gown for the charity dinner.","她挑了一件深綠色長禮服，準備參加慈善晚宴。",""]],"l3-0406":[["及物動詞：迅速抓住","seize / snatch","He grabbed the railing as the boat suddenly began to rock.","船突然開始搖晃時，他一把抓住了欄杆。",""]],"l3-0407":[["形容詞：逐漸的","slow / progressive","There has been a gradual increase in visitors since the museum reopened.","博物館重新開放以來，遊客人數逐漸增加。",""]],"l3-0408":[["及物動詞：授予畢業資格（美式）","無直接同義詞","The college graduated its first group of nursing students last summer.","那所學院去年夏天授予首批護理系學生畢業資格。","此句用美式及物用法；學生畢業常用 graduate from。"]],"l3-0409":[["名詞：穀粒","kernel","A few grains of rice had fallen onto the kitchen floor.","幾粒米掉到了廚房地板上。",""]],"l3-0410":[["名詞：公克","gramme","The recipe calls for fifty grams of butter and two eggs.","食譜需要五十公克奶油和兩顆蛋。","gramme 是較少見的英式拼字。"]],"l3-0411":[["及物動詞：理解","understand / comprehend","It took me a while to grasp how the new ticket machine worked.","我花了一點時間才弄懂新售票機怎麼用。",""]],"l3-0412":[["名詞：蚱蜢","無直接同義詞","A grasshopper leaped from the path into the tall grass.","一隻蚱蜢從小徑跳進了高草叢裡。","locust 指某些會群聚的蝗蟲，不可一律替換。"]],"l3-0413":[["名詞：溫室","glasshouse / hothouse","The seedlings stayed in the greenhouse until the nights became warmer.","幼苗一直放在溫室裡，直到夜晚轉暖。","hothouse 常指人工加溫的溫室。"]],"l3-0414":[["不及物動詞：咧嘴笑","smile broadly / beam","The boy grinned when he saw his birthday cake shaped like a train.","男孩看到火車造型的生日蛋糕，開心得咧嘴笑了。",""]],"l3-0415":[["名詞：食品雜貨店","grocery store","A small grocery on the corner sells fresh bread every morning.","轉角的小雜貨店每天早上都販售新鮮麵包。",""]],"l3-0416":[["名詞：監護人","custodian / legal caretaker","A legal guardian signed the consent form for the child’s surgery.","法定監護人替孩子的手術同意書簽名。","guardian 指依法負責照顧未成年人的人。"]],"l3-0417":[["名詞：指導","advice / direction","With her teacher's guidance, she learned to organize her ideas clearly.","在老師指導下，她學會了清楚組織自己的想法。",""]],"l3-0418":[["不可數名詞：口香糖","chewing gum","He offered me a piece of gum after we finished lunch.","吃完午餐後，他給了我一片口香糖。",""]],"l3-0419":[["名詞：體育館","gym / sports hall","The basketball practice moved to the gymnasium when it started raining.","開始下雨後，籃球練習移到了體育館。",""]],"l3-0420":[["名詞：美髮師","hairstylist / stylist","My hairdresser suggested a shorter style that would be easier to manage.","美髮師建議我換成比較容易整理的短髮造型。",""]],"l3-0421":[["名詞：走廊","corridor / passageway","Leave your wet shoes in the hallway outside the classroom.","把濕鞋子留在教室外的走廊上。",""]],"l3-0422":[["名詞：一把的量","無直接同義詞","She tossed a handful of seeds onto the ground for the birds.","她在地上撒了一把種子給鳥吃。",""]],"l3-0423":[["形容詞：在手邊的","nearby / within reach","Keep a flashlight handy in case the power goes out.","把手電筒放在隨手可取的地方，以防停電。",""]],"l3-0424":[["名詞：港灣；海港","port / haven","The cargo ship waited in the harbor while customs inspected its containers.","海關檢查貨櫃時，貨船在港灣等待。","harbor 可指船隻停泊的港口，也可作動詞庇護。"]],"l3-0425":[["不可數名詞：傷害","damage / injury","The fallen branch caused no harm to anyone in the park.","掉落的樹枝沒有傷到公園裡任何人。",""]],"l3-0426":[["形容詞：有害的","damaging / detrimental","The spilled chemicals could be harmful to fish in the river.","外洩的化學物質可能對河裡的魚造成傷害。",""]],"l3-0427":[["及物動詞：收成","gather / reap","The farmers harvested the rice before the heavy rains began.","大雨開始前，農夫們收割了稻米。",""]],"l3-0428":[["形容詞：倉促的","hurried / rushed","A hasty decision to leave early meant we forgot the tickets.","我們匆忙決定提早出門，結果忘了帶票。",""]],"l3-0429":[["及物動詞：孵出","無直接同義詞","The hen hatched six chicks in the quiet corner of the barn.","母雞在穀倉安靜的角落孵出了六隻小雞。",""]],"l3-0430":[["名詞：鷹","無直接同義詞","A hawk circled above the field, searching for movement below.","一隻鷹在田野上空盤旋，尋找下方的動靜。","falcon、eagle 為不同鳥類名稱，不能當完全同義詞。"]],"l3-0431":[["名詞：乾草","無直接同義詞","The horses pulled hay from a large net beside the fence.","馬兒從圍欄旁的一個大網袋裡扯出乾草吃。",""]],"l3-0432":[["名詞：新聞標題","heading / title","The headline caught my attention as I walked past the newsstand.","我經過報攤時，那則新聞的標題吸引了我的注意。",""]],"l3-0433":[["名詞：總部","head office","The company moved its headquarters into a larger building downtown.","公司把總部搬進市中心一棟更大的大樓。","headquarters 單複數同形。"]],"l3-0434":[["及物動詞：療癒","mend","Years of patient conversation helped heal the divisions within the family.","多年耐心的溝通，幫助這個家庭修復了彼此的裂痕。","此處 heal 為比喻用法，指修復關係。"]],"l3-0435":[["名詞：一堆","pile / mound","A heap of dirty clothes lay beside the washing machine.","一堆髒衣服放在洗衣機旁邊。",""]],"l3-0436":[["名詞：天堂","paradise","The child asked whether her grandmother could see the stars from heaven.","孩子問，祖母在天堂是否看得到星星。","paradise 的宗教意涵因傳統而異。"]],"l3-0437":[["名詞：腳跟","無直接同義詞","The new shoes rubbed against my heels during the long walk.","長途步行時，新鞋磨到了我的腳跟。",""]],"l3-0438":[["名詞：地獄","the infernal realm","The painting shows frightened figures descending into the fires of hell.","畫中描繪驚恐的人物墜入地獄烈火。","本句採宗教中的地獄義。"]],"l3-0439":[["名詞：安全帽；頭盔","無直接同義詞","The worker checked his helmet before entering the construction site.","工人進入工地前，先檢查了安全帽。",""]],"l3-0440":[["不及物動詞：猶豫","pause / waver","She hesitated before answering because she did not want to hurt his feelings.","她回答前猶豫了一下，因為不想傷害他的感受。",""]],"l3-0441":[["不及物動詞：健行","trek / walk","We hiked through the forest to a waterfall hidden behind the rocks.","我們穿越森林健行，走到一座藏在岩石後的瀑布。","trek 常指較長或辛苦的徒步旅程。"]],"l3-0442":[["名詞：提示","clue / suggestion","The teacher gave us a hint without revealing the answer.","老師給了我們一個提示，卻沒有透露答案。",""]],"l3-0443":[["名詞：歷史學家","無直接同義詞","A local historian helped us identify the buildings in the old photograph.","一位地方歷史學家幫我們辨認老照片裡的建築。",""]],"l3-0444":[["形容詞：具有歷史意義的","momentous / landmark","The two leaders signed a historic agreement to end the conflict.","兩位領導人簽署了具有歷史意義的協議，結束衝突。","historic 強調重要性；historical 只表示與歷史有關。"]],"l3-0445":[["形容詞：與歷史有關的","無直接同義詞","The novelist studied historical records before writing about the old port.","小說家在描寫那座老港口前，先研究了歷史紀錄。",""]],"l3-0446":[["名詞：蜂巢；蜂箱","beehive","The beekeeper carefully removed a wooden frame from the hive.","養蜂人小心地從蜂箱裡取出一個木框。",""]],"l3-0447":[["形容詞：中空的","empty inside","The children used a hollow log as a hiding place.","孩子們把一根中空的樹幹當作藏身處。",""]],"l3-0448":[["形容詞：神聖的","sacred","Visitors removed their shoes before entering the holy building.","訪客進入那座神聖的建築前先脫下鞋子。",""]],"l3-0449":[["名詞：家鄉","home town","She returns to her hometown every spring to visit her grandparents.","她每年春天都回家鄉探望祖父母。","home town 是分寫形式。"]],"l3-0450":[["名詞：誠實","truthfulness / integrity","His honesty impressed the owner when he returned the extra change.","他退還多找的零錢時，那份誠實讓店主留下深刻印象。","integrity 還含堅守道德原則之意。"]],"l3-0451":[["名詞：榮幸","privilege","It was an honor to perform with musicians I had admired for years.","能與我仰慕多年的音樂家一起演出，讓我深感榮幸。",""]],"l3-0452":[["名詞：動物的角","無直接同義詞","The goat caught one horn in the wire fence behind the shed.","山羊的一隻角卡在棚屋後方的鐵絲圍欄裡。",""]],"l3-0453":[["形容詞：糟糕的","terrible / dreadful","A horrible smell came from the food left in the broken refrigerator.","留在壞冰箱裡的食物散發出難聞的氣味。",""]],"l3-0454":[["名詞：恐懼","terror / dread","We watched in horror as the car slid toward the river.","我們驚恐地看著那輛車滑向河裡。",""]],"l3-0455":[["形容詞：按小時計的","per-hour","The hourly parking rate rises after the first two hours.","停車超過前兩小時後，每小時的費率會提高。",""]],"l3-0456":[["名詞：家務管理員；管家","無直接同義詞","The housekeeper prepared the guest rooms before the family arrived.","那家人抵達前，管家整理好了客房。","housekeeper 通常指受僱管理或清潔居所者，不等於 housewife。"]],"l3-0457":[["及物動詞：擁抱","embrace / hold close","She hugged her younger brother tightly when he returned from overseas.","弟弟從海外回來時，她緊緊抱住了他。",""]],"l3-0458":[["形容詞：幽默的","funny / amusing","His humorous account of the camping trip made everyone laugh.","他幽默地講述露營經過，逗得大家哈哈大笑。",""]],"l3-0459":[["名詞：寂靜","silence / stillness","A hush fell over the hall as the singer approached the microphone.","歌手走近麥克風時，大廳裡安靜了下來。",""]],"l3-0460":[["名詞：簡陋小屋","shack / cabin","The hikers sheltered in a wooden hut until the rain stopped.","健行者躲在一間木屋裡，等到雨停才離開。",""]],"l3-0461":[["形容詞：結冰的","frozen / ice-covered","The road was icy, so the driver slowed down before the bend.","路面結冰，所以駕駛在轉彎前減速。",""]],"l3-0462":[["形容詞：理想的","perfect / optimal","The quiet room is ideal for students who need to concentrate.","這間安靜的房間很適合需要專心的學生。",""]],"l3-0463":[["名詞：身分","無直接同義詞","The receptionist asked for a passport to confirm the guest's identity.","櫃檯人員請房客出示護照，以確認身分。",""]],"l3-0464":[["名詞：不了解；無知","lack of knowledge / unfamiliarity","My ignorance of local customs led to an embarrassing mistake.","我不了解當地習俗，因而犯了令人尷尬的錯。","ignorance of something；unfamiliarity with something，替換時介系詞也要調整。"]],"l3-0465":[["名詞：形象","reputation / public impression","The company hopes its new packaging will improve its public image.","公司希望新包裝能改善它的公眾形象。",""]],"l3-0466":[["名詞：想像力","inventiveness / creativity","The cardboard castle showed how much imagination the children had.","那座紙板城堡展現了孩子們豐富的想像力。",""]],"l3-0467":[["形容詞：立即的","instant / prompt","The leaking roof needs immediate attention before the next storm arrives.","下一場暴風雨來臨前，漏水的屋頂必須立刻處理。",""]],"l3-0468":[["名詞：進口","importation","The country placed new limits on the import of used vehicles.","該國對二手車進口設下了新的限制。",""]],"l3-0469":[["及物動詞：使留下深刻好印象","make an impression on","Her careful preparation impressed everyone on the interview panel.","她周全的準備讓所有面試委員留下深刻的好印象。",""]],"l3-0470":[["形容詞：令人印象深刻的","remarkable / striking","The view from the tower was even more impressive at sunset.","日落時，塔上的景色更加令人驚豔。",""]],"l3-0471":[["副詞：確實","certainly / truly","The path was steep indeed, and we stopped several times to rest.","那條小路確實很陡，我們停下來休息了好幾次。",""]],"l3-0472":[["名詞：個人","person","Each individual in the group will receive a separate feedback form.","小組裡的每個人都會收到一份個別的意見表。",""]],"l3-0473":[["形容詞：室內的","無直接同義詞","The hotel has an indoor pool that stays open all year.","飯店有一座全年開放的室內游泳池。",""]],"l3-0474":[["副詞：在室內","inside","We stayed indoors and played cards while the storm passed.","暴風雨經過時，我們待在室內打牌。",""]],"l3-0475":[["形容詞：工業的","無直接同義詞","Several old factories in the industrial district have become art studios.","工業區裡幾座老工廠已改成藝術工作室。",""]],"l3-0476":[["形容詞：品質較差的","poorer / lower-quality","The cheaper paint was inferior to the brand we usually bought.","便宜的油漆品質不如我們平常買的品牌。","inferior to，不用 inferior than。"]],"l3-0477":[["及物動詞：通知","notify / tell","Please inform the office if your mailing address changes.","通訊地址變更時，請通知辦公室。",""]],"l3-0478":[["及物動詞：使受傷","hurt / wound","A falling tile injured a worker standing near the entrance.","一塊掉落的磁磚砸傷了站在入口附近的工人。",""]],"l3-0479":[["名詞：傷勢","physical harm","The player missed the final match because of a knee injury.","那位球員因膝傷錯過了決賽。","injury 常可數，harm 通常不可數；wound 特指傷口，不涵蓋所有傷勢。"]],"l3-0480":[["名詞：小旅館","small hotel / lodge","We spent the night at an inn beside the mountain road.","我們在山路旁的一間小旅館住了一晚。",""]],"l3-0481":[["形容詞：內側的","inside / interior","The inner pocket of my jacket is large enough for a passport.","我的外套內袋夠大，可以放一本護照。",""]],"l3-0482":[["形容詞：無罪的","not guilty / blameless","The new evidence proved that the accused woman was innocent.","新的證據證明，那位被指控的女子是無辜的。",""]],"l3-0483":[["及物動詞：仔細檢查","examine / check","The mechanic inspected the tires before we began the long journey.","長途旅行開始前，技師檢查了輪胎。",""]],"l3-0484":[["名詞：檢查員","examiner","The building inspector found several cracks in the basement walls.","建築檢查員在地下室牆上發現了幾處裂縫。",""]],"l3-0485":[["副詞：改為；代替","as an alternative","The restaurant was full, so we bought sandwiches and ate in the park instead.","餐廳客滿，所以我們改買三明治，到公園吃。","此處提供近義片語，表示改採另一做法。alternatively 常用來提出另一個選項，不適合直接替換本句句尾的 instead。"]],"l3-0486":[["名詞：操作說明（常用複數）","directions / guidelines","Follow the instructions carefully when assembling the new bookshelf.","組裝新書架時，要仔細依照說明操作。",""]],"l3-0487":[["形容詞：內部的","inner / interior","An internal wall separates the kitchen from the dining area.","一道內牆把廚房與用餐區隔開。",""]],"l3-0488":[["及物動詞：打斷","disrupt / cut short","A loud announcement interrupted our conversation at the train station.","火車站一則大聲的廣播打斷了我們的談話。",""]],"l3-0489":[["名詞：介紹；引言","opening remarks","After a brief introduction, the speaker began explaining her research.","簡短介紹後，講者開始說明她的研究。","此句採口頭引言義。"]],"l3-0490":[["名詞：發明者","creator / originator","The inventor demonstrated a device that helps people carry heavy boxes upstairs.","發明者展示了一種能幫人把重箱子搬上樓的裝置。",""]],"l3-0491":[["及物動詞：調查","look into / examine","The school will investigate the cause of the sudden power failure.","學校將調查突然停電的原因。",""]],"l3-0492":[["名詞：象牙","無直接同義詞","The antique piano had keys made from ivory and dark wood.","那架古董鋼琴的琴鍵由象牙和深色木材製成。",""]],"l3-0493":[["名詞：監獄；拘留所","prison / detention center","He spent three months in jail before the court reviewed his case.","法院重新審查他的案件前，他在拘留所待了三個月。","jail 與 prison 的制度差異依地區而定。"]],"l3-0494":[["名詞：廣口罐","無直接同義詞","She stored the homemade jam in a clean glass jar.","她把自製果醬裝進乾淨的玻璃罐裡。",""]],"l3-0495":[["名詞：顎部","無直接同義詞","His jaw ached after the dentist asked him to keep his mouth open.","牙醫請他一直張著嘴後，他的顎部感到痠痛。","jaw 指顎或顎骨；chin 特指下巴前端，不能一律互換。"]],"l3-0496":[["形容詞：嫉妒的","envious","She felt jealous when her younger brother received a new bicycle.","弟弟收到新自行車時，她覺得很嫉妒。",""]],"l3-0497":[["名詞：果凍（英式）","gelatin dessert","The children made orange jelly in small cups for the party.","孩子們用小杯子做了柳橙果凍，準備在派對上吃。","美式 jelly 也常指透明果醬；本句採甜點義。"]],"l3-0498":[["名詞：噴射機","jet aircraft / jet plane","A private jet landed at the small airport just before sunset.","日落前，一架私人噴射機降落在小機場。",""]],"l3-0499":[["名詞：寶石","gem / gemstone","A blue jewel sparkled at the center of the silver necklace.","銀項鍊中央有一顆藍色寶石閃閃發光。",""]],"l3-0500":[["不可數名詞：珠寶首飾","jewellery","She keeps her jewelry in a small box lined with velvet.","她把首飾放在一個內襯天鵝絨的小盒子裡。","jewellery 為英式拼字；jewelry 不可數。"]],"l3-0501":[["名詞：日記","diary","During the trip, I kept a journal of places we visited.","旅行期間，我寫日記記錄去過的地方。",""]],"l3-0502":[["名詞：旅程","trip","The journey across the island took longer than we expected.","橫越島嶼的旅程比我們預期的更久。",""]],"l3-0503":[["形容詞：喜悅的","delighted / happy","The joyful children ran outside when they saw the first snow.","孩子們看到初雪，歡喜地跑到屋外。",""]],"l3-0504":[["名詞：熱帶密林","tropical forest","Our guide cut a narrow path through the dense jungle.","導遊在茂密的叢林中劈開一條狹窄的路。",""]],"l3-0505":[["不可數名詞：廢物；破爛","rubbish / trash","We cleared years of junk out of the garage on Saturday.","星期六，我們清掉了車庫裡堆積多年的破爛。","此義是無用物品，並非 counterfeit（仿冒品）。"]],"l3-0506":[["名詞：公平；正義","fairness / equity","The story raises questions about justice and the unequal treatment of workers.","這個故事提出了關於正義與工人遭受不平等待遇的問題。",""]],"l3-0507":[["名詞：袋鼠","無直接同義詞","A kangaroo with a baby in its pouch rested beneath the tree.","一隻育兒袋裡帶著小袋鼠的母袋鼠在樹下休息。",""]],"l3-0508":[["名詞：煮水壺","無直接同義詞","The kettle began to whistle just as our guests arrived.","客人剛到，煮水壺就開始發出笛聲。",""]],"l3-0509":[["名詞：電腦鍵盤","無直接同義詞","Crumbs fell between the keys when he ate lunch at his keyboard.","他在鍵盤前吃午餐時，食物碎屑掉進了按鍵縫裡。",""]],"l3-0510":[["名詞：腎臟","無直接同義詞","The doctor pointed to a kidney on the model of the human body.","醫師指著人體模型上的一個腎臟。",""]],"l3-0511":[["名詞：公斤","kilo","This bag of flour weighs one kilogram according to the label.","根據標籤，這袋麵粉重一公斤。","kilo 是口語簡稱。"]],"l3-0512":[["名詞：公里","kilometre","The nearest bus stop is about half a kilometer from our house.","最近的公車站離我們家大約半公里。","kilometre 為英式拼字。"]],"l3-0513":[["名詞：成套工具用品","equipment set","Each student received a sewing kit with needles, thread, and small scissors.","每位學生都收到一組縫紉工具，裡面有針、線和小剪刀。",""]],"l3-0514":[["不及物動詞：跪下","get down on one's knees","He knelt beside the garden bed to pull out the weeds.","他跪在花圃旁，把雜草拔掉。","過去式可用 knelt 或 kneeled。"]],"l3-0515":[["名詞：騎士","無直接同義詞","The knight rode across the wooden bridge toward the castle gate.","騎士騎馬越過木橋，朝城堡大門前進。",""]],"l3-0516":[["及物動詞：編織","無直接同義詞","My aunt knitted a warm scarf for me before winter arrived.","冬天來臨前，阿姨為我織了一條暖和的圍巾。","knit 是用棒針等編織；weave、crochet 技法不同。"]],"l3-0517":[["名詞：球形門把","doorknob","The door would not open even when I turned the knob fully.","即使我把門把轉到底，門還是打不開。",""]],"l3-0518":[["名詞：繩結","無直接同義詞","Tie a firm knot so the bag will not open during the trip.","打個牢固的結，袋子才不會在旅途中鬆開。",""]],"l3-0519":[["名詞：標籤","tag","The label inside the coat explains how to wash it safely.","外套內的標籤說明了如何妥善清洗。",""]],"l3-0520":[["名詞：鞋帶","shoelace","One lace came undone as she ran toward the bus.","她跑向公車時，一條鞋帶鬆開了。",""]],"l3-0521":[["名詞：梯子","無直接同義詞","We needed a ladder to reach the highest shelf in the storeroom.","我們需要一架梯子，才搆得到儲藏室最高的層架。",""]],"l3-0522":[["形容詞：後者的","second-mentioned","Of the two routes, the latter option takes us along the river.","兩條路線中，後者會帶我們沿著河邊走。","latter 指兩者中的後者；later 表示較晚。"]],"l3-0523":[["不可數名詞：笑聲","laughing","The room filled with laughter when the puppy stole his slipper.","小狗叼走他的拖鞋時，房間裡充滿了笑聲。",""]],"l3-0524":[["不可數名詞：洗好的衣物","washing","She hung the laundry outside while the sun was still shining.","趁太陽還在，她把洗好的衣服晾到外面。",""]],"l3-0525":[["名詞：草坪","無直接同義詞","The children spread a blanket on the lawn for their picnic.","孩子們把毯子鋪在草坪上準備野餐。",""]],"l3-0526":[["名詞：漏水處","無直接同義詞","The plumber found a leak in the pipe beneath the sink.","水管工在水槽下的管線找到了一處漏水點。",""]],"l3-0527":[["不及物動詞：跳躍","jump / spring","The cat leaped onto the windowsill when it heard a bird outside.","貓聽到外面有鳥叫，便跳上了窗臺。",""]],"l3-0528":[["名詞：皮革","無直接同義詞","The bag is made of soft leather with strong metal handles.","那個包包以柔軟的皮革製成，配有堅固的金屬提把。",""]],"l3-0529":[["名詞：休閒時間","free time / spare time","She spends much of her leisure reading novels beside the window.","她把大部分休閒時間用來坐在窗邊讀小說。",""]],"l3-0530":[["及物動詞：延長","extend / prolong","We decided to lengthen our stay because the village was so peaceful.","村莊十分寧靜，我們決定延長住宿時間。",""]],"l3-0531":[["名詞：鏡片；鏡頭","無直接同義詞","Clean the camera lens gently before taking pictures of the sunset.","拍攝夕陽前，先輕輕清潔相機鏡頭。",""]],"l3-0532":[["名詞：說謊者","untruthful person","Nobody trusted the witness after the evidence showed he was a liar.","證據顯示那位證人在說謊後，便沒有人相信他了。",""]],"l3-0533":[["形容詞：開明的；寬容的","open-minded / tolerant","Her parents have liberal views about how young people should dress.","對於年輕人應該如何穿著，她的父母抱持開明態度。","此處不指特定政黨或政治立場。"]],"l3-0534":[["名詞：自由","freedom","The prisoners celebrated their liberty as they walked out of the gates.","囚犯走出大門時，慶祝自己重獲自由。",""]],"l3-0535":[["名詞：圖書館員","無直接同義詞","The librarian helped me find reliable books about local history.","圖書館員幫我找到關於地方歷史的可靠書籍。",""]],"l3-0536":[["名詞：救生艇","rescue boat","The crew lowered a lifeboat to reach the people in the water.","船員放下救生艇，前去救援水中的人。",""]],"l3-0537":[["名詞：救生員","lifesaver","A lifeguard watched the swimmers from a tall chair beside the pool.","救生員坐在泳池旁的高椅上，注意游泳者的情況。","lifesaver 也可泛指救人者；lifeguard 指此職務。"]],"l3-0538":[["名詞：一生","life","Over his lifetime, he collected thousands of photographs from his travels.","他一生收藏了數千張旅行途中拍攝的照片。",""]],"l3-0539":[["名詞：燈塔","無直接同義詞","The lighthouse flashed across the bay to guide boats away from the rocks.","燈塔的光掠過海灣，引導船隻遠離礁石。",""]],"l3-0540":[["名詞：肢體","extremity","After sitting still for hours, he stretched his stiff limbs.","坐著好幾個小時沒動後，他伸展僵硬的四肢。","extremity 常特指手腳等肢體末端。"]],"l3-0541":[["不可數名詞：亞麻布","無直接同義詞","The light linen curtains let a soft breeze enter the room.","輕薄的亞麻布窗簾讓微風透進房間。",""]],"l3-0542":[["名詞：口紅","lip color","A faint mark of red lipstick remained on the white cup.","白色杯子上留著一道淡淡的紅色口紅印。",""]],"l3-0543":[["名詞：散落的垃圾","rubbish / trash","Volunteers picked up litter along the beach after the holiday weekend.","連假結束後，志工沿著海灘撿拾垃圾。",""]],"l3-0544":[["形容詞：熱鬧活潑的","animated / energetic","A lively discussion followed the film about life in the countryside.","看完描寫鄉村生活的電影後，大家展開熱烈的討論。",""]],"l3-0545":[["名詞：肝臟","無直接同義詞","The biology teacher showed us where the liver sits in the body.","生物老師向我們展示肝臟在體內的位置。",""]],"l3-0546":[["名詞：一批載運的東西","cargo / cargo load","The truck delivered a load of fresh vegetables before sunrise.","卡車在日出前送來了一批新鮮蔬菜。",""]],"l3-0547":[["名詞：大廳","foyer / entrance hall","We agreed to meet in the hotel lobby at eight.","我們約好八點在飯店大廳見面。",""]],"l3-0548":[["名詞：龍蝦","無直接同義詞","The fisherman lifted a large lobster from the trap beside his boat.","漁夫從船旁的捕籠裡提起了一隻大龍蝦。",""]],"l3-0549":[["名詞：棒棒糖","lolly / sucker","The child unwrapped a strawberry lollipop while waiting for the bus.","等公車時，那個孩子拆開了一根草莓棒棒糖。","lolly 為英式口語，sucker 為美式口語。"]],"l3-0550":[["形容詞：鬆動的","not firmly fixed","A loose screw made the chair wobble whenever I sat down.","一顆鬆動的螺絲讓椅子每次坐下都會搖晃。","loose 表示鬆動；lose 是失去，兩者不可混淆。"]],"l3-0551":[["及物動詞：鬆開","slacken","He loosened the rope so the dog could move more freely.","他鬆開繩子，讓狗能更自由地活動。","loosen 表示變鬆，不一定完全解開。"]],"l3-0552":[["名詞：領主","master / ruler","The villagers asked the local lord to repair the damaged bridge.","村民請求當地領主修復受損的橋。",""]],"l3-0553":[["名詞：擴音喇叭","speaker","An announcement came over the loudspeaker just before the race began.","比賽即將開始前，擴音喇叭傳出了一則廣播。",""]],"l3-0554":[["不可數名詞：行李","baggage","Our luggage arrived on a later flight after we reached the island.","我們抵達島嶼後，行李才隨較晚的班機送到。",""]],"l3-0555":[["名詞：搖籃曲","cradle song","She sang a gentle lullaby while rocking the baby to sleep.","她一邊輕搖寶寶哄睡，一邊唱柔和的搖籃曲。",""]],"l3-0556":[["名詞：肺","無直接同義詞","The diagram shows how air travels from the mouth into the lungs.","圖中顯示空氣如何從口部進入肺部。",""]],"l3-0557":[["形容詞：有魔法的","enchanted / magic","The children discovered a magical door that opened into another world.","孩子們發現了一扇能通往另一個世界的魔法門。",""]],"l3-0558":[["名詞：磁鐵","無直接同義詞","A small magnet holds the shopping list on our refrigerator door.","一塊小磁鐵把購物清單固定在冰箱門上。",""]],"l3-0559":[["名詞：客房清潔員（傳統稱呼）","chambermaid","The maid brought fresh towels and changed the sheets in our room.","客房清潔員送來乾淨毛巾，並換了我們房間的床單。","chambermaid 專指客房清潔員；housemaid 通常指私人住宅的女佣。maid 是較傳統稱呼。"]],"l3-0560":[["形容詞：主要的","main / principal","The lack of clean water is a major problem in the village.","缺乏乾淨用水是村莊面臨的主要問題。",""]],"l3-0561":[["名詞：過半數；大多數","greater part / most","A majority of the members voted to keep the library open later.","多數成員投票贊成延長圖書館開放時間。",""]],"l3-0562":[["名詞：購物中心","shopping center / shopping mall","The mall has a children's play area beside the food court.","購物中心在美食街旁設有兒童遊戲區。",""]],"l3-0563":[["及物動詞：設法做到","succeed in / be able to","We managed to catch the last train despite leaving the hotel late.","雖然離開飯店的時間晚了，我們仍設法趕上末班車。","manage to do；succeed in doing。"]],"l3-0564":[["名詞：管理","administration / supervision","Good management helped the small hotel recover after a difficult year.","良好的管理幫助那家小飯店在艱困的一年後重振業務。",""]],"l3-0565":[["形容詞：可處理的","controllable / workable","Dividing the project into small tasks made the work more manageable.","把專案分成小任務後，工作變得更容易處理。",""]],"l3-0566":[["名詞：經理","supervisor / person in charge","The store manager arranged extra staff for the busy holiday weekend.","店經理為忙碌的連假週末增派了人手。","supervisor 通常偏指直接督導者，職級未必相同。"]],"l3-0567":[["名詞：人類","humankind / humanity","The exhibition explores inventions that have changed the course of mankind's history.","這場展覽探討曾改變人類歷史進程的發明。","mankind 指全人類，不僅指男人；humankind、humanity 為性別中性用語。"]],"l3-0568":[["複數名詞：禮貌舉止","etiquette / courtesy","Good manners include listening carefully when another person is speaking.","別人說話時仔細聆聽，是良好禮貌的一部分。",""]],"l3-0569":[["不可數名詞：大理石","無直接同義詞","The statue was carved from white marble found in nearby mountains.","那座雕像以附近山區出產的白色大理石雕成。",""]],"l3-0570":[["名詞：遊行","procession / demonstration","Hundreds of residents joined the march to protect the old forest.","數百名居民參加遊行，要求保護那片古老森林。","demonstration 不一定採行進形式。"]],"l3-0571":[["形容詞：極好的","wonderful / splendid","The rooftop restaurant gave us a marvelous view of the harbor.","屋頂餐廳讓我們欣賞到極美的港口景色。",""]],"l3-0572":[["形容詞：數學的","無直接同義詞","She used a mathematical formula to calculate the area of the garden.","她用一個數學公式計算花園的面積。",""]],"l3-0573":[["名詞：數學","math / maths","Mathematics was his favorite subject because he enjoyed solving difficult problems.","數學是他最喜歡的科目，因為他喜歡解難題。","math 為美式簡稱，maths 為英式簡稱；學科名用單數動詞。"]],"l3-0574":[["形容詞：成熟的","fully grown / fully developed","The garden has several mature trees that provide shade all afternoon.","花園裡有幾棵成熟的大樹，整個下午都能遮蔭。",""]],"l3-0575":[["名詞：市長；鎮長","無直接同義詞","The mayor opened the new bridge with a short speech.","市長發表簡短致詞，宣布新橋啟用。",""]],"l3-0576":[["名詞：草地","grassy field","Wildflowers covered the meadow where we stopped to eat lunch.","我們停下吃午餐的那片草地，開滿了野花。","meadow 通常指開闊草地，可供割草或放牧。"]],"l3-0577":[["形容詞：有意義的","significant / worthwhile","Volunteering at the shelter gave her a meaningful way to spend weekends.","在收容中心當志工，讓她能有意義地度過週末。",""]],"l3-0578":[["名詞：這段期間（in the meanwhile）","meantime","Dinner will be ready soon; in the meanwhile, please set the table.","晚餐快好了；這段時間請先擺好餐具。","名詞常用 in the meanwhile；單獨 meanwhile 通常作副詞。"]],"l3-0579":[["名詞：獎牌；獎章","無直接同義詞","The swimmer showed her silver medal to the children at her old school.","那位游泳選手向母校的孩子展示她的銀牌。","medallion 常指較大的紀念章或圓形飾物，不能替換所有比賽獎牌。"]],"l3-0580":[["形容詞：醫療的","clinical","The village needs better medical services for its growing population.","村莊人口日增，需要更完善的醫療服務。","clinical 偏指臨床診療相關，範圍較窄。"]],"l3-0581":[["名詞：傳播媒介","channel / means of communication","Radio remains an important medium for reaching people in remote areas.","廣播仍是向偏遠地區民眾傳遞資訊的重要媒介。",""]],"l3-0582":[["及物動詞：使融化","liquefy","Melt the butter slowly before stirring it into the cake mixture.","先慢慢融化奶油，再攪入蛋糕麵糊中。",""]],"l3-0583":[["名詞：會員資格","無直接同義詞","Library membership allows residents to borrow books and use the study rooms.","擁有圖書館會員資格的居民，可以借書並使用自習室。",""]],"l3-0584":[["及物動詞：背熟","learn by heart / commit to memory","She memorized the poem by reading it aloud every evening.","她每天晚上朗讀那首詩，直到把它背熟。",""]],"l3-0585":[["及物動詞：修補","repair / fix","My grandmother taught me how to mend a torn shirt.","祖母教我如何修補破掉的襯衫。",""]],"l3-0586":[["形容詞：心理的","psychological","The coach discussed the mental pressure players face before important matches.","教練談到了球員在重要比賽前面臨的心理壓力。",""]],"l3-0587":[["及物動詞：提及","refer to / bring up","She mentioned seeing your older brother at the market yesterday.","她提到昨天在市場看見了你哥哥。",""]],"l3-0588":[["名詞：商人","trader / dealer","The merchant traveled between coastal towns selling cloth and spices.","那位商人往返沿海城鎮，販售布料和香料。",""]],"l3-0589":[["形容詞：歡樂的","cheerful / jolly","A merry group of friends sang together around the campfire.","一群快樂的朋友圍著營火一起唱歌。",""]],"l3-0590":[["名詞：凌亂","disorder / clutter","The kitchen was a mess after the children finished baking cookies.","孩子們烤完餅乾後，廚房一片凌亂。",""]],"l3-0591":[["名詞：麥克風","mic / mike","Move the microphone closer so the audience can hear you clearly.","把麥克風移近一點，觀眾才能聽清楚你的聲音。",""]],"l3-0592":[["名詞：微波爐","microwave oven","The office microwave is large enough to heat two lunch boxes together.","辦公室的微波爐夠大，可以一次加熱兩個便當。",""]],"l3-0593":[["助動詞：可能","may / could","We might take the earlier train if the meeting finishes on time.","如果會議準時結束，我們可能會搭較早的火車。","might 在此表不確定的可能性，不一定表示過去。"]],"l3-0594":[["形容詞：強大的","powerful / formidable","A mighty wave crashed against the rocks below the lighthouse.","一道巨浪猛然拍打燈塔下方的岩石。",""]],"l3-0595":[["名詞：磨坊","無直接同義詞","The old mill used river water to turn its heavy wheel.","那座老磨坊利用河水轉動沉重的水車。",""]],"l3-0596":[["名詞：百萬富翁","無直接同義詞","The young millionaire bought the house where his grandparents had once lived.","那位年輕的百萬富翁買下了祖父母曾經住過的房子。",""]],"l3-0597":[["名詞：礦工","mineworker","The miner removed his helmet after returning from the underground tunnel.","礦工從地下坑道返回後，摘下了頭盔。",""]],"l3-0598":[["形容詞：輕微的","slight / small","The bicycle needed only minor repairs after falling off the rack.","自行車從車架上掉下來後，只需小幅維修。",""]],"l3-0599":[["名詞：少數人","smaller group","Only a minority of the students chose to study abroad that year.","那一年，只有少數學生選擇出國留學。",""]],"l3-0600":[["名詞：令人驚奇的幸運事件","wonder","It was a miracle that nobody was hurt when the roof collapsed.","屋頂倒塌竟然無人受傷，真是奇蹟。","此處為日常誇飾，不一定宣稱超自然事件。"]],"l3-0601":[["名詞：痛苦","suffering / distress","The long months of separation caused great misery for the family.","長達數月的分離，讓這家人承受了極大的痛苦。",""]],"l3-0602":[["名詞：飛彈","無直接同義詞","The museum displays a missile beside several aircraft from the same period.","博物館在幾架同時期的飛機旁展出一枚飛彈。","guided missile 特指具導引功能的飛彈，範圍較窄；此句沒有交代導引方式。"]],"l3-0603":[["形容詞：失蹤的；找不到的","lost / unaccounted for","Search teams found the missing hikers near a stream before dark.","搜索隊在天黑前，於一條溪流附近找到失蹤的健行者。",""]],"l3-0604":[["名詞：任務","assignment / task","The rescue team's mission was to reach the village before nightfall.","救援隊的任務是在夜幕降臨前抵達村莊。",""]],"l3-0605":[["名詞：薄霧","light fog","Morning mist hung over the fields as the train passed.","火車經過時，田野上籠罩著晨霧。","mist 指空氣中懸浮的小水滴。"]],"l3-0606":[["名詞：混合物","blend / mix","Pour the mixture into the cake tin and smooth the top.","把混合好的麵糊倒入蛋糕模，再抹平表面。",""]],"l3-0607":[["名詞：暴民群眾","unruly crowd","The angry mob pushed past the barriers outside the palace.","憤怒的暴民推擠著越過宮殿外的圍欄。",""]],"l3-0608":[["形容詞：移動式的","traveling","A mobile library visits the remote village twice a month.","行動圖書館每月到那座偏遠村莊服務兩次。","此句 mobile 指巡迴服務，不是可拿在手中的 portable。"]],"l3-0609":[["形容詞：微濕的","damp","The soil was still moist after last night's gentle rain.","昨晚下過小雨，土壤仍然濕潤。",""]],"l3-0610":[["名詞：水分；濕氣","dampness / humidity","The tight lid helps keep moisture out of the biscuit tin.","密合的蓋子有助於防止濕氣進入餅乾罐。","humidity 常指空氣中的水氣含量。"]],"l3-0611":[["名詞：僧侶；修道士","無直接同義詞","A monk showed visitors the quiet garden behind the temple.","一位僧侶帶訪客參觀寺廟後方安靜的花園。","priest 指宗教職務，並不等於 monk。"]],"l3-0612":[["名詞：心情","state of mind / frame of mind","Her good mood disappeared when she saw the broken window.","她看到破掉的窗戶，好心情頓時消失。",""]],"l3-0613":[["名詞：拖把","無直接同義詞","Use the mop to clean up the water spilled near the doorway.","用拖把清掉門口附近灑出的水。",""]],"l3-0614":[["形容詞：道德的","ethical","The story presents a moral choice between telling the truth and protecting a friend.","故事提出了一個道德抉擇：說實話，或保護朋友。",""]],"l3-0615":[["名詞：汽車旅館","motor lodge / motor inn","We found a clean motel beside the highway and stopped for the night.","我們在公路旁找到一家乾淨的汽車旅館，住了一晚。",""]],"l3-0616":[["名詞：馬達","electric motor","The washing machine's motor made a loud noise during the final cycle.","洗衣機在最後一道程序中，馬達發出了很大的聲響。",""]],"l3-0617":[["名詞：謀殺","無直接同義詞","The detective returned to the village to investigate an unsolved murder.","偵探回到村莊，調查一宗尚未破案的謀殺案。","homicide 泛指殺人事件，法律範圍比 murder 廣。"]],"l3-0618":[["名詞：肌肉","無直接同義詞","She stretched her leg muscles before stepping onto the running track.","踏上跑道前，她伸展了腿部肌肉。",""]],"l3-0619":[["名詞：蘑菇","無直接同義詞","The farmer sells fresh mushrooms at the market every Saturday.","那位農夫每週六在市場販售新鮮蘑菇。",""]],"l3-0620":[["形容詞：音樂的","無直接同義詞","The school lends musical instruments to students who cannot afford their own.","學校把樂器借給無力自行購買的學生。",""]],"l3-0621":[["名詞：謎；難解的事","puzzle / enigma","The disappearance of the old photograph remains a mystery to our family.","那張老照片怎麼不見的，對我們家而言仍是個謎。",""]],"l3-0622":[["名詞：保姆","childminder","The nanny picks up the children from school every afternoon.","保姆每天下午到學校接孩子。","nanny 常受僱在孩子家中照顧孩子；childminder 也可能在自己家提供照顧。"]],"l3-0623":[["名詞：小睡","snooze / short sleep","After lunch, my grandfather took a short nap in his favorite chair.","午餐後，祖父在最喜歡的椅子上小睡了一會兒。",""]],"l3-0624":[["形容詞：原生的","indigenous","The garden contains native plants that grow well in the local climate.","花園種有適應當地氣候的原生植物。",""]],"l3-0625":[["名詞：海軍","naval forces","Her older brother joined the navy after completing his engineering degree.","她哥哥取得工程學位後加入了海軍。",""]],"l3-0626":[["名詞：必需品","essential / requirement","Reliable transport is a necessity for people living far from town.","對住在遠離城鎮地區的人而言，可靠的交通是必需的。",""]],"l3-0627":[["名詞：領帶","tie","He loosened his necktie as soon as the formal dinner ended.","正式晚宴一結束，他就鬆開了領帶。",""]],"l3-0628":[["名詞：住宅社區；街區","local area / district","A new bakery has opened in our neighborhood near the school.","我們社區的學校附近新開了一家麵包店。",""]],"l3-0629":[["名詞：神經","無直接同義詞","The diagram uses yellow lines to show the nerves in the hand.","這張圖用黃色線條標示手部的神經。",""]],"l3-0630":[["形容詞：緊張的","anxious / uneasy","I felt nervous while waiting outside the room for my first interview.","第一次面試時，我在房間外等待，感到很緊張。",""]],"l3-0631":[["名詞：電腦網路","無直接同義詞","All the office computers connect to the same secure network.","辦公室所有電腦都連接到同一個安全網路。",""]],"l3-0632":[["名詞：暱稱；綽號","moniker / informal name","His childhood nickname stayed with him long after he left school.","離開學校很久以後，大家仍用他童年的綽號叫他。","moniker 較口語且帶趣味。"]],"l3-0633":[["形容詞：高尚的","honorable / worthy","Helping families rebuild their homes was a noble goal for the volunteers.","幫助家庭重建家園，是志工們高尚的目標。",""]],"l3-0634":[["形容詞：正常的","usual / ordinary","Normal traffic resumed after the broken truck was removed from the road.","故障卡車被移走後，交通恢復了正常。",""]],"l3-0635":[["名詞：小說家","writer of novels","The novelist spent a month in the fishing village researching her next book.","那位小說家在漁村住了一個月，為下一本書蒐集資料。",""]],"l3-0636":[["名詞：修女","sister","A nun welcomed the visitors and showed them the convent garden.","一位修女迎接訪客，帶他們參觀修道院的花園。","sister 用於某些基督教傳統的修女稱呼。"]],"l3-0637":[["名詞：橡樹","無直接同義詞","A huge oak beside the gate provides shade for the playground.","門邊一棵巨大的橡樹為遊樂場遮蔭。",""]],"l3-0638":[["及物動詞：觀察","watch / monitor","The students observed the birds without disturbing their nests.","學生們觀察鳥類，沒有打擾牠們的巢。",""]],"l3-0639":[["形容詞：明顯的","clear / apparent","It was obvious from his muddy shoes that he had walked through the fields.","從他沾滿泥巴的鞋子可以明顯看出，他走過田地。",""]],"l3-0640":[["名詞：場合；特別事件","event / celebration","We dressed formally because the anniversary dinner was a special occasion.","因為週年紀念晚宴是個特別場合，所以我們穿得很正式。",""]],"l3-0641":[["形容詞：奇怪的","strange / peculiar","An odd noise from the attic kept us awake all night.","閣樓傳來奇怪的聲音，讓我們整晚睡不著。",""]],"l3-0642":[["介系詞：到上面","on to","The kitten climbed onto my lap while I was reading.","我看書時，小貓爬到了我的大腿上。","onto 表示移動到表面；靜態位置通常用 on。"]],"l3-0643":[["名詞：機器操作員","machine operator","The operator stopped the machine when a warning light came on.","警示燈亮起時，操作員停下了機器。",""]],"l3-0644":[["名詞：機會","chance / opening","The internship gave her an opportunity to work with experienced engineers.","實習給了她與資深工程師共事的機會。",""]],"l3-0645":[["名詞：相反的事物","reverse / contrary","I expected the room to be noisy, but the opposite was true.","我原以為房間會很吵，實際上卻正好相反。",""]],"l3-0646":[["形容詞：樂觀的","hopeful / positive","The coach remained optimistic despite the team's slow start to the season.","儘管球隊季初表現不佳，教練仍保持樂觀。",""]],"l3-0647":[["名詞：起源","source / beginning","The museum explains the origin of the town's unusual name.","博物館說明了這座城鎮特殊名稱的由來。",""]],"l3-0648":[["形容詞：最初的","initial / first","The original plan was to camp, but the forecast changed our minds.","最初的計畫是露營，但天氣預報讓我們改變了主意。",""]],"l3-0649":[["名詞：孤兒","無直接同義詞","The story follows an orphan who finds a new family in a small village.","故事描述一名孤兒在小村莊找到新家庭的經過。",""]],"l3-0650":[["助動詞片語：應該","should","You ought to tell the organizer that you cannot attend.","你應該告訴主辦人，你無法出席。",""]],"l3-0651":[["形容詞：戶外的","open-air","The school canceled its outdoor activities because of the heavy rain.","學校因大雨取消了戶外活動。",""]],"l3-0652":[["副詞：在戶外","outside / in the open air","We ate outdoors under the trees while the weather stayed warm.","趁天氣暖和，我們在戶外的樹下用餐。",""]],"l3-0653":[["形容詞：外部的","external / exterior","The outer walls of the castle were built from thick stone blocks.","城堡的外牆是用厚實石塊砌成的。",""]],"l3-0654":[["名詞：大綱","summary / overview","Prepare a short outline before you start writing the report.","開始寫報告前，先準備一份簡短大綱。",""]],"l3-0655":[["名詞：長大衣","topcoat","He hung his wet overcoat beside the door before entering the kitchen.","他進廚房前，把濕大衣掛在門邊。","topcoat 通常比 overcoat 輕薄。"]],"l3-0656":[["及物動詞：欠款","be indebted to","I still owe my older sister twenty dollars for the concert ticket.","那張演唱會門票的錢，我還欠姊姊二十元。",""]],"l3-0657":[["名詞：所有權","title","The document confirms the family's ownership of the small farm.","這份文件確認了那家人對小農場的所有權。","title 可指合法所有權；possession 可只指占有。"]],"l3-0658":[["名詞：便條紙本","notepad","She wrote the caller's number on a pad beside the telephone.","她把來電者的號碼寫在電話旁的便條紙本上。",""]],"l3-0659":[["名詞：提桶","bucket","The children carried a pail of water back from the well.","孩子們從井邊提了一桶水回來。",""]],"l3-0660":[["名詞：好友（口語）","friend / buddy","An old school pal invited me to lunch last weekend.","上週末，一位學生時代的老朋友邀我吃午餐。",""]],"l3-0661":[["名詞：宮殿","royal residence","Visitors lined up outside the palace to see the royal gardens.","遊客在宮殿外排隊，等著參觀皇家花園。",""]],"l3-0662":[["形容詞：臉色蒼白的","ashen / wan","He looked pale after spending the entire morning on the rough sea.","在波濤洶湧的海上待了一整個早上後，他看起來臉色蒼白。",""]],"l3-0663":[["名詞：煎餅","無直接同義詞","She served the warm pancakes with honey and sliced bananas.","她把熱煎餅配上蜂蜜和香蕉片端上桌。",""]],"l3-0664":[["名詞：恐慌","alarm / terror","The sudden darkness caused panic among passengers on the crowded train.","突然一片漆黑，讓擁擠列車上的乘客陷入恐慌。",""]],"l3-0665":[["名詞：遊行","procession / march","The parade moved slowly through the town behind a brass band.","遊行隊伍跟在銅管樂隊後方，緩緩穿過城鎮。",""]],"l3-0666":[["名詞：樂園；理想之地","heaven","With its quiet beaches, the island felt like paradise to us.","島上有寧靜的海灘，對我們而言宛如樂園。","此處天堂、樂園是比喻理想之地；haven 著重避難或安穩的場所，不能一律替換。"]],"l3-0667":[["名詞：包裹","package","A parcel from my aunt arrived just before my birthday.","生日即將到來時，阿姨寄的包裹送到了。",""]],"l3-0668":[["不及物動詞：參與","take part / join in","All students are welcome to participate in the school cooking competition.","歡迎所有學生參加學校的烹飪比賽。","participate in；take part in。"]],"l3-0669":[["名詞：文章段落","extract / excerpt","Read the passage carefully before answering the questions below it.","回答下方的問題前，先仔細閱讀這段文章。",""]],"l3-0670":[["名詞：熱愛","enthusiasm / love","Her passion for photography began during a family trip to the mountains.","一次家庭山區旅行，讓她開始熱愛攝影。",""]],"l3-0671":[["名詞：護照","無直接同義詞","Keep your passport in a safe place while traveling abroad.","在國外旅行時，把護照放在安全的地方。",""]],"l3-0672":[["名詞：密碼","passcode","I had to reset my password before I could access the account.","我必須重設密碼，才能登入帳戶。","passcode 常指一組數字或簡短存取碼。"]],"l3-0673":[["名詞：耐心","forbearance / tolerance","Teaching young children to tie their shoes requires patience.","教幼童綁鞋帶需要耐心。",""]],"l3-0674":[["不及物動詞：暫停","stop briefly / break off","The speaker paused to let the audience consider her question.","講者停頓了一下，讓觀眾思考她的問題。",""]],"l3-0675":[["及物動詞：鋪路面","surface","Workers paved the muddy lane to make access easier during winter.","工人鋪平那條泥濘巷道的路面，讓冬天通行更方便。",""]],"l3-0676":[["名詞：人行道（英式）","sidewalk","Leave enough room on the pavement for people pushing strollers.","在人行道上留出足夠空間，讓推嬰兒車的人通過。","美式 pavement 通常指鋪設的路面，sidewalk 才是人行道。"]],"l3-0677":[["名詞：動物的腳掌","無直接同義詞","The dog lifted one paw and rested it on my knee.","狗抬起一隻腳掌，放在我的膝蓋上。","paw 指腳掌；claw 指爪的尖硬部分。"]],"l3-0678":[["名詞：薪資","salary / wages","The job offers better pay but requires working every other weekend.","這份工作薪資較高，但隔週的週末必須上班。",""]],"l3-0679":[["名詞：豌豆","無直接同義詞","The children shelled fresh peas while their father prepared dinner.","父親準備晚餐時，孩子們幫忙剝新鮮豌豆。",""]],"l3-0680":[["名詞：山頂","summit / mountaintop","We reached the peak just as the clouds began to clear.","我們登上山頂時，雲層剛好開始散開。",""]],"l3-0681":[["名詞：珍珠","無直接同義詞","A single pearl hung from the delicate gold chain around her neck.","她頸上細緻的金鍊垂著一顆珍珠。",""]],"l3-0682":[["及物動詞：削皮；剝皮","skin / pare","Peel the apples and cut them into small pieces for the pie.","把蘋果削皮，切成小塊來做派。","pare 常指用刀薄薄削去外皮。"]],"l3-0683":[["不及物動詞：偷看","peek","The child peeped through the curtain to see who was at the door.","孩子從窗簾縫偷看，想知道誰站在門口。",""]],"l3-0684":[["名詞：一美分硬幣","one-cent coin","She found a penny on the sidewalk outside the bakery.","她在麵包店外的人行道上找到一枚一美分硬幣。",""]],"l3-0685":[["及物動詞：演出","present / act out","The students performed a short play for their parents on Friday.","學生們星期五為家長演出了一齣短劇。",""]],"l3-0686":[["名詞：演出","show / presentation","Her piano performance ended with a long round of applause.","她的鋼琴演奏在久久不歇的掌聲中結束。",""]],"l3-0687":[["名詞：許可","consent / authorization","You need permission from the owner before entering the private garden.","進入私人花園前，你需要得到主人的許可。",""]],"l3-0688":[["及物動詞：允許","allow / authorize","The museum permits visitors to take photographs without using a flash.","博物館允許遊客在不使用閃光燈的情況下拍照。",""]],"l3-0689":[["名詞：個性","character / temperament","Her friendly personality helps new students feel comfortable in the class.","她友善的個性讓新同學在班上感到自在。",""]],"l3-0690":[["及物動詞：說服","convince / talk into","We persuaded our teacher to hold the final lesson in the garden.","我們說服老師把最後一堂課安排在花園裡。","persuade someone to do；talk someone into doing。"]],"l3-0691":[["名詞：害蟲","無直接同義詞","This tiny pest damages young leaves before the farmers notice it.","這種小害蟲在農夫發現牠之前，就會破壞嫩葉。","vermin 為集合用語，也可涵蓋老鼠等有害動物，不能逐一替換 pest。"]],"l3-0692":[["及物動詞：醃漬","preserve in brine / preserve in vinegar","My grandmother pickles cucumbers in jars every summer after the harvest.","每年夏天收成後，祖母都把小黃瓜放進罐裡醃漬。",""]],"l3-0693":[["名詞：藥丸；藥錠","tablet","The nurse placed the pill in a small cup beside the water.","護理師把藥錠放進水杯旁的一個小杯子裡。","tablet 特指壓製藥錠；pill 在口語中範圍較廣。"]],"l3-0694":[["名詞：飛行員","aviator","The pilot announced that we would land ten minutes ahead of schedule.","飛行員宣布，我們將比預定時間早十分鐘降落。",""]],"l3-0695":[["名詞：松樹","無直接同義詞","A tall pine beside the cabin stayed green throughout the winter.","木屋旁一棵高大的松樹整個冬天都維持翠綠。",""]],"l3-0696":[["名詞：品脫","無直接同義詞","He bought a pint of milk from the shop near the station.","他在車站附近的商店買了一品脫牛奶。","英制與美制品脫容量不同。"]],"l3-0697":[["名詞：坑洞","hole / hollow","Rainwater collected in a deep pit beside the unfinished road.","雨水積在未完工道路旁的一個深坑裡。",""]],"l3-0698":[["名詞：可惜的事","shame / unfortunate thing","It is a pity that you cannot join us for the concert.","你不能和我們一起去聽音樂會，真可惜。",""]],"l3-0699":[["形容詞：塑膠製的","無直接同義詞","We replaced the cracked plastic chairs with stronger wooden ones.","我們把裂開的塑膠椅換成了更堅固的木椅。",""]],"l3-0700":[["名詞：充足；富足","abundance / prosperity","The family remembered a time of plenty before the long drought.","這家人回想起漫長乾旱以前的富足日子。","此句採名詞用法；plenty of 是更常見的數量表達。"]],"l3-0701":[["名詞：電源插頭","無直接同義詞","Pull the plug out of the socket before moving the lamp.","搬動檯燈前，先把插頭從插座拔出。",""]],"l3-0702":[["名詞：李子","無直接同義詞","The ripe plum was so juicy that I needed a napkin.","那顆熟李子多汁到讓我需要拿張餐巾紙。",""]],"l3-0703":[["名詞：水管工","無直接同義詞","The plumber replaced the leaking pipe beneath our bathroom sink.","水管工更換了浴室洗手台下方漏水的水管。",""]],"l3-0704":[["名詞：杆；柱","post / rod","A red flag flew from the tall pole beside the entrance.","入口旁的高旗杆上飄著一面紅旗。",""]],"l3-0705":[["形容詞：政治的","無直接同義詞","The newspaper explains the political issues behind the upcoming election.","那份報紙說明了即將到來的選舉背後的政治議題。",""]],"l3-0706":[["名詞：政治人物","political figure","The politician answered questions from residents at a public meeting.","那位政治人物在公開會議上回答居民的提問。",""]],"l3-0707":[["名詞：政治事務","public affairs","She became interested in politics after joining the student council.","加入學生會後，她開始對政治產生興趣。",""]],"l3-0708":[["名詞：民意調查","survey / opinion poll","A recent poll asked residents which local services needed improvement.","最近一項民調詢問居民，哪些地方公共服務需要改善。",""]],"l3-0709":[["及物動詞：汙染","contaminate / foul","Waste from the factory polluted a stream used by nearby farms.","工廠廢棄物汙染了一條附近農場使用的溪流。",""]],"l3-0710":[["名詞：矮種馬","無直接同義詞","The instructor led a gentle pony around the ring with a child on its back.","教練牽著一匹溫馴的小馬繞行圍場，馬背上坐著一個孩子。","pony 通常指小型品種的馬，不是幼馬；幼馬是 foal。"]],"l3-0711":[["及物動詞：使啪地爆裂","burst","She accidentally popped the balloon while tying it to the chair.","她把氣球綁到椅子上時，不小心弄破了它。",""]],"l3-0712":[["形容詞：流行音樂的","popular","The band mixed traditional instruments with modern pop melodies.","樂團把傳統樂器與現代流行旋律融合在一起。",""]],"l3-0713":[["不可數名詞：瓷器","china","My grandmother keeps her fine porcelain in a glass cabinet.","祖母把精緻的瓷器收藏在玻璃櫃裡。",""]],"l3-0714":[["名詞：一部分","part / share","A large portion of the garden is shaded by an old tree.","花園很大一部分都被一棵老樹遮蔭。",""]],"l3-0715":[["名詞：肖像","likeness","The artist painted a portrait of the fisherman beside his boat.","畫家為船旁的漁夫畫了一幅肖像。","likeness 指人物的形象再現，較書面。"]],"l3-0716":[["名詞：郵資","mailing cost","The postage cost more than the small gift inside the parcel.","郵資比包裹裡的小禮物還貴。",""]],"l3-0717":[["名詞：海報","placard","A colorful poster outside the library advertised the summer reading program.","圖書館外一張色彩繽紛的海報宣傳暑期閱讀活動。","placard 常指告示牌或標語牌。"]],"l3-0718":[["及物動詞：延期","put off / defer","We postponed the outdoor concert until the following weekend because of rain.","因為下雨，我們把戶外音樂會延到下個週末。",""]],"l3-0719":[["名詞：延期","delay / deferral","The postponement of the match gave the injured player more time to recover.","比賽延期讓受傷球員有更多時間恢復。",""]],"l3-0720":[["不可數名詞：陶器","ceramics","The market stall sells pottery made by artists from nearby villages.","那個市場攤位販售附近村莊藝術家製作的陶器。",""]],"l3-0721":[["及物動詞：倒出液體","tip","Pour the soup into warm bowls and serve it immediately.","把湯倒進溫熱的碗裡，立即上桌。","pour 著重液體流出；tip 著重傾斜容器來倒出內容物。"]],"l3-0722":[["名詞：貧困","destitution","The organization helps families escape poverty through education and job training.","該組織透過教育和職業訓練，幫助家庭脫離貧困。","destitution 指極度貧困，程度比 poverty 強。"]],"l3-0723":[["名詞：粉末","無直接同義詞","Grind the dried herbs into a fine powder before adding them.","把乾燥香草磨成細粉後再加入。",""]],"l3-0724":[["形容詞：實用的","useful","The workshop provides practical advice on repairing common household items.","工作坊提供修理常見家用品的實用建議。",""]],"l3-0725":[["名詞：禱告","無直接同義詞","The family said a quiet prayer before beginning their meal.","這家人開始用餐前，輕聲作了禱告。","supplication 著重懇求，不涵蓋所有禱告類型。"]],"l3-0726":[["形容詞：珍貴的","valuable / treasured","The letters are precious reminders of the years we spent together.","那些信是我們共度歲月的珍貴回憶。",""]],"l3-0727":[["名詞：準備工作","planning / groundwork","Careful preparation helped the team finish the outdoor event before the rain.","周詳的準備讓團隊在下雨前完成了戶外活動。",""]],"l3-0728":[["名詞：壓力","stress / strain","The approaching deadline put extra pressure on everyone in the office.","截止日期逼近，讓辦公室每個人都承受額外壓力。",""]],"l3-0729":[["及物動詞：假裝","feign / make believe","The children pretended that the empty box was a spaceship.","孩子們假裝那個空箱子是一艘太空船。","pretend 可接 that 子句；feign 通常直接接名詞。"]],"l3-0730":[["及物動詞：防止","stop","A strong fence prevents the sheep from wandering onto the road.","堅固的圍欄防止羊隻跑到馬路上。","prevent someone or something from doing。"]],"l3-0731":[["形容詞：先前的","earlier / preceding","The previous owner left several fruit trees in the garden.","前一位屋主在花園裡留下了幾棵果樹。",""]],"l3-0732":[["名詞：神父；祭司","無直接同義詞","The priest welcomed the visitors into the old village church.","神父迎接訪客進入村裡的老教堂。","minister、pastor、priest 的宗派職稱不同，不能一律互換。"]],"l3-0733":[["形容詞：首要的","main / principal","Our primary concern is making sure every child gets home safely.","我們最關心的是確保每個孩子都安全回家。",""]],"l3-0734":[["形容詞：很可能的","likely","Heavy rain is probable tonight, so the organizers are preparing an indoor space.","今晚很可能下大雨，所以主辦單位正在準備室內場地。",""]],"l3-0735":[["名詞：過程","procedure / series of steps","The guide explained the process of turning cocoa beans into chocolate.","導覽員說明了把可可豆製成巧克力的過程。",""]],"l3-0736":[["名詞：產品","無直接同義詞","The company tested its new product with a small group of customers.","公司找了一小群顧客測試新產品。","item 泛指物件；merchandise 泛指商品，不能精確替換所有 product。"]],"l3-0737":[["名詞：利潤","earnings / financial gain","The bakery made a small profit during its first month.","那家麵包店在第一個月賺了少許利潤。",""]],"l3-0738":[["名詞：電腦程式","application / software program","The program automatically saves a backup copy every ten minutes.","這個程式每十分鐘會自動儲存一份備份。",""]],"l3-0739":[["及物動詞：升遷","advance / raise in rank","The company promoted her to branch manager after three successful years.","她表現出色三年後，公司升她為分店經理。",""]],"l3-0740":[["名詞：證明；證據","evidence / confirmation","The receipt provided proof that I had already paid for the repair.","收據證明我已經支付了維修費。","proof 通常比 evidence 更強，表示足以證明。"]],"l3-0741":[["形容詞：適當的","appropriate / suitable","Wear proper shoes because the trail is rocky and uneven.","要穿合適的鞋子，因為步道多石又不平。",""]],"l3-0742":[["不可數名詞：財產","possessions / belongings","The police returned the stolen property to its rightful owners.","警方把遭竊財物歸還給原主。",""]],"l3-0743":[["名詞：提案","suggestion / plan","The committee discussed a proposal to turn the empty lot into a garden.","委員會討論了把空地改成花園的提案。",""]],"l3-0744":[["名詞：保護","shelter","The thick walls offer protection from the strong winter winds.","厚實的牆壁可以抵擋冬天的強風。",""]],"l3-0745":[["形容詞：防護用的","無直接同義詞","Workers wore protective gloves while handling the rough metal sheets.","工人搬動粗糙金屬板時戴著防護手套。","defensive 常指防禦攻擊；防護裝備通常用 protective。"]],"l3-0746":[["名詞：英式酒館","public house / tavern","They met at a quiet pub after the evening football match.","晚間足球賽結束後，他們在一家安靜的酒館碰面。",""]],"l3-0747":[["名詞：拳擊的一拳","fist blow","The boxer avoided the punch by moving quickly to the left.","拳擊手迅速向左移動，閃過了那一拳。",""]],"l3-0748":[["形容詞：純淨無摻雜的","unmixed / unadulterated","The necklace is made of pure silver with a simple round pendant.","這條項鍊以純銀製成，配有簡單的圓形墜飾。",""]],"l3-0749":[["及物動詞：追求","seek / work toward","She moved to the city to pursue a career in design.","她搬到城市，追求設計領域的職涯。",""]],"l3-0750":[["不及物動詞：爭吵","argue / bicker","The children quarreled over who would sit beside the window.","孩子們為了誰要坐窗邊而爭吵。",""]],"l3-0751":[["形容詞：奇怪的（較舊用法）","strange / odd","There was a queer clicking sound inside the old clock.","那座老鐘裡傳出奇怪的喀噠聲。","此處示範較舊的奇怪義。queer 也可作性少數身分自稱，但用來指稱他人時可能帶侮辱性，須尊重對方用語。"]],"l3-0752":[["及物動詞：引用原話","cite / repeat verbatim","The reporter quoted the mayor's exact words in the evening article.","記者在晚間報導中引用了市長的原話。","cite 也可只提及來源，不一定逐字引用。"]],"l3-0753":[["形容詞：種族的","無直接同義詞","The school held a discussion about racial discrimination and equal treatment.","學校舉行了一場關於種族歧視與平等待遇的討論。",""]],"l3-0754":[["名詞：雷達","無直接同義詞","The ship's radar detected another vessel moving through the thick fog.","船上的雷達偵測到另一艘船正在濃霧中移動。",""]],"l3-0755":[["名詞：抹布；破布","cloth scrap","He wiped the oil off his hands with an old rag.","他用一塊舊抹布擦掉手上的油。",""]],"l3-0756":[["名詞：葡萄乾","無直接同義詞","She stirred a handful of raisins into the warm oatmeal.","她把一把葡萄乾拌進溫熱的燕麥粥裡。",""]],"l3-0757":[["名詞：軍階；等級","grade","After several years of army service, he reached the rank of captain.","在陸軍服役數年後，他升到了上尉軍階。","本句限定陸軍軍階；captain 在不同軍種或組織的職級與譯法可能不同。"]],"l3-0758":[["名詞：速率","speed / pace","The plants grew at a faster rate after we moved them into sunlight.","把植物移到陽光下之後，它們長得更快了。",""]],"l3-0759":[["形容詞：生的；未煮熟的","uncooked","The salad contains raw carrots, cabbage, and thin slices of cucumber.","這道沙拉有生紅蘿蔔、高麗菜和薄黃瓜片。",""]],"l3-0760":[["名詞：光線","beam / shaft of light","A ray of sunlight reached the floor through a gap in the curtains.","一束陽光穿過窗簾的縫隙照到地板上。",""]],"l3-0761":[["名詞：刮鬍刀","shaver","He packed his razor and toothbrush in a small travel bag.","他把刮鬍刀和牙刷裝進一個小旅行袋。","shaver 常指電動刮鬍刀；razor 也包括手動刮鬍刀，範圍較廣。"]],"l3-0762":[["不及物動詞：作出反應","respond","The dog reacted to the doorbell by running toward the entrance.","狗一聽到門鈴，就跑向門口。",""]],"l3-0763":[["名詞：反應","response","Her surprised reaction showed that she had not expected the gift.","她驚訝的反應顯示，她沒料到會收到禮物。",""]],"l3-0764":[["形容詞：合理的","fair","The repair shop charged a reasonable price for replacing the broken screen.","維修店更換破螢幕的收費很合理。",""]],"l3-0765":[["名詞：收據","proof of payment","Keep the receipt in case you need to return the jacket.","把收據留著，以防需要退回外套。",""]],"l3-0766":[["名詞：電話聽筒","handset","She lifted the receiver and listened carefully to the caller.","她拿起電話聽筒，仔細聆聽來電者說話。",""]],"l3-0767":[["及物動詞：認出","identify","I recognized my old teacher immediately despite his much shorter haircut.","雖然頭髮剪短了許多，我還是一眼就認出了以前的老師。",""]],"l3-0768":[["名詞：錄音機","audio recorder","The journalist placed a small recorder on the table before the interview.","訪談開始前，記者把一台小錄音機放在桌上。",""]],"l3-0769":[["及物動詞：找回","retrieve / regain","The police recovered the stolen bicycle from an abandoned building.","警方在一棟廢棄建築裡找回了遭竊的自行車。",""]],"l3-0770":[["及物動詞：減少","decrease / cut","The café reduced waste by offering smaller portions to children.","咖啡館提供兒童較小的份量，藉此減少浪費。",""]],"l3-0771":[["形容詞：區域的","local / area-wide","The regional competition brought together school teams from six nearby towns.","區域賽集合了附近六個城鎮的學校隊伍。","regional 通常涵蓋比 local 更大的區域。"]],"l3-0772":[["及物動詞：後悔","be sorry about","I regret leaving my camera at home on such a beautiful day.","天氣這麼好，我很後悔把相機留在家裡。","regret doing 表示後悔做過某事。"]],"l3-0773":[["及物動詞：敘述","recount / tell","The traveler related her adventures to the children gathered around the fire.","旅人向圍在火邊的孩子們講述她的冒險經歷。",""]],"l3-0774":[["及物動詞：放鬆","loosen / ease","Relax your shoulders before you begin the breathing exercise.","開始呼吸練習前，先放鬆肩膀。",""]],"l3-0775":[["及物動詞：釋放","free / let go","The volunteers released the injured bird after its wing had healed.","志工在受傷鳥兒的翅膀痊癒後，將牠放走了。","release 直接接受詞；let go of 後接放開的對象。"]],"l3-0776":[["形容詞：可靠的","dependable / trustworthy","We need a reliable person to care for the pets while we travel.","旅行期間，我們需要一個可靠的人照顧寵物。",""]],"l3-0777":[["名詞：寬慰；鬆一口氣","comfort","I felt enormous relief when the missing passport was found.","遺失的護照找到了，我大大鬆了一口氣。","此句 relief 指擔憂消除後的寬慰。"]],"l3-0778":[["名詞：宗教","faith / belief system","The course explores how religion has influenced art in different societies.","這門課探討宗教如何影響不同社會的藝術。","belief system 的範圍較廣，也可能指非宗教的信念體系。"]],"l3-0779":[["形容詞：虔誠的","devout / pious","Her religious grandparents begin each day with a quiet prayer.","她虔誠的祖父母每天都以一段安靜的禱告開始一天。",""]],"l3-0780":[["不及物動詞：依賴","depend / count","The village relies on a single bridge for access to the main road.","村莊仰賴唯一的一座橋連接主要道路。","rely on；depend on；count on。"]],"l3-0781":[["不及物動詞：保持","stay / continue to be","The library will remain open during the building work next door.","隔壁施工期間，圖書館將繼續開放。",""]],"l3-0782":[["及物動詞：提醒","prompt","Please remind me to return the library books tomorrow morning.","請提醒我明天早上歸還圖書館的書。","remind someone to do；prompt 著重促使某人行動。"]],"l3-0783":[["形容詞：偏遠的","isolated / outlying","A narrow road leads to the remote village high in the mountains.","一條狹窄的道路通往高山上的偏遠村莊。",""]],"l3-0784":[["及物動詞：移除","take away / eliminate","Remove the damaged leaves before putting the flowers in a vase.","把花放進花瓶前，先去掉受損的葉片。",""]],"l3-0785":[["及物動詞：續期","extend","I need to renew my library membership before it expires next week.","我需要在下週到期前續辦圖書館會員資格。",""]],"l3-0786":[["名詞：租金","rental payment","The monthly rent includes water but does not cover electricity.","每月租金包含水費，但不含電費。",""]],"l3-0787":[["及物動詞：修理","fix / mend","The mechanic repaired the bicycle while I waited in the shop.","我在店裡等候時，技師修好了自行車。",""]],"l3-0788":[["及物動詞：更換；取代","substitute for / take the place of","We replaced the old curtains with blinds that block more sunlight.","我們把舊窗簾換成遮陽效果更好的百葉窗。","replace A with B；substitute B for A。"]],"l3-0789":[["名詞：替換品","substitute / alternative","The shop sent a replacement when I reported the damaged lamp.","我反映檯燈損壞後，店家寄來了替換品。",""]],"l3-0790":[["及物動詞：代表","stand for / symbolize","The blue line on the map represents the river through the valley.","地圖上的藍線代表流經山谷的河流。",""]],"l3-0791":[["名詞：典型代表","example / specimen","The oak is a familiar representative of the trees found in this forest.","橡樹是這片森林裡常見樹種的典型代表。","本句採代表物義，不是代言人或民意代表。"]],"l3-0792":[["名詞：共和國","無直接同義詞","The history book describes how the monarchy was replaced by a republic.","歷史書描述了君主政體如何被共和國取代。",""]],"l3-0793":[["及物動詞：請求","ask for / seek","We requested a quieter room away from the busy street.","我們要求一間遠離繁忙街道、比較安靜的房間。",""]],"l3-0794":[["及物動詞：預訂","book","Please reserve a table for six near the window if possible.","如果可以，請預訂一張靠窗的六人桌。",""]],"l3-0795":[["及物動詞：抵擋","withstand","The old wooden door could not resist the pressure of the rising water.","那扇舊木門無法抵擋不斷上漲的水所造成的壓力。",""]],"l3-0796":[["名詞：資源","asset","The library is a valuable resource for students researching local history.","對研究地方歷史的學生而言，圖書館是寶貴的資源。",""]],"l3-0797":[["不及物動詞：回覆","reply / answer","The hotel responded to my email within a few hours.","飯店在幾個小時內回覆了我的電子郵件。","respond to；reply to。"]],"l3-0798":[["名詞：答覆","reply / answer","We are still waiting for a response to our booking request.","我們仍在等候訂位要求的回覆。",""]],"l3-0799":[["名詞：責任","duty / obligation","It is your responsibility to lock the office before leaving.","離開前鎖好辦公室，是你的責任。",""]],"l3-0800":[["及物動詞：限制","limit / constrain","The museum restricts the number of visitors allowed into the tower.","博物館限制進入塔樓的參觀人數。",""]],"l3-0801":[["及物動詞：揭露","disclose / uncover","The old letters revealed a surprising friendship between the two writers.","那些舊信揭露了兩位作家之間一段出人意料的友誼。",""]],"l3-0802":[["名詞：絲帶","無直接同義詞","She tied a blue ribbon around the box of homemade cookies.","她在裝著自製餅乾的盒子上繫了一條藍色絲帶。",""]],"l3-0803":[["及物動詞：使擺脫","free / clear","We opened the windows to rid the room of the paint smell.","我們打開窗戶，去除房間裡的油漆味。","rid A of B 表示使 A 擺脫 B。"]],"l3-0804":[["名詞：謎語","puzzle / brainteaser","The children took turns asking riddles during the long bus ride.","搭長途公車時，孩子們輪流出謎語。",""]],"l3-0805":[["形容詞：水果成熟的","ready to eat / mature","The peaches are ripe enough to pick for tomorrow's market.","桃子已經夠熟，可以採收後拿去明天的市場賣。",""]],"l3-0806":[["名詞：風險","danger / hazard","There is a risk of falling rocks on the narrow mountain road.","狹窄的山路有落石危險。",""]],"l3-0807":[["不及物動詞：吼叫","bellow","The lion roared so loudly that the visitors stepped back.","獅子的吼聲大到讓遊客往後退。",""]],"l3-0808":[["及物動詞：烘烤","bake","We roasted the vegetables with olive oil and fresh rosemary.","我們用橄欖油和新鮮迷迭香烤蔬菜。","roast 常用於肉類或蔬菜；bake 常用於麵包糕點，也可用於蔬菜。"]],"l3-0809":[["及物動詞：搶劫","hold up","Two masked men robbed the shop shortly before closing time.","兩名蒙面男子在商店快打烊時搶劫了那家店。","rob 接被搶的人或場所；steal 接被偷的東西。"]],"l3-0810":[["名詞：搶匪","hold-up man","The robber dropped his bag while running away from the bank.","搶匪逃離銀行時，掉了他的袋子。","thief 泛指竊賊，robber 通常涉及威脅或暴力。"]],"l3-0811":[["名詞：搶劫","hold-up","The shop installed new cameras after the robbery last winter.","去年冬天發生搶案後，那家店裝了新的監視器。",""]],"l3-0812":[["名詞：浴袍","bathrobe / dressing gown","He put on a warm robe after getting out of the shower.","洗完澡後，他穿上一件暖和的浴袍。",""]],"l3-0813":[["名詞：火箭","無直接同義詞","The rocket rose above the launch pad in a cloud of smoke.","火箭在一團濃煙中升離發射臺。",""]],"l3-0814":[["形容詞：浪漫的","無直接同義詞","They planned a romantic dinner on the balcony overlooking the sea.","他們計畫在能眺望大海的陽臺上享用浪漫晚餐。","本句指營造戀愛氣氛；amorous 著重愛慕或情慾，通常描述人或舉動。"]],"l3-0815":[["不及物動詞：腐爛","decay / decompose","The fallen apples began to rot after several days of rain.","接連下了幾天雨，掉落的蘋果開始腐爛。",""]],"l3-0816":[["形容詞：腐爛的","decayed / decomposed","We removed the rotten wood before repairing the garden bench.","修理花園長椅前，我們先去除了腐爛的木頭。",""]],"l3-0817":[["形容詞：粗糙的","coarse / uneven","The rough surface of the stone scratched the wooden table.","石頭粗糙的表面刮傷了木桌。",""]],"l3-0818":[["名詞：固定日常程序","habit / regular practice","A short walk after breakfast is part of her daily routine.","早餐後散步一小段，是她每日固定作息的一部分。",""]],"l3-0819":[["名詞：小地毯","mat / area rug","A colorful rug made the small living room feel warmer.","一張色彩繽紛的小地毯讓小客廳感覺更溫暖。",""]],"l3-0820":[["名詞：傳聞","hearsay / unconfirmed report","A rumor spread that the old cinema would close next month.","有傳聞說，那家老電影院下個月就要歇業。",""]],"l3-0821":[["名詞：鐵鏽","無直接同義詞","Orange rust had formed on the tools left outside in the rain.","工具放在外面淋雨，表面已長出橘色鐵鏽。",""]],"l3-0822":[["形容詞：生鏽的","corroded","The rusty gate made a loud noise whenever someone opened it.","那扇生鏽的門每次被打開都會發出很大的聲響。","corroded 指腐蝕，範圍比鐵鏽更廣。"]],"l3-0823":[["名詞：大袋子","large bag","The farmer carried a heavy sack of potatoes into the kitchen.","農夫把一大袋沉重的馬鈴薯扛進廚房。",""]],"l3-0824":[["名詞：利益；緣故（for the sake of）","benefit / interest","For the sake of the children, they agreed to stop arguing.","為了孩子著想，他們同意停止爭吵。",""]],"l3-0825":[["形容詞：令人滿意的","acceptable / adequate","The mechanic tested the brakes and found them in satisfactory condition.","技師測試了煞車，發現狀況令人滿意。",""]],"l3-0826":[["名詞：茶杯碟","無直接同義詞","She placed the teacup carefully in the center of its saucer.","她小心地把茶杯放在茶碟中央。",""]],"l3-0827":[["名詞：香腸","無直接同義詞","The market vendor grilled sausages beside a tray of sliced onions.","市場攤販在一盤洋蔥片旁邊烤香腸。",""]],"l3-0828":[["複數名詞：積蓄","nest egg / money put aside","They used part of their savings to repair the leaking roof.","他們用部分積蓄修理漏水的屋頂。",""]],"l3-0829":[["名詞：規模","size / extent","We did not realize the scale of the damage until daylight.","天亮後，我們才發現受災範圍有多大。",""]],"l3-0830":[["形容詞：短缺的","in short supply / limited","Fresh water became scarce after the long period without rain.","長時間沒下雨後，淡水變得短缺。",""]],"l3-0831":[["名詞：稻草人","無直接同義詞","The farmer put a scarecrow in the field to frighten away birds.","農夫在田裡放了一個稻草人，嚇走鳥兒。",""]],"l3-0832":[["名詞：圍巾","muffler","She wrapped a wool scarf around her neck before stepping outside.","出門前，她在脖子上圍了一條羊毛圍巾。","muffler 指保暖圍巾，較少用於輕薄裝飾款。"]],"l3-0833":[["形容詞：嚇人的","frightening","The empty house looked scary with its broken windows and dark doorway.","那棟空屋窗戶破損、門口幽暗，看起來很嚇人。",""]],"l3-0834":[["及物動詞：撒布","spread / disperse","Scatter the seeds evenly over the prepared patch of soil.","把種子均勻撒在準備好的那塊土壤上。",""]],"l3-0835":[["名詞：時間表","timetable","Check the bus schedule before deciding when to leave the hotel.","決定何時離開飯店前，先查看公車時刻表。","此句採交通時刻表義。"]],"l3-0836":[["名詞：學者","academic / researcher","The visiting scholar gave a lecture on ancient trade routes.","那位訪問學者作了一場關於古代貿易路線的演講。",""]],"l3-0837":[["名詞：獎學金","study grant / bursary","A scholarship allowed her to attend university without borrowing so much money.","獎學金讓她不必借那麼多錢就能上大學。","bursary 常依經濟需求提供，scholarship 也常依成績或才能頒發。"]],"l3-0838":[["形容詞：科學的","無直接同義詞","The article explains the scientific evidence behind the discovery.","那篇文章說明了這項發現背後的科學證據。",""]],"l3-0839":[["名詞：冰淇淋勺","無直接同義詞","The server used a metal scoop to fill the ice cream cones.","服務人員用金屬挖勺把冰淇淋裝進甜筒。",""]],"l3-0840":[["名詞：球探","talent scout","A scout watched the young goalkeeper during the regional final.","一位球探在區域決賽中觀察那位年輕守門員。",""]],"l3-0841":[["不及物動詞：尖叫","shriek / yell","She screamed when a large spider dropped onto her shoulder.","一隻大蜘蛛掉到她肩上時，她尖叫了起來。",""]],"l3-0842":[["名詞：螺絲","無直接同義詞","One screw was missing from the handle of the old drawer.","舊抽屜的把手少了一顆螺絲。",""]],"l3-0843":[["及物動詞：用力刷洗","scour / rub clean","He scrubbed the muddy boots with a stiff brush outside the door.","他在門外用硬毛刷刷洗沾滿泥巴的靴子。",""]],"l3-0844":[["名詞：海豹","無直接同義詞","A seal lifted its head above the water near our boat.","一隻海豹在我們船旁的水面探出頭來。",""]],"l3-0845":[["名詞：封口","closure","Check that the seal on the jar is intact before opening it.","開罐前，先確認罐子的封口完好。",""]],"l3-0846":[["形容詞：次要的","less important / subordinate","Cost was secondary to safety when we chose the new equipment.","挑選新設備時，安全優先，費用是次要考量。",""]],"l3-0847":[["名詞：安全防護","protection / safety","The museum improved security after several valuable paintings were stolen.","幾幅珍貴畫作遭竊後，博物館加強了保安措施。",""]],"l3-0848":[["及物動詞：尋求","look for / search for","The travelers sought shelter in a small café during the storm.","暴風雨期間，旅人在一家小咖啡館尋求庇護。","seek 的過去式為 sought。"]],"l3-0849":[["及物動詞：抓住","grab / grasp","She seized the rope before the boat drifted out of reach.","船漂得太遠之前，她一把抓住了繩子。",""]],"l3-0850":[["副詞：很少","rarely / infrequently","My grandfather seldom uses his car because most shops are nearby.","祖父很少開車，因為多數商店都在附近。",""]],"l3-0851":[["形容詞：明智的","wise / reasonable","Taking a jacket was a sensible decision as the evening became colder.","傍晚愈來愈冷，可見帶外套是個明智的決定。",""]],"l3-0852":[["形容詞：敏感的","easily affected","My skin is sensitive to the strong soap used at work.","我的皮膚對工作時使用的強效肥皂很敏感。","sensitive to 表示對某物敏感。"]],"l3-0853":[["名詞：分離","parting","The long separation from her family made her first year abroad difficult.","長時間與家人分離，讓她在國外的第一年很難熬。",""]],"l3-0854":[["及物動詞：縫上","stitch","She sewed a new button onto the sleeve of my coat.","她在我的外套袖子上縫了一顆新鈕扣。",""]],"l3-0855":[["名詞：生理性別","無直接同義詞","The vet recorded each animal's age, sex, and weight before the examination.","檢查前，獸醫記錄了每隻動物的年齡、性別和體重。","本句為生理性別義，並非性行為義。"]],"l3-0856":[["形容詞：有性生殖的","無直接同義詞","The biology class compared sexual reproduction in flowering plants and animals.","生物課比較了開花植物與動物的有性生殖。","sexual reproduction 是有性生殖的固定用語。"]],"l3-0857":[["形容詞：性感的","sensual / alluring","The designer described the evening dress as both elegant and sexy.","設計師形容那件晚禮服既優雅又性感。","alluring 泛指誘人的；sexy 明確帶性吸引力之意。"]],"l3-0858":[["名詞：陰涼處","shelter from the sun","We rested in the shade of a large tree beside the trail.","我們在步道旁一棵大樹的樹蔭下休息。",""]],"l3-0859":[["名詞：影子","無直接同義詞","The late afternoon sun cast a long shadow behind the cyclist.","午後偏晚的陽光在自行車騎士身後拉出長長的影子。","silhouette 指黑色輪廓，不一定是光照投射的影子。"]],"l3-0860":[["形容詞：有樹蔭的","shaded / sheltered from the sun","We chose a shady spot beside the river for our picnic.","我們在河邊挑了一處有樹蔭的地方野餐。",""]],"l3-0861":[["形容詞：淺的","not deep","The children played in the shallow water close to the shore.","孩子們在靠近岸邊的淺水處玩耍。",""]],"l3-0862":[["名詞：羞愧","guilt / humiliation","He felt shame when he realized he had blamed the wrong person.","發現自己怪錯人時，他感到羞愧。","guilt 著重對過錯的罪惡感；humiliation 著重受辱感。"]],"l3-0863":[["名詞：洗髮精","無直接同義詞","A small bottle of shampoo stood beside the hotel shower.","飯店淋浴間旁放著一小瓶洗髮精。",""]],"l3-0864":[["及物動詞：剃除毛髮","無直接同義詞","He shaved his beard before having his passport photograph taken.","拍護照照片前，他把鬍子剃掉了。",""]],"l3-0865":[["名詞：牧羊人","sheepherder","The shepherd guided the sheep down the hillside before sunset.","牧羊人在日落前把羊群趕下山坡。",""]],"l3-0866":[["形容詞：閃亮的","gleaming / glossy","The shiny red bicycle caught my eye in the shop window.","店家櫥窗裡那輛閃亮的紅色自行車吸引了我的目光。",""]],"l3-0867":[["及物動詞：縮短","reduce / cut down","We shortened the meeting so everyone could catch the last bus.","我們縮短會議，讓大家都能趕上末班公車。",""]],"l3-0868":[["副詞：不久後","soon / before long","The bus should arrive shortly, so please have your ticket ready.","公車應該快到了，請準備好車票。",""]],"l3-0869":[["名詞：鏟子","無直接同義詞","He used a shovel to clear snow from the front steps.","他用鏟子清除門前階梯上的積雪。","spade 通常鏟面較平，偏用於挖土；shovel 適合鏟起搬動材料。"]],"l3-0870":[["不及物動詞：縮水","contract / become smaller","My wool sweater shrank after I washed it in hot water.","我的羊毛毛衣用熱水洗過後縮水了。","shrink 的過去式常為 shrank，過去分詞為 shrunk。"]],"l3-0871":[["不及物動詞：嘆氣","let out a long breath","She sighed when she saw how much paperwork remained on her desk.","她看到桌上還有那麼多文書工作，便嘆了口氣。",""]],"l3-0872":[["名詞：信號","sign / cue","The guide raised his hand as a signal for us to stop.","導遊舉起手，示意我們停下。",""]],"l3-0873":[["形容詞：重要的；顯著的","important / notable","The new bridge brought a significant reduction in travel times across the valley.","新橋大幅縮短了穿越山谷的交通時間。",""]],"l3-0874":[["名詞：相似之處","resemblance / likeness","The similarity between the two paintings made us question who had copied whom.","兩幅畫的相似之處，讓我們懷疑究竟是誰模仿了誰。",""]],"l3-0875":[["名詞：宗教或道德上的罪","wrongdoing / transgression","The sermon described greed as a sin that could damage a whole community.","講道把貪婪描述為一種會傷害整個社群的罪。",""]],"l3-0876":[["形容詞：真誠的","genuine / heartfelt","Please accept my sincere apology for forgetting our meeting yesterday.","昨天忘了我們的約，請接受我真誠的道歉。",""]],"l3-0877":[["及物動詞：小口喝","take small drinks of","She sipped her hot tea while looking out at the rainy street.","她一邊望著下雨的街道，一邊小口喝熱茶。","近義片語強調每次只喝一小口；單說 drink slowly 只表示速度慢，未必是小口啜飲。"]],"l3-0878":[["名詞：情況","circumstances / state of affairs","The manager explained the situation before asking us to work extra hours.","經理先說明情況，再請我們加班。",""]],"l3-0879":[["名詞：冰鞋","ice skate","One skate had a broken lace, so we stopped to replace it.","一隻冰鞋的鞋帶斷了，所以我們停下來更換。",""]],"l3-0880":[["名詞：滑雪板","無直接同義詞","He carried his skis to the lift at the bottom of the slope.","他扛著滑雪板，走向坡底的纜車。",""]],"l3-0881":[["及物動詞：略過","omit / leave out","Do not skip the first step when following these instructions.","依照這些說明操作時，不要跳過第一個步驟。",""]],"l3-0882":[["名詞：摩天大樓","無直接同義詞","The glass skyscraper reflected the clouds above the busy city.","玻璃帷幕摩天大樓映照出繁忙城市上方的雲朵。","high-rise building 包括高度未達摩天大樓規模的高樓。"]],"l3-0883":[["名詞：奴隸","enslaved person","The novel tells the story of a slave who escaped to freedom.","小說敘述一名奴隸逃離束縛、獲得自由的故事。",""]],"l3-0884":[["名詞：袖子","無直接同義詞","She rolled up her sleeves before washing the dirty dishes.","洗髒碗盤前，她先捲起了袖子。",""]],"l3-0885":[["名詞：薄片","thin piece","He placed a slice of cheese between two pieces of bread.","他在兩片麵包中間放了一片起司。","slice 特指切下的薄片。"]],"l3-0886":[["形容詞：濕滑的","slick","The wooden steps became slippery after the rain began.","開始下雨後，木階梯變得很滑。",""]],"l3-0887":[["名詞：斜坡","incline / hillside","The children ran down the gentle slope toward the lake.","孩子們沿著緩坡跑向湖邊。",""]],"l3-0888":[["形容詞：光滑的","even / polished","Years of flowing water had made the stones smooth and round.","多年水流沖刷，讓石頭變得光滑圓潤。",""]],"l3-0889":[["不及物動詞：突然折斷","break / crack","The thin branch snapped under the weight of the heavy snow.","厚重積雪壓得細樹枝啪地折斷了。",""]],"l3-0890":[["形容詞：結實堅固的","sturdy / strong","The table feels solid even when all four children lean on it.","即使四個孩子都靠在桌上，桌子仍感覺很穩固。",""]],"l3-0891":[["副詞：未來某一天","one day","Someday I hope to return to the village where my grandparents lived.","我希望將來有一天能回到祖父母住過的村莊。","someday 常指未來不確定的某一天；eventually 著重最後終於發生，語氣不同。"]],"l3-0892":[["副詞：以某種方式","in some way","We somehow managed to fit all the luggage into the small car.","我們不知怎麼地，竟然把所有行李都塞進了小車。",""]],"l3-0893":[["副詞：某個時候","at some point","Let's meet for coffee sometime next week when your schedule is less crowded.","下週你比較不忙時，我們找個時間喝咖啡吧。",""]],"l3-0894":[["副詞：有點","slightly / rather","The room was somewhat smaller than it looked in the photograph.","房間比照片看起來小了一點。",""]],"l3-0895":[["形容詞：痠痛的","aching / painful","My legs were sore after climbing the stairs to the tower.","爬樓梯登上塔樓後，我的腿很痠痛。",""]],"l3-0896":[["名詞：悲傷","grief / sadness","Her voice was full of sorrow as she described losing her home.","她描述失去家園的經歷時，聲音充滿悲傷。",""]],"l3-0897":[["名詞：鐵鍬","shovel","The gardener pushed the spade into the soil to dig a planting hole.","園丁把鐵鍬插入土中，挖了一個種植用的洞。","spade 常為平鏟面；shovel 通常較適合鏟起材料。"]],"l3-0898":[["名詞：義大利長麵","無直接同義詞","We served spaghetti with a simple sauce made from fresh tomatoes.","我們把義大利長麵配上用新鮮番茄做的簡單醬汁。","pasta 是更廣的義大利麵類別，不是直接同義詞。"]],"l3-0899":[["形容詞：明確具體的","precise / explicit","Please give specific examples to explain why the plan should change.","請提出具體例子，說明為什麼應該修改計畫。",""]],"l3-0900":[["名詞：香料","無直接同義詞","A little spice can give this plain soup a richer flavor.","加一點香料，就能讓這道清淡的湯風味更豐富。","seasoning 也包含鹽等調味品，範圍比 spice 廣。"]],"l3-0901":[["及物動詞：灑出","accidentally pour out","I spilled some coffee on the table while reaching for my phone.","我伸手拿手機時，把一些咖啡灑到了桌上。","本句 spill 指不小心使液體灑出。"]],"l3-0902":[["及物動詞：使旋轉","twirl / rotate","The child spun the wooden top on the smooth kitchen floor.","孩子在光滑的廚房地板上轉起了木陀螺。",""]],"l3-0903":[["不及物動詞：吐口水","expectorate","The player spat into the grass after getting dirt in his mouth.","球員嘴裡進了泥土，便朝草地吐了一口唾沫。","spit 的過去式可用 spat 或 spit；expectorate 很正式。"]],"l3-0904":[["名詞：惡意","malice / ill will","He hid the invitation out of spite after their argument.","他們爭吵後，他出於惡意藏起了邀請函。",""]],"l3-0905":[["及物動詞：潑灑","spatter","The children splashed water at each other in the shallow pool.","孩子們在淺水池裡互相潑水。","splash 通常指較明顯地潑濺；spatter 偏指灑成水滴。"]],"l3-0906":[["及物動詞：破壞樂趣","ruin / mar","The sudden rain did not spoil our afternoon at the beach.","突然下起的雨沒有掃了我們下午在海邊玩的興致。",""]],"l3-0907":[["及物動詞：扭傷","twist","She sprained her ankle when she stepped into a hole.","她踩進一個坑洞時扭傷了腳踝。","twist 指扭到，是否構成韌帶扭傷仍有差別。"]],"l3-0908":[["名詞：噴散的水滴","shower of droplets","The waterfall's spray left tiny drops on our jackets.","瀑布濺起的水霧在我們外套上留下細小水珠。",""]],"l3-0909":[["及物動詞：撒上","scatter","Sprinkle chopped parsley over the soup just before serving it.","湯上桌前，撒上切碎的巴西里。","sprinkle 著重少量、分散地撒上。"]],"l3-0910":[["名詞：間諜","secret agent / intelligence agent","The spy passed a coded message to her contact at the station.","間諜在車站把一則暗號訊息交給接頭人。",""]],"l3-0911":[["及物動詞：擠壓","press / compress","Squeeze the lemon gently to release its juice into the bowl.","輕輕擠壓檸檬，讓檸檬汁流進碗裡。",""]],"l3-0912":[["及物動詞：刺；戳","pierce / jab","He stabbed a piece of potato with his fork and lifted it.","他用叉子叉起一塊馬鈴薯。",""]],"l3-0913":[["名詞：馬廄","horse barn","The rider led the tired horse back to the stable.","騎士把疲倦的馬牽回馬廄。",""]],"l3-0914":[["名詞：體育場","arena","Thousands of fans filled the stadium for the final football match.","數千名球迷湧進體育場，觀看足球決賽。","arena 常指中央競技區或室內場館，構造未必相同。"]],"l3-0915":[["集合名詞：全體員工","personnel / workforce","The hotel staff arranged an early breakfast for guests leaving before sunrise.","飯店員工為日出前就要離開的房客安排了提早供應的早餐。",""]],"l3-0916":[["形容詞：不新鮮的","old / no longer fresh","The bread had become stale after sitting uncovered overnight.","麵包沒蓋好放了一夜，已經變乾、不新鮮了。",""]],"l3-0917":[["不及物動詞：盯著看","gaze / look fixedly","The child stared at the huge dinosaur skeleton in silence.","孩子默默盯著那具巨大的恐龍骨架。",""]],"l3-0918":[["不及物動詞：挨餓","go hungry","Without the regular food deliveries, many families in the isolated valley would starve.","如果沒有定期送來的糧食，偏遠山谷的許多家庭就會挨餓。","starve 程度較強，可指嚴重挨餓甚至餓死；go hungry 只表示缺食挨餓。"]],"l3-0919":[["名詞：雕像","sculpted figure","A bronze statue of the town's founder stands in the square.","廣場上矗立著城鎮創建者的銅像。",""]],"l3-0920":[["形容詞：穩定的","stable / firm","Keep the ladder steady while I reach for the box.","我拿箱子的時候，幫忙扶穩梯子。",""]],"l3-0921":[["形容詞：陡峭的","sharply sloping","The path became so steep that we had to stop and rest.","小路變得非常陡，我們只好停下來休息。",""]],"l3-0922":[["名詞：繼子女","無直接同義詞","She helped her stepchild settle into a new school after the family moved.","搬家後，她幫助繼子女適應新學校。","指配偶與前段伴侶關係所生的孩子；原稿「前配偶所生」容易誤導。"]],"l3-0923":[["名詞：繼父","stepdad","His stepfather taught him how to repair a punctured bicycle tire.","他的繼父教他如何修補被刺破的自行車輪胎。","stepdad 是較口語、親切的說法。"]],"l3-0924":[["名詞：繼母","stepmom / stepmum","My stepmother helped me prepare a speech for the school ceremony.","繼母幫我準備學校典禮的演講稿。","stepmom 多見美式，stepmum 多見英式。"]],"l3-0925":[["名詞：立體音響設備","stereo system","We played the old records on my father's stereo after dinner.","晚餐後，我們用父親的立體音響播放老唱片。",""]],"l3-0926":[["形容詞：黏的","tacky / adhesive","The sticky label left a mark when I peeled it off.","我撕下黏黏的標籤時，它留下了痕跡。",""]],"l3-0927":[["形容詞：僵硬的","rigid / inflexible","My neck felt stiff after I slept in the armchair.","在扶手椅上睡了一覺後，我的脖子感到僵硬。",""]],"l3-0928":[["及物動詞：螫","無直接同義詞","A bee stung her hand when she reached into the flowerpot.","她把手伸進花盆時，被蜜蜂螫了一下。","sting 過去式為 stung；bite 是咬，機制不同。"]],"l3-0929":[["及物動詞：攪拌","mix","Stir the sauce gently so it does not stick to the pan.","輕輕攪拌醬汁，避免它黏在鍋底。",""]],"l3-0930":[["名詞：縫的一針；針腳","無直接同義詞","The tailor added a few small stitches to strengthen the pocket.","裁縫添了幾道細小的針腳，把口袋縫得更牢固。",""]],"l3-0931":[["名詞：長襪","無直接同義詞","She carefully pulled on a pair of stockings before putting on her shoes.","穿鞋之前，她小心地穿上一雙長襪。",""]],"l3-0932":[["名詞：凳子","backless seat","The musician sat on a wooden stool while tuning her guitar.","音樂家坐在木凳上，替吉他調音。",""]],"l3-0933":[["形容詞：暴風雨的","tempestuous","The fishing boats stayed in the harbor during the stormy weather.","暴風雨期間，漁船留在港內。","tempestuous 較書面。"]],"l3-0934":[["名詞：策略","plan / approach","The coach changed the team's strategy after watching the first half.","看完上半場後，教練改變了球隊的策略。",""]],"l3-0935":[["名詞：力氣","power / force","It took all his strength to lift the heavy suitcase onto the rack.","他使盡力氣，才把沉重的行李箱抬上架子。",""]],"l3-0936":[["及物動詞：剝除","remove / peel off","We stripped the old paint from the door before applying a new coat.","重新上漆前，我們先剝除了門上的舊漆。",""]],"l3-0937":[["名詞：長條","band / narrow piece","She cut a strip of cloth to tie around the package.","她剪下一條布，綁在包裹外面。",""]],"l3-0938":[["名詞：結構","framework / organization","The essay's clear structure makes the writer's argument easy to follow.","文章結構清楚，讓讀者容易理解作者的論點。",""]],"l3-0939":[["形容詞：固執的","obstinate / headstrong","The stubborn boy refused to admit that he had taken the wrong path.","那個固執的男孩不肯承認自己走錯路。",""]],"l3-0940":[["名詞：藝術工作室","atelier / workshop","The artist's studio overlooks a courtyard filled with climbing plants.","藝術家的工作室能俯瞰一座長滿攀爬植物的庭院。","atelier 為較正式的藝術家工作室用語。"]],"l3-0941":[["不可數名詞：東西（口語）","things / belongings","Put your stuff in the spare room until we finish moving the furniture.","我們搬完家具前，先把你的東西放在空房間。",""]],"l3-0942":[["不可數名詞：填充物","stuffing / filling","Some of the stuff inside the torn cushion had spilled onto the sofa.","破坐墊裡的一些填充物掉到了沙發上。",""]],"l3-0943":[["名詞：風格","manner / approach","Her simple writing style makes complicated ideas easy to understand.","她簡潔的寫作風格，讓複雜的概念也容易理解。",""]],"l3-0944":[["名詞：物質","material","The scientist tested the unknown substance found in the water sample.","科學家檢測了水樣中發現的不明物質。",""]],"l3-0945":[["名詞：郊區住宅區","outlying residential area","They moved to a quiet suburb with good train connections to the city.","他們搬到一處安靜的郊區，搭火車進城很方便。",""]],"l3-0946":[["及物動詞：吸","draw in","The vacuum cleaner sucked the dust from beneath the heavy sofa.","吸塵器吸走了沉重沙發底下的灰塵。","suck 著重利用吸力吸入。"]],"l3-0947":[["及物動詞：遭受","experience / endure","The village suffered serious damage when the river flooded last spring.","去年春天河水氾濫時，村莊遭受了嚴重破壞。",""]],"l3-0948":[["形容詞：足夠的","enough / adequate","There is sufficient space in the car for all our camping equipment.","車內有足夠空間放下我們所有露營裝備。",""]],"l3-0949":[["及物動詞：建議","recommend / propose","The guide suggested taking an earlier bus to avoid the crowds.","導遊建議搭較早的公車，以避開人潮。","suggest doing，不用 suggest someone to do。"]],"l3-0950":[["名詞：自殺","taking one's own life","The charity organized a meeting on suicide prevention for local teachers.","慈善機構為當地教師舉辦了一場自殺防治會議。",""]],"l3-0951":[["形容詞：合適的","appropriate / fitting","This quiet café is suitable for a small afternoon meeting.","這家安靜的咖啡館適合舉行小型下午會議。",""]],"l3-0952":[["名詞：金額；總額","amount / total","They donated a large sum to help rebuild the village school.","他們捐了一大筆錢，協助重建村裡的學校。",""]],"l3-0953":[["名詞：摘要","overview / synopsis","The report begins with a short summary of the main findings.","報告開頭先以簡短摘要說明主要發現。",""]],"l3-0954":[["名詞：山頂","peak / mountaintop","Clouds hid the summit as we began climbing from the village.","我們從村莊開始往上爬時，山頂被雲遮住了。",""]],"l3-0955":[["形容詞：更好的","better / higher-quality","The more expensive tent proved superior in strong wind and heavy rain.","遇到強風大雨時，比較貴的帳篷表現更好。","比較對象用 superior to，不用 superior than。"]],"l3-0956":[["及物動詞：猜想；認為","assume / think","I suppose the shop is closed because all the lights are off.","店裡的燈都關了，我猜已經打烊了。",""]],"l3-0957":[["及物動詞：環繞","encircle / enclose","Tall trees surround the old house at the end of the lane.","巷子盡頭的老房子四周環繞著高樹。",""]],"l3-0958":[["名詞：調查","poll / study","The school conducted a survey to learn which lunch dishes students preferred.","學校進行了一項調查，了解學生喜歡哪些午餐菜色。","survey 可透過問卷或訪談等方式收集資料；study 的範圍更廣。"]],"l3-0959":[["名詞：生存","continued existence","The animals' survival depends on protecting the forest where they live.","保護這些動物棲息的森林，是牠們生存的關鍵。",""]],"l3-0960":[["名詞：生還者","無直接同義詞","A survivor of the shipwreck described how a fishing boat rescued the passengers.","一位船難生還者描述了漁船如何救起乘客。",""]],"l3-0961":[["及物動詞：懷疑；猜想","think / have a suspicion","I suspect that the missing keys are still in your coat pocket.","我猜那些找不到的鑰匙還在你的外套口袋裡。",""]],"l3-0962":[["名詞：懷疑","doubt / mistrust","Her explanation raised suspicion because it did not match the earlier account.","她的說明與先前的敘述不符，因此引起懷疑。",""]],"l3-0963":[["及物動詞：發誓保證","vow / promise solemnly","He swore that he had never opened the locked drawer.","他發誓自己從未打開那個鎖著的抽屜。","swear 的過去式為 swore，過去分詞為 sworn。"]],"l3-0964":[["不可數名詞：汗水","perspiration","Sweat ran down his face as he carried the boxes upstairs.","他把箱子搬上樓時，汗水從臉上流下。",""]],"l3-0965":[["不及物動詞：腫起","puff up / become swollen","Her ankle began to swell after she fell on the uneven path.","她在不平的路上摔倒後，腳踝開始腫起。",""]],"l3-0966":[["形容詞：迅速的","quick / rapid","The manager's swift response kept the small problem from becoming serious.","經理迅速回應，避免小問題變得嚴重。",""]],"l3-0967":[["名詞：開關","無直接同義詞","The light switch is on the wall just inside the door.","電燈開關在門內側的牆上。",""]],"l3-0968":[["名詞：劍","blade","The knight raised his sword as the castle gates opened.","城堡大門開啟時，騎士舉起了劍。","blade 可借指刀劍，但也可只指刀刃。"]],"l3-0969":[["名詞：制度；系統","method / organized scheme","The library introduced a new system for reserving popular books.","圖書館導入了一套預約熱門書籍的新系統。",""]],"l3-0970":[["名詞：刻字石板","inscribed slab","The archaeologist discovered a stone tablet covered with ancient writing.","考古學家發現了一塊刻滿古老文字的石板。","本卡示範刻寫板義；tablet 另有藥錠、平板電腦等常見義。"]],"l3-0971":[["名詞：短平頭釘","short flat-headed nail","He used a tack to fasten the fabric to the wooden frame.","他用一枚短釘把布固定在木框上。",""]],"l3-0972":[["名詞：標籤","label","The price tag was missing from the jacket I wanted to buy.","我想買的那件外套沒有標價牌。",""]],"l3-0973":[["名詞：裁縫師","無直接同義詞","The tailor measured my shoulders before adjusting the new suit.","裁縫師修改新西裝前，先量了我的肩寬。",""]],"l3-0974":[["形容詞：馴服的","docile","The tame deer came close enough to eat from the keeper's hand.","那隻馴服的鹿走近到可以吃飼養員手裡的食物。","tame 指已馴服、不怕人的；docile 著重溫順。"]],"l3-0975":[["名詞：水龍頭","faucet","The kitchen tap kept dripping until the plumber replaced a small part.","廚房水龍頭一直滴水，直到水管工換掉一個小零件。",""]],"l3-0976":[["及物動詞：輕拍","pat / touch lightly","She tapped my shoulder to let me know the bus had arrived.","她輕拍我的肩膀，告訴我公車到了。",""]],"l3-0977":[["名詞：稅","levy","The price on the label does not include the local sales tax.","標籤上的價格不包含當地的銷售稅。",""]],"l3-0978":[["及物動詞：逗弄","kid / make fun of","Her brothers teased her about the enormous hat she wore to the picnic.","她的兄弟拿她戴去野餐的那頂大帽子逗她。","make fun of 可能比 tease 更帶嘲弄意味。"]],"l3-0979":[["形容詞：技術方面的","無直接同義詞","The manual explains the technical details of setting up the equipment.","手冊說明了設備安裝的技術細節。","specialized 泛指專業領域，不一定是技術。"]],"l3-0980":[["名詞：技法","method / approach","The teacher demonstrated a simple technique for blending watercolor paints.","老師示範了一個調和水彩的簡單技法。",""]],"l3-0981":[["名詞：科技","applied science","New technology allows farmers to check soil conditions without digging holes.","新科技讓農夫不必挖洞，就能檢查土壤狀況。","applied science 著重科學的實際應用，涵蓋面不完全相同。"]],"l3-0982":[["名詞：脾氣","temperament / disposition","His gentle temper made him a patient teacher of young children.","他脾氣溫和，因此教導幼童時很有耐心。",""]],"l3-0983":[["名詞：溫度","無直接同義詞","The temperature dropped quickly after the sun disappeared behind the mountains.","太陽隱沒在群山後，氣溫迅速下降。",""]],"l3-0984":[["形容詞：暫時的","short-term / provisional","The library moved into a temporary building during the roof repairs.","修理屋頂期間，圖書館暫時搬進另一棟建築。",""]],"l3-0985":[["及物動詞：照料","care for / look after","She tends the garden every morning before leaving for work.","她每天早上出門上班前都會照料花園。",""]],"l3-0986":[["不及物動詞：往往會","be inclined to","The buses tend to be crowded around the time school finishes.","放學時段附近，公車往往很擁擠。","tend to 後接原形動詞，表示常有某種傾向。"]],"l3-0987":[["形容詞：軟嫩的","soft","The meat was tender enough to cut easily with a fork.","肉軟嫩到用叉子就能輕易切開。",""]],"l3-0988":[["名詞：領土","land / domain","The river forms the boundary between the two countries' territories.","那條河構成了兩國領土的邊界。",""]],"l3-0989":[["名詞：正文","main body / written content","The text explains the experiment, while the diagrams show the equipment.","正文說明實驗，圖則展示所用設備。",""]],"l3-0990":[["形容詞：感激的","grateful / appreciative","We were thankful for the neighbor's help when our car broke down.","車子拋錨時，我們很感激鄰居伸出援手。",""]],"l3-0991":[["名詞：理論","explanatory framework","The scientist developed a theory to explain the unusual pattern in the data.","科學家提出了一套理論，解釋資料中的異常模式。",""]],"l3-0992":[["名詞：口渴","無直接同義詞","A glass of cool water satisfied my thirst after the long walk.","走了很長一段路後，一杯涼水解了我的渴。",""]],"l3-0993":[["名詞：縫紉線","無直接同義詞","Choose a thread that matches the color of the torn shirt.","挑一條與破襯衫顏色相配的縫紉線。",""]],"l3-0994":[["名詞：威脅；危害","danger / menace","The growing fire posed a serious threat to the nearby village.","火勢愈來愈大，對附近村莊構成嚴重威脅。",""]],"l3-0995":[["及物動詞：恐嚇","intimidate / menace","The robber threatened the cashier with a knife and demanded money.","搶匪拿刀威脅收銀員，要求交出金錢。","threaten someone with something。"]],"l3-0996":[["及物動詞：搔癢","無直接同義詞","The puppy's soft fur tickled my arm as it climbed onto my lap.","小狗爬上我大腿時，柔軟的毛弄得我手臂癢癢的。",""]],"l3-0997":[["名詞：潮水","無直接同義詞","We walked back from the rocks before the tide came in.","漲潮前，我們從礁石區走了回來。",""]],"l3-0998":[["形容詞：整齊的","neat / orderly","Her desk was tidy, with every notebook arranged in a straight row.","她的書桌很整齊，所有筆記本都排成筆直的一列。",""]],"l3-0999":[["形容詞：緊身的","close-fitting / snug","The jacket felt tight across my shoulders when I raised my arms.","我抬起雙臂時，覺得外套肩部很緊。",""]],"l3-1000":[["及物動詞：拴緊；轉緊","fasten firmly","Tighten the screws until the shelf no longer moves from side to side.","把螺絲鎖緊，直到層板不再左右晃動。","tighten 著重把原本鬆的東西弄緊。"]],"l3-1001":[["名詞：木材","lumber","The builders stacked the timber under a roof to keep it dry.","工人把木材堆在有屋頂遮蔽的地方，讓它保持乾燥。","lumber 主要為美式建築用木材用語。"]],"l3-1002":[["名詞：面紙","paper tissue","She handed him a tissue after he spilled tea on his hand.","他把茶灑到手上後，她遞給他一張面紙。",""]],"l3-1003":[["不可數名詞：菸草","無直接同義詞","The old warehouse once stored tobacco brought in from nearby farms.","那座舊倉庫曾儲存附近農場送來的菸草。",""]],"l3-1004":[["名詞：噸","無直接同義詞","The truck can carry several tons of sand in one trip.","那輛卡車一趟可以運送好幾噸沙。","ton 有不同制度；公噸通常明確寫 metric ton 或 tonne。"]],"l3-1005":[["名詞：陸龜","無直接同義詞","The tortoise moved slowly across the garden toward a patch of lettuce.","陸龜慢慢爬過花園，朝一小片萵苣前進。","turtle 範圍依地區用法而異，不一定專指陸龜。"]],"l3-1006":[["及物動詞：拋","throw","He tossed the keys to his younger brother across the kitchen table.","他隔著餐桌，把鑰匙拋給了弟弟。",""]],"l3-1007":[["名詞：觀光業","travel industry","Tourism provides many seasonal jobs for people living near the coast.","觀光業為沿海居民提供了許多季節性工作。",""]],"l3-1008":[["名詞：觀光客","sightseer","The tourist asked a local shopkeeper for directions to the old temple.","觀光客向當地店主問了去老廟的路。",""]],"l3-1009":[["及物動詞：拖曳","pull / haul","A truck towed our broken car to the nearest repair shop.","拖吊車把我們故障的車拖到最近的維修廠。",""]],"l3-1010":[["名詞：痕跡","sign / remnant","By morning, the snow had covered every trace of our footprints.","到了早上，積雪已掩蓋我們腳印的所有痕跡。",""]],"l3-1011":[["名詞：商人","merchant / dealer","The trader brought silk and spices to the crowded market.","商人把絲綢與香料帶到熱鬧的市場。",""]],"l3-1012":[["名詞：步道","path / track","A narrow trail winds through the forest to the waterfall.","一條狹窄步道蜿蜒穿過森林，通往瀑布。",""]],"l3-1013":[["名詞：交通運輸","transportation","Public transport makes it possible to visit the town without a car.","公共運輸讓人不必開車也能到那座城鎮遊覽。",""]],"l3-1014":[["名詞：垃圾","garbage / rubbish","Please put your trash in the bins near the park entrance.","請把垃圾丟進公園入口附近的垃圾桶。",""]],"l3-1015":[["名詞：旅人","traveller / wayfarer","A tired traveler stopped at the café to ask about nearby accommodation.","一位疲倦的旅人到咖啡館詢問附近的住宿。","traveller 為英式拼字；wayfarer 較文學，常指徒步旅人。"]],"l3-1016":[["名詞：托盤","無直接同義詞","The waiter carried six glasses of water on a round tray.","服務生用圓形托盤端著六杯水。",""]],"l3-1017":[["不及物動詞：發抖","shake / quiver","Her hands trembled as she opened the letter with her exam results.","她拆開裝有考試成績的信時，雙手在發抖。",""]],"l3-1018":[["名詞：趨勢","tendency / pattern","The survey shows a growing trend toward working from home.","調查顯示，在家工作有日益普遍的趨勢。",""]],"l3-1019":[["名詞：部族","無直接同義詞","The museum worked with members of the tribe to present their history accurately.","博物館與部族成員合作，準確呈現他們的歷史。","tribe 的使用須尊重群體自稱；不一律等於 race。"]],"l3-1020":[["形容詞：棘手的","difficult / awkward","Parking on the narrow street was tricky because of the delivery trucks.","那條街很窄，又有送貨卡車，要停車很不容易。",""]],"l3-1021":[["名詞：軍隊（通常用複數）","soldiers / military forces","Troops arrived in the valley to help repair the damaged road.","部隊抵達山谷，協助修復受損道路。","軍隊、士兵合稱常用 troops。"]],"l3-1022":[["形容詞：熱帶的","無直接同義詞","The greenhouse contains tropical plants that cannot survive the cold winters outside.","溫室裡種著無法在戶外寒冬存活的熱帶植物。","equatorial 指赤道附近，比 tropical 範圍窄。"]],"l3-1023":[["名詞：汽車行李廂（美式）","boot","We put the suitcases in the trunk before driving to the airport.","開車去機場前，我們把行李箱放進汽車行李廂。","boot 為英式用法。"]],"l3-1024":[["形容詞：如實的","honest / accurate","The witness gave a truthful account of what she had seen.","目擊者如實敘述了她所見的情況。",""]],"l3-1025":[["名詞：浴缸","bathtub / bath","The child floated a toy boat in the tub during bath time.","洗澡時，孩子讓一艘玩具船漂在浴缸裡。",""]],"l3-1026":[["及物動詞：用力拉","pull / yank","The child tugged his mother's sleeve to get her attention.","孩子拉了拉母親的袖子，想引起她的注意。","原稿詞頭混入音標成為「tug [tʌg」；正確詞頭是 tug。"]],"l3-1027":[["名詞：鬱金香","無直接同義詞","Red tulips opened along the path after several warm spring days.","春天暖了幾天後，小徑兩旁的紅色鬱金香開了。",""]],"l3-1028":[["不及物動詞：跌落翻滾","fall / roll","The loose stones tumbled down the slope when I stepped forward.","我往前踏一步時，鬆動的石頭沿著斜坡滾了下去。",""]],"l3-1029":[["名詞：旋律","melody / air","She hummed a familiar tune while washing the breakfast dishes.","她洗早餐碗盤時，哼著一段熟悉的旋律。","air 指曲調時較文學。"]],"l3-1030":[["名詞：家教","private teacher","A tutor helped him understand the algebra problems he found difficult.","一位家教幫他弄懂那些他覺得困難的代數題。",""]],"l3-1031":[["名詞：細枝","small branch","The bird carried a twig to its nest under the roof.","鳥兒叼著一根細枝，飛到屋簷下的巢。",""]],"l3-1032":[["名詞：雙胞胎之一","無直接同義詞","My twin lives abroad, but we talk to each other every week.","我的雙胞胎手足住在國外，但我們每週都會通話。",""]],"l3-1033":[["及物動詞：扭轉","turn / rotate","Twist the lid gently until it comes off the jar.","輕輕轉動蓋子，直到能從罐子上取下。",""]],"l3-1034":[["名詞：打字機","無直接同義詞","The novelist wrote her first book on a borrowed typewriter.","小說家用借來的打字機寫出了她的第一本書。",""]],"l3-1035":[["形容詞：典型的","無直接同義詞","The small stone house is typical of buildings in this mountain region.","那間小石屋是這個山區的典型建築。",""]],"l3-1036":[["名詞：工會","labor union / trade union","The union asked management to improve safety conditions in the factory.","工會要求管理階層改善工廠的安全條件。",""]],"l3-1037":[["及物動詞：使團結","bring together / join","The campaign united neighbors who had rarely spoken to each other before.","這場活動讓原本很少交談的鄰居團結起來。",""]],"l3-1038":[["名詞：團結","solidarity / togetherness","The team's unity helped them remain focused after several disappointing results.","幾次成績不理想後，團隊的團結讓他們仍能保持專注。",""]],"l3-1039":[["名詞：宇宙","cosmos","The children asked whether there might be life elsewhere in the universe.","孩子們問，宇宙其他地方是否也可能有生命。",""]],"l3-1040":[["連接詞：除非","except if / if not","We will eat in the garden unless it starts raining.","除非開始下雨，否則我們會在花園裡吃飯。","unless 相當於 if ... not；改寫時須調整否定位置，本句可改為 if it does not start raining。"]],"l3-1041":[["及物動詞：使難過；使心煩","distress / trouble","The news about the damaged school upset many former students.","學校受損的消息讓許多校友很難過。",""]],"l3-1042":[["形容詞：空著的","empty / unoccupied","There were no vacant seats on the morning train to the city.","開往市區的早班火車上沒有空位。",""]],"l3-1043":[["形容詞：貴重的","precious","The museum keeps its most valuable coins in a locked display case.","博物館把最珍貴的錢幣放在上鎖的展示櫃裡。",""]],"l3-1044":[["名詞：廂型車","無直接同義詞","The delivery van stopped outside the bakery before the morning rush.","早晨尖峰時段前，送貨廂型車停在麵包店外。",""]],"l3-1045":[["不及物動詞：消失","disappear / fade away","The mountain vanished behind the clouds as we drove farther north.","我們繼續往北開，山峰消失在雲層後方。",""]],"l3-1046":[["名詞：種類繁多","diversity / assortment","The market offers a wide variety of vegetables grown on nearby farms.","市場販售附近農場種植的各式各樣蔬菜。",""]],"l3-1047":[["形容詞：各式各樣的","different / assorted","We considered various routes before choosing the road along the coast.","我們考慮了好幾條路線，才選擇沿海的道路。",""]],"l3-1048":[["不及物動詞：有所不同","differ / change","Ticket prices vary depending on the day and time of travel.","票價會隨出發日期與時間而不同。",""]],"l3-1049":[["名詞：花瓶","無直接同義詞","A tall glass vase held the sunflowers beside the kitchen window.","廚房窗邊，一只高玻璃花瓶插著向日葵。",""]],"l3-1050":[["名詞：車輛","無直接同義詞","The narrow bridge allows only one vehicle to cross at a time.","那座窄橋一次只容許一輛車通過。","vehicle 指運載用的車輛或裝置；means of transport 的範圍較廣。"]],"l3-1051":[["不可數名詞：韻文","poetry","The play was written in verse and performed by local students.","那齣戲以韻文寫成，由當地學生演出。",""]],"l3-1052":[["名詞：西裝背心（美式）","waistcoat","He wore a gray vest under his jacket at the wedding.","婚禮上，他在外套裡穿了一件灰色背心。","waistcoat 為英式；英式 vest 也常指內衣背心。"]],"l3-1053":[["名詞：副總裁","無直接同義詞","The company's vice-president met the new employees during their first week.","公司副總裁在新員工到職第一週與他們見面。","常見拼字也有 vice president；不同組織的 deputy president 職級未必相同。"]],"l3-1054":[["名詞：受害者","sufferer","The volunteers helped each flood victim complete an application for assistance.","志工幫助每位水災受害者填寫援助申請表。",""]],"l3-1055":[["名詞：暴力","physical aggression / brutality","The community organized a peaceful march to protest violence in the neighborhood.","社區舉辦了一場和平遊行，抗議街區裡的暴力事件。",""]],"l3-1056":[["形容詞：猛烈的","fierce / intense","A violent storm damaged several boats tied up in the harbor.","一場猛烈暴風雨損壞了港內停泊的幾艘船。",""]],"l3-1057":[["形容詞：紫羅蘭色的","bluish-purple","Violet ribbons decorated the white chairs along the garden path.","花園小徑旁的白色椅子裝飾著紫羅蘭色絲帶。","原稿詞性為 adj 卻只列花名；本句依形容詞用法教紫羅蘭色。花名 violet 是名詞。"]],"l3-1058":[["形容詞：看得見的","in sight / observable","The lighthouse was barely visible through the thick morning fog.","透過濃濃的晨霧，幾乎看不見燈塔。",""]],"l3-1059":[["名詞：視力","eyesight / sight","His poor vision made it difficult to read the small print.","他視力不好，很難閱讀細小的文字。",""]],"l3-1060":[["名詞：維生素","無直接同義詞","The food label lists the vitamins found in each serving.","食品標籤列出每份所含的維生素。",""]],"l3-1061":[["形容詞：鮮明生動的","graphic / lifelike","Her vivid description made us feel as though we were inside the storm.","她生動的描述讓我們彷彿置身暴風雨中。",""]],"l3-1062":[["名詞：音量","loudness / sound level","Please lower the volume because the baby is sleeping upstairs.","寶寶正在樓上睡覺，請把音量調低。",""]],"l3-1063":[["及物動詞：搖擺","move from side to side","The dog wagged its tail when it heard its owner's footsteps.","狗聽到主人的腳步聲，就搖起尾巴。","此處提供釋義片語，描述尾巴來回搖擺；wag 的過去式為 wagged。"]],"l3-1064":[["名詞：工資","pay / earnings","The workers received higher wages after completing the training program.","工人完成培訓課程後，獲得了更高的工資。",""]],"l3-1065":[["名詞：四輪運貨馬車","無直接同義詞","Two horses pulled a wagon loaded with vegetables toward the town market.","兩匹馬拉著一輛滿載蔬菜的貨車，前往鎮上市場。",""]],"l3-1066":[["不及物動詞：醒來","wake up / awaken","I wakened before dawn and listened to rain falling on the roof.","天亮前我醒了，聽著雨滴落在屋頂上的聲音。","waken 比 wake up 較書面。"]],"l3-1067":[["不及物動詞：閒逛","roam / stroll","We wandered through the old market without looking for anything in particular.","我們在老市場隨意閒逛，沒有特別要找什麼。",""]],"l3-1068":[["名詞：溫暖","heat","The warmth of the fire soon dried our wet jackets.","爐火的暖意很快烘乾了我們的濕外套。","此句採溫度義，不是情感上的熱情。"]],"l3-1069":[["及物動詞：警告","alert / caution","The guide warned us about loose stones on the narrow path.","導遊提醒我們小心狹窄路上的鬆動石塊。",""]],"l3-1070":[["名詞：蠟","無直接同義詞","Warm wax dripped from the candle onto the wooden table.","溫熱的蠟從蠟燭滴到了木桌上。",""]],"l3-1071":[["及物動詞：削弱","undermine / reduce the strength of","Repeated flooding weakened the wooden supports beneath the old bridge.","反覆淹水削弱了老橋下方的木製支架。",""]],"l3-1072":[["名詞：財富","riches / fortune","The family's wealth came from a business started by their grandparents.","這家人的財富來自祖父母創辦的企業。",""]],"l3-1073":[["形容詞：富有的","rich / affluent","A wealthy donor paid for new instruments for the school band.","一位富有的捐款人出資替學校樂隊購買新樂器。",""]],"l3-1074":[["及物動詞：編織","interlace / intertwine","The artist wove thin strips of bamboo into a strong basket.","藝術家把細竹片編成一個堅固的籃子。","weave 的過去式為 wove，過去分詞通常為 woven。"]],"l3-1075":[["名詞：蜘蛛網","spiderweb / cobweb","Morning dew shone on the web stretched between two branches.","晨露在兩根樹枝間的蜘蛛網上閃閃發亮。","cobweb 常指積塵或廢棄的蜘蛛網。"]],"l3-1076":[["名詞：雜草","unwanted plant","A tall weed had grown through a crack in the pavement.","一株高高的雜草從人行道裂縫中長了出來。",""]],"l3-1077":[["不及物動詞：哭泣","cry / shed tears","She wept quietly when she read the letter from her old friend.","讀到老朋友的信時，她靜靜落下淚來。",""]],"l3-1078":[["不可數名詞：小麥","無直接同義詞","The golden wheat moved gently in the wind across the field.","田野裡金黃色的小麥隨風輕輕搖曳。",""]],"l3-1079":[["名詞：鞭子","lash","The museum displayed a leather whip beside the old horse carriage.","博物館在舊馬車旁展出了一條皮鞭。","lash 也可指鞭子的柔韌鞭梢。"]],"l3-1080":[["名詞：哨子","無直接同義詞","The referee blew his whistle to signal the end of the match.","裁判吹哨，示意比賽結束。",""]],"l3-1081":[["形容詞：邪惡的","evil","The wicked king forced the villagers to surrender their winter food supplies.","邪惡的國王強迫村民交出過冬的糧食。",""]],"l3-1082":[["名詞：柳樹","無直接同義詞","The willow's long branches nearly touched the surface of the pond.","柳樹的長枝幾乎碰到了池塘水面。",""]],"l3-1083":[["不及物動詞：眨一隻眼示意","無直接同義詞","She winked at me to show that her serious words were only a joke.","她朝我眨了眨眼，表示那些嚴肅的話只是玩笑。","blink 通常指一般眨眼，不一定帶示意。"]],"l3-1084":[["及物動詞：擦拭","clean / rub","Wipe the table with a damp cloth before setting out the plates.","擺盤子前，先用濕布擦桌子。",""]],"l3-1085":[["名詞：智慧","good judgment / insight","Her grandmother's wisdom helped her make a difficult decision about work.","祖母的智慧幫助她在工作上作出艱難的決定。",""]],"l3-1086":[["及物動詞：包裹","cover / enclose","Wrap the glass carefully in paper before putting it in the box.","把玻璃杯放進盒子前，先仔細用紙包好。",""]],"l3-1087":[["名詞：手腕","無直接同義詞","The bracelet was too loose and slipped off her wrist.","手鍊太鬆，從她的手腕滑了下來。",""]],"l3-1088":[["名詞：X 光片","radiograph","The dentist showed me an X-ray of my back teeth.","牙醫給我看了一張後排牙齒的 X 光片。","X-ray 可指射線、檢查或影像；本句採影像義。"]],"l3-1089":[["不及物動詞：打呵欠","無直接同義詞","He yawned during the early meeting after staying up all night.","他熬了一整夜，在一早的會議中打起呵欠。",""]],"l3-1090":[["及物動詞：大聲喊叫","shout / call out","She yelled my name across the crowded station platform.","她隔著擁擠的車站月台，大聲喊我的名字。",""]],"l3-1091":[["名詞：蛋黃","無直接同義詞","The recipe requires two egg yolks, but we saved the whites for later.","食譜需要兩顆蛋黃，我們把蛋白留著之後用。",""]],"l3-1092":[["名詞：小孩；年輕人","child / young person","The coach encouraged each youngster to try the new obstacle course.","教練鼓勵每個孩子試試新的障礙訓練場。",""]],"l3-1093":[["名詞：拉鍊","zip","The zipper on my jacket got stuck just as I was leaving.","我正要出門時，外套拉鍊卡住了。","zip 常用於英式英語。"]],"l3-1094":[["名詞：區域","area / district","Cars are not allowed inside the pedestrian zone during the afternoon market.","下午市集營業時，汽車不得進入行人徒步區。",""]],"l4-0001":[["動詞：放棄計畫","give up","We abandoned the plan to camp when the river began to rise.","河水開始上漲時，我們放棄了露營計畫。","abandon 後直接接受詞；give up 是片語動詞。"]],"l4-0002":[["名詞：腹部","belly","The nurse placed a warm blanket over the patient's abdomen.","護理師把一條溫暖的毛毯蓋在病人的腹部。","belly 較口語；abdomen 常用於醫療或解剖語境。"]],"l4-0003":[["形容詞：完全的","complete / total","There was absolute silence in the hall before the announcement.","宣布消息之前，大廳裡一片寂靜。",""]],"l4-0004":[["動詞：吸收液體","soak up","Use a clean towel to absorb the water on the floor.","用乾淨的毛巾吸掉地板上的水。","soak up 可用於此處吸收液體的意思。"]],"l4-0005":[["形容詞：抽象的","conceptual","Young children may find abstract ideas easier to understand through stories.","透過故事，幼童可能更容易理解抽象的概念。","conceptual 強調概念層面，並非所有 abstract 的用法都能替換。"],["名詞：論文摘要","summary","Read the abstract before deciding whether to download the full research paper.","先讀摘要，再決定是否下載整篇研究論文。","abstract 通常指論文等學術作品的摘要。"]],"l4-0006":[["形容詞：學術的","scholarly","The library provides free access to several academic journals.","圖書館提供數種學術期刊的免費閱覽服務。",""]],"l4-0007":[["名詞：口音","無直接同義詞","Although she speaks English fluently, she still has a noticeable French accent.","雖然她的英語說得流利，仍帶有明顯的法國口音。","pronunciation 指發音，範圍較廣，並非 accent 的直接同義詞。"]],"l4-0008":[["名詞：接受、接納","approval","The new recycling policy has gained widespread acceptance among residents.","新的回收政策已獲得居民普遍接受。","approval 偏重贊同；acceptance 也可能只是願意接受。"]],"l4-0009":[["名詞：進入、使用的權限","entry","Only staff members have access to the equipment room.","只有員工可以進入器材室。","entry 在此指進入；access 還可指使用資料或服務的權限。"],["動詞：存取、使用","無直接同義詞","Students can access the course materials through the school website.","學生可以透過學校網站存取課程資料。","access 作動詞直接接受詞，不加 to；have access to 才使用 to。"]],"l4-0010":[["形容詞：意外的、非故意的","unintentional","The accidental deletion of the folder cost us an afternoon of work.","誤刪那個資料夾讓我們損失了一個下午的工作成果。",""]],"l4-0011":[["動詞：陪同","go with / escort","A parent must accompany each child on the museum's evening tour.","每位孩童參加博物館晚間導覽時，都必須有一位家長陪同。","escort 通常帶有引領或保護的意味。"],["動詞：為音樂表演伴奏","無直接同義詞","My sister will accompany the school choir on the piano.","我姊姊將為學校合唱團鋼琴伴奏。","此義常用 accompany someone on the piano 等結構。"]],"l4-0012":[["動詞：完成任務","complete / achieve","With everyone's help, we accomplished the task before sunset.","在大家的幫忙下，我們在日落前完成了任務。","achieve 較常搭配目標或成果，如 achieve a goal。"]],"l4-0013":[["名詞：成就","achievement","Finishing her first marathon was an accomplishment she would never forget.","跑完人生第一場馬拉松，是她永遠難忘的成就。",""]],"l4-0014":[["名詞：會計人員","無直接同義詞","Our accountant checked the figures before we submitted the annual report.","我們提交年度報告之前，會計人員核對了數字。","bookkeeper 與 auditor 分別指簿記人員、稽核人員，職務並不完全相同。"]],"l4-0015":[["名詞：準確性","correctness","Please check the accuracy of every address before mailing the invitations.","寄出邀請函前，請檢查每個地址是否正確。",""]],"l4-0016":[["動詞：指控","charge","The customer accused the shop of selling damaged goods as new.","那位顧客指控商店把損壞的商品當新品販售。","accuse someone of；charge someone with 多用於正式指控。"]],"l4-0017":[["名詞：酸","無直接同義詞","The students wore safety glasses while handling acid in the laboratory.","學生在實驗室處理酸液時戴著護目鏡。","此處 acid 為化學物質的名稱，不等於形容詞 acidic。"]],"l4-0018":[["動詞：使熟悉","familiarize","The guide acquainted us with the island's history before the tour began.","導覽開始前，導遊先讓我們了解這座島的歷史。","acquaint someone with something；familiarize someone with something。"]],"l4-0019":[["名詞：認識但不熟的人","無直接同義詞","An old acquaintance recognized me at the airport and came over to say hello.","一位以前認識的人在機場認出我，走過來打招呼。","acquaintance 通常沒有 friend 那麼親近。"]],"l4-0020":[["動詞：獲得、習得","gain / obtain","She acquired valuable teaching experience while volunteering at the community center.","她在社區中心擔任志工期間，累積了寶貴的教學經驗。","acquire experience 常指透過時間與實踐獲得經驗。"]],"l4-0021":[["名詞：英畝","無直接同義詞","The family grows vegetables on a small farm of about five acres.","這家人在一座約五英畝的小農場種蔬菜。","acre 是面積單位；hectare（公頃）是不同單位。"]],"l4-0022":[["動詞：修改使適用","modify / adjust","The teacher adapted the activity for students with limited English.","老師調整了這項活動，讓英語能力有限的學生也能參加。",""],["動詞：改編作品","無直接同義詞","The director adapted her favorite novel into a film.","這位導演把她最喜歡的小說改編成電影。","adapt a novel into a film 指從一種作品形式改編為另一種。"]],"l4-0023":[["形容詞：足夠的","sufficient / enough","Make sure there is adequate space between the tables for wheelchairs.","請確保桌子之間留有足夠空間，方便輪椅通行。",""]],"l4-0024":[["名詞：形容詞","無直接同義詞","Choose a more specific adjective to describe the sound of the engine.","選一個更具體的形容詞來描述引擎的聲音。",""]],"l4-0025":[["動詞：調整","alter / modify","You can adjust the height of the chair using the lever underneath.","你可以用椅子下方的控制桿調整椅面高度。","adjust 常指為了合適或準確而做小幅調整。"]],"l4-0026":[["名詞：調整","modification / alteration","A slight adjustment to the camera angle made the photograph much clearer.","稍微調整相機角度後，照片清楚多了。",""]],"l4-0027":[["形容詞：值得敬佩的","commendable / praiseworthy","Her patience with the younger children was admirable.","她對年幼孩子的耐心令人敬佩。",""]],"l4-0028":[["名詞：敬佩","respect / esteem","The team expressed their admiration for the coach's dedication.","隊員們表達了對教練奉獻精神的敬佩。",""]],"l4-0029":[["名詞：進入許可；入場費；承認","entry / entry fee","Admission to the science museum includes access to the planetarium show.","科學博物館的入場費包含天文館展演。","admission 可指進入許可、入場費或承認事實。"],["名詞：進入許可；入場費；承認（另一例）","entry / entry fee","The admission desk opens thirty minutes before the first museum tour.","博物館的入場櫃檯在第一場導覽前三十分鐘開放。","admission 可指進入許可、入場費或承認事實。"]],"l4-0030":[["名詞：副詞","無直接同義詞","The adverb in this sentence tells us how carefully she worked.","這句話中的副詞告訴我們，她工作時有多仔細。",""]],"l4-0031":[["名詞：代辦機構","無直接同義詞","We asked a travel agency to arrange transport from the airport.","我們請旅行社安排從機場出發的交通接送。","travel agency 為旅行社；agency 的近義詞需依機構性質判斷。"]],"l4-0032":[["名詞：代理人","representative","The author's agent negotiated a new contract with the publisher.","這位作家的經紀人與出版社協商了一份新合約。","agent 常指獲授權代他人處理事務的人。"]],"l4-0033":[["形容詞：咄咄逼人的","hostile / confrontational","The customer's aggressive tone made the new employee uncomfortable.","顧客咄咄逼人的語氣讓新員工感到不自在。","此義帶有敵意；積極進取的 aggressive 是另一義項。"]],"l4-0034":[["形容詞：宜人的","pleasant / enjoyable","We spent an agreeable afternoon reading beside the lake.","我們在湖邊閱讀，度過了一個愉快的下午。",""]],"l4-0035":[["名詞：愛滋病","無直接同義詞","The charity supports families affected by AIDS.","這個慈善組織為受愛滋病影響的家庭提供支持。","AIDS 是疾病名稱；HIV 是病毒名稱，兩者不能當同義詞。"]],"l4-0036":[["名詞：酒、含酒精飲料","alcoholic drinks","This restaurant serves fresh juice but does not sell alcohol.","這家餐廳供應新鮮果汁，但不販售酒類。","alcohol 此處泛指酒類；在化學語境中另有較精確的意思。"]],"l4-0037":[["形容詞：警覺的","watchful / vigilant","The guard remained alert throughout the quiet night.","警衛在寧靜的夜裡始終保持警覺。",""],["動詞：提醒、使注意","warn / notify","Please alert the staff if you notice a problem with the equipment.","如果你發現設備有問題，請告知工作人員。","warn 強調警告危險；notify 偏重正式通知。"]],"l4-0038":[["名詞：零用錢","pocket money","He saves half of his weekly allowance to buy a bicycle.","他每週把一半的零用錢存起來，準備買腳踏車。","allowance 也可指津貼；pocket money 僅適用於零用錢的意思。"]],"l4-0039":[["名詞：鋁","aluminium","The ladder is made of aluminum, so it is easy to carry.","這架梯子是鋁製的，因此很容易搬動。","aluminium 是英式拼法，與 aluminum 指同一種金屬。"]],"l4-0040":[["時間標記：上午","in the morning","The first bus leaves at 6 a.m., well before sunrise.","第一班公車早上六點發車，那時離日出還有一段時間。","a.m. 放在時間數字後；in the morning 的句法位置不同。"]],"l4-0041":[["名詞：業餘愛好者","nonprofessional","Although he is an amateur, his wildlife photographs have won several prizes.","雖然他是業餘攝影者，拍攝的野生動物照片卻得過好幾個獎。","amateur 不一定表示技術差，重點是未以此為專業職業。"]],"l4-0042":[["形容詞：有抱負的","aspiring / driven","The ambitious young chef hopes to open her own restaurant one day.","這位有抱負的年輕主廚希望有一天能開自己的餐廳。","driven 強調強烈動力；aspiring 常接所嚮往的職業。"]],"l4-0043":[["介系詞：在某情況之中","amidst","The mayor resigned amid growing criticism of the transport plan.","在交通計畫遭到越來越多批評之際，市長辭職了。",""]],"l4-0044":[["動詞：逗樂","entertain","The puppy's attempts to climb onto the sofa amused the children.","小狗試圖爬上沙發的模樣逗得孩子們很開心。","amuse 常含使人發笑之意；entertain 的娛樂範圍較廣。"]],"l4-0045":[["名詞：覺得有趣的心情","無直接同義詞","She watched with amusement as her cat chased its own tail.","她看著貓追自己的尾巴，覺得十分有趣。","with amusement 表示覺得好笑或有趣，不必然真的笑出聲。"]],"l4-0046":[["名詞：分析","examination / study","Our analysis of the survey revealed a strong demand for evening classes.","我們對問卷的分析顯示，晚間課程有很大的需求。","analysis 強調拆解資訊以理解關係，比一般 study 更具體。"]],"l4-0047":[["動詞：分析","examine / study","The researchers analyzed water samples from six locations along the river.","研究人員分析了河流沿線六個地點的水樣。",""]],"l4-0048":[["名詞：祖先","forebear / forefather","Her ancestors moved to this island more than two hundred years ago.","她的祖先在兩百多年前遷居到這座島。","forefather 通常指男性祖先，也可泛稱先人。"]],"l4-0049":[["名詞：週年紀念日","無直接同義詞","They returned to the seaside hotel for their twentieth wedding anniversary.","他們在結婚二十週年紀念日時，再次入住那間海濱飯店。",""]],"l4-0050":[["動詞：使煩惱、惹惱","irritate / bother","The constant noise from the construction site annoyed the neighbors.","工地持續不斷的噪音惹得鄰居們很煩。",""]],"l4-0051":[["形容詞：每年一次的","yearly","The town's annual book festival attracts readers from across the region.","鎮上一年一度的書展吸引了各地的讀者。",""]],"l4-0052":[["名詞：焦慮","worry / unease","Waiting for the interview results filled him with anxiety.","等待面試結果讓他滿心焦慮。","此處為一般情緒，不代表醫學上的診斷。"]],"l4-0053":[["形容詞：焦慮的","worried / uneasy","She felt anxious about leaving her dog with a stranger.","她對於把狗交給陌生人照顧感到不安。",""]],"l4-0054":[["動詞：道歉","say sorry","The waiter apologized for bringing us the wrong order.","服務生為送錯餐點向我們道歉。","apologize to someone for something；說明原因時也可接 for doing。"]],"l4-0055":[["名詞：道歉","expression of regret","The company sent a written apology for the delay in delivery.","公司針對延遲送貨寄來了一封書面道歉信。","expression of regret 是近義表達，但單純表示遺憾未必承認過失。"]],"l4-0056":[["名詞：家用電器","無直接同義詞","Unplug the appliance before moving it to another room.","把電器搬到另一個房間前，請先拔掉插頭。","device、equipment 範圍較廣，並非家用電器的直接同義詞。"]],"l4-0057":[["名詞：申請人","candidate","Each applicant must submit a résumé and two letters of recommendation.","每位申請人都必須提交履歷和兩封推薦信。","candidate 可指候選人；applicant 明確指已提出申請的人。"]],"l4-0058":[["名詞：申請","request","The university received her application just before the deadline.","大學在截止期限前不久收到了她的申請。","application 通常是依程序提出的正式申請，request 範圍較廣。"],["名詞：應用","use","The workshop explores the practical application of mathematics in everyday life.","這場工作坊探討數學在日常生活中的實際應用。",""]],"l4-0059":[["動詞：任命","name / designate","The board appointed a new director after three months of interviews.","經過三個月的面試，董事會任命了一位新主管。",""]],"l4-0060":[["名詞：預約會面","meeting","I have an appointment with the career adviser on Thursday afternoon.","我預約了星期四下午與職涯顧問會面。","appointment 指事先約定的會面；meeting 不一定有預約的意思。"],["名詞：任命","selection / designation","Her appointment as principal was announced at the staff meeting.","她獲任命為校長的消息在教職員會議上宣布了。","selection 強調選擇人選；appointment 強調正式授予職位。"]],"l4-0061":[["名詞：感謝","gratitude / thanks","The students wrote a letter of appreciation to their volunteer tutor.","學生們寫了一封感謝信給義務家教老師。",""]],"l4-0062":[["形容詞：適當的","suitable / fitting","Comfortable walking shoes are appropriate for the outdoor tour.","這趟戶外導覽適合穿舒適的步行鞋。",""]],"l4-0063":[["名詞：批准","authorization / permission","We cannot begin the repairs without the building owner's approval.","沒有屋主的批准，我們不能開始修繕。",""]],"l4-0064":[["名詞：拱門","archway","Visitors pass through a stone arch to enter the old courtyard.","遊客穿過一道石拱門，進入古老的庭院。","archway 指拱形通道；arch 也可指其他拱形結構。"]],"l4-0065":[["動詞：出現、產生","emerge / occur","Unexpected difficulties arose when we tried to move the heavy cabinet.","我們試著搬動那個沉重的櫥櫃時，出現了意想不到的困難。","arise 的過去式為 arose；此處不等於使某物升起的 raise。"]],"l4-0066":[["複數名詞：武器","weapons / armaments","The museum has a collection of arms used by medieval soldiers.","這間博物館收藏了中古時期士兵使用的武器。","此義使用複數 arms，與手臂的 arm 不同。"]],"l4-0067":[["動詞：引起情緒或反應","awaken / stir","The mysterious letter aroused her curiosity about the empty house.","那封神祕的信引起了她對那間空屋的好奇。",""]],"l4-0068":[["名詞：文章","piece","I read an interesting article about urban gardens in yesterday's newspaper.","我在昨天的報紙上讀到一篇關於城市花園的有趣文章。","piece 可指一篇文章，範圍比 article 廣；詞條尾端的 1 是原稿分義標記。"]],"l4-0069":[["形容詞：人造的","synthetic / man-made","The florist arranged artificial flowers in the hotel lobby.","花藝師在飯店大廳擺放了人造花。","synthetic 偏重人工合成的材料；artificial 範圍較廣。"]],"l4-0070":[["形容詞：藝術方面的","無直接同義詞","The school encourages artistic expression through music, painting, and dance.","學校透過音樂、繪畫和舞蹈鼓勵藝術表達。","creative 偏重創造力，不完全等於與藝術相關的 artistic。"]],"l4-0071":[["形容詞：感到羞愧的","embarrassed","He was ashamed of laughing at his classmate's mistake.","他為自己嘲笑同學的錯誤感到羞愧。","ashamed 常涉及做錯事的羞愧；embarrassed 常指尷尬。"]],"l4-0072":[["名詞：某事的一個方面","facet / dimension","The report examines the environmental aspects of building a new airport.","這份報告探討興建新機場所涉及的環境層面。",""]],"l4-0073":[["名詞：阿斯匹靈","無直接同義詞","The pharmacist asked whether she had taken aspirin that morning.","藥師詢問她當天早上是否服用過阿斯匹靈。","aspirin 是特定藥物名稱，不能與所有止痛藥畫上等號。"]],"l4-0074":[["動詞：組裝","put together","It took us two hours to assemble the new desk.","我們花了兩個小時組裝新書桌。",""]],"l4-0075":[["名詞：集會","gathering","The principal introduced the exchange students at the morning assembly.","校長在早上的集會中介紹了交換學生。",""]],"l4-0076":[["動詞：分派工作","allocate","The manager assigned a different section of the report to each team member.","經理把報告中的不同部分分派給每一位組員。","assign a task to someone；allocate 也常用於分配時間、資源。"]],"l4-0077":[["名詞：課業作業","task","Our first writing assignment is a short description of a familiar place.","我們的第一份寫作作業是簡短描述一個熟悉的地方。","task 範圍較廣；assignment 是分派給某人的工作或作業。"]],"l4-0078":[["名詞：協助","help / aid","Please ask a member of staff if you need assistance with your luggage.","如果你需要協助搬運行李，請洽工作人員。",""]],"l4-0079":[["名詞：工作夥伴","colleague / partner","She discussed the proposal with a trusted business associate.","她與一位信任的商業夥伴討論了這項提案。","associate 不一定是法律上的合夥人；partner 的關係可能更緊密。"],["動詞：聯想","connect / link","I always associate the smell of fresh bread with my grandmother's kitchen.","聞到剛出爐麵包的香味，我總會想起祖母的廚房。","associate A with B 表示在心中將兩者聯繫起來。"]],"l4-0080":[["名詞：協會","society / organization","The local teachers' association holds a meeting every month.","當地的教師協會每個月舉行一次會議。","organization 是較廣的組織概念。"]],"l4-0081":[["動詞：未經確認便認為","suppose / presume","I assumed the shop was open because the lights were still on.","因為燈還亮著，我便以為那家店仍在營業。",""],["動詞：承擔職責","take on","She assumed responsibility for the project when her supervisor retired.","主管退休後，她承擔起這個專案的責任。",""]],"l4-0082":[["名詞：保證","promise / guarantee","We received an assurance that the repairs would be finished by Friday.","我們獲得保證，維修會在星期五之前完成。","assurance 常指使人放心的承諾；guarantee 語氣通常較強。"]],"l4-0083":[["動詞：向某人保證","reassure","The guide assured us that there was enough time to catch the train.","導遊向我們保證，還有足夠時間趕上火車。","assure someone that…；reassure 特別強調消除疑慮。"]],"l4-0084":[["形容詞：運動的","sporting","The new athletic facilities include a running track and an indoor pool.","新的運動設施包括跑道和室內游泳池。",""]],"l4-0085":[["名詞：自動提款機","cash machine / automated teller machine","I stopped at an ATM to withdraw some cash before visiting the market.","去市場之前，我在自動提款機前停下來領了一些現金。","cash machine 較常見於英式英語。"]],"l4-0086":[["名詞：氣氛","ambience / mood","Soft lighting creates a relaxed atmosphere in the small restaurant.","柔和的燈光讓這間小餐廳充滿輕鬆的氣氛。",""]],"l4-0087":[["名詞：原子","無直接同義詞","The diagram shows the parts of an atom in different colors.","這張圖以不同顏色呈現原子的各個部分。","molecule（分子）不是 atom 的同義詞。"]],"l4-0088":[["形容詞：原子的","無直接同義詞","The students used a computer model to explore atomic structure.","學生利用電腦模型探索原子結構。","atomic 指原子層面；nuclear 指原子核，不能全面互換。"]],"l4-0089":[["動詞：附上、繫上","fasten / affix","Attach a name tag to your suitcase before checking it in.","辦理行李託運前，請在行李箱上繫上姓名吊牌。","attach something to something；affix 語氣較正式。"]],"l4-0090":[["名詞：電子郵件附件","無直接同義詞","The photographs are included as an attachment to this email.","照片已作為這封電子郵件的附件附上。","attachment 指附加的檔案；file 只是檔案，不一定是附件。"]],"l4-0091":[["名詞：吸引人的景點","draw","The castle is the town's main tourist attraction.","那座城堡是鎮上最主要的觀光景點。","draw 作名詞可指吸引人前來的事物，較不正式。"]],"l4-0092":[["形容詞：音訊的、聲音的","sound","The archive contains audio recordings of interviews with local residents.","這個檔案庫收藏了訪問當地居民的錄音。","在 audio recordings 中，可用名詞修飾語 sound 表達相近意思。"]],"l4-0093":[["名詞：權限","power","Only the director has the authority to approve purchases of this size.","只有主管有權核准這麼大筆的採購。","authority 指獲認可或被授予的權力；power 範圍較廣。"]],"l4-0094":[["名詞：自傳","無直接同義詞","In her autobiography, the singer describes growing up in a small coastal town.","這位歌手在自傳中描述了自己在海邊小鎮長大的經歷。","memoir 通常選述部分人生經歷，不完全等於 autobiography。"]],"l4-0095":[["動詞：等待","wait for","Passengers gathered near the gate to await the boarding announcement.","旅客聚集在登機門附近，等待登機廣播。","await 直接接受詞；wait for 需要介系詞 for。"]],"l4-0096":[["形容詞：尷尬的","uncomfortable / embarrassing","An awkward silence followed when I forgot the speaker's name.","我忘記講者的名字後，現場陷入一陣尷尬的沉默。",""]],"l4-0097":[["名詞：背包","rucksack","She packed a raincoat and a water bottle in her backpack.","她把雨衣和水壺放進背包。","rucksack 較常見於英式英語。"]],"l4-0098":[["形容詞：禿頭的","hairless","My grandfather was already bald when he was in his thirties.","我祖父三十多歲時就已經禿頭了。","hairless 可形容全身或物體表面無毛；bald 通常指頭頂無髮。"]],"l4-0099":[["名詞：芭蕾舞","無直接同義詞","She has studied ballet since she was seven years old.","她從七歲起就學習芭蕾舞。","dance 是舞蹈的總稱，並非 ballet 的直接同義詞。"]],"l4-0100":[["形容詞：破產的","insolvent","The company went bankrupt after losing its largest customer.","失去最大客戶後，那家公司破產了。","insolvent 指無力償債；bankrupt 常涉及正式破產狀態。"]],"l4-0101":[["動詞：討價還價","haggle / negotiate","We bargained with the seller for a lower price on the rug.","我們跟賣家討價還價，希望用較低的價格買下地毯。","bargain with someone over/for something；此用法是不及物動詞。"],["名詞：划算的商品","good deal","At half the original price, this winter coat was a real bargain.","這件冬季外套只要原價的一半，真的買得很划算。",""]],"l4-0102":[["名詞：阻隔物","obstruction / obstacle","Workers placed a barrier across the road while they repaired the bridge.","工人修橋時，在路上放置了路障。","barrier 常指刻意設置、阻止通行的設施。"]],"l4-0103":[["名詞：盆","bowl","She filled a basin with warm water to wash the vegetables.","她在盆裡裝滿溫水，準備洗蔬菜。","bowl 是近義詞；basin 常指較大的盆或洗手盆。"]],"l4-0104":[["名詞：電池","無直接同義詞","The remote control needs a new battery before it will work again.","遙控器需要換一顆新電池，才能再次使用。",""]],"l4-0105":[["名詞：鳥喙","bill","The bird carried a small twig in its beak.","那隻鳥嘴裡叼著一根小樹枝。",""]],"l4-0106":[["動詞：眉開眼笑","smile broadly","She beamed with pride as her son received his diploma.","兒子領到畢業證書時，她驕傲地笑開了臉。","beam 在此與光束無關；詞條的 2 是分義標記。"]],"l4-0107":[["名詞：行為、舉止","conduct","The coach praised the players for their respectful behavior toward the opposing team.","教練稱讚球員們對對手表現得很有禮貌。",""]],"l4-0108":[["名詞：傳記","life story","The biography describes how the scientist continued her research during the war.","這本傳記描述了那位科學家如何在戰爭期間持續研究。","biography 通常由他人撰寫；autobiography 是自傳。"]],"l4-0109":[["名詞：生物學","無直接同義詞","In biology class, we examined leaves collected from the school garden.","生物課上，我們觀察了從學校花園採集的葉子。",""]],"l4-0110":[["名詞：刀片、刀刃部分","無直接同義詞","The blade of this kitchen knife needs sharpening.","這把菜刀的刀刃需要磨一磨了。","blade 是刀的切割部分，不等於整把 knife。"]],"l4-0111":[["動詞：混合","mix / combine","Blend the flour and butter until the mixture looks like fine crumbs.","將麵粉與奶油混合，直到混合物看起來像細碎的麵包屑。",""]],"l4-0112":[["名詞：祝福","benediction","The priest offered a blessing before the family began their journey.","一家人啟程前，牧師為他們祝福。","benediction 較正式，通常用於宗教祝福。"]],"l4-0113":[["動詞：眨眼","無直接同義詞","He blinked several times as his eyes adjusted to the bright sunlight.","眼睛適應強烈陽光時，他眨了好幾次眼。","wink 通常指有意眨一隻眼，不等於一般的 blink。"]],"l4-0114":[["動詞：開花","flower / blossom","The roses usually bloom in late spring and fill the garden with color.","玫瑰通常在春末開花，讓花園充滿繽紛色彩。",""]],"l4-0115":[["名詞：樹上的花","flower / bloom","Pink blossoms covered the cherry trees along the river.","河邊的櫻花樹開滿了粉紅色的花。","blossom 常指果樹或開花樹木上的花。"]],"l4-0116":[["動詞：臉紅","flush / redden","She blushed when the teacher read her poem aloud to the class.","老師向全班朗讀她的詩時，她臉紅了。","blush 常因害羞或尷尬；flush 也可能因熱或其他原因。"]],"l4-0117":[["動詞：吹噓","brag","He kept boasting about how much money he had earned.","他不停吹噓自己賺了多少錢。",""]],"l4-0118":[["名詞：情感聯繫","tie / connection","Caring for the injured dog created a strong bond between the two neighbors.","照顧那隻受傷的狗，讓兩位鄰居之間建立了深厚情誼。",""]],"l4-0119":[["動詞：彈跳","rebound","The ball bounced off the wall and landed behind the sofa.","球從牆上彈回來，落在沙發後面。",""]],"l4-0120":[["名詞：手環、手鐲","無直接同義詞","She wore a silver bracelet that her grandmother had given her.","她戴著祖母送給她的銀手環。","bangle 通常指硬式環狀手鐲，並非所有 bracelet 都是 bangle。"]],"l4-0121":[["名詞：胸罩","bra","The shop sells brassieres in a wide range of sizes.","這家商店販售各種尺寸的胸罩。","brassiere 較正式，日常通常說 bra。"]],"l4-0122":[["動詞：繁殖","reproduce","These birds breed on the island during the summer months.","這些鳥在夏季於島上繁殖。",""],["名詞：品種","variety","This breed of dog has a thick coat and pointed ears.","這個品種的狗有濃密的毛和尖尖的耳朵。","breed 用於經繁殖形成的動物品種；variety 的範圍較廣。"]],"l4-0123":[["名詞：新郎","groom","The bridegroom waited at the entrance while the guests took their seats.","賓客入座時，新郎在入口處等候。",""]],"l4-0124":[["動詞：以上方強熱烤炙","grill","Broil the peppers until their skins begin to darken.","把甜椒放在上方熱源下烤，直到表皮開始變深色。","美式 broil 通常相當於英式 grill，指以上方熱源烤炙。"]],"l4-0125":[["形容詞：手頭沒錢的","penniless / short of money","After paying for the repairs, I was too broke to eat out.","付完修理費後，我窮得沒錢外食了。","broke 在此為口語形容詞，不代表一定已正式破產。"]],"l4-0126":[["形容詞：殘酷的","cruel / savage","The film tells the story of a village under a brutal ruler.","這部電影敘述一座村莊在殘酷統治者掌權下的故事。",""]],"l4-0127":[["名詞：公告、簡報","notice / report","The weather bulletin warned of strong winds along the coast.","氣象簡報提醒沿海地區將有強風。","bulletin 常是簡短而正式的資訊發布。"]],"l4-0128":[["名詞：櫃子","cupboard","Keep the clean towels in the cabinet beside the bathroom door.","把乾淨的毛巾收在浴室門旁的櫃子裡。",""],["名詞：內閣","無直接同義詞","The prime minister discussed the proposal with the cabinet.","首相與內閣討論了這項提案。","cabinet 指政府核心部長組成的團體，不等於整個 government。"]],"l4-0129":[["動詞：計算","compute / work out","We calculated the total cost before choosing a hotel.","我們先計算總費用，再選擇飯店。",""]],"l4-0130":[["名詞：計算","computation","A mistake in the calculation caused us to order too much paint.","計算上的一個錯誤，讓我們訂了太多油漆。",""]],"l4-0131":[["名詞：計算機","無直接同義詞","You may use a calculator for the final section of the exam.","考試的最後一部分可以使用計算機。",""]],"l4-0132":[["名詞：卡路里","無直接同義詞","The nutrition label lists the number of calories in each serving.","營養標示列出了每份食物所含的卡路里數。","calorie 是能量單位，不等於營養素或脂肪。"]],"l4-0133":[["名詞：有組織的宣導活動","drive","The school launched a campaign to reduce plastic waste.","學校發起了一項減少塑膠廢棄物的宣導活動。","drive 作名詞可指為特定目標展開的活動。"]],"l4-0134":[["名詞：候選人","contender","Each candidate explained how they would improve public transport.","每位候選人都說明了自己會如何改善大眾運輸。","contender 強調競爭某個位置或獎項的人。"]],"l4-0135":[["名詞：容納量","無直接同義詞","The hall has a seating capacity of three hundred people.","這座大廳可容納三百人就座。","capacity 在此指最多能容納的數量，不只是一般 size。"]],"l4-0136":[["名詞：斗篷","cloak","The actor put on a long black cape before stepping onto the stage.","演員上台前披上了一件黑色長斗篷。","cloak 與 cape 相近，但不同服裝款式的長度與結構可能不同。"],["名詞：海角","headland / promontory","A lighthouse stands at the tip of the rocky cape.","岩石海角的尖端矗立著一座燈塔。",""]],"l4-0137":[["名詞：首都","無直接同義詞","We spent our first two days exploring the country's capital.","我們前兩天都在遊覽這個國家的首都。",""],["名詞：資本、資金","funds / financing","They need more capital to turn the empty warehouse into a bakery.","他們需要更多資金，才能把空倉庫改造成麵包店。","funds 指資金的範圍較廣；此例 capital 用於創業投資。"],["名詞：大寫字母","uppercase letter","Write your surname in capitals at the top of the form.","請在表格頂端用大寫字母填寫姓氏。","in capitals 表示使用大寫字母。"]],"l4-0138":[["名詞：資本主義","無直接同義詞","The course examines how capitalism developed in different parts of the world.","這門課探討資本主義在世界不同地區的發展。",""]],"l4-0139":[["名詞：資本家","無直接同義詞","The historian described the influence of industrial capitalists on the growing city.","歷史學家描述了工業資本家對這座發展中城市的影響。","investor 指投資者，未必等同持有或控制大量資本的 capitalist。"]],"l4-0140":[["名詞：職業生涯","professional life","She began her career as a reporter for a small local newspaper.","她從一家地方小報的記者做起，展開職業生涯。","career 指長期職業歷程，不只是單一 job。"]],"l4-0141":[["名詞：運輸中的貨物","freight","The ship's cargo included grain, machinery, and medical supplies.","這艘船裝載的貨物包括穀物、機械和醫療物資。",""]],"l4-0142":[["名詞：送信人","無直接同義詞","The mail carrier left the parcel with our next-door neighbor.","郵差把包裹交給了我們的隔壁鄰居。","mail carrier 整體可對應 postman；carrier 單獨使用並不一定指郵差。"]],"l4-0143":[["動詞：雕刻","sculpt","He carved a small bird from a piece of driftwood.","他用一塊漂流木雕出一隻小鳥。","carve 可直接接受詞；sculpt 也包含塑造等不同製作方式。"]],"l4-0144":[["名詞：目錄","listing / directory","The library's online catalogue shows which books are available to borrow.","圖書館的線上目錄會顯示哪些書可以借閱。","catalog 是美式常用拼法；catalogue 常見於英式英語。"]],"l4-0145":[["名詞：光碟","compact disc","I found a CD of my father's favorite songs in the drawer.","我在抽屜裡找到一張收錄父親最愛歌曲的光碟。","CD 的標準全稱通常寫 compact disc。"]],"l4-0146":[["動詞：停止","stop / end","The rain finally ceased just before the outdoor concert began.","戶外音樂會開始前不久，雨終於停了。","此處 cease 是動詞；原稿的名詞標記不適用於這個常用義項。"]],"l4-0147":[["名詞：慶祝活動","festivity","The whole village gathered for the celebration of the school's hundredth anniversary.","全村的人齊聚一堂，慶祝學校成立一百週年。","festivity 較常用複數 festivities 指歡慶活動。"]],"l4-0148":[["名詞：水泥","無直接同義詞","The workers stored bags of cement in a dry shed.","工人把袋裝水泥存放在乾燥的棚屋裡。","concrete 是混凝土，cement 是其中使用的黏結材料，兩者不可混為同義詞。"]],"l4-0149":[["名詞：房間、室","room","A narrow staircase leads to a small chamber beneath the tower.","一道狹窄的樓梯通往塔下的小房間。","chamber 較正式，常用於歷史建築或特定用途的房間。"]],"l4-0150":[["名詞：錦標賽","tournament","Eight teams will compete in the regional basketball championship this weekend.","本週末有八支隊伍將參加地區籃球錦標賽。","tournament 泛指競賽活動；championship 特別以爭奪冠軍為目標。"]],"l4-0151":[["名詞：特徵","feature / trait","One characteristic of this plant is its unusually thick leaves.","這種植物的一項特徵是葉片特別厚。",""]],"l4-0152":[["名詞：慈善團體","charitable organization","The charity provides warm meals for people without permanent homes.","這個慈善團體為沒有固定住所的人提供熱食。",""]],"l4-0153":[["名詞：化學","無直接同義詞","Our chemistry teacher demonstrated how the two substances react when mixed.","化學老師示範了這兩種物質混合後會如何反應。",""]],"l4-0154":[["動詞：珍惜、珍愛","treasure / value","She still cherishes the letters her brother sent while studying abroad.","她至今仍珍藏著哥哥留學期間寄來的信。",""]],"l4-0155":[["動詞：鳥啾啾叫","tweet / cheep","Small birds chirped in the bushes outside my bedroom window.","小鳥在我臥室窗外的灌木叢中啾啾叫。",""]],"l4-0156":[["名詞：家務、雜務","task","Washing the dishes is the household chore I dislike most.","洗碗是我最不喜歡的家務。","chore 常指例行且不太有趣的工作；task 範圍較廣。"]],"l4-0157":[["名詞：歌曲副歌","refrain","Everyone joined in when the singer reached the chorus.","歌手唱到副歌時，大家都跟著唱了起來。","refrain 可指反覆出現的歌詞段落，與 chorus 的音樂結構不一定完全相同。"],["名詞：合唱團","choir","The chorus rehearses in the school hall every Wednesday evening.","合唱團每週三晚上在學校禮堂排練。",""]],"l4-0158":[["名詞：雪茄","無直接同義詞","An old cigar box now holds her collection of foreign coins.","一只舊雪茄盒如今用來裝她收藏的外國硬幣。","cigarette 是香菸，不是 cigar 的同義詞。"]],"l4-0159":[["名詞：電影院","movie theater","The old cinema has reopened after six months of repairs.","那間老電影院整修六個月後重新開幕了。","cinema 常見於英式英語；movie theater 常見於美式英語。"]],"l4-0160":[["形容詞：圓形的","round","The guests sat around a circular table near the window.","賓客圍坐在窗邊的一張圓桌旁。",""]],"l4-0161":[["動詞：流通、循環","flow","Opening the windows allows fresh air to circulate through the room.","打開窗戶可以讓新鮮空氣在房間裡流通。","circulate 常帶有持續流動或繞行之意。"]],"l4-0162":[["名詞：流通、流傳","distribution","The library has removed the damaged books from circulation.","圖書館已停止外借那些損壞的書。","in/from circulation 指是否供人流通使用；distribution 側重分發。"]],"l4-0163":[["名詞：情況","situation / conditions","Under these circumstances, postponing the trip seems sensible.","在這種情況下，延後旅行似乎比較明智。","描述整體情況時，circumstances 常用複數。"]],"l4-0164":[["名詞：平民","noncombatant","Civilians were allowed to return after the military training exercise ended.","軍事演習結束後，平民獲准返回。","noncombatant 指非戰鬥人員，範圍與 civilian 並非完全相同。"]],"l4-0165":[["名詞：文明","無直接同義詞","The exhibition explores the daily life of an ancient civilization.","這個展覽探索一個古文明的日常生活。","culture 與文明密切相關，但所指範圍不同，不宜全面互換。"]],"l4-0166":[["動詞：闡明","explain / make clear","Could you clarify which documents we need to bring to the interview?","你能說清楚我們面試時需要帶哪些文件嗎？",""]],"l4-0167":[["動詞：發生衝突","conflict","The two designers clashed over the choice of colors for the exhibition.","兩位設計師對展覽的配色意見不合，發生了衝突。",""]],"l4-0168":[["名詞：分類","categorization","The classification of these insects is based on the structure of their wings.","這些昆蟲是根據翅膀構造分類的。",""]],"l4-0169":[["動詞：分類","categorize / group","The museum classifies its photographs by date and location.","博物館依日期與地點將照片分類。",""]],"l4-0170":[["名詞：懸崖","precipice","The path follows the edge of a steep cliff above the sea.","這條小徑沿著海上陡峭懸崖的邊緣延伸。","precipice 強調非常陡峭的懸崖。"]],"l4-0171":[["名詞：高潮","peak / high point","The story reaches its climax when the missing child is finally found.","失蹤的孩子終於被找到時，故事達到了高潮。",""]],"l4-0172":[["形容詞：笨手笨腳的","awkward / uncoordinated","I felt clumsy trying to carry three cups without a tray.","沒用托盤就想拿三個杯子，讓我覺得自己笨手笨腳的。",""]],"l4-0173":[["形容詞：粗糙的","rough","The coarse wool irritated the skin around his neck.","粗糙的羊毛刺激了他頸部的皮膚。",""]],"l4-0174":[["名詞：行為規範","rules / guidelines","All employees are expected to follow the company's dress code.","所有員工都應遵守公司的服裝規定。","code 常指一整套規則；guidelines 的約束力可能較弱。"]],"l4-0175":[["動詞：倒塌","fall down / cave in","Part of the old roof collapsed under the weight of the snow.","積雪的重量使老屋的一部分屋頂塌了下來。",""]],"l4-0176":[["名詞：組合","mix / blend","A combination of strong wind and heavy rain damaged the crops.","強風加上豪雨損壞了農作物。",""]],"l4-0177":[["名詞：喜劇","無直接同義詞","We chose a light comedy because everyone wanted something cheerful to watch.","大家都想看些開心的內容，所以我們選了一部輕鬆喜劇。",""]],"l4-0178":[["形容詞：滑稽的、喜劇的","comical / humorous","The actor's comic timing made even a simple line sound funny.","這位演員掌握喜劇節奏的功力，讓簡單的台詞也變得好笑。","詞條尾端的 1 是分義標記。"]],"l4-0179":[["名詞：連環漫畫","comic strip","He reads the comics in the newspaper while eating breakfast.","他吃早餐時會看報紙上的連環漫畫。","此例 comics 指報上的漫畫，comic strip 可對應其中一則；2 是分義標記。"]],"l4-0180":[["名詞：指揮官","commanding officer","The commander ordered the rescue team to leave before dawn.","指揮官命令救援隊在黎明前出發。",""]],"l4-0181":[["名詞：評論、意見","remark / observation","Her comment about the ending started a lively discussion of the novel.","她對結局的一番評論，引發了大家對這本小說的熱烈討論。",""]],"l4-0182":[["名詞：商業、貿易","trade / business","The new railway helped commerce develop between the two cities.","新鐵路促進了兩座城市之間的商業發展。",""]],"l4-0183":[["動詞：犯下罪行","perpetrate","The detective wanted to know who had committed the crime.","偵探想知道是誰犯下了這起罪行。","perpetrate 很正式，通常搭配罪行或有害行為。"]],"l4-0184":[["名詞：溝通","exchange of information","Clear communication between the kitchen and the waiters keeps the restaurant running smoothly.","廚房與服務生之間清楚的溝通，讓餐廳運作順暢。",""]],"l4-0185":[["名詞：社區","neighborhood","The community came together to clean the park after the storm.","暴風雨過後，社區居民一起清理公園。","community 在此著重共同生活的人；neighborhood 偏重居住區域及其居民。"]],"l4-0186":[["名詞：同伴","partner / fellow traveler","My traveling companion preferred quiet villages to crowded cities.","我的旅伴喜歡寧靜的村莊，勝過擁擠的城市。","fellow traveler 適用於旅行情境；companion 的使用範圍較廣。"]],"l4-0187":[["名詞：競賽","contest","She entered a photography competition with a picture of the harbor at dawn.","她拿一張黎明時分的港口照片參加攝影比賽。",""]],"l4-0188":[["形容詞：競爭激烈的","無直接同義詞","The job market is highly competitive for recent graduates.","對剛畢業的人而言，就業市場競爭非常激烈。","rival 可指競爭對手，但不能直接取代此處形容詞 competitive。"]],"l4-0189":[["名詞：競爭對手","rival / opponent","Our main competitor opened a larger store across the street.","我們的主要競爭對手在街道對面開了一家更大的店。",""]],"l4-0190":[["動詞：使複雜化","make more complex","Adding another destination would complicate our travel plans.","再增加一個目的地，會讓我們的旅行計畫變得更複雜。",""]],"l4-0191":[["動詞：創作音樂","write","She composed a short piece for piano and violin.","她為鋼琴與小提琴創作了一首短曲。","compose music 可用 write music 表達相近意思。"],["動詞：構成","make up / constitute","The committee is composed of teachers, parents, and students.","這個委員會由老師、家長和學生組成。","be composed of 表示由……組成；主動結構為 A and B compose C。"]],"l4-0192":[["名詞：作曲家","無直接同義詞","The composer listened carefully as the orchestra rehearsed her new symphony.","管弦樂團排練她的新交響曲時，這位作曲家仔細聆聽。","songwriter 專指歌曲創作者，範圍比 composer 窄。"]],"l4-0193":[["名詞：作文","essay","The teacher asked us to write a composition about a memorable journey.","老師要我們寫一篇關於難忘旅程的作文。","composition 在此指課堂寫作作品，另可指樂曲。"]],"l4-0194":[["動詞：專注","focus","I find it difficult to concentrate when people are talking beside me.","有人在旁邊說話時，我覺得很難專心。","concentrate on 與 focus on 都可接專注的對象。"]],"l4-0195":[["名詞：專注力","focus / attention","The puzzle requires patience and complete concentration.","這個益智題需要耐心與全神貫注。",""]],"l4-0196":[["名詞：概念","idea / notion","The teacher used a simple drawing to explain the concept of balance.","老師用一張簡單的圖畫說明平衡的概念。",""]],"l4-0197":[["介系詞：關於","regarding / about","Please contact the office with any questions concerning your registration.","如果有任何關於報名的問題，請與辦公室聯絡。",""]],"l4-0198":[["形容詞：具體的","specific / definite","We need concrete examples to understand how the new rule will work.","我們需要具體例子，才能了解新規則將如何運作。",""],["名詞：混凝土","無直接同義詞","The workers poured concrete into the wooden frame to make the steps.","工人把混凝土倒進木框裡，製作階梯。","cement（水泥）是製作混凝土的材料之一，不是同義詞。"]],"l4-0199":[["名詞：樂團指揮","無直接同義詞","The conductor raised her baton, and the orchestra fell silent.","指揮舉起指揮棒，管弦樂團隨即安靜下來。","conductor 在此為音樂職務；一般 leader 範圍過廣。"]],"l4-0200":[["名詞：研討會、正式會議","meeting / convention","Researchers from twenty countries attended the conference on ocean conservation.","來自二十個國家的研究人員參加了海洋保育研討會。","conference 常指有特定主題、安排多場討論的正式會議。"]],"l4-0201":[["動詞：坦白承認","admit / own up","He confessed that he had broken the vase while playing indoors.","他坦承在屋內玩耍時打破了花瓶。","own up 常用 own up to something，與 confess that 的結構不同。"]],"l4-0202":[["名詞：自信","self-assurance","Her confidence grew as she practiced speaking in front of small groups.","隨著她練習在小團體面前說話，她的自信逐漸增加。",""]],"l4-0203":[["動詞：限制在某範圍","restrict / limit","Please confine your comments to the issues on today's agenda.","請將你的發言限於今天議程上的議題。",""]],"l4-0204":[["名詞：困惑、混亂","uncertainty / bewilderment","The sudden change of platform caused confusion among the passengers.","突然更換月台，讓旅客們感到困惑。",""]],"l4-0205":[["動詞：祝賀","無直接同義詞","We congratulated our neighbor on the birth of her daughter.","我們祝賀鄰居喜獲千金。","congratulate someone on something；praise 是稱讚，並不完全等於祝賀。"]],"l4-0206":[["名詞：代表大會","convention / assembly","Delegates gathered for the annual congress of the international teachers' union.","代表們齊聚一堂，參加國際教師工會的年度代表大會。","Congress 大寫時還可指美國國會，此例為一般代表大會。"]],"l4-0207":[["名詞：連接詞","linking word","We practiced using conjunctions to join two short sentences into one.","我們練習用連接詞把兩個短句合成一句。","原稿詞性欄漏列；此義為名詞。linking word 是解說性近義表達。"]],"l4-0208":[["動詞：征服、攻下","overcome / subdue","The army failed to conquer the heavily defended fortress.","軍隊未能攻下防守嚴密的堡壘。","conquer 常指以武力取得控制；overcome 範圍較廣。"]],"l4-0209":[["名詞：良心","sense of right and wrong","His conscience would not let him keep the wallet he had found.","他的良心讓他無法把撿到的皮夾據為己有。","所列為釋義式表達；conscience 不等於意識 consciousness。"]],"l4-0210":[["名詞：結果、後果","result / outcome","One consequence of the drought was a sharp rise in food prices.","乾旱造成的後果之一，是食物價格大幅上漲。",""]],"l4-0211":[["形容詞：隨之而來的","resulting / resultant","Heavy snow and the consequent road closures delayed the delivery.","大雪及其導致的道路封閉，延誤了送貨。",""]],"l4-0212":[["形容詞：保守的","traditional / cautious","The family takes a conservative approach to spending and avoids unnecessary purchases.","這家人的消費態度保守，會避免不必要的購物。","此例指審慎保守的態度；不使用原稿列出的罕見防腐劑義項。"]],"l4-0213":[["動詞片語：由……組成","be made up of / comprise","The breakfast set consists of eggs, toast, and a cup of tea.","這份早餐套餐包括雞蛋、吐司和一杯茶。","同義表達對應 consist of 整體；consist 通常不用被動式。"]],"l4-0214":[["形容詞：一致的、穩定的","steady / uniform","The bakery has earned loyal customers by maintaining consistent quality.","這間麵包店靠著維持穩定的品質，贏得了忠實顧客。",""]],"l4-0215":[["名詞：子音","無直接同義詞","She had trouble pronouncing the final consonant in the unfamiliar word.","她不太會唸那個陌生單字最後的子音。",""]],"l4-0216":[["動詞：構成","make up / compose","International students constitute nearly a quarter of the class.","國際學生約占全班人數的四分之一。",""]],"l4-0217":[["名詞：憲法","無直接同義詞","The students compared the constitutions of three different countries.","學生比較了三個不同國家的憲法。","charter 可能指章程或憲章，並非所有語境都等於 constitution。"]],"l4-0218":[["動詞：建造","build / erect","The town plans to construct a footbridge over the busy road.","鎮上計畫在繁忙道路上方興建一座人行天橋。",""]],"l4-0219":[["名詞：建造工程","building","Construction of the new sports center will begin in March.","新運動中心的興建工程將於三月開始。",""]],"l4-0220":[["形容詞：有建設性的","helpful / productive","Her constructive suggestions helped us improve the design without starting over.","她提出的建設性建議讓我們能改善設計，而不用重新開始。",""]],"l4-0221":[["動詞：請教","seek advice from","We consulted an architect before changing the layout of the house.","更動房屋格局之前，我們請教了一位建築師。","consult 直接接受詞，不用說 consult to someone。"]],"l4-0222":[["名詞：顧問","adviser / advisor","The company hired a consultant to review its training program.","公司聘請了一位顧問，檢視員工訓練計畫。",""]],"l4-0223":[["動詞：消耗","use up","Older refrigerators often consume more electricity than newer models.","舊款冰箱的耗電量往往比新款高。",""]],"l4-0224":[["名詞：消費者","buyer / customer","Consumers can compare prices online before visiting a store.","消費者可以先在網路上比價，再到店裡選購。","consumer 強調商品或服務的使用者；buyer 偏重購買者。"]],"l4-0225":[["名詞：容器","receptacle","Store the leftover rice in a clean container with a lid.","把剩飯放在乾淨且有蓋的容器裡保存。","receptacle 較正式。"]],"l4-0226":[["形容詞：滿足的","satisfied / happy","She was content with a quiet evening at home after the long trip.","長途旅行後，能在家安靜地過一個晚上，她就很滿足了。","形容詞 content 重音在第二音節，常用 be content with。"]],"l4-0227":[["名詞：內容物","無直接同義詞","The customs officer asked me to show him the contents of my suitcase.","海關人員請我讓他查看行李箱裡的物品。","contents 複數可指容器裡的全部物品；content 單數另可指含量或內容。"]],"l4-0228":[["名詞：知足、滿足","satisfaction","She felt a quiet sense of contentment as she watched the children playing.","看著孩子們玩耍，她心中湧起一股平靜的滿足感。","contentment 是不可數名詞；原稿的形容詞標記有誤。"]],"l4-0229":[["名詞：比賽","competition","The school held a poster contest to promote water conservation.","學校舉辦海報比賽，宣導節約用水。",""]],"l4-0230":[["名詞：上下文","surrounding text","You can often guess an unfamiliar word's meaning from its context.","你常常可以從上下文猜出陌生單字的意思。","surrounding text 是此語言學義項的解說性近義表達。"]],"l4-0231":[["形容詞：反覆不斷的","repeated / recurring","Continual changes to the schedule made it difficult to arrange childcare.","時間表反覆更動，讓安排托育變得困難。","此義重點是反覆發生，不一定每一刻都沒有間斷。"]],"l4-0232":[["形容詞：持續不中斷的","uninterrupted / nonstop","The machine needs a continuous supply of water to operate safely.","這台機器需要不間斷的供水，才能安全運作。",""]],"l4-0233":[["形容詞：相反的","opposite / opposing","Despite the new evidence, he continued to express a contrary opinion.","儘管出現新證據，他仍持續表達相反的看法。",""]],"l4-0234":[["名詞：明顯差異、對比","difference","The contrast between the crowded city and the quiet village was striking.","擁擠城市與寧靜村莊之間的對比十分鮮明。","contrast 強調對照之下顯得明顯的差異。"]],"l4-0235":[["動詞：捐獻","donate / give","Several local businesses contributed money to repair the community playground.","幾家當地商家捐款，協助修繕社區遊樂場。",""]],"l4-0236":[["名詞：貢獻","input / part","Her contribution to the project went far beyond writing the final report.","她對這個專案的貢獻，遠不止撰寫最終報告而已。","input 常指投入的意見或努力；contribution 的範圍更廣。"]],"l4-0237":[["名詞：便利","ease","Many customers value the convenience of ordering groceries from home.","許多顧客重視在家訂購日用品的便利性。","ease 側重容易、省力；convenience 也指安排上合適便利。"]],"l4-0238":[["名詞：大型會議","conference / congress","Thousands of teachers attended the national education convention.","數千名教師參加了全國教育大會。",""],["名詞：慣例","custom / practice","The designer challenged the convention that formal clothing must be uncomfortable.","這位設計師挑戰了正式服裝必定不舒服的慣常觀念。",""]],"l4-0239":[["形容詞：傳統的、慣常的","traditional / standard","They chose a conventional wedding ceremony rather than a themed celebration.","他們選擇傳統婚禮儀式，而沒有採用主題式慶典。","conventional 的常用意思是傳統或慣常，不是一般的會議相關。"]],"l4-0240":[["動詞：交談","talk / chat","We conversed in French throughout the train journey.","整趟火車旅程中，我們都用法語交談。","converse 較正式；chat 較口語、輕鬆。"]],"l4-0241":[["動詞：傳達","communicate / express","Her short message conveyed both gratitude and concern.","她簡短的訊息同時傳達了感謝與關心。",""]],"l4-0242":[["動詞：使相信","persuade","The photographs convinced us that the roof needed immediate repairs.","那些照片讓我們相信，屋頂需要立即修繕。","convince someone that… 側重使人相信；persuade 也可指勸人採取行動。"]],"l4-0243":[["動詞：合作","collaborate / work together","The two schools cooperated to organize a joint science fair.","兩所學校合作舉辦了一場聯合科展。","cooperate 是不及物動詞，原稿 vt 標記不適用於此常用義項。"]],"l4-0244":[["名詞：合作","collaboration / teamwork","The rescue depended on close cooperation between the two teams.","這次救援有賴兩支隊伍密切合作。",""]],"l4-0245":[["形容詞：願意配合的","helpful / willing","The staff were cooperative when we asked to change the meeting room.","我們要求更換會議室時，工作人員很願意配合。",""]],"l4-0246":[["動詞：應付、妥善處理","manage / deal with","The small clinic struggled to cope with the sudden increase in patients.","病患突然增加，讓這間小診所難以應付。","cope with something；deal with 也需要 with，manage 則通常直接接受詞。"]],"l4-0247":[["名詞：銅","無直接同義詞","The artist used thin sheets of copper to make the sculpture.","藝術家用薄銅片製作這座雕塑。",""]],"l4-0248":[["名詞：細繩","string / rope","She tied the package securely with a length of cord.","她用一段細繩把包裹綁牢。","string 通常較細，rope 通常較粗；cord 的粗細介於多種用途之間。"]],"l4-0249":[["名詞：軟木塞","stopper","He carefully pulled the cork from the old bottle.","他小心地拔出舊瓶子的軟木塞。","stopper 泛指瓶塞；cork 在此特別指軟木製的塞子。"]],"l4-0250":[["動詞：相符","match / agree","The numbers on the receipt do not correspond to the prices on the shelf.","收據上的數字與貨架上的價格不一致。","correspond to/with 可表示相符；correspond with someone 另可表示通信。"]],"l4-0251":[["名詞：戲服","無直接同義詞","The actors changed into their costumes before the final rehearsal.","演員們在最後一次彩排前換上戲服。","outfit 只是成套服裝，不一定是表演用 costume。"]],"l4-0252":[["名詞：鄉間小屋","small house","They rented a cottage near the forest for the summer.","他們租了一間森林附近的小屋過暑假。","small house 為解說性近義表達；cottage 常帶有鄉間住宅的意涵。"]],"l4-0253":[["名詞：地方議會","無直接同義詞","The town council approved a plan to improve the public library.","鎮議會核准了改善公共圖書館的計畫。","council 為議事或管理團體，不等於單次 meeting。"]],"l4-0254":[["名詞：櫃檯","service desk","Please leave the completed form on the counter beside the entrance.","請把填妥的表格放在入口旁的櫃檯上。","service desk 適用於服務櫃檯；counter 也可指廚房工作檯。"]],"l4-0255":[["副詞：與……相反","contrary","Their actions ran counter to the promises they had made.","他們的行動與先前做出的承諾背道而馳。","run counter to 表示違背或相反；原詞條混入分義及詞性標記，實際拼字為 counter。"]],"l4-0256":[["形容詞：勇敢的","brave / bold","It was courageous of her to speak openly about the problem.","她能坦率地談論這個問題，非常勇敢。",""]],"l4-0257":[["形容詞：有禮貌的","polite / respectful","The receptionist was courteous even when several visitors became impatient.","即使幾位訪客開始不耐煩，接待人員仍保持禮貌。",""]],"l4-0258":[["名詞：禮貌","politeness / civility","He treated every customer with courtesy, regardless of how much they spent.","無論顧客消費多少，他都以禮相待。",""]],"l4-0259":[["動詞：裂開","split","The glass cracked when hot water was poured into it.","熱水倒進去時，玻璃杯裂開了。","crack 可只是出現裂痕，不一定完全碎裂。"]],"l4-0260":[["名詞：手藝、工藝","handicraft","She learned the craft of basket weaving from her grandfather.","她向祖父學會了編籃子的手藝。",""]],"l4-0261":[["動詞：硬塞","stuff / pack","We crammed all our camping equipment into the back of the car.","我們把所有露營裝備硬塞進車子後方。",""],["動詞：考前突擊讀書","無直接同義詞","He stayed up late cramming for the history exam.","他熬夜為歷史考試臨時抱佛腳。","cram for an exam 特別指短時間內大量讀書，不等於一般 study。"]],"l4-0262":[["名詞：創作、創造過程","making / production","The exhibition follows the creation of a sculpture from sketch to finished work.","這個展覽呈現一座雕塑從草圖到完成作品的創作過程。",""]],"l4-0263":[["名詞：創造力","inventiveness / imagination","The project gives students room to use their creativity.","這項專題讓學生有空間發揮創造力。",""]],"l4-0264":[["動詞：使癱瘓、嚴重損害","disable / severely damage","The storm crippled the town's transport system for several days.","暴風雨使鎮上的交通系統癱瘓了好幾天。","例句使用現代常見的比喻義。原稿中以 cripple 名詞稱呼身障者的用法過時且可能冒犯。"]],"l4-0265":[["名詞：評論家","reviewer","The film critic praised the acting but found the story unconvincing.","這位影評人稱讚演技，但認為故事缺乏說服力。",""]],"l4-0266":[["形容詞：關鍵的","crucial / vital","Accurate timing is critical to the success of this experiment.","精確掌握時間，是這項實驗成功的關鍵。",""],["形容詞：批評的","disapproving","The report was highly critical of the company's safety procedures.","這份報告強烈批評了公司的安全程序。",""]],"l4-0267":[["名詞：批評","disapproval / censure","The decision drew criticism from residents who wanted to preserve the park.","這項決定引起了希望保留公園的居民批評。","censure 是較強烈、正式的譴責。"]],"l4-0268":[["動詞：批評","find fault with","Several reviewers criticized the book for its lack of reliable sources.","幾位書評人批評這本書缺乏可靠的資料來源。",""]],"l4-0269":[["名詞：殘酷","brutality / inhumanity","The documentary exposed the cruelty of keeping wild animals in tiny cages.","這部紀錄片揭露了把野生動物關在狹小籠子裡的殘酷。",""]],"l4-0270":[["動詞：壓碎","crumble / grind","Crush the biscuits into small pieces before adding the melted butter.","先把餅乾壓成小碎塊，再加入融化的奶油。","grind 往往使顆粒更細；crush 不一定磨成粉末。"],["名詞：迷戀","infatuation","She had a crush on the boy who sat beside her in art class.","她暗戀著美術課上坐在她旁邊的男孩。","have a crush on someone 常指浪漫的迷戀，較口語。"]],"l4-0271":[["名詞：立方體、方塊","無直接同義詞","Drop a few ice cubes into the glass before adding the juice.","倒果汁前，先在杯子裡放幾塊冰塊。","cube 指立方形狀；square 通常指平面的正方形。"]],"l4-0272":[["名詞：小黃瓜","無直接同義詞","Slice the cucumber thinly and add it to the salad.","把小黃瓜切成薄片，加入沙拉。",""]],"l4-0273":[["名詞：提示、信號","signal / prompt","The stage manager gave us the cue to start the music.","舞台監督給了我們開始播放音樂的信號。",""]],"l4-0274":[["形容詞：狡猾的","sly / crafty","The cunning thief distracted the guard with a false alarm.","狡猾的小偷用假警報分散了警衛的注意力。",""]],"l4-0275":[["名詞：好奇心","inquisitiveness","Curiosity led the children to explore the path behind the garden.","好奇心驅使孩子們去探索花園後方的小徑。",""]],"l4-0276":[["名詞：一綹捲髮","ringlet","A dark curl had fallen across her forehead.","一綹深色捲髮垂落在她的額前。","ringlet 常指小而清楚成圈的捲髮。"]],"l4-0277":[["動詞：咒罵","swear","He cursed under his breath when he missed the last train.","錯過末班火車時，他低聲咒罵。",""]],"l4-0278":[["名詞：彎道、曲線","bend / arc","The road makes a sharp curve just beyond the bridge.","道路過橋不遠處有一個急彎。","bend 適合此處道路彎曲的意思；arc 常指較規則的弧線。"]],"l4-0279":[["名詞：靠墊","pillow","She placed a soft cushion behind her back before sitting down to read.","她坐下閱讀前，在背後放了一個柔軟的靠墊。","pillow 在部分語境也指靠枕；cushion 常用於座椅。"]],"l4-0280":[["感嘆詞：該死、可惡","blast","Damn! I left my keys inside the locked car.","可惡！我把鑰匙留在已經鎖上的車裡了。","damn 帶咒罵語氣，正式或需要禮貌的場合宜避免；blast 較常見於英式用法。"]],"l4-0281":[["形容詞：微濕的","moist","The towels were still damp when I took them off the line.","我把毛巾從曬衣繩上收下來時，它們還有點濕。",""]],"l4-0282":[["名詞：截止期限","time limit","The deadline for submitting the application is next Friday.","提交申請的截止日期是下週五。","deadline 指最後時點；time limit 也可指允許花費的時間長度。"]],"l4-0283":[["動詞：宣布","announce / proclaim","The mayor declared the new community center officially open.","市長宣布新的社區中心正式啟用。",""],["動詞：申報","report","Travelers must declare certain goods when they arrive at customs.","旅客抵達海關時，必須申報某些物品。","此例示範用法，具體申報項目需依當地規定。"]],"l4-0284":[["名詞：裝飾品","ornament / embellishment","The children made paper decorations for the classroom windows.","孩子們製作了紙裝飾品，布置教室窗戶。",""]],"l4-0285":[["名詞：減少","reduction / decline","The town reported a decrease in traffic accidents this year.","鎮上公布，今年的交通事故減少了。",""]],"l4-0286":[["動詞：擊敗","beat / overcome","Our team defeated the defending champions in the final match.","我們的隊伍在決賽中擊敗了衛冕冠軍。",""]],"l4-0287":[["動詞：防守、保衛","protect / guard","The soldiers built a wall to defend the village from attack.","士兵築起一道牆，保衛村莊免受攻擊。",""]],"l4-0288":[["名詞：防守","protection","A strong defense prevented the other team from scoring.","堅固的防守讓對方球隊無法得分。","體育語境中的 defense 指防守；protection 只是較廣的近義概念。"]],"l4-0289":[["形容詞：可辯護的","justifiable / reasonable","Given the limited evidence, postponing the decision was a defensible choice.","考量到證據有限，延後決定是個有理由支持的選擇。",""]],"l4-0290":[["形容詞：防禦性的","protective","The castle's defensive walls were built to resist attacks from the valley.","城堡的防禦城牆是為了抵擋來自山谷的攻擊而建。",""]],"l4-0291":[["形容詞：明確的","clear / firm","We need a definite answer before we can reserve the room.","我們需要明確的答覆，才能預訂房間。",""]],"l4-0292":[["形容詞：易損壞的","fragile","Handle the delicate glass ornaments with both hands.","請用雙手拿取這些易碎的玻璃飾品。",""]],"l4-0293":[["名詞：喜悅","joy / pleasure","To our delight, the lost dog was waiting outside the front door.","令我們開心的是，走失的狗就在大門外等著。",""]],"l4-0294":[["形容詞：令人愉快的","lovely / charming","We discovered a delightful little café at the end of the street.","我們在街道盡頭發現了一間令人喜愛的小咖啡館。",""]],"l4-0295":[["動詞：強烈要求","insist on / call for","The passengers demanded an explanation for the three-hour delay.","旅客要求對方解釋為何延誤了三個小時。","demand 語氣比一般 request 強烈；insist on 的結構也不同。"]],"l4-0296":[["動詞：示範","show","The instructor demonstrated how to adjust the bicycle brakes.","教練示範了如何調整腳踏車煞車。",""]],"l4-0297":[["名詞：示範","presentation / display","The chef gave a demonstration of three ways to prepare fresh fish.","主廚示範了三種料理鮮魚的方法。","demonstration 側重展示做法或運作方式，另有示威義項。"]],"l4-0298":[["形容詞：濃密的","thick","Dense fog made it impossible to see the far end of the bridge.","濃霧讓人看不見橋的另一端。",""]],"l4-0299":[["動詞：出發","leave / set off","The ferry departs from the harbor at half past eight.","渡輪八點半從港口出發。",""]],"l4-0300":[["名詞：出發","leaving","Please arrive at the station twenty minutes before departure.","請在發車前二十分鐘抵達車站。","leaving 為動名詞近義表達；departure 常用於交通運輸的正式語境。"]],"l4-0301":[["形容詞：可靠的","reliable / trustworthy","We need a dependable person to look after the shop while we are away.","我們需要一位可靠的人，在我們離開期間照顧店面。",""]],"l4-0302":[["形容詞：依賴的","reliant","The village is heavily dependent on tourism for its income.","這座村莊的收入高度依賴觀光業。","dependent on 與 reliant on 都需要介系詞 on。"]],"l4-0303":[["動詞：使沮喪","sadden / dishearten","The thought of spending the whole weekend alone depressed him.","想到整個週末都要獨自度過，他就感到沮喪。",""]],"l4-0304":[["名詞：沮喪、消沉","dejection / despondency","A sense of depression settled over the team after another defeat.","再次落敗後，一股沮喪的情緒籠罩了全隊。","此例指消沉的心情；醫學上的憂鬱症義項需要分開理解。"]],"l4-0305":[["動詞：值得、應得","merit","The volunteers deserve recognition for their months of hard work.","志工們辛勤工作了好幾個月，值得受到表揚。",""]],"l4-0306":[["形容詞：極度渴望的","eager / anxious","After hours in the heat, we were desperate for a drink of water.","在熱天裡待了好幾個小時後，我們迫切想喝口水。","desperate 語氣比 eager 強，常帶迫切或難以忍受之意。"]],"l4-0307":[["介系詞：儘管","in spite of","Despite the heavy rain, every member of the team arrived on time.","儘管下著大雨，每位隊員仍準時抵達。","despite 後接名詞或動名詞，不直接接完整子句，也不加 of。"]],"l4-0308":[["名詞：摧毀、毀滅","devastation","The flood caused widespread destruction in the riverside villages.","洪水對河畔村莊造成了大規模的破壞。",""]],"l4-0309":[["名詞：偵探","investigator","The detective interviewed everyone who had been in the building that night.","偵探詢問了那晚所有待在大樓裡的人。",""]],"l4-0310":[["名詞：決心","resolve / perseverance","Her determination helped her finish the race despite a painful ankle.","儘管腳踝疼痛，她仍靠著決心跑完了比賽。","perseverance 側重遇到困難仍持續努力；determination 側重決心。"]],"l4-0311":[["名詞：裝置","gadget / apparatus","This small device measures the temperature inside the storage room.","這個小裝置會測量儲藏室內的溫度。","gadget 常指小巧工具；apparatus 較正式，也可指整套器材。"]],"l4-0312":[["動詞：想出、設計","develop / come up with","The students devised a simple way to collect rainwater for the garden.","學生想出了一個簡單的方法，為花園收集雨水。",""]],"l4-0313":[["動詞：投入、奉獻","dedicate","She devotes two evenings a week to helping children with their homework.","她每週投入兩個晚上，幫助孩子們做功課。","devote time to doing something；to 在此為介系詞。"]],"l4-0314":[["名詞：尿布","nappy","He packed extra diapers in the bag before taking the baby out.","帶寶寶出門前，他在包包裡多放了幾片尿布。","diaper 為美式常用詞，nappy 為英式常用詞。"]],"l4-0315":[["動詞：不同","vary","The two recipes differ mainly in the amount of sugar they use.","這兩份食譜主要差在糖的用量。",""]],"l4-0316":[["動詞：消化食物","break down","The stomach helps digest the food we eat.","胃有助於消化我們吃下的食物。","break down 在此指分解；詞條的 1 是分義標記。"],["動詞：理解、吸收資訊","absorb / take in","I needed a few minutes to digest all the information in the presentation.","我需要幾分鐘，才能消化簡報中的所有資訊。",""]],"l4-0317":[["名詞：摘要、文摘","summary / synopsis","The newsletter includes a weekly digest of local news.","這份電子報每週提供地方新聞摘要。","此名詞通常重音在第一音節，與動詞 digest 不同；2 是分義標記。"]],"l4-0318":[["名詞：消化","無直接同義詞","The diagram traces the movement of food during digestion.","這張圖描繪了食物在消化過程中的移動路徑。",""]],"l4-0319":[["形容詞：數位的","無直接同義詞","The library is creating digital copies of its oldest newspapers.","圖書館正在製作館內最老報紙的數位副本。","electronic 範圍較廣，並非所有電子設備或訊號都是 digital。"]],"l4-0320":[["名詞：尊嚴","respect","The staff treated every resident with dignity and patience.","工作人員尊重每位住民的尊嚴，並耐心相待。","treat someone with dignity 與 treat someone with respect 在此語境意思相近。"]],"l4-0321":[["名詞：勤勉","industriousness / dedication","Her diligence in checking the records prevented several costly mistakes.","她勤勉地核對紀錄，避免了好幾個代價高昂的錯誤。",""]],"l4-0322":[["名詞：畢業證書","certificate","He proudly showed his parents the diploma he had just received.","他驕傲地把剛領到的畢業證書拿給父母看。","certificate 範圍較廣；diploma 常證明完成某項學業。"]],"l4-0323":[["名詞：外交官","無直接同義詞","The diplomat met with local officials to discuss cultural exchanges.","這位外交官與當地官員會面，討論文化交流事宜。","ambassador 是大使，屬特定職位，不能替代所有 diplomat。"]],"l4-0324":[["名詞：缺點、不利條件","drawback / downside","One disadvantage of living here is the limited public transport.","住在這裡的缺點之一，是大眾運輸選擇有限。",""]],"l4-0325":[["名詞：災難","catastrophe / calamity","The earthquake was the worst disaster the town had experienced in decades.","這次地震是鎮上數十年來遭遇的最嚴重災難。",""]],"l4-0326":[["名詞：自律、紀律","self-control","Learning to play the violin requires discipline as well as enthusiasm.","學小提琴除了需要熱情，也需要自律。",""]],"l4-0327":[["動詞：中斷連接","detach / separate","Disconnect the printer from the computer before replacing the cable.","更換連接線前，請先中斷印表機與電腦的連接。",""]],"l4-0328":[["動詞：使氣餒","dishearten / demoralize","A few mistakes should not discourage you from learning a new language.","幾個錯誤不應讓你對學習新語言感到氣餒。",""]],"l4-0329":[["名詞：氣餒","disheartenment / despondency","Despite her initial discouragement, she continued practicing every day.","儘管起初感到氣餒，她仍然每天練習。",""]],"l4-0330":[["動詞：偽裝","mask","He disguised his voice so that his sister would not recognize him.","他偽裝聲音，讓妹妹認不出他。","disguise 在此表示改變聲音以隱藏身分。"]],"l4-0331":[["名詞：厭惡","revulsion / loathing","She turned away in disgust when she saw the spoiled food.","看到腐敗的食物時，她厭惡地轉過頭去。",""]],"l4-0332":[["動詞：不予理會","reject / disregard","The committee dismissed the proposal without discussing its possible benefits.","委員會沒有討論提案可能帶來的好處，就把它否決了。",""]],"l4-0333":[["名詞：混亂","chaos / disarray","The office was in complete disorder after the hurried move.","匆忙搬遷後，辦公室裡一片混亂。",""]],"l4-0334":[["名詞：爭端","disagreement / argument","The neighbors settled their dispute over the shared driveway.","鄰居們解決了共用車道所引起的爭端。",""]],"l4-0335":[["形容詞：有明顯區別的","different / separate","The museum divides the exhibition into three distinct sections.","博物館把展覽分成三個截然不同的部分。",""]],"l4-0336":[["動詞：區分","differentiate / tell apart","The guide showed us how to distinguish the two similar bird species.","導遊教我們如何區分這兩種相似的鳥。",""]],"l4-0337":[["形容詞：傑出而受敬重的","eminent / renowned","A distinguished historian will give the opening lecture at the conference.","一位傑出的歷史學家將在研討會上發表開幕演講。",""]],"l4-0338":[["動詞：分發","hand out / give out","Volunteers distributed blankets to families waiting outside the shelter.","志工把毛毯分發給在收容所外等候的家庭。",""]],"l4-0339":[["名詞：分發","handing out","The distribution of emergency food began early in the morning.","緊急糧食的分發一大早就開始了。","handing out 是動名詞片語，較口語。"]],"l4-0340":[["名詞：地區","area / region","The new hotel is located in the city's historic district.","新飯店位於這座城市的歷史街區。",""]],"l4-0341":[["動詞：打擾","interrupt / bother","Please do not disturb the students while they are taking the exam.","學生考試時，請不要打擾他們。",""]],"l4-0342":[["形容詞：神的","heavenly","The painting shows a king asking for divine guidance.","這幅畫描繪了一位國王祈求神明指引的情景。","heavenly 在此取來自天國或神的意思。"]],"l4-0343":[["名詞：離婚","dissolution of marriage","After the divorce, they continued to attend their children's school events together.","離婚後，他們仍繼續一起參加孩子的學校活動。","dissolution of marriage 為正式表達。"]],"l4-0344":[["形容詞：居主導地位的","leading / predominant","Tourism has become the dominant industry on the island.","觀光業已成為島上最主要的產業。",""]],"l4-0345":[["動詞：主導、控制","control / command","A few large companies dominate the local newspaper market.","少數幾家大公司主導著當地的報業市場。",""]],"l4-0346":[["名詞：學生宿舍","dorm / residence hall","She shares a room in the university dormitory with another first-year student.","她與另一位大一學生同住在大學宿舍的一間房裡。",""]],"l4-0347":[["動詞：下載","無直接同義詞","You can download the application form from the museum's website.","你可以從博物館網站下載申請表。","save 是儲存，不一定包含從遠端取得資料的下載過程。"]],"l4-0348":[["動詞：打盹","nap / snooze","My grandfather dozed in his chair while the radio played softly.","收音機輕聲播放時，祖父坐在椅子上打盹。",""]],"l4-0349":[["名詞：草稿","rough version","She sent the first draft of her report to her supervisor for comments.","她把報告初稿寄給主管，請對方提供意見。",""]],"l4-0350":[["動詞：害怕、擔憂即將發生的事","fear","I dread telling him that his favorite café is closing.","我很害怕告訴他，他最喜歡的咖啡館要關門了。","dread 常含強烈擔憂將來事情之意，常接動名詞。"]],"l4-0351":[["動詞：漂流","float","A small wooden boat drifted slowly toward the shore.","一艘小木船緩緩漂向岸邊。","drift 強調隨水流或風移動；float 只需浮在表面，不一定移動。"]],"l4-0352":[["動詞：鑽孔","bore","He drilled two holes in the wall to hang the shelf.","他在牆上鑽了兩個洞，用來掛層架。",""],["名詞：演練","exercise / practice","Everyone left the building calmly during the fire drill.","消防演練時，大家都冷靜地離開了大樓。",""]],"l4-0353":[["形容詞：耐用的","hard-wearing / long-lasting","Choose a durable fabric for a sofa that children will use every day.","每天都會讓孩子使用的沙發，應選擇耐用的布料。",""]],"l4-0354":[["形容詞：滿是灰塵的","dust-covered","We found a dusty suitcase behind the old wardrobe.","我們在舊衣櫃後面找到一只滿是灰塵的行李箱。",""]],"l4-0355":[["名詞：DVD 光碟","無直接同義詞","The film is available on DVD with subtitles in several languages.","這部電影有 DVD 版本，附有多種語言字幕。","DVD 為特定光碟格式；CD、Blu-ray 不能當作同義詞。"]],"l4-0356":[["動詞：染色","color / tint","She dyed the white fabric blue for her art project.","她為了美術專題，把白布染成藍色。","dye 指用染料使材料改變顏色；color 的方法與範圍較廣。"]],"l4-0357":[["形容詞：有活力的","energetic / lively","The dynamic new director brought fresh ideas to the theater.","這位充滿活力的新導演為劇院帶來了新點子。",""]],"l4-0358":[["名詞：王朝","ruling family","The palace was built during the final years of the dynasty.","這座宮殿建於該王朝的最後幾年。","ruling family 是解說性近義表達；dynasty 常指同一家族連續統治的時期。"]],"l4-0359":[["形容詞：認真而誠懇的","sincere / serious","His earnest apology persuaded her to give him another chance.","他誠懇的道歉說服了她，讓她願意再給他一次機會。",""]],"l4-0360":[["名詞：耳機","earpiece","One earphone stopped working during the long train ride.","漫長的火車旅途中，一邊的耳機壞了。","earphones 常用複數指一對；earpiece 可指單邊聽筒或耳機部分。"]],"l4-0361":[["形容詞：經濟方面的","無直接同義詞","The report examines the economic effects of closing the factory.","這份報告檢視關閉工廠對經濟造成的影響。","financial 偏重金錢或財務；economic 涵蓋更廣的經濟活動。"]],"l4-0362":[["形容詞：節省資源的","cost-effective","Sharing a car can be an economical way to travel to work.","共乘汽車可以是節省通勤費用的方式。","economical 強調節省；economic 則通常表示與經濟相關。"]],"l4-0363":[["名詞：經濟學","無直接同義詞","She chose to study economics because she wanted to understand how markets work.","她選擇學習經濟學，因為她想了解市場如何運作。","economics 作學科名稱時通常視為單數。"]],"l4-0364":[["名詞：經濟學家","無直接同義詞","The economist explained the survey results in terms the audience could understand.","這位經濟學家用聽眾能理解的方式說明調查結果。",""]],"l4-0365":[["名詞：經濟、經濟體系","economic system","Small family businesses play an important role in the local economy.","小型家族企業在當地經濟中扮演重要角色。","economic system 是此義項的解說性表達。"]],"l4-0366":[["名詞：效率","無直接同義詞","The new system improved efficiency by reducing the time spent entering data.","新系統縮短了輸入資料所需的時間，提升了效率。","effectiveness 偏重是否有效達成目標；efficiency 偏重時間與資源使用。"]],"l4-0367":[["形容詞：有彈性的","stretchy","The trousers have an elastic waistband for a more comfortable fit.","這條褲子的褲頭有彈性，穿起來更舒適合身。",""]],"l4-0368":[["名詞：電工","無直接同義詞","An electrician came to replace the damaged wiring in the kitchen.","一位電工來更換廚房損壞的電線。",""]],"l4-0369":[["名詞：電子學","無直接同義詞","He developed an interest in electronics while repairing old radios.","他在修理舊收音機的過程中，對電子學產生了興趣。","electronics 作學科名稱時通常視為單數。"]],"l4-0370":[["形容詞：優雅的","graceful / stylish","She wore an elegant dark blue dress to the concert.","她穿了一件優雅的深藍色洋裝去聽音樂會。",""]],"l4-0371":[["形容詞：基礎的","basic / introductory","The course introduces elementary principles of drawing and perspective.","這門課介紹素描與透視法的基本原理。",""]],"l4-0372":[["動詞：排除、消除","remove / get rid of","The new filter eliminates most of the dust from the air.","新濾網能去除空氣中的大部分灰塵。",""]],"l4-0373":[["副詞：在別處","somewhere else","If the library is closed, we will have to study elsewhere.","如果圖書館關門了，我們就得到別的地方讀書。",""]],"l4-0374":[["名詞：電子郵件","electronic mail","I received an email confirming the date of my interview.","我收到一封電子郵件，確認了面試日期。","email 與 e-mail 為拼寫變體。"]],"l4-0375":[["動詞：使尷尬","make uncomfortable","His loud comments about the food embarrassed everyone at the table.","他大聲評論食物，讓同桌的人都很尷尬。","make uncomfortable 是解說性近義表達。"]],"l4-0376":[["名詞：尷尬","awkwardness / self-consciousness","She laughed to hide her embarrassment after forgetting the words of the song.","忘記歌詞後，她用笑聲掩飾自己的尷尬。",""]],"l4-0377":[["名詞：大使館","無直接同義詞","The students visited the embassy to learn about the cultural exchange program.","學生參訪大使館，了解文化交流計畫。","consulate 是領事館，與 embassy 的職能和層級不同。"]],"l4-0378":[["動詞：出現","appear / come out","A deer emerged from the trees and stopped beside the stream.","一隻鹿從林間走出來，停在溪邊。",""]],"l4-0379":[["形容詞：情緒激動的","moved / tearful","She became emotional when she saw her brother after ten years apart.","與哥哥分隔十年後再次相見，她激動了起來。","emotional 不一定流淚；tearful 進一步表示含淚或想哭。"]],"l4-0380":[["名詞：重視、強調","stress / focus","The training program places great emphasis on practical experience.","這個訓練計畫非常重視實務經驗。",""]],"l4-0381":[["名詞：帝國","無直接同義詞","The map shows how the empire expanded over three centuries.","這張地圖呈現了該帝國在三個世紀中的擴張情形。","kingdom 是王國，與 empire 並非同一概念。"]],"l4-0382":[["動詞：圍住","surround / fence in","A low stone wall encloses the garden behind the house.","一道矮石牆圍住了屋後的花園。",""]],"l4-0383":[["動詞：遇到","meet / come across","We encountered several difficulties while restoring the old photographs.","修復老照片的過程中，我們遇到了幾個困難。",""]],"l4-0384":[["動詞：危及","jeopardize / put at risk","Leaving the gate open could endanger the animals near the road.","把大門敞開，可能會讓靠近道路的動物陷入危險。",""]],"l4-0385":[["動詞：忍受","tolerate / bear","The passengers had to endure a long wait in the crowded terminal.","旅客不得不在擁擠的航廈裡忍受漫長的等待。",""]],"l4-0386":[["動詞：執行、強制遵守","implement","The school began to enforce its parking rules more strictly.","學校開始更嚴格地執行停車規定。","enforce 強調確保他人遵守；implement 側重付諸實行。"]],"l4-0387":[["名詞：執行、強制實施","implementation","Effective enforcement of the rules requires clear signs and regular inspections.","要有效執行規定，需要清楚的標示和定期檢查。","enforcement 側重確保遵守規定，與一般 implementation 不完全相同。"]],"l4-0388":[["名詞：工程學","無直接同義詞","She studied engineering before joining a team that designs bridges.","她先修讀工程學，之後加入了設計橋梁的團隊。",""]],"l4-0389":[["動詞：放大","magnify / expand","Could you enlarge the photograph so that we can see the details?","你能把照片放大，讓我們看清楚細節嗎？",""]],"l4-0390":[["名詞：放大的照片","blow-up","An enlargement of the original photograph hangs in the entrance hall.","入口大廳掛著原照片的放大版本。","blow-up 作名詞可指放大的照片，較口語。"]],"l4-0391":[["形容詞：巨大的","huge / immense","An enormous tree stood in the center of the courtyard.","庭院中央矗立著一棵巨大的樹。",""]],"l4-0392":[["動詞：娛樂、逗樂","amuse","The storyteller entertained the children with tales about talking animals.","說故事的人用會說話的動物故事逗樂了孩子們。",""]],"l4-0393":[["名詞：娛樂活動","amusement / recreation","The festival offers free entertainment for visitors of all ages.","這個節慶為各年齡層的訪客提供免費娛樂活動。",""]],"l4-0394":[["名詞：熱情","eagerness / zeal","Her enthusiasm for gardening soon spread to the rest of the family.","她對園藝的熱情很快感染了家中其他人。",""]],"l4-0395":[["形容詞：羨慕的","jealous","I felt envious of my friend's chance to spend a year abroad.","我羨慕朋友有機會到國外待一年。","jealous 在口語中常有羨慕義，另可指擔心失去感情或地位的嫉妒。"]],"l4-0396":[["名詞：平等","equal treatment","The organization campaigns for equality in education and employment.","這個組織致力於爭取教育與就業方面的平等。","equal treatment 是此社會義項的解說性近義表達。"]],"l4-0397":[["動詞：配備","outfit / furnish","The school equipped each classroom with a projector and a whiteboard.","學校為每間教室配備了投影機和白板。",""]],"l4-0398":[["名詞：設備、器材","gear / apparatus","Check that all your camping equipment is dry before storing it.","收起露營裝備前，請確認所有器材都已乾燥。","equipment 為不可數名詞，不加複數 s；gear 較口語。"]],"l4-0399":[["名詞：時代","age / period","The railway station was built during an era of rapid industrial growth.","這座火車站建於工業快速成長的時代。",""]],"l4-0400":[["名詞：外出辦的小差事","無直接同義詞","I need to run an errand at the post office before lunch.","午餐前，我得去郵局辦一件事。","errand 通常涉及短程外出辦事，並非所有 task 都是 errand。"]],"l4-0401":[["名詞：電扶梯","moving staircase","Take the escalator to the second floor and turn left.","搭電扶梯到二樓後左轉。","moving staircase 是解說性近義表達；elevator 是電梯，不能互換。"]],"l4-0402":[["名詞：論說文、短文","composition / paper","Her essay examines the advantages and disadvantages of working from home.","她的文章探討了居家工作的優缺點。",""]],"l4-0403":[["形容詞：必要的","necessary / indispensable","A reliable water supply is essential for the new laboratory.","穩定的供水對新實驗室而言不可或缺。",""]],"l4-0404":[["動詞：創立、建立","found / set up","The two sisters established a small publishing company in their hometown.","這對姊妹在家鄉創立了一家小型出版社。",""]],"l4-0405":[["名詞：創立、設立","founding / creation","The establishment of the new library took several years of planning.","新圖書館的設立經過了好幾年的規劃。",""]],"l4-0406":[["動詞：估計","reckon","We estimate that the repairs will take about three weeks.","我們估計修繕大約需要三個星期。","reckon 較口語。"]],"l4-0407":[["動詞：評估","assess / appraise","The teachers will evaluate each project based on clarity and originality.","老師將根據清楚程度與原創性評估每份專題。",""]],"l4-0408":[["名詞：評估","assessment / appraisal","The evaluation helped the team identify weaknesses in its training program.","這次評估幫助團隊找出訓練計畫中的弱點。",""]],"l4-0409":[["名詞：前夕","day before","We spent Christmas Eve baking cookies and wrapping presents.","我們在平安夜烤餅乾、包禮物。","eve 常指節日前一天或前夜；Christmas Eve 是固定名稱。"]],"l4-0410":[["形容詞：最終的","ultimate / final","The eventual winner was the youngest player in the tournament.","最後獲勝的是錦標賽中最年輕的選手。",""]],"l4-0411":[["名詞：證據","proof","The damaged lock provided evidence that someone had entered the room.","損壞的門鎖提供了有人進入房間的證據。","evidence 可支持推論，但不一定像 proof 一樣足以確證。"]],"l4-0412":[["形容詞：明顯的","obvious / apparent","Her disappointment was evident from the expression on her face.","從她臉上的表情，可以明顯看出她的失望。",""]],"l4-0413":[["動詞：誇大","overstate / magnify","The advertisement exaggerates how quickly the product can clean a room.","這則廣告誇大了這項產品打掃房間的速度。",""]],"l4-0414":[["名詞：應試者","test taker / candidate","Each examinee was given a number before entering the examination room.","每位考生在進入考場前都拿到了一個號碼。",""]],"l4-0415":[["名詞：考官","assessor","The examiner asked me to describe the picture in my own words.","考官要我用自己的話描述這張圖片。","assessor 指評核者，範圍較廣。"]],"l4-0416":[["名詞：例外","special case","Everyone must wear a helmet, and visitors are no exception.","每個人都必須戴安全帽，訪客也不例外。","special case 是近義表達，通常不能直接替換固定片語 no exception。"]],"l4-0417":[["動詞：耗盡","use up / deplete","We exhausted our supply of clean towels before the last guests arrived.","最後一批客人抵達前，乾淨的毛巾就已經用完了。",""],["名詞：廢氣","fumes","Dark exhaust poured from the old bus as it climbed the hill.","老公車爬坡時，不斷排出黑色廢氣。","fumes 指氣體或煙霧，exhaust 特別指引擎排出的氣體。"]],"l4-0418":[["動詞：展出","display / show","The museum will exhibit photographs taken during the town's early years.","博物館將展出城鎮早期拍攝的照片。",""]],"l4-0419":[["動詞：擴張","grow / enlarge","The company plans to expand its delivery service to nearby villages.","公司計畫把配送服務擴展到附近村莊。",""]],"l4-0420":[["名詞：擴張、擴建","growth / enlargement","The expansion of the station will provide space for two more platforms.","車站擴建後，將有空間增設兩座月台。",""]],"l4-0421":[["名詞：解釋","account / clarification","The manager offered a clear explanation of the changes to our schedule.","經理清楚說明了我們的班表有哪些調整。",""]],"l4-0422":[["動詞：探索","investigate / examine","The students explored several possible causes of the river's pollution.","學生探討了河流汙染的幾種可能原因。",""]],"l4-0423":[["名詞：爆炸","blast","The explosion shattered windows in buildings across the street.","爆炸震碎了街道對面建築物的窗戶。",""]],"l4-0424":[["形容詞：易爆炸的","無直接同義詞","The workers received special training before handling explosive materials.","工人在處理爆炸性物料前，接受了專門訓練。","flammable 指易燃，並不表示一定具有爆炸性。"]],"l4-0425":[["動詞：使暴露於","subject","The damaged roof exposed the furniture to rain and wind.","損壞的屋頂讓家具暴露在風雨之中。","expose something to something；subject something to something 的語氣較正式。"]],"l4-0426":[["名詞：暴露、曝曬","無直接同義詞","Years of exposure to sunlight had faded the curtains.","經年累月的日曬讓窗簾褪色了。","exposure to 指受到某因素的影響或接觸，不能直接以 contact 替換所有用法。"]],"l4-0427":[["動詞：延長","lengthen / prolong","The library will extend its opening hours during the exam period.","考試期間，圖書館將延長開放時間。",""]],"l4-0428":[["名詞：程度、範圍","degree / scope","We could not judge the extent of the damage until the water receded.","水退去之前，我們無法判斷受損的程度。",""]],"l4-0429":[["形容詞：臉部的","無直接同義詞","Her facial expression changed as she read the letter.","讀信時，她的臉部表情起了變化。",""]],"l4-0430":[["名詞：設施","amenity","The hotel has excellent sports facilities, including an indoor tennis court.","這家飯店有完善的運動設施，包括一座室內網球場。","amenity 側重提供舒適或便利的設施；facility 使用範圍較廣。"]],"l4-0431":[["形容詞：忠誠的","loyal / devoted","She remained a faithful supporter of the team through years of poor results.","儘管球隊多年戰績不佳，她始終是忠實的支持者。",""]],"l4-0432":[["名詞：名聲、知名度","renown / celebrity","The young musician gained international fame after her first major concert.","這位年輕音樂家在第一場大型音樂會後享譽國際。","celebrity 在此指知名狀態，也可另指名人。"]],"l4-0433":[["形容詞：極好的","excellent / wonderful","We had a fantastic view of the harbor from our room.","從我們的房間可以看到絕佳的港口景色。",""]],"l4-0434":[["名詞：幻想","daydream / imagining","His fantasy of living on a tropical island inspired his first novel.","他對住在熱帶島嶼的幻想，成了第一部小說的靈感。",""]],"l4-0435":[["名詞：告別","goodbye / parting","The family gathered at the station to say farewell to their grandmother.","一家人聚在車站，向祖母道別。","farewell 較正式，也常用於較長時間的離別。"]],"l4-0436":[["形容詞：致命的","deadly / lethal","The report describes a fatal accident at a road junction.","這份報告描述了路口發生的一起致命事故。",""]],"l4-0437":[["形容詞：有利的","advantageous / beneficial","Favorable weather conditions allowed the farmers to finish the harvest early.","有利的天氣條件讓農民提早完成收成。",""]],"l4-0438":[["名詞：盛宴","banquet","The hosts prepared a feast to celebrate the guests' arrival.","主人準備了一桌盛宴，慶祝客人到來。",""]],"l4-0439":[["名詞：渡輪","ferryboat","We took a ferry across the bay instead of driving around it.","我們搭渡輪穿越海灣，省去了開車繞行的路程。",""]],"l4-0440":[["形容詞：肥沃的","productive / rich","The valley's fertile soil is ideal for growing vegetables.","山谷裡肥沃的土壤非常適合種蔬菜。",""]],"l4-0441":[["動詞：去拿來","go and get","Could you fetch a clean towel from the cupboard?","你可以去櫥櫃裡拿一條乾淨的毛巾過來嗎？","fetch 包含前往取得再帶回的意思；bring 不一定包含前往取得。"]],"l4-0442":[["名詞：小說作品","無直接同義詞","The bookstore keeps fiction on the ground floor and travel books upstairs.","這家書店把小說放在一樓，旅遊書放在樓上。","fiction 為虛構文學總稱，不只單一本 novel。"]],"l4-0443":[["形容詞：猛烈的","intense / violent","Fierce winds forced the fishing boats to return to the harbor.","猛烈的強風迫使漁船返回港口。",""]],"l4-0444":[["名詞：金融、財務領域","無直接同義詞","After graduation, he found a job in finance at a shipping company.","畢業後，他在一家航運公司找到財務方面的工作。","accounting 是會計，範圍與 finance 不完全相同。"]],"l4-0445":[["形容詞：財務方面的","monetary","The club is facing financial difficulties after losing its main sponsor.","失去主要贊助者後，這個俱樂部面臨財務困難。","monetary 強調與金錢有關；financial 也涵蓋整體財務管理。"]],"l4-0446":[["名詞：鞭炮","banger","The loud sound of a firecracker startled the sleeping dog.","鞭炮的巨響嚇醒了熟睡的狗。","banger 在英式口語中可指鞭炮，另有其他意思。"]],"l4-0447":[["名詞：壁爐","hearth","We sat near the fireplace and listened to the rain outside.","我們坐在壁爐旁，聽著外面的雨聲。","hearth 常指壁爐底部或爐邊，與整座 fireplace 有範圍差異。"]],"l4-0448":[["動詞：奉承","butter up","He tried to flatter the manager before asking for a day off.","他請假前先試著奉承經理。","butter someone up 為口語片語，常含為達目的而奉承之意。"]],"l4-0449":[["動詞：逃離","escape / run away","The family fled their home when smoke began filling the hallway.","煙開始瀰漫走廊時，這家人逃離了住處。","flee 的過去式與過去分詞都是 fled。"]],"l4-0450":[["形容詞：可變通的","adaptable","My employer offers flexible working hours for parents with young children.","我的雇主為有年幼孩子的家長提供彈性工時。",""]],"l4-0451":[["形容詞：語言流利的","無直接同義詞","After living in Spain for five years, she speaks fluent Spanish.","在西班牙住了五年後，她說得一口流利的西班牙語。","proficient 指熟練，並不專指說話流暢。"]],"l4-0452":[["動詞：考試不及格","fail","He flunked his driving test but passed it on the second attempt.","他第一次駕照考試沒通過，但第二次考過了。","flunk 較口語，常見於美式英語。"]],"l4-0453":[["動詞：沖洗","rinse","Flush the pipe with clean water before reconnecting it.","重新接回水管前，先用清水把它沖洗乾淨。","flush 通常強調以水流沖過；rinse 可指較一般的沖洗。"]],"l4-0454":[["名詞：泡沫","froth","A layer of white foam formed on the surface of the water.","水面上形成了一層白色泡沫。",""]],"l4-0455":[["動詞：禁止","prohibit / ban","The museum forbids visitors to touch the fragile exhibits.","博物館禁止訪客觸碰易損壞的展品。","forbid someone to do something；也可用 forbid doing something。"]],"l4-0456":[["名詞：預報","prediction","The forecast suggests that the rain will continue through the weekend.","天氣預報顯示，降雨將持續到週末。",""]],"l4-0457":[["名詞：隊形","arrangement","The dancers moved into a circular formation around the singer.","舞者在歌手周圍排成了圓形隊形。",""]],"l4-0458":[["名詞：數學公式","無直接同義詞","Use this formula to calculate the area of a circle.","用這個公式計算圓的面積。","equation 是等式，formula 是表達數量關係的公式，概念不完全相同。"]],"l4-0459":[["名詞：堡壘","fortress / stronghold","The old fort overlooks the narrow entrance to the harbor.","古老的堡壘俯瞰著港口狹窄的入口。",""]],"l4-0460":[["形容詞：幸運的","lucky","We were fortunate to find a room during the busy holiday weekend.","在繁忙的連假週末能找到房間，我們很幸運。",""]],"l4-0461":[["名詞：化石","無直接同義詞","The children found a fossil in a piece of rock near the beach.","孩子們在海灘附近的一塊岩石裡發現了化石。",""]],"l4-0462":[["名詞：建築物地基","base / footing","Engineers inspected the foundation before work began on the upper floors.","建造上層樓層之前，工程師先檢查了地基。","footing 可特指支撐基礎荷重的底部結構，範圍較窄。"],["名詞：基金會","無直接同義詞","The foundation offers scholarships to students from low-income families.","這個基金會提供獎學金給低收入家庭的學生。",""]],"l4-0463":[["名詞：創辦人","無直接同義詞","The founder of the school returned for its fiftieth anniversary.","學校創辦人在五十週年校慶時回到了學校。","cofounder 只適用於與他人共同創辦的情況，不能取代所有 founder。"]],"l4-0464":[["名詞：香氣","scent / perfume","The fragrance of orange blossoms filled the courtyard.","橙花的香氣瀰漫整個庭院。",""]],"l4-0465":[["形容詞：芳香的","aromatic / sweet-smelling","She added a few fragrant herbs to the soup.","她在湯裡加了幾種芳香的香草。",""]],"l4-0466":[["名詞：框架","framework / structure","The bicycle has a lightweight aluminum frame.","這輛腳踏車有輕巧的鋁製車架。",""]],"l4-0467":[["名詞：高速公路","motorway / expressway","We left the freeway at the next exit to avoid the traffic jam.","為了避開塞車，我們從下一個交流道離開高速公路。","motorway 為英式常用詞；expressway 的道路規格可能因地區而異。"]],"l4-0468":[["名詞：發生頻率","rate","The survey measures the frequency of visits to public libraries.","這份調查測量民眾造訪公共圖書館的頻率。","frequency 重點是某事發生多常；rate 也可指速度或比率。"]],"l4-0469":[["名詞：一年級新生","first-year student","As a freshman, he joined the university's photography club.","大一時，他加入了大學攝影社。",""]],"l4-0470":[["名詞：霜","hoarfrost","A thin layer of frost covered the grass before sunrise.","日出前，草地上覆蓋著一層薄霜。","hoarfrost 常指可見白色冰晶的霜，較正式。"]],"l4-0471":[["動詞：皺眉","scowl","She frowned when she noticed an unexpected charge on the bill.","看到帳單上多出一筆沒預料到的費用時，她皺起了眉頭。","scowl 通常帶有較明顯的怒氣；frown 也可表示困惑或擔心。"]],"l4-0472":[["名詞：挫折感","exasperation","He sighed in frustration when the computer froze for the third time.","電腦第三次當機時，他挫折地嘆了口氣。","exasperation 常比 frustration 更帶惱怒。"]],"l4-0473":[["名詞：燃料","無直接同義詞","The boat was running low on fuel, so we returned to the harbor.","船上的燃料快用完了，所以我們返回港口。","petrol、diesel 等是不同種類的燃料，energy 是能量，均不能直接概括取代 fuel。"]],"l4-0474":[["動詞：履行承諾","keep / honor","The company fulfilled its promise to replace the damaged tables.","公司履行承諾，更換了損壞的桌子。",""]],"l4-0475":[["名詞：實現、完成","realization / accomplishment","Opening the bookstore was the fulfillment of a lifelong dream.","開設這家書店，是畢生夢想的實現。",""]],"l4-0476":[["形容詞：功能方面的","無直接同義詞","The study examines functional differences between the two parts of the machine.","這項研究檢視機器兩個部分在功能上的差異。","functional 在此表示與功能有關，另可指實用或能正常運作。"]],"l4-0477":[["形容詞：根本的","basic / essential","Trust is a fundamental part of a successful partnership.","信任是成功合作關係中的根本要素。",""]],"l4-0478":[["名詞：葬禮","funeral service","Friends traveled from across the country to attend his funeral.","朋友們從全國各地趕來參加他的葬禮。","funeral service 常指葬禮儀式本身。"]],"l4-0479":[["形容詞：盛怒的","angry / enraged","She was furious when she discovered that someone had damaged her bicycle.","發現有人弄壞她的腳踏車時，她氣壞了。","furious 比一般 angry 表示更強烈的憤怒。"]],"l4-0480":[["動詞：為房間配置家具","fit out / equip","They furnished the small apartment with secondhand tables and chairs.","他們用二手桌椅布置了這間小公寓。","furnish 特別指配置家具；equip 範圍較廣。"]],"l4-0481":[["副詞：此外、而且","moreover / in addition","The room is spacious; furthermore, it has a balcony overlooking the garden.","這個房間很寬敞，而且有一座俯瞰花園的陽台。",""]],"l4-0482":[["名詞：美術館、畫廊","art museum","The gallery is showing paintings by several local artists.","這間美術館正在展出幾位當地藝術家的畫作。","gallery 也可指商業畫廊，未必都是 museum。"]],"l4-0483":[["名詞：幫派分子","mobster","In the film, a former gangster tries to begin a peaceful life.","電影中，一名前幫派分子試著展開平靜的生活。",""]],"l4-0484":[["動詞：凝視","stare / look steadily","We gazed at the stars from the roof of the farmhouse.","我們從農舍屋頂凝望星空。","gaze 常帶專注、欣賞或沉思意味；stare 可能顯得無禮。"]],"l4-0485":[["名詞：裝備","equipment / kit","Keep your climbing gear in a dry place after each trip.","每趟行程結束後，都要把攀岩裝備放在乾燥的地方。",""]],"l4-0486":[["名詞：基因","無直接同義詞","The researchers are studying a gene involved in the plant's growth.","研究人員正在研究一個與這種植物生長有關的基因。","gene 與 DNA 或 chromosome（染色體）並非同一層級的概念。"]],"l4-0487":[["名詞：世代","無直接同義詞","Three generations of the family gathered for the holiday meal.","這家人祖孫三代齊聚一堂，享用節日大餐。","家庭語境中的 generation 指輩分，不能僅以年齡分組代替。"]],"l4-0488":[["名詞：慷慨","generousness / liberality","Thanks to the generosity of local residents, the shelter stayed open all winter.","多虧當地居民慷慨相助，收容所在整個冬季都能持續開放。",""]],"l4-0489":[["名詞：天才人物","exceptionally talented person","His teacher recognized him as a musical genius at an early age.","他年紀還很小時，老師就看出他是音樂天才。","所列為解說性近義表達。"]],"l4-0490":[["形容詞：真品的","authentic / real","The expert confirmed that the painting was genuine.","專家確認這幅畫是真跡。",""]],"l4-0491":[["名詞：病菌","microbe","The children made a poster explaining how germs spread.","孩子們製作了一張海報，說明病菌如何傳播。","germ 日常常指致病微生物；microbe 範圍較廣，並非都會致病。"]],"l4-0492":[["形容詞：有天賦的","talented","The gifted young pianist learned the difficult piece in just a week.","這位有天賦的年輕鋼琴家只花一週就學會了這首難曲。",""]],"l4-0493":[["形容詞：巨大的","enormous / immense","A gigantic crane lifted the steel beams into place.","一台巨大的起重機把鋼梁吊到定位。",""]],"l4-0494":[["動詞：咯咯笑","chuckle","The children giggled when the puppy tripped over its own feet.","小狗被自己的腳絆倒時，孩子們咯咯笑了起來。","giggle 常是輕而反覆的笑聲；chuckle 通常較低沉。"]],"l4-0495":[["名詞：薑","無直接同義詞","Add a small piece of fresh ginger to the soup.","在湯裡加一小塊新鮮的薑。",""]],"l4-0496":[["動詞：平穩滑行","slide / sail","The swan glided across the lake without making a sound.","天鵝悄然無聲地滑過湖面。","glide 強調平穩、流暢的移動。"]],"l4-0497":[["名詞：短暫的一瞥","brief look","We caught a glimpse of the mountains as the clouds began to clear.","雲開始散去時，我們短暫看到了群山。",""]],"l4-0498":[["名詞：地球儀","無直接同義詞","The teacher used a globe to show how far the two countries are apart.","老師用地球儀展示兩個國家之間的距離有多遠。",""]],"l4-0499":[["形容詞：光榮、輝煌的","splendid / magnificent","The team celebrated its glorious victory with a parade through town.","球隊在鎮上遊行，慶祝這場光榮的勝利。",""]],"l4-0500":[["複數名詞：商品","merchandise / products","The shop sells handmade goods produced by local artists.","這家店販售當地藝術家製作的手工商品。","goods 在此為複數名詞；merchandise 為不可數名詞。"]],"l4-0501":[["名詞：優雅","elegance / poise","The dancer moved across the stage with remarkable grace.","舞者以格外優雅的姿態穿越舞台。",""]],"l4-0502":[["形容詞：優雅的","elegant / fluid","Her graceful movements made the difficult dance look effortless.","她優美的動作，讓這支高難度舞蹈看起來毫不費力。","fluid 在動作語境中強調流暢。"]],"l4-0503":[["形容詞：親切有禮的","courteous / kind","Our hosts were gracious even though we arrived much later than expected.","儘管我們比預期晚到許多，主人仍親切有禮地接待我們。",""]],"l4-0504":[["名詞：畢業","completion of studies","After graduation, she plans to work at a local newspaper.","畢業後，她計畫到當地一家報社工作。","completion of studies 是此義的解說性表達。"]],"l4-0505":[["名詞：文法","無直接同義詞","The teacher corrected the grammar in my letter without changing its meaning.","老師修正了信中的文法，但沒有改變原意。","syntax 指句法，範圍比整體 grammar 窄。"]],"l4-0506":[["形容詞：文法正確的","grammatically correct","A sentence can be grammatical without sounding natural in everyday conversation.","一個句子即使文法正確，在日常對話中也未必聽起來自然。",""]],"l4-0507":[["名詞：葡萄柚","無直接同義詞","She cut a grapefruit in half and placed it beside the toast.","她把葡萄柚切成兩半，放在吐司旁邊。",""]],"l4-0508":[["形容詞：感激的","thankful / appreciative","I am grateful for the help you gave me during the move.","我很感激你在搬家期間給我的幫忙。",""]],"l4-0509":[["名詞：感謝","thankfulness / appreciation","The family expressed their gratitude to everyone who had helped search for the dog.","這家人向所有協助尋狗的人表達了感謝。",""]],"l4-0510":[["名詞：墓穴、墳墓","burial place","Fresh flowers lay on the grave beside the old church.","老教堂旁的墳墓上放著鮮花。","burial place 為近義表達；詞條的 1 是分義標記。"]],"l4-0511":[["形容詞：嚴重的","serious / severe","The engineers expressed grave concern about the condition of the bridge.","工程師對橋梁的狀況表達了嚴重關切。","此義是形容詞，與墳墓的名詞義不同；2 是分義標記。"]],"l4-0512":[["形容詞：油膩的","oily","The paper bag became greasy after we put the fried snacks inside.","我們把炸物放進紙袋後，紙袋變得油油的。",""]],"l4-0513":[["名詞：問候","salutation","She gave us a warm greeting when we arrived at the house.","我們抵達她家時，她熱情地向我們打招呼。","salutation 較正式，也常指信件開頭的稱呼。"]],"l4-0514":[["名詞：悲痛","sorrow / anguish","The loss of her oldest friend filled her with grief.","失去交情最久的朋友，讓她滿心悲痛。",""]],"l4-0515":[["動詞：悲痛、哀傷","mourn","The community grieved for the teacher who had helped so many children.","社區居民為那位曾幫助許多孩子的老師離世而哀傷。",""]],"l4-0516":[["動詞：磨碎","crush / pulverize","Grind the coffee beans just before you make the coffee.","煮咖啡前再把咖啡豆磨碎。","pulverize 強調磨成很細的粉末；grind 不一定磨到那麼細。"]],"l4-0517":[["名詞：商品保固","warranty","The washing machine comes with a two-year guarantee.","這台洗衣機附有兩年保固。","在商品保固語境中 guarantee 與 warranty 相近，具體內容以保固條款為準。"]],"l4-0518":[["名詞：內疚","remorse","He felt a deep sense of guilt about forgetting his sister's birthday.","忘記妹妹的生日，讓他感到深深的內疚。","remorse 常表示對自己的過錯深感懊悔。"]],"l4-0519":[["形容詞：有罪的","culpable","The jury found him guilty of stealing the missing painting.","陪審團認定他犯下了竊取失蹤畫作的罪行。","guilty of 是常見搭配；culpable 側重應受責備或負責，句法不同。"]],"l4-0520":[["名詞：海灣","bay","The fishing village lies on the eastern shore of a large gulf.","這座漁村位於一個大海灣的東岸。","gulf 通常較大且深入陸地；bay 的範圍較廣。"]],"l4-0521":[["形容詞：習慣性的","customary / usual","She gave her habitual wave as the bus pulled away.","公車駛離時，她照慣例揮了揮手。",""]],"l4-0522":[["動詞：使停止","stop / suspend","The workers halted construction when they discovered an underground pipe.","工人發現地下管線時，停止了施工。",""]],"l4-0523":[["名詞：手寫字跡","script / penmanship","I recognized my mother's handwriting on the envelope.","我認出了信封上母親的筆跡。","penmanship 也常指書寫技術或字體表現。"]],"l4-0524":[["動詞：變硬","set / solidify","Leave the clay in a warm place to harden overnight.","把黏土放在溫暖的地方一整晚，讓它變硬。","solidify 常指由液態轉固態；harden 也可指原本的固體變得更硬。"]],"l4-0525":[["名詞：困苦","adversity / difficulty","The family faced years of hardship after their farm was destroyed.","農場被毀後，這家人度過了多年的艱苦生活。",""]],"l4-0526":[["名詞：電腦硬體","physical components","The technician checked the hardware before reinstalling the software.","技術人員先檢查硬體，再重新安裝軟體。","physical components 是電腦硬體的解說性表達。"]],"l4-0527":[["名詞：口琴","mouth organ","He played a cheerful tune on his harmonica while we waited for the bus.","等公車時，他用口琴吹奏了一段輕快的旋律。",""]],"l4-0528":[["名詞：和睦","concord / agreement","The neighbors worked together in harmony to restore the shared garden.","鄰居們和睦合作，修復共用花園。",""]],"l4-0529":[["形容詞：刺耳的","grating / shrill","A harsh alarm sounded when someone opened the emergency door.","有人打開緊急出口時，響起了刺耳的警報。","shrill 還特別強調尖銳的高音。"]],"l4-0530":[["名詞：匆忙","hurry / rush","In her haste to catch the train, she left her umbrella behind.","她匆忙趕火車，忘了帶走雨傘。",""]],"l4-0531":[["動詞：加速","speed up / accelerate","The warm weather hastened the melting of the snow.","溫暖的天氣加快了雪的融化。",""]],"l4-0532":[["名詞：憎恨","hate / loathing","The novel explores how fear can develop into hatred.","這本小說探討了恐懼如何演變成憎恨。",""]],"l4-0533":[["複數名詞：頭戴式耳機","無直接同義詞","He put on his headphones so he could listen without disturbing anyone.","他戴上耳機，這樣聽音樂就不會打擾別人。","headset 常附有麥克風，與一般 headphones 不完全相同。"]],"l4-0534":[["形容詞：有益健康的","healthy / wholesome","The brochure describes several healthful ways to spend a weekend outdoors.","這份手冊介紹了幾種有益健康的戶外週末活動。","healthful 較正式；此處 healthy 取有益健康之義。"]],"l4-0535":[["名詞：直升機","chopper","A rescue helicopter landed in the field beside the hospital.","一架救援直升機降落在醫院旁的空地上。","chopper 是口語說法。"]],"l4-0536":[["名詞：獸群、畜群","無直接同義詞","A herd of cattle moved slowly toward the river.","一群牛緩緩走向河邊。","herd 常指牛、鹿等獸群；flock 通常用於鳥或羊等，不能任意互換。"]],"l4-0537":[["名詞：猶豫","reluctance / uncertainty","After a moment of hesitation, she agreed to lead the team.","猶豫了片刻後，她同意帶領團隊。","reluctance 帶不情願之意，hesitation 也可能只是拿不定主意。"]],"l4-0538":[["副詞：非常、很","very / greatly","The workshop was highly useful for teachers new to online learning.","對剛開始接觸線上教學的老師而言，這場工作坊非常實用。","highly 的搭配有限，例如 highly useful，不能全面取代 very。"]],"l4-0539":[["名詞：祖國、故鄉","native country / home country","She returned to her homeland after spending twenty years overseas.","在海外生活二十年後，她回到了祖國。",""]],"l4-0540":[["名詞：蜜月","無直接同義詞","They spent their honeymoon exploring small towns along the coast.","他們在蜜月期間遊覽了沿海的小鎮。",""]],"l4-0541":[["形容詞：正直高尚的","upright / ethical","Returning the money was the only honorable choice he could make.","把錢還回去，是他唯一能做出的正直選擇。",""]],"l4-0542":[["名詞：掛鉤","無直接同義詞","Hang your coat on the hook behind the door.","把外套掛在門後的掛鉤上。",""]],"l4-0543":[["形容詞：抱持希望的","optimistic","We remain hopeful that the missing cat will find its way home.","我們仍抱著希望，相信走失的貓會找到回家的路。",""]],"l4-0544":[["名詞：地平線","無直接同義詞","A line of dark clouds appeared on the horizon.","地平線上出現了一排烏雲。","skyline 指建築或地形形成的天際輪廓，不等於 horizon。"]],"l4-0545":[["動詞：使驚恐","appall / shock","The condition of the abandoned animals horrified the volunteers.","那些遭棄養動物的狀況讓志工們驚駭不已。",""]],"l4-0546":[["名詞：軟水管","hosepipe","We used a hose to wash the mud off our boots.","我們用水管把靴子上的泥沖掉。","hosepipe 較常見於英式英語。"]],"l4-0547":[["名詞：主人、東道主","無直接同義詞","Our host showed us to a table in the garden.","主人帶我們到花園裡的一張桌子旁。","host 指接待他人的人；owner 只是所有者，不一定負責接待。"],["動詞：主辦","organize / hold","The school will host a debate competition next month.","學校將在下個月主辦辯論比賽。",""]],"l4-0548":[["名詞：青年旅舍","youth hostel","We stayed in a hostel within walking distance of the railway station.","我們住在一間步行就能到火車站的青年旅舍。","hostel 的客群不一定僅限青年，常提供共用設施。"]],"l4-0549":[["名詞：同住的一戶人家","無直接同義詞","Each household received a leaflet about the new recycling schedule.","每戶人家都收到了一份介紹新回收時間表的傳單。","household 以同住為重點，成員不一定有親屬關係，因此不完全等於 family。"]],"l4-0550":[["名詞：家庭主婦","homemaker","She worked as a housewife for several years before returning to paid employment.","她當了幾年家庭主婦後，重新回到有薪工作。","homemaker 不限定性別；housewife 指以家務為主要工作的已婚女性。"]],"l4-0551":[["名詞：家務","household chores","We divide the housework so that neither of us has to do everything.","我們分擔家務，讓任何一方都不必包辦所有事情。","housework 不可數；household chores 使用複數。"]],"l4-0552":[["名詞：人類","humankind / mankind","The exhibition considers how new discoveries have changed the lives of humanity.","這個展覽探討新發現如何改變人類的生活。","humankind 為不限定性別的常用表達。"]],"l4-0553":[["名詞：空氣濕度","moisture level","The high humidity made our clothes feel damp even indoors.","濕度很高，即使在室內，我們的衣服也感覺潮潮的。","moisture level 是此義項的解說性表達，humidity 特指空氣中的水氣。"]],"l4-0554":[["名詞：颶風","無直接同義詞","The hurricane damaged fishing boats along the coast.","颶風損壞了沿海的漁船。","hurricane 與 typhoon 是依海域使用的不同名稱；tropical cyclone 範圍較廣，並非直接同義詞。"]],"l4-0555":[["名詞：氫","無直接同義詞","The laboratory uses a special sensor to detect hydrogen leaks.","實驗室使用特殊感測器偵測氫氣洩漏。",""]],"l4-0556":[["名詞：冰山","無直接同義詞","The passengers watched an iceberg drift past the ship.","旅客看著一座冰山漂過船邊。","glacier 是冰河，不等於漂浮海上的 iceberg。"]],"l4-0557":[["形容詞：完全相同的","exactly the same / indistinguishable","The two keys looked identical, but only one opened the door.","這兩把鑰匙看起來一模一樣，但只有一把打得開門。",""]],"l4-0558":[["名詞：身分證明文件","ID / proof of identity","The receptionist asked to see some identification before handing over the keys.","接待人員交付鑰匙前，要求查看身分證明文件。","identification 在此不可數；ID 是常用縮寫。"]],"l4-0559":[["動詞：辨認","recognize","The witness identified the missing bicycle from a photograph.","目擊者從照片中認出了那輛失竊的腳踏車。",""]],"l4-0560":[["名詞：慣用語","idiomatic expression","The teacher explained the idiom using a situation from everyday life.","老師用日常生活中的情境解釋這個慣用語。",""]],"l4-0561":[["形容詞：閒置的","unused / inactive","The factory's machines stood idle while workers waited for new materials.","工人等待新材料時，工廠的機器都閒置著。",""]],"l4-0562":[["名詞：受崇拜的人物","hero","The young athlete finally met her childhood idol at the awards ceremony.","這位年輕運動員終於在頒獎典禮上見到了兒時偶像。","hero 在此指心目中敬仰的人，不一定是英勇人物。"]],"l4-0563":[["形容詞：不知道的","unaware / uninformed","We were ignorant of the rule until a staff member explained it.","直到工作人員解釋，我們才知道這項規定。","ignorant of 表示不知道某事；直接說某人 ignorant 可能帶貶意。"]],"l4-0564":[["動詞：用例子說明","demonstrate / explain","The teacher used a map to illustrate the route taken by the explorers.","老師用地圖說明探險者走過的路線。",""]],"l4-0565":[["名詞：插圖","picture / drawing","The book contains detailed illustrations of plants found in the mountains.","書中有山區植物的精細插圖。",""]],"l4-0566":[["形容詞：想像得到的","conceivable","The store sells camping equipment in every color imaginable.","這家店販售各種想像得到的顏色的露營裝備。","every…imaginable 中 imaginable 常置於被修飾名詞之後。"]],"l4-0567":[["形容詞：想像中的","fictional / make-believe","The children drew maps of an imaginary island filled with unusual animals.","孩子們畫出了一座充滿奇特動物的想像島嶼的地圖。",""]],"l4-0568":[["形容詞：富有想像力的","creative / inventive","Her imaginative use of recycled materials impressed the judges.","她富有創意地運用回收材料，令評審印象深刻。","imaginative 指有想像力；imaginary 指想像出來、並非真實存在。"]],"l4-0569":[["動詞：模仿","copy / mimic","The child tried to imitate the way his grandfather walked.","孩子試著模仿祖父走路的樣子。",""]],"l4-0570":[["名詞：仿製品","copy / replica","The necklace is an inexpensive imitation of a famous royal jewel.","這條項鍊是某件著名王室珠寶的廉價仿製品。",""]],"l4-0571":[["名詞：移入某國的移民","無直接同義詞","As a recent immigrant, she joined a local group to practice the language.","作為剛移居當地的新移民，她加入了一個在地團體練習語言。","newcomer 只表示新來者；immigrant 特指為居住而移入另一國的人。"]],"l4-0572":[["動詞：移居入境","settle in another country","Her grandparents immigrated to Canada when they were young.","她的祖父母年輕時移居加拿大。","所列為釋義表達；immigrate to 著重移入目的地，emigrate from 著重移出原國。"]],"l4-0573":[["名詞：移入、移民活動","inward migration","The museum documents the history of immigration to the island.","這間博物館記錄了人們移居這座島的歷史。","inward migration 為解說性近義表達。"]],"l4-0574":[["名詞：撞擊","collision / blow","The impact shattered the car's front window.","撞擊震碎了汽車的前窗。",""]],"l4-0575":[["動詞：暗示","suggest / hint","Her smile seemed to imply that she already knew the answer.","她的微笑似乎暗示，她早已知道答案。","imply 側重說話者或事物暗示；infer 則是接收者推斷。"]],"l4-0576":[["名詞：印象","feeling / perception","The quiet streets gave me the impression that most residents were still asleep.","安靜的街道讓我覺得，大多數居民似乎仍在睡覺。",""]],"l4-0577":[["名詞：事件","event / occurrence","The manager asked us to write down exactly what happened during the incident.","經理要我們詳實記錄事件發生時的經過。","incident 常指不尋常或不愉快的事件；event 較中性。"]],"l4-0578":[["介系詞：包括","無直接同義詞","The fee covers all meals, including breakfast on the final day.","費用包含所有餐點，包括最後一天的早餐。","such as 用來舉例，including 表明實際包含，並非全面可互換。"]],"l4-0579":[["名詞：跡象","sign / signal","The empty shelves were an indication of how popular the new product had become.","空空的貨架顯示出這項新產品有多受歡迎。",""]],"l4-0580":[["動詞：工業化","develop industry","The region began to industrialize after the railway reached its largest town.","鐵路通到當地最大的城鎮後，這個地區開始工業化。","develop industry 為近義片語，industrialize 更強調整體轉變。"]],"l4-0581":[["名詞：嬰兒","baby","The infant fell asleep while her father gently rocked the chair.","父親輕輕搖動椅子時，女嬰睡著了。",""]],"l4-0582":[["動詞：感染","無直接同義詞","The researchers studied how the virus infects the plant's leaves.","研究人員探討這種病毒如何感染植物的葉片。","contaminate 指汙染，並不必然發生生物感染。"]],"l4-0583":[["名詞：感染","無直接同義詞","The doctor examined the wound for signs of infection.","醫師檢查傷口是否有感染跡象。","illness 是疾病，infection 是感染，不能一概等同。"]],"l4-0584":[["名詞：通貨膨脹","rising prices","The article explains how inflation affects the cost of everyday goods.","這篇文章說明通貨膨脹如何影響日常商品的價格。","rising prices 是便於理解的近義描述；inflation 指一般價格水準持續上升。"]],"l4-0585":[["形容詞：有影響力的","powerful / important","Her teacher was an influential figure in her decision to become an artist.","她的老師對她決定成為藝術家有重要影響。",""]],"l4-0586":[["名詞：資訊","details / facts","The website provides information about bus routes and ticket prices.","這個網站提供公車路線與票價資訊。","information 為不可數名詞；details、facts 是複數可數名詞，換用時需調整句法。"]],"l4-0587":[["形容詞：提供有用資訊的","instructive / enlightening","The guide gave an informative talk about the history of the bridge.","導遊介紹了橋梁的歷史，內容讓人增長見聞。","informative 形容內容有資訊價值，不是形容某人本身見聞廣博。"]],"l4-0588":[["名詞：食材、材料","component","Flour is the main ingredient in this simple bread recipe.","麵粉是這份簡單麵包食譜中的主要材料。","component 為較廣的組成部分；食譜中通常用 ingredient。"]],"l4-0589":[["形容詞：最初的","first / preliminary","Our initial plan was to stay for two days, but we extended the visit.","我們最初計畫待兩天，後來延長了停留時間。",""],["名詞：姓名起首字母","無直接同義詞","She wrote her initials on the inside cover of the notebook.","她在筆記本封面內側寫上姓名的起首字母。","姓名的縮寫字母常用複數 initials。"]],"l4-0590":[["名詞：清白、無罪","blamelessness","The new evidence finally proved his innocence.","新的證據終於證明了他的清白。",""]],"l4-0591":[["動詞：輸入資料","enter / key in","Please input your booking number before choosing a seat.","選擇座位前，請先輸入訂位編號。",""]],"l4-0592":[["動詞：插入","put in / slip in","Insert the card into the slot with the printed side facing up.","把卡片有印字的一面朝上，插入卡槽。",""]],"l4-0593":[["名詞：檢查","examination / check","The building passed its final safety inspection yesterday.","這棟建築物昨天通過了最後一次安全檢查。",""]],"l4-0594":[["名詞：靈感","無直接同義詞","The colors of the old market provided inspiration for her paintings.","老市場的色彩為她的畫作帶來了靈感。","idea 是點子，inspiration 在此偏重激發創作的靈感來源。"]],"l4-0595":[["動詞：激勵","motivate / encourage","His account of the journey inspired us to explore more of our own country.","他對旅程的敘述，激勵我們更深入探索自己的國家。",""]],"l4-0596":[["動詞：安裝","fit / set up","The technician installed a new air conditioner in the classroom.","技術人員在教室裡安裝了一台新冷氣。",""]],"l4-0597":[["名詞：直覺","intuition / gut feeling","My first instinct was to check whether everyone had left the building.","我的第一個直覺反應，是確認所有人是否都已離開大樓。","gut feeling 較口語；instinct 另可指天生本能。"]],"l4-0598":[["動詞：指示","direct / tell","The supervisor instructed us to keep the emergency exit clear.","主管指示我們，要讓緊急出口保持暢通。",""]],"l4-0599":[["名詞：教練、指導老師","teacher / trainer","The swimming instructor showed us how to breathe while moving through the water.","游泳教練教我們如何在游動時換氣。",""]],"l4-0600":[["動詞：侮辱","offend / slight","He did not mean to insult her by forgetting to introduce her.","他忘了介紹她，但並非有意冒犯她。","insult 常指以言行貶低他人；offend 的冒犯範圍較廣。"]],"l4-0601":[["不可數名詞：保險保障","coverage","Our travel insurance covered the cost of replacing the stolen suitcase.","我們的旅遊保險支付了更換被偷行李箱的費用。","coverage 指保障範圍或承保，insurance 指保險制度或契約。"]],"l4-0602":[["形容詞：智力的；思考上的","mental / cognitive","The debate offered an intellectual challenge that the students clearly enjoyed.","這場辯論帶來思考上的挑戰，學生們顯然樂在其中。",""]],"l4-0603":[["名詞：理解與推理能力","intellect / reasoning ability","Her intelligence showed in the careful questions she asked during the discussion.","她在討論中提出周詳的問題，展現了聰明才智。",""]],"l4-0604":[["形容詞：聰明的","clever / bright","The intelligent young assistant noticed a flaw that everyone else had missed.","那位聰明的年輕助理發現了其他人都沒注意到的缺失。",""]],"l4-0605":[["及物動詞：打算","plan / mean","We intend to restore the old theater before its hundredth anniversary.","我們打算在老劇院百週年以前完成修復。","intend to do；mean to do。"]],"l4-0606":[["形容詞：強烈的","strong / extreme","The intense heat forced the road crew to work before sunrise.","酷熱迫使道路施工人員在日出前工作。",""]],"l4-0607":[["及物動詞：加劇","heighten / strengthen","The missing documents intensified our concern about the project's finances.","文件遺失加深了我們對專案財務狀況的擔憂。",""]],"l4-0608":[["名詞：強度","strength","The technician adjusted the intensity of the lights above the stage.","技術人員調整了舞台上方燈光的強度。",""]],"l4-0609":[["形容詞：密集的","concentrated","An intensive language course helped him prepare for his semester abroad.","一門密集語言課程幫他為到海外就讀一學期做好準備。","intensive 著重短時間投入大量活動；intense 著重強烈程度。"]],"l4-0610":[["名詞：意圖","aim / purpose","Her intention was to simplify the form, but several questions became less clear.","她本想簡化表格，卻讓幾個問題變得更不清楚。",""]],"l4-0611":[["不及物動詞：互動","engage","The exhibit lets visitors interact with digital versions of ancient musical instruments.","這個展區讓遊客與古代樂器的數位模型互動。","interact with、engage with 都可表示與物件互動；communicate 不適合此例的樂器模型。"]],"l4-0612":[["名詞：互動","exchange / communication","Regular interaction between designers and customers improved the final product.","設計師與顧客定期互動，改善了最終產品。",""]],"l4-0613":[["不及物動詞：干擾","disrupt / get in the way","Noise from the nearby construction site interfered with our recording session.","附近工地的噪音干擾了我們的錄音工作。","interfere with 後接受干擾的事；disrupt 直接接受詞。"]],"l4-0614":[["形容詞：中等程度的","mid-level","The intermediate class is designed for swimmers who can already cross the pool.","中級班是為已能游到泳池另一端的學員設計的。",""]],"l4-0615":[["名詞：網際網路","the Net","The village finally gained reliable access to the Internet through a new cable.","新電纜讓村莊終於有了可靠的網際網路連線。","the Net 為非正式說法；the Web 是網際網路上的服務，不完全相同。"]],"l4-0616":[["及物動詞：解讀","understand / construe","She interpreted his silence as a sign that he disagreed.","她把他的沉默解讀為不同意的表示。","interpret A as B。"]],"l4-0617":[["名詞：中斷；干擾","disruption / break","We completed the interview without interruption after moving to a quieter room.","換到較安靜的房間後，我們順利完成訪談，沒有受到打擾。",""]],"l4-0618":[["形容詞：親密的","close","Only a few intimate friends were invited to the small wedding.","只有幾位親密好友受邀參加那場小型婚禮。",""]],"l4-0619":[["名詞：語調","pitch pattern","Her rising intonation made the statement sound like a question.","她上揚的語調讓那句陳述聽起來像個問題。",""]],"l4-0620":[["及物動詞：侵犯","intrude on / encroach on","The photographer refused to invade the family's privacy during their holiday.","攝影師拒絕在那家人度假時侵犯他們的隱私。",""]],"l4-0621":[["名詞：侵犯","intrusion / violation","Residents considered the constant filming an invasion of their privacy.","居民認為持續拍攝的行為侵犯了他們的隱私。",""]],"l4-0622":[["名詞：發明物","無直接同義詞","His latest invention folds a bicycle into a compact shape within seconds.","他最新的發明能在幾秒內把自行車摺成小巧的形狀。","innovation 可指新方法或改良，範圍與 invention 不同。"]],"l4-0623":[["及物動詞：投入資金","put money into","The company invested its savings in equipment that uses less energy.","公司把積存的資金投入更節能的設備。","invest money in something。"]],"l4-0624":[["名詞：投入的資金","capital outlay","The new ovens required a substantial investment from the small bakery.","購置新烤箱需要那家小麵包店投入相當多的資金。",""]],"l4-0625":[["名詞：調查","inquiry / examination","An investigation into the missing paintings revealed weaknesses in the museum's security.","針對失蹤畫作的調查揭露了博物館保安上的漏洞。",""]],"l4-0626":[["及物動詞：讓人參與","include / engage","The architect involved local residents in planning the new public square.","建築師讓當地居民參與新公共廣場的規劃。","involve someone in something。"]],"l4-0627":[["名詞：參與","participation / engagement","Parents' involvement in the reading program increased after the evening sessions began.","閱讀計畫開辦晚間場次後，家長的參與增加了。",""]],"l4-0628":[["及物動詞：使隔絕","cut off / separate","Heavy snowfall isolated the village from the rest of the valley.","大雪使村莊與山谷其他地區隔絕。",""]],"l4-0629":[["名詞：孤立；隔絕","separation","The island's isolation helped preserve traditions that had disappeared elsewhere.","島嶼與外界隔絕，使其他地方已消失的傳統得以保存。",""]],"l4-0630":[["不及物動詞：發癢","feel itchy","My arms began to itch after I brushed against the rough plants.","我的手臂擦過粗糙的植物後，開始發癢。",""]],"l4-0631":[["名詞：嫉妒","envy","He felt a flash of jealousy when his colleague received the award.","同事獲獎時，他心裡閃過一絲嫉妒。",""]],"l4-0632":[["形容詞：資淺的","less experienced / lower-ranking","A senior engineer checked the calculations prepared by her junior colleague.","一位資深工程師檢查了資淺同事完成的計算。",""]],"l4-0633":[["形容詞：熱切的","eager / enthusiastic","The students were keen to test their bridge design with heavier weights.","學生們迫切想用更重的砝碼測試他們設計的橋。","keen to do；keen on something。"]],"l4-0634":[["名詞：手指關節","finger joint","He scraped a knuckle while reaching behind the metal cabinet.","他把手伸到金屬櫃後面時，擦傷了一個指關節。",""]],"l4-0635":[["不可數名詞：勞動","work / toil","Repairing the stone wall required several days of hard physical labor.","修復石牆需要好幾天辛苦的體力勞動。","toil 強調辛勞。"]],"l4-0636":[["名詞：實驗室","lab","The samples arrived at the laboratory in carefully sealed containers.","樣本裝在仔細密封的容器裡，送達實驗室。",""]],"l4-0637":[["不及物動詞：落後","fall behind / trail","Sales in the northern stores lagged behind those in the city center.","北部各店的銷售額落後於市中心的分店。",""]],"l4-0638":[["名詞：里程碑","milestone","Opening the new library was a landmark in the town's recovery.","新圖書館啟用，是城鎮復甦過程中的一個里程碑。",""]],"l4-0639":[["名詞：自然景觀","scenery","The train passed through a landscape of vineyards and low green hills.","火車駛過一片葡萄園與低矮綠丘交錯的景色。","landscape 可數；scenery 通常不可數。"]],"l4-0640":[["名詞：山崩","landslip","A landslide blocked the mountain road after three days of heavy rain.","接連三天大雨後，一場山崩堵住了山路。","mudslide 特指含大量泥水的滑動，不涵蓋所有 landslide。"]],"l4-0641":[["副詞：主要地","mainly / chiefly","The festival's success depended largely on the work of local volunteers.","慶典能成功，主要仰賴當地志工的付出。",""]],"l4-0642":[["副詞：最近","recently / of late","The station café has been closing earlier than usual lately.","最近車站咖啡館都比平常提早打烊。",""]],"l4-0643":[["及物動詞：發射","send up","The team launched a weather balloon to measure conditions above the clouds.","團隊放升了一顆氣象氣球，測量雲層上方的狀況。",""]],"l4-0644":[["形容詞：合法的","legal / legitimate","The judge confirmed that the documents had been obtained through lawful means.","法官確認，那些文件是經由合法方式取得的。",""]],"l4-0645":[["及物動詞：引導","guide / direct","A narrow staircase leads visitors to the rooftop viewing platform.","一座狹窄樓梯引導遊客前往屋頂觀景臺。","本句 lead 讀 /liːd/；金屬鉛 lead 讀 /led/。"]],"l4-0646":[["不及物動詞：倚靠","rest","She leaned against the railing while waiting for the ferry.","她靠著欄杆等候渡輪。","lean against、rest against 均可表示倚靠。"]],"l4-0647":[["形容詞：精瘦的","slim / slender","The lean runner moved easily through the crowded starting area.","那位精瘦的跑者輕鬆穿過擁擠的起跑區。","lean 常暗示脂肪少、體格結實。"]],"l4-0648":[["形容詞：博學的","scholarly / erudite","The learned professor explained the old manuscript without consulting any notes.","那位博學的教授不用查看筆記，就解說了那份古老手稿。","本義 learned 讀兩個音節 /ˈlɜːnɪd/。"]],"l4-0649":[["名詞：學習","study / acquisition of knowledge","Hands-on learning helped the apprentices understand how the machines worked.","實作學習幫助學徒理解機器的運作方式。",""]],"l4-0650":[["名詞：專題演講","talk / presentation","The lecture on ocean currents attracted students from several departments.","那場關於洋流的演講吸引了好幾個系所的學生。",""]],"l4-0651":[["名詞：講者","speaker","The lecturer paused to answer a question from the back row.","講者停下來回答後排聽眾提出的問題。",""]],"l4-0652":[["名詞：傳說","traditional tale","According to local legend, a hidden tunnel connects the castle and the monastery.","根據當地傳說，城堡和修道院之間有一條隱密通道。",""]],"l4-0653":[["形容詞：悠閒的","unhurried / relaxed","We enjoyed a leisurely breakfast before exploring the streets around the hotel.","悠閒享用早餐後，我們才去探索飯店周圍的街道。",""]],"l4-0654":[["名詞：執照","licence","The inspector asked to see the restaurant's license before checking the kitchen.","檢查員進廚房檢查前，先要求查看餐廳的營業執照。","licence 是英式名詞拼字。"]],"l4-0655":[["不及物動詞：變亮","brighten","The sky began to lighten as the first fishing boats left port.","第一批漁船出港時，天空開始亮了起來。",""]],"l4-0656":[["名詞：限制","restriction / constraint","The main limitation of the apartment is its lack of storage space.","這間公寓最主要的限制，是缺少收納空間。",""]],"l4-0657":[["不可數名詞：烈酒","spirits / hard liquor","The bartender arranged the bottles of liquor on the shelf behind the counter.","酒保把烈酒瓶整齊排放在吧臺後的架子上。","美式 liquor 通常指蒸餾烈酒，並非所有含酒精飲料。"]],"l4-0658":[["形容詞：文學的","無直接同義詞","The town holds a literary festival where readers can meet local authors.","鎮上舉辦文學節，讓讀者能與當地作家見面。",""]],"l4-0659":[["不可數名詞：研究文獻","published research","She reviewed the medical literature before designing her study of sleep patterns.","設計睡眠模式研究前，她先回顧了醫學文獻。",""]],"l4-0660":[["名詞：貸款","無直接同義詞","A small bank loan helped the couple purchase equipment for their bakery.","一筆小額銀行貸款幫助那對夫妻購置麵包店設備。",""]],"l4-0661":[["名詞：位置","site / position","The restaurant's location beside the station attracts commuters at lunchtime.","餐廳位於車站旁，午餐時段吸引了許多通勤者。",""]],"l4-0662":[["名詞：可上鎖的置物櫃","無直接同義詞","Leave your backpack in a locker before entering the swimming pool area.","進入泳池區前，把背包放進置物櫃。",""]],"l4-0663":[["名詞：推理邏輯","reasoning","I understood her conclusion but could not follow the logic behind it.","我明白她的結論，卻無法理解背後的推理。",""]],"l4-0664":[["形容詞：合乎邏輯的","reasonable / rational","Moving the delivery entrance away from pedestrians seemed the most logical solution.","把卸貨入口移離行人動線，似乎是最合理的解決方法。",""]],"l4-0665":[["名詞：乳液","無直接同義詞","She rubbed a little lotion onto her hands after washing the dishes.","洗完碗後，她在手上抹了一點乳液。",""]],"l4-0666":[["形容詞：糟糕的（口語）","terrible / awful","The lousy weather forced us to cancel our boat trip twice.","糟糕的天氣讓我們兩度取消搭船遊覽。",""]],"l4-0667":[["形容詞：忠誠的","faithful / devoted","The café's loyal customers kept returning throughout the lengthy renovations.","咖啡館漫長整修期間，忠實顧客仍持續光顧。",""]],"l4-0668":[["名詞：忠誠","devotion / allegiance","Her loyalty to the team never weakened despite several difficult seasons.","儘管經歷幾個艱難賽季，她對球隊的忠誠始終不減。",""]],"l4-0669":[["形容詞：月球的","of the Moon","The astronauts photographed the rough lunar surface before collecting samples near their lander.","太空人先拍攝崎嶇的月球表面，再到登陸器附近採集樣本。",""]],"l4-0670":[["形容詞：奢華舒適的","lavish / opulent","The hotel transformed an old warehouse into luxurious suites overlooking the harbor.","飯店把舊倉庫改造成可眺望港口的豪華套房。",""]],"l4-0671":[["名詞：奢侈的享受","indulgence / extravagance","For parents of young children, a quiet breakfast can feel like a luxury.","對有幼兒的父母而言，安靜吃頓早餐可能就是奢侈享受。",""]],"l4-0672":[["不可數名詞：機械設備","machines / mechanical equipment","The factory replaced its aging machinery to reduce unexpected shutdowns.","工廠更換了老舊機械，以減少突發停工。",""]],"l4-0673":[["名詞：女士（正式稱呼）","ma'am","Excuse me, madam, but you left your umbrella beside the counter.","女士，不好意思，您的雨傘忘在櫃檯旁了。","madam 作正式稱呼；ma'am 是較常見的縮略形式。"]],"l4-0674":[["形容詞：有磁性的","無直接同義詞","The magnetic strip holds the small tools against the workshop wall.","磁條把小工具吸附在工作室牆上。",""]],"l4-0675":[["形容詞：壯麗的","splendid / grand","The magnificent ceiling was hidden beneath layers of paint for decades.","那片華麗的天花板被層層油漆掩蓋了數十年。",""]],"l4-0676":[["片語動詞：編造","invent / fabricate","He made up a convincing excuse for arriving without the documents.","他編出一個聽來可信的理由，解釋為何沒帶文件。","原稿 makeup1／n／虛構混淆詞形；編造應用分寫片語動詞 make up。"]],"l4-0677":[["不可數名詞：化妝品","cosmetics","The actor removed his stage makeup before greeting friends outside the theater.","演員卸去舞臺妝後，才到劇院外與朋友見面。",""]],"l4-0678":[["名詞：操作手冊","handbook / guide","The manual includes clear diagrams for replacing the printer's ink cartridges.","手冊提供清楚的圖解，說明如何更換印表機墨水匣。",""]],"l4-0679":[["及物動詞：大量製造","produce / fabricate","The company manufactures bicycle frames from lightweight metal in its coastal factory.","公司在沿海工廠用輕金屬製造自行車車架。",""]],"l4-0680":[["名詞：製造商","producer / maker","The manufacturer recalled the lamps after discovering a problem with the wiring.","製造商發現線路問題後，召回了那些燈具。",""]],"l4-0681":[["名詞：馬拉松賽跑","無直接同義詞","Volunteers handed out water along the route of the city's annual marathon.","志工沿著城市年度馬拉松的路線發放飲水。",""]],"l4-0682":[["名詞：頁邊空白","blank edge","The teacher wrote a short comment in the margin of my essay.","老師在我作文的頁邊空白處寫了一則簡短評語。",""]],"l4-0683":[["名詞：心智成熟","無直接同義詞","Her maturity showed in the calm way she handled criticism from her teammates.","她沉著面對隊友的批評，展現了成熟的態度。","maturity 指成熟的狀態；emotional development 指情緒發展的過程，不是直接同義詞。"]],"l4-0684":[["名詞：最大限額","upper limit / ceiling","The room can hold a maximum of thirty people comfortably.","這個房間最多能讓三十人舒適地使用。",""]],"l4-0685":[["及物動詞：測量","gauge / determine the dimensions of","Measure the doorway carefully before ordering the large wooden cabinet.","訂購大型木櫃前，先仔細測量門口尺寸。",""]],"l4-0686":[["名詞：機械維修技師","mechanical repair technician","The mechanic traced the unusual vibration to a loose engine part.","技師查出異常震動來自一個鬆動的引擎零件。",""]],"l4-0687":[["形容詞：機械方面的","無直接同義詞","A mechanical failure left the ferry unable to leave the dock.","機械故障讓渡輪無法駛離碼頭。",""]],"l4-0688":[["形容詞：難忘的","unforgettable","The unexpected visit from our former teacher made the reunion especially memorable.","以前的老師意外現身，讓那場同學會格外難忘。",""]],"l4-0689":[["名詞：紀念碑；紀念物","monument","The village built a memorial to honor those lost at sea.","村莊建了一座紀念碑，悼念在海上罹難的人。",""]],"l4-0690":[["名詞：寬恕；仁慈","compassion / clemency","The defeated soldiers asked the king for mercy after surrendering their weapons.","戰敗士兵交出武器後，請求國王寬恕。","clemency 尤指掌權者減輕懲罰或寬赦。"]],"l4-0691":[["形容詞：僅僅的","only / no more than","The repairs took a mere twenty minutes once the correct part arrived.","正確零件送到後，維修只花了短短二十分鐘。","mere 放在名詞前；改用 only 時句構可能略調。"]],"l4-0692":[["名詞：優點","strength / advantage","The committee considered the merits of each proposal before making its choice.","委員會考量各提案的優點後，才作出選擇。",""]],"l4-0693":[["名詞：信差","courier","A messenger delivered the signed agreement to the office before noon.","信差在中午前把簽妥的協議送到辦公室。",""]],"l4-0694":[["形容詞：凌亂的","untidy / disorganized","Her messy desk made it difficult to locate the missing invoice.","她的書桌很凌亂，因此很難找到那張不見的發票。",""]],"l4-0695":[["名詞：顯微鏡","無直接同義詞","Under the microscope, the thin leaf revealed a network of tiny cells.","在顯微鏡下，薄葉片呈現出微小細胞組成的網絡。",""]],"l4-0696":[["形容詞：氣候溫和的","temperate","The region's mild winters allow farmers to grow vegetables throughout the year.","這個地區冬季溫和，農夫全年都能種植蔬菜。",""]],"l4-0697":[["名詞：礦物","無直接同義詞","The geologist identified a green mineral inside the freshly broken rock.","地質學家辨認出了新敲開岩石裡的一種綠色礦物。",""]],"l4-0698":[["名詞：最低數量","lower limit","A minimum of six participants is needed for the workshop to proceed.","工作坊至少需要六名參加者才能開課。",""]],"l4-0699":[["名詞：部長","無直接同義詞","The education minister visited the island's only high school on Monday.","教育部長星期一走訪了島上唯一的高中。","cabinet member 泛指內閣成員，職銜不一定是 minister。"]],"l4-0700":[["名詞：政府部門","government department","The ministry announced new funding for repairs to rural school buildings.","該部宣布撥款，修繕鄉村學校建築。",""]],"l4-0701":[["不可數名詞：頑皮胡鬧","naughtiness","The twins were full of mischief and hid their father's slippers under the sofa.","那對雙胞胎很淘氣，把爸爸的拖鞋藏在沙發下。",""]],"l4-0702":[["形容詞：痛苦難受的","unhappy / wretched","The cold, wet journey left us miserable and desperate for a warm room.","又濕又冷的旅程讓我們難受極了，迫切想找間溫暖的房間。",""]],"l4-0703":[["名詞：不幸遭遇","bad luck / adversity","The family suffered another misfortune when the repair shop closed without returning their car.","維修店沒還車就歇業，讓這家人又遭遇了一樁不幸。",""]],"l4-0704":[["及物動詞：誤導","deceive / misinform","The outdated map misled us into following a route that ended at a locked gate.","過時的地圖誤導我們走上一條盡頭是上鎖大門的路線。",""]],"l4-0705":[["及物動詞：誤解","misinterpret / misconstrue","He misunderstood my suggestion and canceled the meeting instead of moving it online.","他誤解了我的建議，把會議取消，而不是改成線上舉行。",""]],"l4-0706":[["形容詞：適中的","medium / not excessive","The recipe recommends baking the bread at a moderate temperature.","食譜建議用適中的溫度烤麵包。",""]],"l4-0707":[["形容詞：謙虛的","humble / unassuming","Despite winning several awards, the young scientist remained modest about her achievements.","儘管贏得多項獎項，那位年輕科學家談到成就時仍很謙虛。",""]],"l4-0708":[["不可數名詞：謙遜","humility","Her modesty led her to praise the team rather than claim all the credit.","她很謙遜，選擇讚揚團隊，而沒有把功勞全攬在自己身上。",""]],"l4-0709":[["名詞：監視螢幕","display screen","The guard watched the entrance on a monitor beside the reception desk.","警衛透過接待櫃檯旁的監視螢幕，查看入口動靜。",""]],"l4-0710":[["形容詞：每月的","once-a-month","Our monthly meeting includes a short review of customer feedback.","我們每月的會議包含簡短檢討顧客意見的時間。",""]],"l4-0711":[["名詞：紀念碑","memorial","Flowers lay at the base of the monument in the town square.","鎮上廣場的紀念碑基座前擺放著鮮花。",""]],"l4-0712":[["副詞：此外","furthermore / in addition","The apartment is close to work; moreover, it has a sunny balcony.","公寓離上班地點很近；此外，還有一座陽光充足的陽臺。",""]],"l4-0713":[["副詞：主要地","mainly / chiefly","The audience consisted mostly of students interested in environmental science.","聽眾主要是對環境科學有興趣的學生。",""]],"l4-0714":[["及物動詞：激勵","inspire / encourage","Seeing her progress motivated the other runners to keep practicing.","看到她的進步，其他跑者也受到激勵，繼續練習。",""]],"l4-0715":[["名詞：動力","drive / incentive","The chance to study overseas gave him fresh motivation to improve his English.","海外留學的機會給了他提升英語能力的新動力。",""]],"l4-0716":[["形容詞：多山的","full of mountains","The mountainous region has few straight roads and many isolated villages.","那個多山地區少有筆直的道路，卻有許多偏僻村莊。",""]],"l4-0717":[["及物動詞：割草","cut","We mowed the lawn early before the afternoon heat became uncomfortable.","我們趁早割完草坪，避開下午難受的高溫。","mow 特指用工具或機器割草；cut 的適用範圍較廣。"]],"l4-0718":[["專有名詞：MTV 音樂電視頻道","Music Television","My uncle remembers watching music videos on MTV after school as a teenager.","叔叔記得青少年時期放學後會看 MTV 播放的音樂錄影帶。","MTV 是專有名稱，不等於所有音樂錄影帶或 MV。"]],"l4-0719":[["形容詞：泥濘的","mud-covered / boggy","The muddy path was difficult to cross without getting our shoes wet.","小徑泥濘，我們很難不弄濕鞋子就走過去。",""]],"l4-0720":[["形容詞：多個的","several / numerous","The report identified multiple reasons for the delay in construction.","報告指出了施工延誤的多個原因。",""]],"l4-0721":[["名詞：謀殺犯","無直接同義詞","The detective discovered that the murderer had returned to the village.","偵探發現，那名殺人兇手回到了村莊。","killer 可泛指殺人者，murderer 特指犯下謀殺者。"]],"l4-0722":[["名詞：低語聲","muttering / soft voices","A murmur passed through the audience as the unexpected guest entered.","那位意外到場的嘉賓走進來時，觀眾間響起低語聲。",""]],"l4-0723":[["名詞：上唇鬍鬚","moustache","His thick mustache made him look quite different from his passport photograph.","他濃密的鬍子讓本人看起來與護照照片很不一樣。","moustache 是英式拼字；指上唇鬍鬚，不是整片 beard。"]],"l4-0724":[["形容詞：相互的","reciprocal / shared","Their partnership grew from years of mutual trust and careful communication.","他們的合作關係源自多年來的相互信任與謹慎溝通。",""]],"l4-0725":[["形容詞：神祕難解的","puzzling / enigmatic","A mysterious light appeared above the empty farmhouse every evening.","每天傍晚，空農舍上方都會出現一道神祕的光。",""]],"l4-0726":[["副詞：也就是","that is / specifically","One problem remains, namely, how to transport the equipment across the river.","還有一個問題，也就是如何把設備運過河。",""]],"l4-0727":[["名詞：國籍","citizenship","The application asks for your nationality and the country where you currently live.","申請表詢問你的國籍，以及你目前居住的國家。","nationality 與 citizenship 在某些法律制度中有區別。"]],"l4-0728":[["形容詞：近視的","short-sighted / myopic","The nearsighted student moved closer to read the writing on the board.","那位近視的學生走近了一點，讀取黑板上的字。",""]],"l4-0729":[["形容詞：貧困的","impoverished / poor","The charity delivers winter clothing to needy families in the district.","慈善機構把冬衣送給區內的貧困家庭。",""]],"l4-0730":[["及物動詞：疏於照顧","fail to care for","The owner neglected the garden until weeds covered the stone path.","主人疏於照料花園，直到雜草長滿了石板小徑。",""]],"l4-0731":[["及物動詞：協商達成","agree on","The two companies negotiated a delivery schedule that suited both sides.","兩家公司協商出一套雙方都能接受的交貨時程。","negotiate 強調透過協商達成；agree on 側重達成共識。"]],"l4-0732":[["副詞：然而","nonetheless / even so","The route was demanding; nevertheless, every member of the group completed it.","路線很辛苦；然而，團隊的每位成員都完成了。",""]],"l4-0733":[["名詞：惡夢","bad dream","She woke from a nightmare about being lost in an empty station.","她做了在空蕩車站迷路的惡夢，從夢中醒來。",""]],"l4-0734":[["不可數名詞：胡說","rubbish / absurdity","He dismissed the rumor as nonsense and asked for reliable evidence.","他認為那則傳聞是胡說，並要求提出可靠證據。",""]],"l4-0735":[["名詞：名詞（文法）","無直接同義詞","The teacher underlined each noun that referred to a place in the passage.","老師把文章中每個指地點的名詞畫上底線。",""]],"l4-0736":[["副詞：現今","these days / at present","Nowadays, many visitors book their museum tickets before arriving in the city.","如今，許多遊客還沒到達城市，就先訂好博物館門票。",""]],"l4-0737":[["形容詞：原子核的","無直接同義詞","The students used a diagram to explain the stages of a nuclear reaction.","學生用圖表說明核反應的各個階段。","atomic 範圍也可涵蓋整個原子，nuclear 著重原子核。"]],"l4-0738":[["形容詞：許多的","many","Numerous visitors stopped to photograph the flowers along the old railway line.","許多遊客停下來拍攝老鐵路沿線的花。",""]],"l4-0739":[["名詞：苗圃","plant nursery","We bought young fruit trees from a nursery outside the town.","我們從鎮外的一座苗圃買了果樹幼苗。",""]],"l4-0740":[["不可數名詞：尼龍","無直接同義詞","The lightweight tent is made of nylon and fits inside a small backpack.","這頂輕量帳篷以尼龍製成，可以放進小背包。",""]],"l4-0741":[["名詞：服從","compliance","The trainer rewarded the dog's obedience with a short game.","訓練師用一段短短的遊戲獎勵狗的服從表現。",""]],"l4-0742":[["形容詞：順從的","compliant / dutiful","The obedient dog waited quietly beside the gate until its owner returned.","那隻聽話的狗靜靜守在門邊，直到主人回來。",""]],"l4-0743":[["名詞：反對意見","protest / opposition","Her main objection to the plan was the loss of public green space.","她反對這項計畫的主要理由，是會失去公共綠地。",""]],"l4-0744":[["形容詞：客觀的","impartial / unbiased","The reviewer gave an objective assessment despite knowing the project's designer personally.","儘管私下認識專案設計師，評審仍作出了客觀評估。",""]],"l4-0745":[["名詞：目標","goal / aim","Our main objective is to make the website easier for first-time visitors to use.","我們的主要目標，是讓初次造訪的人更容易使用這個網站。",""]],"l4-0746":[["名詞：觀察","monitoring / watching","Careful observation of the birds revealed changes in their feeding habits.","仔細觀察鳥類後，發現牠們的覓食習慣有所改變。",""]],"l4-0747":[["名詞：障礙","barrier / hindrance","Limited transport remains a major obstacle to attending evening classes in the village.","交通不便仍是村民參加晚間課程的一大障礙。",""]],"l4-0748":[["及物動詞：取得","acquire / secure","We obtained permission to photograph the documents in the private collection.","我們獲准拍攝那批私人收藏的文件。",""]],"l4-0749":[["形容詞：偶爾的","infrequent / sporadic","Apart from an occasional truck, the road through the forest was quiet.","除了偶爾經過的卡車，穿越森林的道路十分安靜。",""]],"l4-0750":[["名詞：職業","line of work","The form asks for your occupation but does not require your employer's name.","表格詢問你的職業，但不要求填寫僱主名稱。",""]],"l4-0751":[["及物動詞：占用空間","take up / fill","The new reading area occupies the space where the old reception desk stood.","新的閱讀區占用了原本接待櫃檯所在的空間。",""]],"l4-0752":[["及物動詞：冒犯","insult / upset","His careless joke offended several people who had worked hard on the project.","他隨口開的玩笑，冒犯了幾位為專案努力付出的人。",""]],"l4-0753":[["名詞：違法行為","violation / crime","The court treated the damage to the protected building as a serious offense.","法院把破壞受保護建築的行為視為嚴重違法。",""]],"l4-0754":[["形容詞：冒犯人的","insulting / objectionable","The editor removed an offensive remark before publishing the interview.","編輯在刊出訪談前，刪去了一句冒犯人的話。",""]],"l4-0755":[["名詞：歌劇","無直接同義詞","The opera was performed outdoors with the castle walls as its backdrop.","那齣歌劇在戶外演出，以城堡的城牆為背景。",""]],"l4-0756":[["名詞：外科手術","surgery","The surgeon explained the operation to the family using a simple diagram.","外科醫師用簡單的圖解向家屬說明手術。","operation 指一次手術時可數；surgery 指手術通常不可數。"]],"l4-0757":[["及物動詞：反對","object to / resist","Many residents opposed the plan to replace the park with a parking lot.","許多居民反對把公園改成停車場的計畫。",""]],"l4-0758":[["形容詞：口頭的","spoken / verbal","The students gave oral reports before handing in their written assignments.","學生先作口頭報告，再交出書面作業。",""]],"l4-0759":[["名詞：天體軌道","orbital path","The satellite entered a stable orbit after the final engine adjustment.","引擎完成最後調整後，衛星進入了穩定軌道。",""]],"l4-0760":[["名詞：管弦樂團","無直接同義詞","The orchestra rehearsed the difficult passage several times before the conductor was satisfied.","管弦樂團把那段困難樂段排練了好幾次，指揮才滿意。",""]],"l4-0761":[["形容詞：生物來源的","biological","Fallen leaves add organic matter to the soil as they gradually decompose.","落葉逐漸分解時，會為土壤增添有機質。","此處 organic 指來自生物的物質，並非有機農業認證。"]],"l4-0762":[["副詞：否則","or else","Write down the address now; otherwise, we may forget it before we arrive.","現在把地址寫下來；否則，我們可能還沒到就忘了。",""]],"l4-0763":[["名詞：結果","result / consequence","The outcome of the meeting depended on whether both sides accepted the compromise.","會議結果取決於雙方是否接受折衷方案。",""]],"l4-0764":[["形容詞：傑出的","exceptional / excellent","Her outstanding presentation explained a difficult topic without unnecessary technical language.","她出色的簡報不用多餘術語，就說清楚了一個困難主題。",""]],"l4-0765":[["名詞：橢圓形","無直接同義詞","Draw an oval around the part of the diagram that needs correction.","在圖中需要修正的部分外圍畫一個橢圓。","ellipse 是精確的數學橢圓，oval 也可泛指蛋形。"]],"l4-0766":[["及物動詞：克服","surmount / get over","She overcame her fear of public speaking by practicing with a small group.","她透過在小組中練習，克服了公開演說的恐懼。",""]],"l4-0767":[["及物動詞：忽略","miss / fail to notice","We overlooked a small error in the address and sent the package elsewhere.","我們漏看了地址裡的一個小錯誤，把包裹寄到別處。",""]],"l4-0768":[["副詞：過夜；整晚","for the night","The hikers stayed overnight in a cabin before continuing to the summit.","健行者在木屋過夜後，繼續朝山頂前進。","原稿詞頭混入 a.；本句採 overnight 副詞用法。"]],"l4-0769":[["及物動詞：超越前方車輛","pass","The driver waited for a clear stretch of road before overtaking the slow tractor.","駕駛等到前方路段暢通，才超越緩慢的拖拉機。",""]],"l4-0770":[["及物動詞：推翻政權","oust / topple","The rebels overthrew the government after gaining control of the capital.","叛軍控制首都後，推翻了政府。",""]],"l4-0771":[["不可數名詞：氧氣","無直接同義詞","The nurse checked the oxygen supply before moving the patient to another room.","護理師把病人移到另一間病房前，先檢查氧氣供應。","oxygen 不等於普通空氣，兩者不能當作同義詞。"]],"l4-0772":[["名詞：速度","speed / rate","The guide slowed her pace so everyone could enjoy the view.","導遊放慢腳步，讓每個人都能欣賞風景。",""]],"l4-0773":[["名詞：專家小組","committee / group of experts","A panel of engineers reviewed the bridge design before construction began.","工程師小組在施工前審查了橋樑設計。",""]],"l4-0774":[["名詞：降落傘","chute","The parachute opened smoothly, slowing the package as it descended toward the field.","降落傘順利張開，讓往田野下降的包裹減速。","chute 是此義的簡稱。"]],"l4-0775":[["名詞：段落","無直接同義詞","The final paragraph explains how readers can support the conservation project.","最後一段說明了讀者可以如何支持保育計畫。",""]],"l4-0776":[["形容詞：不完整的","incomplete","The damaged camera recorded only a partial view of the accident.","受損的攝影機只錄到了事故的部分畫面。",""]],"l4-0777":[["名詞：參與","involvement / engagement","Student participation increased when the class began choosing its own discussion topics.","班上開始自行選擇討論主題後，學生的參與增加了。",""]],"l4-0778":[["名詞：分詞（文法）","無直接同義詞","The teacher circled the past participle 'broken' in the sentence on the board.","老師把黑板句子中的過去分詞 broken 圈了起來。",""]],"l4-0779":[["名詞：合作關係","collaboration / alliance","A partnership between the school and the museum created new learning opportunities.","學校與博物館建立合作關係，創造了新的學習機會。",""]],"l4-0780":[["形容詞：被動的","無直接同義詞","The workshop encouraged passive listeners to become active participants in the discussion.","工作坊鼓勵被動聆聽的人積極參與討論。",""]],"l4-0781":[["名詞：義大利麵食","無直接同義詞","The café makes fresh pasta each morning for its lunch menu.","咖啡館每天早上製作新鮮義大利麵，供應午餐菜單。","spaghetti 是 pasta 的一種，不是涵蓋相同範圍的同義詞。"]],"l4-0782":[["名詞：小卵石","small rounded stone","Smooth pebbles covered the beach where the river met the sea.","河流入海處的海灘上鋪滿了光滑的小卵石。",""]],"l4-0783":[["形容詞：古怪的","odd / strange","A peculiar smell came from the cupboard where we stored cleaning supplies.","存放清潔用品的櫥櫃傳出一股古怪的味道。",""]],"l4-0784":[["名詞：踏板","foot lever","The bicycle's left pedal came loose halfway up the steep hill.","自行車騎到陡坡半途，左邊踏板鬆掉了。",""]],"l4-0785":[["名詞：同儕","equal","She values honest advice from her peers in the design industry.","她很重視設計業同儕給予的真誠建議。","peer 指地位、年齡或能力相近者；此例是專業同儕。"]],"l4-0786":[["名詞：處罰","punishment / sanction","The club imposed a penalty on members who repeatedly damaged shared equipment.","社團對屢次損壞共用設備的成員施以處罰。",""]],"l4-0787":[["名詞：百分比單位","per cent","Nearly twenty percent of the seats remained empty when the performance began.","演出開始時，將近百分之二十的座位仍空著。","per cent 是分寫形式；percent 通常跟在數字後。"]],"l4-0788":[["名詞：百分比","無直接同義詞","A higher percentage of students completed the course after the schedule changed.","課表調整後，完成課程的學生比例提高了。","percentage 以百分制表示；proportion 不限定表達單位。"]],"l4-0789":[["名詞：完美","flawlessness","The chef spent years pursuing perfection in a single traditional dessert.","那位主廚花了多年，追求一道傳統甜點的完美境界。",""]],"l4-0790":[["名詞：香水","fragrance","A trace of her perfume remained on the scarf she had left behind.","她留下的圍巾上，仍有一絲香水氣味。","fragrance 可指香水，也可泛指香氣。"]],"l4-0791":[["形容詞：永久的","lasting / enduring","The exhibition will become a permanent part of the museum next year.","那個展覽明年將成為博物館的常設展。",""]],"l4-0792":[["不可數名詞：勸說","convincing / coaxing","After much persuasion, the owner agreed to open the garden to visitors.","經過再三勸說，主人同意開放花園供遊客參觀。","coaxing 常指耐心而溫和地勸誘。"]],"l4-0793":[["形容詞：有說服力的","convincing / compelling","Her persuasive argument convinced the committee to fund the library renovation.","她有說服力的論述讓委員會同意資助圖書館整修。",""]],"l4-0794":[["形容詞：悲觀的","gloomy / negative","He was pessimistic about finishing the repairs before the holiday weekend.","他對於連假前能否完成維修抱持悲觀態度。",""]],"l4-0795":[["名詞：花瓣","無直接同義詞","Pink petals floated on the pond beneath the flowering cherry tree.","開花的櫻樹下，粉紅色花瓣漂在池塘上。",""]],"l4-0796":[["名詞：可觀察的現象","occurrence","The scientists studied the unusual phenomenon using cameras placed along the coast.","科學家利用沿海架設的攝影機，研究那個不尋常的現象。","現象義的標準複數為 phenomena。"]],"l4-0797":[["名詞：哲學家","無直接同義詞","The philosopher asked whether a comfortable life was always a meaningful one.","那位哲學家問，舒適的生活是否必然有意義。",""]],"l4-0798":[["名詞：指導行動的理念","guiding principle","Her teaching philosophy centers on encouraging students to ask thoughtful questions.","她的教學理念以鼓勵學生提出有深度的問題為核心。",""]],"l4-0799":[["不可數名詞：攝影","taking photographs","Her interest in photography began with documenting changes in her neighborhood.","她從記錄社區的變化開始，對攝影產生興趣。",""]],"l4-0800":[["形容詞：身體的","bodily","The job requires physical strength as well as careful attention to detail.","這份工作除了需要留意細節，也需要體力。",""]],"l4-0801":[["名詞：醫師","doctor / medical practitioner","The physician asked about my symptoms before examining my throat.","醫師先詢問我的症狀，然後檢查我的喉嚨。","physician 常指內科醫師；doctor 也可指其他科別的醫師。"]],"l4-0802":[["名詞：物理學家","無直接同義詞","A physicist explained how the telescope detects light from distant galaxies.","一位物理學家解釋這部望遠鏡如何偵測來自遙遠星系的光。",""]],"l4-0803":[["名詞：物理學","無直接同義詞","Our physics class measured how quickly a ball rolled down the ramp.","我們的物理課測量了球沿斜坡滾下的速度。",""]],"l4-0804":[["名詞：鋼琴演奏者","piano player","The pianist adjusted the bench before beginning her final piece.","鋼琴演奏者在開始彈奏最後一首曲子前調整了琴椅。",""]],"l4-0805":[["名詞：扒手","無直接同義詞","A pickpocket stole his wallet while he was boarding the crowded train.","他登上擁擠的火車時，扒手偷走了他的皮夾。",""]],"l4-0806":[["名詞：先驅者","trailblazer","The museum honors a pioneer who opened engineering courses to women.","這座博物館向一位讓女性也能修讀工程課程的先驅致敬。",""]],"l4-0807":[["名詞：海盜","無直接同義詞","The captain warned that pirates had attacked ships near the island.","船長警告，海盜曾在那座島附近攻擊船隻。",""]],"l4-0808":[["形容詞：充足的；豐富的","abundant / ample","Fresh vegetables are plentiful at the market during the summer months.","夏季時，市場裡有充足的新鮮蔬菜。",""]],"l4-0809":[["名詞：故事情節","storyline","The novel has a clever plot that keeps readers guessing until the end.","這本小說的情節巧妙，讓讀者一直猜到結尾。",""]],"l4-0810":[["名詞：複數形式","plural form","The teacher asked us to write the plural of each noun.","老師要我們寫出每個名詞的複數形式。","此處指一個詞的複數形式，可數；原稿僅標 [U] 不足以涵蓋此用法。"]],"l4-0811":[["時間縮寫：下午；午後","無直接同義詞","The last guided tour begins at 4 p.m. near the main entrance.","最後一場導覽下午四點在正門附近開始。","此例 p.m. 表示午後時間；PM 表示首相是另一種縮寫用法。"]],"l4-0812":[["形容詞：有毒的","toxic","The guide warned us not to touch the poisonous berries beside the trail.","嚮導提醒我們不要碰步道旁有毒的漿果。",""]],"l4-0813":[["及物動詞：擦亮","buff","She polished the silver tray until she could see her reflection.","她把銀托盤擦得發亮，亮到能看見自己的倒影。",""]],"l4-0814":[["名詞：汙染","contamination","The city introduced stricter rules to reduce pollution from factories.","市政府實施更嚴格的規定，以減少工廠造成的汙染。",""]],"l4-0815":[["名詞：受歡迎的程度","無直接同義詞","The growing popularity of cycling has encouraged shops to offer bicycle repairs.","騎自行車越來越受歡迎，促使商家提供自行車維修服務。",""]],"l4-0816":[["形容詞：可攜式的","easily carried","We used a portable speaker to play music at the picnic.","我們在野餐時用可攜式喇叭播放音樂。",""]],"l4-0817":[["名詞：行李搬運員","無直接同義詞","A porter helped the family carry their heavy bags to the platform.","一位行李搬運員幫那家人把沉重的行李搬到月台。","porter 在此指替旅客搬運行李的人；baggage handler 通常指裝卸行李的工作人員。"]],"l4-0818":[["及物動詞：描繪；刻畫","depict / represent","The film portrays a small fishing village during a period of rapid change.","這部電影描繪了一座小漁村在快速變遷時期的樣貌。",""]],"l4-0819":[["及物動詞：具有","have","A good interpreter must possess excellent listening skills and cultural knowledge.","優秀的口譯員必須具備出色的聆聽技巧與文化知識。","possess 比 have 正式。"]],"l4-0820":[["名詞：個人財物","belongings","She packed her most valuable possessions in a small locked suitcase.","她把最貴重的個人物品裝進一只上鎖的小行李箱。","表示個人物品時常用複數 possessions。"]],"l4-0821":[["形容詞：精確的","exact / accurate","We need precise measurements before ordering glass for the window.","訂購窗戶玻璃前，我們需要精確的尺寸。",""]],"l4-0822":[["及物動詞：預測","forecast","Analysts predict that demand for electric buses will increase next year.","分析師預測，明年對電動公車的需求將會增加。",""]],"l4-0823":[["形容詞：較理想的；更可取的","better / more desirable","An early appointment is preferable because the clinic gets crowded after lunch.","較早的預約時段比較理想，因為診所午餐過後會變得擁擠。","比較兩個選項時用 preferable to，不用 preferable than。"]],"l4-0824":[["名詞：懷孕","無直接同義詞","During her pregnancy, she kept a journal to record her experiences.","懷孕期間，她用日記記錄自己的經歷。",""]],"l4-0825":[["形容詞：懷孕的","expecting","When she learned she was pregnant, she shared the news with her partner.","得知自己懷孕後，她把消息告訴了伴侶。","expecting 在此省略 a baby。"]],"l4-0826":[["名詞：介系詞","無直接同義詞","The exercise asks students to choose a preposition that fits each sentence.","這個練習要求學生選出適合每個句子的介系詞。",""]],"l4-0827":[["名詞：演出；呈現的作品","performance","The school's presentation of the musical attracted families from across the town.","學校演出的音樂劇吸引了鎮上各地的家庭前來觀賞。",""]],"l4-0828":[["名詞：保存；維護","conservation","The preservation of these old photographs requires careful control of humidity.","保存這些老照片需要仔細控制濕度。",""]],"l4-0829":[["及物動詞：保存；維護","protect / conserve","The restoration team worked carefully to preserve the painting's original colors.","修復團隊小心作業，以保存這幅畫原有的色彩。",""]],"l4-0830":[["名詞：預防","無直接同義詞","The workshop focused on fire prevention in restaurants with busy kitchens.","這場工作坊著重探討廚房繁忙的餐廳如何預防火災。",""]],"l4-0831":[["形容詞：主要的；首要的","main / chief","Cost was the prime reason the company chose a smaller office.","成本是這家公司選擇較小辦公室的主要原因。",""]],"l4-0832":[["形容詞：原始的；簡陋的","basic / rudimentary","The hikers built a primitive shelter from fallen branches and leaves.","健行者用掉落的樹枝和樹葉搭了一個簡陋的避難處。",""]],"l4-0833":[["名詞：隱私；不受打擾的狀態","無直接同義詞","She closed the office door to give the caller some privacy.","她關上辦公室的門，讓打電話的人有些私人空間。",""]],"l4-0834":[["名詞：特權","special right","Access to the private reading room is a privilege reserved for members.","使用這間私人閱覽室是會員專有的特權。",""]],"l4-0835":[["名詞：程序；步驟","process","Please follow the safety procedure before opening the machine's protective cover.","打開機器的防護罩前，請先依照安全程序操作。",""]],"l4-0836":[["不及物動詞：繼續進行","continue / go ahead","The builders cannot proceed until the inspector approves the revised plans.","檢查人員核准修改後的圖面前，施工人員無法繼續作業。",""]],"l4-0837":[["名詞：生產","manufacture","Production stopped for two hours while technicians repaired the damaged conveyor belt.","技術人員維修受損輸送帶期間，生產停了兩個小時。",""]],"l4-0838":[["形容詞：有生產力的；多產的","fruitful","The research team enjoyed a productive year and published several important studies.","這個研究團隊度過了成果豐碩的一年，發表了幾篇重要研究。",""]],"l4-0839":[["名詞：需要專業訓練的職業","無直接同義詞","She chose nursing as her profession because she wanted to care for patients.","她選擇護理作為自己的職業，因為她想照顧病人。","profession 強調需要專業訓練的職業；occupation 的範圍更廣。"]],"l4-0840":[["名詞：職業運動員","pro","After years of training, he became a professional and joined the national tennis tour.","經過多年訓練後，他成為職業選手，參加了全國網球巡迴賽。","pro 是 professional 的非正式說法；此例指職業運動員。"]],"l4-0841":[["名詞：教授","無直接同義詞","The professor invited students to discuss their research during office hours.","這位教授邀請學生在諮詢時間討論自己的研究。",""]],"l4-0842":[["形容詞：有利潤的","lucrative","The bakery became profitable after it started supplying bread to local hotels.","這家麵包店開始供應麵包給當地旅館後，便開始獲利。","lucrative 通常強調能賺很多錢。"]],"l4-0843":[["形容詞：知名的；重要的","leading / distinguished","Several prominent scientists signed a letter supporting the new research center.","幾位知名科學家聯名簽署了一封支持新研究中心的信。",""]],"l4-0844":[["形容詞：有前途的；大有希望的","encouraging","The first trial produced promising results, but further testing is needed.","第一次試驗得到了令人看好的結果，但仍需要進一步測試。",""]],"l4-0845":[["名詞：升遷","advancement","Her promotion to department manager came after years of consistent performance.","她多年來表現穩定，之後獲升任部門經理。",""]],"l4-0846":[["形容詞：迅速的；及時的","swift / quick","We appreciated the technician's prompt response when the office network failed.","辦公室網路故障時，我們很感謝技術人員的迅速回應。",""]],"l4-0847":[["及物動詞：促使","spur / motivate","Several customer complaints prompted the company to redesign its ordering system.","幾起客訴促使公司重新設計訂購系統。",""]],"l4-0848":[["名詞：代名詞","無直接同義詞","The editor replaced the repeated name with a pronoun to improve the sentence.","編輯把重複的人名改成代名詞，讓句子更流暢。",""]],"l4-0849":[["名詞：發音","無直接同義詞","Listening to the recording helped me improve my pronunciation of unfamiliar words.","聽這段錄音幫助我改善了不熟悉單字的發音。",""]],"l4-0850":[["不及物動詞：繁榮；成功發展","thrive / flourish","Small businesses began to prosper after the new station opened nearby.","附近的新車站啟用後，小型商家開始蓬勃發展。",""]],"l4-0851":[["名詞：繁榮；興盛","affluence","The town's prosperity depended largely on trade with neighboring coastal cities.","這個城鎮的繁榮主要仰賴與鄰近沿海城市的貿易。","affluence 強調富裕；prosperity 也包含經濟發展順利。"]],"l4-0852":[["形容詞：富裕的；繁榮的","wealthy / affluent","The once prosperous port declined after ships began using a deeper harbor.","船隻開始改用較深的港口後，這座曾經繁榮的港埠逐漸沒落。",""]],"l4-0853":[["名詞：蛋白質","無直接同義詞","The package lists the amount of protein in each serving of yogurt.","包裝上列出了每份優格的蛋白質含量。",""]],"l4-0854":[["不及物動詞：抗議","object","Residents gathered outside city hall to protest against the proposed road closure.","居民聚集在市政廳外，抗議擬議中的道路封閉措施。","protest against 對應 object to；介系詞不同。"]],"l4-0855":[["名詞：諺語","adage / saying","My grandmother often used a proverb to remind us to be patient.","我的祖母常用一句諺語提醒我們要有耐心。",""]],"l4-0856":[["形容詞：心理學的","無直接同義詞","The students discussed psychological theories about how children learn new skills.","學生們討論了有關兒童如何學習新技能的心理學理論。",""]],"l4-0857":[["名詞：心理學家","無直接同義詞","A psychologist observed how volunteers reacted to different types of background noise.","一位心理學家觀察志願參與者對不同背景噪音的反應。",""]],"l4-0858":[["名詞：心理學","無直接同義詞","She studied psychology to understand how memory affects people's everyday decisions.","她研讀心理學，以了解記憶如何影響人們日常的決定。",""]],"l4-0859":[["名詞：出版；發行","release","Publication of the report was delayed because several figures needed checking.","這份報告延後出版，因為其中幾個數字需要核對。",""]],"l4-0860":[["名詞：媒體關注；宣傳報導","media attention / coverage","The restaurant received unexpected publicity when a famous actor praised its noodles.","一位知名演員稱讚這家餐廳的麵食，讓餐廳意外受到媒體關注。",""]],"l4-0861":[["及物動詞：出版；刊登","print","The newspaper will publish the winning essays in its weekend edition.","報社將在週末版刊登得獎的文章。",""]],"l4-0862":[["名詞：出版商","publishing company","The publisher asked the author to revise the final chapter before printing.","出版商要求作者在印製前修改最後一章。",""]],"l4-0863":[["名詞：追求","quest","Her pursuit of a better education took her to three different countries.","為了追求更好的教育，她前往了三個不同的國家。",""]],"l4-0864":[["不及物動詞：顫抖；震動","shake / tremble","The floor began to quake as the heavy machinery started below us.","下方的重型機械啟動時，地板開始震動。",""]],"l4-0865":[["名詞：縫製的棉被","無直接同義詞","She covered the sleeping child with a quilt made by her grandmother.","她用祖母做的棉被蓋在熟睡的孩子身上。","quilt 指有填充物並縫合的被子，不等同一般 blanket。"]],"l4-0866":[["名詞：引文","quote","He opened his speech with a quotation from a nineteenth-century travel diary.","他在演說開頭引用了一段十九世紀旅行日記的文字。",""]],"l4-0867":[["名詞：盛怒","fury / anger","She struggled to control her rage when she discovered the deliberate deception.","她發現對方故意欺騙時，努力壓抑心中的怒火。","anger 強度較廣；rage 和 fury 表示強烈憤怒。"]],"l4-0868":[["名詞：降雨量","無直接同義詞","Rainfall this spring was lower than usual, leaving the reservoir nearly empty.","今年春天的降雨量比平常少，讓水庫幾乎見底。","此例指一段期間的降雨量；precipitation 也包含雪等其他降水。"]],"l4-0869":[["形容詞：切合實際的","practical / sensible","We need a realistic budget that includes maintenance and transportation costs.","我們需要一份符合實際情況的預算，把維護和運輸費用都算進去。",""]],"l4-0870":[["不及物動詞：反抗","revolt / rise up","The workers began to rebel against rules that denied them adequate rest.","工人開始反抗那些不讓他們充分休息的規定。","動詞 rebel 的重音在第二音節。"]],"l4-0871":[["及物動詞：回想起","remember / recollect","I clearly recall meeting her at a conference several years ago.","我清楚記得幾年前曾在一場會議上見過她。",""]],"l4-0872":[["名詞：招待會","無直接同義詞","Guests gathered in the garden for a reception after the wedding ceremony.","婚禮儀式結束後，賓客聚集在花園參加招待會。",""]],"l4-0873":[["名詞：食譜","無直接同義詞","The recipe calls for fresh ginger, but I only have powdered ginger.","這份食譜需要新鮮薑，但我只有薑粉。",""]],"l4-0874":[["及物動詞：背誦；朗誦","無直接同義詞","Each student recited a short poem without looking at the page.","每位學生都不看書頁，背誦了一首短詩。","recite 可指背誦或正式朗誦；此例由 without looking 表明是背誦。"]],"l4-0875":[["名詞：認可；肯定","acknowledgment","The award gave her recognition for years of work protecting local wetlands.","這個獎項肯定了她多年來保護當地濕地的努力。",""]],"l4-0876":[["名詞：康復","recuperation","His recovery was slow, so he postponed his return to work.","他的康復進展緩慢，因此延後了重返工作的時間。",""]],"l4-0877":[["名詞：休閒活動；消遣","leisure activities","The new community center offers space for exercise, recreation, and informal meetings.","新的社區中心提供運動、休閒活動和非正式聚會的空間。",""]],"l4-0878":[["及物動詞：回收再製","reprocess","The factory recycles used paper into packaging for locally made products.","這家工廠將廢紙回收再製，做成當地產品的包裝。","recycle 強調使廢棄材料再次可用；reprocess 強調重新加工。"]],"l4-0879":[["名詞：減少；削減","decrease / cut","The plan calls for a gradual reduction in the use of disposable cups.","這項計畫要求逐步減少免洗杯的使用。",""]],"l4-0880":[["及物動詞：轉介","direct","The doctor referred her to a specialist for a more detailed examination.","醫師將她轉介給專科醫師，以接受更詳細的檢查。","refer someone to someone 指把人轉介給另一位專業人士。"]],"l4-0881":[["名詞：提及","mention","The article makes no reference to the cost of maintaining the new bridge.","這篇文章完全沒有提到新橋的維護成本。",""]],"l4-0882":[["及物動詞：反射","mirror","The still water reflected the mountains and the pale morning sky.","平靜的水面映出了群山和淡淡的晨空。",""]],"l4-0883":[["名詞：深思；思考","consideration / contemplation","After careful reflection, she decided to accept the position in another city.","仔細思考後，她決定接受那份位於另一座城市的職位。",""]],"l4-0884":[["及物動詞：改革","overhaul","The committee proposed measures to reform the outdated school funding system.","委員會提出措施，改革過時的學校經費分配制度。","overhaul 通常強調全面檢討與大幅改善。"]],"l4-0885":[["及物動詞：使恢復精神","revive / reinvigorate","A short walk in the cool air refreshed us after the long meeting.","漫長的會議後，在涼爽的空氣中走了一小段路，讓我們恢復了精神。",""]],"l4-0886":[["名詞：難民","無直接同義詞","The organization helped refugees find temporary housing after they crossed the border.","難民越過邊境後，這個組織協助他們尋找臨時住所。",""]],"l4-0887":[["名詞：拒絕","無直接同義詞","His refusal to answer basic questions made the interview increasingly difficult.","他拒絕回答基本問題，讓訪談越來越難進行。","refusal to do something 指拒絕做某事；rejection 通常接受詞，不接這種 to 不定詞結構。"]],"l4-0888":[["介系詞：關於","concerning / about","Please contact the front desk regarding any changes to your reservation.","如果訂房內容有任何變更，請聯絡櫃台。",""]],"l4-0889":[["不及物動詞：登記；報名","sign up / enroll","You must register online before attending the free photography workshop.","參加這場免費攝影工作坊之前，你必須先上網報名。",""]],"l4-0890":[["名詞：報名；登記","enrollment","Registration for the evening language classes closes at the end of August.","夜間語言課程的報名將於八月底截止。",""]],"l4-0891":[["及物動詞：調節","control / adjust","This device regulates the temperature inside the greenhouse throughout the night.","這個裝置會整夜調節溫室內的溫度。",""]],"l4-0892":[["名詞：規章；規定","rule","The new regulation requires restaurants to display prices clearly on their menus.","新規定要求餐廳在菜單上清楚標示價格。",""]],"l4-0893":[["名詞：拒絕接受","refusal","The rejection of our proposal led us to reconsider the project's scope.","我們的提案遭到拒絕，這讓我們重新思考計畫的範圍。",""]],"l4-0894":[["名詞：親戚","family member / relation","A distant relative contacted me while researching our family's history.","一位遠親在研究我們的家族歷史時聯絡了我。",""]],"l4-0895":[["形容詞：相對的；比較而言的","comparative","The relative quiet of the countryside helped her concentrate on writing.","鄉間相對安靜的環境幫助她專心寫作。",""]],"l4-0896":[["名詞：放鬆；休息","rest","The hotel has a quiet garden designed for relaxation after a busy day.","這家旅館設有一座安靜的花園，讓人在忙碌一天後放鬆。",""]],"l4-0897":[["及物動詞：減輕；緩和","ease / alleviate","The extra staff helped relieve pressure on the busy customer service team.","增派的人手幫忙減輕了繁忙客服團隊的壓力。",""]],"l4-0898":[["形容詞：不情願的","unwilling / hesitant","He was reluctant to lend his camera to someone he barely knew.","他不太願意把相機借給一個幾乎不認識的人。",""]],"l4-0899":[["名詞：評論；說的話","comment / observation","Her thoughtful remark helped the group see the problem from another angle.","她那番經過思考的評論，幫助大家從另一個角度看待問題。",""]],"l4-0900":[["形容詞：非凡的；引人注目的","extraordinary / exceptional","The young violinist showed remarkable confidence during her first public performance.","這位年輕小提琴家首次公開演出時，展現了非凡的自信。",""]],"l4-0901":[["名詞：治療方法","treatment","The advertisement claimed the tea was a remedy for sleeplessness.","這則廣告宣稱，這種茶可以用來治療失眠。","此例轉述廣告的宣稱，未表示療效已獲證實。"]],"l4-0902":[["名詞：重複；反覆","repeating","Frequent repetition helped the dancers remember the complicated sequence of steps.","頻繁的反覆練習幫助舞者記住那一連串複雜的舞步。",""]],"l4-0903":[["名詞：描繪；呈現","depiction / portrayal","The painting offers a lively representation of a crowded nineteenth-century market.","這幅畫生動地呈現了一個擁擠的十九世紀市場。",""]],"l4-0904":[["名詞：名聲；聲譽","standing","The company built its reputation on reliable products and excellent customer service.","這家公司靠可靠的產品和優質的客戶服務建立了聲譽。",""]],"l4-0905":[["及物動詞：營救","save","Firefighters rescued two hikers who were trapped on a narrow mountain ledge.","消防員救出了兩名受困在山腰狹窄岩架上的健行者。",""]],"l4-0906":[["名詞：研究","investigation / study","Her research examines how urban trees affect temperatures in nearby buildings.","她的研究探討都市樹木如何影響附近建築物內的溫度。",""]],"l4-0907":[["名詞：研究人員","investigator","The researcher interviewed dozens of residents before drawing conclusions about the neighborhood.","這位研究人員訪問了數十位居民，才對這個社區作出結論。",""]],"l4-0908":[["及物動詞：與……相像","look like / be similar to","The leaves of this plant resemble small hearts with pointed tips.","這種植物的葉子像一顆顆帶有尖端的小愛心。","resemble 直接接受詞，不加 to。"]],"l4-0909":[["名詞：預訂","booking","I called the restaurant to change our reservation from six to eight people.","我打電話給餐廳，把訂位人數從六人改成八人。",""]],"l4-0910":[["不及物動詞：辭職","step down / quit","The director decided to resign after accepting a position at another organization.","這位主管接受另一個組織的職位後，決定辭職。",""]],"l4-0911":[["名詞：辭職信；辭呈","letter of resignation","She submitted her resignation and agreed to help train her replacement.","她遞交了辭呈，並同意協助訓練接替她的人。",""]],"l4-0912":[["名詞：反對；抵制","opposition","The proposal met strong resistance from residents concerned about traffic noise.","這項提案遭到擔心交通噪音的居民強烈反對。",""]],"l4-0913":[["名詞：正式決議","formal decision","The council passed a resolution supporting the restoration of the old theater.","議會通過了一項決議，支持修復那座老劇院。",""]],"l4-0914":[["及物動詞：解決","settle / sort out","A short meeting helped the two teams resolve their disagreement about scheduling.","一場簡短的會議幫助兩個團隊解決了時程安排上的歧見。",""]],"l4-0915":[["形容詞：值得尊敬的；正派的","reputable / honorable","They wanted a respectable employer who treated workers fairly and paid them promptly.","他們想找一位正派的雇主，公平對待員工並準時付薪。",""]],"l4-0916":[["形容詞：表示尊敬的","courteous / deferential","The students remained respectful even when they disagreed with the visiting speaker.","即使不認同來賓講者的看法，學生們仍保持尊重的態度。","deferential 更強調順從或禮讓對方的判斷。"]],"l4-0917":[["及物動詞：修復；使恢復原貌","renovate","Craftspeople restored the damaged ceiling using photographs of the original design.","工匠參考原始設計的照片，修復了受損的天花板。","restore 強調恢復原貌；renovate 側重整修改善。"]],"l4-0918":[["名詞：限制","limitation / constraint","Water restrictions prevented residents from filling their swimming pools during the drought.","乾旱期間的用水限制使居民無法把自家泳池注滿水。",""]],"l4-0919":[["及物動詞：保留；留存","keep","Please retain your receipt in case you need to exchange the jacket.","請保留收據，以備需要更換這件外套時使用。","retain 比 keep 正式。"]],"l4-0920":[["不及物動詞：退休","stop working permanently","My aunt plans to retire next spring and spend more time painting.","我的阿姨計畫明年春天退休，把更多時間用來畫畫。",""]],"l4-0921":[["名詞：退休生活","無直接同義詞","During retirement, he volunteers at the library and repairs bicycles for neighbors.","退休後，他在圖書館當志工，也替鄰居修理自行車。",""]],"l4-0922":[["名詞：撤退","withdrawal","The commander ordered a retreat when supplies could no longer reach the troops.","補給無法再送達部隊時，指揮官下令撤退。",""]],"l4-0923":[["名詞：重聚；團聚","無直接同義詞","Our family reunion brought together relatives who had not met for decades.","這次家族聚會讓幾十年沒見面的親戚重新相聚。",""]],"l4-0924":[["及物動詞：為……報仇","avenge","In the novel, the soldier vows to revenge his brother's death.","在這本小說中，這名士兵發誓要為兄弟的死報仇。","revenge 作動詞較正式且少見；一般更常說 avenge his brother's death。"]],"l4-0925":[["及物動詞：修訂","amend / rework","The architect revised the plans after the client requested a larger kitchen.","客戶要求加大廚房後，建築師修改了設計圖。",""]],"l4-0926":[["名詞：修改；修訂內容","amendment / change","The latest revision adds clearer instructions for assembling the wooden shelves.","最新的修訂加入了更清楚的木製層架組裝說明。",""]],"l4-0927":[["名詞：革命","無直接同義詞","The exhibition traces the political changes that followed the revolution.","這場展覽追溯了革命之後的政治變化。",""]],"l4-0928":[["形容詞：帶來重大變革的","groundbreaking / radical","The invention introduced a revolutionary way to send messages across long distances.","這項發明帶來了遠距離傳送訊息的革命性方式。",""]],"l4-0929":[["及物動詞：獎勵；酬謝","recompense","The owner rewarded the boy for returning the missing wallet.","失主獎勵了那名歸還遺失皮夾的男孩。","recompense 較正式，可指以金錢或其他方式酬謝。"]],"l4-0930":[["名詞：押韻的字詞","rhyming word","The poet searched for a rhyme that would fit the final line.","詩人尋找一個能放進最後一行的押韻字詞。",""]],"l4-0931":[["名詞：節奏","beat","The drummer changed the rhythm as the dancers moved into a faster section.","舞者進入較快的段落時，鼓手改變了節奏。","beat 偏重規律的拍點；rhythm 指節拍組成的整體模式。"]],"l4-0932":[["名詞：愛情小說","romantic novel / love story","She borrowed a romance set in a small seaside town.","她借了一本以海邊小鎮為背景的愛情小說。",""]],"l4-0933":[["副詞：大約","approximately / about","The repairs will take roughly three days if all the parts arrive on time.","如果所有零件準時送達，維修大約需要三天。",""]],"l4-0934":[["名詞：路線","course / path","The driver chose a different route to avoid the roadworks near the bridge.","司機選擇了另一條路線，避開橋邊的道路工程。",""]],"l4-0935":[["名詞：廢墟；遺跡","remains","Wildflowers now grow among the ruins of the abandoned stone village.","那座遭廢棄的石造村落如今已成廢墟，野花在其中生長。","建築物的廢墟常用複數 ruins。"]],"l4-0936":[["形容詞：鄉村的","無直接同義詞","The program brings mobile libraries to rural communities far from large towns.","這項計畫把行動圖書館帶進遠離大城鎮的鄉村社區。",""]],"l4-0937":[["名詞：犧牲；捨棄珍惜事物的行為","無直接同義詞","Moving away from close friends was a difficult sacrifice for her career.","為了事業而搬離親近的朋友，對她而言是一項艱難的犧牲。",""]],"l4-0938":[["名詞：固定薪資","fixed regular pay","The position offers a competitive salary and three weeks of paid vacation.","這個職位提供具競爭力的薪資和三週有薪假。",""]],"l4-0939":[["名詞：銷售人員","sales representative / sales assistant","The salesperson explained the differences between the two washing machines.","銷售人員解釋了這兩臺洗衣機的差異。",""]],"l4-0940":[["名詞：女性售貨員","無直接同義詞","The saleswoman found a smaller pair of shoes in the stockroom.","這位女店員在庫房找到了一雙尺寸較小的鞋。","現今常用不限定性別的 salesperson 或 sales assistant。"]],"l4-0941":[["名詞：人造衛星","無直接同義詞","The satellite sends images of cloud patterns to weather stations on Earth.","這顆人造衛星把雲層分布影像傳送到地球上的氣象站。",""]],"l4-0942":[["名詞：滿足感","contentment","She felt great satisfaction after finishing the difficult restoration project.","完成這項艱難的修復工程後，她感到非常滿足。",""]],"l4-0943":[["副詞：幾乎不","hardly / barely","We could scarcely hear the announcement over the noise of the crowd.","人群的吵雜聲讓我們幾乎聽不見廣播。",""]],"l4-0944":[["名詞：風景","landscape","We stopped beside the lake to admire the scenery and take photographs.","我們在湖邊停下來欣賞風景、拍照。","scenery 不可數；landscape 指一片景觀時可數。"]],"l4-0945":[["及物動詞：責罵","reprimand / tell off","The coach scolded the players for leaving their equipment on the wet field.","教練責罵球員把裝備留在濕漉漉的球場上。",""]],"l4-0946":[["及物動詞：刮傷","scrape","Be careful not to scratch the wooden table when moving the metal lamp.","移動金屬檯燈時，小心別刮傷木桌。","scratch 通常留下細痕；scrape 可造成較大範圍的擦損。"]],"l4-0947":[["名詞：螺絲起子","無直接同義詞","He used a small screwdriver to tighten the handle on the cupboard door.","他用一把小螺絲起子鎖緊櫥櫃門上的把手。",""]],"l4-0948":[["名詞：雕塑作品","無直接同義詞","A bronze sculpture of a running horse stands outside the museum.","博物館外立著一座奔馬銅雕。",""]],"l4-0949":[["名詞：海鷗","gull","A seagull landed on the railing and watched the fishermen unload their catch.","一隻海鷗停在欄杆上，看著漁民卸下漁獲。",""]],"l4-0950":[["形容詞：資深的；職位較高的","higher-ranking","A senior engineer reviewed the design before the team began construction.","團隊開始施工前，一位資深工程師審查了設計。",""]],"l4-0951":[["名詞：移居者；定居者","無直接同義詞","The diary describes how the settlers built homes beside the river.","這本日記描述了移居者如何在河邊建造家園。",""]],"l4-0952":[["形容詞：嚴重的；劇烈的","intense","Severe storms damaged several buildings and interrupted train services across the region.","猛烈的暴風雨損壞了幾棟建築物，並使這個地區的火車服務中斷。",""]],"l4-0953":[["形容詞：可恥的","disgraceful / dishonorable","The report exposed the shameful treatment of workers at the remote factory.","這份報告揭露了那座偏遠工廠對待員工的可恥方式。",""]],"l4-0954":[["名詞：電動刮鬍刀","electric razor","He packed his shaver and toothbrush before leaving for the business trip.","他出發去出差前，把電動刮鬍刀和牙刷裝進行李。",""]],"l4-0955":[["名詞：避難處；遮蔽處","refuge","We found shelter beneath a stone arch when the rain grew heavier.","雨勢變大時，我們在一道石拱門下找到避雨處。",""]],"l4-0956":[["及物動詞：轉移","move / redirect","The discussion shifted our attention from short-term costs to future benefits.","這場討論把我們的注意力從短期成本轉向未來的效益。",""]],"l4-0957":[["形容詞：近視的","nearsighted / myopic","Being shortsighted, she needed her glasses to read the departure board.","她有近視，需要戴眼鏡才能看清出發資訊看板。","shortsighted 常見於英式英語；nearsighted 常見於美式英語。"]],"l4-0958":[["不及物動詞：聳肩","無直接同義詞","He shrugged when I asked why the meeting had been canceled.","我問他會議為何取消時，他聳了聳肩。",""]],"l4-0959":[["名詞：往返接駁車","shuttle bus","A free shuttle runs between the airport terminal and the nearby parking lots.","免費接駁車往返於機場航廈與附近的停車場。",""]],"l4-0960":[["名詞：觀光；遊覽","touring","We set aside one afternoon for sightseeing before the conference began.","會議開始前，我們留出一個下午去觀光。",""]],"l4-0961":[["名詞：簽名","無直接同義詞","The delivery driver requested my signature before handing over the package.","送貨司機把包裹交給我之前，請我簽名。",""]],"l4-0962":[["名詞：重要性","importance","The discovery's historical significance became clear after experts examined the inscription.","專家檢視銘文後，這項發現的歷史重要性變得明確。",""]],"l4-0963":[["名詞：真誠；誠意","genuineness / earnestness","Her willingness to correct the mistake convinced us of her sincerity.","她願意改正錯誤，讓我們相信了她的誠意。",""]],"l4-0964":[["形容詞：文法上的單數的","無直接同義詞","The teacher circled the singular noun and asked us to change it.","老師圈出那個單數名詞，要我們把它改掉。",""]],"l4-0965":[["名詞：地點；場所","location","Engineers inspected the proposed site before approving construction of the new hospital.","工程師檢查預定地後，才核准新醫院的興建。",""]],"l4-0966":[["及物動詞：速寫；畫草圖","draw roughly","The designer sketched several possible layouts on the back of an envelope.","設計師在信封背面畫出了幾種可能配置的草圖。",""]],"l4-0967":[["名詞：雪橇","sled","The children pulled their sledge up the snowy hill for another ride.","孩子們把雪橇拉上雪坡，準備再滑一次。","sledge 常見於英式英語；sled 常見於美式英語。"]],"l4-0968":[["名詞：馬拉雪橇","無直接同義詞","Two horses pulled the sleigh through the snow-covered streets of the village.","兩匹馬拉著雪橇，穿過村裡覆滿白雪的街道。","sleigh 常指大型、由馬等牲畜拉動的雪橇。"]],"l4-0969":[["形容詞：輕微的；小幅的","small / minor","There was a slight delay while the flight crew checked one of the doors.","機組人員檢查其中一扇門時，航班稍微延誤了。",""]],"l4-0970":[["名詞：口號；標語","catchphrase","The campaign's slogan appeared on posters throughout the city's train stations.","這場宣傳活動的標語出現在市內各火車站的海報上。",""]],"l4-0971":[["名詞：霧霾；汙染煙霧","無直接同義詞","A thick layer of smog hid the mountains beyond the city.","一層濃厚的霧霾遮住了城市遠方的山。","smog 指受汙染的霧霾，不等同一般 fog。"]],"l4-0972":[["不及物動詞：打噴嚏","無直接同義詞","The dust made me sneeze as I opened the old cardboard box.","我打開那個舊紙箱時，灰塵讓我打了噴嚏。",""]],"l4-0973":[["不及物動詞：啜泣","weep","The child began to sob after discovering that his favorite toy was broken.","那個孩子發現心愛的玩具壞了，便啜泣起來。","sob 強調抽噎出聲；weep 不一定出聲。"]],"l4-0974":[["名詞：電源插座","outlet / power point","The desk has a socket underneath for charging phones and laptops.","這張書桌下方有一個插座，可以為手機和筆電充電。","outlet 常見於美式英語；power point 常見於英式英語。"]],"l4-0975":[["名詞：電腦軟體","無直接同義詞","The new software helps the warehouse track orders and update stock levels.","這套新軟體協助倉庫追蹤訂單並更新庫存數量。","software 是不可數名詞。"]],"l4-0976":[["形容詞：太陽的；太陽能的","無直接同義詞","Solar panels on the roof provide electricity for the community center.","屋頂上的太陽能板為社區中心供電。",""]],"l4-0977":[["名詞：高中或大學二年級學生","second-year student","As a college sophomore, she began volunteering at a local legal aid office.","大學二年級時，她開始在當地的法律扶助辦公室當志工。","sophomore 主要用於美國學制。"]],"l4-0978":[["形容詞：悲傷的","sad / mournful","He gave us a sorrowful smile as the train pulled away.","火車駛離時，他對我們露出一個悲傷的微笑。",""]],"l4-0979":[["名詞：紀念品","memento / keepsake","I bought a small ceramic bowl as a souvenir of our island trip.","我買了一只小陶碗，作為這趟海島旅行的紀念。",""]],"l4-0980":[["及物動詞：抽出；騰出","set aside","Could you spare ten minutes to review this letter before I send it?","你能抽出十分鐘，在我寄出這封信前幫忙看一下嗎？",""]],"l4-0981":[["名詞：火花","無直接同義詞","A spark flew from the fireplace and landed on the stone floor.","一點火花從壁爐飛出，落在石頭地板上。",""]],"l4-0982":[["名詞：閃光；閃耀","glitter / shimmer","The sparkle of sunlight on the water caught the photographer's attention.","陽光在水面上閃耀的光芒吸引了攝影師的注意。",""]],"l4-0983":[["名詞：麻雀","無直接同義詞","A sparrow carried a piece of dry grass into the hedge.","一隻麻雀把一根乾草叼進樹籬裡。",""]],"l4-0984":[["名詞：矛","無直接同義詞","The painting shows a soldier holding a spear beside the castle gate.","這幅畫描繪一名士兵持矛站在城堡大門旁。","lance 通常指騎兵使用的長矛。"]],"l4-0985":[["名詞：物種","無直接同義詞","Several rare species of orchid grow in this protected mountain forest.","這片受保護的山林生長著幾種稀有的蘭花。","species 的單複數同形。"]],"l4-0986":[["形容詞：辛辣的","hot / fiery","The soup was too spicy for me, so I ordered something milder.","這碗湯對我來說太辣了，所以我改點了口味較溫和的餐點。","此例 spicy 指辣味；也可泛指添加香料的。"]],"l4-0987":[["形容詞：心靈的；精神層面的","無直接同義詞","The retreat offered time for quiet reflection and spiritual growth.","這次靜修提供了安靜省思與心靈成長的時間。",""]],"l4-0988":[["形容詞：極好的；壯麗的","magnificent / wonderful","The hilltop restaurant offers a splendid view of the entire bay.","山頂的餐廳可以欣賞到整個海灣的壯麗景色。",""]],"l4-0989":[["及物動詞：劈開","cleave","He split the thick log with an axe before stacking the firewood.","他用斧頭把粗木段劈開，再把柴火堆好。",""]],"l4-0990":[["名詞：男性運動員","male athlete","The award honors a sportsman who has supported youth athletics for many years.","這個獎項表揚了一位多年來支持青少年體育的男性運動員。","sportsman 指男性運動員或喜愛運動的男性；本句採運動員義。"]],"l4-0991":[["名詞：運動家精神","fair play","The coach praised her sportsmanship after she helped an injured opponent.","她幫助一名受傷的對手後，教練稱讚她的運動家精神。",""]],"l4-0992":[["名詞：狀態；進度情況","state","You can check the status of your application through the online portal.","你可以透過線上入口查詢申請的處理狀態。",""]],"l4-0993":[["名詞：植物的莖","stalk","The gardener tied the tall stem to a stake for support.","園丁把高高的莖綁在支柱上，讓它有所支撐。",""]],"l4-0994":[["形容詞：吝嗇的","mean / miserly","The owner was too stingy to replace the office's broken chairs.","老闆太吝嗇，捨不得更換辦公室裡的壞椅子。","mean 表示吝嗇較常見於英式英語。"]],"l4-0995":[["及物動詞：加強；鞏固","reinforce / fortify","The builders strengthened the old wall with steel supports before removing the roof.","施工人員拆除屋頂前，先用鋼製支架加固了舊牆。",""]],"l4-0996":[["不及物動詞：努力；奮鬥","endeavor / work hard","The team strives to provide clear answers to every customer's question.","這個團隊努力為每位顧客的問題提供清楚的回答。",""]],"l4-0997":[["名詞：寫字或繪畫的一筆","無直接同義詞","The artist added one final stroke of blue to the painting.","畫家在畫上添了最後一筆藍色。",""]],"l4-0998":[["及物動詞：輕撫","caress","She gently stroked the cat's back while it slept beside her.","貓睡在她身旁時，她輕輕撫摸牠的背。",""]],"l4-0999":[["名詞：潛水艇","sub","The submarine remained beneath the surface while the storm passed overhead.","暴風雨從上方經過時，潛水艇一直停留在水面下。","sub 是 submarine 的非正式簡稱。"]],"l4-1000":[["名詞：建議；提議","proposal / recommendation","Your suggestion to move the meeting online saved everyone a long journey.","你提議把會議改到線上進行，讓大家省去了一趟長途旅程。",""]],"l4-1001":[["及物動詞：概述；總結","sum up / outline","At the end of the meeting, the chair summarized the main decisions.","會議結束時，主席概述了主要決議。",""]],"l4-1002":[["不及物動詞：衝浪","無直接同義詞","They learned to surf at a beach known for its gentle waves.","他們在一處以浪勢平緩聞名的海灘學習衝浪。",""]],"l4-1003":[["名詞：外科醫師","無直接同義詞","The surgeon explained the operation and answered the family's questions.","外科醫師說明了手術內容，並回答家人的問題。",""]],"l4-1004":[["名詞：外科手術","operation","She needed surgery after an accident injured her left knee.","一次意外傷及左膝後，她需要接受手術。","surgery 指手術時通常不可數；operation 指一次手術時可數。"]],"l4-1005":[["不及物動詞：投降","give in / yield","The soldiers agreed to surrender when they realized they were surrounded.","士兵發現自己已被包圍後，同意投降。",""]],"l4-1006":[["名詞：周遭環境","environment","The child slowly became familiar with the surroundings of her new home.","這個孩子慢慢熟悉了新家周遭的環境。","此義 surroundings 用複數形式。"]],"l4-1007":[["形容詞：感到懷疑的","distrustful / wary","The unusually low price made us suspicious of the seller's claims.","異常低廉的價格讓我們對賣家的說法起了疑心。",""]],"l4-1008":[["不及物動詞：搖擺","swing / rock","The hanging lamps swayed gently whenever a breeze entered the open window.","每當微風吹進開著的窗戶，吊燈就會輕輕搖晃。",""]],"l4-1009":[["名詞：音節","無直接同義詞","The children clapped once for each syllable as they said their names.","孩子們說出自己的名字時，每念一個音節就拍一下手。",""]],"l4-1010":[["形容詞：有同情心的；體諒的","understanding / compassionate","Her manager was sympathetic when she explained why she needed time off.","她說明需要請假的原因時，主管表示體諒。",""]],"l4-1011":[["名詞：同情；同情心","compassion","The neighbors expressed their sympathy after the family lost their home in a fire.","這家人在火災中失去家園後，鄰居紛紛表達同情。",""]],"l4-1012":[["名詞：交響曲","無直接同義詞","The orchestra rehearsed the final movement of the symphony before the concert.","音樂會前，管弦樂團排練了那首交響曲的最後一個樂章。",""]],"l4-1013":[["名詞：糖漿","無直接同義詞","She poured a little maple syrup over the warm pancakes.","她在溫熱的鬆餅上淋了一點楓糖漿。",""]],"l4-1014":[["形容詞：有系統的；有條理的","methodical / organized","A systematic search of the records revealed several errors in the dates.","有系統地查閱紀錄後，發現了幾處日期錯誤。",""]],"l4-1015":[["名詞：水龍頭","faucet","The tap in the kitchen kept dripping until we replaced the washer.","廚房的水龍頭一直滴水，直到我們換掉墊圈才停。","tap 常見於英式英語；faucet 常見於美式英語。"]],"l4-1016":[["及物動詞：輕敲","無直接同義詞","She tapped the microphone gently to check whether it was working.","她輕敲麥克風，確認它是否正常運作。","tap 強調輕輕且短促地碰擊。"]],"l4-1017":[["名詞：技術人員","tech","A technician checked the cables before replacing the damaged network switch.","技術人員先檢查纜線，再更換受損的網路交換器。","tech 是 technician 的非正式簡稱。"]],"l4-1018":[["形容詞：科技的；技術的","無直接同義詞","Technological advances have changed how the factory monitors the quality of its products.","科技進步改變了這家工廠監控產品品質的方式。",""]],"l4-1019":[["名詞：電報訊息","cable / wire","The telegram informed the family that their son had arrived safely.","這封電報通知家人，他們的兒子已平安抵達。","cable、wire 可指電報訊息，現多見於歷史語境。"]],"l4-1020":[["名詞：電報通信系統","無直接同義詞","The telegraph allowed news to travel much faster than letters carried by horse.","電報讓消息傳遞的速度遠超過由馬匹運送的信件。","telegraph 通常指通信系統或裝置；一封電報訊息是 telegram。"]],"l4-1021":[["名詞：望遠鏡","無直接同義詞","Through the telescope, we could see several bright moons beside the planet.","透過望遠鏡，我們可以看見那顆行星旁幾顆明亮的衛星。",""]],"l4-1022":[["名詞：傾向；習性","inclination / propensity","He has a tendency to speak too quickly when he feels nervous.","他緊張時往往會說話太快。",""]],"l4-1023":[["形容詞：緊繃的","taut / tight","Her shoulders were tense after hours of working at the computer.","在電腦前工作數小時後，她的肩膀很緊繃。",""]],"l4-1024":[["名詞：緊張；精神壓力","stress / strain","The long silence increased the tension as everyone waited for the announcement.","大家等待宣布消息時，長時間的沉默讓氣氛更加緊張。",""]],"l4-1025":[["及物動詞：使非常害怕","frighten / scare","The sudden roar of thunder terrified the dog, which hid beneath the bed.","突如其來的雷聲把狗嚇壞了，牠躲到床底下。","terrify 比 frighten、scare 更強烈。"]],"l4-1026":[["名詞：恐懼；驚駭","horror","She froze in terror when she saw the car sliding toward her.","她看見汽車滑向自己時，嚇得動彈不得。",""]],"l4-1027":[["名詞：主題","central idea","The theme of belonging connects the different stories in this collection.","歸屬感這個主題串聯起這本選集中的不同故事。",""]],"l4-1028":[["形容詞：徹底的；仔細全面的","comprehensive / meticulous","The mechanic performed a thorough inspection before approving the bus for service.","技師進行了徹底檢查後，才准許這輛公車投入服務。",""]],"l4-1029":[["形容詞：體貼的","considerate / kind","It was thoughtful of you to bring dinner while I was moving house.","我搬家時，你送晚餐過來，真是體貼。",""]],"l4-1030":[["形容詞：膽小的；怯生的","shy / nervous","The timid puppy stayed close to its owner in the crowded park.","在擁擠的公園裡，那隻膽小的小狗一直緊靠著主人。",""]],"l4-1031":[["形容詞：令人厭煩的","tedious / wearisome","Filling out the same information on several forms became a tiresome task.","在好幾份表格上填寫相同資料，成了一件令人厭煩的工作。",""]],"l4-1032":[["形容詞：可以忍受的","bearable / endurable","With the windows open, the afternoon heat became more tolerable.","打開窗戶後，午後的炎熱變得比較能忍受。",""]],"l4-1033":[["名詞：寬容；包容","open-mindedness / acceptance","The school encourages tolerance toward classmates with different beliefs and backgrounds.","學校鼓勵學生包容信仰與背景不同的同學。",""]],"l4-1034":[["及物動詞：容忍；忍受","put up with / endure","The landlord will not tolerate loud parties that disturb other tenants.","房東不會容忍吵鬧的派對打擾其他房客。",""]],"l4-1035":[["形容詞：寬容的；能接受差異的","open-minded / accepting","She is tolerant of different opinions and welcomes respectful debate.","她能包容不同意見，也歡迎彼此尊重的辯論。",""]],"l4-1036":[["名詞：墓；墓穴","sepulcher","Archaeologists found painted pottery inside the ancient tomb near the river.","考古學家在河邊的古墓裡發現了彩陶。","sepulcher 是較正式、文學性的用字；英式拼寫為 sepulchre。"]],"l4-1037":[["形容詞：困難的；費力的","difficult / demanding","Finding affordable housing near the station proved to be a tough challenge.","要在車站附近找到負擔得起的住處，事實證明是一項艱難的挑戰。",""]],"l4-1038":[["名詞：悲劇作品","tragic drama","The theater company performed a tragedy about a ruler who loses his kingdom.","這個劇團演出了一齣統治者失去王國的悲劇。",""]],"l4-1039":[["形容詞：悲慘的","heartbreaking / disastrous","The tragic accident changed the lives of everyone in the small community.","那場悲慘的事故改變了這個小社區裡每個人的生活。",""]],"l4-1040":[["不及物動詞：轉乘","change","We need to transfer to a local train at the next station.","我們需要在下一站轉乘區間車。",""]],"l4-1041":[["及物動詞：使徹底改觀","change / convert","The renovation transformed the empty warehouse into a bright community theater.","這次整修把空倉庫改造成一座明亮的社區劇院。","transform 強調顯著改變；change 的改變程度較廣。"]],"l4-1042":[["及物動詞：翻譯","render","She translated the instructions into Spanish so her grandparents could understand them.","她把說明翻成西班牙文，讓祖父母能看懂。","render ... into ... 表示譯成某語言，較正式。"]],"l4-1043":[["名詞：譯本；譯文","rendering / translated version","This translation preserves the humor of the original without sounding unnatural.","這個譯本保留了原作的幽默，讀起來也不生硬。",""]],"l4-1044":[["名詞：譯者；筆譯員","無直接同義詞","The translator asked the author to clarify an ambiguous sentence.","譯者請作者說明一句意思不清楚的句子。","translator 常指筆譯者；口譯者通常稱 interpreter。"]],"l4-1045":[["名詞：交通運輸","transport","Reliable public transportation makes it easier for residents to reach the hospital.","可靠的大眾運輸讓居民前往醫院更方便。","transportation 常見於美式英語；transport 常見於英式英語。"]],"l4-1046":[["形容詞：極大的","enormous / immense","The volunteers put tremendous effort into restoring the storm-damaged community garden.","志工投入了極大的心力，修復遭風暴破壞的社區花園。",""]],"l4-1047":[["形容詞：部落的","無直接同義詞","Tribal leaders met to discuss how the new road would affect their land.","部落領袖聚在一起，討論新道路會如何影響他們的土地。","tribal 是形容詞，原稿附的 [C] 可數標記不適用。"]],"l4-1048":[["名詞：重大成功；勝利","victory / success","Completing the bridge ahead of schedule was a triumph for the engineering team.","提前完成橋梁工程，是工程團隊的一大成就。",""]],"l4-1049":[["形容詞：麻煩的；難處理的","problematic / difficult","A troublesome leak forced the restaurant to close its kitchen for repairs.","一處難處理的漏水迫使餐廳關閉廚房進行維修。",""]],"l4-1050":[["名詞：拔河比賽","無直接同義詞","The two classes competed in a tug-of-war during the school sports day.","學校運動會當天，這兩個班進行了一場拔河比賽。",""]],"l4-1051":[["不及物動詞：閃爍","sparkle / glimmer","Tiny lights twinkled along the garden path after the sun went down.","太陽下山後，小燈沿著花園步道閃爍。",""]],"l4-1052":[["名詞：打字員","無直接同義詞","The typist checked the handwritten notes before preparing a clean copy.","打字員先核對手寫筆記，再打出一份整潔的文件。",""]],"l4-1053":[["名詞：地下通道","subway","Pedestrians can use the underpass to reach the station without crossing the busy road.","行人可以走地下道到車站，不必穿越繁忙的馬路。","subway 在英式英語中可指行人地下道；美式英語中通常指地鐵。"]],"l4-1054":[["形容詞：獨一無二的","one-of-a-kind","Each handmade bowl has a unique pattern created during the firing process.","每只手工碗都有在燒製過程中形成的獨特花紋。",""]],"l4-1055":[["形容詞：普遍適用的；全體共有的","unanimous","The proposal received universal support from all members of the committee.","這項提案獲得了委員會全體成員的一致支持。","universal 在此涵蓋全體成員；unanimous 強調意見一致。"]],"l4-1056":[["名詞：大學","無直接同義詞","The university offers evening courses for adults who work during the day.","這所大學為白天工作的成人提供夜間課程。",""]],"l4-1057":[["及物動詞：上傳","無直接同義詞","Please upload a clear copy of your certificate with the application form.","請連同申請表一起上傳一份清楚的證書副本。",""]],"l4-1058":[["形容詞：城市的","無直接同義詞","The study compares air quality in urban areas and nearby villages.","這項研究比較了都市地區和附近村莊的空氣品質。",""]],"l4-1059":[["及物動詞：力勸；敦促","encourage / press","The guide urged us to leave early before the trail became crowded.","嚮導力勸我們提早出發，趕在步道擁擠之前離開。","urge 比 encourage 更有急切、強烈勸說的意味。"]],"l4-1060":[["形容詞：緊急的；迫切的","pressing","The damaged roof needs urgent repairs before the next heavy rain.","下次大雨來臨前，受損的屋頂急需修繕。",""]],"l4-1061":[["名詞：使用；使用量","use / consumption","The new meters help residents monitor their daily water usage.","新的水表幫助居民監測每天的用水量。",""]],"l4-1062":[["形容詞：徒勞的","futile / fruitless","They made a vain attempt to restart the engine without replacing the battery.","他們沒換電池就試圖重新發動引擎，結果徒勞無功。",""]],"l4-1063":[["形容詞：廣大的；遼闊的","immense / extensive","A vast plain stretched beyond the hills as far as we could see.","丘陵後方是一片遼闊的平原，延伸到目光所及的遠處。",""]],"l4-1064":[["名詞：素食者","無直接同義詞","As a vegetarian, she asked whether the soup contained any meat stock.","她是素食者，因此詢問湯裡是否含有肉類高湯。",""]],"l4-1065":[["名詞：動詞","無直接同義詞","Underline the verb that tells us what happened in each sentence.","請在每個句子中表示發生何事的動詞下畫線。",""]],"l4-1066":[["副詞：非常；很","extremely","The instructions were very clear, so we assembled the desk without any difficulty.","說明非常清楚，所以我們很順利就組好了書桌。",""]],"l4-1067":[["名詞：船艦","ship / boat","The rescue vessel approached slowly because rocks lay just beneath the surface.","救援船緩緩接近，因為水面下不深處就有礁石。",""]],"l4-1068":[["名詞：醋","無直接同義詞","Add a little vinegar to the dressing, then taste it before serving.","在沙拉醬裡加一點醋，上桌前再嚐嚐味道。",""]],"l4-1069":[["及物動詞：違反","breach / break","The company violated the agreement by sharing the client's confidential information.","這家公司洩露了客戶的機密資訊，因而違反協議。",""]],"l4-1070":[["名詞：違反行為","breach / infringement","Parking in the emergency lane is a violation of the building's safety rules.","把車停在緊急通道上，違反了這棟大樓的安全規定。",""]],"l4-1071":[["名詞：未曾有過性行為的人；此例指處女","無直接同義詞","She rejected the assumption that every unmarried woman was a virgin.","她不接受每個未婚女性都是處女這種假設。","virgin 不等同未婚者，且不限女性；原稿的未婚女子不能當成等義解釋。"]],"l4-1072":[["名詞：美德","moral quality","The story presents honesty as a virtue worth preserving under difficult circumstances.","這個故事把誠實呈現為一種即使處境艱難也值得堅守的美德。","此例 a virtue 指一項美德，而非不可數的整體善良品德。"]],"l4-1073":[["名詞：病毒","無直接同義詞","The laboratory developed a test to detect the virus in water samples.","這間實驗室研發了一種檢測方法，用來偵測水樣中的病毒。",""]],"l4-1074":[["形容詞：視覺的","無直接同義詞","The guide used visual aids to explain how the old printing press worked.","導覽員利用視覺輔助教材，解釋這臺老印刷機的運作方式。",""]],"l4-1075":[["形容詞：維持生命所必需的","essential / indispensable","Clean water is vital to the survival of every community.","乾淨的水對每個社區的生存都不可或缺。",""]],"l4-1076":[["名詞：火山","無直接同義詞","The volcano released a cloud of ash that darkened the nearby villages.","火山噴出一團火山灰，讓附近村莊的天色變暗。",""]],"l4-1077":[["形容詞：自願的；非強制的","optional","Participation in the weekend cleanup is voluntary, but all residents are welcome.","週末清掃活動採自願參加，歡迎所有居民加入。","voluntary 強調出於自願；optional 強調可以選擇不參加。"]],"l4-1078":[["名詞：志工；志願服務者","無直接同義詞","A volunteer showed visitors how to find books in the children's section.","一位志工教訪客如何在兒童區找書。",""]],"l4-1079":[["名詞：母音","無直接同義詞","The teacher asked us to listen carefully to the vowel in each word.","老師要我們仔細聽每個單字裡的母音。",""]],"l4-1080":[["名詞：海上航行","sea journey","The crew prepared enough food and water for the long voyage across the ocean.","船員為這趟橫越大洋的漫長航程準備了足夠的食物和水。",""]],"l4-1081":[["名詞：核桃","無直接同義詞","She cracked a walnut and added the pieces to her bowl of oatmeal.","她敲開一顆核桃，把果仁碎塊加進自己的燕麥粥裡。",""]],"l4-1082":[["名詞：網站","site","The museum's website provides opening hours and details of its current exhibitions.","博物館的網站提供開放時間及目前展覽的詳細資訊。",""]],"l4-1083":[["形容詞：每週一次的","once-a-week","Our weekly meeting gives everyone a chance to raise questions about ongoing projects.","每週一次的會議讓大家有機會提出關於進行中專案的問題。",""]],"l4-1084":[["名詞：福祉；身心安好","well-being","The organization works to improve the welfare of children living in temporary housing.","這個組織致力於改善住在臨時住所中兒童的福祉。",""]],"l4-1085":[["名詞：機智；風趣的言辭能力","clever humor","Her sharp wit made even an ordinary discussion lively and entertaining.","她敏捷的機智，連平常的討論都能變得生動有趣。",""]],"l4-1086":[["名詞：女巫","sorceress","In the story, a witch offers the traveler a bowl of enchanted soup.","故事裡，一位女巫給旅人一碗施了魔法的湯。",""]],"l4-1087":[["名詞：男巫；術士","sorcerer / magician","The young wizard practiced a spell that could make locked doors open.","年輕的男巫練習一道能打開上鎖門扉的咒語。","此處 magician 指故事中施魔法的人，並非舞臺魔術師。"]],"l4-1088":[["及物動詞：提領金錢","take out / draw out","I withdrew enough cash to pay for meals during the weekend trip.","我提領了足夠的現金，支付週末旅行的餐費。",""]],"l4-1089":[["名詞：目擊者","eyewitness","A witness described the blue truck that had driven away from the crash.","一位目擊者描述了那輛駛離事故現場的藍色卡車。",""]],"l4-1090":[["名詞：船難","shipwreck","The wreck occurred during a storm that drove the ship onto hidden rocks.","這起船難發生在暴風雨中，風浪把船推向了暗礁。",""]],"l4-1091":[["名詞：皺紋","crease / line","A small wrinkle appeared beside his eye whenever he smiled.","每當他微笑時，眼角旁就會出現一道小皺紋。",""]],"l4-1092":[["形容詞：每年的；一年一次的","annual","The club's yearly report includes a summary of donations and expenses.","俱樂部的年度報告包含捐款與支出的摘要。",""]],"l4-1093":[["名詞：優格；酸奶","yoghurt / yoghourt","For breakfast, she mixed plain yogurt with sliced fruit and toasted oats.","早餐時，她把原味優格與切片水果和烤燕麥拌在一起。","yoghurt、yoghourt 是拼寫變體；優格是發酵乳製品，原稿的酵母乳不是恰當名稱。"]],"l4-1094":[["形容詞：有青春活力的","lively","Her youthful enthusiasm brought fresh energy to the long-established theater group.","她充滿青春活力的熱情，為這個歷史悠久的劇團帶來了新的活力。","youthful 帶有青春活力的意味；lively 側重活潑有精神。"]],"l5-0001":[["不及物動詞片語：遵守（abide by）","comply with / adhere to","All visitors must abide by the museum's rules about photography and handling exhibits.","所有訪客都必須遵守博物館有關攝影及觸碰展品的規定。","遵守用 abide by；單獨 abide 的常見及物義是容忍。"]],"l5-0002":[["及物動詞：廢除","eliminate / do away with","The university voted to abolish the entrance fee for its annual public lecture series.","大學投票決定取消年度公開系列講座的入場費。","abolish 通常用於正式取消制度、規定或措施。"]],"l5-0003":[["名詞：人工流產；墮胎","termination of pregnancy","The documentary examines how attitudes toward abortion differ across generations within one family.","這部紀錄片探討同一家族不同世代對墮胎的態度有何差異。","此處取人工終止妊娠義；醫學上的 abortion 也可包含自然流產。"]],"l5-0004":[["形容詞：突然的；猝然的","sudden / unexpected","An abrupt change in the weather forced the hikers to abandon their original route.","天氣突然改變，迫使登山者放棄原定路線。","abrupt 常暗示轉變突兀，缺乏過渡。"]],"l5-0005":[["形容詞：荒謬的","ridiculous / ludicrous","It seemed absurd to replace a working printer simply because its color was unfashionable.","只因印表機的顏色不流行就換掉一台正常運作的機器，似乎很荒謬。",""]],"l5-0006":[["形容詞：豐富的；充裕的","plentiful / copious","Fresh water was abundant in the valley, allowing farmers to grow several different crops.","山谷裡淡水充裕，讓農民得以種植好幾種作物。",""]],"l5-0007":[["名詞：專門學院","無直接同義詞","She entered a dance academy where students trained each morning and studied academic subjects afterward.","她進入一所舞蹈學院；那裡的學生每天上午接受訓練，之後再上學科課程。","academy 用於多種教育機構名稱，不能一律換成 university。"]],"l5-0008":[["及物動詞：使習慣","acclimate","The short daily walks helped accustom the puppy to traffic and unfamiliar sounds.","每天短暫散步，幫助小狗習慣車流與陌生聲音。","accustom someone to something；acclimate 也可表示使適應某種環境。"]],"l5-0009":[["名詞：王牌；傑出好手","star","The team's young pitching ace remained calm even with the bases loaded in the final inning.","最後一局滿壘時，球隊年輕的王牌投手仍保持冷靜。","ace 在此指表現頂尖的投手；star 指明星好手，expert 強調專業知識，不能直接替換本搭配。"]],"l5-0010":[["及物動詞：承認","admit / concede","The director acknowledged that the original schedule had left too little time for testing.","主管承認，原定時程留給測試的時間太少。","concede 常含在壓力或證據下承認之意。"]],"l5-0011":[["名詞：承認","admission / recognition","Her public acknowledgement of the mistake helped restore the team's trust in her leadership.","她公開承認錯誤，有助於恢復團隊對她領導能力的信任。","acknowledgment 是常見美式拼法。"]],"l5-0012":[["名詞：痤瘡；青春痘","無直接同義詞","He felt more comfortable discussing his acne after hearing classmates describe similar experiences.","聽到同學分享類似經驗後，他更自在地談起自己的青春痘問題。","acne 指痤瘡，原卡粉刺不足以涵蓋其所有表現；不等於單一 pimple。"]],"l5-0013":[["名詞：海軍將領；海軍上將","無直接同義詞","The admiral reviewed the rescue plan with the captains before the ships left port.","艦艇離港前，海軍將領和各艦艦長共同檢視救援計畫。","admiral 的確切軍階對應因各國制度而異。"]],"l5-0014":[["名詞：青春期","teenage years","During adolescence, she began keeping a journal to make sense of her changing relationships.","青春期時，她開始寫日記，整理自己對人際關係變化的感受。","teenage years 特指十三至十九歲；adolescence 的範圍未必完全相同。"]],"l5-0015":[["形容詞：青少年的；青春期的","teenage","The novel explores adolescent friendships and the pressures of fitting in at a new school.","這本小說探討青少年的友誼，以及融入新學校的壓力。",""]],"l5-0016":[["及物動詞：深愛；非常喜歡","love / cherish","She adores her grandfather and visits every weekend to listen to his stories.","她深愛祖父，每個週末都去探望，聽他講故事。",""]],"l5-0017":[["名詞：成年期","adult life","He carried his childhood habit of collecting unusual stones well into adulthood.","他把童年收集奇石的習慣一直保留到成年之後。","adult life 是成年生活階段的解說性對應。"]],"l5-0018":[["名詞：廣告主","無直接同義詞","The advertiser requested a clearer photograph so customers could see the product's main features.","廣告主要求使用更清楚的照片，讓顧客看得見產品的主要特色。","advertiser 是刊登或出資投放廣告的一方，不是 advertising agency 廣告公司。"]],"l5-0019":[["名詞：喜愛；深情","fondness / love","The letters reveal his lasting affection for the village where he spent his childhood.","這些信件流露出他對童年居住村莊的深厚情感。",""]],"l5-0020":[["名詞：議程","order of business","The committee added building repairs to the agenda after several residents reported leaking roofs.","幾位住戶反映屋頂漏水後，委員會把建物修繕加入議程。","agenda 在本句列出討論事項；schedule 更著重時間安排，不是完全相同的概念。"]],"l5-0021":[["名詞：極度痛苦","anguish / torment","The long wait for news of her missing dog put her in agony.","漫長等待失蹤愛犬消息的過程，讓她痛苦萬分。","本例為精神痛苦；agony 也可指劇烈身體疼痛。"]],"l5-0022":[["形容詞：農業的","無直接同義詞","The region's agricultural exports increased after a new railway connected farms to the coast.","新鐵路連接農場與海岸後，這個地區的農產品出口增加了。","agricultural exports 指農產品出口；agrarian 側重土地制度或農業社會，不適用於本搭配。"]],"l5-0023":[["名詞：人工智慧","machine intelligence","The researchers use artificial intelligence to sort thousands of wildlife photographs before checking the results themselves.","研究人員用人工智慧分類數千張野生動物照片，再親自核對結果。","AI 是 artificial intelligence 的縮寫；本句指機器執行影像分類的能力。"]],"l5-0024":[["形容詞：不透氣的；密封的","hermetic","Store the roasted coffee beans in an airtight container to keep outside moisture away.","把烘焙咖啡豆放進密封容器，避免外部水氣進入。","hermetic 較正式，強調密封隔絕。"]],"l5-0025":[["名詞：呼吸道","respiratory passage","The diagram shows how air moves through the upper airway before reaching the lungs.","圖表顯示空氣到達肺部之前，如何通過上呼吸道。","respiratory passage 是呼吸通道的解說性對應；airway 不只指氣管。"]],"l5-0026":[["名詞：走道（座位或貨架間）","passageway","A passenger stepped into the aisle to let the family reach their window seats.","一位乘客走到走道上，讓那家人進到靠窗座位。",""]],"l5-0027":[["名詞：代數","無直接同義詞","Her algebra teacher used the price of concert tickets to explain equations with two unknowns.","她的代數老師用演唱會票價，解釋含有兩個未知數的方程式。",""]],"l5-0028":[["名詞：外星人","extraterrestrial","In the film, an alien learns human customs by watching a family prepare dinner.","電影裡，一個外星人透過觀察一家人準備晚餐，學習人類習俗。","本例為外星人義；法律舊用法中的外國人義另有語氣問題。"]],"l5-0029":[["形容詞：過敏的","無直接同義詞","Because he is allergic to peanuts, he asks restaurant staff about the ingredients before ordering.","因為他對花生過敏，點餐前會先向餐廳人員詢問食材。","allergic to 為固定搭配；食物不耐受不能一概視為過敏。"]],"l5-0030":[["名詞：過敏症","無直接同義詞","She mentioned her shellfish allergy when the host asked guests about their dietary needs.","主人詢問賓客飲食需求時，她提到自己對帶殼海鮮過敏。","shellfish 可含甲殼類及貝類；本例指食物過敏，不是食物不耐受。"]],"l5-0031":[["名詞：短吻鱷","gator","An alligator lay motionless beside the marsh while the visitors watched from a raised platform.","遊客在高架平台觀察時，一隻短吻鱷一動不動地伏在沼澤旁。","gator 為口語簡稱；原卡鱷魚較廣，alligator 不應一概當成 crocodile。"]],"l5-0032":[["名詞：盟友；支持者","partner / supporter","The library found an unexpected ally in a local business that offered free printing.","圖書館意外獲得一家當地企業支持，對方提供免費印刷服務。","ally 強調共同立場或協力目標。"]],"l5-0033":[["及物動詞：更改；改動","change / modify","The tailor altered the jacket so the sleeves would fit comfortably over a sweater.","裁縫修改了外套，讓袖子在裡面穿毛衣時也能舒適合身。",""]],"l5-0034":[["不及物動詞：交替","take turns / rotate","The two nurses alternate between morning and evening shifts to share the less convenient hours.","兩名護理師輪流上早班和晚班，共同分擔較不方便的時段。","alternate between A and B；用 take turns 時可改成 take turns working morning and evening shifts。"],["形容詞：替代的（美式）","alternative / substitute","The guide suggested an alternate route after learning that the mountain bridge was closed.","導遊得知山區橋梁封閉後，建議改走另一條路。","alternate 作替代的常見於美式；也可表示每隔一個。"]],"l5-0035":[["名詞：海拔；高度","elevation / height","The hikers gained altitude gradually, stopping often to admire the valley below them.","登山者慢慢往高處走，不時停下欣賞下方山谷。","elevation 常指地點的海拔；altitude 也常用於飛行高度。"]],"l5-0036":[["形容詞：充足的","sufficient / plentiful","The new classroom provides ample space for students to work together on large projects.","新教室提供充足空間，讓學生一起製作大型專題。","ample 通常含綽綽有餘之意。"]],"l5-0037":[["名詞：錨","無直接同義詞","The crew lowered the anchor in a sheltered bay before preparing the evening meal.","船員在避風海灣下錨，再準備晚餐。",""]],"l5-0038":[["名詞：國歌","national anthem","The spectators stood quietly as their national anthem played before the international basketball match.","國際籃球賽開始前，觀眾在自己國家的國歌響起時安靜起立。","本例為國歌義；anthem 也可指團體的代表歌曲或頌歌。"]],"l5-0039":[["名詞：古董","無直接同義詞","The dealer examined the antique carefully before estimating how much restoration it would need.","古董商仔細檢查了那件古董，再估計需要多少修復工作。","old object 太廣，不能把所有舊物都當 antique。"]],"l5-0040":[["及物動詞：鼓掌；喝采","clap for","The audience applauded the young violinist long after she had finished her final piece.","年輕小提琴家演奏完最後一首曲子後，觀眾仍鼓掌許久。",""]],"l5-0041":[["名詞：掌聲","clapping","The announcement that the library would remain open drew loud applause from the crowd.","圖書館將繼續開放的消息，引來群眾熱烈掌聲。",""]],"l5-0042":[["形容詞：易於……的；傾向……的","likely / prone","The old door is apt to stick when damp weather causes the wood to swell.","潮濕天氣使木材膨脹時，那扇老門容易卡住。","apt to + 原形動詞；prone to 通常接名詞或動名詞。"]],"l5-0043":[["名詞：建築師","無直接同義詞","The architect positioned the windows to bring morning light into the reading room.","建築師安排了窗戶位置，讓晨光照進閱覽室。",""]],"l5-0044":[["名詞：建築風格；建築藝術","architectural design","Visitors admire the city's architecture, especially the narrow houses built around shared courtyards.","遊客欣賞這座城市的建築，尤其是圍繞共用庭院興建的狹長房屋。","architectural design 是建築設計的解說性近義片語。"]],"l5-0045":[["名詞：競技場；大型表演場地","stadium","Thousands of fans filled the arena to watch the final game of the season.","數千名球迷擠滿競技場，觀看球季最後一場比賽。","arena 常指室內或中央表演場；stadium 通常是較大型體育場。"]],"l5-0046":[["名詞：盔甲","無直接同義詞","The museum displayed a suit of armor beside the tools once used to make it.","博物館把一套盔甲和當年製造它的工具並列展出。","armour 為英式拼法。"]],"l5-0047":[["及物動詞：攀登；上升至","climb / go up","We ascended the narrow staircase slowly because the stone steps were worn and uneven.","石階磨損不平，我們緩慢地沿著狹窄樓梯往上走。",""]],"l5-0048":[["名詞：驢（較舊用字）","donkey","The farmer loaded the sacks onto an ass and led it carefully down the rocky path.","農夫把袋子裝上驢背，小心牽著牠走下崎嶇小路。","ass 的其他口語義含笨蛋、屁股；此例只採動物義。"]],"l5-0049":[["名詞：攻擊；襲擊","attack","The witness described the assault and helped officers identify the direction in which the attacker fled.","目擊者描述襲擊經過，幫助警員確認攻擊者逃跑的方向。","此為一般敘述用法；法律定義依制度而異。"]],"l5-0050":[["名詞：資產","property","The company sold an unused warehouse, turning an idle asset into funds for new equipment.","公司賣掉閒置倉庫，把未利用的資產轉成購買新設備的資金。","本例為有形資產；asset 也包含某些無形資產。"]],"l5-0051":[["及物動詞：使驚訝","amaze / surprise","The child's detailed drawing astonished the judges, who had expected a much simpler entry.","孩子細緻的畫作讓評審驚訝，他們原以為參賽作品會簡單得多。",""]],"l5-0052":[["名詞：驚訝","amazement / surprise","To her astonishment, the letter contained an invitation to exhibit her photographs abroad.","令她驚訝的是，信中邀請她到國外展出攝影作品。",""]],"l5-0053":[["副詞：偏離正路；迷路","off course / off track","The hikers went astray after following a faded sign that pointed toward an abandoned trail.","登山者循著褪色標誌走向廢棄步道，因而偏離了正路。",""]],"l5-0054":[["名詞：太空人","無直接同義詞","The astronaut practiced repairing equipment while wearing the thick gloves required for a spacewalk.","太空人戴著太空漫步所需的厚手套，練習修理設備。","cosmonaut 通常用於俄羅斯或前蘇聯培訓的太空人；本句未限定背景，不宜直接互換。"]],"l5-0055":[["名詞：天文學家","無直接同義詞","The astronomer compared images taken months apart to measure the distant star's changing brightness.","天文學家比較相隔數月拍攝的影像，測量遙遠恆星的亮度變化。",""]],"l5-0056":[["名詞：天文學","無直接同義詞","An evening astronomy class taught residents how to recognize familiar constellations above the city.","一門夜間天文學課程教居民辨認城市上空常見的星座。",""]],"l5-0057":[["名詞：出席；到場人數","turnout","Attendance at the free workshops increased after the library began offering sessions on weekends.","圖書館開始在週末開課後，免費工作坊的參加人數增加了。","turnout 側重某次活動的到場人數。"]],"l5-0058":[["名詞：禮堂；觀眾席所在大廳","assembly hall","The auditorium filled quickly as families arrived to watch the students perform their new musical.","家屬陸續到場觀看學生演出的新音樂劇，禮堂很快就坐滿了。","auditorium 側重觀眾聆聽或觀看活動的空間。"]],"l5-0059":[["形容詞：輔助的；備用的","supplementary / backup","An auxiliary generator kept the emergency lights on when the building's main power supply failed.","大樓主要電源失效時，備用發電機讓緊急照明繼續運作。",""]],"l5-0060":[["名詞：敬畏；驚嘆","wonder / reverence","We stood in awe beneath the enormous trees, speaking softly despite being outdoors.","我們懷著敬畏站在巨木下，即使身處戶外，仍輕聲交談。","awe 常混合讚嘆、敬重與些許畏懼。"]],"l5-0061":[["副詞：片刻；一會兒","for a while / briefly","She waited awhile beside the empty platform before checking the updated train schedule.","她在空蕩蕩的月台旁等了一會兒，才查看更新後的列車時刻表。","awhile 本身含 for a while，不再加 for。"]],"l5-0062":[["名詞：未婚男子","unmarried man","The retired teacher remained a bachelor and devoted much of his free time to restoring old boats.","退休教師一直未婚，將許多空閒時間投入修復老船。","unmarried man 為解說性對應；bachelor 通常指成年且未結婚的男性。"]],"l5-0063":[["名詞：脊柱","spine / spinal column","The skeleton model shows how the backbone supports the body and protects the spinal cord.","骨骼模型顯示脊柱如何支撐身體並保護脊髓。",""]],"l5-0064":[["名詞：徽章；識別章","insignia","The volunteers wore badges displaying the charity's symbol so visitors could recognize them.","志工佩戴印有慈善機構標誌的徽章，方便訪客辨認他們。","insignia 可泛指身分或組織標誌；badge 通常可佩戴。"]],"l5-0065":[["名詞：選票","ballot paper","Each member placed a marked ballot in the box before the counting began.","開始計票前，每位成員都把填好的選票投入票箱。",""]],"l5-0066":[["名詞：禁令","prohibition","The ban on parking near the school entrance made the crossing safer for children.","學校入口附近禁止停車的規定，讓孩子過馬路更安全。",""],["及物動詞：禁止","prohibit / forbid","The club banned glass bottles from the pool area after a broken bottle caused an injury.","玻璃瓶破裂導致有人受傷後，俱樂部禁止把玻璃瓶帶到泳池區。",""]],"l5-0067":[["名詞：強盜；土匪","robber","In the adventure novel, bandits block the mountain pass and demand payment from travelers.","冒險小說裡，土匪封鎖山口，向旅人索取通行費。","bandit 常指在偏遠地區活動的強盜。"]],"l5-0068":[["名詞：橫幅；布條","無直接同義詞","Students hung a colorful banner above the entrance to welcome visitors to their art exhibition.","學生在入口上方掛起繽紛布條，歡迎遊客參觀他們的美術展。",""]],"l5-0069":[["名詞：宴會","feast","The village held a banquet to thank the volunteers who had rebuilt the community hall.","村莊舉辦宴會，感謝協助重建活動中心的志工。","banquet 常較正式；feast 強調盛宴與豐盛食物。"]],"l5-0070":[["名詞：野蠻人（歷史性貶稱）","savage","The historian questioned why ancient writers described neighboring peoples as barbarians rather than potential partners.","歷史學家質疑，古代作者為何把鄰近民族描述為野蠻人，而不是可能的合作對象。","barbarian、savage 都帶貶意；此句討論文獻中的稱呼，不認同該標籤。"]],"l5-0071":[["名詞：理髮店","barber's","The neighborhood barbershop stayed open late so customers could get haircuts after finishing work.","社區理髮店營業到較晚，讓顧客下班後也能剪頭髮。","barber's 為英式常見稱法，完整形式可為 barber's shop。"]],"l5-0072":[["形容詞：赤腳的","barefooted","The barefoot children waited on the warm sand while their parents packed the beach bags.","赤腳的孩子們在溫暖沙灘上等候，父母則收拾海灘用品袋。",""]],"l5-0073":[["形容詞：貧瘠的；不長植物的","infertile / unproductive","Years of severe erosion had left the hillside barren, with only scattered patches of grass.","多年嚴重侵蝕使山坡變得貧瘠，只剩零星幾片草。",""]],"l5-0074":[["名詞：男低音歌手","basso","The bass sang the lowest notes while the rest of the choir carried the melody.","男低音歌手唱最低的音，其餘合唱團員則唱主旋律。","此義 bass 讀 /beɪs/；basso 較常見於古典音樂。"],["名詞：鱸魚","無直接同義詞","The angler released the small bass after measuring it beside the edge of the lake.","釣客在湖邊量過那條小鱸魚後，把牠放回水裡。","魚類義 bass 讀 /bæs/；不是低音義的讀音。"]],"l5-0075":[["名詞：一批","lot","The baker removed the first batch of rolls while the next batch waited beside the oven.","麵包師取出第一批小餐包時，下一批正放在烤箱旁等候。","batch 指同批製作或處理的一組。"]],"l5-0076":[["及物動詞：連續猛擊","pound / pummel","Strong waves battered the harbor wall throughout the night, leaving debris scattered across the walkway.","強浪整夜猛擊港牆，在步道上留下散落的碎物。",""]],"l5-0077":[["名詞：市集","market / marketplace","We wandered through the bazaar, comparing handmade baskets and spices sold at neighboring stalls.","我們漫步市集，比較相鄰攤位販售的手工籃子與香料。","bazaar 常指中東、南亞等地的市場，也可指義賣會。"]],"l5-0078":[["及物動詞：美化","embellish / enhance","Residents planted flowering trees to beautify the empty square beside the railway station.","居民種植開花樹木，美化火車站旁的空廣場。","embellish 側重加上裝飾；enhance 更廣，需有改善外觀的語境。"]],"l5-0079":[["副詞：預先","in advance / ahead of time","Read the route description beforehand so you can recognize the landmarks during the hike.","先讀路線說明，健行時才能認出沿途地標。",""]],"l5-0080":[["名詞片語：代表（on behalf of）","as a representative of","The class captain accepted the award on behalf of everyone who had worked on the project.","班長代表所有參與專題的人領獎。","behalf 通常在 on behalf of、on someone's behalf 等片語中使用。"]],"l5-0081":[["複數名詞：隨身物品；個人財物","possessions / personal effects","Passengers were asked to check for belongings under their seats before leaving the aircraft.","乘客被提醒下機前查看座位下方，確認有無遺留個人物品。",""]],"l5-0082":[["形容詞：深受喜愛的","cherished / adored","The town restored its beloved cinema after residents raised enough money to repair the roof.","居民募得足夠修繕屋頂的資金後，小鎮修復了大家鍾愛的電影院。",""]],"l5-0083":[["形容詞：有益的","helpful / advantageous","The exchange program proved beneficial to both schools by giving teachers new ideas for classroom activities.","交流計畫讓老師獲得新的課堂活動構想，證明對兩所學校都有益。",""]],"l5-0084":[["動詞：當心；提防","watch out / be wary","Beware of loose stones near the cliff edge, especially after several days of heavy rain.","當心懸崖邊緣的鬆動石塊，尤其是在連日大雨之後。","beware of；watch out for；be wary of，搭配不同。"]],"l5-0085":[["及物動詞：出價競標","offer","She bid more than she had planned because the old map showed her childhood neighborhood.","她出價超過原先計畫，因為那張老地圖畫出了她兒時居住的社區。","本句 bid 為過去式，與原形相同；offer 未必處於競標情境。"]],"l5-0086":[["名詞：鐵匠","smith","The blacksmith heated the iron bar before shaping it into a hinge for the gate.","鐵匠先加熱鐵條，再把它打造成大門的鉸鏈。","smith 常指金屬工匠；blacksmith 特指鍛鐵者。"]],"l5-0087":[["名詞：爆炸","explosion","The blast shattered windows in nearby buildings, although the damaged warehouse had already been evacuated.","爆炸震碎附近建築的窗戶，不過受損倉庫內的人員先前已經撤離。",""]],"l5-0088":[["名詞：大火","fire / inferno","Firefighters contained the blaze before it could spread from the workshop to the neighboring houses.","消防員控制住大火，避免火勢從工坊延燒到鄰近房屋。","inferno 指猛烈的大火，程度更強。"]],"l5-0089":[["及物動詞：漂白；使褪色","lighten","Years of strong sunlight had bleached the curtains, leaving only faint traces of their original blue.","多年強烈日曬使窗簾褪色，只留下淡淡的原本藍色。","本句指藍色因日曬變淡；不一定完全變白，故不以 whiten 對應此例。"]],"l5-0090":[["名詞：暴風雪","snowstorm","The blizzard closed the mountain road and left travelers waiting overnight at a small roadside inn.","暴風雪使山路封閉，旅客只得在一間路邊小旅館等候過夜。","blizzard 特別強調強風夾帶降雪；snowstorm 範圍較廣。"]],"l5-0091":[["形容詞：金髮的","fair-haired","The blond actor wore a dark wig so audiences would recognize him as the older character.","那位金髮演員戴上深色假髮，讓觀眾認出他所扮演的年長角色。","blonde 也可作形容詞，傳統上較常用於女性。"]],"l5-0092":[["名詞：污漬；墨漬","stain / spot","A large ink blot covered the address, making the old envelope difficult to identify.","一大片墨漬遮住了地址，使那個舊信封難以辨識。",""]],"l5-0093":[["複數名詞：憂鬱；低落心情","sadness / melancholy","A long walk with a friend helped lift the blues after her disappointing interview.","面試不如意後，和朋友長時間散步幫助她紓解低落心情。","情緒義常用 the blues；另有藍調音樂義。"]],"l5-0094":[["名詞：模糊影像","indistinct image","Without his glasses, the figures on the distant stage appeared as little more than a blur.","沒戴眼鏡時，遠處舞台上的人物在他眼裡幾乎只是一團模糊影像。","indistinct image 是解說性片語。"]],"l5-0095":[["形容詞：身體的","physical / corporeal","The dance workshop explored bodily movement without requiring participants to memorize any fixed sequence of steps.","舞蹈工作坊探索身體動作，不要求參與者記住任何固定舞步。","corporeal 較正式，常見於哲學或文學。"]],"l5-0096":[["名詞：保鑣","personal guard","The bodyguard checked the entrance before allowing the visiting musician to leave the hotel.","保鑣先查看入口情況，再讓到訪的音樂家離開旅館。","personal guard 是負責保護特定人士的解說性對應。"]],"l5-0097":[["名詞：泥沼；沼澤","mire","The trail crossed a wet bog where wooden boards kept walkers from sinking into the mud.","步道穿過潮濕泥沼，木板讓行人不致陷進泥裡。","bog 在生態學上有更精確的泥炭濕地含義。"]],"l5-0098":[["名詞：門閂","無直接同義詞","She slid the heavy bolt into place after the last visitor had left the workshop.","最後一位訪客離開工坊後，她把沉重的門閂推入定位。",""],["名詞：一道閃電","flash of lightning","A bolt of lightning struck the old oak during the fiercest part of the storm.","暴風雨最猛烈時，一道閃電擊中了老橡樹。","flash of lightning 對應整個 bolt of lightning。"]],"l5-0099":[["名詞：獎金；額外酬勞","extra payment","The company gave the team a bonus for completing the urgent repair ahead of schedule.","公司發給團隊獎金，獎勵他們提早完成緊急修繕。","extra payment 是解說性片語；bonus 不一定是分紅。"]],"l5-0100":[["不及物動詞：迅速繁榮","flourish / expand rapidly","Tourism boomed after the railway reopened, bringing new customers to the village's small shops.","鐵路恢復通車後，觀光業迅速興盛，替村裡小店帶來新顧客。",""]],"l5-0101":[["名詞：攤位；小亭","stall","At the information booth, volunteers handed visitors maps and answered questions about the festival.","志工在服務亭發給訪客地圖，並回答有關節慶的問題。",""]],"l5-0102":[["名詞：無聊；厭倦","tedium","The students invented a word game to relieve the boredom of the long bus journey.","學生們發明了一個文字遊戲，排解長途巴士旅行的無聊。","tedium 常帶有因單調而厭倦的意味。"]],"l5-0103":[["名詞：胸懷；胸前（文學）","breast / chest","In the painting, the woman holds a sleeping child close to her bosom.","畫中的女子把熟睡的孩子緊抱在胸前。","bosom 帶文學或舊式語感；breast 在此指胸部，不能直接替換表示 figurative 的「胸懷」。"]],"l5-0104":[["名詞：植物學","plant science","Her interest in botany grew after she began identifying the wildflowers along a nearby river.","開始辨認附近河邊的野花後，她對植物學的興趣漸漸加深。",""]],"l5-0105":[["名詞：寬闊大道；林蔭大道","avenue","The parade moved slowly along the boulevard while spectators watched from balconies shaded by old trees.","遊行隊伍沿著大道緩緩前進，觀眾在老樹遮蔭的陽台上觀看。","boulevard 通常較寬，常有樹木或中央分隔帶。"]],"l5-0106":[["不及物動詞：跳躍前進","leap / spring","The puppy bounded across the lawn when it heard its owner return from work.","小狗聽見主人下班回來，就蹦跳著穿過草坪。","本例 bound 是跳躍，不是 bind 的過去式。"]],"l5-0107":[["名詞：邊界；界線","border / limit","A low stone wall marks the boundary between the public garden and the neighboring farm.","一道低石牆標示出公共花園與鄰近農場的界線。",""]],"l5-0108":[["名詞：腸","intestine","The medical illustration shows the position of the bowel in relation to the stomach and liver.","醫學插圖顯示腸相對於胃和肝臟的位置。","bowel 可指腸的部分或整體；常見複數 bowels。"]],"l5-0109":[["名詞：拳擊手","pugilist","The boxer reviewed the recording with her coach to understand why she kept losing her balance.","拳擊手與教練一起重看錄影，了解自己為何不斷失去平衡。","pugilist 較正式或文學。"]],"l5-0110":[["名詞：拳擊","pugilism","He took up boxing for the discipline of regular training rather than the chance to compete.","他開始練拳擊，是為了規律訓練帶來的自律，而非參賽機會。","pugilism 較正式或舊式。"]],"l5-0111":[["名詞：男孩時代","childhood","He revisited the harbor where he had spent much of his boyhood watching fishing boats return.","他重訪那座港口，童年時他常在那裡看漁船返航。","boyhood 特指男性童年；childhood 不限性別。"]],"l5-0112":[["名詞：支撐架","support / strut","The builder added a wooden brace to keep the damaged beam from bending further.","工人加上一個木製支撐架，防止受損橫梁繼續彎曲。",""]],"l5-0113":[["名詞：辮子","plait","She tied her hair in a tight braid before putting on her helmet for the ride.","她先把頭髮編成緊實辮子，再戴上安全帽準備騎車。","plait 為英式常見用字。"]],"l5-0114":[["名詞：寬度","width","The carpenter measured the breadth of the doorway before attempting to move the cabinet inside.","木匠先量門口寬度，再嘗試把櫃子搬進去。",""]],"l5-0115":[["名詞：賄賂；賄款","payoff","The official reported the attempted bribe instead of accepting money to overlook the missing documents.","官員通報了行賄企圖，沒有收錢放過文件缺漏的問題。","payoff 作賄款義較口語；bribe 本身有誘使不當行為之意。"]],"l5-0116":[["名詞：公事包","無直接同義詞","He placed the signed contract in his briefcase before leaving the client's office.","他離開客戶辦公室前，把簽好的合約放進公事包。","attaché case 特指較扁平、硬殼的公事包；本句未限定外形，不宜直接互換。"]],"l5-0117":[["及物動詞：拓寬；擴大","widen / expand","Reading accounts from different countries helped broaden her understanding of the same historical event.","閱讀不同國家的記述，幫助她更全面地理解同一歷史事件。",""]],"l5-0118":[["名詞：青銅","無直接同義詞","The sculptor chose bronze because she wanted the outdoor statue to develop a rich surface color.","雕塑家選擇青銅，因為她希望戶外雕像逐漸呈現豐富的表面色澤。",""]],"l5-0119":[["名詞：胸針","pin","The small silver brooch held her scarf in place throughout the windy outdoor ceremony.","整場戶外典禮風很大，那枚小銀胸針始終固定著她的圍巾。","pin 在飾品語境可指胸針，也有大頭針等其他義。"]],"l5-0120":[["名詞：同窩幼鳥；一窩幼雛","無直接同義詞","The duck led her brood through the reeds, pausing whenever one duckling fell behind.","母鴨帶著一窩小鴨穿過蘆葦叢，只要有小鴨落後就停下來。","brood 指同窩的幼鳥；clutch 通常指一窩蛋。"]],"l5-0121":[["名詞：清湯；高湯","stock / bouillon","She simmered the vegetables in a light broth until they were tender but still held their shape.","她把蔬菜放在清淡的高湯中慢煮，煮到軟嫩但仍保有形狀。","stock 通常用作烹調基底；broth 也可直接飲用。"]],"l5-0122":[["名詞：兄弟情誼；手足之情","fellowship / comradeship","Years of working together at sea created a strong sense of brotherhood among the crew.","多年共同海上工作，讓船員之間形成深厚的手足情誼。",""]],"l5-0123":[["不及物動詞：隨意瀏覽","look through","She browsed through the secondhand books while waiting for the rain outside to ease.","等待外頭雨勢減弱時，她隨意翻看二手書。","look through 對應本句的 browse through 整個片語，替換時不可重複 through。"]],"l5-0124":[["名詞：瘀青","contusion","A dark bruise appeared on his arm after he bumped into the corner of the table.","他的手臂撞到桌角後，出現一塊深色瘀青。","contusion 是較正式的醫學用語。"]],"l5-0125":[["名詞：凸起；鼓包","swelling / protrusion","A bulge in the wallpaper revealed where rainwater had been leaking behind the wall.","壁紙上一處鼓起，顯露出雨水滲入牆後的位置。",""]],"l5-0126":[["名詞：體積；龐大體積","volume / size","The sofa's bulk made it difficult to carry up the narrow staircase of the old apartment.","沙發體積龐大，很難沿著老公寓的狹窄樓梯往上搬。","bulk 常特別強調龐大、不易搬動的體積。"]],"l5-0127":[["及物動詞：霸凌；欺壓","intimidate / torment","The coach intervened when older players began to bully a newcomer during practice.","年長隊員開始在練習時霸凌新隊員，教練隨即介入。","intimidate 側重恐嚇；bully 常有反覆欺凌及力量不對等。"]],"l5-0128":[["名詞：局；處；機關","agency / department","The tourism bureau opened a temporary desk to help visitors during the summer festival.","觀光局在夏季節慶期間設立臨時服務台，協助遊客。",""]],"l5-0129":[["名詞：肉販；屠夫","無直接同義詞","The butcher explained which cuts would stay tender during the long cooking time of the stew.","肉販說明哪些部位的肉經過燉煮很久後，仍能保持軟嫩。",""]],"l5-0130":[["名詞：仙人掌","無直接同義詞","A cactus stood beside the sunny window, its red flowers bright against the pale wall.","一盆仙人掌放在向陽窗邊，紅花映著淺色牆面，格外鮮明。",""]],"l5-0131":[["名詞：小牛","無直接同義詞","The farmer checked that the newborn calf was warm before returning to the milking shed.","農夫確認剛出生的小牛很暖和，再回到擠乳棚。","calf 的複數為 calves；也可指某些大型哺乳動物的幼獸。"]],"l5-0132":[["名詞：書法","無直接同義詞","The calligraphy teacher demonstrated how changing the pressure on the brush could alter each stroke.","書法老師示範改變毛筆下壓力道，如何影響每一筆的線條。",""]],"l5-0133":[["名詞：運河","無直接同義詞","The narrow canal once carried grain to the harbor, but now pleasure boats use it.","這條狹窄運河曾運送穀物到港口，如今則供遊艇使用。","canal 是人工水道，不一概等於天然 channel。"]],"l5-0134":[["名詞：大砲","無直接同義詞","The museum placed the restored cannon beside a drawing showing how the old fortress was defended.","博物館把修復的大砲放在一幅古堡防禦示意圖旁。","artillery 是大砲等火砲的集合稱呼，不等於一門 cannon。"]],"l5-0135":[["名詞：碳（化學元素）","無直接同義詞","The students built a model showing how carbon atoms connect to form different molecular structures.","學生製作模型，呈現碳原子如何連接，形成不同的分子結構。","原卡寫炭；元素名稱應為碳，木炭則是 charcoal。"]],"l5-0136":[["名詞：硬紙板","paperboard","We reinforced the cardboard with wooden strips before using it as scenery for the school play.","我們先用木條加固硬紙板，再把它當作學校戲劇的布景。","paperboard 常指較厚實的紙板，工業分類可能更精細。"]],"l5-0137":[["形容詞：無憂無慮的","lighthearted / unworried","The photographs show a carefree summer spent swimming, reading, and exploring the countryside with friends.","照片呈現出一個無憂無慮的夏天，有游泳、閱讀，還有與朋友一起探索鄉間的時光。",""]],"l5-0138":[["名詞：看管人；管理員","custodian / keeper","The caretaker checks the empty school each evening and makes sure every window is securely closed.","管理員每天傍晚巡查空校舍，確認每扇窗戶都已關妥。","本例為建物管理員義，不是家庭照護者義。"]],"l5-0139":[["名詞：康乃馨","無直接同義詞","She placed a pink carnation beside each guest's name card at the long dining table.","她在長餐桌上每位賓客的名牌旁，都放了一朵粉紅色康乃馨。",""]],"l5-0140":[["名詞：嘉年華；遊樂慶典","fair / festival","The annual carnival filled the town square with music, food stalls, and brightly painted rides.","年度嘉年華使鎮廣場充滿音樂、食物攤位和色彩鮮豔的遊樂設施。","fair 可指遊樂市集；festival 是較廣的節慶活動。"]],"l5-0141":[["名詞：鯉魚","無直接同義詞","Large carp gathered beneath the wooden bridge as the children leaned over to watch them.","大鯉魚聚集在木橋下，孩子們探身觀看。",""]],"l5-0142":[["名詞：紙箱；紙盒","cardboard box","The delivery arrived in a sturdy carton with folded paper protecting the cups inside.","貨物裝在堅固紙箱裡送達，內部摺好的紙保護著杯子。",""]],"l5-0143":[["名詞：類別","class / group","The librarian placed the book in a different category because it was a memoir, not a novel.","圖書館員把那本書歸入另一類，因為它是回憶錄，而不是小說。",""]],"l5-0144":[["名詞：主教座堂；大教堂","無直接同義詞","Restoration workers cleaned the cathedral's stained glass while preserving the original pieces of colored glass.","修復人員清理主教座堂的彩繪玻璃，同時保留原有的彩色玻璃片。","cathedral 指教區的重要教堂，通常為主教座堂，不單以建築大小判定。"]],"l5-0145":[["名詞：小心；謹慎","care / prudence","The guide urged caution because loose gravel made the final section of the descent slippery.","導遊提醒大家小心，因為最後一段下坡有鬆散碎石，容易滑倒。","prudence 較強調審慎判斷。"]],"l5-0146":[["形容詞：小心的；謹慎的","careful / wary","She was cautious about promising a delivery date before the supplier confirmed that the parts were available.","供應商確認零件有貨之前，她很謹慎，不輕易承諾交貨日期。",""]],"l5-0147":[["名詞：名人","star / famous person","The celebrity declined to discuss her private life and kept the interview focused on her new film.","那位名人不願談私生活，讓訪問持續聚焦於她的新電影。","star 常指娛樂界明星；celebrity 也可來自其他領域。"]],"l5-0148":[["名詞：芹菜","無直接同義詞","The cook chopped the celery finely so its flavor would blend into the vegetable soup.","廚師把芹菜切得細碎，讓它的味道融進蔬菜湯裡。",""]],"l5-0149":[["名詞：地窖；地下儲藏室","basement","They stored the harvested apples in the cool cellar beneath the old farmhouse.","他們把採收的蘋果存放在老農舍下方涼爽的地窖裡。","cellar 常作儲藏用；basement 也可包含居住或工作空間。"]],"l5-0150":[["名詞：手機","mobile phone / cell phone","She switched off her cellphone before entering the rehearsal room so the musicians would not be interrupted.","她進排練室前關掉手機，避免打斷音樂家。","cellphone、cell phone 常見於美式；mobile phone 常見於英式。"]],"l5-0151":[["名詞：大提琴","violoncello","The cello's warm tone balanced the brighter sound of the violins during the quiet passage.","樂曲安靜的段落中，大提琴溫潤的音色平衡了小提琴較明亮的聲音。","violoncello 是 cello 的完整名稱，較正式。"]],"l5-0152":[["溫標名稱：攝氏","centigrade","The laboratory kept the room at twenty degrees Celsius throughout the weeklong experiment.","實驗室在為期一週的實驗期間，始終維持室溫攝氏二十度。","Celsius 與 centigrade 在一般溫度表達中同指攝氏溫標。"]],"l5-0153":[["名詞：典禮；儀式","無直接同義詞","The ceremony ended with the graduates thanking the teachers who had supported them throughout the course.","典禮最後，畢業生感謝在整個課程期間支持他們的老師。","本句為畢業典禮；ritual 側重固定程序，service 常指宗教儀式。"]],"l5-0154":[["名詞：證書；證明文件","無直接同義詞","After completing the safety course, each volunteer received a certificate showing the date of training.","完成安全課程後，每位志工都收到一張註明訓練日期的證書。","diploma 通常指學歷或特定課程文憑，不涵蓋所有 certificate。"]],"l5-0155":[["名詞：主席（不限定性別）","chair","The chairperson invited quieter members to speak before the committee voted on the proposal.","委員會對提案投票前，主席邀請較少發言的成員表達意見。",""]],"l5-0156":[["名詞：主席","chairperson / presiding officer","The chairman postponed the vote until all members had received a copy of the revised budget.","主席延後表決，等所有成員都收到修訂後的預算副本。","chair 是常用的不分性別稱呼；chairman 傳統上常指男性。"]],"l5-0157":[["名詞：女主席","chair / chairperson","The chairwoman asked the speakers to keep their remarks brief so everyone could contribute.","女主席請發言者簡短陳述，讓每個人都有機會參與。","chair、chairperson 不限定性別。"]],"l5-0158":[["及物動詞：反覆高呼；吟誦","repeat rhythmically","Supporters chanted the team's name as the players stepped onto the field for the final match.","球員踏入球場準備決賽時，支持者反覆高呼隊名。","此為解釋性片語；替換時可說 repeated the team's name rhythmically。intone 常指莊重或單調地吟誦，不適合本句的球迷歡呼。"]],"l5-0159":[["不及物動詞：喋喋不休；閒聊","chat / babble","The children chattered excitedly on the bus, comparing everything they had seen at the aquarium.","孩子們在巴士上興奮地聊個不停，交流在水族館看到的一切。","babble 可暗示說得快而雜亂，語氣較負面。"]],"l5-0160":[["名詞：支票簿","chequebook","He checked the account balance before taking out his checkbook to pay the repair bill.","他先查看帳戶餘額，再拿出支票簿支付修理費。","chequebook 為英式拼法。"]],"l5-0161":[["名詞：報到；辦理入住","registration","Online check-in reduced the time guests spent waiting at the hotel's reception desk.","線上辦理入住縮短了客人在旅館櫃台等候的時間。","名詞 check-in 有連字號；動詞 check in 分開寫。"]],"l5-0162":[["名詞：退房；結帳離開","無直接同義詞","We requested a later check-out so we could leave our bags in the room until noon.","我們要求延後退房，這樣就能把行李留在房間到中午。","此處採旅館退房義；也常拼 checkout。動詞寫 check out。"]],"l5-0163":[["名詞：健康檢查","medical examination","She scheduled a routine checkup before leaving for a year of study abroad.","她安排了一次例行健康檢查，準備出國留學一年。",""]],"l5-0164":[["名詞：主廚；專業廚師","cook","The chef adjusted the menu to feature vegetables grown by farmers in the surrounding villages.","主廚調整菜單，主打周邊村莊農民種植的蔬菜。","chef 通常指受訓的專業廚師或廚房主管；cook 範圍較廣。"]],"l5-0165":[["名詞：化學家","無直接同義詞","The chemist repeated the experiment to check whether a contaminated sample had affected the results.","化學家重做實驗，確認是否有受污染樣本影響結果。","英式 chemist 也可指藥師；本例只採科學家義。"]],"l5-0166":[["名詞：栗子","無直接同義詞","The vendor roasted chestnuts in a large pan, filling the cold street with a sweet aroma.","攤販用大鍋炒栗子，讓寒冷的街道充滿甜香。",""]],"l5-0167":[["名詞：辣椒","chili pepper / hot pepper","She added a finely chopped chili to the sauce, then tasted it before adding another.","她在醬汁裡加了一根切碎的辣椒，嚐過之後又加了一根。","原卡譯胡椒不準確；chili 指辣椒，英式常拼 chilli。"]],"l5-0168":[["名詞：黑猩猩","chimp","The chimpanzee used a thin stick to reach food hidden inside a narrow opening.","黑猩猩用細棍伸進狹窄開口，取得藏在裡面的食物。","chimp 是口語簡稱。"]],"l5-0169":[["名詞：合唱團；唱詩班","chorus","The community choir rehearsed twice a week before performing at the opening of the new library.","社區合唱團每週排練兩次，準備在新圖書館開幕時演出。",""]],"l5-0170":[["名詞：和弦","無直接同義詞","The pianist played the final chord softly and waited until its sound had completely faded.","鋼琴家輕輕彈出最後一個和弦，等聲音完全消散。","chord 是同時發聲的多個音，不等於單一 note。"]],"l5-0171":[["形容詞：圓胖的","plump","The chubby toddler clapped when the puppet appeared from behind the curtain.","圓胖的幼兒看到布偶從幕後出現，就拍起手來。","plump 表圓潤豐滿，通常比 fat 語氣溫和。"]],"l5-0172":[["名詞：電路","electrical circuit","The students completed the circuit and watched the small bulb light up on their board.","學生完成電路，看到板上的小燈泡亮了起來。",""]],"l5-0173":[["及物動詞：引用；援引為證","refer to","The report cites several interviews to support its claim that the new service saves residents time.","報告引用幾段訪談，支持新服務能節省居民時間的說法。","cite 可指援引資料，不一定逐字引用；quote 通常涉及原話，故本句不直接對應 quote。"]],"l5-0174":[["形容詞：市民的；公民事務的","無直接同義詞","The school encourages civic responsibility by involving students in discussions about local transport and public spaces.","學校讓學生參與地方交通與公共空間的討論，培養公民責任感。","civic responsibility 指公民對社群與公共事務的責任。"]],"l5-0175":[["名詞：蛤蜊","無直接同義詞","The cook rinsed the clams carefully before adding them to a pot of steaming broth.","廚師仔細沖洗蛤蜊，再放入冒著熱氣的高湯裡。","本例為貝類義；夾鉗通常是 clamp，不應以 clam 教學。"]],"l5-0176":[["名詞：氏族；家族群體","extended family","Members of the clan traveled from several villages to attend the annual gathering.","氏族成員從幾個村莊趕來，參加年度聚會。","clan 常以共同祖先或血緣認同相連；不一定等於 tribe。"]],"l5-0177":[["及物動詞：緊握","grip / grasp","She clasped the handrail firmly as the train slowed suddenly before reaching the platform.","火車到站前突然減速，她牢牢抓住扶手。",""]],"l5-0178":[["名詞：條款","provision / stipulation","The tenant asked the landlord to explain a clause concerning repairs to shared facilities.","房客請房東解釋一項關於共用設施修繕的條款。",""],["名詞：子句","無直接同義詞","The teacher marked the main clause in blue and the dependent clause in green.","老師把主要子句標成藍色，從屬子句標成綠色。",""]],"l5-0179":[["不及物動詞：緊抓；依附","hold on","The child clung to the railing while looking down at the boats far below.","孩子望著遠下方的船隻，同時緊抓欄杆。","本句 cling to 對應 hold on to；注意不規則過去式 clung。"]],"l5-0180":[["副詞：順時針方向地","無直接同義詞","Turn the dial clockwise until the small arrow lines up with the temperature you want.","順時針轉動旋鈕，直到小箭頭對準所需溫度。",""]],"l5-0181":[["名詞：三葉草","無直接同義詞","White clover spread across the lawn, attracting bees to its small rounded flowers.","白三葉草在草坪上蔓延，圓圓的小花吸引了蜜蜂。","此處指三葉草屬植物；不可一概將 clover 與 alfalfa（苜蓿）互換。"]],"l5-0182":[["名詞：聚集的一群；一簇","group / bunch","A cluster of hikers gathered around the map to decide which trail to follow.","一群健行者圍著地圖，決定要走哪條步道。","cluster 強調聚集得較近；bunch 較口語。"]],"l5-0183":[["及物動詞：緊抓","grip / grasp","He clutched the folder against his chest as a gust of wind scattered loose papers.","一陣風吹散了零散紙張，他把資料夾緊抱在胸前。",""],["名詞：離合器","無直接同義詞","The instructor reminded her to release the clutch slowly as the car began to move.","車子開始移動時，教練提醒她慢慢放開離合器。",""]],"l5-0184":[["名詞：海岸線","coast","We followed the coastline north, stopping at small fishing villages along the way.","我們沿著海岸線往北走，途中在小漁村停留。","coast 可指較廣的沿海地區；coastline 強調陸海交界的輪廓。"]],"l5-0185":[["名詞：繭","無直接同義詞","The children examined an empty cocoon hanging from a twig near the classroom window.","孩子們觀察掛在教室窗邊一根小樹枝上的空繭。","cocoon 是包覆的繭，不等於蛹本身。"]],"l5-0186":[["名詞：捲；一圈圈盤繞的物體","無直接同義詞","A coil of rope lay beside the anchor, ready for the crew to use.","一捲繩索放在船錨旁，供船員隨時使用。",""]],"l5-0187":[["名詞：同事","coworker","My colleague offered to handle the morning appointments while I attended a training session.","我參加培訓課程時，同事主動提出處理上午的預約。",""]],"l5-0188":[["名詞：上校","無直接同義詞","The colonel inspected the damaged bridge before discussing possible routes with the engineering team.","上校先視察受損橋梁，再與工程小組討論可行路線。","特定軍階；不可用一般 officer 當成同義詞。"]],"l5-0189":[["形容詞：殖民時期的；殖民地的","無直接同義詞","The museum displays colonial records alongside accounts written by the island's local communities.","博物館把殖民時期的紀錄與島上當地社群撰寫的記述並列展出。",""]],"l5-0190":[["及物動詞：對抗；設法消除","fight / counter","The council planted more trees to combat the intense heat in crowded residential neighborhoods.","市議會種植更多樹木，對抗人口密集住宅區的酷熱。",""]],"l5-0191":[["名詞：喜劇演員","comic","The comedian turned a broken microphone into part of the act and kept everyone laughing.","喜劇演員把故障的麥克風融入表演，逗得大家笑個不停。",""]],"l5-0192":[["名詞：彗星","無直接同義詞","Through the telescope, we could see a faint tail extending behind the comet.","透過望遠鏡，我們看見彗星後方延伸著一條微弱的尾巴。",""]],"l5-0193":[["名詞：賽事播報員；評述員","sportscaster","The commentator explained the penalty while a replay showed exactly where the foul had occurred.","播報員解釋判罰，同時重播畫面清楚顯示犯規發生的位置。","本例為體育播報；commentator 也可指時事評論員。"]],"l5-0194":[["名詞：佣金","無直接同義詞","The agent earns a commission whenever a customer purchases a house through her office.","只要顧客透過她的事務所買房，這位仲介就能賺取佣金。","commission 指依成交獲得的報酬；fee 不一定與成交掛鉤。"]],"l5-0195":[["名詞：商品；交易物資","無直接同義詞","Coffee became the town's main export commodity after farmers formed a cooperative to reach overseas buyers.","農民成立合作社接洽海外買家後，咖啡成為鎮上主要的出口商品。","commodity 常指可大量交易的物資；不是只指日用品。"]],"l5-0196":[["形容詞：常見的；普通的","ordinary / common","What once seemed remarkable has become commonplace as more households install solar panels.","隨著更多家庭安裝太陽能板，曾經令人驚奇的事已變得司空見慣。",""]],"l5-0197":[["名詞：共產主義","無直接同義詞","The seminar compared how different writers interpreted communism during the early twentieth century.","研討課比較二十世紀初不同作家如何詮釋共產主義。","政治思想名稱；不可直接與 socialism 畫上等號。"]],"l5-0198":[["形容詞：共產主義的","無直接同義詞","The novelist joined a communist party in her youth but later questioned its leadership.","這位小說家年輕時加入一個共產黨，但後來對該黨的領導提出質疑。","原卡也列名詞義「共產主義者」；本句以形容詞修飾 party。"]],"l5-0199":[["不及物動詞：通勤","無直接同義詞","She commutes by train three days a week and works from home on the other days.","她每週有三天搭火車通勤，其餘日子在家工作。","commute 表示定期往返住處與工作或上學地點。"]],"l5-0200":[["名詞：通勤者","無直接同義詞","Several commuters shared a taxi after the last evening train was canceled.","晚間末班火車取消後，幾名通勤者共乘計程車。",""]],"l5-0201":[["形容詞：小巧且節省空間的","space-saving","The compact desk folds against the wall, leaving enough room for an exercise mat.","這張小巧的書桌可以收折貼牆，留下足夠空間放運動墊。",""]],"l5-0202":[["名詞：指南針","無直接同義詞","When fog hid the mountain peaks, our guide used a compass to check our direction.","霧遮住山峰時，嚮導用指南針確認方向。",""]],"l5-0203":[["名詞：同情；憐憫","sympathy / empathy","She showed compassion for the exhausted travelers by offering them water and a place to rest.","她給疲憊的旅人水和休息的地方，表達對他們的同情與關懷。","compassion 常包含想減輕他人痛苦的心意；empathy 側重理解其感受。"]],"l5-0204":[["形容詞：有同情心的","caring / sympathetic","A compassionate supervisor listened to his concerns and helped him arrange a more manageable schedule.","一位體恤人的主管聆聽他的顧慮，並協助安排較能負荷的工作時間。",""]],"l5-0205":[["及物動詞：迫使","force / oblige","The missing safety records compelled the organizers to postpone the race until further inspections were completed.","安全紀錄缺漏，迫使主辦單位延後比賽，直到進一步檢查完成。",""]],"l5-0206":[["及物動詞：稱讚","praise","Several guests complimented the chef on the delicate flavor of the mushroom soup.","幾位客人稱讚主廚的蘑菇湯風味細緻。","compliment someone on something；praise someone for something。"]],"l5-0207":[["名詞：化合物","無直接同義詞","The chemist identified a new compound in the sample and recorded its properties for further study.","化學家在樣本中辨識出一種新化合物，並記錄其性質以便進一步研究。","化學語境應譯化合物；不能把 compound 與物理混合物 mixture 等同。"]],"l5-0208":[["及物動詞：理解","understand / grasp","He reread the final paragraph several times before he could comprehend the author's argument.","他把最後一段重讀好幾次，才理解作者的論點。",""]],"l5-0209":[["名詞：理解力；理解","understanding","The teacher checked our comprehension by asking us to explain the instructions in our own words.","老師請我們用自己的話解釋指示，確認我們是否理解。",""]],"l5-0210":[["名詞：折衷方案；妥協","middle ground","After a long discussion, the neighbors reached a compromise about when construction work could begin.","長時間討論後，鄰居們就施工可以開始的時間達成折衷方案。","middle ground 是雙方可接受的中間立場；用法為 find 或 reach middle ground。"]],"l5-0211":[["及物動詞：計算","calculate / work out","The spreadsheet computes the total cost after discounts and delivery charges have been entered.","輸入折扣與運費後，試算表會計算總費用。","本例使用常見動詞義；表示一般計算行為的名詞通常用 computation。"]],"l5-0212":[["及物動詞：使電腦化","無直接同義詞","The clinic computerized its appointment system so staff could find available time slots more quickly.","診所將預約系統電腦化，讓員工更快找到可預約時段。","digitize 主要指轉成數位形式，未必包含建立電腦管理流程。"]],"l5-0213":[["名詞：同志；戰友","companion / fellow soldier","The veteran returned to the village where he had last seen his wartime comrades.","老兵回到那座村莊，他最後一次見到戰時同袍就是在那裡。","本例採戰友義；fellow soldier 是解說性對應。"]],"l5-0214":[["及物動詞：隱藏","hide","Thick vines concealed the entrance to the abandoned house until workers cleared the overgrown garden.","工人清理雜草叢生的花園前，茂密藤蔓遮住了廢棄房屋的入口。",""]],"l5-0215":[["及物動詞：構想出","devise / imagine","The designer conceived a folding chair that could fit inside a standard bicycle basket.","設計師構想出一張能放進一般自行車車籃的折疊椅。",""]],"l5-0216":[["及物動詞：譴責","denounce / criticize","Residents condemned the company's decision to dump construction waste beside the community's only playground.","居民譴責公司把建築廢棄物倒在社區唯一遊樂場旁的決定。","condemn、denounce 比 criticize 更強烈。"]],"l5-0217":[["及物動詞：指揮樂團","lead / direct","She conducted the orchestra with small, precise gestures that every musician could follow.","她以細微而精確的手勢指揮樂團，讓每位樂手都能跟上。",""]],"l5-0218":[["名詞：坦白；承認","admission","His confession that he had broken the vase surprised no one who had seen the fallen shelf.","他坦白自己打破花瓶；看過倒下架子的人對此都不意外。",""]],"l5-0219":[["及物動詞：正視；面對","face / tackle","The new manager must confront the staffing problems that have delayed deliveries for months.","新經理必須面對已使交貨延誤數月的人力問題。",""]],"l5-0220":[["名詞：同意；允許","permission / agreement","The photographer asked for each participant's consent before including their portraits in the exhibition.","攝影師在把人像納入展覽前，先徵求每位參與者的同意。",""]],"l5-0221":[["及物動詞：節約；保存","save / preserve","During the drought, residents collected rainwater whenever possible to conserve the town's limited water supply.","乾旱期間，居民盡可能收集雨水，節約鎮上有限的水資源。",""]],"l5-0222":[["形容詞：體貼的","thoughtful","It was considerate of him to lower the music when the baby fell asleep upstairs.","樓上的嬰兒睡著後，他把音樂調小，十分體貼。",""]],"l5-0223":[["及物動詞：安慰","comfort","Her teammates tried to console her after she missed the final penalty kick of the match.","她踢失比賽最後一記十二碼球後，隊友試著安慰她。","本句指安慰失望的人；reassure 側重消除擔憂，不是此處的直接替換詞。"]],"l5-0224":[["形容詞：憲法的","無直接同義詞","The class debated a proposed constitutional amendment after reading arguments from several legal scholars.","班上閱讀幾位法學學者的論點後，討論一項憲法修正提案。",""]],"l5-0225":[["形容詞：情緒等容易感染他人的","infectious","Her enthusiasm was contagious, and soon even the reluctant volunteers were suggesting ideas for the festival.","她的熱情很有感染力，不久連原本不太情願的志工都開始為慶典出點子。","本例為比喻義；疾病語境中 contagious 與 infectious 的涵蓋範圍不同。"]],"l5-0226":[["及物動詞：汙染","pollute / taint","A leaking storage tank contaminated the soil behind the factory, prompting a lengthy cleanup.","一座漏液儲槽汙染了工廠後方的土壤，因而展開漫長的清理作業。",""]],"l5-0227":[["及物動詞：仔細考慮","consider","She contemplated moving closer to the coast but worried about finding work in a smaller town.","她仔細考慮搬到更靠近海岸的地方，但擔心在小鎮找不到工作。","contemplate doing 與 consider doing 可直接接動名詞；ponder 通常接問題或想法，不宜直接替換 contemplated moving。"]],"l5-0228":[["形容詞：當代的","modern / present-day","The gallery pairs contemporary photographs with old maps to show how the harbor has changed.","畫廊把當代照片與老地圖搭配展示，呈現港口的變遷。","本句指現在的；contemporary 另可指與某人或某事同時代的。"]],"l5-0229":[["名詞：輕蔑","scorn / disdain","The critic's contempt for popular novels was obvious from the dismissive tone of her review.","從評論中不屑的語氣，可以清楚看出這位評論家對通俗小說的輕蔑。",""]],"l5-0230":[["及物動詞：主張；聲稱","argue / maintain","The researchers contend that smaller classes allow teachers to give more useful feedback on student writing.","研究人員主張，較小的班級讓教師能對學生的寫作提供更有用的回饋。","contend that 引出主張；本例不是競爭義。"]],"l5-0231":[["形容詞：大陸的；大陸地區的","無直接同義詞","The exhibition follows the trade routes that once connected island ports with continental markets.","這場展覽追溯曾經連接島嶼港口與大陸市場的貿易路線。",""]],"l5-0232":[["名詞：持續性；連貫性","consistency","Keeping the same teacher for two years gave the children a valuable sense of continuity.","連續兩年由同一位老師教導，讓孩子們感受到可貴的延續性。","continuity 強調不中斷的延續；consistency 強調穩定一致。"]],"l5-0233":[["及物動詞：改裝；轉換用途","transform","The owners converted an unused garage into a bright studio with windows facing the garden.","屋主把閒置車庫改成明亮的工作室，窗戶朝向花園。","convert A into B；transform 也接 into，常強調顯著的改變。"]],"l5-0234":[["及物動詞：判定有罪","find guilty","The jury convicted the defendant after reviewing the recordings and hearing testimony from several witnesses.","陪審團審視影音紀錄並聽取數名證人的證詞後，認定被告有罪。","find someone guilty 對應 convict someone；可接 of 加罪名。"]],"l5-0235":[["名詞：珊瑚","無直接同義詞","The divers floated above the coral, taking care not to touch it with their fins.","潛水員漂浮在珊瑚上方，小心避免用蛙鞋碰到它。",""]],"l5-0236":[["名詞：公司；法人企業","company","The family business grew into a large corporation with offices in several neighboring countries.","這家家族企業發展成大型公司，在幾個鄰國設有辦公室。","corporation 強調依法成立的法人組織；company 較廣。"]],"l5-0237":[["名詞：著作權","無直接同義詞","The publisher contacted the artist to discuss copyright before reproducing the illustration on the book cover.","出版社在書封重製插畫前，聯絡畫家討論著作權事宜。",""]],"l5-0238":[["名詞：往來書信；通信","letters","The archive contains decades of correspondence between the scientist and colleagues working abroad.","檔案館保存了這位科學家與海外同事數十年間的往來書信。","本句 correspondence 是不可數集合名詞；letters 是可數複數。"]],"l5-0239":[["名詞：走廊","hallway / passageway","At the end of the corridor, a glass door opened onto a quiet rooftop garden.","走廊盡頭的一扇玻璃門通往安靜的屋頂花園。",""]],"l5-0240":[["形容詞：貪汙的；腐敗的","dishonest","The journalist uncovered evidence that corrupt officials had diverted public funds into private accounts.","記者找到證據，顯示貪汙官員將公款轉入私人帳戶。","corrupt 在此特指濫用公權謀私；dishonest 範圍較廣。"]],"l5-0241":[["名詞：忠告；建議","advice / guidance","She sought her mentor's counsel before accepting a role that would require frequent travel.","她在接受一份需要頻繁出差的職務前，先徵詢導師的意見。",""]],"l5-0242":[["名詞：輔導員","adviser","The school counselor helped him explore career options that matched his interests and practical skills.","學校輔導員幫助他探索符合興趣與實作能力的職業選擇。","adviser 泛指提供建議者；counselor 可具有專門輔導職責。"]],"l5-0243":[["形容詞：溫暖舒適的","snug / comfortable","With a small fire and soft blankets, the cabin felt cozy despite the storm outside.","雖然外頭風雨交加，微微爐火與柔軟毛毯讓小木屋十分溫暖舒適。",""]],"l5-0244":[["副詞：逆時針地","anticlockwise","She turned the lid counterclockwise and lifted it carefully to avoid spilling the paint.","她逆時針轉開蓋子，再小心提起，以免油漆灑出。","counterclockwise 常見於美式；anticlockwise 常見於英式。"]],"l5-0245":[["名詞：折價券","voucher","The cashier applied the coupon before calculating the delivery charge for the washing machine.","收銀員先套用折價券，再計算洗衣機的運費。","voucher 可指抵用券，範圍較廣；本句為折抵購物金額。"]],"l5-0246":[["名詞：庭院；院落","court","Guests ate breakfast in a shaded courtyard surrounded by stone walls and flowering vines.","客人在一座有遮蔭的庭院吃早餐，庭院四周是石牆與開花藤蔓。","court 的院落義較正式，常見於建築名稱。"]],"l5-0247":[["形容詞：怯懦的","craven","He regretted his cowardly silence when a colleague was unfairly blamed for the missing files.","一位同事因檔案遺失而受到不公平的責備時，他因怯懦保持沉默，事後很後悔。","cowardly 常見用法為形容詞；副詞用法屬舊式或文學語體。craven 較正式且帶強烈貶意。"]],"l5-0248":[["名詞：薄脆餅乾","無直接同義詞","She arranged cheese, sliced apples, and crackers on a wooden board for the arriving guests.","她把乳酪、蘋果切片和薄脆餅乾擺在木板上，招待即將抵達的客人。","cracker 在此是通常不甜的薄脆餅乾；不同於爆竹義。"]],"l5-0249":[["名詞：火山口","無直接同義詞","From the viewing platform, visitors could see steam rising from the crater far below.","遊客從觀景平台可以看見遠處下方的火山口冒出蒸氣。","crater 也可指撞擊形成的坑；本例採火山口義。"]],"l5-0250":[["不及物動詞：發出嘎吱聲","squeak","The wooden stairs creaked under his weight as he carried the suitcase to the attic.","他提著行李箱走向閣樓，木樓梯承受他的重量，發出嘎吱聲。","creak 多為摩擦或受力的拖長聲；squeak 通常較尖。"]],"l5-0251":[["名詞：小溪","stream / brook","We crossed the shallow creek on stepping stones and followed the path into the orchard.","我們踩著踏腳石越過淺溪，沿小路走進果園。",""]],"l5-0252":[["名詞：嬰兒床","cot","She lowered the sleeping baby into the crib and switched off the bedside lamp.","她輕輕把熟睡的嬰兒放進嬰兒床，關掉床頭燈。","嬰兒床義美式常用 crib，英式常用 cot。"]],"l5-0253":[["名詞：鱷魚","無直接同義詞","A crocodile lay motionless beside the river while birds searched for insects along the bank.","一隻鱷魚靜靜趴在河邊，鳥兒沿著河岸找昆蟲。","crocodile 與 alligator 是不同類群，不作精確同義詞。"]],"l5-0254":[["名詞：行人穿越道","crosswalk","The driver slowed as two children approached the crossing outside the primary school.","兩個孩子走近小學外的行人穿越道時，駕駛減速了。","本例為 pedestrian crossing；crosswalk 常見於美式。"]],"l5-0255":[["不及物動詞：蹲伏","squat","The photographer crouched behind a low wall to capture the fox without disturbing it.","攝影師蹲伏在矮牆後，拍攝狐狸而不打擾牠。","crouch 可包含向前彎身壓低姿勢；squat 特別指屈膝蹲下。"]],"l5-0256":[["不及物動詞：發出嘎吱碎裂聲","無直接同義詞","Frozen leaves crunched beneath our boots as we walked along the empty forest path.","我們沿著空無一人的林間小徑行走，結凍的樹葉在靴底發出嘎吱聲。",""]],"l5-0257":[["名詞：水晶","無直接同義詞","The jeweler held the piece of clear crystal against the light to examine a tiny crack.","珠寶商把那塊透明水晶對著光，檢查一道細小裂痕。",""]],"l5-0258":[["名詞：某地區的料理；烹調風格","cooking","The restaurant introduces visitors to regional cuisine through a menu based on local seafood and seasonal vegetables.","餐廳以當地海鮮和當季蔬菜設計菜單，向遊客介紹地方料理。","cuisine 常指特定地區或風格的烹調傳統；cooking 較廣。"]],"l5-0259":[["名詞：路緣；人行道邊石","kerb","He moved the bicycle away from the curb so passengers could step off the bus safely.","他把自行車從路緣移開，讓乘客可以安全下公車。","美式 curb；英式 kerb。"]],"l5-0260":[["名詞：貨幣","money","Travelers exchanged their remaining local currency before boarding the ferry to the neighboring country.","旅客登上前往鄰國的渡輪前，兌換了剩餘的當地貨幣。","currency 側重特定國家或地區使用的貨幣；money 較廣。"]],"l5-0261":[["名詞：學校課程；課程內容","無直接同義詞","The school revised its science curriculum to include more experiments and fewer exercises based on memorization.","學校修訂自然科課程，增加實驗，減少以背誦為主的練習。","curriculum 指整體課程安排或內容；syllabus 常指單門課的綱要。"]],"l5-0262":[["名詞：咖哩料理","無直接同義詞","The vegetable curry simmered gently while she prepared rice and sliced cucumbers for the table.","蔬菜咖哩正慢慢燉煮，她則準備白飯與黃瓜切片上桌。",""]],"l5-0263":[["名詞：海關","無直接同義詞","At customs, an officer asked him to open the suitcase containing samples for the trade fair.","在海關，一名官員請他打開裝有商展樣品的行李箱。","海關義固定使用 customs；不等於單數 custom（習俗）。"]],"l5-0264":[["名詞：飛鏢","無直接同義詞","Her first dart landed near the edge of the board, but the next struck the center.","她第一支飛鏢射在鏢靶邊緣附近，下一支卻命中中心。",""]],"l5-0265":[["及物動詞：使目眩","blind","Sunlight reflected from the wet pavement dazzled him as he stepped out of the dark tunnel.","他走出幽暗隧道時，濕路面反射的陽光讓他目眩。","blind 在此指強光使人暫時看不清楚，語氣較強。"]],"l5-0266":[["不及物動詞：腐朽；腐爛","rot / decompose","The fence posts had begun to decay where they were in constant contact with damp soil.","圍籬柱長期接觸潮濕土壤的部位已開始腐朽。",""]],"l5-0267":[["及物動詞：欺騙","mislead / fool","The seller deceived buyers by hiding scratches beneath labels and claiming the equipment was new.","賣家把刮痕藏在標籤下，聲稱器材是新的，藉此欺騙買家。",""]],"l5-0268":[["名詞：宣言；正式聲明","statement / announcement","The union issued a declaration explaining why its members had rejected the proposed working conditions.","工會發表聲明，解釋會員為何拒絕提議的工作條件。",""]],"l5-0269":[["名詞：代表","representative","Each village sent a delegate to discuss how the shared irrigation system should be maintained.","每個村莊派出一位代表，討論共用灌溉系統應如何維護。",""]],"l5-0270":[["名詞：代表團","deputation","A delegation of local farmers met the minister to request better access to regional markets.","當地農民組成的代表團會見部長，要求改善進入區域市場的管道。","deputation 較正式，常指奉派提出請求或意見的代表團。"]],"l5-0271":[["名詞：民主制度的支持者","無直接同義詞","As a committed democrat, she argued that residents should have a voice in choosing their leaders.","她堅定支持民主，主張居民應有權參與選擇領導者。","小寫 democrat 指民主支持者；大寫 Democrat 可指特定民主黨的黨員。"]],"l5-0272":[["名詞：否認","disavowal","His denial of involvement failed to explain why the missing document had been found in his desk.","他否認涉入此事，卻無法解釋為何遺失的文件會在他書桌裡被找到。","disavowal 較正式，可表示否認與某事有關。"]],"l5-0273":[["形容詞：描述性的","無直接同義詞","The editor asked for more descriptive details so readers could picture the crowded harbor at dawn.","編輯要求增加描述細節，讓讀者能想像黎明時擁擠的港口。",""]],"l5-0274":[["名詞：絕望","hopelessness","A sense of despair settled over the team when the rescue helicopter disappeared into thick fog.","救援直升機消失在濃霧裡時，團隊籠罩在一股絕望感中。",""]],"l5-0275":[["及物動詞：鄙視；厭惡","scorn / detest","She despised the manager's habit of taking credit for ideas that his staff had developed.","她厭惡經理把員工想出的點子據為己功的習慣。","despise 包含輕蔑；detest 著重強烈厭惡。"]],"l5-0276":[["名詞：目的地","無直接同義詞","After two ferry rides and a steep climb, we finally reached our destination above the bay.","搭了兩趟渡輪、爬上一段陡坡後，我們終於抵達海灣上方的目的地。",""]],"l5-0277":[["名詞：命運","fate","The novel follows a young musician who believes leaving her village will change her destiny.","這本小說描寫一位年輕音樂家，她相信離開村莊能改變命運。",""]],"l5-0278":[["形容詞：有破壞力的","damaging / devastating","The destructive storm tore roofs from houses and left fishing boats scattered across the waterfront.","這場破壞力強大的暴風雨掀走屋頂，讓漁船散落在濱水區各處。","devastating 強調造成極嚴重破壞。"]],"l5-0279":[["名詞：奉獻；投入","dedication / commitment","Her devotion to the community library kept the reading program running through years of financial difficulty.","她對社區圖書館的投入，讓閱讀計畫在多年財務困境中仍持續運作。",""]],"l5-0280":[["及物動詞：狼吞虎嚥地吃","wolf down / gobble up","The hungry hikers devoured the sandwiches before anyone remembered to take a photograph of lunch.","還沒有人想起要拍午餐照，飢餓的健行者就把三明治吃光了。",""]],"l5-0281":[["名詞：方言","無直接同義詞","The director asked local actors to speak in their own dialect to make the dialogue more convincing.","導演請當地演員用自己的方言說話，讓對白更有說服力。","dialect 可包含詞彙與文法差異；accent 主要是口音。"]],"l5-0282":[["名詞：不敢相信；懷疑","incredulity","She stared at the winning ticket in disbelief before asking someone else to check the numbers.","她難以置信地盯著中獎彩券，接著請別人幫忙核對號碼。",""]],"l5-0283":[["名詞：被丟棄的物品","castoff / reject","The sculptor searched through the workshop's discards for pieces of metal that could become wings.","雕塑家翻找工坊丟棄的物品，尋找能製成翅膀的金屬片。","名詞 discard 指丟棄之物或棄牌，重音在首音節；表示丟棄動作時常用動詞。"]],"l5-0284":[["名詞：門徒；追隨者","follower / pupil","The philosopher's disciples continued meeting in the garden to discuss his teachings after his death.","哲學家去世後，他的門徒仍繼續在花園聚會，討論他的教誨。","disciple 強調追隨某人的思想或教導，不只是一般學生。"]],"l5-0285":[["不及物動詞：歧視","無直接同義詞","The organization challenged employers who rejected qualified applicants because of their age, arguing that this discriminated against older workers.","該組織反對雇主因年齡拒絕合格求職者的做法，認為這歧視了年長勞工。","discriminate against someone；此義不是中性的辨別。"]],"l5-0286":[["及物動詞：分發；供給","distribute / give out","The machine dispenses reusable cups after customers place a small deposit in the payment slot.","顧客將少量押金投入付款口後，機器就會提供可重複使用的杯子。",""]],"l5-0287":[["動詞片語：丟棄；處理掉","discard / get rid of","The workshop uses separate containers to dispose of metal scraps without mixing them with ordinary waste.","工坊使用不同容器處理金屬廢料，避免與一般垃圾混在一起。","本義為 dispose of；不可省略 of。discard 後直接接受詞。"]],"l5-0288":[["名詞：差別；區別","difference","The guide explained the distinction between a restored building and one reconstructed from old photographs.","導覽員解釋修復的建築與依老照片重建的建築之間的差別。",""]],"l5-0289":[["形容詞：獨特而易辨認的","無直接同義詞","The bird's distinctive call helped us locate it among the thick branches above the trail.","那隻鳥獨特的叫聲幫我們在步道上方茂密的枝葉間找到牠。","distinctive 強調足以區別、辨認的特色。"]],"l5-0290":[["名詞：痛苦；苦惱","anguish / suffering","The loss of the family photographs caused her more distress than the damage to the furniture.","家庭照片遺失帶給她的痛苦，比家具損壞還大。",""]],"l5-0291":[["名詞：文件","record / paper","The archivist placed the fragile document in a protective sleeve before carrying it to the reading room.","檔案管理員先把易損壞的文件放進保護套，再帶到閱覽室。","本例為紙本文件；document 也可指電子文件。"]],"l5-0292":[["名詞：門前台階","無直接同義詞","A basket of fresh vegetables appeared on our doorstep while we were away visiting friends.","我們外出拜訪朋友時，一籃新鮮蔬菜出現在家門前的台階上。",""]],"l5-0293":[["名詞：門口；門洞","entrance","He paused in the doorway to let a nurse push the equipment cart into the room.","他在門口停下，讓護理師把器材推車推進房間。","doorway 指門所在的開口；entrance 可泛指入口。"]],"l5-0294":[["名詞：學生宿舍","dorm / residence hall","The university opened a new dormitory within walking distance of the library and science laboratories.","大學啟用一棟新學生宿舍，從那裡步行即可抵達圖書館和自然科學實驗室。","dorm 是 dormitory 的非正式縮略語。"]],"l5-0295":[["名詞：生麵團","無直接同義詞","She kneaded the dough until it felt smooth, then covered the bowl with a clean cloth.","她把麵團揉到光滑，再用乾淨的布蓋住碗。","dough 是可揉塑的麵團；batter 通常較稀、可倒流。"]],"l5-0296":[["副詞：向下","down","The path slopes downward toward the river, becoming steeper beyond the last row of houses.","小路向河邊下斜，越過最後一排房屋後變得更陡。","向下的副詞可用 downward 或 downwards。"]],"l5-0297":[["名詞：窗簾；垂簾","curtain","Heavy drapes blocked the afternoon sun and kept the rehearsal room pleasantly dim.","厚重的窗簾擋住午後陽光，讓排練室保持宜人的昏暗。","窗簾義常用複數 drapes，尤指較厚重的布簾。"]],"l5-0298":[["形容詞：糟透的；令人難受的","awful / terrible","The soup tasted dreadful because someone had mistaken the sugar jar for the salt container.","有人把糖罐誤當成鹽罐，讓湯變得難喝極了。","dreadful 表事物令人不快或可怕，並非人感到畏懼的 afraid。"]],"l5-0299":[["名詞：抽屜櫃；衣物櫃","chest of drawers / bureau","She moved the dresser away from the window so its wooden surface would not fade in the sun.","她把抽屜櫃移離窗邊，以免木製表面被陽光曬到褪色。","本例採美式衣物抽屜櫃義，可能附鏡子；英式 dresser 也可指餐具櫥。"]],"l5-0300":[["名詞：沙拉醬","salad dressing","He served the salad dressing in a small jug so guests could add as much as they liked.","他把沙拉醬裝在小壺裡端上桌，讓客人依喜好取用。","salad dressing 是本義的完整名稱；不等於所有 sauce。"]],"l5-0301":[["名詞：住宅的私人車道","drive","The delivery van stopped in the driveway while we cleared a space inside the garage.","我們清出車庫裡的一塊空間時，送貨車停在私人車道上。","drive 的私人車道義常見於英式。"]],"l5-0302":[["名詞：持續時間","length","The technician recorded the duration of each test to compare how quickly the batteries lost power.","技術員記錄每次測試的持續時間，比較電池耗電的速度。","length 在此是時間長度。"]],"l5-0303":[["名詞：黃昏；暮色初臨時","twilight / nightfall","At dusk, the fishermen returned to shore and began unloading baskets beneath the harbor lights.","黃昏時，漁民回到岸邊，開始在港口燈光下卸下籃子。","twilight 可指日出前或日落後微光；本句 dusk 為晚間。"]],"l5-0304":[["名詞：童話中的矮人","無直接同義詞","The dwarf in the story carved a secret passage through the mountain with a silver hammer.","故事中的矮人用一把銀錘，在山裡鑿出一條秘密通道。","本例指奇幻角色；不能把 dwarf 當作稱呼身材矮小者的隨意綽號。"]],"l5-0305":[["不及物動詞：居住","live / reside","For many years, the poet dwelt in a cottage overlooking the marshes outside the village.","這位詩人多年住在村外一間俯瞰沼澤的小屋裡。","dwell 較文學或正式；過去式 dwelt，也可用 dwelled。"]],"l5-0306":[["名詞：住所","home / residence","The old mill became a comfortable dwelling after its owners installed windows and repaired the roof.","屋主安裝窗戶並修好屋頂後，老磨坊成了一處舒適的住所。",""]],"l5-0307":[["名詞：日食或月食","無直接同義詞","During the lunar eclipse, students watched the moon change color through telescopes set up in the schoolyard.","月食期間，學生透過架設在校園裡的望遠鏡，觀察月亮顏色的變化。",""]],"l5-0308":[["名詞：鰻魚","無直接同義詞","An eel slipped between the rocks and vanished before the underwater camera could follow it.","一條鰻魚鑽進岩石縫，在水下攝影機跟上之前就消失了。",""]],"l5-0309":[["名詞：自尊心；自負","pride / self-importance","His ego made it difficult for him to admit that the youngest assistant had solved the problem.","他的自負讓他難以承認，解決問題的是最年輕的助理。","ego 在此指過度自我重視；其他語境也可中性地指自我。"]],"l5-0310":[["形容詞：精心製作且繁複的","intricate / ornate","The costume featured elaborate embroidery that took the designer several weeks to complete.","這套戲服有繁複精緻的刺繡，設計師花了好幾週才完成。",""]],"l5-0311":[["及物動詞：抬高","raise / lift","Workers elevated the platform slightly so people at the back could see the speaker clearly.","工人把平台略微抬高，讓後方的人能清楚看見講者。",""]],"l5-0312":[["及物動詞：擁抱","hug","She embraced her father at the airport after spending almost a year working overseas.","在海外工作將近一年後，她在機場擁抱父親。",""]],"l5-0313":[["不及物動詞：努力；盡力","strive / try","The restoration team endeavored to preserve the original colors while repairing the damaged ceiling paintings.","修復團隊修補受損的天花板畫作時，努力保留原有色彩。","endeavor to do something 較正式；英式常拼 endeavour。"]],"l5-0314":[["不及物動詞：註冊；報名","register / sign up","He enrolled in an evening photography course to learn how to use the camera he had inherited.","他報名晚間攝影課，學習使用繼承來的相機。","enroll in a course；sign up for a course。"]],"l5-0315":[["名詞：註冊；報名","registration","Enrollment for the summer workshops opens next Monday, and places will be assigned in order of registration.","暑期工作坊下週一開放報名，將依註冊順序分配名額。","本句為報名作業義；enrollment 另可表示入學或註冊總人數。"]],"l5-0316":[["及物動詞：ensure，確保","guarantee","The coordinator checked every reservation to ensure that no participant would arrive without a place to stay.","協調員核對每筆訂房，確保所有參與者抵達時都有地方住宿。","ensure 表確保；insure 在部分美式用法也有此義，但常用於保險。"],["及物動詞：insure，為物品投保","無直接同義詞","The gallery insured the paintings before sending them abroad for a six-month exhibition.","畫廊先為畫作投保，再送往海外參加為期六個月的展覽。","此保險義不可用 ensure 直接替代。"]],"l5-0317":[["名詞：企業；公司","business / company","The bakery began as a family enterprise and now supplies bread to restaurants throughout the district.","這家麵包店最初是家族企業，如今供應整個地區餐廳的麵包。",""]],"l5-0318":[["形容詞：熱衷的；熱情的","eager / keen","The children were enthusiastic about building a small weather station in the school garden.","孩子們很熱衷於在學校花園裡建造一座小型氣象站。","enthusiastic about；keen on；eager to build 需改句型。"]],"l5-0319":[["及物動詞：使有資格或權利","qualify","The membership card entitles visitors to a discount on workshops held at the museum.","這張會員卡讓訪客享有博物館工作坊的折扣。","entitle someone to something；qualify someone for something，介系詞不同。"]],"l5-0320":[["及物動詞：把兩者等同","identify","She warned students not to equate a high salary with a satisfying career.","她提醒學生，不要把高薪與令人滿意的職涯畫上等號。","equate A with B；identify A with B 在此可指把兩者視為一樣。"]],"l5-0321":[["及物動詞：搭建；豎立","put up / construct","Volunteers erected a large tent beside the playing field before the charity concert began.","慈善音樂會開始前，志工在運動場旁搭起一座大帳篷。",""]],"l5-0322":[["不及物動詞：火山噴發","無直接同義詞","The volcano erupted during the night, sending a column of ash high above the surrounding villages.","火山在夜裡噴發，向周圍村莊上方的高空噴出一道火山灰柱。","explode 不必涉及火山物質噴出，不能精確取代。"]],"l5-0323":[["名詞：陪同者；護送者","attendant","The visitor's escort waited outside the secure room while the archivist brought out the requested documents.","檔案管理員取出所需文件時，訪客的陪同人員在受管制的房間外等候。","本例為陪同人員；escort 不一定指保鑣。"]],"l5-0324":[["名詞：遺產；身後留下的財產","無直接同義詞","Her estate included a small orchard, several paintings, and the house where she had spent her childhood.","她留下的遺產包括一座小果園、幾幅畫，以及童年居住的房子。","estate 在此指死者留下的整體財產，不只是不動產。"]],"l5-0325":[["名詞：尊重；敬重","respect / regard","The retiring teacher was held in high esteem by generations of students and their families.","這位即將退休的老師深受好幾代學生及其家人敬重。",""]],"l5-0326":[["形容詞：永恆的；無盡的","everlasting / endless","In the legend, the hidden valley remained in eternal spring while winter covered the surrounding mountains.","傳說中，周圍山區被寒冬籠罩時，隱密的山谷依然永遠停留在春天。",""]],"l5-0327":[["名詞：ethics，道德規範","moral principles","The journalism course examines ethics through discussions of privacy, accuracy, and the treatment of vulnerable interviewees.","新聞課透過討論隱私、準確性與如何對待弱勢受訪者，探討道德規範。","moral principles 是解說性近義片語。"],["名詞：ethic，某種行為準則","無直接同義詞","A strong work ethic helped the apprentices maintain high standards even during the busiest weeks.","強烈的工作責任感讓學徒即使在最忙的幾週也維持高標準。","work ethic 指重視勤奮與盡責的工作態度；work principle 並非本片語的自然替換。"]],"l5-0328":[["名詞：常綠樹","無直接同義詞","A row of evergreens sheltered the farmhouse from cold winds blowing across the open fields.","一排常綠樹替農舍擋住吹過空曠田野的寒風。","常綠植物不一定是 conifer（針葉樹）。"]],"l5-0329":[["名詞：誇張；誇大","overstatement","His claim that the queue stretched for miles was an exaggeration, although the wait was certainly long.","他說隊伍綿延好幾英里，是誇大其詞，不過等待的時間確實很長。",""]],"l5-0330":[["及物動詞：超過","surpass / go beyond","The final repair bill exceeded our estimate because several hidden leaks were discovered behind the kitchen walls.","因為廚房牆後又發現幾處隱藏漏水，最後的修繕費超出我們的估計。",""]],"l5-0331":[["不及物動詞：擅長；表現出色","shine","She excels at explaining difficult concepts with simple diagrams that younger students can understand.","她很擅長用年紀較小的學生能懂的簡單圖解，說明困難概念。","excel at 或 in；shine 較口語，強調出色表現。"]],"l5-0332":[["形容詞：傑出的；特別優異的","outstanding / remarkable","The young violinist showed exceptional control during a demanding solo that left the audience silent.","這位年輕小提琴家在高難度獨奏中展現出色的控制力，讓觀眾安靜下來。","本句採優異義；exceptional 也可指異常或例外。"]],"l5-0333":[["名詞：過量；多餘的部分","surplus","An excess of fertilizer washed into the pond after heavy rain, affecting the water quality.","大雨過後，過量肥料被沖進池塘，影響水質。",""]],"l5-0334":[["及物動詞：驚呼；喊出","cry out","She exclaimed that the missing ring was under the table, and everyone rushed over to look.","她驚呼遺失的戒指就在桌子下，大家便趕過去看。",""]],"l5-0335":[["及物動詞：排除；不包括","leave out / omit","The price excludes delivery, so customers outside the city must ask for a separate shipping estimate.","價格不含運送費，因此城外顧客必須另行詢問運費估價。",""]],"l5-0336":[["及物動詞：執行；完成","無直接同義詞","The crew executed the emergency drill smoothly, despite having only a few minutes to prepare.","儘管只有幾分鐘準備，工作人員仍順利完成緊急演練。",""]],"l5-0337":[["名詞：企業高階主管","senior manager","The executive visited the factory floor to hear workers' concerns about the proposed production schedule.","這位高階主管走訪工廠現場，聽取工人對擬議生產時程的顧慮。",""]],"l5-0338":[["名詞：流亡；放逐","無直接同義詞","The writer spent years in exile, publishing essays about the homeland he could no longer visit.","這位作家流亡多年，發表文章描寫自己已無法回去的故鄉。","banishment 特指被迫放逐；exile 也可因危險而自行離國，本句未交代離國原因。"]],"l5-0339":[["名詞：延長；延期","prolongation","The student requested an extension because the archive she needed for her research had temporarily closed.","研究所需的檔案館暫時關閉，因此這名學生申請延期。","此處為期限延長；prolongation 較正式。"]],"l5-0340":[["形容詞：廣泛的；大規模的","wide-ranging","The report draws on extensive research into housing, transport, and education across the region.","這份報告根據對區域內住房、交通及教育的廣泛研究撰寫。","extensive 強調涵蓋範圍大；本句研究多個領域，可用 wide-ranging。"]],"l5-0341":[["形容詞：外部的；建築外側的","outer / outside","The builders repaired the exterior walls before replacing the damaged floors inside the house.","建築工人先修補外牆，再更換屋內損壞的地板。",""]],"l5-0342":[["形容詞：外來的；外部的","outside","The committee invited an external reviewer to assess the proposal and identify any overlooked weaknesses.","委員會邀請外部審查者評估提案，找出可能被忽略的弱點。",""]],"l5-0343":[["形容詞：滅絕的","無直接同義詞","The museum's new exhibition uses fossils to show how the extinct animal moved and fed.","博物館的新展覽運用化石，呈現這種已滅絕動物如何移動與進食。","extinct 指物種已無存活個體；endangered 是瀕危，意思不同。"]],"l5-0344":[["形容詞：非凡的；令人驚奇的","remarkable / astonishing","Her extraordinary memory allowed her to recognize former students even after several decades had passed.","即使數十年過去，她仍憑非凡記憶力認出以前的學生。",""]],"l5-0345":[["名詞：睫毛","lash","A tiny snowflake landed on his eyelash and melted as soon as he stepped inside.","一片小雪花落在他的睫毛上，他一走進室內便融化了。",""]],"l5-0346":[["名詞：眼瞼；眼皮","lid","Her eyelids grew heavy during the lecture after a long night of caring for her baby.","整夜長時間照顧嬰兒後，她上課時眼皮漸漸沉重起來。","lid 在眼睛語境可指 eyelid。"]],"l5-0347":[["名詞：布料","cloth / material","The tailor chose a light fabric that would keep its shape without making the summer jacket too warm.","裁縫選用輕薄而能維持版型的布料，讓夏季外套不會太悶熱。",""]],"l5-0348":[["名詞：一時的流行","craze","The toy became a brief fad, filling shop windows before disappearing from most children's wish lists.","這種玩具曾短暫風靡，擺滿商店櫥窗，後來卻從多數孩子的願望清單消失。","fad 強調流行短暫，不等於所有 fashion。"]],"l5-0349":[["形容詞：華氏的","無直接同義詞","The old oven displayed Fahrenheit temperatures, so she converted the recipe's Celsius setting before baking.","這台舊烤箱顯示華氏溫度，因此她烘烤前先換算食譜上的攝氏設定值。","Fahrenheit 指溫標或華氏的，並非溫度計本身。"]],"l5-0350":[["不及物動詞：說話變得不流暢；聲音不穩","waver","His voice faltered when he reached the part of the speech about his late teacher.","演講說到已故老師時，他的聲音變得斷斷續續。","此處為聲音因情緒而不穩，不是步伐蹣跚。"]],"l5-0351":[["及物動詞：使著迷","captivate / intrigue","The intricate gears inside the clock fascinated the child, who watched the repairer for nearly an hour.","時鐘裡繁複的齒輪讓孩子著迷，他看著修理師傅工作將近一小時。",""]],"l5-0352":[["名詞：極度疲勞","exhaustion / weariness","Fatigue slowed the climbers as they made their way back to camp through deep snow.","登山者穿過深雪返回營地時，疲憊拖慢了他們的腳步。",""]],"l5-0353":[["形容詞：聯邦政府的","無直接同義詞","The state applied for federal funding to repair bridges damaged by the spring floods.","該州申請聯邦經費，修復春季洪水損壞的橋梁。","federal 專指聯邦層級；不與所有 national 或 central 用法等同。"]],"l5-0354":[["形容詞：微弱的；無力的","weak / faint","A feeble beam from the dying flashlight barely reached the far end of the tunnel.","快沒電的手電筒發出微弱光束，勉強照到隧道另一端。",""]],"l5-0355":[["形容詞：帶傳統女性風格的","無直接同義詞","The designer gave the jacket a feminine shape by softening the shoulders and narrowing the waist.","設計師柔化肩線、收窄腰身，讓外套帶有傳統女性服裝的線條。","本例描述服裝風格；womanly 較常形容人的特質，不能直接套用本搭配。"]],"l5-0356":[["名詞：肥料","無直接同義詞","The gardener stored the fertilizer in a dry shed and labeled each bag with its contents.","園丁把肥料存放在乾燥的棚屋裡，並在每袋標明內容物。","manure 是肥料的一種，不是 fertilizer 的完整同義詞。"]],"l5-0357":[["名詞：未婚夫","無直接同義詞","She and her fiancé chose a small seaside restaurant for their wedding reception.","她與未婚夫選了一家海邊小餐廳舉辦婚宴。","fiancé 通常指已訂婚的男性；未婚妻拼 fiancée。"]],"l5-0358":[["名詞：未婚妻","無直接同義詞","He asked his fiancée to help choose the music for the ceremony they were planning together.","他請未婚妻協助挑選兩人共同籌劃的典禮音樂。",""]],"l5-0359":[["名詞：纖維","filament / strand","Under the microscope, a single fiber from the blanket looked like a rough, twisted rope.","在顯微鏡下，毛毯的一根纖維看起來像粗糙扭曲的繩子。","本句為細絲狀材料，不是膳食纖維；英式拼 fibre。"]],"l5-0360":[["名詞：小提琴","violin","He played lively tunes on his fiddle while the dancers gathered in the village hall.","舞者聚集在村莊禮堂時，他拉小提琴演奏輕快的曲調。","fiddle 較口語，常見於民俗音樂語境，樂器本身仍是 violin。"]],"l5-0361":[["名詞：濾網；過濾器","無直接同義詞","The mechanic removed the dusty filter and held it up to show why the airflow had weakened.","技師拆下積灰的濾網，舉起來說明氣流為何變弱。",""]],"l5-0362":[["名詞：魚鰭","無直接同義詞","A silver fin broke the surface just beyond the boat before the fish vanished again.","船外不遠處，一片銀色魚鰭露出水面，魚隨後又消失了。",""]],"l5-0363":[["名詞：漁場","fishing ground","The coastal fishery supports several villages whose boats return each morning with fresh catches.","這處沿海漁場維繫著幾個村莊的生計，村裡的船每天早上載著新鮮漁獲返回。","本例為捕魚水域；fishery 也可表示漁業或養殖場。"]],"l5-0364":[["名詞：薄片","thin fragment","A flake of old paint fell from the ceiling while we were moving the bookshelves.","我們搬動書架時，一小片舊油漆從天花板掉了下來。","thin fragment 是解說性片語，表示剝落的一小片。"]],"l5-0365":[["及物動詞：拍動翅膀","beat","The pigeon flapped its wings twice before rising from the windowsill and circling above the square.","鴿子拍了兩下翅膀，從窗台飛起，在廣場上方盤旋。",""]],"l5-0366":[["名詞：缺陷；瑕疵","defect / imperfection","The inspector found a small flaw in the glass that could weaken the entire panel.","檢查員在玻璃上發現一個小瑕疵，可能削弱整片玻璃的強度。",""]],"l5-0367":[["名詞：輕彈；快速輕揮的動作","無直接同義詞","With a quick flick of his wrist, the magician sent the coin spinning across the table.","魔術師手腕迅速一揮，硬幣便旋轉著滑過桌面。",""]],"l5-0368":[["及物動詞：翻轉","turn over","She flipped the pancake when bubbles appeared on its surface and the edges looked firm.","鬆餅表面冒出氣泡、邊緣看起來凝固時，她把鬆餅翻面。",""]],"l5-0369":[["不及物動詞：興盛；蓬勃生長","thrive / prosper","Small bookstores flourished in the neighborhood after the university opened a new campus nearby.","大學在附近啟用新校區後，這個街區的小書店蓬勃發展。",""]],"l5-0370":[["名詞：語言流利度","無直接同義詞","Her fluency improved as she began discussing everyday topics with classmates instead of rehearsing memorized answers.","她開始與同學討論日常話題，不再只練習背好的答案，語言流利度因此提升。","fluency 著重表達流暢；proficiency 指整體熟練程度，範圍較廣。"]],"l5-0371":[["名詞：敵人；對手","enemy / adversary","The two former foes eventually worked together to rebuild the market damaged during their dispute.","這兩個昔日的敵手最後合作，重建了衝突期間受損的市場。","foe 較文學或正式。"]],"l5-0372":[["名詞：金屬箔","無直接同義詞","He covered the dish with aluminum foil to keep the vegetables warm while the bread finished baking.","麵包還在烤，他用鋁箔蓋住餐盤，讓蔬菜保溫。","本例為廚房常用的鋁箔；foil 泛指薄金屬片。"]],"l5-0373":[["名詞：民間傳說與習俗","無直接同義詞","The festival draws on local folklore, including stories about river spirits and the first fishing families.","這個節慶取材自當地民間傳說，包括河神與最早捕魚家族的故事。","folklore 包含傳說、信仰及習俗；legend 只是一種傳說。"]],"l5-0374":[["形容詞：健忘的","absentminded","He had become forgetful lately, so he kept a small notebook beside the telephone.","他最近變得健忘，因此在電話旁放了一本小筆記本。","absentminded 常因心不在焉而忘事；forgetful 不限定原因。"]],"l5-0375":[["名詞：編排形式；格式","layout / arrangement","The new report format places the main findings first and moves detailed tables to the appendix.","新的報告格式把主要發現放在前面，將詳細表格移到附錄。",""]],"l5-0376":[["形容詞：氣味難聞的","offensive / unpleasant","A foul smell drifted from the blocked drain and spread through the ground-floor hallway.","堵塞的排水管飄出惡臭，瀰漫一樓走廊。","foul 在此強調極難聞；unpleasant 語氣較弱。"]],"l5-0377":[["名詞：家禽","poultry","The farmer moved the fowl into a covered enclosure before the cold rain reached the valley.","冷雨抵達山谷前，農夫把家禽移進有遮蓋的圍欄區。","此處 fowl 作集合意義，指飼養的禽鳥。"]],"l5-0378":[["名詞：數學上的分數","無直接同義詞","She converted the fraction to a decimal before entering the result into the spreadsheet.","她先把分數換成小數，再將結果輸入試算表。",""],["名詞：極少量；小部分","small part","The repairs cost only a fraction of what replacing the entire machine would have cost.","修理費只占更換整台機器所需費用的一小部分。","small part 是本句的解說性對應。"]],"l5-0379":[["名詞：架構；基本骨架","structure / frame","The builders assembled the steel framework before adding the walls and glass roof of the greenhouse.","建築工人先組裝鋼骨架，再加上溫室的牆壁與玻璃屋頂。",""]],"l5-0380":[["形容詞：焦急慌亂的","panicked / desperate","The parents made a frantic search of the station before finding their child beside the information desk.","父母焦急地找遍車站，最後在服務台旁找到孩子。",""]],"l5-0381":[["名詞：貨物；貨運","cargo / shipment / transport","The company specializes in international freight.","該公司專門經營國際貨運。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0382":[["名詞：邊境","border / boundary","The hikers reached the frontier before sunset and showed their passports.","健行者在日落前抵達邊境並出示護照。","frontier 常指國家或已開發地區的邊界。"]],"l5-0383":[["名詞：濃烈難聞的煙氣","smoke / vapor","Workers wore respirators when toxic fumes filled the paint room.","油漆室充滿有毒煙氣時，工人都戴上呼吸器。","fume 通常指有害或刺激性的氣體。"]],"l5-0384":[["名詞：盛怒","rage / wrath","The customer shouted in fury after the airline lost her luggage.","航空公司弄丟她的行李後，這名顧客憤怒地大喊。","fury 比 anger 強烈。"]],"l5-0385":[["動詞：熔合；名詞：保險絲","melt together / safety fuse","The electrician replaced the blown fuse before restoring power to the office.","電工更換熔斷的保險絲後，才恢復辦公室供電。","本句採 fuse 的名詞義；動詞 fuse 指熔合。"]],"l5-0386":[["名詞、動詞：大驚小怪","complain noisily / make a fuss","There is no need to fuss over a small stain on the tablecloth.","不用為桌巾上的小污漬大驚小怪。","fuss over 常帶有過度操心的語氣。"]],"l5-0387":[["動詞：疾馳","race / run swiftly","The horses galloped across the meadow when the gate opened.","大門打開時，馬匹疾馳穿過草地。","gallop 專指馬等以最快步態奔跑。"]],"l5-0388":[["名詞：衣服；服裝","clothing / attire","The designer displayed a linen garment beside the matching jacket.","設計師把亞麻衣服展示在搭配的外套旁。","garment 指一件衣物；attire 通常指整體穿著。"]],"l5-0389":[["動詞：喘氣","pant","She gasped for air after climbing six flights of stairs.","她爬上六層樓梯後喘著氣。","gasp 強調突然吸氣；pant 是持續喘息。"]],"l5-0390":[["名詞：聚集；集會","meeting / assembly","The neighborhood held a small gathering to welcome the new librarian.","社區舉辦小型聚會歡迎新圖書館員。","gathering 指人們聚在一起的活動。"]],"l5-0391":[["形容詞、名詞：同性戀的；男同性戀","queer","The film follows a gay couple who run a small bookstore together.","這部電影描述一對共同經營小書店的男同性戀伴侶。","gay 是同性戀身分用語；queer 是較廣義且可能帶有重新認同色彩的用語，不一定等同 gay。用於描述人物時應尊重其自我認同。"]],"l5-0392":[["名詞：性別","無直接同義詞","The survey recorded each participant's gender for the demographic analysis.","這份調查記錄每位參與者的性別，以供人口統計分析。","gender 指社會或身分脈絡中的性別；本句採人口統計義。"]],"l5-0393":[["形容詞：地理的","geographical","The atlas provides geographic data about rainfall in each province.","這本地圖集提供各省降雨量的地理資料。","geographic 與 geographical 意義相同，前者較常見於美式英文。"]],"l5-0394":[["名詞：幾何學","無直接同義詞","Students used geometry to calculate the angles in the bridge design.","學生運用幾何學計算橋梁設計中的角度。","geometry 是研究形狀、大小與空間關係的數學分支。"]],"l5-0395":[["名詞：冰河","glacial ice","The glacier has retreated several meters since scientists began measuring it.","自科學家開始測量以來，這座冰河已後退數公尺。","glacier 是緩慢流動的大型冰體。"]],"l5-0396":[["動詞、名詞：閃耀；怒視","shine harshly / stare angrily","The guard glared at the visitor who ignored the warning sign.","那名訪客無視警告標誌，警衛便怒視著他。","本句採怒視義；強光閃耀是另一義。"]],"l5-0397":[["名詞、動詞：閃爍；一絲光線","shimmer / faint light","A gleam of sunlight slipped through the curtains at dawn.","黎明時，一絲陽光從窗簾間透進來。","gleam 可指短暫或微弱的光。"]],"l5-0398":[["名詞：快樂","delight / joy","The children shouted with glee when the magician pulled out a rabbit.","魔術師變出兔子時，孩子們開心地大叫。","glee 指明顯而興奮的喜悅。"]],"l5-0399":[["名詞、動詞：閃爍；閃光","sparkle / shine","The necklace glittered under the jewelry shop lights.","項鍊在珠寶店的燈光下閃閃發亮。","glitter 常指許多細小亮點反射光線。"]],"l5-0400":[["名詞：黑暗；憂鬱","darkness / despondency","Winter gloom lifted when the town reopened its riverside market.","小鎮重新開放河畔市場後，冬日的陰鬱一掃而空。","gloom 可指昏暗環境或低落情緒。"]],"l5-0401":[["動詞：咬；消耗","chew / wear away","Acid from the mine continued to gnaw at the metal pipes.","礦坑裡的酸液持續侵蝕金屬管線。","gnaw at 可指反覆啃咬或逐漸侵蝕。"]],"l5-0402":[["動詞：狼吞虎嚥；火雞咯咯叫","devour","He gobbled his sandwich before boarding the last train.","他在搭上末班火車前狼吞虎嚥吃完三明治。","gobble down 強調吃得又快又多。"]],"l5-0403":[["名詞：峽谷；動詞：狼吞虎嚥","ravine","The narrow gorge opened into a valley covered with pine trees.","狹窄的峽谷通往一座覆滿松樹的山谷。","本句採 gorge 的地形名詞義。"]],"l5-0404":[["形容詞：華麗的；極好的","stunning / magnificent","The hotel lobby had a gorgeous ceiling painted with gold stars.","那家飯店大廳有一座繪滿金色星星的華麗天花板。","gorgeous 是強烈的正面形容詞。"]],"l5-0405":[["名詞：大猩猩","great ape","The zoo moved its gorilla to a larger enclosure with climbing poles.","動物園把大猩猩移到有攀爬桿的較大圍欄。","gorilla 指非洲大型猿類。"]],"l5-0406":[["名詞：福音；福音書","doctrine","The preacher read a passage from the Gospel during the service.","牧師在禮拜中朗讀福音書的一段經文。","Gospel 大寫時常指基督教《福音書》。"]],"l5-0407":[["及物動詞：正式授予；給予","award / bestow","The university granted her a research fellowship for the coming year.","大學正式授予她下一年度的研究獎學金。","grant 作及物動詞時指正式授予權利、許可或資助；award 偏向頒發獎項，bestow 較正式。"]],"l5-0408":[["名詞：重力","force of gravity","Gravity pulled the dropped wrench toward the workshop floor.","重力把掉落的扳手拉向工坊地面。","gravity 是使物體互相吸引的力。"]],"l5-0409":[["動詞：吃草；放牧","brush against","The goats grazed quietly beside the stone wall.","山羊在石牆旁安靜地吃草。","本句採 graze 的放牧義；擦過是另一義。"]],"l5-0410":[["油脂；潤滑油","lubricant / machine oil","The mechanic applied grease to the bicycle chain before the test ride.","技師在試騎前將潤滑油塗在自行車鏈條上。","grease 是厚重油脂，也可作動詞表示塗油。"]],"l5-0411":[["名詞：貪心；貪婪","avarice","His greed led him to falsify the accounts and steal from the charity.","他的貪婪使他竄改帳目並偷取慈善機構的款項。","greed 指對財物或利益過度渴求。"]],"l5-0412":[["形容詞：嚴厲的；無情的","severe / harsh","The drought left farmers facing a grim financial outlook.","乾旱讓農民面臨嚴峻的財務前景。","grim 常指令人沮喪且幾乎沒有希望。"]],"l5-0413":[["名詞：緊握","hold / grasp","The climber kept a firm grip on the rope.","攀岩者緊緊握住繩索。","a firm grip on something 表示緊緊握住某物。"]],"l5-0414":[["動詞、名詞：呻吟","moan / murmur in pain","The injured cyclist groaned as the paramedic examined his ankle.","救護員檢查受傷自行車騎士的腳踝時，他痛苦地呻吟。","groan 可表痛苦、疲憊或不滿。"]],"l5-0415":[["形容詞：總的；粗略的","total / approximate","The gross cost includes labor, materials, and delivery fees.","總成本包含人工、材料與運送費。","gross 在會計語境常指扣除前的總額。"]],"l5-0416":[["動詞、名詞：嚎叫；咆哮","snarl / rumble","The dog growled when a stranger reached for its food bowl.","陌生人伸手拿牠的食盆時，那隻狗發出低沉咆哮。","growl 是低沉而具威脅性的聲音。"]],"l5-0417":[["動詞、名詞：抱怨；怨言","complain / grievance","Several passengers grumbled about the delayed departure.","幾名乘客抱怨班機延誤起飛。","grumble 比 complain 語氣較低沉、不正式。"]],"l5-0418":[["名詞：準則","guiding principle / rule","The safety guideline requires visitors to wear helmets inside the plant.","安全準則要求訪客在工廠內戴上安全帽。","guideline 是提供方向的規則，通常比 law 寬鬆。"]],"l5-0419":[["動詞、名詞：狼吞虎嚥","swallow quickly / mouthful","She gulped down water after the long run.","長跑後，她大口吞下水。","gulp down 強調快速吞嚥。"]],"l5-0420":[["名詞：強風；爆發","blast / sudden burst","A sudden gust scattered the papers across the station platform.","一陣突如其來的強風吹散了車站月台上的文件。","gust 是短促而強的風。"]],"l5-0421":[["名詞：腸子；內臟；勇氣","intestines / courage","It took real guts to report the manager’s misconduct.","舉報經理的不當行為確實需要很大的勇氣。","本句採 guts 的口語「勇氣」義。"]],"l5-0422":[["名詞：吉普賽人","Roma person","The guide explained how the term Gypsy appears in older historical records.","導覽員說明 Gypsy 一詞如何出現在較早的歷史記錄中。","Gypsy 現代使用可能被視為過時或冒犯；指族群時通常使用 Roma 或 Romani。"]],"l5-0423":[["招呼；冰雹","greet / acclaim","Dark clouds gathered as hail began striking the greenhouse roof.","烏雲聚集時，冰雹開始打在溫室屋頂上。","hail 作名詞是冰雹，作動詞也可表示呼喊或招呼。"]],"l5-0424":[["名詞：髮型","hairstyle / hairdo","Her new hairstyle was practical for working in the bakery.","她的新髮型很適合在麵包店工作。","hairdo 較口語；hairstyle 較中性。"]],"l5-0425":[["名詞：障礙；動詞：妨礙","obstacle / impede","A knee injury handicapped the runner during the final race.","膝傷在最後一場比賽中妨礙了那名跑者。","handicap 作動詞指使人處於不利位置。"]],"l5-0426":[["名詞：手工藝品","craft / handmade article","The market sells local handicrafts made from bamboo and recycled glass.","市場販售以竹子和回收玻璃製成的地方手工藝品。","handicraft 指手工製作的物品或技藝。"]],"l5-0427":[["形容詞：吃苦耐勞的；強壯的；大膽的","sturdy / resilient","The hardy plants survived the salty wind on the exposed coast.","這些耐寒植物在曝露海岸的鹹風中存活下來。","hardy 常形容能承受艱苦條件。"]],"l5-0428":[["名詞、動詞：馬具；套上馬具；利用","make use of","The trainer harnessed the horse before leading it onto the track.","訓練師替馬套上馬具後，才牽牠走上跑道。","harness 作動詞也可指有效利用資源。"]],"l5-0429":[["動詞：拖；拉；搬運","drag / transport","Workers hauled the damaged generator out of the flooded basement.","工人把損壞的發電機從淹水的地下室拖出來。","haul 強調費力搬運重物。"]],"l5-0430":[["動詞：不斷糾纏；困擾","trouble / trouble repeatedly","The memory of the accident continued to haunt him for years.","那場事故的記憶多年來一直困擾著他。","haunt 常指持續縈繞心頭的記憶或恐懼。"]],"l5-0431":[["形容詞：真誠的；熱誠的","sincere / cordial","The host gave us a hearty welcome after our long journey.","我們長途跋涉後，主人熱誠地歡迎我們。","hearty 可形容真誠熱烈的情感或歡迎，也可形容豐盛的食物。"]],"l5-0432":[["形容詞：天空的；天國的；美好的","celestial / blissful","They watched a heavenly sunset from the quiet mountain cabin.","他們在安靜的山間小屋欣賞美麗的夕陽。","heavenly 也可作比喻，表示極其美好。"]],"l5-0433":[["名詞：樹籬","shrub barrier / row of bushes","The gardener planted a hedge to screen the patio from the street.","園丁種植樹籬，遮擋露臺與街道之間的視線。","hedge 作名詞是成排灌木形成的樹籬；另有動詞「閃避明確表態」義。"]],"l5-0434":[["動詞、名詞：留意；注意","pay attention to / observe","Please heed the evacuation notice and leave through the nearest exit.","請留意疏散通知，從最近的出口離開。","heed 比 notice 正式，常接 advice、warning 或 instruction。"]],"l5-0435":[["提高；加強","raise / intensify","The dim lighting heightened the suspense in the theater.","昏暗燈光加強了劇院中的懸疑氣氛。","heighten 指使感受、程度或效果變得更強。"]],"l5-0436":[["名詞：繼承人","successor / inheritor","As the eldest heir, she inherited the family farm after her parents died.","她是長女繼承人，父母過世後繼承了家族農場。","heir 指依法或依家族關係取得財產的人。"]],"l5-0437":[["副詞：因此","therefore / consequently","The road was icy; hence, the bus service was suspended.","道路結冰，因此公車服務暫停。","hence 較正式，常用於書面語。"]],"l5-0438":[["名詞、動詞：使者；傳達","messenger / announce","The newspaper heralded the discovery as a breakthrough in medicine.","報紙宣告這項發現是醫學上的突破。","herald 作動詞常指正式宣布重要消息。"]],"l5-0439":[["名詞：藥草；草本植物","medicinal plant","The chef added fresh herbs to the soup just before serving it.","廚師在上湯前才把新鮮香草加入湯裡。","herb 可指香草或藥用草本植物。"]],"l5-0440":[["名詞：隱士","recluse / solitary","The hermit lived alone in a cabin deep in the forest.","那名隱士獨自住在森林深處的小屋裡。","hermit 強調選擇遠離社會的人。"]],"l5-0441":[["形容詞：英雄的","brave / valiant","The firefighter made a heroic effort to rescue the child from the smoke-filled room.","消防員英勇地努力把孩子從充滿煙霧的房間救出來。","heroic 可指像英雄般勇敢的行為。"]],"l5-0442":[["形容詞：異性戀的","straight","The survey asked whether respondents identified as heterosexual, gay, or bisexual.","調查詢問受訪者是否認同自己是異性戀、同性戀或雙性戀。","heterosexual 是正式中性用語。"]],"l5-0443":[["名詞：高傳真","high fidelity / hi-fi","The studio installed hi-fi speakers so listeners could hear every instrument clearly.","錄音室安裝高傳真喇叭，讓聽眾清楚聽見每件樂器。","hi-fi 是 high fidelity 的非正式縮寫。"]],"l5-0444":[["動詞、名詞：劫持","take control by force / abduction","The crew followed the emergency procedure when a passenger tried to hijack the plane.","乘客試圖劫持飛機時，機組員依照緊急程序行動。","hijack 通常指以武力奪取交通工具或控制權。"]],"l5-0445":[["動詞：發出嘶嘶（噓）聲；名詞：嘶嘶（噓）聲","sizzle","The radiator hissed as steam escaped from a loose valve.","蒸汽從鬆脫的閥門逸出時，暖氣器發出嘶嘶聲。","hiss 可指蒸汽聲、蛇聲或噓聲。"]],"l5-0446":[["形容詞：沙啞的","raspy","After three hours of singing, the announce’ voice became hoarse.","唱了三小時歌後，播報員的聲音變得沙啞。","hoarse 指聲帶疲勞或受刺激造成的粗啞聲。"]],"l5-0447":[["名詞：曲棍球","ice hockey / field hockey","Our school formed a hockey team and practiced twice a week.","我們學校組成曲棍球隊，每週練習兩次。","hockey 可指冰上或草地曲棍球，地區用法不同。"]],"l5-0448":[["形容詞、名詞：同性戀的；同性戀者","gay","The counselor created a safe support group for homosexual students.","輔導員為同性戀學生成立安全的支持團體。","homosexual 較正式；gay 通常是較自然的身分用語。"]],"l5-0449":[["名詞、動詞：汽車喇叭；鳴喇叭","car horn","The taxi driver honked twice to let the cyclist know he was passing.","計程車司機按了兩下喇叭，讓自行車騎士知道他要超車。","honk 作動詞指發出汽車喇叭聲。"]],"l5-0450":[["兜帽；罩","cowl / bonnet","She pulled the hood over her head when the rain started.","開始下雨時，她把兜帽拉到頭上。","hood 可指衣物的帽兜，也可指覆蓋機械的罩子。"]],"l5-0451":[["名詞：蹄","無直接同義詞","The farrier carefully trimmed the hors’ hoof and replaced its shoe.","馬蹄鐵匠仔細修剪馬蹄並換上蹄鐵。","hoof 是馬、牛等有蹄動物的腳端。"]],"l5-0452":[["形容詞：水平的","level","Keep the picture horizontal so it fits the wide frame.","讓圖片保持水平，才能放進寬邊框。","horizontal 與 vertical 相對。"]],"l5-0453":[["名詞：人質","captive","The police negotiated for hours to free the hostages from the bank.","警方為了救出銀行裡的人質，談判了好幾個小時。","hostage 指被扣留以迫使他人滿足要求的人；captive 範圍較廣，泛指遭囚禁者。to free 在本句表目的，未說明是否救援成功。"]],"l5-0454":[["形容詞：敵人的；有敵意的","antagonistic / unfriendly","The hostile crowd blocked the reporters from entering the building.","充滿敵意的人群阻擋記者進入大樓。","hostile 描述公開的敵對態度或環境。"]],"l5-0455":[["名詞：獵犬","hunting dog","The hound followed the fox’s trail through the wet forest.","那隻獵犬沿著狐狸的足跡穿過潮濕的森林。","hound 特指用於追蹤獵物的狗。"]],"l5-0456":[["名詞：住宅","accommodation / homes","The city is building affordable housing near the new train station.","市政府正在新火車站附近興建可負擔住宅。","housing 指整體住宅供應或居住安排。"]],"l5-0457":[["動詞：盤旋","hang in the air","A hummingbird hovered beside the red flower without landing.","一隻蜂鳥在紅花旁盤旋，沒有停下來。","hover 指在空中保持位置。"]],"l5-0458":[["動詞：號叫","wail","The wolves howled together when the moon rose above the trees.","月亮升到樹梢上方時，狼群一起號叫。","howl 指狼或狗的長聲號叫，也可指人痛哭。"]],"l5-0459":[["動詞：用力投擲","throw forcefully / fling","The athlete hurled the javelin beyond the marked line.","那名運動員把標槍用力投過標線。","hurl 比 throw 更強調力量。"]],"l5-0460":[["名詞：聖歌、讚美詩","religious song / psalm","The choir sang a hymn before the evening service began.","晚間禮拜開始前，唱詩班唱了一首讚美詩。","hymn 通常是宗教禮拜中的歌曲。"]],"l5-0461":[["名詞：愚蠢的人","fool / foolish person","Calling a colleague an idiot during a meeting is rude and unprofessional.","在會議中叫同事笨蛋既無禮又不專業。","idiot 是侮辱性用語，正式溝通應避免。"]],"l5-0462":[["形容詞：廣大的；無限的","enormous / vast","An immense crowd gathered outside the stadium before the concert.","演唱會前，一大群人聚集在體育場外。","immense 強調尺寸或數量非常大。"]],"l5-0463":[["形容詞：帝國的","pertaining to an empire","The museum displays imperial coins from the ancient dynasty.","博物館展示古代王朝的帝國錢幣。","imperial 與帝國或皇帝有關。"]],"l5-0464":[["vt：徵(稅)；加負擔於…","inflict / levy / force","The government imposed new taxes.","政府徵收了新稅。","impose taxes 表示徵收稅款；本句翻譯採用與英文動詞搭配一致的自然說法。"]],"l5-0465":[["名詞：衝動","urge / sudden desire","On impulse, she bought a bright scarf that matched her coat.","她一時衝動買了一條與外套相配的鮮豔圍巾。","impulse 指突然產生而未深思的念頭。"]],"l5-0466":[["名詞：香","無直接同義詞","The temple filled with sandalwood incense during the morning ceremony.","早晨儀式期間，寺廟裡充滿檀香。","incense 指燃燒後產生香味的物質。"]],"l5-0467":[["名詞、動詞：索引；指數","catalogue","Use the index at the back of the book to find the technical terms.","請使用書末的索引尋找技術術語。","本句採 index 的名詞義；數學指數是另一用法。"]],"l5-0468":[["名詞：冷淡；不重要","apathy / unimportance","The committee’s indifference to the safety complaint angered the workers.","委員會對安全投訴的冷淡態度激怒了工人。","indifference 指缺乏關心或興趣。"]],"l5-0469":[["adj：漠不關心的","unconcerned / uninterested","They were indifferent to our concerns.","他們對我們的顧慮漠不關心。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0470":[["形容詞：憤慨的","outraged / offended","Residents were indignant about the unexpected closure of their clinic.","居民對診所突然關閉感到憤慨。","indignant 通常因不公平或不當行為而憤怒。"]],"l5-0471":[["形容詞：必需的","essential / vital","A reliable internet connection is indispensable for remote medical consultations.","可靠的網路連線是遠距醫療諮詢不可或缺的條件。","indispensable 表示完全不能缺少。"]],"l5-0472":[["vt：誘導；導致","cause / trigger / bring about","The medicine may induce drowsiness.","該藥物可能會引起睡意。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0473":[["動詞片語：讓自己享受（indulge in）","treat oneself to","We occasionally indulge in a fancy dinner at our favorite restaurant.","我們偶爾會到最喜歡的餐廳享用一頓大餐。","indulge in + 喜愛的事物；treat oneself to + 事物為近義表達，主詞不同時須調整反身代名詞。"]],"l5-0474":[["形容詞：無限的；極大的","boundless / limitless","The telescope revealed an apparently infinite field of stars.","望遠鏡揭示出看似無限的星海。","infinite 指沒有邊界或盡頭。"]],"l5-0475":[["動詞：繼承","receive by inheritance / succeed to","She inherited her grandfather’s watch and kept it in a velvet case.","她繼承祖父的手錶，並把它放在絨布盒裡。","inherit 可指取得財產、特徵或地位。"]],"l5-0476":[["vt：開始；創始","start / begin / launch","We will initiate the project next week.","我們將於下週啟動該專案。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0477":[["形容詞：內陸的；遠離海岸的","interior","The inland town receives less rain than the coastal villages.","這座內陸城鎮的雨量比沿海村莊少。","inland 指遠離海岸的地區。"]],"l5-0478":[["形容詞：數不清的","countless","Innumerable small lights appeared across the hillside after dark.","天黑後，山坡上出現數不清的小燈。","innumerable 是正式用語，強調數量極多。"]],"l5-0479":[["vt / vi：詢問；調查","ask / query / investigate","I called to inquire about the job opening.","我打電話去詢問職缺資訊。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0480":[["vt：設立 n.機構","organization / establish","He works at a research institute.","他在研究機構工作。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0481":[["動詞：投保；保證","guarantee","They insured the delivery van against theft and collision.","他們為送貨車投保失竊與碰撞險。","insure 通常指購買保險；ensure 是確保。"]],"l5-0482":[["n：意圖 adj.熱切的","intention / purpose","His intent was to help.","他的意圖是幫忙。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0483":[["名詞：妨礙；干涉","obstruction","Radio interference made the pilot’s instructions difficult to hear.","無線電干擾使飛行員的指示難以聽清。","interference 指介入或干擾造成的阻礙。"]],"l5-0484":[["形容詞：內部的","inner / inside","The interior walls of the gallery were painted a warm gray.","畫廊的內牆漆成溫暖的灰色。","interior 可指建築內部或內在部分。"]],"l5-0485":[["n：闡明；翻譯","translation / understanding","We provide interpretation services for foreign guests.","我們為外賓提供口譯服務。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0486":[["名詞：口譯員","無直接同義詞","The interpreter translated the mayor’s remarks into Japanese in real time.","口譯員即時把市長的談話翻成日文。","interpreter 處理口頭翻譯；translator 通常處理書面文字。"]],"l5-0487":[["名詞：直覺","gut feeling","Her intuition told her to check the invoice one more time.","她的直覺告訴她要再檢查一次發票。","intuition 是不經明確推理而形成的感覺。"]],"l5-0488":[["副詞：向內","無直接同義詞","The door opens inward.","門向內開。","本句 inward 修飾 opens；副詞也可寫 inwards。形容詞 internal 不能直接替換。"]],"l5-0489":[["名詞：內部；裡面","inside / interior","The inward side of the gate was covered with a layer of rust.","大門朝內的一面覆著一層鐵鏽。","inward 描述朝向內部的方向。"]],"l5-0490":[["名詞：小島","islet / small island","A quiet isle lies a short boat ride from the fishing village.","離漁村搭船不久處有一座寧靜小島。","isle 是較文學化的 island。"]],"l5-0491":[["n：議題；發行 vt.vi.發行","problem / matter / publish","We need to discuss this issue.","我們需要討論這個問題。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0492":[["名詞：常春藤","無直接同義詞","Ivy climbed the brick wall and shaded the window in summer.","常春藤爬上磚牆，夏天替窗戶遮蔭。","ivy 是攀爬牆面的常綠植物。"]],"l5-0493":[["名詞：男人；侍者；水手","man / sailor","The old jack at the harbor repaired nets for the fishing boats.","港口那名老水手替漁船修補漁網。","jack 作男人或水手時屬非正式用語。"]],"l5-0494":[["名詞：玉","無直接同義詞","The artisan carved a small jade pendant for the wedding gift.","工匠雕刻了一枚小玉墜，作為結婚禮物。","jade 是可製成飾品的綠色或其他顏色礦石。"]],"l5-0495":[["n：管理員；看門人","custodian / caretaker","The janitor cleans the office every evening.","清潔工每天晚上打掃辦公室。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0496":[["名詞：茉莉","無直接同義詞","The jasmine outside the window released a sweet scent at night.","窗外的茉莉在夜裡散發甜美香氣。","jasmine 可指植物或其香味。"]],"l5-0497":[["動詞：擅自穿越馬路","cross illegally / cross against the light","The officer warned pedestrians not to jaywalk across the busy avenue.","警員警告行人不要擅自穿越繁忙的大道。","jaywalk 指不在指定路口或違反號誌穿越馬路。"]],"l5-0498":[["動詞、名詞：嘲弄","mock / taunt","The audience jeered when the referee reversed the decision.","裁判改判時，觀眾發出嘲弄的噓聲。","jeer 可作動詞或名詞，帶有公開嘲笑意味。"]],"l5-0499":[["n：叮噹聲 vi.發出叮噹聲","ringing sound / advertising song","The company's TV commercial has a very catchy jingle.","該公司的電視廣告有一首很洗腦的短曲。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0500":[["形容詞：快活的","cheerful / merry","Our jolly guide told jokes throughout the long bus ride.","我們快活的導遊在漫長車程中一路說笑話。","jolly 常形容開朗愉快的人或氣氛。"]],"l5-0501":[["名詞：新聞工作","news reporting / press work","She studied journalism before joining the city newspaper.","她研讀新聞學後加入地方報社。","journalism 指蒐集、查證與報導新聞的工作。"]],"l5-0502":[["n：新聞\\撰稿記者","reporter","The journalist is writing a story about the new company.","記者正在撰寫關於這家新公司的報導。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0503":[["名詞：水罐","pitcher","He filled the glass jug with lemonade and placed it in the refrigerator.","他把玻璃水罐裝滿檸檬水，放進冰箱。","jug 通常是有把手、用來盛液體的容器。"]],"l5-0504":[["名詞：陪審團","無直接同義詞","The jury listened carefully to both sides before reaching a verdict.","陪審團在作出裁決前仔細聽取雙方說法。","jury 是負責判斷案件事實的一組陪審員。"]],"l5-0505":[["vt / vi：認為正當；為...辯 護","validate / defend / warrant","The results justify the cost of the project.","這些成果證明了該專案的成本是合理的。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0506":[["名詞、形容詞：少年；少年的","adolescent / youthful","The juvenile court assigned the teenager a community service program.","少年法庭安排那名青少年參加社區服務計畫。","juvenile 可指未成年人，也可形容與少年相關的事物。"]],"l5-0507":[["名詞：親屬","relative / family member","She invited close kin to the memorial service in her hometown.","她邀請近親參加家鄉的追思會。","kin 是較正式或文學化的 relatives。"]],"l5-0508":[["動詞：點燃；激起","ignite / inspire","The teacher’s story kindled the students’ interest in astronomy.","老師的故事激起學生對天文學的興趣。","kindle 可指點燃火，也可比喻激起情感或興趣。"]],"l5-0509":[["adj：博學的","well-informed / educated","He is very knowledgeable about international law.","他對國際法非常了解。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0510":[["名詞：少年；小夥子；老友","boy / young man","The farm lad carried two sacks of grain into the barn.","那名農場小夥子把兩袋穀物搬進穀倉。","lad 是英式口語，指男孩或年輕男子。"]],"l5-0511":[["形容詞：跛腳的；動詞：使跛腳","crippled / limping","A lame horse was taken to the veterinarian before the race.","一匹跛腳的馬在比賽前被送去看獸醫。","lame 描述行走困難；用於人時可能不禮貌。"]],"l5-0512":[["名詞：女房東","female landlord","The landlady repaired the leaking tap in our rented apartment.","女房東修好了我們租屋裡漏水的水龍頭。","landlady 是女性 landlord。"]],"l5-0513":[["n：地主","property owner","The landlord fixed the leaking roof.","房東修好了漏水的屋頂。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0514":[["名詞：雷射","無直接同義詞","The surgeon used a laser to remove the tiny skin lesion.","外科醫師用雷射移除微小的皮膚病灶。","laser 是以受激發光產生的高集中度光束。"]],"l5-0515":[["名詞：緯度","無直接同義詞","The island’s warm climate is unusual for its northern latitude.","以其北方的緯度而言，這座島的氣候異常溫暖。","latitude 是赤道以北或以南的角距離。"]],"l5-0516":[["名詞：立法之人","legislator","The lawmaker proposed stricter rules for labeling imported food.","那名立法者提議制定更嚴格的進口食品標示規則。","lawmaker 是制定法律的民選或任命官員。"]],"l5-0517":[["名詞：一層","stratum / coating","A thin layer of dust covered the unused display case.","一層薄灰塵覆蓋著未使用的展示櫃。","layer 指覆在表面或上下排列的一層物質。"]],"l5-0518":[["名詞：聯盟","association / federation","The regional sports league added two new teams this season.","區域體育聯盟本季新增兩支隊伍。","league 指為共同競賽或目標組成的團體。"]],"l5-0519":[["名詞：制定法律","lawmaking","The proposed legislation would require companies to disclose emissions.","擬議中的法案將要求公司揭露排放量。","legislation 指法律整體或制定法律的過程。"]],"l5-0520":[["動詞：減少","reduce / diminish","Planting trees can lessen the heat around the school playground.","種樹可以降低學校操場周圍的熱度。","lessen 可及物或不及物使用，表示程度變小。"]],"l5-0521":[["連接詞：以免","for fear that / so that not","She whispered lest the sleeping child should wake.","她低聲說話，以免吵醒熟睡的孩子。","lest 後接原形或 should，屬正式用法。"]],"l5-0522":[["名詞：中尉","無直接同義詞","The lieutenant briefed the rescue team before they entered the canyon.","中尉在救援隊進入峽谷前向他們說明任務。","lieutenant 是軍階名稱，讀音依英美用法不同。"]],"l5-0523":[["形容詞：一輩子的","lasting a lifetime","Their lifelong friendship began when they met at primary school.","他們一輩子的友誼始於小學相識時。","lifelong 指持續一生的關係、習慣或活動。"]],"l5-0524":[["名詞：可能性","probability","There is a strong likelihood that the bridge will reopen tomorrow.","這座橋明天重新開放的可能性很高。","likelihood 指某事發生的機率，不是「相似之處」。"]],"l5-0525":[["名詞：石灰","calcium oxide","Workers spread lime on the acidic soil before planting the orchard.","工人在種植果樹前把石灰撒在酸性土壤上。","lime 在此指改善土壤的化合物，不是酸橙。"]],"l5-0526":[["動詞、名詞：跛行","hobble","He limped back to the bench after twisting his ankle.","他扭傷腳踝後一跛一跛地走回長椅。","limp 可作動詞或名詞，指不均衡地走路。"]],"l5-0527":[["動詞：徘徊","remain / loiter","The smell of smoke lingered in the room long after the fire was out.","火熄滅很久後，房間裡仍殘留煙味。","linger 可指人逗留，也可指氣味或感覺持續。"]],"l5-0528":[["名詞：家畜","farm animals / cattle","The farmer moved the livestock to higher ground before the flood arrived.","洪水來臨前，農夫把家畜移到較高的地勢。","livestock 是農場飼養動物的總稱，通常不可數。"]],"l5-0529":[["名詞：蜥蜴","無直接同義詞","A green lizard warmed itself on the stone wall beside the garden.","一隻綠色蜥蜴在花園旁的石牆上曬太陽。","lizard 是爬蟲類的通稱。"]],"l5-0530":[["名詞：火車頭","engine / train locomotive","The locomotive pulled twelve carriages up the steep mountain track.","火車頭拉著十二節車廂爬上陡峭的山路。","locomotive 是牽引列車的引擎。"]],"l5-0531":[["名詞：蝗蟲","無直接同義詞","A swarm of locusts destroyed the farmer’s wheat field in a single afternoon.","一群蝗蟲在一個下午就摧毀了農夫的麥田。","locust 是會成群遷徙並危害農作物的昆蟲。"]],"l5-0532":[["名詞：小屋","cabin / hut","The hikers spent the night in a wooden lodge beside the lake.","健行者在湖邊的木屋住了一晚。","lodge 可指供旅客住宿的鄉間小屋。"]],"l5-0533":[["形容詞：崇高的","elevated / noble","The charity’s lofty goal is to provide clean water to every village.","這個慈善組織的崇高目標是為每座村莊提供乾淨的水。","lofty 可指理想崇高，也可指位置高。"]],"l5-0534":[["名詞：標誌","emblem / brand mark","The company redesigned its logo before launching the new product.","公司在推出新產品前重新設計了標誌。","logo 是代表品牌的圖案或字樣。"]],"l5-0535":[["形容詞：寂寞的","lonely / solitary","The lonesome puppy waited by the gate until its owner returned.","那隻寂寞的小狗在門邊等到主人回來。","lonesome 比 lonely 更帶有孤單的情緒。"]],"l5-0536":[["名詞：經度","無直接同義詞","The navigator checked the ship’s longitude against the digital chart.","領航員把船的經度與電子海圖核對。","longitude 是東西向的位置座標。"]],"l5-0537":[["名詞：彩券；樂透","raffle","She bought one lottery ticket at the station kiosk.","她在車站小亭買了一張彩券。","lottery 通常指以抽籤決定獎項的遊戲。"]],"l5-0538":[["名詞：蓮花","無直接同義詞","A pink lotus opened on the pond as the morning sun rose.","早晨太陽升起時，池塘裡一朵粉紅蓮花綻放。","lotus 是生長在水中的植物。"]],"l5-0539":[["名詞：木材","timber / wood","The carpenter selected dry lumber for the roof beams.","木匠為屋頂樑柱挑選乾燥木材。","lumber 通常指鋸成建材的木料。"]],"l5-0540":[["名詞：團；塊","clump","A lump of clay remained stuck to the child’s shoe.","一團黏土仍黏在孩子的鞋子上。","lump 指不規則的一團或一塊。"]],"l5-0541":[["動詞：放大；擴大","enlarge","The microscope magnified the cell until its walls were clearly visible.","顯微鏡把細胞放大到能清楚看見細胞壁。","magnify 可指放大影像，也可指誇大事情。"]],"l5-0542":[["名詞：少女","young woman / virgin","The novel follows a maiden who leaves her village to study music.","這部小說描述一名少女離開村莊學習音樂。","maiden 是較文學化的 young woman。"]],"l5-0543":[["n：大陸","continent","They traveled to the mainland.","他們前往大陸旅行。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0544":[["名詞：主流","無直接同義詞","The documentary brought the local band into the mainstream music scene.","這部紀錄片讓當地樂團進入主流音樂圈。","mainstream 指普遍接受的思想或文化。"]],"l5-0545":[["n：維持；保持","upkeep / repair","The machine requires regular maintenance.","這台機器需要定期維護。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0546":[["形容詞：雄偉的；威嚴的","grand / imposing","The majestic mountain stood above the clouds at sunrise.","日出時，那座雄偉的山峰高聳在雲端之上。","majestic 強調令人敬畏的壯麗。"]],"l5-0547":[["名詞：雄偉；莊嚴","grandeur / dignity","Visitors stood quietly beneath the cathedral’s arches and admired its majesty.","訪客安靜站在大教堂拱頂下，欣賞它的莊嚴。","majesty 可指宏偉外觀或君主尊嚴。"]],"l5-0548":[["名詞：哺乳類","無直接同義詞","A dolphin is a mammal because it breathes air and nurses its young.","海豚是哺乳類，因為牠用肺呼吸並哺乳幼體。","mammal 的特徵包括哺乳與用肺呼吸。"]],"l5-0549":[["形容詞：顯然的；明白的","obvious / clear","The damage was manifest as soon as the engineers inspected the bridge.","工程師檢查橋梁後，損壞情況立刻顯而易見。","manifest 作形容詞表示清楚可見。"]],"l5-0550":[["名詞：府邸；大廈","large residence","The historic mansion now serves as a museum for regional art.","這座歷史府邸現在是地方藝術博物館。","mansion 指寬敞豪華的住宅。"]],"l5-0551":[["名詞：楓樹；楓葉","無直接同義詞","The maple leaves turned brilliant red during the cool October nights.","涼爽的十月夜晚過後，楓葉變成鮮紅色。","maple 可指楓樹或其葉子。"]],"l5-0552":[["adj：邊緣的；微幅的","slight / minimal","There was a marginal increase in sales.","銷售額有微幅增加。","此處 marginal 修飾 increase，意為「微幅的；些微的」；另可表示邊緣的。"]],"l5-0553":[["形容詞：海的；海生的","oceanic","The research vessel recorded several marine species near the coral reef.","研究船記錄了珊瑚礁附近的數種海洋生物。","marine 指與海洋有關的事物。"]],"l5-0554":[["名詞：元帥；高級將官","field commander","The marshal inspected the troops before the national ceremony.","元帥在國家典禮前檢閱部隊。","marshal 可指高階軍官，也可指維持秩序的官員。"]],"l5-0555":[["形容詞：好戰的；戰爭的","warlike / military","The documentary examines the ruler’s martial culture and military campaigns.","這部紀錄片探討那位統治者的好戰文化與軍事戰役。","martial 與戰爭、軍事或武術有關。"]],"l5-0556":[["名詞、動詞：驚奇；感到驚訝","wonder / be amazed","We marveled at how quickly the injured bird recovered.","我們對那隻受傷鳥兒恢復得如此迅速感到驚訝。","marvel at 表示對令人驚奇的事感到讚嘆。"]],"l5-0557":[["形容詞：男子氣概的","manly","The advertisement presents a masculine style through dark colors and sturdy boots.","這則廣告以深色和堅固靴子呈現男子氣概的風格。","masculine 描述傳統上與男性相關的特質。"]],"l5-0558":[["名詞：糊狀物","paste / puree","Mash the boiled potatoes with butter until they form a smooth mash.","把煮熟的馬鈴薯加奶油壓成滑順的糊狀物。","mash 可指壓碎後的糊狀食品。"]],"l5-0559":[["名詞、動詞：按摩","rubdown","The therapist massaged my shoulders after the long cycling trip.","長途騎車後，治療師替我的肩膀按摩。","massage 可作名詞或動詞。"]],"l5-0560":[["adj：巨大的","huge / enormous","There was a massive crowd.","有一大群人。","massive 形容 crowd 時，表示人數非常多。"]],"l5-0561":[["名詞：傑作","masterwork","The restoration team spent five years preserving the painter’s masterpiece.","修復團隊花了五年保存那位畫家的傑作。","masterpiece 指藝術家最出色的作品。"]],"l5-0562":[["名詞：美乃滋","無直接同義詞","She spread mayonnaise on the sandwich before adding the grilled vegetables.","她在加入烤蔬菜前，先把美乃滋抹在三明治上。","mayonnaise 是以油、蛋黃等製成的醬料。"]],"l5-0563":[["副詞：同時","meanwhile / in the meantime","The technicians repaired the server; in the meantime, customers used the backup website.","技術人員修理伺服器時，顧客改用備援網站。","meantime 常用於表示兩件事同時進行。"]],"l5-0564":[["名詞：力學；機械學","無直接同義詞","The course introduces the mechanics of gears, levers, and moving parts.","這門課介紹齒輪、槓桿和活動零件的機械原理。","mechanics 可指物理學中的力學或機械運作方式。"]],"l5-0565":[["vt / vi：居中調停 adj.居間的","arbitrate / resolve","He was asked to mediate the dispute.","他被要求調解這場糾紛。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0566":[["n / vt / vi：威脅","threat / danger","Pollution is a menace to the environment.","污染對環境構成威脅。","menace to 表示「對……構成威脅」。"]],"l5-0567":[["名詞：美人魚","無直接同義詞","The children listened to a story about a mermaid who guarded a sunken ship.","孩子們聽著一則守護沉船的美人魚故事。","mermaid 是神話中上半身為人、下半身為魚的生物。"]],"l5-0568":[["名詞：中間","middle","In the midst of the storm, the lighthouse continued to guide ships.","暴風雨正猛烈時，燈塔仍持續引導船隻。","midst 多用於 in the midst of 的正式片語。"]],"l5-0569":[["形容詞、名詞：移居的；移民","migratory","The farm hires migrant workers to pick fruit during the harvest season.","農場在收成季雇用移民工人採摘水果。","migrant 可作名詞或形容詞，指跨地區移居。"]],"l5-0570":[["n：里程數","distance","The car has low mileage.","這輛車的里程數很低。","mileage 的標準繁中譯法為「里程數」。"]],"l5-0571":[["n：里程碑","important event","This is a milestone in our project.","這是我們專案的一個里程碑。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0572":[["vt / vi：混合","socialize / mix","The flavors mingle well in this sauce.","這些味道在這道醬汁中融合得很好。","此處 mingle 表示不同味道融合，與卡面「混合」義項一致。"]],"l5-0573":[["形容詞：最小的","minimum / smallest","The clinic operates with a minimal staff on public holidays.","這家診所在國定假日只由少數人員值班。","minimal 表示數量或程度很少。"]],"l5-0574":[["名詞：薄荷","無直接同義詞","Fresh mint gave the iced tea a cool, clean flavor.","新鮮薄荷讓冰茶帶有清涼清新的味道。","mint 也可指鑄幣廠；本句採植物義。"]],"l5-0575":[["名詞：吝嗇鬼；守財奴","skinflint","The miser refused to replace his worn shoes even after they began to leak.","那名守財奴即使鞋子開始漏水，也不肯換新鞋。","miser 指極度不願花錢的人。"]],"l5-0576":[["名詞：女主人；情婦","female host / female head of a household","The mistress of the estate greeted visitors in the entrance hall.","莊園女主人在入口大廳迎接訪客。","mistress 的傳統義是女主人；現代語境也常指已婚男性的情婦，需依上下文判斷。"]],"l5-0577":[["動詞、名詞：呻吟","groan","The patient moaned softly while the nurse changed the bandage.","護士更換繃帶時，病人輕聲呻吟。","moan 可表痛苦聲，也可表抱怨。"]],"l5-0578":[["動詞、名詞：嘲笑","ridicule / parody","The comedian mocked the mayor’s speech without naming him directly.","喜劇演員沒有直接點名，卻嘲笑了市長的演講。","mock 可指嘲笑或模仿以取笑。"]],"l5-0579":[["名詞：模式","method / pattern","The device has an energy-saving mode that dims the screen automatically.","這台裝置有節能模式，會自動調暗螢幕。","mode 指操作方式或狀態。"]],"l5-0580":[["動詞：現代化","update","The city plans to modernize its water-treatment plant next year.","市政府計畫明年使淨水廠現代化。","modernize 指採用新設備或方法使其符合現代需求。"]],"l5-0581":[["vt：修改","change / alter","We need to modify the design.","我們需要修改設計。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0582":[["名詞：模型；模式；鑄模","mould / pattern","The sculptor poured wet plaster into a mold shaped like a human hand.","雕刻家把濕石膏倒入人手形狀的鑄模。","mold 可指鑄模、模型或形狀範本。"]],"l5-0583":[["名詞：分子","無直接同義詞","A water molecule contains two hydrogen atoms and one oxygen atom.","一個水分子含有兩個氫原子和一個氧原子。","molecule 是由兩個以上原子結合成的微小單位。"]],"l5-0584":[["名詞：君王","sovereign","The monarch addressed the nation after the devastating earthquake.","大地震後，君王向全國發表談話。","monarch 指統治王國的君主。"]],"l5-0585":[["形容詞：似怪物的","grotesque","The film depicts a monstrous creature emerging from the abandoned mine.","電影描繪一隻似怪物的生物從廢棄礦坑出現。","monstrous 可指外貌可怕，也可指行為殘酷。"]],"l5-0586":[["形容詞：會死的；致命的","fatal","The hikers carried an antidote for the mortal bite of the desert snake.","健行者攜帶解毒劑，以應對沙漠蛇的致命咬傷。","mortal 可指會死亡的，也可指致命的。"]],"l5-0587":[["名詞：苔蘚","無直接同義詞","Soft moss covered the stones beside the shaded forest stream.","陰暗森林溪流旁的石頭覆滿柔軟苔蘚。","moss 是生長在潮濕表面的微小植物。"]],"l5-0588":[["名詞：母親身分","being a mother","She wrote honestly about the joys and exhaustion of early motherhood.","她坦率寫下初為人母的喜悅與疲憊。","motherhood 指成為母親的身分與經驗。"]],"l5-0589":[["名詞：動機","reason / incentive","Investigators searched the suspect’s emails for a possible motive.","調查人員搜尋嫌疑人的電子郵件，尋找可能的動機。","motive 是促使某人行動的原因。"]],"l5-0590":[["名詞：丘","hill / knoll","The children rolled down the grassy mound behind the school.","孩子們從學校後方的草丘滾下來。","mound 指圓形隆起的小丘或土堆。"]],"l5-0591":[["動詞：登上；名詞：底座","climb / pedestal","The climber mounted the platform to receive the award.","登山者登上平台領取獎項。","mount 作動詞可指登上；名詞可指支架或底座。"]],"l5-0592":[["動詞：哀悼","grieve","The village gathered to mourn the teacher who had served it for forty years.","村民聚集哀悼服務社區四十年的老師。","mourn 指因死亡而哀悼。"]],"l5-0593":[["名詞：刈草機","lawn mower","He pushed the mower across the backyard before the rain began.","下雨前，他把刈草機推過後院。","mower 是切割草或農作物的機器。"]],"l5-0594":[["動詞、名詞：咕噥","mutter","He mumbled an apology because he was embarrassed by the mistake.","他因為那個錯誤感到尷尬，咕噥著道歉。","mumble 指聲音低而含糊，難以聽清。"]],"l5-0595":[["形容詞：肌肉發達的","strong","The muscular athlete lifted the loaded barbell without assistance.","那名肌肉發達的運動員不靠協助就舉起負重槓鈴。","muscular 強調肌肉的大小或發達程度。"]],"l5-0596":[["動詞、名詞：沉思","ponder / reflect","She mused over the proposal before giving the board her answer.","她仔細沉思那份提案後，才向董事會回答。","muse over 表示沉思或反覆考慮。"]],"l5-0597":[["名詞：芥末","無直接同義詞","The waiter brought mustard for the grilled sausage.","服務生拿芥末來搭配烤香腸。","mustard 是帶辛味的黃色調味醬或植物。"]],"l5-0598":[["動詞、名詞：咕噥","grumble","The passenger muttered about the delay while checking the departure board.","乘客查看出發看板時，低聲抱怨延誤。","mutter 指低聲說話，常讓人聽不清楚。"]],"l5-0599":[["名詞：羊肉","無直接同義詞","The restaurant serves slow-cooked mutton with rosemary and potatoes.","這家餐廳供應迷迭香馬鈴薯燉羊肉。","mutton 通常指成年羊的肉。"]],"l5-0600":[["名詞：神話","legend","The guide explained that the river monster is a local myth.","導遊解釋那隻河怪是當地傳說。","myth 可指傳說故事，也可指未經證實的觀念。"]],"l5-0601":[["動詞：使煩惱；嘮叨","pester","The supervisor nagged the contractor until the broken railing was repaired.","主管不停催促承包商，直到損壞的欄杆修好。","nag 指反覆提醒而令人厭煩。"]],"l5-0602":[["形容詞：天真的","innocent / unsophisticated","The naive buyer trusted the advertisement without checking the contract.","那名天真的買家沒有查看合約就相信了廣告。","naive 常暗示缺乏經驗或判斷力。"]],"l5-0603":[["形容詞：猥褻的；險惡的","vulgar / vicious","The judge imposed a fine for the nasty messages sent to the witness.","法官因寄給證人的惡劣訊息而處以罰款。","nasty 可指令人厭惡、惡意或危險。"]],"l5-0604":[["vt / vi：導航；航行","steer / guide","It is easy to navigate the website.","這個網站很容易操作。","navigate 用於網站時可指瀏覽或操作；此句採「操作」義。"]],"l5-0605":[["名詞：新聞廣播","news bulletin / broadcast","The evening newscast reported the results of the local election.","晚間新聞廣播報導了地方選舉結果。","newscast 指播出的新聞節目。"]],"l5-0606":[["動詞、名詞：一點一點嚙咬","bite lightly","The rabbit nibbled the lettuce leaves beside its water bowl.","兔子在水碗旁一點一點啃食萵苣葉。","nibble 強調小口慢慢吃。"]],"l5-0607":[["名詞：鎳","無直接同義詞","The manufacturer added a thin layer of nickel to protect the steel part.","製造商在鋼製零件上加鍍薄鎳層以防護。","nickel 是一種金屬元素。"]],"l5-0608":[["名詞：夜鶯","無直接同義詞","A nightingale sang from the hedge after the village became quiet.","村莊安靜後，一隻夜鶯在樹籬中歌唱。","nightingale 是以歌聲著名的鳥類。"]],"l5-0609":[["vt：提名","propose / suggest","They nominated her for the position.","他們提名她擔任那個職位。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0610":[["副詞、連接詞：然而","nevertheless / however","The route was longer; nonetheless, it avoided the flooded bridge.","路線比較長；然而，它避開了淹水的橋。","nonetheless 表示讓步轉折。"]],"l5-0611":[["形容詞：非暴力的","peaceful / nonaggressive","The protesters held a nonviolent march through the city center.","抗議者在市中心舉行非暴力遊行。","nonviolent 強調不使用暴力。"]],"l5-0612":[["名詞：鼻孔","無直接同義詞","The swimmer pinched her nostrils before diving into the cold water.","游泳者跳入冷水前捏住鼻孔。","nostril 是鼻子的兩個開口之一。"]],"l5-0613":[["形容詞：著名的","prominent / noteworthy","The museum honored a notable scientist who developed the vaccine.","博物館表揚一位研發疫苗的著名科學家。","notable 表示值得注意或有名。"]],"l5-0614":[["形容詞：顯著的","obvious / perceptible","The drop in temperature was noticeable as soon as the sun set.","太陽下山後，氣溫下降變得很明顯。","noticeable 指容易被察覺。"]],"l5-0615":[["vt：通知；告知","inform","Please notify us of any changes.","若有變更請通知我們。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0616":[["名詞：概念；想法","idea / concept","The architect rejected the notion that a small house must feel cramped.","建築師不接受小房子一定擁擠的想法。","notion 可指看法或概念。"]],"l5-0617":[["n：新手","beginner","He is a novice at tennis.","他是網球新手。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0618":[["副詞：無處；哪裡都沒有","no place","The missing files were nowhere on the office computer.","遺失的檔案在辦公室電腦裡哪裡都找不到。","nowhere 表示沒有任何地方。"]],"l5-0619":[["名詞：核","core / center","The nucleus of the cell contains the genetic material.","細胞核含有遺傳物質。","nucleus 可指細胞核或核心。"]],"l5-0620":[["形容詞：裸的；不加修飾的","naked / unadorned","The artist displayed a nude figure study behind a privacy screen.","藝術家在遮蔽屏後展示裸體人物習作。","nude 描述裸體或未經修飾的形式。"]],"l5-0621":[["n：槳","無直接同義詞","He rowed the boat with two oars.","他用兩支槳划船。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0622":[["名詞：綠洲","無直接同義詞","The travelers found an oasis where palm trees grew around a spring.","旅人找到一座綠洲，泉水周圍長著棕櫚樹。","oasis 是沙漠中的水源地。"]],"l5-0623":[["名詞：誓言","vow","The witness took an oath to tell the truth in court.","證人在法庭上宣誓說實話。","oath 是正式或莊重的誓言。"]],"l5-0624":[["名詞：燕麥粥","porridge","She ate warm oatmeal with fruit before leaving for work.","她上班前吃了溫熱的水果燕麥粥。","oatmeal 是以燕麥煮成的食物。"]],"l5-0625":[["名詞：長方形","rectangle","The designer cut the paper into an oblong to make a label for the bottle.","設計師把紙裁成長方形，做成瓶子的標籤。","本句 an oblong 為名詞，指長方形；美式英語也可指其他長度大於寬度的形狀。"]],"l5-0626":[["名詞：觀測員","monitor","An independent observer watched the vote count at each polling station.","獨立觀察員監督每個投票所的計票。","observer 指負責觀看並記錄的人。"]],"l5-0627":[["形容詞：頑固的","stubborn / inflexible","The obstinate tenant refused every reasonable repair proposal.","那名頑固的房客拒絕所有合理的維修方案。","obstinate 常帶不願改變的負面語氣。"]],"l5-0628":[["n：事件","event / incident","Such an occurrence is rare.","這樣的事件很罕見。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0629":[["名詞：章魚","無直接同義詞","The octopus changed color as it slipped between the rocks.","章魚鑽過岩石時改變了顏色。","octopus 是有八條腕足的海洋動物。"]],"l5-0630":[["名詞：機會","chance / probability","The odds of seeing a comet are better away from city lights.","遠離城市燈光時，看見彗星的機會較高。","odds 常表示機率或勝算。"]],"l5-0631":[["名詞：氣味","scent / smell","A sharp odor of paint remained in the room after renovation.","整修後，房間裡仍殘留刺鼻的油漆味。","odor 可是香味或臭味，語氣常偏中性。"]],"l5-0632":[["名詞：橄欖","無直接同義詞","The chef added sliced olives to the Mediterranean salad.","廚師把切片橄欖加入地中海沙拉。","olive 也可指橄欖樹。"]],"l5-0633":[["n：對手","rival / competitor","He defeated his opponent.","他擊敗了他的對手。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0634":[["名詞：樂觀主義","hopefulness","Her optimism kept the team working during the difficult recovery.","艱難的復原期間，她的樂觀主義讓團隊持續努力。","optimism 是對未來抱持正面期待。"]],"l5-0635":[["名詞：果園","無直接同義詞","The family planted apple trees throughout the hillside orchard.","這家人在山坡果園各處種下蘋果樹。","orchard 是栽種果樹的土地。"]],"l5-0636":[["n：組織者","planner","He is the main organizer of the event.","他是活動的主要組織者。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0637":[["名詞：東方","the East","The exhibition explores trade between Europe and the ancient Orient.","展覽探討歐洲與古代東方之間的貿易。","Orient 作地理文化名詞較正式，現代用法須注意語境。"]],"l5-0638":[["形容詞：東方的","eastern / Asian","The restaurant serves oriental herbs with its traditional noodle dishes.","這家餐廳用東方香草搭配傳統麵食。","oriental 用於人可能過時；描述物品時可依語境使用。"]],"l5-0639":[["名詞：裝飾品","decoration / adornment","A silver ornament hung from the center of the holiday wreath.","一件銀色裝飾品掛在節日花圈中央。","ornament 是用來裝飾的物件。"]],"l5-0640":[["名詞：孤兒院","children’s home","The volunteers delivered books and blankets to the orphanage.","志工把書籍和毛毯送到孤兒院。","orphanage 是照顧孤兒的機構。"]],"l5-0641":[["名詞：鴕鳥","無直接同義詞","The ostrich ran across the reserve faster than the tour vehicle.","那隻鴕鳥跑過保護區，速度比觀光車還快。","ostrich 是不會飛但善於奔跑的大型鳥類。"]],"l5-0642":[["名詞：盎司","無直接同義詞","Add two ounces of flour before mixing the batter.","攪拌麵糊前加入兩盎司麵粉。","ounce 是重量或液量單位，依語境而定。"]],"l5-0643":[["動詞：勝過；超越","surpass / beat","The young pianist outdid every previous performance at the festival.","那名年輕鋼琴家在音樂節超越了之前的每次演出。","outdo 表示表現得比某人或某事更好。"]],"l5-0644":[["adj：外向的；外出的","extroverted / leaving","She has an outgoing personality.","她有外向的個性。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0645":[["n / vt：出產；生產","production","The factory increased its output.","工廠提高了產量。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0646":[["名詞：局外人","nonmember","As an outsider, she noticed problems that longtime staff had overlooked.","身為局外人，她注意到資深員工忽略的問題。","outsider 指不屬於某團體或圈子的人。"]],"l5-0647":[["n：郊區","suburbs / edge","They live on the outskirts of the city.","他們住在城市郊區。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0648":[["形容詞、副詞：向外的","external","The doors open outward toward the courtyard.","這些門朝庭院方向向外開。","outward 表示由內向外的方向。"]],"l5-0649":[["副詞：往外去","outside / away from the center","The hikers moved outwards from the crowded trail.","健行者從擁擠的步道向外移動。","outwards 是英式拼法；美式常寫 outward。"]],"l5-0650":[["adj：全部的 adv.大體上來說 n.連身工作服","general / total","The overall effect was good.","整體效果很好。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0651":[["動詞：做得過分","exaggerate","Do not overdo the spices, or the soup will become too salty.","香料不要放過量，否則湯會太鹹。","overdo 指把事情做到超過適當程度。"]],"l5-0652":[["動詞：過度飲食","eat too much / overindulge","He felt ill after overeating at the holiday buffet.","他在節日自助餐吃太多後感到不舒服。","overeat 指吃得超過身體需要。"]],"l5-0653":[["vi / vt：氾濫","spill over","The sink started to overflow.","洗手台開始溢出來了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0654":[["動詞：無意中聽到","catch unintentionally","I overheard two passengers discussing the canceled flight.","我無意中聽到兩名乘客談論取消的航班。","overhear 表示偶然聽見，不是故意偷聽。"]],"l5-0655":[["動詞：睡過頭","sleep late","I overslept and missed the early train to the airport.","我睡過頭，錯過了前往機場的早班車。","oversleep 指睡得比預定時間久。"]],"l5-0656":[["動詞：戰勝；淹沒","overpower","The sudden flood overwhelmed the temporary barriers around the village.","突如其來的洪水沖垮了村莊周圍的臨時防洪設施。","overwhelm 可指力量壓倒或情緒難以承受。"]],"l5-0657":[["vt / vi：過度工作","exhaust / strain","He often overworks himself.","他經常工作過度。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0658":[["名詞：牡蠣；蠔","無直接同義詞","The fisherman opened a fresh oyster beside the harbor market.","漁夫在港口市場旁打開一顆新鮮牡蠣。","oyster 是可食用的雙殼軟體動物。"]],"l5-0659":[["名詞：臭氧","無直接同義詞","The ozone layer protects Earth from much of the sun’s ultraviolet radiation.","臭氧層保護地球免受大量太陽紫外線。","ozone 是由三個氧原子組成的氣體。"]],"l5-0660":[["形容詞：和平的","peaceful / calm","The negotiators reached a pacific settlement after months of talks.","談判代表經過數月協商後達成和平解決方案。","pacific 作形容詞指愛好和平；Pacific 大寫指太平洋。"]],"l5-0661":[["名詞：小包裹","small parcel","Each packet of seeds included planting instructions in three languages.","每小包種子都附有三種語言的種植說明。","packet 指小包裝或小包裹。"]],"l5-0662":[["n：槳","無直接同義詞","He used two oars to row the boat.","他用兩支槳划船。","oar 指划船用的長柄槳；paddle 是相關但不同的划槳。"]],"l5-0663":[["名詞：自相矛盾的人事物","contradiction / seeming contradiction","It is a paradox that the busiest route is also the least profitable.","最繁忙的路線竟然也是最不賺錢的，這真是矛盾。","paradox 表面矛盾但可能含有道理。"]],"l5-0664":[["名詞：窗玻璃","windowpane","A cracked pane let cold air into the bedroom.","破裂的窗玻璃讓冷空氣進入臥室。","pane 指窗戶中的一片玻璃。"]],"l5-0665":[["形容詞：平行的；並聯的","無直接同義詞","The two railway lines run parallel through the valley.","兩條鐵路線平行穿過山谷。","parallel 可指幾何平行或同時進行。"]],"l5-0666":[["n：店；店舖","shop / room","He opened an ice cream parlor.","他開了一家冰淇淋店。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0667":[["n：參與者","attendee","Each participant will receive a gift.","每位參加者都會收到一份禮物。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0668":[["名詞：微粒","speck","A dust particle floated through the beam of sunlight.","一顆灰塵微粒飄過陽光形成的光束。","particle 指極小的物質單位。"]],"l5-0669":[["副詞：部分地","in part","The delay was partly caused by a shortage of replacement parts.","延誤部分是由替換零件短缺造成的。","partly 表示原因或程度只有一部分。"]],"l5-0670":[["形容詞：熱情的","enthusiastic / fervent","She is passionate about teaching children to read.","她熱衷於教孩子閱讀。","passionate about 後接名詞或動名詞，表強烈熱情。"]],"l5-0671":[["名詞：消遣、娛樂","hobby / recreation","Gardening became his favorite pastime after he retired.","退休後，園藝成了他最喜歡的消遣。","pastime 指用來休閒消磨時間的活動。"]],"l5-0672":[["名詞：酥皮點心","baked pastry","The bakery sells flaky pastries filled with apple and cinnamon.","麵包店販售填入蘋果和肉桂的酥皮點心。","pastry 可指麵皮或以麵皮製成的點心。"]],"l5-0673":[["名詞：補丁；貼片","repair piece","She sewed a patch over the tear in her hiking jacket.","她在健行外套的破洞上縫了一塊補丁。","patch 可指修補材料，也可指小片區域。"]],"l5-0674":[["n：專利","無直接同義詞","They applied for a new patent.","他們申請了一項新專利。","patent 是授予發明的法律權利，不等同於 license 或 copyright。"]],"l5-0675":[["名詞：愛國者","無直接同義詞","The patriot donated his collection to the national museum.","那名愛國者把收藏捐給國家博物館。","patriot 指熱愛並支持自己國家的人。"]],"l5-0676":[["動詞、名詞：巡邏","guard","Officers patrol the harbor at night to deter theft.","警員夜間巡邏港口以遏止竊盜。","patrol 可作動詞或名詞，指定期巡查。"]],"l5-0677":[["n：贊助者；主顧","customer / supporter","The restaurant has many regular patrons.","這家餐廳有很多熟客。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0678":[["名詞：孔雀","無直接同義詞","The peacock spread its brilliant tail feathers across the garden path.","孔雀在花園小徑上展開鮮豔的尾羽。","peacock 是雄孔雀；雌鳥稱 peahen。"]],"l5-0679":[["名詞：農民；小農","tenant farmer","The novel portrays a peasant family working on a rented hillside farm.","小說描寫一家農民在租來的山坡農地上工作。","peasant 可指傳統農村的農民，語氣依語境而定。"]],"l5-0680":[["動詞、名詞：啄","tap with the beak","The woodpecker pecked a neat row of holes in the old tree.","啄木鳥在老樹上啄出整齊的一排洞。","peck 指鳥用喙快速啄擊。"]],"l5-0681":[["n：小販","vendor","The peddler sold fruit on the street.","小販在街上賣水果。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0682":[["動詞、名詞：偷看；窺視","glance secretly","She peeked through the curtain before opening the front door.","她開門前先從窗簾後偷看。","peek 通常指短暫、偷偷地看。"]],"l5-0683":[["名詞：掛物用的小栓","無直接同義詞","He hung his raincoat on a wooden peg beside the entrance.","他把雨衣掛在入口旁的木栓上。","此句 peg 指牆上掛物用的小栓；stake 通常是插入地面的樁，不能直接代換。"]],"l5-0684":[["動詞：穿透","pierce / pass through","The roots penetrated the dry soil in search of water.","根部穿透乾燥土壤尋找水分。","penetrate 強調進入或穿過某物。"]],"l5-0685":[["vt：察覺；感知","understand / see","They perceive the problem differently.","他們對這個問題有不同的看法。","perceive 可指理解或察覺事物，尤其用於表達對情況的解讀方式。"]],"l5-0686":[["名詞、動詞：棲木；棲息","roost / settle","The hawk perched on a branch above the river.","老鷹棲息在河面上方的樹枝上。","perch 可指鳥停棲的位置或停棲動作。"]],"l5-0687":[["名詞：表演者","artist / entertainer","The performer bowed after completing the final dance.","表演者完成最後一支舞後鞠躬。","performer 泛指在觀眾面前演出的人。"]],"l5-0688":[["名詞：危險的事物","danger / hazard","Climbing the wet cliff without a rope would be a needless peril.","沒有繩索攀爬濕滑懸崖會帶來不必要的危險。","peril 是較正式的 danger。"]],"l5-0689":[["動詞：消滅；枯萎","die / be destroyed","Many seedlings perished during the unexpected week-long frost.","許多幼苗在意外持續一週的霜凍中枯死。","perish 是較正式的死亡或毀滅。"]],"l5-0690":[["形容詞：可允許的","allowable / acceptable","Only permissible expenses may be claimed on the travel form.","旅費表只能申報符合規定的支出。","permissible 表示規則或法律允許。"]],"l5-0691":[["vi / vt：堅持(說)","continue / persevere","He persisted in his efforts.","他堅持不懈地努力。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0692":[["n：(總稱)人員","staff / employees","The company needs more personnel.","公司需要更多人員。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0693":[["名詞：悲觀主義","negativity","His pessimism made him expect the project to fail before it began.","他的悲觀主義使他在專案開始前就預期失敗。","pessimism 是對結果持負面預期的態度。"]],"l5-0694":[["n：碼頭","dock / wharf","The ship is docked at the pier.","船停靠在碼頭。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0695":[["名詞：朝聖者；香客","religious traveler","Each pilgrim carried water while walking toward the mountain shrine.","每名朝聖者走向山中神社時都帶著水。","pilgrim 指前往宗教聖地的人。"]],"l5-0696":[["名詞：柱子","column / post","A stone pillar marked the entrance to the ancient temple.","一根石柱標示古老寺廟的入口。","pillar 可指支撐建築的柱子或比喻支柱。"]],"l5-0697":[["名詞：面皰","spot","A small pimple appeared on his cheek before the photograph was taken.","拍照前，他的臉頰上冒出一顆小面皰。","pimple 是皮膚上的小丘疹。"]],"l5-0698":[["動詞、名詞：擰；夾","squeeze / nip","She pinched the fabric between her fingers to test its thickness.","她用手指捏住布料測試厚度。","pinch 指用手指夾住或捏壓。"]],"l5-0699":[["動詞、名詞：小便","urinate / pee","The child asked to piss before the long bus journey began.","長途巴士出發前，孩子要求去小便。","piss 是粗俗口語；正式場合用 urinate。"]],"l5-0700":[["名詞：手槍","handgun / firearm","The officer locked the pistol in a secure evidence cabinet.","警員把手槍鎖進安全的證物櫃。","pistol 指可單手使用的短槍。"]],"l5-0701":[["名詞、動詞：瘟疫；折磨","epidemic / torment","The plague devastated several coastal towns during the fourteenth century.","十四世紀時，瘟疫摧毀了數個沿海城鎮。","plague 也可作動詞指持續折磨。"]],"l5-0702":[["名詞：農園；造林地","estate","The coffee plantation employs local workers during the harvest.","咖啡農園在收成期間雇用當地工人。","plantation 指大規模種植作物的農場。"]],"l5-0703":[["名詞：劇作家","dramatist","The playwright revised the final scene after the first rehearsal.","劇作家在第一次彩排後修改最後一幕。","playwright 專指創作戲劇的人。"]],"l5-0704":[["名詞：請求；藉口","appeal / excuse","The lawyer made a plea for leniency before sentencing.","宣判前，律師請求法官從輕處置。","plea 可指正式請求或法律答辯。"]],"l5-0705":[["動詞：辯護；承認","argue for / confess","The defendant pleaded guilty after discussing the evidence with counsel.","被告與律師討論證據後承認有罪。","plead guilty 是固定法律用語。"]],"l5-0706":[["名詞、動詞：保證；立誓","promise / vow","The company pledged to replace every defective product.","公司保證更換每件有瑕疵的產品。","pledge 表示莊重承諾，也可指抵押品。"]],"l5-0707":[["動詞、名詞：犁；耕地","till","Farmers plowed the field after the autumn rain softened the soil.","秋雨使土壤變軟後，農夫犁了田。","plow 可指犁具或耕地動作。"]],"l5-0708":[["動詞、名詞：拔","pull out","She plucked a loose thread from the sleeve of her jacket.","她從外套袖子拔掉一條鬆線。","pluck 可指迅速拔除，也可指彈奏弦樂器。"]],"l5-0709":[["vt / vi / n：(使)投入；跳入","drop / dive","Stock prices took a plunge.","股價暴跌了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0710":[["名詞：袖珍書","pocket book / small volume","He carried a pocketbook of poems in his coat during the train ride.","搭火車時，他把一本袖珍詩集放在外套裡。","pocketbook 在此指小型書本，不是錢包。"]],"l5-0711":[["形容詞：詩的","lyrical / verse-like","The novelist used poetic language to describe the quiet harbor.","小說家用詩意的語言描寫寧靜港口。","poetic 指具有詩歌般意象或節奏。"]],"l5-0712":[["動詞、名詞：戳","prod","The nurse poked the package gently to see whether it was still soft.","護士輕輕戳了戳包裹，確認它是否仍然柔軟。","poke 指用手指或尖物推戳。"]],"l5-0713":[["名詞：家禽","無直接同義詞","The farm raises poultry and sells fresh eggs to nearby restaurants.","農場飼養家禽，並把新鮮雞蛋賣給附近餐廳。","poultry 是雞、鴨等家養鳥類的總稱。"]],"l5-0714":[["形容詞：極地的","arctic","Researchers tracked polar bears across the melting sea ice.","研究人員追蹤北極熊穿越正在融化的海冰。","polar 指地球兩極或其寒冷地區。"]],"l5-0715":[["n：門廊；入口處","veranda","We sat on the front porch.","我們坐在前廊。","porch 在此指房屋入口外的廊道，翻譯為「前廊」。"]],"l5-0716":[["adj：潛在的","possible / prospective","This is a potential growth area.","這是潛在的成長領域。","此處 potential 為形容詞，表示可能發展或成長的。"]],"l5-0717":[["名詞：大草原；牧場","grassland","Bison wandered across the open prairie at the edge of the reserve.","野牛在保護區邊緣的開闊大草原上漫步。","prairie 指北美廣闊無樹草原。"]],"l5-0718":[["vt / vi / n：傳道；鼓吹","advocate / sermonize","He likes to preach his ideas.","他喜歡宣揚他的想法。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0719":[["n：預防(措施)；警惕","safeguard / preventive measure","Take safety precautions.","採取安全預防措施。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0720":[["n：偏好的事物","choice / liking","Do you have any preferences?","你有什麼偏好嗎？","採用既有原創例句；同義詞依該義項校對。"]],"l5-0721":[["形容詞：史前的","ancient","The cave contains prehistoric drawings of animals and hunters.","洞穴裡有史前動物與獵人的圖畫。","prehistoric 指有文字記錄以前的時代。"]],"l5-0722":[["vi：戰勝","triumph / succeed","Justice will prevail.","正義終將獲勝。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0723":[["n / vt：預習","look over","Can I preview the document?","我可以預覽這份文件嗎？","採用既有原創例句；同義詞依該義項校對。"]],"l5-0724":[["名詞：獵物","quarry","The eagle carried its prey to a high branch before eating.","老鷹把獵物帶到高樹枝上才進食。","prey 指被捕食的動物，也可作動詞。"]],"l5-0725":[["形容詞：無價的","invaluable","The handwritten letter is priceless to the family because it came from their founder.","這封手寫信對家族無價，因為它來自家族創辦人。","priceless 可指無法用金錢衡量的珍貴。"]],"l5-0726":[["動詞、名詞：刺；刺痛","sting","A thorn pricked her finger while she trimmed the rose bush.","她修剪玫瑰叢時，一根刺刺痛了手指。","prick 可指尖銳物刺入或造成刺痛。"]],"l5-0727":[["adj：優先的","previous / earlier","I have a prior engagement.","我先前已經有約了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0728":[["n：優先(權)","preference / importance","Safety is our top priority.","安全是我們最優先考量的事項。","top priority 表示最優先考量的事項。"]],"l5-0729":[["名詞：行進隊伍","march / parade","A torchlit procession moved slowly toward the town square.","火炬行進隊伍緩慢走向城鎮廣場。","procession 指按順序前進的一群人。"]],"l5-0730":[["名詞：輪廓；外型；人物簡介","outline / biographical summary","The magazine published a profile of the engineer behind the solar project.","雜誌刊登了這位太陽能專案工程師的人物簡介。","profile 可指人物介紹、輪廓或側面外型。"]],"l5-0731":[["vt：延長；拖長","extend / lengthen","The meeting was prolonged.","會議被延長了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0732":[["名詞、動詞：支柱；支撐；道具","support / stage prop","The stage crew used a wooden prop to keep the doorway upright.","舞台工作人員用木製支柱支撐門框直立。","prop 可指支撐物或戲劇道具。"]],"l5-0733":[["名詞：先知","seer","The prophet warned the king that the drought would continue.","先知警告國王乾旱將持續。","prophet 指宣講神意或預言未來的人。"]],"l5-0734":[["n：比例；比率","ratio / percentage","The proportion of men to women was nearly equal.","男性與女性的比例大致相等。","proportion of A to B 表示 A 與 B 的比例；nearly equal 表達比例大致相等。"]],"l5-0735":[["n：指望；預期；景象","outlook / possibility","The prospect of a new job is exciting.","新工作的展望令人興奮。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0736":[["n：省","region","He lives in that province.","他住在那個省。","province 指行政區域的省。"]],"l5-0737":[["名詞：梅乾；動詞：修剪","dried plum","The gardener pruned the apple tree before the new buds opened.","園丁在新芽綻放前修剪蘋果樹。","prune 作動詞指剪去枝葉；名詞是梅乾。"]],"l5-0738":[["vt：宣傳；公布","promote / advertise","They are trying to publicize the new campaign.","他們正試圖宣傳這項新活動。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0739":[["名詞：泡芙","cream puff / pastry","The bakery filled each puff with vanilla cream just before display.","麵包店在展示前才把每個泡芙填入香草奶油。","puff 在此指膨鬆的泡芙點心。"]],"l5-0740":[["n：脈搏","heartbeat","The doctor checked his pulse.","醫生檢查了他的脈搏。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0741":[["名詞：購買行為","無直接同義詞","I made a purchase online.","我在網路上買了東西。","make a purchase 表示購買；可改用動詞 buy 重述整句，但 buy 不能直接替換此處的名詞。"]],"l5-0742":[["名詞：金字塔","無直接同義詞","The archaeologists mapped the chambers inside the stepped pyramid.","考古學家繪製階梯金字塔內部墓室的地圖。","pyramid 指底部寬、向上逐漸變窄的立體形狀。"]],"l5-0743":[["名詞：呱呱聲；庸醫","croak / quack doctor","The duck gave a loud quack when the children approached the pond.","孩子們靠近池塘時，鴨子大聲呱呱叫。","quack 也可指沒有資格的醫生；本句採鳥叫義。"]],"l5-0744":[["vt：使合格 vi.取得資格","certify / enable","Does this training qualify you for the job?","這項培訓能讓你取得這份工作的資格嗎？","採用既有原創例句；同義詞依該義項校對。"]],"l5-0745":[["名詞：夸脫","無直接同義詞","The recipe calls for one quart of milk and two cups of flour.","食譜需要一夸脫牛奶和兩杯麵粉。","quart 是英美制液量單位，容量略有不同。"]],"l5-0746":[["名詞、動詞：尋求；追求","seek","The scientist began a quest for a cleaner source of energy.","那名科學家開始尋找更乾淨能源的追求。","quest 常指長期而艱苦的尋求。"]],"l5-0747":[["動詞、名詞：發抖；顫動","tremble / shake","The leaves quivered when a cold wind passed through the garden.","冷風吹過花園時，葉子顫動起來。","quiver 指快速而輕微地顫動。"]],"l5-0748":[["名詞、動詞：架子；折磨；過度使用","shelf / torment","The mechanic placed the tools on a rack beside the workbench.","技師把工具放在工作台旁的架子上。","rack 可指置物架，也可作動詞表示折磨。"]],"l5-0749":[["名詞：蘿蔔","無直接同義詞","She sliced a crisp radish into the summer salad.","她把爽脆的蘿蔔切片放進夏日沙拉。","radish 是根莖類蔬菜。"]],"l5-0750":[["名詞：半徑","無直接同義詞","The technician measured the circle’s radius before cutting the panel.","技術員在切割面板前量了圓的半徑。","radius 是圓心到圓周的距離。"]],"l5-0751":[["形容詞：破爛的","torn / shabby","The ragged tent could no longer protect the campers from the rain.","那頂破爛帳篷已無法保護露營者免受雨淋。","ragged 可指破舊、磨損或邊緣不整齊。"]],"l5-0752":[["名詞：欄杆；扶手；鐵軌","railing / track","He held the rail while climbing the steep station stairs.","他爬上車站陡梯時扶著欄杆。","rail 可指扶手、欄杆或鐵路軌道。"]],"l5-0753":[["vt / vi / n：重整旗鼓；集合","gathering / meeting","They held a political rally.","他們舉行了一場政治集會。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0754":[["名詞：大牧場","cattle farm","The family raises cattle on a remote ranch in western Montana.","這家人在蒙大拿州西部偏遠的大牧場飼養牛隻。","ranch 尤指大型畜牧農場。"]],"l5-0755":[["名詞：流氓；無賴","scoundrel / rogue","The shopkeeper recognized the rascal who had stolen from elderly customers.","店主認出那名偷竊老年顧客物品的無賴。","rascal 可是調皮搗蛋者，也可指壞人。"]],"l5-0756":[["n：比例","proportion / rate","The ratio of successful applicants to total applicants is small.","錄取者與申請總人數的比例很低。","ratio 表示兩個數量之間的比例，常用 ratio of A to B。"]],"l5-0757":[["動詞、名詞：喀喀聲","clatter","The loose window rattled whenever a truck passed the house.","卡車經過房子時，鬆動的窗戶就喀喀作響。","rattle 指連續快速的碰撞聲或震動。"]],"l5-0758":[["名詞：王國","kingdom / domain","The ancient realm stretched from the mountains to the sea.","古代王國從山脈延伸到海邊。","realm 可指國家、領域或抽象範圍。"]],"l5-0759":[["動詞：收割","harvest / gather","Farmers reap the rice when the grains turn golden.","稻穀變成金色時，農夫便收割稻米。","reap 也可比喻得到行動的結果。"]],"l5-0760":[["n：後方 vt.撫養 vi.高聳","back","The entrance is at the rear.","入口在後面。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0761":[["形容詞：魯莽的","rash / careless","The reckless driver overtook three cars on the narrow mountain road.","那名魯莽的駕駛在狹窄山路上超越三輛車。","reckless 指不顧危險或後果。"]],"l5-0762":[["動詞：計算；認為","calculate / suppose","I reckon the repairs will cost less than replacing the entire machine.","我認為修理費會低於更換整台機器。","reckon 作口語動詞可表示估計或認為。"]],"l5-0763":[["vt / vi：推薦","suggest / endorse","I recommend this book.","我推薦這本書。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0764":[["名詞：礁石","無直接同義詞","The boat slowed near the coral reef to avoid damaging its hull.","船在珊瑚礁附近減速，以免損壞船身。","reef 是海面下或近海的岩礁。"]],"l5-0765":[["名詞：捲、捆","roll / coil","The electrician carried a reel of cable into the construction site.","電工把一捲電纜帶進工地。","reel 指纏繞成卷的材料或捲軸。"]],"l5-0766":[["名詞：裁判","official / umpire","The referee stopped the match when the goalkeeper was injured.","守門員受傷時，裁判中止了比賽。","referee 在足球、籃球等運動中執法。"]],"l5-0767":[["名詞：避難所","shelter / safe haven","The hikers reached a mountain refuge before the snowstorm intensified.","暴風雪加劇前，健行者抵達山區避難所。","refuge 指提供安全保護的地方。"]],"l5-0768":[["名詞：聖殿；庇護所","shrine","The birds found sanctuary in the protected wetland.","鳥群在受保護的濕地找到庇護所。","sanctuary 可指宗教聖地或安全避難處。"]],"l5-0769":[["vt：駁斥、反駁","deny / disprove","He refuted the claim.","他駁斥了那個說法。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0770":[["名詞：君王在位期間","rule / sovereignty","During her reign, the queen expanded the public library system.","女王在位期間擴建了公共圖書館系統。","reign 指君王統治的期間。"]],"l5-0771":[["動詞：歡欣；快樂","celebrate / be joyful","The villagers rejoiced when the missing child was found unharmed.","失蹤孩童平安找到時，村民們歡欣不已。","rejoice 是較正式的喜悅表達。"]],"l5-0772":[["名詞：遺物","remnant / artifact","The museum displayed a relic from the city’s medieval wall.","博物館展示一件來自城市中世紀城牆的遺物。","relic 指保存下來的歷史物件或遺留物。"]],"l5-0773":[["n：提醒物","memo / prompt","I set a reminder for the meeting.","我設定了會議提醒。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0774":[["動詞：償還；回報","reimburse / pay back","She repaid the loan before the final due date.","她在最後期限前償還了貸款。","repay 可指償還金錢或回報恩惠；原卡較窄地只列回報義。"]],"l5-0775":[["動詞：繁殖；複製","breed / duplicate","The laboratory reproduced the experiment to confirm the original result.","實驗室重做實驗以確認原始結果。","reproduce 可指繁殖、生產或重現。"]],"l5-0776":[["名詞：爬蟲類","無直接同義詞","The turtle is a reptile with a hard shell and cold blood.","烏龜是有硬殼且冷血的爬蟲類。","reptile 包括蛇、蜥蜴、龜和鱷魚。"]],"l5-0777":[["形容詞：共和政體的","nonmonarchical","The country adopted a republican constitution after the revolution.","革命後，該國採用了共和政體的憲法。","republican 在此指國家制度，不是政黨名稱。"]],"l5-0778":[["動詞：怨恨","begrudge","He resented being excluded from the team’s important decision.","他怨恨自己被排除在團隊的重要決定之外。","resent 指因不公平而長期不滿。"]],"l5-0779":[["名詞：怨恨","bitterness","Years of resentment damaged the relationship between the brothers.","多年的怨恨損害了兄弟之間的關係。","resentment 是持續累積的不滿情緒。"]],"l5-0780":[["動詞：居住","live / dwell","The artist resides in a small apartment above her studio.","那位藝術家住在工作室樓上的小公寓。","reside 較正式，常用於居住地。"]],"l5-0781":[["n：住所","home / dwelling","They moved to a new residence.","他們搬到了一處新住所。","residence 指住所或居所，語氣比 home 正式。"]],"l5-0782":[["n：居民","inhabitant","She is a local resident.","她是當地居民。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0783":[["vi：訴諸於… n.度假勝地","vacation spot","They went to a ski resort.","他們去了滑雪度假勝地。","resort 作名詞時指度假勝地。"]],"l5-0784":[["動詞：抑制","hold back","The nurse restrained the dog gently while the veterinarian treated its paw.","獸醫治療狗掌時，護士輕輕制住那隻狗。","restrain 指控制行動或衝動。"]],"l5-0785":[["vt / vi：重新開始；繼續","restart / continue","We will resume the meeting shortly.","我們將稍後恢復會議。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0786":[["動詞、名詞：反擊；反駁","reply sharply / comeback","“That is not evidence,” she retorted during the debate.","她在辯論中反駁：「那不是證據。」","retort 常指迅速而尖銳的回答。"]],"l5-0787":[["adj / vt / vi / n：顛倒(的)；倒轉","opposite / turn around","The result was the reverse.","結果恰恰相反。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0788":[["動詞：復甦","recover / restore","Warm spring weather revived the plants damaged by frost.","溫暖的春天天氣使遭霜害的植物復甦。","revive 可指恢復生命、活力或興趣。"]],"l5-0789":[["動詞、名詞：造反；使厭惡；反叛","rebel","The soldiers revolted against the corrupt governor.","士兵反抗貪腐的總督。","revolt 作動詞指起義；作名詞指叛亂。"]],"l5-0790":[["vi / vt：(使)旋轉","rotate","The earth revolves around the sun.","地球繞著太陽運轉。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0791":[["名詞：犀牛","rhino","The ranger photographed a rhinoceros grazing near the water hole.","巡護員拍下犀牛在水坑附近吃草的照片。","rhino 是 rhinoceros 的常用縮寫。"]],"l5-0792":[["名詞：肋骨","無直接同義詞","He cracked a rib when he fell from the bicycle.","他從自行車摔下來時弄裂了一根肋骨。","rib 是胸腔中保護內臟的弧形骨頭。"]],"l5-0793":[["名詞：山脊；梁","crest","A narrow ridge separates the two valleys.","一道狹窄山脊分隔兩座山谷。","ridge 可指狹長隆起的山地或物體。"]],"l5-0794":[["adj：荒謬的","absurd / silly","That is a ridiculous idea.","那是一個荒謬的想法。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0795":[["名詞：步槍","long gun","The museum keeps an unloaded rifle in its military history display.","博物館在軍事史展區展示一支未裝彈的步槍。","rifle 是具有膛線的長槍。"]],"l5-0796":[["adj：嚴苛的","inflexible / strict","The rules are too rigid.","這些規則太僵化了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0797":[["名詞：邊緣","edge / border","A drop of paint dried on the rim of the metal bucket.","一滴油漆在金屬桶的邊緣乾掉了。","rim 指圓形容器或物體的外緣。"]],"l5-0798":[["動詞、名詞：撕扯；裂縫","tear / split","Be careful not to rip the fragile map while unfolding it.","展開脆弱的地圖時，小心不要把它撕破。","rip 強調快速或用力撕裂。"]],"l5-0799":[["名詞：漣漪","small wave","A stone landed in the pond and sent ripples across the water.","石頭落入池塘，在水面漾起漣漪。","ripple 指由擾動產生的小波紋。"]],"l5-0800":[["名詞：對手","competitor / opponent","Her closest rival finished only two seconds behind her.","她最接近的對手只比她晚兩秒完成比賽。","rival 指爭奪同一目標的競爭者。"]],"l5-0801":[["動詞、名詞：漫遊","wander","The rescue dog roamed the hills until it found the missing camper.","搜救犬在山丘漫遊，直到找到失蹤的露營者。","roam 表示沒有固定路線地走動。"]],"l5-0802":[["名詞：知更鳥","無直接同義詞","A robin built its nest in the apple tree beside the porch.","一隻知更鳥在門廊旁的蘋果樹築巢。","robin 在英美可指不同但相近的鳥種。"]],"l5-0803":[["adj：強健的","strong / healthy","The system is robust.","這個系統很強健。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0804":[["名詞：棍子","stick","The surveyor used a measuring rod to mark the boundary.","測量員用測量桿標示邊界。","rod 通常指細長而堅硬的桿子。"]],"l5-0805":[["名詞：垃圾","trash / waste","Please put the rubbish in the recycling bin rather than on the pavement.","請把垃圾放進回收桶，不要丟在人行道上。","rubbish 是英式常用的 trash。"]],"l5-0806":[["adj：高低不平的","uneven / rough","The terrain is rugged.","地形崎嶇。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0807":[["動詞、名詞：隆隆響","thunder","Thunder rumbled beyond the hills as the storm approached.","暴風雨接近時，山丘外傳來雷聲隆隆。","rumble 指低沉而持續的聲音。"]],"l5-0808":[["動詞、名詞：沙沙作響","swish","Dry leaves rustled under the hikers’ boots.","乾葉在健行者的靴子下沙沙作響。","rustle 常指葉片或布料摩擦的聲音。"]],"l5-0809":[["形容詞：神聖的","holy / consecrated","The pilgrims removed their shoes before entering the sacred hall.","朝聖者進入神聖的大廳前脫下鞋子。","sacred 指受宗教尊崇或不可褻瀆。"]],"l5-0810":[["名詞：馬鞍","無直接同義詞","The rider checked the saddle straps before mounting the horse.","騎士上馬前檢查馬鞍繫帶。","saddle 是放在馬背上供騎乘的座具。"]],"l5-0811":[["名詞：聖徒","無直接同義詞","The cathedral holds a statue of Saint Francis near the altar.","大教堂祭壇旁有一尊聖方濟各雕像。","saint 可指基督宗教認可的聖人。"]],"l5-0812":[["名詞：鮭魚","無直接同義詞","The river is famous for salmon that return upstream each autumn.","這條河以每年秋天洄游上游的鮭魚聞名。","salmon 的複數形式通常仍是 salmon。"]],"l5-0813":[["vt / vi / n：敬禮","honor / acknowledge","The soldier saluted the officer.","士兵向軍官敬禮。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0814":[["名詞：涼鞋","無直接同義詞","She wore leather sandals during the hot coastal walk.","她在炎熱的海岸步行時穿著皮涼鞋。","sandal 是露出部分腳面的輕便鞋。"]],"l5-0815":[["形容詞、名詞：野蠻的；野蠻人","brutal","The documentary describes how the savage attack displaced an entire village.","紀錄片描述那場野蠻攻擊如何迫使整座村莊的人流離失所。","savage 可指殘酷，也可指未開化；後者可能帶貶意。"]],"l5-0816":[["vt / vi / n：掃描","digitize / inspect","Please scan the document.","請掃描這份文件。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0817":[["名詞：醜聞","disgrace","The minister resigned after the financial scandal became public.","財務醜聞曝光後，部長辭職。","scandal 指引起公眾震驚或非議的事件。"]],"l5-0818":[["名詞：傷痕","mark","The surgery left a small scar below her left knee.","手術在她左膝下方留下小小的傷痕。","scar 可指傷口癒合後留下的痕跡。"]],"l5-0819":[["名詞：香氣","fragrance","The scent of jasmine drifted through the open kitchen window.","茉莉的香氣飄進敞開的廚房窗戶。","scent 可指香味，也可指動物追蹤的氣味。"]],"l5-0820":[["n：計畫","plan / project","They have a new marketing scheme.","他們有一個新的行銷方案。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0821":[["動詞、名詞：輕蔑","despise / contempt","She scorned the offer because it ignored the workers’ safety.","她鄙視那份忽視工人安全的提議。","scorn 可作動詞或名詞，表示強烈輕蔑。"]],"l5-0822":[["動詞：爭先恐後地做；慌忙處理","clamber / assemble hastily","The volunteers scrambled to find enough blankets for the evacuees.","志工們慌忙找足夠的毯子給撤離者。","scramble 可指匆忙行動或攀爬。"]],"l5-0823":[["名詞、動詞：碎片；當廢紙扔掉","fragment / discard","The editor kept a scrap of the original poster for the archive.","編輯保留原海報的一小片作為檔案。","scrap 可指小碎片，也可指廢棄物。"]],"l5-0824":[["動詞、名詞：刮；擦","rub / graze","The box scraped the floor as we moved it into the storeroom.","我們把箱子搬進儲藏室時，箱子刮過地板。","scrape 指摩擦造成刮痕或聲音。"]],"l5-0825":[["名詞：卷軸","manuscript roll","The archivist unrolled a fragile scroll under controlled light.","檔案員在受控燈光下展開脆弱的卷軸。","scroll 是捲起保存的長幅文件。"]],"l5-0826":[["名詞：雕刻家","artist","The sculptor shaped the marble block into a lifelike horse.","雕刻家把大理石塊雕成栩栩如生的馬。","sculptor 專指創作立體雕塑的藝術家。"]],"l5-0827":[["adj：安全的 vt.vi.(使)變安全","safe / protected","The system is secure.","這系統很安全。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0828":[["n：部分","part / section","This is a market segment.","這是一個細分市場。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0829":[["n：感覺；轟動(的事)","feeling / buzz","It caused a sensation.","它引起了一陣轟動。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0830":[["n：敏感度","responsiveness","The device has high sensitivity.","這個裝置的敏感度很高。","sensitivity 在此指裝置感測或察覺的敏感度。"]],"l5-0831":[["名詞：情緒","feeling","Public sentiment shifted after the report revealed the river pollution.","報告揭露河川污染後，公眾情緒改變了。","sentiment 指群體或個人的態度與感受。"]],"l5-0832":[["名詞：陸軍中士","noncommissioned officer","The sergeant organized the supplies before the unit left the base.","中士在部隊離開基地前整理物資。","sergeant 是軍中的士官階級。"]],"l5-0833":[["名詞：系列","sequence / set","The museum will present a series of lectures on maritime history.","博物館將推出一系列海事史講座。","series 的單複數形式相同。"]],"l5-0834":[["名詞：佈道","religious address","The pastor’s sermon focused on forgiveness and community service.","牧師的佈道著重寬恕與社區服務。","sermon 是宗教場合的講道。"]],"l5-0835":[["n：服務生；發球員；伺服器","waiter / waitress","The server was polite.","服務生很有禮貌。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0836":[["n：安裝；環境；背景；佈景","environment / location","The setting is very peaceful.","這裡的環境非常寧靜。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0837":[["形容詞：破爛的","worn / threadbare","The charity collected shabby coats for families facing the winter cold.","慈善機構為面對冬寒的家庭募集破舊外套。","shabby 指破舊、失去光澤或品質不佳。"]],"l5-0838":[["vt / vi：(使)變銳利；磨尖","hone","Please sharpen the pencil before the test.","請在考試前把鉛筆削尖。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0839":[["動詞：粉碎","smash / break into pieces","The dropped glass shattered on the kitchen floor.","掉落的玻璃杯在廚房地板上摔得粉碎。","shatter 強調碎成許多片，也可指信念破滅。"]],"l5-0840":[["名詞：警長","county law officer","The sheriff spoke with residents after the storm damaged the bridge.","暴風雨損壞橋梁後，警長與居民交談。","sheriff 是美國郡級執法官員。"]],"l5-0841":[["名詞：盾牌","protective barrier","The firefighter raised a shield against the falling sparks.","消防員舉起盾牌擋住掉落的火花。","shield 可指防護裝備或比喻保護。"]],"l5-0842":[["動詞、名詞：打顫","tremble","He shivered in the cold wind while waiting for the delayed bus.","他在寒風中等候誤點的公車時不停發抖。","shiver 通常因寒冷或恐懼而顫抖。"]],"l5-0843":[["n：短缺","scarcity / deficiency","There is a food shortage.","有食物短缺的問題。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0844":[["n：缺點","flaw / weakness","He knows his own shortcomings.","他知道自己的缺點。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0845":[["動詞：推","push","The guard shoved the heavy door closed against the strong wind.","警衛用力把沉重的門推上，抵擋強風。","shove 比 push 更強調用力或粗魯。"]],"l5-0846":[["n：碎片；vt：切成條狀","tear / cut","Please shred these documents.","請把這些文件切碎。","shred 作動詞時表示把紙張等切成細條或碎片。"]],"l5-0847":[["動詞、名詞：尖叫","scream","A shriek came from the theater when the lights suddenly went out.","劇院燈光突然熄滅時，裡面傳來一聲尖叫。","shriek 指尖銳高亢的叫聲。"]],"l5-0848":[["名詞：神龕；聖地","holy place","Visitors left flowers at the shrine to honor the village’s founder.","訪客在神龕前獻花，向村莊創辦人致敬。","shrine 是供奉神聖人物或物件的地方。"]],"l5-0849":[["n：灌木","bush","They planted a shrub.","他們種了一株灌木。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0850":[["動詞、名詞：發抖","tremble / shake","The windows shuddered when the freight train passed nearby.","貨運列車經過附近時，窗戶震動起來。","shudder 可指因恐懼、寒冷或震動而顫抖。"]],"l5-0851":[["名詞：百葉窗；快門","blind / camera shutter","She closed the shutters before the afternoon sun overheated the room.","午後陽光使房間過熱前，她關上了百葉窗。","shutter 也可指相機快門；本句採窗板義。"]],"l5-0852":[["名詞：蠶","無直接同義詞","The farmer raises silkworms on mulberry leaves for the local textile mill.","農夫以桑葉飼養蠶，供應當地紡織廠。","silkworm 是吐絲結繭的蠶蛾幼蟲。"]],"l5-0853":[["動詞、名詞：燉","cook gently","Let the sauce simmer for twenty minutes so the onions become tender.","讓醬汁燉煮二十分鐘，使洋蔥變軟。","simmer 指液體接近沸騰但不上滾地慢煮。"]],"l5-0854":[["名詞：骨骸","bones","The archaeologist uncovered a human skeleton beneath the ancient floor.","考古學家在古老地板下發現人類骨骸。","skeleton 指骨骼整體，也可作結構的比喻。"]],"l5-0855":[["名詞：頭蓋骨","cranium","The helmet protected the cyclist’s skull during the fall.","跌倒時，安全帽保護了自行車騎士的頭蓋骨。","skull 是包覆腦部的頭部骨骼。"]],"l5-0856":[["動詞、名詞：摑","strike with the palm","She slapped the mosquito on her arm before it could bite.","蚊子要咬她前，她拍打了手臂上的蚊子。","slap 常指用手掌快速擊打。"]],"l5-0857":[["動詞、名詞：屠宰","butcher","The documentary explains how the farm stopped slaughtering animals for meat.","紀錄片說明這座農場如何停止為肉品屠宰動物。","slaughter 也可指大規模殺戮，語氣強烈。"]],"l5-0858":[["動詞：殺害","kill / murder","The legend says the hero slew the dragon with a silver sword.","傳說英雄用銀劍殺死了巨龍。","slay 是較文學化的 kill。"]],"l5-0859":[["形容詞：草率的","careless / untidy","The sloppy report contained misspelled names and missing figures.","那份草率的報告有拼錯的姓名和遺漏的數字。","sloppy 可指粗心、不整潔或液體濺灑。"]],"l5-0860":[["動詞、名詞：衰落","decline / downturn","The factory suffered a slump in orders after its largest customer moved abroad.","最大客戶移往海外後，工廠訂單大幅下滑。","slump 指突然且明顯的下降。"]],"l5-0861":[["形容詞：狡猾的","cunning / crafty","The sly fox waited until the farmer left before entering the henhouse.","狡猾的狐狸等農夫離開後才進入雞舍。","sly 常指以欺騙手段達成目的。"]],"l5-0862":[["動詞、名詞：撞毀；粉碎","crush","The falling tree smashed the garden shed during the storm.","暴風雨中倒下的樹撞毀了花園小屋。","smash 強調猛烈撞擊造成破壞。"]],"l5-0863":[["動詞、名詞：吠；咆哮","growl","The dog snarled when the stranger reached toward its injured paw.","陌生人伸手靠近受傷的狗掌時，狗發出咆哮。","snarl 是帶威脅意味的吼叫。"]],"l5-0864":[["動詞、名詞：奪走","grab / seize","The pickpocket snatched her phone and disappeared into the crowd.","扒手奪走她的手機，消失在人群中。","snatch 指突然快速地搶走。"]],"l5-0865":[["動詞、名詞：偷偷走；偷偷做","creep","The children sneaked downstairs to watch the surprise cake being decorated.","孩子們偷偷下樓，觀看驚喜蛋糕的裝飾過程。","sneak 強調秘密且不被發現的行動。"]],"l5-0866":[["名詞：運動鞋；鬼祟的人","trainers / furtive person","He changed into sneakers before joining the charity basketball game.","他加入慈善籃球賽前換上運動鞋。","sneakers 是美式用法；英式常說 trainers。"]],"l5-0867":[["動詞、名詞：嗅","smell","The dog sniffed the parcel before the handler opened it.","訓犬員打開包裹前，狗先嗅了嗅包裹。","sniff 指短促地用鼻子聞。"]],"l5-0868":[["動詞、名詞：打呼","breathe noisily","My brother snored so loudly that I moved to the spare room.","我哥哥打呼太大聲，我只好搬到客房睡。","snore 通常指睡眠時發出的聲音。"]],"l5-0869":[["動詞、名詞：噴鼻息","blow through the nose","The horse snorted when the unfamiliar saddle was placed on its back.","陌生馬鞍放上馬背時，馬噴了噴鼻息。","snort 可指馬鼻息或人不屑地哼聲。"]],"l5-0870":[["動詞、名詞：浸泡","steep","Soak the beans overnight before cooking them in the pressure cooker.","把豆子浸泡一晚，再放入壓力鍋烹煮。","soak 指讓物品長時間浸在液體中。"]],"l5-0871":[["形容詞：清醒的","awake","The driver remained sober and alert throughout the overnight trip.","那名駕駛在整晚旅程中保持清醒警覺。","sober 可指未醉，也可指嚴肅。"]],"l5-0872":[["動詞：變柔軟","make tender","Heat softened the wax enough for the artist to shape it.","熱度使蠟變軟，足以讓藝術家塑形。","soften 可指質地、語氣或態度變柔和。"]],"l5-0873":[["名詞、形容詞：鞋底；單獨的","underside / only","The sole of the hiking boot was worn smooth after years of use.","這雙健行靴的鞋底使用多年後磨得平滑。","sole 作鞋底與作「唯一的」是不同義項。"]],"l5-0874":[["形容詞：莊嚴的","serious / ceremonial","The judge delivered a solemn warning before announcing the sentence.","法官宣布判決前發表嚴肅的警告。","solemn 指嚴肅、莊重而不輕浮。"]],"l5-0875":[["adj：獨自的","alone / single","He is a solitary person.","他是個獨來獨往的人。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0876":[["名詞、形容詞：獨唱；單獨的","unaccompanied","The violinist performed a solo before the orchestra returned to the stage.","管弦樂團回到舞台前，小提琴家演奏了一段獨奏。","solo 可作名詞、形容詞或副詞。"]],"l5-0877":[["形容詞：具獨立主權的","independent / autonomous","The treaty recognized the island as a sovereign state.","條約承認這座島是具獨立主權的國家。","sovereign 指擁有最高統治權或獨立主權。"]],"l5-0878":[["動詞、名詞：播種；母豬","plant seeds","Farmers sow wheat in autumn and harvest it the following summer.","農夫在秋天播種小麥，隔年夏天收割。","sow 作動詞是播種；名詞母豬讀音不同。"]],"l5-0879":[["名詞：太空船","space vehicle","The spacecraft transmitted images of the planet’s rings to Earth.","太空船把行星環的影像傳回地球。","spacecraft 可泛指進入太空的載具。"]],"l5-0880":[["名詞：太空船","spacecraft","The science-fiction film shows a spaceship traveling beyond the solar system.","科幻電影描寫太空船飛越太陽系。","spaceship 常用於科幻或一般敘述；spacecraft 較正式。"]],"l5-0881":[["n：專家","expert","He is a marketing specialist.","他是一位行銷專家。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0882":[["n：標本","sample","They analyzed the specimen.","他們分析了這份標本。","specimen 指供研究或檢驗的標本；sample 的涵義較廣。"]],"l5-0883":[["名詞：奇觀；眼鏡","wonder / spectacles","The northern lights were a breathtaking spectacle above the frozen lake.","冰湖上空的北極光是一幅令人屏息的壯觀景象。","spectacle 可指令人驚嘆的景象；複數 spectacles 指眼鏡。"]],"l5-0884":[["n：觀眾","viewer / observer","The spectators cheered.","觀眾歡呼了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0885":[["名詞：脊椎","backbone","The doctor checked the runner’s spine after the collision.","碰撞後，醫師檢查跑者的脊椎。","spine 是支撐軀幹的脊柱，也可指書脊。"]],"l5-0886":[["n：壯麗","grandeur / magnificence","The splendor of the palace is amazing.","宮殿的輝煌令人驚嘆。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0887":[["名詞：海綿","無直接同義詞","Use a soft sponge to clean the paint from the window.","用柔軟海綿清掉窗戶上的油漆。","sponge 可指吸水清潔用品或海洋動物。"]],"l5-0888":[["名詞：聚光燈","stage light / beam","The singer stepped into the spotlight as the orchestra began.","管弦樂團開始演奏時，歌手走進聚光燈下。","spotlight 可指舞台燈，也可比喻公眾注意。"]],"l5-0889":[["動詞、名詞：衝刺","dash","She sprinted the final fifty meters and won the race.","她衝刺最後五十公尺，贏得比賽。","sprint 指短距離全速奔跑。"]],"l5-0890":[["名詞、動詞：靴刺；激勵","encourage","The coach’s praise spurred the team to practice harder.","教練的讚美激勵團隊更加努力練習。","spur 可指馬刺或促使某人行動。"]],"l5-0891":[["名詞、動詞：南瓜；擠壓","pumpkin / press","She made a squash soup from the pumpkins harvested in October.","她用十月採收的南瓜煮湯。","squash 也可指壓扁或壁球運動。"]],"l5-0892":[["動詞、名詞：蹲","crouch","The mechanic squatted beside the engine to inspect the loose belt.","技師蹲在引擎旁檢查鬆脫的皮帶。","squat 指屈膝降低身體或蹲姿。"]],"l5-0893":[["n：(乾草等)堆","pile","A stack of files sat on her desk.","她的桌上放著一疊文件。","stack 作名詞可指整齊堆疊的一疊物品；本句採名詞義。"]],"l5-0894":[["動詞、名詞：猛關；砰然聲","bang","He slammed the locker door after discovering that his keys were missing.","發現鑰匙不見後，他猛地關上置物櫃門。","slam 強調用力撞擊或關閉。"]],"l5-0895":[["動詞、名詞：蹣跚","stumble / reel","The exhausted hiker staggered toward the shelter through the snow.","疲憊的健行者蹣跚穿過雪地走向避難所。","stagger 指失去平衡、不穩地走。"]],"l5-0896":[["n：沾汙；汙點","spot / mark","There is a stain on the shirt.","襯衫上有一個汙點。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0897":[["名詞：樁；賭注；危險","wager","The workers drove a stake into the ground to mark the new fence line.","工人把樁打入地面標示新圍籬線。","stake 也可指賭注或利害關係。"]],"l5-0898":[["名詞、動詞：莖；悄悄追蹤","stem / follow secretly","The detective noticed someone stalking the witness outside the courthouse.","偵探注意到有人在法院外悄悄跟蹤證人。","stalk 作動詞指持續秘密跟蹤；名詞可指植物莖。"]],"l5-0899":[["n：(牲畜的)欄；廄","pen / stable","The farmer cleaned the cattle stall.","農夫清理了牛欄。","stall 可指牲畜的欄舍，也可指市場攤位；本句採牲畜欄舍義。"]],"l5-0900":[["名詞：詩節","verse","The final stanza repeats the image of the river returning to the sea.","最後一節詩重複河流回到大海的意象。","stanza 是詩中由數行組成的一節。"]],"l5-0901":[["vt / vi / n：(使)驚嚇","surprise / shock","He was startled by the noise.","他被噪音嚇到了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0902":[["名詞：政治家","politician / public leader","The respected statesman negotiated a peace agreement between the two countries.","受人敬重的政治家協商兩國間的和平協議。","statesman 常含有成熟、有原則的正面評價。"]],"l5-0903":[["名詞：統計數字","figure / data","The latest statistics show a sharp fall in workplace accidents.","最新統計數字顯示職場事故大幅下降。","statistic 是可量化的資料；statistics 也指統計學。"]],"l5-0904":[["形容詞：統計數字的","numerical","The researchers used statistical analysis to compare the two treatments.","研究人員用統計分析比較兩種治療方式。","statistical 指與統計資料或方法有關。"]],"l5-0905":[["名詞：汽船；蒸籠","steamboat / food steamer","The steamer carried passengers along the river to the old port.","汽船載著乘客沿河前往舊港。","steamer 可指蒸汽船或蒸煮食物的器具。"]],"l5-0906":[["vt / vi：駕駛","drive / guide","He steered the car carefully.","他小心地駕駛汽車。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0907":[["名詞：刻板印象","cliché","The campaign challenges the stereotype that older workers cannot learn technology.","這項宣傳挑戰年長工作者無法學習科技的刻板印象。","stereotype 是過度簡化且固定的觀念。"]],"l5-0908":[["形容詞：嚴厲的","strict / severe","The stern teacher expected every student to meet the deadline.","那名嚴厲的老師要求每位學生遵守期限。","stern 可指人嚴厲，也可指船尾。"]],"l5-0909":[["動詞、名詞：燉；燉肉","braise","The cook stewed the beef with carrots until it became tender.","廚師把牛肉和紅蘿蔔燉到軟嫩。","stew 可作烹調動詞或燉煮的菜餚。"]],"l5-0910":[["名詞：男服務員","attendant","The train steward helped passengers find their reserved seats.","火車服務員協助乘客找到預訂座位。","steward 可指交通工具上的服務員。"]],"l5-0911":[["名詞：女服務員（較舊用法）","female attendant","The stewardess brought blankets to passengers on the overnight flight.","女服務員在夜間航班上替乘客送來毛毯。","stewardess 是較舊的性別化稱呼；現代航空業通常使用 flight attendant。"]],"l5-0912":[["名詞：服務員","assistant","A museum attendant answered questions about the ancient paintings.","博物館服務員回答古畫相關問題。","attendant 泛指在場所提供協助的人。"]],"l5-0913":[["動詞、名詞：發臭；惡臭","smell bad / stench","The garbage began to stink after the collection truck was delayed.","垃圾車延誤後，垃圾開始發臭。","stink 可作動詞或名詞，語氣強烈。"]],"l5-0914":[["名詞：庫存","inventory / supply","We have plenty of stock.","我們有充足的庫存。","此句 stock 指供應或販售中的存貨，通常作不可數名詞；股票是另一個義項。"]],"l5-0915":[["動詞、名詞：俯身","bend down","He stooped to pick up the shell beside the path.","他俯身撿起小徑旁的貝殼。","stoop 指彎腰或身體前傾。"]],"l5-0916":[["n：貯藏","keeping","We need more storage space.","我們需要更多儲存空間。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0917":[["形容詞：堅固的","sturdy / solid","The stout wooden table supported all the equipment in the workshop.","堅固的木桌支撐了工坊裡所有設備。","stout 可指結實，也可指身材肥胖或酒味濃。"]],"l5-0918":[["動詞：弄直；好轉","make straight / correct","She straightened the bent frame before hanging the photograph.","她把彎曲的相框弄直後才掛上照片。","straighten 可指變直，也可指整理或改善。"]],"l5-0919":[["adj：直率的；簡單明確的","clear / simple / direct","The instructions are straightforward.","這些說明很簡單明確。","此處 straightforward 指說明清楚、容易理解；形容人的個性時則可指直率。"]],"l5-0920":[["動詞、名詞：拉緊","tension","The rope strained under the weight of the rescue basket.","救援籃的重量使繩索承受拉力。","strain 可指拉緊、壓力或過度使用造成的傷害。"]],"l5-0921":[["名詞：海峽","channel","The ship passed through the narrow strait between the two islands.","船通過兩座島嶼之間狹窄的海峽。","strait 是連接兩大片水域的狹窄水道。"]],"l5-0922":[["名詞、動詞：線；繩；擱淺","shore / rope strand","The whale became stranded on the beach when the tide went out.","退潮時，那頭鯨魚擱淺在海灘上。","strand 作動詞指使人或動物擱淺；名詞可指一股線。"]],"l5-0923":[["n：帶子","belt / tie","The strap is broken.","帶子斷了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0924":[["動詞、形容詞、名詞：迷路；流浪","lost / wandering","A stray dog followed the mail carrier through the quiet neighborhood.","一隻流浪狗跟著郵差穿過安靜的社區。","stray 可指偏離路線或無主的動物。"]],"l5-0925":[["名詞：條紋","stripe","A bright streak of orange appeared across the evening sky.","傍晚天空出現一道明亮的橘色條紋。","streak 指細長的線條或連續成績。"]],"l5-0926":[["動詞、名詞：大步走","step","She strode confidently into the interview room.","她自信地大步走進面試室。","stride 指大而有力的步伐，也可作動詞。"]],"l5-0927":[["名詞：條紋","band","A blue stripe runs along the side of the racing bicycle.","一條藍色條紋沿著競賽自行車側面延伸。","stripe 指長而窄的色帶或標記。"]],"l5-0928":[["vi / vt / n：閒逛","walk","Let's take a stroll in the park.","我們去公園散步吧。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0929":[["形容詞：結構的","load-bearing / foundational","Engineers found structural damage beneath the bridge’s outer paint.","工程師在橋梁外漆下發現結構損壞。","structural 關乎支撐結構，而非表面。"]],"l5-0930":[["動詞：絆倒","trip","She stumbled over a loose cable while carrying the projector.","她搬投影機時被鬆脫的電纜絆倒。","stumble 可指失去平衡，也可指犯錯。"]],"l5-0931":[["名詞、動詞：殘幹；笨重地走","trudge","He stumped along the muddy road after the long hike.","長途健行後，他沿著泥濘的道路蹣跚前行。","stump 作動詞可指笨重、吃力地走；作名詞則指樹被砍後留下的樹樁。"]],"l5-0932":[["動詞：使昏厥","daze / knock unconscious","The bright flash stunned the photographer for several seconds.","強光閃過，使攝影師昏眩了幾秒鐘。","stun 可指使人昏厥或極度震驚。"]],"l5-0933":[["形容詞：結實的","strong / robust","The sturdy shelves held hundreds of reference books without bending.","結實的架子承載數百本參考書而沒有彎曲。","sturdy 強調堅固耐用。"]],"l5-0934":[["動詞、名詞：結巴","stammer / falter","He stuttered when asked to explain the missing receipts.","被要求解釋遺失收據時，他說話結巴。","stutter 可指說話反覆卡住，也可指口吃。"]],"l5-0935":[["adj：時髦的；流行的","fashionable / trendy / chic","She wears stylish clothes.","她穿著時髦的衣服。","stylish 指外觀或風格時髦；本句修飾 clothes。"]],"l5-0936":[["vt：(使…)順服；提交","hand in","Please submit your resume.","請提交您的履歷。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0937":[["adj：真實的；大量的","considerable / significant","There is a substantial improvement.","有顯著的改善。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0938":[["n：替代物；vt.vi：代替；adj：代替的","replace / use instead of","You can substitute honey for sugar in this recipe.","在這份食譜中，你可以用蜂蜜代替糖。","substitute B for A 表示「用 B 代替 A」；with 也可見於此義，但 for 更清楚。"]],"l5-0939":[["n：手提箱","luggage / baggage","He packed his suitcase before leaving for the airport.","他在前往機場前整理好了行李。","此處 pack 是把衣物等物品裝入行李箱。"]],"l5-0940":[["名詞：硫磺","sulphur","The volcano released sulfur gases that smelled like rotten eggs.","火山釋放出聞起來像臭雞蛋的硫磺氣體。","sulfur 是化學元素；英式拼作 sulphur。"]],"l5-0941":[["vt：召喚","call / order","He was summoned to court.","他被傳喚出庭。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0942":[["形容詞：膚淺的","shallow / surface-level","The article offered a superficial explanation of the complex dispute.","那篇文章只對複雜爭端提供膚淺的解釋。","superficial 指只觸及表面、缺乏深度。"]],"l5-0943":[["名詞：迷信","irrational belief","Her grandmother’s superstition forbade opening an umbrella indoors.","她祖母的迷信禁止在室內撐傘。","superstition 是缺乏科學根據的信念。"]],"l5-0944":[["vt / vi：監督","oversee / manage","He supervises the team.","他監督該團隊。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0945":[["名詞：監督者","manager / overseer","The supervisor reviewed the team’s safety procedures every Friday.","監督者每週五檢查團隊的安全程序。","supervisor 負責指導或監督工作人員。"]],"l5-0946":[["vt：鎮壓；抑制","repress / restrain / hold back","He suppressed a laugh during the serious meeting.","他在嚴肅的會議中忍住了笑。","此處 suppress 表示抑制或忍住情緒、反應；不只表示鎮壓。"]],"l5-0947":[["形容詞：最高的","highest / ultimate","The court is the supreme authority on constitutional questions.","該法院是憲法問題的最高權威。","supreme 表示地位、程度或權力最高。"]],"l5-0948":[["vi / n：洶湧；急升","increase / rise","There was a surge in demand.","需求出現了激增。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0949":[["vt / vi：懸掛；使…中止","pause / delay","The meeting was suspended.","會議被暫停了。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0950":[["vt：支撐；維持","maintain / support / preserve","These investments sustain economic growth.","這些投資維持了經濟成長。","sustain 在此表示持續支持或維持某種成長狀態。"]],"l5-0951":[["名詞：沼澤","marsh / wetland","The biologists surveyed birds living in the coastal swamp.","生物學家調查住在沿海沼澤的鳥類。","swamp 指長期積水的濕地，也可作動詞淹沒。"]],"l5-0952":[["名詞：群","crowd / mass","A swarm of bees settled on the flowering tree.","一群蜜蜂停在開花的樹上。","swarm 專指大量昆蟲或人群。"]],"l5-0953":[["動詞：同情","feel for / empathize with","I sympathize with the residents who lost their homes in the flood.","我同情在洪水中失去家園的居民。","sympathize with 後接同情的對象。"]],"l5-0954":[["動詞：解決；擒抱","deal with","The committee tackled the drainage problem before the rainy season.","委員會在雨季前處理排水問題。","tackle 可指處理問題，也可指運動中的擒抱。"]],"l5-0955":[["名詞：古銅色","bronze color","After a week at the beach, his skin had a deep golden tan.","在海灘待了一週後，他的皮膚曬成深金色。","tan 指日曬後的棕褐膚色。"]],"l5-0956":[["動詞、名詞：纏繞；糾結","knot","The fishing line tangled around the propeller during the storm.","暴風雨中，釣魚線纏住了螺旋槳。","tangle 可指線物纏結或問題複雜化。"]],"l5-0957":[["名詞：焦油","無直接同義詞","Workers sealed the roof with hot tar before the rain arrived.","工人在下雨前用熱焦油密封屋頂。","tar 是黑色黏稠物，常用於道路或屋頂。"]],"l5-0958":[["名詞、形容詞：水果塔；酸的","sour / pastry","The lemon tart was pleasantly sharp rather than overly sweet.","檸檬水果塔酸得宜人，不會過甜。","tart 可指酸味或水果塔點心。"]],"l5-0959":[["動詞、名詞：嘲弄","jeer","The fans taunted the visiting team after the final whistle.","終場哨響後，球迷嘲弄客隊。","taunt 指反覆用言語挑釁或嘲笑。"]],"l5-0960":[["名詞：酒館","inn","The travelers stopped at a roadside tavern for soup and bread.","旅人停在路旁酒館喝湯吃麵包。","tavern 是供應飲食和酒的傳統小店。"]],"l5-0961":[["名詞：敘述者；出納員","narrator / bank clerk","The bank teller counted the customer’s cash twice before completing the deposit.","銀行出納員在完成存款前把顧客的現金數了兩次。","teller 可指銀行出納員或故事敘述者。"]],"l5-0962":[["名詞：拍子","pace","The conductor slowed the tempo before the choir entered the final verse.","合唱團唱最後一節前，指揮放慢了拍子。","tempo 指音樂演奏的速度。"]],"l5-0963":[["動詞：誘惑","entice","The discount tempted shoppers to buy supplies they had not planned to purchase.","折扣誘惑購物者買下原本沒打算買的用品。","tempt 表示引起想做某事的慾望。"]],"l5-0964":[["名詞：誘惑","lure","The temptation to check her phone distracted her during the lecture.","查看手機的誘惑讓她上課時分心。","temptation 指想做某事但可能不明智的吸引力。"]],"l5-0965":[["n：租戶","renter","The tenant pays rent.","房客付房租。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0966":[["adj：暫時的","provisional","It is a tentative plan.","這是一個暫定的計畫。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0967":[["adj：末端的；n：總站；航廈","station / air terminal","Please go to the airport terminal to meet the client.","請前往機場航廈與客戶會面。","此處 terminal 是機場航廈或候機大樓。"]],"l5-0968":[["名詞：露臺；階梯看台；梯田","veranda","The restaurant’s terrace overlooks the harbor at sunset.","餐廳露臺在日落時俯瞰港口。","terrace 可指建築露臺、階梯看台或梯田。"]],"l5-0969":[["名詞：大腿","無直接同義詞","The runner applied ice to his thigh after the muscle strain.","跑者肌肉拉傷後在大腿上敷冰。","thigh 是髖部到膝蓋之間的部位。"]],"l5-0970":[["名詞：刺","spine","A thorn pierced the gardener’s glove while she pruned the rose.","園丁修剪玫瑰時，一根刺刺穿了手套。","thorn 指玫瑰等植物的尖刺。"]],"l5-0971":[["動詞、名詞：使激動；激動","excite / exhilarate","The rescue team’s arrival thrilled the families waiting at the shelter.","救援隊抵達使在避難所等待的家人激動不已。","thrill 可指強烈興奮或刺激。"]],"l5-0972":[["名詞：驚悚作品","suspense novel","She read a crime thriller on the train and missed her stop.","她在火車上讀犯罪驚悚小說，結果坐過了站。","thriller 以緊張、懸疑或驚險情節為特色。"]],"l5-0973":[["名詞：王位","royal seat","The prince inherited the throne after his mother abdicated.","王子在母親退位後繼承王位。","throne 可指王位或君主的座位。"]],"l5-0974":[["名詞：群眾","crowd / multitude","A throng of tourists filled the narrow street outside the palace.","一大群遊客擠滿宮殿外的狹窄街道。","throng 是較正式的 large crowd。"]],"l5-0975":[["動詞、名詞：猛推；刺","push forcefully","The fencer thrust his sword toward the target without touching it.","擊劍手把劍猛刺向目標但沒有碰到。","thrust 強調突然且有力地向前推或刺。"]],"l5-0976":[["動詞、名詞：滴答聲","ticking sound","The old clock ticked loudly in the silent hallway.","老時鐘在寂靜走廊裡大聲滴答作響。","tick 可指鐘錶聲或發出滴答聲。"]],"l5-0977":[["名詞：磁磚、瓦片","無直接同義詞","The contractor replaced three cracked tiles in the kitchen.","承包商更換廚房裡三片破裂的磁磚。","tile 可指地面、牆面或屋頂的片材。"]],"l5-0978":[["動詞、名詞：傾斜","lean","Tilt the screen slightly so the audience can read the figures.","把螢幕稍微傾斜，觀眾才能讀到數字。","tilt 指使物體偏離水平。"]],"l5-0979":[["名詞：錫","無直接同義詞","The artisan shaped a thin sheet of tin into a small lantern.","工匠把薄錫片製成小燈籠。","tin 是一種金屬元素，也指錫製容器。"]],"l5-0980":[["名詞、動詞：腳尖；踮腳走","on tiptoe / walk quietly","She tiptoed past the sleeping baby to close the window.","她踮著腳走過熟睡的嬰兒旁去關窗。","tiptoe 可作名詞或動詞，指用腳尖走路。"]],"l5-0981":[["名詞：蟾蜍","無直接同義詞","A toad hid beneath the flowerpot after the summer rain.","夏雨後，一隻蟾蜍躲在花盆下。","toad 是皮膚較粗糙的蛙類。"]],"l5-0982":[["名詞、動詞：辛勞；苦幹","hard work / labor","Years of toil turned the rocky hillside into a productive vineyard.","多年的辛勞把多石山坡變成高產葡萄園。","toil 指艱苦而持續的工作。"]],"l5-0983":[["名詞：象徵","symbol / sign","The white ribbon became a token of support for the patients.","白絲帶成為支持病患的象徵。","token 可指象徵物或代幣。"]],"l5-0984":[["名詞：火炬","flashlight","The runner carried a torch through the dark stadium during the ceremony.","儀式中，跑者拿著火炬穿過漆黑的體育場。","torch 在英式英文也可指手電筒；本句採火炬義。"]],"l5-0985":[["名詞：痛苦","agony / suffering","The injured climber was in torment until the rescue helicopter arrived.","受傷的攀登者在救援直升機抵達前痛苦難耐。","torment 指持續而強烈的身心痛苦。"]],"l5-0986":[["名詞：急流","rushing stream","A torrent of muddy water swept branches down the mountain road.","一股泥水急流把樹枝沖下山路。","torrent 指暴雨或洪水形成的猛烈水流。"]],"l5-0987":[["名詞：痛苦","pain / anguish","The prisoner described years of torture in the detention camp.","囚犯描述拘留營中多年的折磨痛苦。","torture 指故意造成的極度痛苦，也可指折磨人的事。"]],"l5-0988":[["名詞：錦標賽","competition","The school hosted an international chess tournament in the gymnasium.","學校在體育館舉辦國際象棋錦標賽。","tournament 是多輪比賽決定冠軍的賽事。"]],"l5-0989":[["形容詞：有毒的","poisonous","The laboratory stores toxic chemicals in locked ventilated cabinets.","實驗室把有毒化學品存放在上鎖且通風的櫃子裡。","toxic 指會造成中毒或傷害。"]],"l5-0990":[["n：商標","brand name","It is a registered trademark.","這是一個註冊商標。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0991":[["名詞：叛逆者","betrayer","The traitor revealed the army’s route to the opposing forces.","叛逆者把軍隊路線透露給敵對勢力。","traitor 指背叛組織、國家或信任的人。"]],"l5-0992":[["名詞、動詞：流浪漢；沉重地走","wanderer","The tramp walked slowly along the railway carrying a worn backpack.","那名流浪漢背著舊背包沿鐵路緩慢行走。","tramp 可指流浪者或沉重腳步聲。"]],"l5-0993":[["動詞、名詞：踐踏","crush underfoot","Please do not trample the seedlings while crossing the garden bed.","穿過花圃時請不要踐踏幼苗。","trample 強調用腳踩踏造成傷害。"]],"l5-0994":[["adj：透明的","clear","The material is transparent.","這種材質是透明的。","採用既有原創例句；同義詞依該義項校對。"]],"l5-0995":[["名詞：寶庫","storehouse","The national treasury preserved rare manuscripts from the early dynasty.","國家寶庫保存早期王朝的珍貴手稿。","treasury 可指國庫或珍藏大量物品的地方。"]],"l5-0996":[["名詞：條約","pact","The two nations signed a treaty to protect the shared river.","兩國簽署條約保護共同的河流。","treaty 是國家間正式且具約束力的協議。"]],"l5-0997":[["名詞：壕溝","ditch","Soldiers sheltered in a trench during the artillery attack.","砲擊期間，士兵躲在壕溝裡。","trench 是挖入地面的狹長深溝。"]],"l5-0998":[["名詞：貢品；尊崇","homage","The concert was a tribute to the composer who died last year.","這場音樂會是向去年去世的作曲家致敬。","tribute 可指敬意、紀念作品或進貢物。"]],"l5-0999":[["名詞：瑣事","trivial matter","The committee refused to waste time arguing over such a trifle.","委員會拒絕浪費時間爭論這種瑣事。","trifle 指不重要的小事。"]],"l5-1000":[["vt / vi / n：修剪；調整","cut / prune","Trim the hedge.","修剪樹籬。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1001":[["形容詞：三倍的","threefold / three times as much","The new filter gives the machine three times the lifespan of the old one.","新濾心讓機器的壽命達到舊濾心的三倍。","triple 可作形容詞、動詞或名詞。"]],"l5-1002":[["動詞、名詞：快步走；小跑","jog","The horse trotted calmly beside the trainer around the ring.","馬匹在訓練員旁邊繞場小跑，步伐平穩。","trot 指比走路快、比奔跑慢的步態。"]],"l5-1003":[["名詞：鱒魚","無直接同義詞","The fisherman released the trout after taking a quick photograph.","漁夫拍照後把鱒魚放回水中。","trout 的複數形式通常仍是 trout。"]],"l5-1004":[["動詞：塞","put neatly","She tucked the blanket around the sleeping child.","她把毯子仔細塞在熟睡孩子的身邊。","tuck 指把東西塞入或收好，常帶整齊意味。"]],"l5-1005":[["學費","tuition fee / school fees","The scholarship covers her tuition for the fall semester.","這項獎學金涵蓋她秋季學期的學費。","tuition 通常指教育機構收取的教學費用。"]],"l5-1006":[["鮪魚","無直接同義詞","The chef seared fresh tuna and served it with sesame dressing.","主廚煎香新鮮鮪魚，搭配芝麻醬汁上桌。","tuna 是魚名，沒有可互換的日常同義詞。"]],"l5-1007":[["暴君","despot / dictator","The tyrant silenced newspapers that criticized his rule.","那名暴君讓批評其統治的報紙噤聲。","tyrant 強調殘暴且專制地掌權。"]],"l5-1008":[["裁判（棒球、網球、板球）","official / referee","The umpire called the runner out at second base.","裁判判定跑者在二壘出局。","umpire 用於棒球、網球等比賽的裁判。"]],"l5-1009":[["n：大學生","college student / university student","He is an undergraduate at a local university.","他是當地一所大學的學生。","undergraduate 可作名詞，指大學生；也可作形容詞修飾 student、program 等名詞。"]],"l5-1010":[["vt：劃底線；強調","emphasize","Underline the key words.","在關鍵字下方畫線。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1011":[["在……下方","beneath / below","A storage locker sits underneath the staircase.","樓梯下方有一個儲物櫃。","underneath 指位置直接在另一物下方。"]],"l5-1012":[["可理解的","clear / comprehensible","Her explanation was understandable even to new employees.","即使是新進員工也能理解她的說明。","understandable 表示內容容易被理解。"]],"l5-1013":[["adv：毫無疑問地","certainly / definitely","He is undoubtedly the best.","他毫無疑問是最棒的。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1014":[["vt / n：更新；最新消息","latest information / progress report","Please send me an update on the project.","請寄給我一份專案的最新進度。","update 可作動詞表示更新，也可作名詞表示最新消息、進度或更新內容。"]],"l5-1015":[["直立的；正直的","vertical / honest","Keep the ladder upright while I secure its feet.","我固定梯腳時，請保持梯子直立。","upright 可指垂直位置，也可指品格正直。"]],"l5-1016":[["向上的","ascending / rising","The upward arrow on the chart shows monthly sales growth.","圖表上的向上箭頭表示每月銷售額成長。","upward 作形容詞修飾朝上或增加的方向。"]],"l5-1017":[["向上地","up / skyward","Smoke drifted upward through the broken roof.","煙霧穿過破損的屋頂向上飄去。","upwards 是副詞，說明移動方向。"]],"l5-1018":[["全然的；說出","complete / say","The audit revealed the utter absence of safety records.","稽核揭露安全紀錄完全不存在。","utter 作形容詞時表示完全，作動詞時表示說出。"]],"l5-1019":[["n：空缺","opening / position","There is a vacancy for a secretary.","秘書一職有空缺。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1020":[["真空","無直接同義詞","The pump removes air to create a vacuum inside the chamber.","幫浦抽走空氣，在腔室內形成真空。","vacuum 是幾乎沒有物質的空間，也可指吸塵器。"]],"l5-1021":[["adj：模糊的","unclear / indistinct","He gave a vague answer.","他給了一個含糊的回答。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1022":[["虛榮","conceit","His vanity made him check the mirror before every meeting.","他的虛榮心讓他每次開會前都要照鏡子。","vanity 指過度在意外表或他人讚美。"]],"l5-1023":[["蒸氣","steam","Water vapor condensed on the cold laboratory window.","水蒸氣在冰冷的實驗室窗戶上凝結。","vapor 泛指氣態物質；steam 特指水蒸氣。"]],"l5-1024":[["植物","plant life / flora","The island’s dense vegetation shelters many rare birds.","島上茂密的植物為許多稀有鳥類提供棲身處。","vegetation 指某地整體的植物覆蓋。"]],"l5-1025":[["面紗","head covering","The bride lifted her veil after exchanging vows.","新娘交換誓言後掀起面紗。","veil 可指遮臉的薄布，也可比喻遮掩真相。"]],"l5-1026":[["靜脈；血管；葉脈","blood vessel","The nurse inserted the needle into a vein in his arm.","護理師將針插入他手臂的靜脈。","vein 依語境可指血管或葉片中的脈絡。"]],"l5-1027":[["天鵝絨","無直接同義詞","The museum displayed a velvet jacket embroidered with gold thread.","博物館展示一件繡有金線的天鵝絨外套。","velvet 是表面柔軟有短絨毛的布料。"]],"l5-1028":[["名詞：新事業；商業冒險","enterprise","She invested her savings in a new business venture.","她把積蓄投入了一項新事業。","business venture 指帶有風險的新商業活動或事業。"]],"l5-1029":[["形容詞：口頭的","spoken","We reached a verbal agreement before signing the contract.","我們在簽約前先達成了口頭協議。","本句 verbal 指口頭表達，與 written（書面的）對比。"]],"l5-1030":[["與……相對","against","Tonight’s debate is City Council versus the developers.","今晚的辯論由市議會對上開發商。","versus 常用於比較或競爭雙方。"]],"l5-1031":[["垂直的","upright / perpendicular","The architect drew a vertical line to mark the elevator shaft.","建築師畫了一條垂直線標示電梯井。","vertical 表示與水平面成直角。"]],"l5-1032":[["否決","reject","The mayor vetoed the proposal to close the public library.","市長否決了關閉公共圖書館的提案。","veto 可作名詞或動詞，指正式阻止決議。"]],"l5-1033":[["透過","through / by means of","Customers can pay via the secure link in the invoice.","顧客可以透過發票上的安全連結付款。","via 表示經由某途徑或方式。"]],"l5-1034":[["震動","shake / oscillate","The phone vibrated on the desk when the message arrived.","訊息抵達時，手機在桌上震動。","vibrate 指快速來回振動，常用於裝置或機械。"]],"l5-1035":[["錄影帶","video cassette","The archive still holds a videotape of the 1998 concert.","檔案館仍保存著一卷一九九八年演唱會的錄影帶。","videotape 指磁帶格式的錄影，也可指錄製行為。"]],"l5-1036":[["觀眾","spectator / audience member","Each viewer received a survey after watching the training video.","每位觀眾看完訓練影片後都收到一份問卷。","viewer 強調觀看螢幕內容的個人。"]],"l5-1037":[["活力","energy / vitality","The volunteer’s vigor helped keep the cleanup team working through the afternoon.","志工的活力讓清理團隊整個下午都持續工作。","vigor 指旺盛的體力或精神。"]],"l5-1038":[["有活力的","energetic / robust","The vigorous seedlings survived the unusually cold week.","這些充滿活力的幼苗撐過了異常寒冷的一週。","vigorous 可形容強健，也可形容動作或活動強烈。"]],"l5-1039":[["惡徒","criminal / scoundrel","The novel’s villain frames an innocent engineer for the theft.","小說中的惡徒陷害無辜工程師竊盜。","villain 指故事中的反派，也可泛指惡人。"]],"l5-1040":[["藤蔓","climber / creeper","A vine curled around the wooden trellis beside the patio.","一條藤蔓纏繞在露臺旁的木格架上。","vine 指攀爬或蔓生植物的莖，不限定葡萄。"]],"l5-1041":[["小提琴家","violin player","The violinist rehearsed the solo before the orchestra arrived.","小提琴家在樂團抵達前排練獨奏。","violinist 指演奏小提琴的人。"]],"l5-1042":[["簽證","entry permit","She applied for a work visa three months before moving abroad.","她在出國前三個月申請工作簽證。","visa 是護照上的入境或停留許可。"]],"l5-1043":[["誓言；發誓","pledge / swear","He vowed to return the borrowed equipment by Friday.","他發誓星期五前歸還借用的設備。","vow 作名詞是莊重承諾，作動詞表示鄭重發誓。"]],"l5-1044":[["涉水","ford","The hikers waded across the shallow stream to reach the campsite.","健行者涉過淺溪前往營地。","wade 指在水中行走，通常水深不及腰。"]],"l5-1045":[["慟哭；嚎啕","sob / lament","The child wailed when the nurse removed the splinter.","護士拔出木刺時，孩子嚎啕大哭。","wail 指高亢、持續的哭喊聲。"]],"l5-1046":[["病房；躲開","hospital room / evade","The nurse moved the patient to a quieter ward.","護理師把病人移到較安靜的病房。","ward 作名詞可指病房，作動詞表示防避。"]],"l5-1047":[["……的製品","goods / products","The shop specializes in handmade ceramic ware from local studios.","這家店專賣當地工作室製作的手工陶器。","ware 常接材質或用途，表示一類製品。"]],"l5-1048":[["n：倉庫","depot / storehouse","The goods are stored in the warehouse.","貨物存放在倉庫裡。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1049":[["戰士","fighter / soldier","The ancient warrior carried a bronze shield into battle.","那名古代戰士帶著青銅盾牌上戰場。","warrior 強調參與戰鬥、具武勇的人。"]],"l5-1050":[["小心的；謹防的","cautious / vigilant","Be wary of unsolicited emails asking for your password.","要提防要求你提供密碼的陌生電子郵件。","wary 常與 of 連用，表示對危險保持警覺。"]],"l5-1051":[["疲倦的","tired / exhausted","Weary travelers found seats near the station entrance.","疲憊的旅客在車站入口附近找到座位。","weary 比 tired 更強調長時間勞累。"]],"l5-1052":[["怪異的","strange / bizarre","A weird noise from the server room woke the night guard.","伺服器機房傳來的怪聲吵醒夜班警衛。","weird 指不尋常到令人困惑或不安。"]],"l5-1053":[["碼頭","pier / dock","Cargo waited on the wharf until the tide rose.","貨物在碼頭等到潮水上漲。","wharf 是船隻靠岸裝卸貨物的平台。"]],"l5-1054":[["輪椅","無直接同義詞","The museum installed a ramp so wheelchair users could enter independently.","博物館設置坡道，讓輪椅使用者能自行進入。","wheelchair 是供行動不便者乘坐的椅車。"]],"l5-1055":[["哪處；下落","location","The investigator asked for the missing accountant’s whereabouts.","調查員詢問失蹤會計的下落。","whereabouts 通常詢問某人的位置，常用複數形式。"]],"l5-1056":[["然而","while / although","The north route is shorter, whereas the coastal road is safer.","北線較短，然而沿海公路更安全。","whereas 連接兩個對比的子句。"]],"l5-1057":[["發牢騷","complain / gripe","The customer whined about the delay instead of reading the notice.","顧客沒有看公告，反而一直抱怨延誤。","whine 帶有惱人的抱怨語氣，也可作名詞。"]],"l5-1058":[["旋轉","spin","Autumn leaves whirled across the courtyard in the strong wind.","秋葉在強風中旋轉著掠過庭院。","whirl 強調快速而混亂的旋轉。"]],"l5-1059":[["拂去；飛奔","brush away / dash","She whisked the crumbs from the table before serving dessert.","她上甜點前迅速拂去桌上的麵包屑。","whisk 可指快速拂動，也可指匆忙帶走。"]],"l5-1060":[["威士忌","無直接同義詞","The bartender poured a single malt whiskey over one ice cube.","酒保把單一麥芽威士忌倒在一顆冰塊上。","whiskey 是蒸餾酒名，沒有可互換的普通同義詞。"]],"l5-1061":[["n / adj：批發（的）","wholesale trade / bulk sale / in bulk","We sell these items at wholesale prices.","我們以批發價銷售這些商品。","wholesale 可作名詞或形容詞；本句 wholesale prices 指批發價。"]],"l5-1062":[["合乎衛生的；有益健康的","healthy / nourishing","The school cafeteria added a wholesome soup made from fresh vegetables.","學校餐廳新增以新鮮蔬菜熬煮的健康湯品。","wholesome 可指有益健康，也可指正當純樸。"]],"l5-1063":[["廣布的","prevalent","The storm caused widespread power outages across the county.","暴風雨造成全縣大規模停電。","widespread 表示分布範圍很廣。"]],"l5-1064":[["寡婦","無直接同義詞","The widow donated her late husband’s books to the town library.","那名寡婦把亡夫的書捐給鎮立圖書館。","widow 指丈夫去世的女性。"]],"l5-1065":[["鰥夫","無直接同義詞","The widower moved closer to his daughter after retiring.","那名鰥夫退休後搬到離女兒較近的地方。","widower 指妻子去世的男性。"]],"l5-1066":[["假髮","hairpiece / toupee","The actor wore a gray wig to portray the retired judge.","演員戴上灰色假髮，飾演退休法官。","wig 是覆蓋頭部的整頂假髮。"]],"l5-1067":[["荒地","wasteland / wilds","The hikers carried extra water across the remote wilderness.","健行者帶著額外飲水穿越偏遠荒地。","wilderness 指未開發、少有人為設施的自然地區。"]],"l5-1068":[["n：野生動物","wild animals / fauna / animals","The park is a sanctuary for local wildlife.","這座公園是當地野生動物的保護區。","wildlife 指野生動物的總稱，不等於 fauna and flora。"]],"l5-1069":[["枯萎","shrivel / wilt","The potted basil withered after a week without sunlight.","盆栽羅勒一週沒有陽光後枯萎了。","wither 指植物失去水分而乾枯，也可比喻衰退。"]],"l5-1070":[["悲痛；哎喲","grief / misery","The family spoke quietly about their woe after the accident.","事故後，一家人低聲談論他們的悲痛。","woe 是較文學化的深切悲苦用語。"]],"l5-1071":[["啄木鳥","無直接同義詞","A woodpecker tapped repeatedly at the dead tree behind the cabin.","一隻啄木鳥在小屋後的枯樹上反覆啄擊。","woodpecker 是鳥名，沒有可互換的普通同義詞。"]],"l5-1072":[["n：工廠；研討會","seminar / studio","She conducted a training workshop for teachers.","她為教師們舉辦了一場培訓工作坊。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1073":[["崇拜","revere / adore","Many fans worship the singer for her remarkable live performances.","許多歌迷因她精彩的現場演出而崇拜她。","worship 可指宗教敬拜，也可誇張表示極度崇敬。"]],"l5-1074":[["值得做的","worth doing / beneficial","Repairing the old machine is worthwhile because replacement parts are available.","修理那台舊機器是值得的，因為還找得到替換零件。","worthwhile 表示投入時間或金錢有價值。"]],"l5-1075":[["值得的","deserving / meritorious","The committee judged her worthy of the national design award.","委員會認為她值得獲得國家設計獎。","worthy 常接 of，表示配得某種尊重或獎賞。"]],"l5-1076":[["花環","garland","Neighbors placed a wreath at the memorial on the anniversary.","鄰居在周年紀念日於紀念碑前放置花環。","wreath 是圓環形花飾，也常用於悼念。"]],"l5-1077":[["擰；扭","twist / squeeze","She wrung the wet towel over the sink before hanging it to dry.","她把濕毛巾在水槽上方擰乾後掛起來晾。","wring 指用力擰扭以擠出液體；原卡的「蠕動」疑為誤植，與 wriggle（扭動、蠕動）不同。"]],"l5-1078":[["遊艇","pleasure boat","The owners anchored their yacht near the quiet island.","船主把遊艇停泊在寧靜小島附近。","yacht 通常指供休閒航行的私人船隻。"]],"l5-1079":[["紗線","thread","She knitted a scarf from thick wool yarn.","她用粗羊毛紗線織了一條圍巾。","yarn 是編織用的纖維線，也可指故事。"]],"l5-1080":[["酵母菌","無直接同義詞","Warm water activates the yeast before the dough is kneaded.","溫水會在揉麵團前活化酵母菌。","yeast 是使麵團發酵的微生物。"]],"l5-1081":[["vt / vi：產出；屈服","return / profit / produce","This investment offers a high annual yield.","這項投資提供了很高的年收益率。","採用既有原創例句；同義詞依該義項校對。"]],"l5-1082":[["瑜珈","無直接同義詞","He practices yoga every morning to improve his balance.","他每天早上做瑜珈以改善平衡感。","yoga 指結合伸展、呼吸與冥想的運動。"]],"l5-1083":[["鋅","無直接同義詞","The supplement contains zinc, which supports normal immune function.","這種補充劑含有鋅，有助於維持正常免疫功能。","zinc 是化學元素與礦物質名稱。"]],"l5-1084":[["拉鍊；拉開或扣上拉鍊","zipper / fasten","Please zip your jacket before stepping into the cold wind.","走進冷風前，請把外套拉鍊拉上。","zip 作動詞表示拉上或拉開拉鍊。"]],"l5-1085":[["區域改善計畫","neighborhood renewal plan / improvement scheme","The city approved a zone improvement plan for safer sidewalks.","市政府核准區域改善計畫，以打造更安全的人行道。","zone improvement plan 是針對特定區域的整體建設方案。"]],"l5-1086":[["郵遞區號","postal code","Enter your ZIP code to calculate the delivery fee.","請輸入郵遞區號以計算運費。","ZIP code 是美式用語，其他地區常說 postal code。"]],"l5-1087":[["動詞片語：拉近鏡頭（zoom in）","無直接同義詞","The camera zoomed in on the label so we could read the serial number.","相機拉近標籤畫面，讓我們看清序號。","zoom in on + 目標：用鏡頭放大目標，使畫面看起來更近；zoom out 則拉遠。buzz 表嗡嗡聲，不適用本句。"]],"l6-0001":[["動詞：縮寫","shorten / contract","The editor abbreviated the organization names to make the table easier to read.","編輯把機構名稱縮寫，讓表格更容易閱讀。",""]],"l6-0002":[["名詞：縮寫","short form","The report explains each abbreviation before using it in later chapters.","報告先解釋各個縮寫，才在後續章節使用。",""]],"l6-0003":[["形容詞：異常的","unusual / irregular","An abnormal vibration prompted the engineer to shut down the machine.","異常振動促使工程師關閉機器。","abnormal 表示不尋常；irregular 更強調不規則，兩者不能在所有語境中互換。"]],"l6-0004":[["形容詞：原生的","indigenous / native","The reserve protects aboriginal plant species threatened by development along the coast.","保護區保育受到沿海開發威脅的原生植物。","此為原生義；指澳洲原住民族時通常大寫 Aboriginal。"]],"l6-0005":[["名詞：原住民（舊稱）","Indigenous person","The nineteenth-century diary describes an aborigine guiding the travelers across the desert.","那本十九世紀日記記述一位原住民引導旅人穿越沙漠。","本句為歷史敘述；aborigine 作人稱名詞在現代可能被視為過時或冒犯，宜依當事人偏好使用 Indigenous person 或具體族名。https://www.oxfordlearnersdictionaries.com/definition/english/aborigine"]],"l6-0006":[["動詞：大量存在","be plentiful / teem","Wildflowers abound in the valley after the first heavy rains of spring.","春季第一波大雨過後，山谷裡長滿野花。","abound in a place；a place teems with something，句法不同；the first heavy rains 指初期的一波大雨，不必理解為單獨一場。"]],"l6-0007":[["形容詞：心不在焉的","forgetful / distracted","The absentminded professor left his lecture notes on the kitchen table.","那位心不在焉的教授把講義留在廚房桌上。",""]],"l6-0008":[["名詞：抽象概念","abstract concept","For the children, conservation became more than an abstraction after they cleaned the polluted beach.","孩子們清理受污染的海灘後，保育就不再只是抽象概念了。",""]],"l6-0009":[["名詞：充裕","plenty / profusion","An abundance of fresh produce makes summer the busiest season at the market.","夏季新鮮農產品供應充裕，使市場在這個季節最忙碌。",""]],"l6-0010":[["動詞：虐待","mistreat / ill-treat","The investigation found that several animals had been abused at the facility.","調查發現，該設施內有好幾隻動物受到虐待。",""]],"l6-0011":[["動詞：加速","speed up / hasten","The grant will accelerate repairs to bridges damaged by the recent storm.","這筆補助將加快修復近期暴風雨損壞的橋梁。",""]],"l6-0012":[["名詞：加速","speedup","The sudden acceleration pressed the passengers firmly against the backs of their seats.","突然的加速使乘客緊緊貼在座椅椅背上。",""]],"l6-0013":[["形容詞：可抵達的","reachable","The mountain shelter is accessible only by a steep path through the forest.","那座山屋只能沿著穿越森林的陡峭步道抵達。",""]],"l6-0014":[["名詞：配件","add-on","The camera comes with a strap, but the waterproof case is an optional accessory.","相機附有背帶，防水殼則是選購配件。","add-on 指加裝的附加物；attachment 可指可附接的特定配件，並非所有 accessory。"]],"l6-0015":[["動詞：容納","hold / fit","The renovated hall can accommodate two hundred guests without blocking the emergency exits.","整修後的禮堂可容納兩百位賓客，而且不會堵住逃生出口。","hold 或 fit 表示容量足以容納；seat 較窄，會暗示提供足夠座位，需有座位配置語境才適合。"]],"l6-0016":[["名詞：住宿","lodging / housing","The university arranged temporary accommodation for students whose apartments were flooded.","大學替住處淹水的學生安排了臨時住宿。","英式住宿常用不可數 accommodation；美式也常用複數 accommodations。"]],"l6-0017":[["動詞：一致","agree / correspond","Her account of the accident accords with the evidence from the security camera.","她對事故的描述與監視器拍到的證據一致。","accord with 與……一致。"]],"l6-0018":[["名詞：一致（片語 in accordance with：依照）","conformity / compliance","All applications are reviewed in accordance with the published selection criteria.","所有申請都依照公布的甄選標準審查。","固定片語 in accordance with，意為依照。"]],"l6-0019":[["副詞：因此","consequently / therefore","Demand has fallen sharply; accordingly, the factory will reduce production next month.","需求大幅下降，因此工廠下個月將減產。",""]],"l6-0020":[["形容詞：須負責的","answerable / responsible","Managers are accountable for explaining how their departments spend public funds.","經理有責任說明所屬部門如何使用公共資金。","accountable for 事項；accountable to 負責對象。"]],"l6-0021":[["名詞：會計","accountancy","Her background in accounting helped her identify errors in the charity's financial records.","她的會計背景幫助她找出慈善機構財務紀錄中的錯誤。",""]],"l6-0022":[["動詞：累積","build up / collect","Dust accumulated behind the shelves because nobody had moved them for years.","書架多年沒有移動，後面累積了灰塵。",""]],"l6-0023":[["名詞：累積","buildup","An accumulation of fallen leaves blocked the drain outside the school entrance.","堆積的落葉堵住了學校入口外的排水孔。",""]],"l6-0024":[["名詞：指控","allegation / charge","She denied the accusation and asked investigators to examine the complete records.","她否認指控，並要求調查人員檢視完整紀錄。",""]],"l6-0025":[["名詞：取得","obtaining","The acquisition of new equipment allowed the laboratory to process samples more quickly.","取得新設備後，實驗室便能更快處理樣本。",""]],"l6-0026":[["名詞：行動倡議者","campaigner / advocate","The environmental activist organized volunteers to document pollution along the river.","那位環境倡議者組織志工，記錄河流沿線的污染。","activist 不一定是激進分子；本句指積極參與倡議的人。"]],"l6-0027":[["形容詞：急性的","無直接同義詞","The physician distinguished the patient's acute symptoms from her long-standing health problems.","醫師把病人的急性症狀與長期健康問題區分開來。","醫學 acute 強調突然或短期病程，不單等於 severe 嚴重。"]],"l6-0028":[["名詞：適應","adjustment / acclimatization","The seedlings' adaptation to dry conditions became clear during the unusually hot summer.","那個異常炎熱的夏季顯示出幼苗對乾燥環境的適應能力。","adaptation 可指適應的過程或結果；acclimatization 多指個體逐漸適應新環境，不能在所有語境中互換。"]],"l6-0029":[["動詞：使上癮","無直接同義詞","He feared that repeated exposure to the drug would addict vulnerable patients.","他擔心反覆接觸那種藥物會使易受影響的病人上癮。","動詞 addict 較少見，常用被動 be addicted to；名詞重音在第一音節。"]],"l6-0030":[["名詞：成癮","dependence","The center offers support for people recovering from addiction and their families.","該中心為正在戒除成癮的人及其家人提供支持。",""]],"l6-0031":[["動詞：管理","manage / oversee","A local nonprofit administers the scholarship fund and reviews applications each spring.","當地非營利組織管理這筆獎學金基金，每年春天審查申請。","administrate 也可指管理，但 administer 更常見。"]],"l6-0032":[["名詞：管理","management","Poor administration delayed payments to contractors working on the public housing project.","管理不善導致公共住宅專案的承包商延遲收到款項。",""]],"l6-0033":[["形容詞：行政的","bureaucratic","The new system reduces administrative work by generating invoices automatically.","新系統自動產生請款單，減少了行政工作。","bureaucratic 偏重官僚程序，有時帶負面語氣。"]],"l6-0034":[["名詞：行政管理者","manager","The school administrator coordinated classroom repairs while teachers prepared for the new term.","學校行政主管協調教室維修，老師們則準備新學期。",""]],"l6-0035":[["動詞：提倡","support / promote","The committee advocates expanding public transport instead of building additional parking lots.","委員會提倡擴充大眾運輸，取代增建停車場。","advocate 後可接名詞或動名詞。"]],"l6-0036":[["形容詞：充滿愛意的","loving / tender","Her affectionate letters helped her grandson feel connected to home while studying abroad.","她充滿愛意的信，讓在國外讀書的孫子感到與家鄉的連結。",""]],"l6-0037":[["動詞：肯定地表示","assert / declare","The director affirmed that the museum would remain open during the renovations.","館長肯定地表示，博物館在整修期間仍會開放。",""]],"l6-0038":[["名詞：侵略行為","hostility","The neighboring countries condemned the military aggression and called for an immediate withdrawal.","鄰國譴責這項軍事侵略，並要求立即撤軍。","hostility 表敵意或敵對行為，不一定已構成侵略。"]],"l6-0039":[["形容詞：含酒精的","無直接同義詞","The restaurant labels alcoholic drinks separately from its fruit juices and other soft drinks.","餐廳把含酒精飲品與果汁及其他無酒精飲料分開標示。",""]],"l6-0040":[["動詞：使疏遠","estrange / drive away","Ignoring residents' concerns could alienate the very people the project aims to help.","忽視居民的憂慮，可能讓專案原本想幫助的人反而感到疏離。",""]],"l6-0041":[["名詞：聯盟","coalition / partnership","Several small charities formed an alliance to share storage space and delivery vehicles.","幾個小型慈善團體結成聯盟，共享倉儲空間和送貨車輛。",""]],"l6-0042":[["動詞：分配","assign / allot","The council allocated additional funds to repair sidewalks near elementary schools.","議會增撥經費，修繕國小附近的人行道。",""]],"l6-0043":[["介系詞：在……旁邊","beside / next to","The rescue boat moved alongside the damaged yacht so passengers could transfer safely.","救援艇駛到受損遊艇旁，讓乘客能安全換船。",""]],"l6-0044":[["形容詞：替代的","other / substitute","The engineers proposed an alternative route that would avoid the unstable hillside.","工程師提出一條替代路線，可避開不穩定的山坡。",""]],"l6-0045":[["名詞：歧義；含糊","uncertainty / vagueness","The ambiguity in the contract led the two companies to interpret their duties differently.","合約中的歧義讓兩家公司對各自義務有不同解讀。",""]],"l6-0046":[["形容詞：有歧義的","unclear / equivocal","The instruction was ambiguous, so several students completed the task in different ways.","指示有歧義，因此幾位學生以不同方式完成了任務。",""]],"l6-0047":[["名詞：救護車","無直接同義詞","An ambulance arrived within minutes and took the injured worker to hospital.","救護車幾分鐘內抵達，把受傷工人送往醫院。",""]],"l6-0048":[["名詞：伏擊","surprise attack","The convoy changed its route after receiving a warning about a possible ambush.","車隊收到可能遭伏擊的警告後，改變了路線。",""]],"l6-0049":[["形容詞：和藹的","friendly / affable","The amiable librarian made new visitors feel comfortable asking for assistance.","和藹的圖書館員讓初次到訪的人能自在地尋求協助。",""]],"l6-0050":[["動詞：放大聲音","boost / increase","The microphone amplified her voice so people at the back could hear clearly.","麥克風放大了她的聲音，讓後排的人也能聽清楚。",""]],"l6-0051":[["複數名詞：語錄；文選","selected writings / extracts","The editor compiled analects from the philosopher's notebooks for students unfamiliar with his work.","編輯從哲學家的筆記中選編語錄，供不熟悉其著作的學生閱讀。","analects 為複數名詞；大寫 The Analects 常專指《論語》。https://www.merriam-webster.com/dictionary/analects"]],"l6-0052":[["名詞：類比","comparison / parallel","The teacher used an analogy between electrical circuits and flowing water to explain the concept.","老師以電路和流水作類比，解釋這個概念。",""]],"l6-0053":[["名詞：分析師","無直接同義詞","The analyst compared several years of sales data before recommending a new pricing strategy.","分析師比較了好幾年的銷售資料後，才建議新的定價策略。",""]],"l6-0054":[["形容詞：善於分析的","logical / methodical","Her analytical approach helped the team separate reliable evidence from attractive but unsupported claims.","她善於分析的做法幫助團隊區分可靠證據與吸引人但缺乏支持的說法。",""]],"l6-0055":[["名詞：軼事","brief personal account","He opened his speech with an anecdote about his first disastrous attempt at baking.","他演講開場時，講了自己第一次烘焙慘敗的小故事。",""]],"l6-0056":[["動詞：使活躍","enliven / energize","The musician's lively performance animated an audience that had seemed tired and distracted.","音樂家生動的演出讓原本疲倦、分心的觀眾活躍起來。",""]],"l6-0057":[["名詞：惱怒","irritation / exasperation","She could not hide her annoyance when the meeting was delayed for the third time.","會議第三次延後時，她掩飾不住惱怒。",""]],"l6-0058":[["形容詞：匿名的","unnamed / unidentified","An anonymous donor paid for new instruments for the school's music program.","一位匿名捐款者出資，為學校音樂課程添購樂器。",""]],"l6-0059":[["形容詞：南極的","無直接同義詞","The research team tested its equipment before beginning the Antarctic expedition.","研究團隊展開南極探險前，先測試了設備。",""]],"l6-0060":[["名詞：天線","aerial","The technician adjusted the antenna until the radio signal became clear.","技師調整天線，直到無線電訊號變得清楚。",""]],"l6-0061":[["名詞：抗生素","無直接同義詞","The researcher compared how two antibiotics affected the bacterial samples in the laboratory.","研究人員在實驗室比較兩種抗生素對細菌樣本的影響。",""]],"l6-0062":[["名詞：抗體","無直接同義詞","The laboratory measured antibody levels in the samples collected during the study.","實驗室測量研究期間採集樣本中的抗體濃度。",""]],"l6-0063":[["動詞：預期","expect / foresee","We anticipate delays because several roads near the venue are under repair.","由於場地附近好幾條道路正在施工，我們預期會有延誤。",""]],"l6-0064":[["名詞：期待","expectation","The children waited in eager anticipation as the theater lights began to dim.","劇院的燈光逐漸轉暗，孩子們滿懷期待地等候。",""]],"l6-0065":[["名詞：反義詞","opposite","The teacher asked each group to find an antonym for every adjective on the board.","老師要各組為黑板上的每個形容詞找出反義詞。",""]],"l6-0066":[["形容詞：適用的","relevant / appropriate","The discount is applicable only to tickets purchased before the end of the month.","折扣只適用於月底前購買的票券。",""]],"l6-0067":[["名詞：學徒","trainee","The apprentice learned to sharpen tools before working on customers' furniture.","那位學徒先學會磨工具，才開始製作客人的家具。","apprentice 通常有正式師徒訓練；trainee 的訓練型態較廣。"]],"l6-0068":[["形容詞：大約的","rough / estimated","The builder gave us an approximate cost before inspecting the damaged roof.","建商在檢查受損屋頂前，先提供了大約的費用。",""]],"l6-0069":[["名詞：天賦","talent / flair","Her aptitude for languages became apparent when she learned Italian remarkably quickly.","她很快就學會義大利文，顯示出語言天賦。",""]],"l6-0070":[["形容詞：北極的","無直接同義詞","The crew prepared for Arctic conditions by testing their clothing in extreme cold.","船員在嚴寒中測試衣物，為北極環境做準備。",""]],"l6-0071":[["形容詞：傲慢的","haughty / conceited","His arrogant dismissal of the volunteers' concerns damaged trust within the organization.","他傲慢地漠視志工的憂慮，破壞了組織內部的信任。",""]],"l6-0072":[["名詞：交通幹線","main route / thoroughfare","The main artery into the city was closed after a truck overturned.","一輛卡車翻覆後，進城的主要幹道封閉了。","本句為交通要道的比喻義；artery 也指動脈。"]],"l6-0073":[["形容詞：善於清楚表達的","eloquent / well-spoken","The articulate student explained the research clearly without relying on technical jargon.","那位善於表達的學生不用專業術語，也能清楚說明研究。",""]],"l6-0074":[["名詞：人工製品；文物","無直接同義詞","Archaeologists carefully photographed each artifact before removing it from the excavation site.","考古學家把每件文物移出挖掘現場前，都先仔細拍照。",""]],"l6-0075":[["動詞：暗殺","無直接同義詞","The novel follows a detective trying to uncover a plot to assassinate the governor.","小說描寫一名偵探試圖揭發暗殺州長的陰謀。","murder 泛指謀殺，assassinate 通常針對重要人物並有政治等動機。"]],"l6-0076":[["動詞：斷言","declare / maintain","The company asserted that its equipment had passed every required safety inspection.","公司斷言，設備已通過所有必要的安全檢查。",""]],"l6-0077":[["動詞：評估","evaluate / appraise","Engineers assessed the bridge's condition before allowing heavy vehicles to cross.","工程師先評估橋梁狀況，才允許重型車輛通行。",""]],"l6-0078":[["名詞：評估","evaluation / appraisal","The assessment identified several buildings that needed urgent repairs after the flood.","評估找出了洪水後急需修繕的幾棟建築。",""]],"l6-0079":[["名詞：假設","supposition / presumption","Our schedule was based on the assumption that the materials would arrive on time.","我們的進度表建立在材料會準時抵達的假設上。",""]],"l6-0080":[["名詞：氣喘","無直接同義詞","She told the hiking guide about her asthma before joining the mountain walk.","她參加山區健行前，先告知嚮導自己有氣喘。",""]],"l6-0081":[["名詞：庇護","refuge / sanctuary","The journalist sought asylum after receiving threats because of her reporting.","那位記者因報導而遭到威脅後，尋求庇護。","asylum 此處為他國提供的政治或人道庇護。"]],"l6-0082":[["名詞：達成","achievement / accomplishment","The attainment of the fundraising goal allowed construction of the clinic to begin.","募款目標達成後，診所便能開始興建。","原稿 attainment 標 vt/vi 有誤；attainment 是名詞，對應動詞為 attain。https://dictionary.cambridge.org/dictionary/english/attainment"]],"l6-0083":[["名詞：成就；達成程度","achievement","The study linked regular attendance with higher educational attainment among the participating students.","研究發現，參與學生規律出席與較高的教育成就有關。","原稿另有同拼字但詞性誤植的卡片；本筆示範 educational attainment。"]],"l6-0084":[["名詞：服務員","無直接同義詞","The parking attendant directed drivers toward the remaining spaces behind the building.","停車場服務員引導駕駛前往建築物後方剩餘的車位。",""]],"l6-0085":[["名詞：閣樓","loft","We found a box of handwritten letters while clearing out the attic.","清理閣樓時，我們找到了一箱手寫信件。",""]],"l6-0086":[["名詞：拍賣","無直接同義詞","The painting sold at auction for far more than the owner had expected.","那幅畫在拍賣會上的成交價，遠高於畫主預期。",""]],"l6-0087":[["形容詞：真品的","genuine / real","The museum asked an expert to verify that the ancient coins were authentic.","博物館請專家確認那些古錢幣是否為真品。",""]],"l6-0088":[["動詞：授權","permit / empower","The director authorized her assistant to sign the agreement on the organization's behalf.","主任授權助理代表組織簽署協議。",""]],"l6-0089":[["名詞：親筆簽名","signature","The student waited outside the hall to ask the violinist for an autograph.","那名學生在廳外等候，想向小提琴家索取親筆簽名。","autograph 常指收藏用的名人親筆簽名，signature 的用途較廣。"]],"l6-0090":[["名詞：自主權","independence / self-government","The agreement gives local schools greater autonomy over how they spend their budgets.","協議讓地方學校能更自主地決定如何運用預算。",""]],"l6-0091":[["名詞：航空","aeronautics","Her interest in aviation began when she visited an aircraft maintenance workshop.","她參觀飛機維修工場後，開始對航空產生興趣。","aeronautics 偏重飛行的科學與技術。"]],"l6-0092":[["形容詞：令人敬畏的","awe-inspiring / breathtaking","The awesome scale of the glacier made the hikers stop speaking for a moment.","冰川驚人的規模讓登山客一時說不出話來。",""]],"l6-0093":[["名詞：氣壓計","無直接同義詞","The sailor checked the barometer before deciding whether to leave the harbor.","水手查看氣壓計後，才決定是否離港。",""]],"l6-0094":[["動詞：招手示意","signal / gesture","The guide beckoned us toward the entrance as the rain began to fall.","開始下雨時，導覽員招手示意我們走向入口。",""]],"l6-0095":[["動詞：圍攻","lay siege to / surround","Enemy forces besieged the city, cutting off the roads used to bring in supplies.","敵軍圍攻城市，切斷了運送補給的道路。","besiege 強調為迫使投降而包圍，surround 只表示圍住。"]],"l6-0096":[["動詞：背叛","be disloyal to","He felt betrayed when his colleague shared their confidential discussion with competitors.","同事把兩人的機密談話透露給競爭對手，讓他覺得遭到背叛。",""]],"l6-0097":[["名詞：飲料","drink","The ticket includes one beverage, with both hot and cold options available.","票價包含一杯飲料，冷熱飲皆可選。",""]],"l6-0098":[["名詞：偏見","prejudice / partiality","Removing applicants' names helped reduce bias during the first stage of selection.","移除申請人的姓名，有助於降低第一階段篩選時的偏見。",""]],"l6-0099":[["名詞：雙筒望遠鏡","field glasses","We used binoculars to watch the nesting birds without approaching the cliff.","我們用雙筒望遠鏡觀察築巢的鳥，避免靠近懸崖。",""]],"l6-0100":[["名詞：生物化學","無直接同義詞","Her biochemistry research examines how enzymes help cells obtain energy from food.","她的生物化學研究探討酵素如何幫助細胞從食物獲得能量。",""]],"l6-0101":[["形容詞：生物的","無直接同義詞","The laboratory stores biological samples at controlled temperatures to preserve them for future analysis.","實驗室以受控溫度保存生物樣本，供日後分析。",""]],"l6-0102":[["形容詞：怪異的","strange / peculiar","The sculpture's bizarre combination of bicycle wheels and animal bones attracted curious visitors.","那座雕塑怪異地結合自行車輪子與動物骨骼，吸引了好奇的訪客。",""]],"l6-0103":[["形容詞：荒涼的","desolate / barren","The hikers crossed a bleak landscape with no trees or shelter from the wind.","登山客穿過荒涼的地帶，那裡沒有樹木，也無處避風。",""]],"l6-0104":[["名詞：嚴重失誤","mistake / error","A scheduling blunder sent two groups to the same room at the same time.","排程上的重大失誤讓兩組人同時被安排到同一間房。",""]],"l6-0105":[["形容詞：鈍的","dull","The carpenter replaced the blunt blade because it was tearing the wood instead of cutting cleanly.","木匠換掉鈍刀片，因為它扯裂木材，無法俐落切割。",""]],"l6-0106":[["動詞：砲擊","shell","The army bombarded the abandoned fort before attempting to advance across the valley.","軍隊先砲擊廢棄堡壘，再試圖穿越山谷推進。",""]],"l6-0107":[["名詞：奴役","slavery / servitude","The memoir describes her ancestors' struggle to escape bondage and establish an independent community.","回憶錄描寫她的祖先如何努力擺脫奴役，建立自主社群。",""]],"l6-0108":[["動詞：提高","increase / raise","The new railway connection could boost tourism in villages previously difficult to reach.","新鐵路連線可能帶動原本交通不便村莊的觀光。",""]],"l6-0109":[["名詞：拳擊比賽","match / contest","The boxer withdrew from the scheduled bout after injuring his shoulder during training.","那名拳擊手訓練時傷了肩膀，因此退出原訂的比賽。","拳擊 bout 通常指整場比賽，一回合是 round。"]],"l6-0110":[["動詞：抵制","refuse to buy","Customers threatened to boycott the brand after learning about conditions in its factories.","顧客得知品牌工廠的工作條件後，揚言抵制該品牌。",""]],"l6-0111":[["名詞：故障","failure / malfunction","A mechanical breakdown forced the ferry to return to the harbor before completing its route.","機械故障迫使渡輪在跑完航線前返回港口。",""]],"l6-0112":[["名詞：突破","advance / major development","The discovery marked a breakthrough in the team's search for a more durable material.","這項發現是團隊尋找更耐用材料的一大突破。",""]],"l6-0113":[["名詞：分手","separation / split","After the breakup, they agreed to return each other's belongings without further argument.","分手後，他們同意歸還彼此的物品，不再爭吵。",""]],"l6-0114":[["動詞：沖泡","steep","Let the tea brew for a few minutes before removing the leaves.","讓茶泡幾分鐘，再取出茶葉。",""]],"l6-0115":[["名詞：邊緣","edge / verge","The guide warned us to stay well away from the brink of the waterfall.","嚮導提醒我們務必遠離瀑布的邊緣。",""]],"l6-0116":[["形容詞：輕快有力的","energetic / lively","A brisk walk along the river helped her feel alert before the morning meeting.","沿河快步走了一段，讓她在早晨會議前精神振奮。",""]],"l6-0117":[["名詞：宣傳小冊","leaflet / booklet","The brochure includes a map, opening hours, and information about wheelchair access.","宣傳小冊包含地圖、開放時間及輪椅通行資訊。",""]],"l6-0118":[["名詞：粗暴的人","bully / thug","The novel portrays the landlord as a brute who frightens tenants into silence.","小說把房東描寫成粗暴的人，威嚇房客，讓他們不敢出聲。",""]],"l6-0119":[["名詞：扣環","clasp / fastener","The metal buckle on her backpack broke just before the hiking trip.","健行出發前，她背包上的金屬扣環壞了。",""]],"l6-0120":[["形容詞：體積龐大笨重的","cumbersome / unwieldy","The bulky equipment required a larger vehicle and two people to unload it.","設備又大又笨重，需要更大的車輛和兩個人卸貨。",""]],"l6-0121":[["名詞：官僚程序","red tape","The charity struggled with bureaucracy while trying to obtain permission for its emergency shelter.","慈善團體為臨時收容所申請許可時，被繁瑣的官僚程序拖住。",""]],"l6-0122":[["名詞：埋葬","interment","The family gathered for the burial in the small cemetery near their village.","家人聚集在村旁的小墓園，參加下葬儀式。","burial 專指埋葬；funeral 才是範圍較廣的葬禮。https://dictionary.cambridge.org/dictionary/english/burial"]],"l6-0123":[["名詞：位元組","無直接同義詞","The program checks each byte of the file before accepting the transfer as complete.","程式逐一檢查檔案的每個位元組，才確認傳輸完成。",""]],"l6-0124":[["名詞：咖啡因","無直接同義詞","The label states how much caffeine is contained in a single serving of the drink.","標籤列明這款飲料每份含有多少咖啡因。",""]],"l6-0125":[["名詞：鈣","無直接同義詞","The researchers measured calcium levels in soil samples taken from different parts of the field.","研究人員測量了田地不同位置所採土壤樣本的鈣含量。",""]],"l6-0126":[["名詞：帆布","無直接同義詞","The workers covered the equipment with heavy canvas before the rain reached the site.","雨勢到達工地前，工人用厚帆布蓋住設備。",""]],"l6-0127":[["名詞：能力","ability / capacity","The new laboratory has the capability to test water samples for several pollutants simultaneously.","新實驗室能同時檢測水樣中的多種污染物。",""]],"l6-0128":[["名詞：膠囊","無直接同義詞","The pharmacist checked that the capsules matched the prescription before handing over the package.","藥師先確認膠囊符合處方，再交出藥包。",""]],"l6-0129":[["名詞：圖片說明","legend / description","The caption beneath the photograph identifies the workers and explains when the bridge was built.","照片下方的說明標出工人身分，並交代橋梁的建造時間。",""]],"l6-0130":[["名詞：俘虜","prisoner","The negotiators requested proof that the captives were alive before continuing the talks.","談判人員要求先證明俘虜仍然活著，才繼續談判。",""]],"l6-0131":[["名詞：囚禁","confinement / imprisonment","The rescued eagle spent several months in captivity before it was strong enough to be released.","獲救的鷹被圈養了好幾個月，體力恢復後才獲得野放。",""]],"l6-0132":[["名詞：碳水化合物","無直接同義詞","The food label lists the amount of carbohydrate in each serving of the cereal.","食品標籤列出每份穀片含有多少碳水化合物。",""]],"l6-0133":[["動詞：愛撫","stroke","She caressed the frightened dog's head while the veterinarian examined its injured leg.","獸醫檢查受傷的腿時，她輕撫那隻受驚狗兒的頭。",""]],"l6-0134":[["名詞：耶誕頌歌","Christmas song","The choir sang a familiar carol as visitors gathered outside the old church.","訪客聚集在老教堂外時，合唱團唱起了一首熟悉的耶誕頌歌。",""]],"l6-0135":[["名詞：收銀員","checkout operator","The cashier noticed that the same item had been scanned twice and corrected the bill.","收銀員發現同一件商品刷了兩次，便更正帳單。",""]],"l6-0136":[["名詞：傷亡者","無直接同義詞","Rescue teams searched the damaged buildings while hospitals prepared to receive additional casualties.","救援隊搜索受損建築，醫院則準備接收更多傷者。","casualty 可指傷者或死者；本句由送醫情境限定為傷者。"]],"l6-0137":[["名詞：大災難","disaster / calamity","The flood became a catastrophe when the river broke through the town's protective walls.","河水衝破城鎮的防護堤後，洪水演變成大災難。",""]],"l6-0138":[["動詞：提供餐飲服務","provide catering","The family business caters for weddings and other large events throughout the region.","這家家族企業為區內婚禮及其他大型活動提供餐飲服務。",""]],"l6-0139":[["名詞：騎兵","mounted troops","The painting shows cavalry moving across the plain before the battle begins.","這幅畫描繪戰鬥開始前，騎兵穿越平原的情景。",""]],"l6-0140":[["名詞：蛀洞","無直接同義詞","The dentist found a small cavity during the examination and explained the available treatment options.","牙醫檢查時發現了一個小蛀洞，並說明可採用的治療方式。","caries 指蛀牙病變，通常不用 a caries 表示單一蛀洞。"]],"l6-0141":[["名詞：墓園","graveyard / burial ground","The cemetery contains the graves of several families who founded the village.","墓園裡葬著幾個建立這座村莊的家族。",""]],"l6-0142":[["名詞：確定","assurance / confidence","Without the original records, we cannot establish the building's age with certainty.","沒有原始紀錄，我們無法確定這棟建築的年代。",""]],"l6-0143":[["動詞：證明合格","verify / attest","An independent inspector must certify that the lift meets all required safety standards.","必須由獨立檢驗員證明電梯符合所有必要安全標準。",""]],"l6-0144":[["名詞：香檳","無直接同義詞","The hosts served champagne after announcing that the restoration project had been completed.","主人宣布修復專案完成後，端出了香檳。",""]],"l6-0145":[["名詞：混亂","disorder / confusion","Conflicting announcements created chaos as passengers tried to find the correct replacement buses.","相互矛盾的廣播讓尋找正確接駁公車的乘客陷入混亂。",""]],"l6-0146":[["動詞：構成……的特徵","mark / distinguish","Wide verandas and steep roofs characterize many of the region's older wooden houses.","寬敞門廊和陡斜屋頂是當地許多老木屋的特色。",""]],"l6-0147":[["名詞：煤","無直接同義詞","The factory once relied on coal to heat the boilers that powered its machinery.","這間工廠曾靠燃煤加熱鍋爐，驅動機器。","原稿把 coal 譯成木炭有誤；煤為 coal，木炭為 charcoal。https://dictionary.cambridge.org/dictionary/english/coal"]],"l6-0148":[["名詞：古代雙輪戰車","無直接同義詞","The museum displayed a reconstructed chariot beside the ancient wheels found during the excavation.","博物館在挖掘出土的古代車輪旁，展示了一輛重建的雙輪戰車。",""]],"l6-0149":[["形容詞：慈善的","philanthropic / benevolent","The company donated its unused computers to a charitable organization that supports rural schools.","公司把閒置電腦捐給支援偏鄉學校的慈善組織。",""]],"l6-0150":[["名詞：膽固醇","無直接同義詞","The study compared cholesterol measurements taken before and after the participants changed their diets.","研究比較參與者改變飲食前後測得的膽固醇數值。",""]],"l6-0151":[["形容詞：慢性的","persistent / long-term","The clinic provides continuing support for patients managing chronic illnesses at home.","診所持續支持在家管理慢性疾病的病人。","chronic 強調長期持續，不必然表示病情嚴重。"]],"l6-0152":[["動詞：低聲輕笑","laugh quietly","He chuckled when he recognized his childhood haircut in the old family photograph.","他在老全家福裡認出自己童年的髮型時，輕聲笑了。",""]],"l6-0153":[["名詞：大塊","lump / piece","A large chunk of ice broke away from the glacier and fell into the sea.","一大塊冰從冰川剝落，掉進海裡。",""]],"l6-0154":[["動詞：使舉止文明","refine / cultivate","The narrator wrongly assumes that wealth and fine clothing automatically civilize people.","敘事者錯誤地以為財富和華服自然就能使人舉止文明。","描述不同族群時，civilize 容易帶有文化高低之分；此句批判表面判斷。"]],"l6-0155":[["動詞：夾緊","grip / fasten","Clamp the board securely to the workbench before making the first cut.","開始切割前，先把木板牢牢夾在工作臺上。",""]],"l6-0156":[["名詞：清晰","clearness / lucidity","The diagrams improved the clarity of instructions that had confused several new employees.","圖解讓原本困擾幾位新員工的說明更清楚了。",""]],"l6-0157":[["動詞：清潔","clean / purify","The treatment system cleanses the water before releasing it back into the river.","處理系統先淨化水，再排回河裡。",""]],"l6-0158":[["名詞：清除","removal","The clearance of fallen trees allowed emergency vehicles to reach the isolated village.","倒樹清除後，救援車輛便能抵達受困的村莊。",""]],"l6-0159":[["動詞：握緊","tighten / close tightly","He clenched his fists under the table but kept his voice calm.","他在桌下握緊拳頭，語氣卻保持平靜。",""]],"l6-0160":[["形容詞：臨床的","無直接同義詞","The researchers emphasized that laboratory results must be confirmed through clinical studies involving patients.","研究人員強調，實驗室結果必須透過有病人參與的臨床研究確認。",""]],"l6-0161":[["名詞：複製品","duplicate / copy","The cheaper phone looked like a clone of the original, but its software was different.","那支便宜手機看似原版的複製品，軟體卻不同。","本句為外觀或功能仿製的比喻義，非生物複製。"]],"l6-0162":[["名詞：關閉","shutdown","The temporary closure of the bridge forced commuters to take a much longer route.","橋梁暫時封閉，迫使通勤者繞行遠得多的路線。",""]],"l6-0163":[["名詞：棺木","casket","The family placed flowers beside the coffin before the funeral service began.","葬禮開始前，家人在棺木旁放了花。",""]],"l6-0164":[["形容詞：連貫的","logical / consistent","The witness gave a coherent account despite being upset by what she had seen.","證人雖然因目睹的事情而難過，仍作出了連貫的陳述。",""]],"l6-0165":[["動詞：同時發生","overlap / occur together","The repairs will coincide with the school holidays to reduce disruption to lessons.","維修會安排在學校放假期間，以減少對課程的干擾。",""]],"l6-0166":[["名詞：巧合","chance occurrence","It was a coincidence that both researchers arrived at the same conclusion independently.","兩位研究人員獨立得到相同結論，這是個巧合。",""]],"l6-0167":[["形容詞：集體的","joint / shared","The cleanup succeeded because of the collective effort of residents, shopkeepers, and students.","清理工作因居民、店家和學生共同努力而成功。",""]],"l6-0168":[["名詞：收藏家","無直接同義詞","The collector lent several rare maps to the museum for its anniversary exhibition.","那位收藏家借出幾幅珍稀地圖，供博物館週年展覽使用。",""]],"l6-0169":[["動詞：相撞","crash / hit","The two bicycles nearly collided when their riders turned into the narrow lane.","兩位騎士轉進狹窄巷道時，自行車差點相撞。",""]],"l6-0170":[["名詞：碰撞","crash / impact","The collision damaged both vehicles and blocked the intersection for almost an hour.","碰撞損壞了兩輛車，路口也被堵住了將近一小時。",""]],"l6-0171":[["形容詞：口語的","informal / conversational","The translator replaced several formal expressions with colloquial language that suited the teenage narrator.","譯者把幾個正式表達換成口語，更符合青少年敘事者的語氣。",""]],"l6-0172":[["名詞：專欄作家","無直接同義詞","The newspaper's education columnist invited teachers to respond to her article about homework.","報紙的教育專欄作家邀請老師回應她關於作業的文章。",""]],"l6-0173":[["動詞：紀念","honor / remember","The town planted a tree to commemorate the volunteers who rebuilt the school.","鎮上種了一棵樹，紀念重建學校的志工。",""]],"l6-0174":[["動詞：開始","begin / start","The crew will commence repairs once the final safety inspection has been completed.","最後的安全檢查完成後，工班就會開始修繕。",""]],"l6-0175":[["名詞：評論","analysis / discussion","Her commentary connects the novel's family conflicts with wider changes in society.","她的評論把小說中的家庭衝突與更廣泛的社會變遷連結起來。",""]],"l6-0176":[["名詞：承諾","pledge / promise","The company made a commitment to repair faulty products without charging customers.","公司承諾免費維修有故障的產品。",""]],"l6-0177":[["形容詞：樂於交談的","talkative / open","He became more communicative once the interviewer asked about his work with rescue dogs.","面試官問起他與搜救犬合作的工作後，他變得更健談。",""]],"l6-0178":[["名詞：陪伴","company / fellowship","The weekly gardening group offers companionship to older residents who live alone.","每週的園藝團體為獨居長者提供陪伴。",""]],"l6-0179":[["形容詞：相近可比的","similar / equivalent","The researchers compared schools with comparable budgets to make the results more meaningful.","研究人員比較預算相近的學校，讓結果更有參考價值。",""]],"l6-0180":[["形容詞：比較性的","無直接同義詞","The report presents a comparative study of bus fares in five neighboring cities.","報告提出了鄰近五座城市公車票價的比較研究。",""]],"l6-0181":[["形容詞：相容的","interoperable","Check that the replacement charger is compatible with your laptop before buying it.","購買替換充電器前，先確認它與你的筆電相容。","interoperable 常指系統能彼此運作，適用範圍比 compatible 窄。"]],"l6-0182":[["動詞：補償","reimburse / repay","The airline compensated passengers for the extra hotel costs caused by the canceled flight.","航空公司補償乘客因航班取消而增加的住宿費。",""]],"l6-0183":[["名詞：補償金","reimbursement / payment","The family received compensation for damage caused when the construction company broke a water pipe.","建設公司弄破水管造成損害後，那家人獲得了賠償。",""]],"l6-0184":[["名詞：勝任能力","proficiency / capability","Applicants must demonstrate competence in using the equipment before they can work independently.","申請者必須證明能熟練使用設備，才能獨立工作。",""]],"l6-0185":[["形容詞：能勝任的","capable / proficient","A competent technician should be able to identify the fault without replacing every component.","稱職的技師應能找出故障，不必把每個零件都換掉。",""]],"l6-0186":[["動詞：彙編","assemble / collect","The librarian compiled a list of reliable resources for students researching local history.","圖書館員為研究地方史的學生彙整了一份可靠資料清單。",""]],"l6-0187":[["名詞：相輔相成的事物","accompaniment","The crisp salad was a refreshing complement to the rich cheese pie.","爽脆的沙拉清爽解膩，與濃郁的起司派相得益彰。","complement 使另一事物更完整；compliment 是稱讚。"]],"l6-0188":[["名詞：膚色","skin tone","The portrait captured her pale complexion and the faint freckles across her cheeks.","肖像畫呈現了她白皙的膚色，以及臉頰上淡淡的雀斑。",""]],"l6-0189":[["名詞：複雜程度","intricacy","The complexity of the timetable became clear when we tried to accommodate every class.","當我們試著排入每個班級時，才看出課表有多複雜。",""]],"l6-0190":[["名詞：使事情更難的問題","difficulty / obstacle","An unexpected complication arose when workers discovered damaged wiring behind the wall.","工人發現牆後電線損壞，讓工程多了一個意外難題。",""]],"l6-0191":[["名詞：零件","part / element","The mechanic replaced one worn component instead of discarding the entire assembly.","技師只更換一個磨損零件，沒有丟棄整組裝置。",""]],"l6-0192":[["形容詞：全面的","thorough / extensive","The guide provides a comprehensive overview of the region's history, wildlife, and walking routes.","指南全面介紹了當地歷史、野生動物和步行路線。",""]],"l6-0193":[["動詞：包含；由……組成","consist of / include","The exhibition comprises photographs, handwritten letters, and objects donated by local families.","展覽包含照片、手寫信及當地家庭捐贈的物品。","整體 comprises 各部分，不需加 of。"]],"l6-0194":[["動詞：勉強承認","admit / acknowledge","After reviewing the figures, the manager reluctantly conceded that the original estimate was unrealistic.","經理檢視數據後，承認原本的估計不切實際。",""]],"l6-0195":[["名詞：自負","vanity / arrogance","His conceit prevented him from accepting advice from colleagues with far more experience.","他的自負讓他無法接受經驗遠比他豐富的同事的建議。",""]],"l6-0196":[["名詞：觀念","concept / notion","The project challenged her conception of what a public library could offer its community.","這個專案改變了她對公共圖書館能為社區提供什麼的觀念。",""]],"l6-0197":[["名詞：讓步","compromise","The landlord made one concession by allowing tenants to pay the deposit in installments.","房東作出一項讓步，允許房客分期繳付押金。",""]],"l6-0198":[["形容詞：簡潔的","brief / succinct","Please provide a concise explanation of the problem before describing possible solutions.","請先簡潔說明問題，再描述可能的解決方法。",""]],"l6-0199":[["動詞：濃縮文字","shorten / abridge","The editor condensed the lengthy interview into a readable article without changing the speaker's meaning.","編輯把冗長的訪談濃縮成易讀文章，同時保留受訪者的原意。",""]],"l6-0200":[["動詞：授予","award / bestow","The university conferred an honorary degree on the architect who restored the historic campus.","大學頒授榮譽學位給修復歷史校園的建築師。","confer something on someone，把某物授予某人。"]],"l6-0201":[["形容詞：機密的","secret / private","Please keep these financial records confidential until the audit has been completed.","稽核完成前，請對這些財務紀錄保密。",""]],"l6-0202":[["動詞：符合","comply / adhere","All replacement parts must conform to the specifications provided by the manufacturer.","所有替換零件都必須符合製造商提供的規格。","conform to、comply with、adhere to，介系詞不同。"]],"l6-0203":[["名詞：對峙","clash / conflict","A calm explanation prevented the disagreement from turning into an angry confrontation.","冷靜的說明避免了歧見演變成憤怒對峙。",""]],"l6-0204":[["名詞：美國國會議員","member of Congress","The congresswoman met residents whose homes were threatened by the proposed highway expansion.","那位女國會議員會見了住家受到擬議公路拓寬案威脅的居民。",""]],"l6-0205":[["名詞：征服","subjugation","The historian examined how the conquest changed land ownership in the defeated kingdom.","歷史學家研究了征服如何改變戰敗王國的土地所有權。",""]],"l6-0206":[["形容詞：盡責的","diligent / meticulous","The conscientious nurse checked every label before distributing medication to the patients.","那位盡責的護理師逐一檢查標籤，才把藥發給病人。",""]],"l6-0207":[["名詞：共識","agreement","After several meetings, the committee reached a consensus on the new library's location.","經過幾次會議，委員會對新圖書館的地點達成了共識。",""]],"l6-0208":[["名詞：保育","preservation / protection","The conservation project restores wetlands that provide nesting sites for migratory birds.","這項保育計畫復育濕地，為候鳥提供築巢地點。",""]],"l6-0209":[["名詞：安慰","comfort / solace","Her friends' support offered some consolation after the unexpected loss of her job.","她意外失業後，朋友的支持帶來了一些安慰。",""]],"l6-0210":[["名詞：陰謀","plot / scheme","Investigators uncovered a conspiracy to hide the company's debts from potential investors.","調查人員揭發了一項向潛在投資人隱瞞公司債務的陰謀。",""]],"l6-0211":[["形容詞：組成的","composing / forming","The laboratory separated the sample into its constituent elements for further analysis.","實驗室把樣本分離成各個組成元素，進一步分析。",""]],"l6-0212":[["名詞：諮詢","discussion / conference","The architect revised the plans after consultation with residents who use wheelchairs.","建築師諮詢使用輪椅的居民後，修改了設計圖。",""]],"l6-0213":[["名詞：消耗","use / expenditure","Improved insulation reduced the building's energy consumption during the coldest months.","改善隔熱後，這棟建築在最寒冷月份的能源消耗降低了。",""]],"l6-0214":[["名詞：沉思","reflection / meditation","After a period of quiet contemplation, she decided to accept the position abroad.","經過一段安靜沉思，她決定接受海外職位。",""]],"l6-0215":[["名詞：參賽者","competitor / participant","Each contestant had one hour to prepare a meal using the same ingredients.","每位參賽者有一小時，用相同食材做出一餐。",""]],"l6-0216":[["名詞：承包商","無直接同義詞","The contractor agreed to replace the damaged tiles before requesting the final payment.","承包商同意先更換損壞的磁磚，再請領尾款。",""]],"l6-0217":[["動詞：與……矛盾","conflict with / be inconsistent with","The witness's later statement contradicted the account she had originally given the police.","證人後來的說法，與她最初向警方作的陳述矛盾。",""]],"l6-0218":[["名詞：矛盾","inconsistency / conflict","There is a clear contradiction between the company's promises and its actual working conditions.","公司的承諾與實際工作條件有明顯矛盾。",""]],"l6-0219":[["形容詞：有爭議的","contentious / disputed","The controversial proposal to remove the old market divided residents and local businesses.","拆除老市場的提案引發爭議，居民與當地商家意見分歧。","原稿可疑的釋義不準確；controversial 指引起爭議，並非 suspicious。https://dictionary.cambridge.org/dictionary/english/controversial"]],"l6-0220":[["名詞：爭議","dispute / debate","The decision caused controversy because the public had not been consulted beforehand.","這項決定引發爭議，因為事前沒有諮詢公眾。",""]],"l6-0221":[["名詞：堅定信念","belief / certainty","Her conviction that education changes lives guided her work in the rural community.","她堅信教育能改變人生，這份信念引導她在偏鄉的工作。",""]],"l6-0222":[["動詞：協調","organize / synchronize","A central office coordinates deliveries so that each shelter receives enough food and blankets.","中央辦公室協調配送，確保各收容所有足夠的食物和毛毯。",""]],"l6-0223":[["形容詞：熱誠友好的","warm / friendly","Despite their political differences, the two mayors maintained a cordial working relationship.","兩位市長雖然政治立場不同，仍維持友好的工作關係。",""]],"l6-0224":[["名詞：核心","heart / center","Reliable public transport is at the core of the city's plan to reduce traffic.","可靠的大眾運輸，是這座城市減少車流計畫的核心。",""]],"l6-0225":[["形容詞：公司的","無直接同義詞","The investigators examined corporate records to determine who had authorized the payments.","調查人員檢視公司紀錄，釐清誰核准了這些付款。",""]],"l6-0226":[["名詞：專業隊伍","unit / body","The medical corps established a temporary clinic near the flooded villages.","醫療隊在淹水村莊附近設立了臨時診所。","corps 單複數同形；字尾 ps 不發音。"]],"l6-0227":[["名詞：屍體","dead body","The detective asked the medical examiner to determine how long the corpse had been in the water.","偵探請法醫判定屍體在水中已有多久。",""]],"l6-0228":[["名詞：通信者","letter writer","The historian traced the identity of a frequent correspondent mentioned in the author's diary.","歷史學家查明了作家日記中一位經常通信者的身分。","本例為通信者義；correspondent 也常指特派記者。"]],"l6-0229":[["名詞：貪腐","dishonesty / misconduct","The investigation exposed corruption in the awarding of contracts for road repairs.","調查揭露了道路維修合約發包過程中的貪腐。",""]],"l6-0230":[["形容詞：美容用的","無直接同義詞","The company tests cosmetic products for stability before releasing them to retailers.","公司把美容產品交給零售商前，會先測試穩定性。",""]],"l6-0231":[["複數名詞：化妝品","makeup","She packed her cosmetics separately to keep loose powder away from her clothes.","她把化妝品另外裝好，免得散粉沾到衣服。",""]],"l6-0232":[["形容詞：具有多元文化的","international / multicultural","The port has a cosmopolitan atmosphere, with restaurants and markets reflecting many different cultures.","這座港口具有多元文化氣息，餐廳和市場呈現出各種不同文化。",""]],"l6-0233":[["名詞：職位相對應的人","opposite number","The education minister met her counterpart to discuss student exchanges between the two countries.","教育部長會見另一國的教育部長，討論兩國學生交流。",""]],"l6-0234":[["名詞：覆蓋範圍","reach / extent","Mobile coverage becomes unreliable in the valley, so hikers carry a paper map.","山谷中的行動通訊涵蓋不穩定，因此登山客攜帶紙本地圖。",""]],"l6-0235":[["動詞：覬覦","crave / desire","Several developers covet the waterfront land because of its potential for expensive apartments.","幾家建商覬覦那片濱水土地，因為它適合興建高價公寓。","covet 常表示強烈想擁有別人的東西。"]],"l6-0236":[["名詞：抽筋","muscle spasm","A painful cramp in his calf forced the runner to stop and rest.","他小腿抽筋的疼痛，迫使這名跑者停下來休息。",""]],"l6-0237":[["名詞：可信度","believability / trustworthiness","Correcting the error openly helped the newspaper preserve its credibility with readers.","公開更正錯誤，有助於報紙維持在讀者心中的可信度。",""]],"l6-0238":[["形容詞：可信的","believable / convincing","The explanation seemed credible because it matched the records from three independent sources.","這項解釋與三個獨立來源的紀錄相符，因此看來可信。",""]],"l6-0239":[["名詞：判準","standard / yardstick","Reliability was the main criterion used to select the new supplier.","可靠性是選擇新供應商的主要判準。","criterion 單數，criteria 複數。"]],"l6-0240":[["動詞：彎曲","bend / curve","She crooked her finger to beckon the child closer without interrupting the performance.","她彎起手指，示意孩子靠近，同時避免打斷表演。",""]],"l6-0241":[["形容詞：歪斜的","bent / twisted","The carpenter replaced the crooked frame because the door would no longer close properly.","木匠換掉歪斜的門框，因為門已經無法正常關上。",""]],"l6-0242":[["形容詞：關鍵的","critical / vital","Accurate weather information was crucial to deciding when the rescue helicopter could depart.","準確的天氣資訊是決定救援直升機何時能出發的關鍵。",""]],"l6-0243":[["形容詞：未精煉的","unrefined / raw","The tanker carried crude oil to a refinery on the southern coast.","油輪把原油載往南部海岸的一座煉油廠。",""]],"l6-0244":[["動詞：悠閒航行","sail","We cruised along the coast, stopping at small harbors whenever the weather allowed.","我們沿著海岸悠閒航行，天氣許可時便停靠小港口。",""]],"l6-0245":[["名詞：可供遊航的遊艇","cabin cruiser","The family rented a cruiser with sleeping space for four people.","那家人租了一艘有四人睡眠空間的遊艇。","cruiser 也可指巡洋艦；本例為遊艇義。"]],"l6-0246":[["名詞：麵包屑","bread crumb","She brushed the crumbs from the table before bringing out the dessert.","她把桌上的麵包屑刷掉後，才端出甜點。",""]],"l6-0247":[["動詞：碎裂","break apart / disintegrate","The old brick crumbled in his hand when he tried to remove it.","他試著取出老磚時，磚在手中碎裂了。",""]],"l6-0248":[["名詞：派皮","pastry shell","Bake the crust briefly before adding the filling so the bottom stays crisp.","先把派皮稍微烤一下再加餡，讓底部保持酥脆。",""]],"l6-0249":[["動詞：栽培","grow / raise","The farmers cultivate several varieties of rice adapted to the valley's wet climate.","農民栽培幾種適應山谷濕潤氣候的稻米。",""]],"l6-0250":[["形容詞：累積的","accumulated / combined","The report examines the cumulative effect of small delays on the project's final cost.","報告檢視多次小延誤累積後，對專案最終成本造成的影響。",""]],"l6-0251":[["形容詞：慣常的","usual / traditional","It is customary for guests to remove their shoes before entering the house.","客人進屋前脫鞋是慣例。",""]],"l6-0252":[["名詞：黃水仙","無直接同義詞","Bright yellow daffodils appeared along the path as the last snow melted.","最後的積雪融化時，小徑旁開出了鮮黃色的水仙花。",""]],"l6-0253":[["名詞：頭皮屑","無直接同義詞","He noticed flakes of dandruff on his dark jacket before the meeting.","開會前，他發現深色夾克上有一些頭皮屑。",""]],"l6-0254":[["名詞：黎明","dawn / first light","The crew left the harbor at daybreak to reach the island before the wind strengthened.","船員黎明離港，想在風勢增強前抵達島嶼。",""]],"l6-0255":[["形容詞：致命的","lethal / fatal","The warning signs marked an area where unstable rocks could cause a deadly fall.","警告牌標示出岩石不穩、可能發生致命墜落的區域。",""]],"l6-0256":[["形容詞：正派的","honorable / respectable","He was a decent landlord who repaired problems promptly and treated tenants fairly.","他是位正派的房東，會迅速修繕問題，也公平對待房客。",""]],"l6-0257":[["形容詞：果斷的","resolute / determined","Her decisive leadership prevented confusion when the storm forced everyone to evacuate.","暴風雨迫使所有人撤離時，她果斷的領導作風避免了混亂。",""]],"l6-0258":[["動詞：下降","decrease / fall","Attendance declined after the evening bus service to the community center was canceled.","前往活動中心的晚間公車停駛後，出席人數下降了。",""]],"l6-0259":[["動詞：投入；奉獻","devote / commit","She dedicated her weekends to restoring the abandoned garden behind the library.","她把週末時間投入整修圖書館後方荒廢的花園。",""]],"l6-0260":[["名詞：奉獻","devotion / commitment","The volunteers' dedication kept the shelter running throughout the long winter.","志工的奉獻讓收容所在漫長冬季持續運作。",""]],"l6-0261":[["動詞：認為","consider / judge","The inspector deemed the building unsafe until the damaged staircase had been repaired.","檢驗員認為，在損壞樓梯修好之前，這棟建築並不安全。",""]],"l6-0262":[["名詞：缺陷","flaw / fault","A manufacturing defect caused the handle to detach during the product's first use.","製造缺陷讓產品第一次使用時把手就脫落了。",""]],"l6-0263":[["名詞：缺乏","shortage / lack","The report identified a deficiency in the training provided to newly hired staff.","報告指出新進員工接受的訓練有所不足。",""]],"l6-0264":[["動詞：使品質降低","deteriorate / weaken","Repeated exposure to sunlight can degrade the fabric and weaken its protective coating.","反覆曝曬會使布料劣化，削弱保護塗層。","本句示範品質降低義；原稿只列使降級。"]],"l6-0265":[["形容詞：蓄意的","intentional / purposeful","The missing figures appeared to be a deliberate attempt to hide the project's true cost.","那些遺漏數據看來是蓄意隱瞞專案真正成本的手段。",""]],"l6-0266":[["形容詞：逾期未付款的","overdue / in arrears","The company contacted customers whose accounts had become delinquent after repeated missed payments.","公司聯絡了多次未付款、帳款已逾期的客戶。","delinquent 也可指有違法行為；本句限定付款逾期義。"]],"l6-0267":[["動詞：譴責","condemn / censure","The union denounced the decision to close the factory without consulting its workers.","工會譴責未諮詢工人就決定關廠的做法。",""]],"l6-0268":[["名詞：密度","concentration","The map shows areas where population density is highest and green space is limited.","地圖標出人口密度最高、綠地不足的地區。",""]],"l6-0269":[["形容詞：牙齒的","無直接同義詞","The school invited a specialist to explain dental care using a large model of teeth.","學校邀請專家用大型牙齒模型說明牙齒保健。",""]],"l6-0270":[["動詞：描繪","portray / illustrate","The mural depicts market vendors preparing their stalls before the city wakes up.","壁畫描繪市場攤販在城市甦醒前準備攤位的情景。",""]],"l6-0271":[["動詞：剝奪","deny / dispossess","Closing the library would deprive many students of a quiet place to study.","關閉圖書館會讓許多學生失去安靜讀書的地方。","deprive someone of something；deny someone something。"]],"l6-0272":[["名詞：副手","assistant / second-in-command","The director asked her deputy to lead the meeting while she visited the construction site.","主任前往工地時，請副手主持會議。",""]],"l6-0273":[["動詞：獲得","obtain / gain","The village derives much of its income from visitors drawn to the nearby wetlands.","村莊許多收入來自被附近濕地吸引而來的遊客。","derive something from something，從某處取得。"]],"l6-0274":[["動詞：下降","go down","The hikers descended carefully as loose stones shifted beneath their boots.","靴子下的碎石不斷滑動，登山客小心地下山。",""]],"l6-0275":[["名詞：後代","offspring","Descendants of the original residents returned to the village for its anniversary celebration.","最早居民的後代回到村裡，參加週年慶祝活動。","offspring 常指子女，descendant 可隔多個世代。"]],"l6-0276":[["名詞：下降","drop / downward journey","The descent into the valley took longer because the path was covered in ice.","因步道結冰，下到山谷的路程花了更久。",""]],"l6-0277":[["動詞：指定","appoint / name","The committee designated one member to collect questions from residents before the public meeting.","委員會指定一名成員，在公開會議前蒐集居民的問題。",""]],"l6-0278":[["形容詞：注定的","fated / bound","Without reliable funding, the ambitious restoration project seemed destined to fail.","缺乏穩定經費，這個雄心勃勃的修復專案似乎注定失敗。",""]],"l6-0279":[["動詞：拆下","disconnect / remove","Detach the small microphone from its stand before packing the equipment.","收裝設備前，先把小麥克風從支架上拆下。",""]],"l6-0280":[["動詞：拘留","hold / keep in custody","Police detained the driver while they verified the ownership of the vehicle.","警方確認車輛所有權期間，拘留了駕駛。",""]],"l6-0281":[["動詞：阻止；使卻步","discourage / dissuade","Clear warning signs may deter visitors from entering the unstable section of the cliff.","清楚的警告牌可能阻止遊客進入不穩定的崖邊區域。",""]],"l6-0282":[["名詞：清潔劑","cleaning agent","The cleaner used a mild detergent to avoid damaging the painted surface.","清潔人員使用溫和清潔劑，避免損壞漆面。",""]],"l6-0283":[["動詞：惡化","worsen / decline","The road's condition deteriorated rapidly after heavy trucks began using it daily.","重型卡車開始每天行駛後，路況迅速惡化。",""]],"l6-0284":[["動詞：貶低價值","undervalue / depreciate","Treating care work as unskilled can devalue the experience and judgment it requires.","把照護工作視為不需技能，會貶低它所需經驗與判斷力的價值。",""]],"l6-0285":[["名詞：糖尿病","無直接同義詞","The clinic organized a discussion where people living with diabetes could share their experiences.","診所舉辦座談，讓糖尿病患者分享生活經驗。",""]],"l6-0286":[["動詞：診斷","identify","The specialist reviewed the test results before attempting to diagnose the patient's condition.","專科醫師先檢視檢查結果，再試著診斷病人的狀況。",""]],"l6-0287":[["名詞：診斷","identification","The unexpected diagnosis prompted the family to request a second medical opinion.","出乎意料的診斷讓家人決定尋求第二位醫師的意見。",""]],"l6-0288":[["名詞：圖解","illustration / schematic","The diagram shows how water moves through the building's heating system.","圖解顯示水如何流經建築物的暖氣系統。",""]],"l6-0289":[["名詞：直徑","無直接同義詞","Measure the pipe's diameter carefully before ordering a replacement connector.","訂購替換接頭前，先仔細測量管子的直徑。",""]],"l6-0290":[["動詞：口述","read aloud for transcription","She dictated the letter slowly while her assistant typed it into the computer.","她慢慢口述信件內容，助理則把文字輸入電腦。",""]],"l6-0291":[["名詞：聽寫","無直接同義詞","The teacher used a short dictation to check whether students recognized unfamiliar sounds.","老師用簡短聽寫，檢查學生能否辨認不熟悉的語音。",""]],"l6-0292":[["名詞：獨裁者","autocrat / despot","The dictator silenced independent newspapers and replaced elected officials with loyal supporters.","獨裁者壓制獨立報紙，並以效忠者取代民選官員。",""]],"l6-0293":[["動詞：區分","distinguish / tell apart","The guide taught us to differentiate edible mushrooms from similar-looking poisonous varieties.","嚮導教我們區分可食用菇類與外觀相似的有毒種類。",""]],"l6-0294":[["名詞：兩難","predicament / quandary","She faced a dilemma between accepting the promotion and remaining close to her family.","她陷入兩難，必須在接受升遷和留在家人身邊之間選擇。",""]],"l6-0295":[["名詞：尺寸","measurement","The carpenter checked the dimensions of the doorway before building the new cabinet.","木匠先確認門口尺寸，再製作新櫃子。",""]],"l6-0296":[["動詞：減少","reduce / lessen","The initial excitement diminished as repeated delays pushed the opening further into the future.","開幕一再延後，最初的興奮也逐漸消退。",""]],"l6-0297":[["名詞：交涉手腕","tact / negotiation","Resolving the dispute required patient diplomacy rather than another round of public accusations.","化解爭端需要耐心的交涉手腕，而非再一輪公開指責。",""]],"l6-0298":[["形容詞：外交的","無直接同義詞","The two governments resumed diplomatic talks after agreeing on a temporary border arrangement.","兩國政府同意暫時的邊境安排後，恢復外交談判。",""]],"l6-0299":[["名詞：通訊名錄","listing / address book","The staff directory lists each employee's department, extension number, and office location.","員工通訊錄列出每人的部門、分機和辦公室位置。","directory 是名錄，不是原稿所列的一般使用手冊 manual。https://dictionary.cambridge.org/dictionary/english/directory"]],"l6-0300":[["名詞：身心障礙","無直接同義詞","The museum revised its audio guides after consulting visitors with visual disabilities.","博物館諮詢有視覺障礙的訪客後，修改了語音導覽。","本義不可譯成原稿的無能；指身體或心智功能方面的障礙。https://dictionary.cambridge.org/dictionary/english/disability"]],"l6-0301":[["動詞：使失去功能","put out of action","The collision disabled the truck's steering system, leaving it stranded beside the road.","碰撞使卡車的轉向系統失靈，車輛被困在路邊。",""]],"l6-0302":[["動詞：不贊成","object / frown on","Several residents disapproved of the plan to replace the playground with parking spaces.","幾位居民不贊成把遊樂場改成停車位的計畫。","disapprove of；object to；frown on，搭配介系詞不同。"]],"l6-0303":[["形容詞：造成災難的","catastrophic / devastating","The disastrous flood destroyed stored grain and left the village without food supplies.","那場災難性的洪水毀掉了儲糧，讓村莊失去食物供應。",""]],"l6-0304":[["動詞：排放","release / emit","The factory must treat its wastewater before discharging it into the river.","工廠必須先處理廢水，才能排入河流。",""]],"l6-0305":[["形容詞：紀律處分的","無直接同義詞","The school reviewed its disciplinary procedures after parents raised concerns about unfair treatment.","家長對不公平待遇提出疑慮後，學校檢討了懲處程序。",""]],"l6-0306":[["動詞：透露","reveal / divulge","The company refused to disclose the names of investors involved in the purchase.","公司拒絕透露參與收購的投資人姓名。",""]],"l6-0307":[["名詞：揭露","revelation","The disclosure of hidden fees prompted customers to demand refunds from the travel agency.","隱藏費用被揭露後，顧客要求旅行社退款。",""]],"l6-0308":[["名詞：不適","unease / soreness","The narrow seats caused considerable discomfort during the six-hour journey through the mountains.","六小時的山區旅程中，狹窄座椅讓人相當不舒服。",""]],"l6-0309":[["形容詞：謹慎低調的","tactful / unobtrusive","The receptionist made a discreet phone call rather than discussing the guest's problem publicly.","接待員低調地打了一通電話，沒有公開談論房客的問題。",""]],"l6-0310":[["名詞：辨別","distinction / discernment","The listening task requires careful discrimination between sounds that many beginners find almost identical.","這項聽力任務要求仔細辨別許多初學者覺得幾乎相同的聲音。","本句為辨別義；discrimination 另有歧視義。"]],"l6-0311":[["名詞：恥辱","shame / dishonor","The athlete regarded the cheating scandal as a disgrace to the entire team.","那位運動員認為作弊醜聞是全隊的恥辱。",""]],"l6-0312":[["形容詞：可恥的","shameful / dishonorable","The report described the deliberate neglect of vulnerable residents as disgraceful conduct.","報告把故意漠視弱勢住民的行為形容為可恥。",""]],"l6-0313":[["動詞：拆卸","take apart / disassemble","Workers dismantled the old playground equipment before installing the safer replacement structures.","工人先拆除舊遊樂器材，再安裝更安全的替代設施。",""]],"l6-0314":[["名詞：沮喪；驚愕","distress / consternation","To her dismay, the carefully restored photographs had been damaged by a leaking pipe.","令她沮喪的是，仔細修復的照片被漏水的水管弄壞了。",""]],"l6-0315":[["動詞：派遣","send / deploy","The rescue center dispatched two boats after receiving a call from the stranded fishermen.","救援中心接到受困漁民的求救後，派出了兩艘船。",""]],"l6-0316":[["形容詞：非必要的","unnecessary / nonessential","The editor removed dispensable details so readers could follow the main argument more easily.","編輯刪去非必要細節，讓讀者更容易理解主要論點。",""]],"l6-0317":[["動詞：驅散","scatter / break up","A sudden shower dispersed the crowd waiting outside the open-air theater.","一場驟雨驅散了在露天劇場外等候的人群。",""]],"l6-0318":[["動詞：迫使遷離","uproot / force out","The reservoir project displaced several families whose homes stood in the proposed flood zone.","水庫計畫迫使預定淹水區內的幾戶家庭遷離住家。",""]],"l6-0319":[["動詞：使不悅","annoy / upset","The decision to shorten opening hours displeased residents who could visit only after work.","縮短開放時間的決定，讓只能下班後到訪的居民不滿。",""]],"l6-0320":[["形容詞：用完即丟的","single-use / throwaway","The café replaced disposable cups with reusable ones for customers drinking inside.","咖啡館為內用顧客改用可重複使用的杯子，取代免洗杯。",""]],"l6-0321":[["名詞：廢棄物處理","discarding","The laboratory has separate procedures for the disposal of broken glass and chemical waste.","實驗室對碎玻璃和化學廢棄物訂有不同的處理程序。",""]],"l6-0322":[["動詞：忽視","ignore / pay no attention to","The contractor disregarded repeated warnings about the unstable wall beside the work area.","承包商無視一再提出的警告，沒有理會工作區旁那面不穩的牆。",""]],"l6-0323":[["名詞：異議人士","dissenter","The documentary follows a dissident who continued publishing essays despite government pressure.","紀錄片追蹤一位在政府壓力下仍持續發表文章的異議人士。",""]],"l6-0324":[["動詞：溶解","go into solution","Stir the sugar gently until it dissolves completely in the warm water.","輕輕攪拌糖，直到它完全溶解在溫水裡。","溶解不同於 melt 融化；原稿分解未精確呈現本義。"]],"l6-0325":[["動詞：勸阻","discourage / talk out of","Her friends dissuaded her from driving home while she was exhausted.","她的朋友勸她不要在精疲力盡時開車回家。","dissuade someone from doing；talk someone out of doing。"]],"l6-0326":[["動詞：使變形","warp / deform","The curved mirror distorted our reflections, making our faces look unusually long.","曲面鏡讓我們的倒影變形，臉看起來異常長。",""]],"l6-0327":[["動詞：使分心","divert / sidetrack","Repeated phone notifications distracted her from checking the figures in the report.","不停跳出的手機通知讓她無法專心核對報告數據。",""]],"l6-0328":[["名詞：分心事物","interruption / diversion","She moved to a quiet room to work without the distraction of nearby conversations.","她換到安靜房間工作，避免附近談話聲讓她分心。",""]],"l6-0329":[["動詞：不信任","mistrust","Residents began to distrust the company's assurances after several earlier promises were broken.","公司幾次失信後，居民開始不相信它的保證。",""]],"l6-0330":[["名詞：干擾","disruption / interruption","The library scheduled repairs early in the morning to minimize disturbance to visitors.","圖書館把維修排在清晨，盡量減少對訪客的干擾。",""]],"l6-0331":[["形容詞：多元的","varied","The exhibition brings together artists from diverse cultural and professional backgrounds.","展覽集結了文化和專業背景多元的藝術家。",""]],"l6-0332":[["動詞：使多樣化","broaden / vary","The farm diversified its crops to avoid depending entirely on the success of one harvest.","農場改種多種作物，避免完全依賴單一作物的收成。",""]],"l6-0333":[["名詞：消遣","entertainment / recreation","The evening concerts provided a welcome diversion during the demanding two-week training course.","在辛苦的兩週訓練期間，晚間音樂會提供了令人愉快的消遣。",""]],"l6-0334":[["名詞：多樣性","variety","Planting native flowers increased the diversity of insects observed in the school garden.","種植原生花卉後，學校花園裡觀察到的昆蟲種類增加了。",""]],"l6-0335":[["動詞：改道","reroute / redirect","Police diverted traffic away from the flooded tunnel and toward the higher bridge.","警方把車流從淹水隧道改道至較高的橋梁。",""]],"l6-0336":[["名詞：信條；教義","teaching / tenet","The historian compared the movement's original doctrine with the views of its later followers.","歷史學家比較了這場運動最初的信條與後來追隨者的觀點。",""]],"l6-0337":[["名詞：紀錄片","documentary film","The documentary follows local fishermen as they adapt to changes in the coastal environment.","紀錄片追蹤當地漁民如何適應沿海環境變化。",""]],"l6-0338":[["名詞：圓頂","cupola","Light entered through small windows around the base of the cathedral's dome.","光線穿過教堂圓頂底部四周的小窗照進室內。","cupola 常指屋頂上的較小圓頂結構。"]],"l6-0339":[["動詞：捐贈","give / contribute","The company donated unused desks to a community center that lacked office furniture.","公司把閒置書桌捐給缺乏辦公家具的活動中心。",""]],"l6-0340":[["名詞：捐贈","contribution / gift","A generous donation enabled the school to replace its damaged musical instruments.","一筆慷慨捐款讓學校得以更換損壞的樂器。",""]],"l6-0341":[["名詞：捐助者","contributor / benefactor","The donor requested that the money be used specifically for accessible playground equipment.","捐助者要求這筆錢專門用於無障礙遊樂器材。",""]],"l6-0342":[["名詞：毀滅","ruin / downfall","The loss of its only customer spelled doom for the small manufacturing company.","失去唯一客戶，意味著那家小製造公司的滅亡。",""]],"l6-0343":[["名詞：用藥劑量","dose","The pharmacist checked the prescribed dosage before explaining the label to the patient.","藥師先核對處方劑量，再向病人解釋標籤。","dosage 可涵蓋劑量及頻率；dose 常指單次用量。"]],"l6-0344":[["形容詞：大幅的","radical / severe","The drought forced the town to make drastic reductions in outdoor water use.","乾旱迫使鎮上大幅減少戶外用水。",""]],"l6-0345":[["名詞：缺點","disadvantage / downside","The apartment's main drawback is the noise from trains passing throughout the night.","這間公寓的主要缺點，是整晚火車經過所產生的噪音。",""]],"l6-0346":[["形容詞：陰沉乏味的","gloomy / dismal","Bright paintings transformed the dreary waiting room into a much more welcoming space.","色彩明亮的畫作，把陰沉的候診室變成更親切的空間。",""]],"l6-0347":[["名詞：毛毛雨","light rain","A persistent drizzle dampened our clothes without stopping the outdoor concert.","持續的毛毛雨打濕了衣服，卻沒有讓戶外音樂會中止。",""]],"l6-0348":[["名詞：乾旱","dry spell","The prolonged drought lowered the reservoir and forced farmers to reduce planting.","長期乾旱使水庫水位下降，迫使農民減少種植。","dry spell 可指較短的無雨時段；drought 通常較長且影響用水。"]],"l6-0349":[["形容詞：雙重的","double / twofold","The room serves a dual purpose as a library and a meeting space.","這個房間兼具圖書室和會議空間的雙重用途。",""]],"l6-0350":[["形容詞：半信半疑的","skeptical / doubtful","She was dubious about the promise of free repairs and asked for written confirmation.","她對免費維修的承諾半信半疑，因此要求書面確認。",""]],"l6-0351":[["名詞：黃色炸藥","無直接同義詞","The old quarry records mention dynamite, but the museum displays only empty storage boxes.","舊採石場紀錄提到炸藥，博物館展示的則只有空儲存箱。","dynamite 是特定種類的炸藥，不等於所有 explosives。"]],"l6-0352":[["動詞：退潮","recede / retreat","As the tide ebbed, a narrow strip of sand appeared between the rocks.","潮水退去時，岩石間露出了一條窄沙地。",""]],"l6-0353":[["形容詞：古怪的","unconventional / quirky","The eccentric inventor kept bicycle parts in the kitchen and cooked in the workshop.","那位古怪的發明家把自行車零件放在廚房，還在工作室煮飯。",""]],"l6-0354":[["名詞：生態學","無直接同義詞","Her ecology course examines relationships between river plants, insects, and the fish that eat them.","她的生態學課程探討河川植物、昆蟲和以昆蟲為食的魚之間的關係。",""]],"l6-0355":[["名詞：狂喜","rapture / bliss","The crowd erupted in ecstasy when the home team scored in the final seconds.","主隊在最後幾秒得分時，觀眾陷入狂喜。",""]],"l6-0356":[["形容詞：可食用的","eatable","The guide warned us that attractive berries are not necessarily edible.","嚮導提醒我們，漂亮的莓果不一定能吃。",""]],"l6-0357":[["名詞：社論","leader / opinion piece","The newspaper's editorial urged the council to consult residents before closing the market.","報紙社論敦促議會，在關閉市場前先諮詢居民。","leader 是英式報刊用語；opinion piece 不一定代表報社立場。"]],"l6-0358":[["名詞：電子","無直接同義詞","The diagram uses arrows to show the movement of electrons through the circuit.","圖解用箭頭表示電子在電路中的移動。",""]],"l6-0359":[["形容詞：符合資格的","qualified / entitled","Students who complete the training are eligible to apply for the summer placement.","完成訓練的學生有資格申請暑期實習。",""]],"l6-0360":[["名詞：菁英階層","upper echelon","The reforms challenged an elite that had controlled access to education for generations.","改革挑戰了長久掌控教育機會的菁英階層。",""]],"l6-0361":[["名詞：雄辯；口才","articulacy / fluency","Her eloquence helped the audience understand why the threatened wetland mattered to the community.","她出色的口才幫助聽眾理解，受威脅的濕地為何對社區重要。",""]],"l6-0362":[["形容詞：有說服力的","articulate / persuasive","The student gave an eloquent defense of the library's importance to rural families.","那位學生有力地說明圖書館對偏鄉家庭的重要性。",""]],"l6-0363":[["動詞：著手","begin / start","The museum embarked on a restoration project after securing enough funding for specialist workers.","博物館籌足聘請專業人員的經費後，展開了修復計畫。","embark on a project，著手進行計畫。"]],"l6-0364":[["名詞：移出原居國的人","無直接同義詞","The emigrant wrote regularly to relatives who remained in the village she had left.","那位移民定期寫信給仍留在她離開的村莊裡的親人。","emigrant 強調移出；immigrant 強調移入，觀看角度不同。"]],"l6-0365":[["動詞：移居國外","move abroad","Her grandparents emigrated from Italy and eventually opened a bakery in their new country.","她的祖父母從義大利移居國外，後來在新國家開了麵包店。",""]],"l6-0366":[["名詞：移居國外","outward migration","The study examines how emigration affected families remaining in the small coastal town.","研究探討移居國外如何影響仍留在小海港城鎮的家庭。",""]],"l6-0367":[["形容詞：強烈明確的","firm / forceful","The manager gave an emphatic refusal when asked to ignore the safety inspection.","有人要求經理忽略安全檢查時，他明確而強烈地拒絕了。",""]],"l6-0368":[["動詞：制定法律","pass","The council enacted new rules to protect trees during construction work.","議會制定新規定，保護施工期間的樹木。",""]],"l6-0369":[["名詞：法律制定","passage / adoption","The enactment of the new law followed months of debate and public consultation.","新法律經過數月辯論和公眾諮詢後才制定。",""]],"l6-0370":[["名詞：圍起的場地","pen / compound","The rescued animals rested in a spacious enclosure away from the busiest visitor paths.","獲救的動物在寬敞的圍欄區休息，遠離最繁忙的遊客步道。",""]],"l6-0371":[["名詞：百科全書","encyclopaedia","The old encyclopedia helped us identify the tools shown in the historical photograph.","那本老百科全書幫我們辨認歷史照片中的工具。","encyclopaedia 為常見英式拼法。"]],"l6-0372":[["名詞：耐力","stamina / staying power","The long climb tested the hikers' endurance more than their technical climbing skills.","漫長攀登考驗的更多是登山客的耐力，而不是攀登技巧。",""]],"l6-0373":[["動詞：提升","improve / strengthen","Better lighting enhanced the exhibition without changing the arrangement of the artwork.","改善照明提升了展覽效果，無須改動作品的擺設。",""]],"l6-0374":[["名詞：改善；提升","improvement","The software update provides a significant enhancement to the readability of small text.","軟體更新大幅改善了小字的易讀性。",""]],"l6-0375":[["動詞：使明白","inform / educate","The engineer enlightened us about why the old bridge needed such extensive repairs.","工程師讓我們明白，老橋為何需要如此大規模的維修。",""]],"l6-0376":[["名詞：啟發；理解","understanding / insight","The visitor center aims to provide enlightenment about the river's cultural and ecological importance.","遊客中心希望增進大家對河流文化及生態重要性的理解。",""]],"l6-0377":[["動詞：使豐富","deepen / enhance","Conversations with local residents enriched her understanding of the neighborhood's history.","與當地居民交談，豐富了她對社區歷史的理解。",""]],"l6-0378":[["名詞：充實；豐富","enhancement","The school views music and drama as essential forms of educational enrichment.","學校認為音樂和戲劇是充實教育不可或缺的方式。",""]],"l6-0379":[["名詞：流行疫情","outbreak","The epidemic disrupted daily life as schools and businesses adjusted their schedules.","疫情打亂日常生活，學校和商家都調整了時間安排。","outbreak 可指初期或較小範圍爆發；epidemic 強調病例大量增加。"]],"l6-0380":[["名詞：影集的一集","installment","The final episode answers the question that has troubled viewers throughout the series.","最後一集解答了整部影集中一直困擾觀眾的問題。",""]],"l6-0381":[["名詞片語：情緒商數","emotional quotient","The workshop discussed EQ through examples of handling frustration and listening to colleagues.","工作坊用處理挫折和傾聽同事的例子，討論情緒商數。","EQ 常展開為 emotional quotient，表示情緒智力的衡量。https://dictionary.cambridge.org/dictionary/english/eq"]],"l6-0382":[["名詞片語：情緒智力","無直接同義詞","Her emotional intelligence helped her recognize tension and respond thoughtfully during difficult meetings.","她的情緒智力讓她能察覺緊張情緒，在困難會議中審慎回應。",""]],"l6-0383":[["名詞：方程式","無直接同義詞","The students solved the equation and checked their answer by substituting it back in.","學生解出方程式後，把答案代回去檢查。",""]],"l6-0384":[["形容詞：等值的","equal","The two packages contain equivalent amounts of coffee despite their different shapes.","兩種包裝雖然形狀不同，裝的咖啡量卻相等。",""]],"l6-0385":[["動詞：侵蝕","wear away","Years of heavy rain eroded the hillside and exposed the roots of several trees.","多年的豪雨侵蝕山坡，使幾棵樹的根部外露。",""]],"l6-0386":[["名詞：火山噴發","無直接同義詞","The volcanic eruption covered nearby fields with ash and forced residents to leave.","火山噴發使附近田地覆滿灰燼，迫使居民離開。",""]],"l6-0387":[["動詞：加劇","intensify / heighten","Repeated threats escalated the dispute and made a peaceful agreement harder to reach.","一再的威脅加劇了爭端，讓和平協議更難達成。",""]],"l6-0388":[["名詞：本質","core / heart","The short film captures the essence of a community built around the fishing harbor.","這部短片捕捉了以漁港為中心的社區本質。",""]],"l6-0389":[["名詞：極漫長的時間","an age","Waiting outside the operating room felt like an eternity to the anxious family.","對焦急的家人而言，在手術室外等待彷彿過了無止盡的時間。","本句為誇飾久等的用法；eternity 的字面義為永恆。"]],"l6-0390":[["形容詞：倫理方面的","moral","The committee considered the ethical implications of using personal data without clear consent.","委員會考慮了未取得明確同意就使用個人資料的倫理問題。",""]],"l6-0391":[["形容詞：族群的","ethnocultural","The festival brings together residents from diverse ethnic backgrounds to share food and music.","節慶讓不同族群背景的居民聚在一起，分享飲食和音樂。","ethnic 包含文化、語言等共同背景，不只指生物性的種族概念。"]],"l6-0392":[["動詞：疏散","remove to safety","Officials evacuated the residents before floodwater reached the lowest streets in the town.","洪水到達鎮上地勢最低的街道前，官員已疏散居民。",""]],"l6-0393":[["名詞：演變","development","The exhibition traces the evolution of local pottery designs over several centuries.","展覽追溯當地陶器設計數百年來的演變。",""]],"l6-0394":[["動詞：逐漸發展出","develop / devise","Over several trials, the team evolved a simpler method for filtering the water.","經過幾次試驗，團隊逐步發展出更簡單的濾水方法。","本句採及物 evolve，意為逐漸發展；也常作不及物動詞。https://dictionary.cambridge.org/dictionary/english/evolve"]],"l6-0395":[["名詞：摘錄","extract / passage","The teacher read an excerpt from the diary to introduce the historical period.","老師朗讀了一段日記摘錄，介紹那個歷史時期。",""]],"l6-0396":[["形容詞：過度的","undue / unreasonable","Excessive noise from the construction site made it difficult for students to concentrate.","工地過大的噪音讓學生難以專心。",""]],"l6-0397":[["形容詞：專屬的","sole / restricted","The contract gives the publisher exclusive rights to distribute the book in that country.","合約給予出版社在該國發行這本書的獨家權利。",""]],"l6-0398":[["名詞：執行","implementation / carrying out","Careful execution of the evacuation plan kept the crowd moving without confusion.","謹慎執行疏散計畫，讓人群持續前進而沒有混亂。",""]],"l6-0399":[["動詞：施加","apply","The heavy shelves exert considerable pressure on the old wooden floor.","沉重的書架對老木地板施加了相當大的壓力。",""]],"l6-0400":[["形容詞：外來而不常見的","nonnative / foreign","The greenhouse contains exotic orchids that cannot survive the region's cold winters outdoors.","溫室裡種著外來蘭花，無法在當地寒冬於戶外存活。",""]],"l6-0401":[["名詞：探險旅程","exploratory journey","The expedition into the remote valleys required months of preparation and specialized climbing equipment.","這趟深入偏遠山谷的探險，需要數月準備和專門的攀登裝備。",""]],"l6-0402":[["動詞：開除","dismiss / throw out","The association expelled the member after confirming that he had falsified financial records.","協會確認那名會員偽造財務紀錄後，將他除名。",""]],"l6-0403":[["名詞：專業知識","specialist knowledge / proficiency","The restoration requires expertise in repairing glass made with traditional techniques.","這項修復需要具備修復傳統工法玻璃的專業知識。",""]],"l6-0404":[["名詞：到期","expiry","Please submit your renewal application before the expiration of your current membership.","請在目前會籍到期前提出續會申請。",""]],"l6-0405":[["動詞：到期","lapse / run out","The temporary permit expires next month, so the organizers must apply for an extension.","臨時許可下個月到期，因此主辦單位必須申請展延。",""]],"l6-0406":[["形容詞：清楚明確的","clear / unambiguous","The instructions give explicit warnings about which parts should not be removed.","說明明確警告哪些零件不應拆除。",""]],"l6-0407":[["名詞：英勇事蹟","feat / achievement","The sailor described his exploits during a dangerous rescue in the northern seas.","水手敘述了自己在北方海域一次危險救援中的英勇事蹟。","名詞 exploit 重音在第一音節，與剝削的動詞不同。"]],"l6-0408":[["名詞：探索","investigation","The students' exploration of local archives uncovered photographs missing from the town's official history.","學生對地方檔案的探索，找到了鎮上官方歷史未收錄的照片。",""]],"l6-0409":[["形容詞：精美的","delicate / finely crafted","The museum displayed an exquisite necklace made from tiny pieces of colored glass.","博物館展示了一條用小片彩色玻璃製成的精美項鍊。",""]],"l6-0410":[["動詞：提取","remove / draw out","The laboratory extracted oil from the seeds to compare the yields of different varieties.","實驗室從種子提取油，比較不同品種的產量。",""]],"l6-0411":[["形容詞：課外的","無直接同義詞","The school offers extracurricular activities ranging from robotics to traditional music.","學校提供從機器人到傳統音樂等各式課外活動。","extracurricular 指正式課程以外，不限定在放學後舉行。"]],"l6-0412":[["名詞：視力","vision / sight","Her eyesight had weakened, so she requested documents printed in larger letters.","她的視力減弱了，因此要求提供字體較大的文件。",""]],"l6-0413":[["形容詞：極好的","wonderful / marvelous","The rooftop offered fabulous views of the harbor and the mountains beyond it.","屋頂可以欣賞港口及後方群山的絕佳景色。",""]],"l6-0414":[["動詞：促進；使便利","ease / assist","The online form facilitates registration by allowing applicants to upload their documents directly.","線上表格讓申請人直接上傳文件，使報名更方便。",""]],"l6-0415":[["名詞：派系","clique / bloc","A small faction within the committee opposed the agreement and requested another vote.","委員會內一個小派系反對協議，要求重新表決。",""]],"l6-0416":[["名詞：全體教師","teaching staff","The faculty met to discuss how the new timetable would affect laboratory courses.","全體教師開會，討論新課表對實驗課程的影響。","faculty 此義常見於美式大學，不一定包含行政職員。"]],"l6-0417":[["名詞：熟悉","acquaintance / knowledge","Her familiarity with the neighborhood helped the delivery team avoid streets closed for repairs.","她熟悉社區，幫助送貨團隊避開封閉維修的街道。",""]],"l6-0418":[["名詞：饑荒","widespread starvation","The prolonged crop failure led to famine across several isolated farming communities.","長期歉收使幾個偏遠農業社區陷入饑荒。",""]],"l6-0419":[["名詞：迷戀；強烈興趣","absorption / captivation","Her fascination with insects began when she watched caterpillars transform into butterflies.","她觀察毛毛蟲變成蝴蝶後，開始對昆蟲產生強烈興趣。",""]],"l6-0420":[["形容詞：可行的","practical / workable","The engineer confirmed that repairing the bridge was technically feasible within the available budget.","工程師確認，在現有預算內修橋，技術上是可行的。",""]],"l6-0421":[["名詞：聯邦","federal union","The constitution gives the federation certain powers while reserving others for its member states.","憲法授予聯邦部分權力，其他權力則保留給各成員邦。","federation 指聯邦或聯盟本身，不單指原稿所列的聯邦政府。https://dictionary.cambridge.org/dictionary/english/federation"]],"l6-0422":[["名詞：回饋","comments / response","The designers revised the prototype after receiving detailed feedback from wheelchair users.","設計師收到輪椅使用者的詳細回饋後，修改了原型。",""]],"l6-0423":[["名詞：土壤肥力","richness / productivity","Adding compost gradually improved the fertility of the soil in the school garden.","添加堆肥逐漸改善了學校花園的土壤肥力。",""]],"l6-0424":[["名詞：忠誠","loyalty / faithfulness","The letter expressed his fidelity to the principles that had guided their organization.","信中表達了他對一向指引該組織的原則的忠誠。",""]],"l6-0425":[["形容詞：有限的","limited / bounded","Because storage space is finite, the archive cannot accept every object offered to it.","儲存空間有限，因此檔案館無法接受所有捐贈物品。",""]],"l6-0426":[["形容詞：防火的","fire-resistant","The valuable records were kept in a fireproof cabinet inside the main office.","重要紀錄存放在主要辦公室內的防火櫃中。","fire-resistant 指耐火，不保證在所有條件下完全不受火害。"]],"l6-0427":[["動詞：突然旺盛燃燒","blaze up","The campfire flared when a gust of wind reached the dry wood.","一陣風吹到乾木柴，營火突然旺了起來。",""]],"l6-0428":[["名詞：船隊","flotilla","The fishing fleet returned early after receiving warnings of worsening weather offshore.","收到外海天氣惡化的警告後，漁船隊提早返回。","flotilla 通常指小型船隊。"]],"l6-0429":[["動詞：忽明忽暗","flutter / waver","The candle flame flickered whenever someone opened the door to the cold hallway.","每當有人打開通往寒冷走廊的門，燭火就搖曳不定。",""]],"l6-0430":[["動詞：用力扔","hurl / throw","He flung the wet blanket over the railing before rushing back inside.","他把濕毛毯用力甩過欄杆，隨即衝回屋內。",""]],"l6-0431":[["名詞：液體","liquid","The technician checked the color of the fluid leaking from beneath the machine.","技師檢查了從機器下方漏出液體的顏色。","fluid 在科學上也包括氣體，本句為液體。"]],"l6-0432":[["動詞：飄動","flap / wave","Colorful ribbons fluttered above the courtyard as guests arrived for the celebration.","賓客抵達慶典時，彩色緞帶在庭院上方飄揚。",""]],"l6-0433":[["動詞：預見","anticipate / predict","The planners failed to foresee how quickly the new station would increase local traffic.","規劃者未能預見新車站會如此迅速增加當地車流。",""]],"l6-0434":[["形容詞：難以克服的","daunting / challenging","Repairing the remote bridge presented a formidable challenge for the small construction team.","對小型施工團隊而言，修復偏遠橋梁是一項艱鉅挑戰。",""]],"l6-0435":[["動詞：制定","devise / develop","The committee formulated a plan to keep the clinic open during the renovations.","委員會制定了讓診所在整修期間持續營運的計畫。","本例是制定的常見義，不侷限於原稿的使公式化。"]],"l6-0436":[["動詞：背棄","abandon / renounce","She refused to forsake her principles even when accepting the deal would have been profitable.","即使接受交易有利可圖，她仍不肯背棄原則。",""]],"l6-0437":[["形容詞：即將到來的","upcoming / approaching","The museum announced that its forthcoming exhibition would feature letters from local soldiers.","博物館宣布，即將舉辦的展覽將展出當地士兵的信件。",""]],"l6-0438":[["動詞：加固","strengthen / reinforce","Workers fortified the riverbank with additional supports before the rainy season began.","雨季開始前，工人增加支撐結構，加固河岸。",""]],"l6-0439":[["動詞：暫時寄養照顧","care for temporarily","The family fostered two children while social workers arranged longer-term care.","在社工安排長期照顧期間，這家人暫時寄養了兩名孩子。","foster care 通常是寄養，不等於正式收養 adopt。"]],"l6-0440":[["名詞：骨折","break","The X-ray revealed a small fracture that had not been obvious during the initial examination.","X 光顯示了一處初次檢查時不明顯的小骨折。",""]],"l6-0441":[["形容詞：易碎的","delicate / breakable","The fragile glass ornaments were wrapped separately before being placed in the box.","易碎的玻璃飾品先逐一包好，再放進箱子。",""]],"l6-0442":[["名詞：碎片","piece / shard","A fragment of painted pottery helped the archaeologists estimate the age of the settlement.","一片彩陶碎片幫助考古學家推估聚落年代。",""]],"l6-0443":[["形容詞：虛弱的","weak / feeble","The frail patient needed assistance walking from her bed to the nearby chair.","那位虛弱的病人需要協助，才能從床邊走到附近的椅子。",""]],"l6-0444":[["名詞：詐騙","deception / swindling","The accountant discovered evidence of fraud while checking invoices from an unfamiliar supplier.","會計師核對一家陌生供應商的請款單時，發現了詐騙證據。",""]],"l6-0445":[["名詞：異常事物","anomaly / oddity","The giant carrot was a freak of nature that surprised even experienced gardeners.","那根巨大紅蘿蔔是個自然界的異常產物，連有經驗的園丁都驚訝。","freak 用來稱呼人通常帶侮辱性，原稿的人身描述不宜當中性稱呼。https://dictionary.cambridge.org/dictionary/english/freak"]],"l6-0446":[["動詞：苦惱","worry / agonize","She fretted about the missing documents until a colleague found them in another folder.","她一直為遺失的文件苦惱，直到同事在另一個資料夾裡找到它們。",""]],"l6-0447":[["名詞：摩擦力","無直接同義詞","The rough surface increases friction and helps prevent the ladder from sliding.","粗糙表面增加摩擦力，有助於防止梯子滑動。",""]],"l6-0448":[["名詞：星系","無直接同義詞","The observatory recorded light from a distant galaxy using its newly installed telescope.","天文臺用新裝設的望遠鏡記錄來自遙遠星系的光。","galaxy 泛指星系；我們所在的銀河系為 the Milky Way。https://www.merriam-webster.com/dictionary/galaxy"]],"l6-0449":[["動詞：概括推論","draw general conclusions","We should not generalize from one interview without considering the experiences of other residents.","我們不應只憑一次訪談就概括推論，而不考慮其他居民的經驗。",""]],"l6-0450":[["動詞：產生","produce / create","The new exhibition generated considerable interest among teachers planning local history lessons.","新展覽引起了正在規劃地方史課程的老師們的濃厚興趣。",""]],"l6-0451":[["名詞：發電機","無直接同義詞","A backup generator supplied electricity to the clinic while workers repaired the damaged power lines.","工人修理受損電線期間，備用發電機供電給診所。",""]],"l6-0452":[["形容詞：基因的","無直接同義詞","The laboratory compared genetic information from several plant varieties collected in the valley.","實驗室比較了山谷採集的幾種植物的基因資訊。","genetic 指基因或遺傳方面；genomic 則著重基因組層次。"]],"l6-0453":[["名詞：遺傳學","無直接同義詞","Her interest in genetics grew while she studied inherited traits in flowering plants.","她研究開花植物的遺傳特徵時，對遺傳學的興趣逐漸增加。","genetics 作學科名稱時通常搭配單數動詞。"]],"l6-0454":[["名詞：迷人魅力","allure / charm","The photographs capture the glamour of the theater before its years of neglect.","照片捕捉了劇院多年荒廢之前的迷人風采。",""]],"l6-0455":[["名詞：玻璃器皿","無直接同義詞","The laboratory stored clean glassware in a separate cabinet to prevent contamination.","實驗室把乾淨玻璃器皿放在獨立櫃內，避免污染。",""]],"l6-0456":[["動詞：閃亮","gleam / sparkle","Drops of rain glistened on the leaves as sunlight returned to the garden.","陽光重新照進花園時，葉上的雨滴閃閃發亮。",""]],"l6-0457":[["形容詞：陰暗的","dim / dark","Opening the curtains transformed the gloomy room without changing any of the furniture.","拉開窗簾後，陰暗的房間頓時明亮起來，家具完全不用更動。",""]],"l6-0458":[["名詞：基因改造生物","genetically modified organism","The article explains how researchers developed the GMO and what characteristics they intended to change.","文章說明研究人員如何開發這個基因改造生物，以及想改變哪些特徵。",""]],"l6-0459":[["名詞：統計圖","chart","The graph shows how water consumption changed before and after the repairs.","圖表顯示維修前後的用水量如何變化。",""]],"l6-0460":[["形容詞：圖像的","visual / diagrammatic","The report includes a graphic representation of traffic flow around the new station.","報告以圖像呈現新車站周邊的車流。",""]],"l6-0461":[["名詞：烤架","barbecue grill","The cook placed the vegetables on the grill while preparing the sauce.","廚師一邊準備醬汁，一邊把蔬菜放上烤架。",""]],"l6-0462":[["名詞：食品雜貨商","grocery retailer","The neighborhood grocer began delivering essentials to residents who could not leave their homes.","社區雜貨商開始為無法出門的居民配送必需品。",""]],"l6-0463":[["動詞：摸索","feel around / fumble","In the dark hallway, she groped for the light switch beside the door.","在黑暗走廊裡，她摸索著找門旁的電燈開關。",""]],"l6-0464":[["名詞：游擊隊員","irregular fighter","The memoir describes a guerrilla carrying messages between camps hidden in the forest.","回憶錄描寫一名游擊隊員，在森林裡的隱密營地之間傳遞消息。","游擊戰是 guerrilla warfare，guerrilla 在本句指人。"]],"l6-0465":[["名詞：棲地","natural environment","The drainage project threatened a wetland habitat used by several species of migratory birds.","排水工程威脅了幾種候鳥使用的濕地棲地。",""]],"l6-0466":[["動詞：劈砍","chop / cut roughly","The workers hacked through fallen branches to clear a route for the rescue vehicle.","工人劈開倒落的樹枝，為救援車輛清出通道。",""]],"l6-0467":[["名詞：受委託測試安全的駭客","penetration tester","The company hired a hacker to test its defenses under a clearly defined agreement.","公司依照明確協議，聘請駭客測試防禦能力。","本句為經授權的安全測試情境；hacker 不必然是犯罪者。"]],"l6-0468":[["名詞：冰雹","無直接同義詞","Large pieces of hail damaged the greenhouse roof during the sudden afternoon storm.","突如其來的午後暴風雨帶來大冰雹，損壞了溫室屋頂。",""]],"l6-0469":[["動詞：騷擾","subject to repeated mistreatment","The supervisor repeatedly harassed employees who questioned the accuracy of their overtime payments.","主管一再騷擾質疑加班費是否正確的員工。",""]],"l6-0470":[["名詞：騷擾","persistent mistreatment","The organization created a confidential process for reporting harassment without fear of retaliation.","組織建立了保密通報程序，讓人能安心檢舉騷擾，不怕報復。",""]],"l6-0471":[["名詞：危險源","danger / risk","The loose cable presented a serious hazard to visitors crossing the crowded hallway.","鬆散的電線對穿越擁擠走廊的訪客構成嚴重危險。",""]],"l6-0472":[["名詞：地球的半球","無直接同義詞","The map highlights bird migration routes connecting habitats in the northern and southern hemispheres.","地圖標示連接南北半球棲地的鳥類遷徙路線。",""]],"l6-0473":[["副詞：此後","from now on / subsequently","The agreement states that the organization will hereafter publish its financial records annually.","協議規定，組織此後將每年公布財務紀錄。",""]],"l6-0474":[["名詞：文化遺產","legacy / inheritance","Restoring the old fishing boats helped the town preserve its maritime heritage.","修復老漁船，幫助這個城鎮保存海洋文化遺產。",""]],"l6-0475":[["名詞：海洛因","無直接同義詞","The documentary examines how heroin addiction affected families in the former industrial district.","紀錄片探討海洛因成癮如何影響舊工業區的家庭。",""]],"l6-0476":[["動詞：凸顯","emphasize / draw attention to","The report highlights several weaknesses that must be addressed before the bridge reopens.","報告凸顯了橋梁重新開放前必須處理的幾項缺失。",""]],"l6-0477":[["形容詞：榮譽性的","無直接同義詞","The university awarded an honorary degree to a musician who had supported community education.","大學頒發榮譽學位給一位支持社區教育的音樂家。",""]],"l6-0478":[["名詞：荷爾蒙","無直接同義詞","The researchers measured how hormone levels changed during different stages of plant growth.","研究人員測量植物生長不同階段的荷爾蒙濃度變化。",""]],"l6-0479":[["形容詞：好客的","welcoming / friendly","The hospitable family offered the stranded travelers a warm meal and spare beds.","好客的家庭為受困旅客提供熱食和空床。",""]],"l6-0480":[["名詞：熱情款待","warm welcome / generosity to guests","We thanked our hosts for their hospitality before leaving the mountain village.","離開山村前，我們感謝主人熱情款待。",""]],"l6-0481":[["動詞：使住院","admit to hospital","The injured driver was hospitalized overnight while doctors monitored his condition.","受傷駕駛住院一晚，醫師觀察他的狀況。",""]],"l6-0482":[["名詞：敵意","antagonism / animosity","The mediator's calm questions gradually reduced the hostility between the two groups.","調解者冷靜的提問逐漸降低了兩組人之間的敵意。",""]],"l6-0483":[["形容詞：人道救援的","無直接同義詞","The charity sent humanitarian supplies to communities cut off by the landslides.","慈善團體把人道救援物資送往因山崩而對外隔絕的社區。",""]],"l6-0484":[["動詞：羞辱","demean / shame","Criticizing the trainee in front of customers served only to humiliate her.","當著顧客的面批評受訓員工，只讓她受到羞辱。",""]],"l6-0485":[["名詞：直覺","intuition / suspicion","On a hunch, the detective checked an old address mentioned in the missing person's notebook.","偵探憑直覺，查了失蹤者筆記本裡提到的一個舊地址。",""]],"l6-0486":[["名詞：障礙","obstacle / barrier","Obtaining permission to use the land was the final hurdle before construction could begin.","取得土地使用許可，是開工前的最後一道障礙。",""]],"l6-0487":[["名詞：衛生","cleanliness / sanitation","The inspection focused on food storage, kitchen hygiene, and the handling of waste.","檢查重點包括食物儲存、廚房衛生和廢棄物處理。",""]],"l6-0488":[["名詞：虛偽","insincerity / double standards","Residents accused the company of hypocrisy for promoting recycling while dumping waste illegally.","公司一面宣傳回收，一面非法傾倒廢棄物，居民指責它虛偽。",""]],"l6-0489":[["名詞：偽君子","無直接同義詞","He called the official a hypocrite for demanding honesty while concealing personal expenses.","官員一面要求誠實，一面隱瞞個人開支，他因此稱官員為偽君子。",""]],"l6-0490":[["形容詞：情緒失控的","panic-stricken / frantic","The caller sounded hysterical and struggled to give the emergency operator an address.","來電者聽起來情緒失控，很難向緊急服務接線員說出地址。",""]],"l6-0491":[["動詞：照亮","light up / brighten","Soft lamps illuminated the paintings without creating distracting reflections on the glass.","柔和燈光照亮了畫作，又不在玻璃上造成干擾視線的反光。",""]],"l6-0492":[["名詞：錯覺","false impression","The mirrors create the illusion that the small room extends far beyond its walls.","鏡子造成錯覺，讓小房間看似遠遠延伸到牆壁之外。",""]],"l6-0493":[["形容詞：具有免疫力的","insusceptible","The experiment examined why certain plants were immune to the fungal disease affecting neighboring crops.","實驗研究某些植物為何對侵襲鄰近作物的真菌病具有免疫力。",""]],"l6-0494":[["形容詞：必要的","essential / vital","It is imperative that the damaged wiring be repaired before the building reopens.","建築重新開放前，損壞的電線務必修好。",""]],"l6-0495":[["名詞：器具","tool / utensil","The exhibition includes farming implements once used to harvest rice by hand.","展覽包含過去手工收割稻米使用的農具。",""]],"l6-0496":[["名詞：暗示","suggestion / insinuation","She rejected the implication that her team had ignored the residents' concerns.","她駁斥了影射團隊忽視居民疑慮的說法。",""]],"l6-0497":[["形容詞：隱含的","implied / unspoken","Their decision to continue funding the project carried an implicit approval of its direction.","他們決定持續資助專案，隱含著對其方向的認可。",""]],"l6-0498":[["形容詞：宏偉的","impressive / grand","The imposing stone entrance made the modest buildings behind it seem surprisingly small.","宏偉的石造入口讓後方樸實的建築顯得出奇地小。",""]],"l6-0499":[["動詞：監禁","incarcerate / jail","The regime imprisoned writers who continued publishing criticism after independent newspapers were banned.","獨立報紙遭禁後，政權監禁了仍持續發表批評的作家。",""]],"l6-0500":[["名詞：監禁","incarceration / confinement","The memoir describes how years of imprisonment changed his relationship with his family.","回憶錄描寫多年監禁如何改變他與家人的關係。",""]],"l6-0501":[["名詞：誘因","inducement / motivation","The discount provided an incentive for customers to return their empty containers.","折扣成了促使顧客歸還空容器的誘因。",""]],"l6-0502":[["形容詞：附帶的","secondary / ancillary","The travel budget covers accommodation and incidental expenses such as local bus fares.","差旅預算包含住宿和當地公車費等附帶開支。",""]],"l6-0503":[["動詞：傾斜","slope / slant","The path inclines gently toward the river before reaching a wooden footbridge.","小徑朝河流方向緩緩傾斜，之後通往一座木造人行橋。",""]],"l6-0504":[["形容詞：包含在內的","無直接同義詞","The quoted price is inclusive of delivery, installation, and the first maintenance visit.","報價包含運送、安裝和第一次到府保養服務。","inclusive of 後接所包含的項目。"]],"l6-0505":[["名詞：憤慨","outrage / resentment","Residents expressed indignation when they learned that the playground had been sold without consultation.","居民得知遊樂場未經諮詢便遭出售，表達了憤慨。",""]],"l6-0506":[["形容詞：不可避免的","unavoidable / inescapable","Some disruption was inevitable while workers replaced the pipes beneath the busy street.","工人更換繁忙街道底下的管線時，難免造成一些干擾。",""]],"l6-0507":[["形容詞：具有傳染性的","communicable / contagious","The training explains how staff can reduce the spread of infectious diseases in crowded shelters.","訓練說明工作人員如何減少傳染病在擁擠收容所內傳播。",""]],"l6-0508":[["動詞：推論","deduce / conclude","From the muddy footprints, the caretaker inferred that someone had entered through the garden.","管理員根據泥腳印，推論有人從花園進來。","infer 是根據證據推論；原稿的意味著容易與 imply 混淆。https://dictionary.cambridge.org/us/grammar/british-grammar/imply-or-infer"]],"l6-0509":[["名詞：推論","deduction / conclusion","Her inference rested on several independent accounts rather than a single witness's memory.","她的推論依據數份彼此獨立的敘述，而非單一證人的記憶。",""]],"l6-0510":[["形容詞：巧妙的","clever / inventive","The carpenter devised an ingenious folding shelf that fits behind the kitchen door.","木匠設計了一個巧妙的折疊架，可以收在廚房門後。",""]],"l6-0511":[["名詞：巧思","inventiveness / resourcefulness","With limited materials, the students showed remarkable ingenuity in building a working water filter.","材料有限，學生仍發揮非凡巧思，做出能用的濾水器。",""]],"l6-0512":[["動詞：棲息於","live in / occupy","Several rare bird species inhabit the forest surrounding the abandoned mining village.","數種罕見鳥類棲息在廢棄礦村周圍的森林。",""]],"l6-0513":[["名詞：居民","resident / dweller","The island's inhabitants depend on the ferry for supplies and access to the mainland.","島上居民依靠渡輪取得物資，並往返本島。",""]],"l6-0514":[["形容詞：固有的","intrinsic / built-in","The review identified an inherent weakness in the design of the locking mechanism.","審查發現鎖定機構的設計存在固有缺陷。",""]],"l6-0515":[["名詞：主動性","resourcefulness / enterprise","She showed initiative by organizing the damaged records before anyone asked her to help.","還沒有人請她幫忙，她就主動整理受損紀錄，展現了主動性。","原稿欄位只標 adj，但也列名詞義；本例採常用名詞用法。https://dictionary.cambridge.org/dictionary/english/initiative"]],"l6-0516":[["動詞：注入","introduce / pump in","The technician injected colored dye into the pipe to locate the hidden leak.","技師把有色染料注入管線，以尋找隱藏的漏水處。",""]],"l6-0517":[["名詞：注射","shot","The nurse explained the procedure before giving the patient an injection in the upper arm.","護理師先說明程序，再為病人在上臂注射。","shot 是較口語的說法。"]],"l6-0518":[["名詞：不公正","unfairness / inequity","The workers challenged the injustice of paying different wages for exactly the same work.","工人質疑相同工作卻給不同工資的不公正現象。",""]],"l6-0519":[["名詞：創新","novel development / invention","The adjustable handle was an innovation that made the tool easier for children to use.","可調整握柄是一項創新，讓兒童更容易使用這件工具。",""]],"l6-0520":[["形容詞：創新的","inventive / original","The exhibition features innovative designs that turn discarded fabric into durable household products.","展覽呈現把廢棄布料轉為耐用家用品的創新設計。",""]],"l6-0521":[["名詞：調查","investigation / examination","An independent inquiry examined why the warning system failed during the flood.","一項獨立調查查明洪水期間警報系統失靈的原因。",""]],"l6-0522":[["名詞：深入理解","understanding / perception","Interviews with former residents offered valuable insight into daily life in the old neighborhood.","訪談昔日居民，讓人深入了解舊社區的日常生活。",""]],"l6-0523":[["名詞：堅持","persistence / determination","Her insistence on checking every measurement prevented an expensive mistake during construction.","她堅持核對每個尺寸，避免了施工時犯下代價高昂的錯誤。",""]],"l6-0524":[["名詞：安裝","fitting / setting up","The installation of the new heating system required closing the library for two days.","安裝新的暖氣系統，圖書館必須關閉兩天。",""]],"l6-0525":[["名詞：分期付款的一期款項","partial payment","The final installment is due after the furniture has been delivered and inspected.","家具送達並檢查後，就應支付最後一期款項。",""]],"l6-0526":[["名詞：機構","organization / establishment","The research institution shares its laboratory equipment with several nearby community colleges.","這所研究機構與附近幾所社區學院共用實驗室設備。",""]],"l6-0527":[["形容詞：完好無缺的","undamaged / unbroken","Despite the violent storm, the stained glass above the entrance remained intact.","儘管暴風雨猛烈，入口上方的彩色玻璃仍完好無缺。",""]],"l6-0528":[["動詞：整合","combine / incorporate","The software integrates information from several departments into one searchable database.","軟體把數個部門的資訊整合成一個可搜尋的資料庫。",""]],"l6-0529":[["名詞：整合","combination / incorporation","Successful integration of the two booking systems reduced errors at the reception desk.","兩套訂房系統成功整合，減少了櫃檯作業的錯誤。",""]],"l6-0530":[["名詞：正直","honesty / probity","The auditor's integrity earned the trust of employees who had questioned earlier reports.","稽核員的正直，贏得了曾質疑先前報告的員工信任。",""]],"l6-0531":[["名詞：智力","intelligence / mental ability","The chess coach admired her intellect and the patience she brought to difficult positions.","西洋棋教練欣賞她的才智，以及她面對困難棋局時的耐心。",""]],"l6-0532":[["名詞：道路交叉口","junction / crossroads","New traffic lights were installed at the intersection beside the elementary school.","國小旁的交叉路口裝設了新的交通號誌。","intersection 不限於四條道路構成的十字形路口。"]],"l6-0533":[["名詞：時間間隔","gap / period between events","The interval between trains becomes longer after the evening rush hour ends.","晚間尖峰時段結束後，列車班次間隔會拉長。",""]],"l6-0534":[["動詞：介入","step in / intercede","The manager intervened when the disagreement began to affect the team's work.","爭執開始影響團隊工作時，經理出面介入。",""]],"l6-0535":[["名詞：介入","involvement / intercession","The mediator's timely intervention helped both sides return to the negotiating table.","調解者及時介入，幫助雙方重回談判桌。",""]],"l6-0536":[["名詞：親密","closeness / familiarity","Their letters reveal an intimacy that rarely appeared in their formal public conversations.","他們的信件流露出正式公開談話中少見的親密。",""]],"l6-0537":[["動詞：恐嚇","threaten / bully","The landlord tried to intimidate tenants who requested repairs to the leaking roof.","房東企圖恐嚇要求修理漏水屋頂的房客。",""]],"l6-0538":[["動詞：打擾；闖入","interrupt","She knocked softly, unwilling to intrude on a conversation that seemed deeply personal.","她輕輕敲門，不願打擾一段似乎非常私人的談話。","intrude on 後接受干擾的活動；interrupt 可直接接受詞。"]],"l6-0539":[["名詞：擅闖者","trespasser / invader","The alarm alerted the guard to an intruder entering the warehouse through a side window.","警報提醒警衛，有人從側窗擅闖倉庫。",""]],"l6-0540":[["形容詞：極有價值的","priceless / extremely useful","The retired mechanic's advice proved invaluable when we restored the village's old fire engine.","我們修復村裡的老消防車時，退休技師的建議極有價值。","invaluable 表示價值極高，不是沒有價值。"]],"l6-0541":[["名詞：庫存清單","stock list","The librarian checked the inventory before ordering replacements for the missing equipment.","圖書館員先查核庫存清單，再訂購遺失設備的替代品。",""]],"l6-0542":[["名詞：調查人員","examiner / inquirer","The investigator interviewed maintenance workers to establish when the damaged cable was last inspected.","調查人員訪談維修工人，確認受損電纜最後一次受檢的時間。",""]],"l6-0543":[["名詞：智商","intelligence quotient","The study compared participants' IQ scores with their performance on several memory tasks.","研究比較受試者的智商分數，以及他們在數項記憶任務上的表現。",""]],"l6-0544":[["形容詞：帶諷刺意味的","wry / sardonic","She gave an ironic smile when the unreliable clock received a design award.","那座不準的時鐘獲得設計獎時，她露出帶諷刺意味的微笑。",""]],"l6-0545":[["名詞：反諷；具有諷刺意味的情況","無直接同義詞","The irony was that the building inspector's own house had several serious defects.","諷刺的是，建築檢查員自己的房子有好幾項嚴重缺陷。",""]],"l6-0546":[["形容詞：易怒的","short-tempered / touchy","After several sleepless nights, he became irritable and snapped at harmless questions.","連續幾夜沒睡好後，他變得易怒，對無惡意的提問也厲聲回應。",""]],"l6-0547":[["動詞：使惱怒","annoy / exasperate","The repeated interruptions irritated the speaker, who struggled to finish explaining the proposal.","一再被打斷令發言者惱怒，他很難把提案解釋完。",""]],"l6-0548":[["名詞：惱怒","annoyance / exasperation","She concealed her irritation when the visitor ignored the same instruction for a third time.","訪客第三次忽略同一項指示時，她壓下了心中的惱怒。",""]],"l6-0549":[["形容詞：喜悅的","joyful / jubilant","The family held a joyous celebration when their grandmother returned home after a long recovery.","祖母經過漫長康復過程返家時，全家歡欣慶祝。",""]],"l6-0550":[["形容詞：正當的","valid / justified","The residents raised legitimate concerns about noise from the proposed outdoor concert venue.","居民對擬設戶外演唱會場地的噪音提出了正當疑慮。",""]],"l6-0551":[["形容詞：冗長的","long / protracted","After a lengthy discussion, the committee agreed to postpone the decision until Friday.","經過漫長討論，委員會同意把決定延至星期五。",""]],"l6-0552":[["形容詞：須負法律責任的","legally responsible / accountable","The agreement states which party is liable for damage caused during delivery.","協議載明，運送期間造成損壞應由哪一方負責。",""]],"l6-0553":[["動詞：解放","free / release","The account describes how the soldiers liberated prisoners held inside the abandoned fortress.","這份記述描寫士兵如何解救關押在廢棄堡壘內的囚犯。",""]],"l6-0554":[["名詞：解放","emancipation / release","The museum preserves photographs taken immediately after the liberation of the occupied town.","博物館保存了遭佔領城鎮獲得解放後隨即拍攝的照片。",""]],"l6-0555":[["副詞：同樣地","similarly / in the same way","The northern branch extended its opening hours, and the southern branch did likewise.","北區分店延長營業時間，南區分店也照辦。",""]],"l6-0556":[["名詞：豪華大型轎車","limo","A black limousine waited outside the theater while the musicians greeted their guests.","音樂家迎接賓客時，一輛黑色豪華大型轎車在劇院外等候。",""]],"l6-0557":[["名詞：大型客輪","passenger ship","The ocean liner entered the harbor slowly, guided by two small tugboats.","大型遠洋客輪在兩艘小拖船引導下，緩緩駛入港口。","liner 常指大型客輪；原稿只列班機會漏掉此常見義，客機通常用 airliner。https://www.oxfordlearnersdictionaries.com/definition/english/liner"]],"l6-0558":[["名詞：語言學家","language researcher","The linguist recorded local speakers to study changes in the island's traditional dialect.","語言學家錄下當地居民的說話聲，研究島上傳統方言的變化。",""]],"l6-0559":[["名詞：公升","litre","The container holds one liter of paint, enough for several small repairs.","容器裝有一公升油漆，足以進行幾處小修補。","litre 是英式拼字。"]],"l6-0560":[["名詞：讀寫能力","ability to read and write","The evening program supports adult literacy through lessons based on everyday documents.","夜間課程運用日常文件教學，幫助成人提升讀寫能力。",""]],"l6-0561":[["形容詞：按字面的","word-for-word","A literal translation of the joke confused readers who did not know the local expression.","笑話的逐字翻譯，讓不熟悉當地說法的讀者感到困惑。",""]],"l6-0562":[["形容詞：能讀寫的","able to read and write","The records suggest that many workers were literate despite having little formal schooling.","紀錄顯示，許多工人雖然很少接受正規教育，仍能讀寫。",""]],"l6-0563":[["名詞：長久存續","long life / durability","Careful maintenance contributed to the longevity of the wooden boats in the village harbor.","細心保養讓村港內的木船得以長久使用。",""]],"l6-0564":[["名詞：休息室","sitting room / waiting area","Passengers relaxed in the lounge while the crew prepared the ferry for departure.","船員準備渡輪啟航時，乘客在休息室放鬆。",""]],"l6-0565":[["形容詞：荒唐的","reckless / absurd","The engineer rejected the lunatic proposal to remove the supports before inspecting the roof.","工程師否決了未檢查屋頂就先拆支撐的荒唐提案。","此詞帶強烈貶意；本例批評提案，不用作精神疾病的中性描述。"]],"l6-0566":[["動詞：引誘","entice / tempt","The bakery hoped to lure new customers with free samples of its seasonal pastries.","麵包店希望用季節限定糕點的免費試吃吸引新客人。",""]],"l6-0567":[["形容詞：茂盛的","luxuriant / verdant","After weeks of rain, lush vegetation covered the slopes above the mountain village.","數週降雨後，茂密的植被覆蓋山村上方的坡地。",""]],"l6-0568":[["名詞：歌詞","song words","The singer revised the lyrics so that younger listeners could follow the story.","歌手修改歌詞，讓年紀較小的聽眾也能理解故事。","歌詞通常用複數 lyrics；原稿混入形容詞釋義，本例採名詞。https://dictionary.cambridge.org/us/dictionary/english/lyric"]],"l6-0569":[["名詞：規模；程度","scale / extent","The first inspection revealed the magnitude of the damage beneath the station platform.","第一次檢查揭露了車站月臺底下損壞的嚴重程度。",""]],"l6-0570":[["名詞：瘧疾","無直接同義詞","The field study examined how malaria affected attendance at schools in the region.","實地研究探討瘧疾如何影響該地區學校的出席情況。",""]],"l6-0571":[["動詞：操弄","distort / falsify","The company manipulated the survey results by excluding responses from dissatisfied customers.","公司剔除不滿意顧客的回答，操弄調查結果。",""]],"l6-0572":[["名詞：未出版的原稿","draft / unpublished text","The editor returned the manuscript with suggestions for clarifying the final chapter.","編輯退回原稿，並提出讓最後一章更清楚的建議。",""]],"l6-0573":[["名詞：瑕疵","blemish / mark","A small mar on the polished surface reduced the antique table's selling price.","拋光表面的一處小瑕疵，拉低了古董桌的售價。","名詞 mar 確有瑕疵義，但比動詞用法少見。https://www.merriam-webster.com/dictionary/mar"]],"l6-0574":[["名詞：大屠殺","mass killing / slaughter","The memorial lists the names of civilians who died in the massacre.","紀念碑列出在大屠殺中喪生的平民姓名。",""]],"l6-0575":[["名詞：精通","command / proficiency","Her mastery of traditional weaving techniques allowed her to restore the damaged textile.","她精通傳統編織技法，因此能修復受損織品。",""]],"l6-0576":[["名詞：物質至上主義","preoccupation with possessions","The novel criticizes materialism through a character who measures friendship by expensive gifts.","小說藉由一個以昂貴禮物衡量友誼的角色，批判物質至上主義。","本例為重視財物的態度，不是哲學上的唯物論。"]],"l6-0577":[["名詞：床墊","無直接同義詞","The guest requested a firmer mattress because the existing one sagged in the middle.","原本的床墊中央凹陷，房客因此要求換一張較硬的床墊。",""]],"l6-0578":[["名詞：機械裝置","mechanical assembly","The clock's winding mechanism was carefully removed before the wooden case was repaired.","修理木製外殼前，時鐘的上鏈機構先被小心拆下。",""]],"l6-0579":[["名詞：藥物","medicine / drugs","The pharmacist checked the label before explaining how the medication should be stored.","藥師先確認標籤，再說明藥物應如何保存。",""]],"l6-0580":[["形容詞：中世紀的","無直接同義詞","Excavations beneath the market uncovered foundations belonging to a medieval stone building.","市場底下的挖掘工程發現了一座中世紀石造建築的地基。",""]],"l6-0581":[["動詞：沉思","reflect / contemplate","She meditated on the difficult decision while walking alone beside the river.","她獨自在河邊行走時，沉思著那個艱難的決定。","meditate on 後接思考的事情；contemplate 可直接接受詞。"]],"l6-0582":[["名詞：沉思","reflection / contemplation","The quiet garden provided a place for meditation after the difficult meeting.","艱難的會議結束後，寧靜花園提供了一處沉思的地方。",""]],"l6-0583":[["形容詞：憂傷的","sorrowful / mournful","A melancholy tune drifted from the empty hall as the pianist rehearsed alone.","鋼琴家獨自練習時，一段憂傷旋律從空蕩大廳飄出。",""]],"l6-0584":[["形容詞：聲音柔和圓潤的","warm / smooth","The mellow sound of the cello suited the small room's intimate atmosphere.","大提琴柔和圓潤的音色，很適合這個小房間的溫馨氛圍。",""]],"l6-0585":[["名詞：心態","mindset / outlook","The coach encouraged a cooperative mentality instead of rewarding individual success alone.","教練鼓勵合作心態，而非只獎勵個人成就。","常用義為心態、思考方式，原稿只列智力易造成誤解。https://dictionary.cambridge.org/us/dictionary/english/mentality"]],"l6-0586":[["名詞：商品","goods / products","The shop moved its fragile merchandise away from the entrance before the renovation began.","整修開始前，店家把易碎商品從入口附近移開。",""]],"l6-0587":[["動詞：合併","combine / unite","The two charities merged to reduce administrative costs and coordinate their food deliveries.","兩個慈善團體合併，以降低行政成本並協調食物配送。",""]],"l6-0588":[["名詞：隱喻","無直接同義詞","The poet uses the abandoned garden as a metaphor for the family's neglected relationships.","詩人用荒廢花園比喻家人之間疏於維繫的關係。","metaphor 通常直接把一事物比作另一事物；simile 則常用 like 或 as 明示相似。"]],"l6-0589":[["形容詞：大都會的","metro","The new railway connects several smaller towns with the metropolitan area's major employment centers.","新鐵路連接數個小鎮與都會區的主要就業中心。","原稿 n 與大都市的釋義不符，此義應標 adj。https://www.merriam-webster.com/dictionary/metropolitan"]],"l6-0590":[["動詞：遷徙","move seasonally","The birds migrate south when food becomes scarce in their northern breeding grounds.","北方繁殖地的食物變少時，這些鳥便向南遷徙。",""]],"l6-0591":[["名詞：遷移","relocation / movement between regions","The historian studied migration from rural villages to the newly expanding industrial towns.","歷史學家研究人們從農村遷往新興工業城鎮的現象。",""]],"l6-0592":[["形容詞：激進好鬥的","combative / confrontational","The speaker adopted a militant tone and demanded immediate action from the committee.","發言者採取激進好鬥的語氣，要求委員會立刻行動。",""]],"l6-0593":[["名詞：磨坊業者","mill operator","The miller adjusted the stones before grinding the grain delivered that morning.","磨坊業者先調整磨石，再研磨當天早上送來的穀物。",""]],"l6-0594":[["動詞：模仿","imitate / copy","The child could mimic the station announcements so accurately that everyone recognized the voice.","孩子把車站廣播模仿得十分精準，大家都聽得出那個聲音。",""]],"l6-0595":[["形容詞：微型的","tiny / small-scale","The architect built a miniature village to demonstrate how the new homes would fit together.","建築師製作微型村莊，展示新住宅將如何配置。",""]],"l6-0596":[["動詞：盡量減少","reduce / keep to a minimum","Workers covered the shelves to minimize dust during repairs to the library ceiling.","修理圖書館天花板時，工人蓋住書架，盡量減少落塵。",""]],"l6-0597":[["形容詞：奇蹟般的","extraordinary / astonishing","The family described the missing dog's return after six months as miraculous.","失蹤六個月的狗回來了，這家人形容那簡直是奇蹟。",""]],"l6-0598":[["形容詞：愛惡作劇的","impish / naughty","The mischievous child hid paper spiders inside the teacher's drawer before class.","愛惡作劇的孩子在上課前，把紙蜘蛛藏進老師抽屜。",""]],"l6-0599":[["形容詞：傳教的","evangelistic","The archive contains letters describing Christian missionary work in remote coastal communities.","檔案館藏有描述偏遠沿海社區基督教傳教工作的信件。",""]],"l6-0600":[["動詞：動員","rally / organize","The charity mobilized volunteers to deliver blankets before the temperature dropped overnight.","慈善團體動員志工，在夜間降溫前配送毛毯。",""]],"l6-0601":[["名詞：現代化","updating / upgrading","Modernization of the factory included replacing outdated controls and improving the ventilation system.","工廠現代化的工作包括更換過時的控制設備，以及改善通風系統。",""]],"l6-0602":[["名詞：模具","mould / casting form","The craftsperson poured melted wax into the mold to make a decorative candle.","工藝師把熔蠟倒進模具，製作裝飾蠟燭。","此義是製作物品的模具，不是一般展示模型 model；mould 為英式拼字。https://dictionary.cambridge.org/dictionary/english/mold"]],"l6-0603":[["名詞：發展的動力","impetus / driving force","The campaign gained momentum after several neighborhood groups joined the effort to protect the wetland.","數個社區團體加入保護濕地的行列後，這項活動聲勢漸增。",""]],"l6-0604":[["名詞：壟斷","exclusive control","The company lost its monopoly when two competitors began offering ferry services to the island.","兩家競爭對手開始提供往返該島的渡輪服務後，公司失去了壟斷地位。",""]],"l6-0605":[["形容詞：單調的","repetitive / tedious","The monotonous task of copying numbers became easier when the office introduced scanning software.","辦公室引進掃描軟體後，抄寫數字這項單調工作變得輕鬆些。",""]],"l6-0606":[["名詞：單調","repetitiveness / sameness","Occasional field trips broke the monotony of spending every afternoon in the classroom.","偶爾的校外教學，打破了每天下午都待在教室的單調。",""]],"l6-0607":[["名詞：士氣","spirits / confidence","The unexpected praise lifted the team's morale after weeks of difficult repairs.","辛苦維修數週後，出乎意料的讚賞振奮了團隊士氣。","morale 是士氣；原稿並列的道德應與 morals 或 morality 區分。https://dictionary.cambridge.org/us/dictionary/english/morale"]],"l6-0608":[["名詞：道德性","ethical acceptability","The debate focused on the morality of using animals to test new cosmetics.","辯論聚焦於用動物測試新化妝品是否符合道德。",""]],"l6-0609":[["名詞：座右銘","maxim / guiding principle","The founder's motto encouraged careful craftsmanship, even when faster methods would have increased profits.","創辦人的座右銘鼓勵精工製作，即使採用較快的方法可以提高利潤。",""]],"l6-0610":[["形容詞：哀傷的","sorrowful / melancholy","A mournful melody accompanied photographs of the village before it disappeared beneath the reservoir.","哀傷旋律伴隨著村莊沒入水庫之前的照片。",""]],"l6-0611":[["名詞：樂器的吹嘴","無直接同義詞","The trumpet player cleaned the mouthpiece before returning the instrument to its case.","小號手先清潔吹嘴，再把樂器放回盒子。",""]],"l6-0612":[["名詞：發言人","representative / press officer","The spokesperson answered reporters' questions about the delay without revealing the passengers' personal details.","發言人回答記者有關延誤的提問，同時保護乘客的個人資料。",""]],"l6-0613":[["形容詞：市政的","local-government / civic","The municipal council approved funding to repair the town's aging drainage system.","市議會核准經費，用來修繕城鎮老舊的排水系統。",""]],"l6-0614":[["形容詞：沉默不語的","silent / speechless","He remained mute when the chair asked who had authorized the missing payment.","主席問是誰核准了那筆不知去向的款項時，他沉默不語。",""]],"l6-0615":[["名詞：一套神話傳說","body of myths","The exhibition explores how birds appear in the mythology of several coastal cultures.","展覽探討鳥類如何出現在數個沿海文化的神話傳說中。",""]],"l6-0616":[["動詞：敘述","recount / tell","The guide narrated the rescue using letters written by people who had witnessed it.","導覽員根據目擊者寫下的信件，敘述那次救援。",""]],"l6-0617":[["名詞：敘事；故事","account / story","Her narrative of the voyage includes practical details missing from the captain's official report.","她對航程的敘述，包含船長正式報告未記載的實際細節。",""]],"l6-0618":[["名詞：敘事者","storyteller","The narrator remembers the village through a child's eyes, overlooking tensions the adults understood.","敘事者透過孩子的眼光回憶村莊，忽略了大人所了解的緊張關係。",""]],"l6-0619":[["名詞：民族主義","無直接同義詞","The historian examined how nationalism influenced the language used in school textbooks.","歷史學家研究民族主義如何影響學校教科書使用的措辭。","nationalism 不必然等同單純愛國之情 patriotism。"]],"l6-0620":[["名詞：博物學家；自然研究者","nature researcher","The naturalist recorded flowering dates and bird calls during her daily walks through the forest.","自然研究者每天在森林散步時，記錄開花日期和鳥鳴。",""]],"l6-0621":[["形容詞：海軍的","無直接同義詞","The museum displays naval uniforms alongside maps showing the routes of historic voyages.","博物館展示海軍制服，以及標示歷史航程路線的地圖。",""]],"l6-0622":[["名詞：肚臍","belly button / umbilicus","The artist adjusted the position of the navel while sketching the human torso.","畫家描繪人體軀幹時，調整了肚臍的位置。",""]],"l6-0623":[["名詞：導航","wayfinding / route guidance","The boat's navigation system helped the crew locate the narrow entrance to the harbor.","船上的導航系統協助船員找到狹窄的港口入口。",""]],"l6-0624":[["名詞：談判","bargaining / discussion of terms","After weeks of negotiation, the workers and management agreed on a revised shift schedule.","經過數週談判，勞資雙方同意調整後的輪班表。",""]],"l6-0625":[["名詞：霓虹燈光","neon lighting","The red neon above the diner reflected in puddles along the dark sidewalk.","餐館上方的紅色霓虹燈光，倒映在昏暗人行道的積水中。","neon 也指氖氣；本例採燈光的延伸用法。https://allaboutglass.cmog.org/definition/neon"]],"l6-0626":[["形容詞：中立的","impartial / unbiased","A neutral observer monitored the discussion and recorded concerns raised by both sides.","中立觀察員留意討論過程，記錄雙方提出的疑慮。",""]],"l6-0627":[["名詞：新婚者","recently married person","As a newlywed, he enjoyed choosing furniture for the home he shared with his spouse.","剛結婚的他，樂於為與配偶同住的家挑選家具。","單數 newlywed 指一位新婚者；一對新婚夫妻通常用複數 newlyweds。https://dictionary.cambridge.org/us/dictionary/english/newlywed"]],"l6-0628":[["名詞：新聞播報員","newsreader / news anchor","The newscaster paused the scheduled bulletin to announce that the missing hikers had been found.","新聞播報員暫停原定新聞內容，宣布失蹤登山客已被找到。",""]],"l6-0629":[["名詞：提名","proposal for selection","Her nomination for the conservation award recognized years of work restoring the riverbank.","她獲提名角逐保育獎，肯定了多年修復河岸的工作。",""]],"l6-0630":[["名詞：被提名人","nominated candidate","Each nominee submitted a short statement explaining how they would improve the association's services.","每位被提名人都提交了簡短聲明，說明將如何改善協會服務。",""]],"l6-0631":[["名詞：常態","standard practice / usual pattern","Working from home became the norm for the team during the office renovation.","辦公室整修期間，居家工作成了團隊的常態。",""]],"l6-0632":[["形容詞：惡名昭彰的","infamous / ill-famed","The junction was notorious for dangerous turns that gave drivers little time to react.","那個路口以危險轉彎聞名，駕駛幾乎沒有反應時間。",""]],"l6-0633":[["動詞：滋養","feed / sustain","The rich soil nourished the young trees planted along the newly restored stream.","肥沃的土壤滋養了最近修復的溪流沿岸種植的幼樹。",""]],"l6-0634":[["名詞：滋養身體的食物","sustenance / food","The volunteers brought warm soup to provide nourishment for travelers stranded at the station.","志工送來熱湯，為受困車站的旅客補充營養。",""]],"l6-0635":[["名詞：令人困擾的事物","annoyance / inconvenience","The broken gate became a nuisance whenever deliveries arrived during the morning rush.","每逢早上忙碌時段送貨到來，壞掉的大門就令人困擾。",""]],"l6-0636":[["動詞：培育","foster / cultivate","The teacher nurtured her students' curiosity by letting them design their own experiments.","老師讓學生自行設計實驗，培養他們的好奇心。",""]],"l6-0637":[["形容詞：供應養分的","nourishing","The roots were suspended in a nutrient solution rather than planted in soil.","根部懸在營養液中，沒有種在土裡。","本例採原稿所列形容詞義；nutrient 作名詞時指養分。"]],"l6-0638":[["名詞：營養學","study of nourishment","The course combines basic nutrition with practical lessons on planning balanced school meals.","課程結合基礎營養學與規劃均衡學校餐點的實作教學。","study of nourishment 是解釋性片語。"]],"l6-0639":[["形容詞：有營養的","nourishing / wholesome","The community kitchen prepares nutritious meals using vegetables donated by nearby farms.","社區廚房運用附近農場捐贈的蔬菜，烹煮有營養的餐點。",""]],"l6-0640":[["名詞：義務","duty / responsibility","The agreement outlines each member's obligation to maintain the shared garden and storage area.","協議說明各成員維護共用花園和儲藏區的義務。",""]],"l6-0641":[["動詞：迫使；要求","require / compel","The contract obliges the supplier to replace any equipment damaged before delivery.","合約要求供應商更換任何在交貨前受損的設備。",""]],"l6-0642":[["形容詞：晦澀的","unclear / difficult to understand","The instructions were so obscure that even experienced technicians disagreed about the next step.","指示十分晦澀，連有經驗的技師對下一步也意見不同。",""]],"l6-0643":[["名詞：供品","sacrificial gift / tribute","The family placed an offering of fruit beside the candles on the shrine.","家人把水果供品放在神龕上的蠟燭旁。",""]],"l6-0644":[["名詞：後代；幼崽","young / progeny","The researchers watched how the adult birds protected their offspring during heavy rain.","研究人員觀察成鳥如何在大雨中保護幼鳥。","offspring 的單複數同形。"]],"l6-0645":[["形容詞：可運作的","functioning / in working order","The backup system remained operational even after the main power supply failed.","主要電源失效後，備援系統仍能運作。","本例採可運作、投入運作的常見義。"]],"l6-0646":[["名詞：反對","resistance / objection","Strong opposition from residents led the developers to revise the parking plan.","居民強烈反對，促使開發商修改停車規劃。",""]],"l6-0647":[["動詞：壓迫","persecute / subjugate","The novel portrays a ruler who oppresses farmers through forced labor and excessive taxes.","小說描繪一位透過強制勞動和苛稅壓迫農民的統治者。",""]],"l6-0648":[["名詞：壓迫","persecution / subjugation","The exhibition documents the oppression faced by communities denied basic political rights.","展覽記錄了遭剝奪基本政治權利的社群所面臨的壓迫。",""]],"l6-0649":[["名詞：選項","choice / alternative","Taking the overnight ferry was our only practical option after the last flight was canceled.","末班飛機取消後，搭夜間渡輪是我們唯一實際可行的選項。",""]],"l6-0650":[["形容詞：可自行選擇的","voluntary / elective","Attendance at the weekend workshop is optional, but registration helps the organizers prepare materials.","週末工作坊可自由參加，不過報名有助於主辦單位準備材料。",""]],"l6-0651":[["名詞：痛苦的考驗","trial / harrowing experience","The long ordeal ended when rescuers reached the family trapped above the flooded road.","救援人員抵達淹水道路上方受困的一家人身邊，漫長煎熬終於結束。",""]],"l6-0652":[["形容詞：有秩序的","organized / well-regulated","Staff guided visitors through an orderly evacuation when smoke appeared near the kitchen.","廚房附近出現煙霧時，工作人員引導訪客有秩序地疏散。",""]],"l6-0653":[["名詞：生物；有機體","living thing","Under the microscope, the students watched a tiny organism move through a drop of pond water.","學生透過顯微鏡，觀看微小生物在一滴池水中移動。",""]],"l6-0654":[["名詞：獨創性","inventiveness / novelty","The judges praised the design's originality and its thoughtful use of recycled materials.","評審讚賞設計的獨創性，以及巧妙運用回收材料的方式。",""]],"l6-0655":[["動詞：起源","arise / begin","The custom originated in fishing communities before spreading to towns farther inland.","這項習俗起源於漁村，後來傳到更內陸的城鎮。",""]],"l6-0656":[["名詞：疾病的爆發","sudden occurrence","The report traced the outbreak to a shared water source used by several villages.","報告追查到，這次疫情源自數個村莊共用的水源。",""]],"l6-0657":[["名詞：一套服裝","ensemble / set of clothes","She chose a comfortable outfit suitable for both the train journey and the afternoon interview.","她挑了一套舒適服裝，適合搭火車，也適合下午面試。",""]],"l6-0658":[["名詞：短途出遊","excursion / day trip","The club arranged an outing to a coastal reserve during the spring migration.","春季候鳥遷徙期間，社團安排了前往沿海保護區的出遊。",""]],"l6-0659":[["名詞：法外之徒","fugitive criminal","The novel follows an outlaw who hides in the mountains after escaping from prison.","小說描寫一名逃獄後藏身山區的法外之徒。",""]],"l6-0660":[["名詞：排出口","exit / opening","Leaves blocked the drainage outlet, causing water to collect behind the retaining wall.","樹葉堵住排水口，導致擋土牆後方積水。","原稿詞性欄空白，但釋義文字標 n；本例採名詞。"]],"l6-0661":[["名詞：對事物的看法","perspective / attitude","Working with different communities broadened her outlook on how public spaces should be designed.","與不同社區合作，拓展了她對公共空間應如何設計的看法。",""]],"l6-0662":[["動詞：數量超過","be more numerous than","On market days, visitors outnumber permanent residents in the small mountain town.","市集舉行的日子，這座小山城的遊客比常住居民還多。",""]],"l6-0663":[["動詞：激怒","infuriate / incense","The decision to remove the memorial outraged residents who had raised money to build it.","拆除紀念碑的決定，激怒了曾募款興建它的居民。",""]],"l6-0664":[["形容詞：令人憤慨的","appalling / shocking","The committee condemned the outrageous treatment of workers who had reported unsafe conditions.","委員會譴責通報不安全環境的工人所遭受的惡劣待遇。",""]],"l6-0665":[["形容詞：完全的","complete / total","The proposal met with outright rejection from members concerned about the financial risks.","擔憂財務風險的成員徹底否決了提案。","形容詞也常指完全的；本例不是原稿的直率義。https://dictionary.cambridge.org/dictionary/english/outright"]],"l6-0666":[["名詞：開始","beginning / start","Clear responsibilities were established at the outset to prevent confusion during the restoration.","修復工作一開始就確立了明確職責，以免過程中混淆。",""]],"l6-0667":[["形容詞：頭頂上方的","無直接同義詞","The overhead lights dimmed as the audience settled into their seats for the performance.","觀眾坐定準備欣賞表演時，頭頂上方的燈光暗了下來。",""]],"l6-0668":[["動詞：部分重疊","partly coincide","The two training sessions overlap by half an hour, so I cannot attend both in full.","兩場訓練有半小時重疊，因此我無法全程參加兩場。",""]],"l6-0669":[["動詞：翻覆","tip over / capsize","The small boat overturned when a sudden wave struck it near the harbor entrance.","一波突浪在港口入口附近打中小船，導致船翻覆。",""]],"l6-0670":[["名詞：協定","agreement / accord","The neighboring towns signed a pact to share emergency equipment during major storms.","鄰近城鎮簽署協定，在重大風暴期間共用緊急設備。",""]],"l6-0671":[["名詞：小冊子","booklet / brochure","The pamphlet explains the museum's restoration methods through photographs and brief descriptions.","小冊子以照片和簡短說明介紹博物館的修復方法。",""]],"l6-0672":[["動詞：使癱瘓；使停擺","cripple / immobilize","The heavy snowfall paralyzed transport across the region, leaving passengers stranded overnight.","大雪使整個地區交通癱瘓，乘客受困過夜。",""]],"l6-0673":[["名詞：國會","legislature / legislative assembly","The minister presented the proposal to parliament after consulting local education officials.","部長諮詢地方教育官員後，向國會提出提案。",""]],"l6-0674":[["形容詞：令人憐憫的","pitiful / pitiable","The abandoned puppy looked pathetic as it shivered beside the locked gate.","遭遺棄的小狗在鎖住的大門旁發抖，看來十分可憐。",""]],"l6-0675":[["形容詞：愛國的","無直接同義詞","The ceremony included patriotic songs performed by a choir from the local school.","典禮包含由當地學校合唱團演唱的愛國歌曲。","形容歌曲表達愛國情感；nationalistic 帶民族主義含義，不能一概互換。"]],"l6-0676":[["名詞：個人數位助理","PDA","The museum displays a personal digital assistant once used to store appointments and contact details.","博物館展示了一部過去用來儲存行程和聯絡資料的個人數位助理。","此處指較早期的掌上電子裝置。"]],"l6-0677":[["動詞：沿街兜售","hawk / sell door to door","He peddled handmade baskets through the villages before opening a permanent shop.","開設固定店面前，他沿著各村兜售手工籃子。",""]],"l6-0678":[["名詞：行人","person on foot","The driver stopped to let a pedestrian carrying groceries cross the narrow road.","駕駛停車，讓提著雜貨的行人穿越狹窄道路。",""]],"l6-0679":[["名詞：半島","無直接同義詞","A coastal trail runs around the peninsula, passing fishing villages and sheltered beaches.","沿海步道繞行半島，經過漁村和避風海灘。",""]],"l6-0680":[["名詞：退休金","retirement income","Her pension covers basic expenses, while occasional tutoring pays for visits to her grandchildren.","她的退休金支應基本開銷，偶爾家教的收入則用來探望孫子女。",""]],"l6-0681":[["名詞：觀感","impression / view","The renovation changed residents' perception of the station from unsafe to welcoming.","整修改變了居民對車站的觀感，從不安全轉為親切宜人。",""]],"l6-0682":[["名詞：毅力","persistence / determination","Her perseverance kept the restoration project moving despite repeated shortages of materials.","儘管材料一再短缺，她的毅力仍讓修復專案持續推進。",""]],"l6-0683":[["動詞：堅持不懈","persist / keep going","The researchers persevered with the experiment after several attempts produced inconsistent results.","幾次嘗試得到不一致的結果後，研究人員仍堅持繼續實驗。",""]],"l6-0684":[["名詞：堅持","perseverance / tenacity","His persistence finally persuaded the archive to search boxes that had remained unopened for decades.","他的堅持終於說服檔案館搜尋數十年未開啟的箱子。",""]],"l6-0685":[["形容詞：持續不懈的","tenacious / determined","The persistent reporter kept requesting the records until the department released them.","記者鍥而不捨地要求提供紀錄，直到部門公開為止。",""]],"l6-0686":[["名詞：觀點","viewpoint / standpoint","The documentary presents the restoration from the perspective of craftspeople working behind the scenes.","紀錄片從幕後工藝師的觀點，呈現修復工作。","原稿同時列形容詞與名詞釋義；本例採名詞。"]],"l6-0687":[["名詞：防治有害生物的藥劑","pest-control agent","The laboratory tested nearby stream water for traces of pesticide used on surrounding farmland.","實驗室檢測附近溪水，查看是否殘留周圍農田使用的農藥。","pesticide 範圍比殺蟲劑 insecticide 廣，不只針對昆蟲。https://www.merriam-webster.com/dictionary/pesticide"]],"l6-0688":[["名詞：石油","crude oil","The port expanded its storage facilities to handle petroleum arriving from offshore fields.","港口擴建儲存設施，以處理來自海上油田的石油。",""]],"l6-0689":[["形容詞：瑣碎的","trivial / minor","Petty disagreements about desk space distracted the team from preparing the exhibition.","有關桌面空間的瑣碎爭執，讓團隊分心而無法專注籌備展覽。",""]],"l6-0690":[["名詞：藥師","chemist","The pharmacist contacted the clinic to clarify handwriting on the patient's prescription.","藥師聯絡診所，確認病人處方箋上的手寫內容。","chemist 作藥師義主要見於英式英語，也可指化學家。"]],"l6-0691":[["名詞：藥局","drugstore / chemist's","The pharmacy near the station stays open late for passengers returning from work.","車站附近的藥局營業到很晚，方便下班返家的乘客。",""]],"l6-0692":[["名詞：階段","stage / period","The next phase of construction involves rebuilding the steps leading to the river.","下一階段工程包括重建通往河邊的階梯。",""]],"l6-0693":[["形容詞：攝影的","無直接同義詞","The archive stores photographic negatives in special sleeves to protect them from scratches.","檔案館把攝影底片放在專用保護套裡，避免刮傷。",""]],"l6-0694":[["形容詞：如畫的","scenic","The picturesque village attracted painters with its stone cottages and narrow riverside lanes.","如畫的村莊以石造小屋和河畔窄巷吸引畫家。","scenic 指景色優美；picturesque 更突出適合入畫的外觀。"]],"l6-0695":[["動詞：刺穿","puncture / penetrate","A sharp branch pierced the tent fabric during the sudden windstorm overnight.","夜間突起的暴風中，一根尖樹枝刺穿了帳篷布。",""]],"l6-0696":[["名詞：虔誠","devotion / devoutness","Her quiet piety was reflected in daily prayers and patient service to her community.","她每日祈禱，耐心服務社區，展現不張揚的虔誠。",""]],"l6-0697":[["形容詞：虔誠的","devout / religious","The pious family gathered for prayer before sharing their evening meal.","虔誠的一家人在共進晚餐前，聚在一起祈禱。",""]],"l6-0698":[["名詞：輸送管線","conduit","The pipeline carries fresh water from the reservoir to villages across the valley.","管線把淡水從水庫輸送到山谷各村。",""]],"l6-0699":[["名詞：有柄水壺","jug","The server placed a pitcher of iced water beside the glasses on our table.","服務生把一壺冰水放在我們桌上的玻璃杯旁。",""]],"l6-0700":[["名詞：困境","predicament / difficult situation","The report drew attention to the plight of families displaced by the factory closure.","報告讓人注意到因工廠關閉而被迫離開原居地的家庭所面臨的困境。",""]],"l6-0701":[["肺炎","無直接同義詞","The doctor ordered a chest scan after diagnosing pneumonia.","醫師診斷肺炎後安排胸部掃描。","pneumonia 是肺部感染疾病名稱。"]],"l6-0702":[["及物動詞：盜獵；水煮","hunt illegally / cook gently","The chef poached the eggs in barely simmering water for three minutes.","廚師把蛋放在微沸的水中水煮三分鐘。","本句採烹調義；poach 也可指非法捕獵。"]],"l6-0703":[["盜獵者；蒸鍋","hunter / game poacher","Rangers arrested a poacher carrying traps in the reserve.","巡護員逮捕了一名在保護區攜帶陷阱的盜獵者。","poacher 指非法捕獵野生動物的人。"]],"l6-0704":[["名詞：污染物","contaminant / impurity","The factory released harmful pollutants.","那家工廠排放了有害的汙染物。","pollutant 指排放或環境中的污染物；本句採污染物義。"]],"l6-0705":[["沈思；仔細考慮","reflect on / contemplate","The board pondered the cost before approving the renovation.","董事會仔細考慮成本後才批准整修。","ponder 強調長時間、慎重地思考。"]],"l6-0706":[["居住於","inhabit / occupy","More than a million people populate the coastal plain.","有超過一百萬人居住在這片沿海平原。","populate 指人或動物居住於某地。"]],"l6-0707":[["姿勢","stance / bearing","The therapist corrected her posture at the computer.","治療師糾正她使用電腦時的姿勢。","posture 可指身體姿勢，也可指態度立場。"]],"l6-0708":[["vt / vi：處在(...)之前；優於","come before","Lunch will precede the meeting.","午餐會在會議之前舉行。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0709":[["n：先例；adj：在前的","prior example / established practice / legal precedent","There is no precedent for this.","這沒有先例。","precedent 在本句中指可供後續參照的先例。"]],"l6-0710":[["精確","accuracy / exactness","The instrument measures distance with remarkable precision.","這台儀器能以驚人的精確度測量距離。","precision 強調測量或操作的精準程度。"]],"l6-0711":[["n：前任","former holder / previous officeholder","He replaced his predecessor.","他接替了他的前任。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0712":[["預測；預言","forecast / projection","His prediction was correct.","他的預測是正確的。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0713":[["序言","introduction / foreword","The author explains the book’s purpose in the preface.","作者在序言中說明本書的目的。","preface 是作者置於正文前的引言。"]],"l6-0714":[["偏見","bias","The hiring policy was revised to reduce prejudice against older applicants.","公司修改招聘政策，以減少對年長求職者的偏見。","prejudice 是未經充分了解便形成的負面成見。"]],"l6-0715":[["adj：預備的 n.初步","initial / introductory","The preliminary results are in.","初步結果出來了。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0716":[["過早的；不成熟的","untimely / immature","The premature announcement confused investors because the figures were incomplete.","數據尚未完整就過早宣布，令投資人困惑。","premature 表示發生或決定得太早。"]],"l6-0717":[["n：首相；adj：最早的；首要的","leading / top-quality","This is a premier service.","這是一項頂級服務。","premier 在此表示高品質、頂級的。"]],"l6-0718":[["vt：規定；開處方","order / authorize","The doctor will prescribe medicine.","醫生會開藥。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0719":[["規定；處方","medical order / regulation","The pharmacist checked the prescription before preparing the medicine.","藥師調配藥物前核對了處方。","prescription 可指醫師處方，也可指正式規定。"]],"l6-0720":[["vi：主持；管轄","chair / lead","He will preside over the meeting.","他將主持會議。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0721":[["總裁或總統職位","term of office","She announced her candidacy for the company presidency.","她宣布參選公司總裁職位。","presidency 指總裁或總統的職位及任期。"]],"l6-0722":[["總裁或總統的","official / governmental","The presidential residence hosted the visiting delegation.","總統官邸接待了來訪代表團。","presidential 指總統職務或相關的事物。"]],"l6-0723":[["名望","standing / esteem","The scientist’s prestige attracted talented researchers from abroad.","這位科學家的名望吸引了海外優秀研究人員。","prestige 指因成就或地位而獲得的尊崇。"]],"l6-0724":[["擅自做；假定","assume / take for granted","You should not presume that the client has accepted the revised terms.","你不該擅自認定客戶已接受修訂條款。","presume 可指未經證實便假定，也可指擅自行事。"]],"l6-0725":[["預防的","prophylactic","The clinic offers preventive screenings for high blood pressure.","診所提供高血壓預防性篩檢。","preventive 用於降低疾病或問題發生機率的措施。"]],"l6-0726":[["n：生產力","performance / output","The new system increased productivity.","新系統提升了生產力。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0727":[["n：精通","competence / skill","He has a high level of language proficiency.","他的語言能力非常熟練。","proficiency 表示熟練或精通某項技能，尤其是語言能力。"]],"l6-0728":[["深刻的；完全的","deep","The documentary had a profound effect on public attitudes toward recycling.","這部紀錄片深刻影響了大眾對回收的看法。","profound 表示影響深遠或思想深刻。"]],"l6-0729":[["adj：進步的；革新的","forward-thinking / advancing","They have progressive ideas.","他們提出了進步的想法。","progressive ideas 指具有進步性或創新性的想法。"]],"l6-0730":[["vt：禁止","ban / forbid","They prohibit parking here.","他們禁止在這裡停車。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0731":[["禁止","ban","The city imposed a prohibition on parking along the emergency route.","市政府禁止在緊急通道沿線停車。","prohibition 是正式禁止某行為的規定。"]],"l6-0732":[["n：設計；發射；預測","forecast / prediction","These are the sales projections.","這是銷售預測。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0733":[["易於……的；傾斜的","inclined / susceptible","Young seedlings are prone to damage in strong winds.","幼苗容易在強風中受損。","prone 常與 to 連用，表示容易遭遇某事。"]],"l6-0734":[["宣傳","persuasive messaging / political messaging","The regime spread propaganda through state-controlled television.","該政權透過國營電視散播宣傳。","propaganda 通常指為影響觀點而選擇性傳播的訊息。"]],"l6-0735":[["vt：推進","push / drive","Innovation will propel the company forward.","創新將推動公司向前發展。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0736":[["螺旋槳；推進器","screw / propulsor","A damaged propeller forced the ferry to return to port.","螺旋槳受損迫使渡輪返回港口。","propeller 以旋轉葉片推動船或飛機前進。"]],"l6-0737":[["散文","writing","The poet published a short book of prose between collections of verse.","這位詩人在兩本詩集之間出版了一本短篇散文集。","prose 指非詩體、按自然句法書寫的文字。"]],"l6-0738":[["起訴","charge / bring to trial","Prosecutors decided to prosecute the contractor for fraud.","檢察官決定起訴這名承包商詐欺。","prosecute 是以刑事案件正式追訴某人。"]],"l6-0739":[["起訴","legal action","The prosecution presented bank records as evidence.","控方提出銀行紀錄作為證據。","prosecution 可指起訴程序或代表控方的一方。"]],"l6-0740":[["adj：預期的","potential","We are interviewing prospective employees.","我們正在面試潛在的員工。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0741":[["adj：省的；地方性的","regional","The provincial government is based there.","省政府設在那裡。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0742":[["vt：對...挑釁；煽動","cause / trigger","The remark provoked laughter.","那番評論引發了大笑。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0743":[["潛行","sneak / stalk","The cat prowled along the fence after dark.","天黑後，那隻貓沿著圍籬悄悄潛行。","prowl 指為尋找目標而緩慢、偷偷地移動。"]],"l6-0744":[["準時的","on time","Our punctual courier arrived before the warehouse closed.","我們準時的快遞員在倉庫關門前抵達。","punctual 強調嚴格遵守約定時間。"]],"l6-0745":[["vt：淨化；精煉","cleanse / filter","We need to purify the water.","我們需要將這些水淨化。","例句符合 purify 的「淨化」義項；中文翻譯調整為自然表達。"]],"l6-0746":[["純淨","cleanliness","The laboratory tests the purity of every batch of drinking water.","實驗室檢測每批飲用水的純淨度。","purity 指沒有污染或混雜物的程度。"]],"l6-0747":[["n：資格","credential / eligibility","She has the right qualifications for the job.","她具備這份工作所需的資格。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0748":[["喜歡爭吵的","argumentative / combative","The quarrelsome tenant argued with neighbors over every parking space.","那名愛爭吵的房客為每個停車位都和鄰居爭執。","quarrelsome 形容經常挑起爭吵的人。"]],"l6-0749":[["熄滅；解渴；壓制","extinguish / satisfy","A glass of water quenched her thirst after the long hike.","長途健行後，一杯水解了她的口渴。","quench 可指止渴、熄滅火焰或壓抑欲望。"]],"l6-0750":[["n / vt / vi：詢問","inquiry / question","Please address any queries to the manager.","若有任何疑問請洽經理。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0751":[["n：問卷","survey","Please fill out this questionnaire.","請填寫這份問卷。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0752":[["種族主義","racialism / bigotry","The school added lessons that confront the history of racism.","學校增加課程，正視種族主義的歷史。","racism 指基於種族而歧視或主張優越的思想。"]],"l6-0753":[["光芒四射的；容光煥發的","glowing / brilliant","She looked radiant in the photographs from her wedding day.","她在婚禮照片中看起來容光煥發。","radiant 可指發光，也可形容神采奕奕。"]],"l6-0754":[["輻射；散發；流露","emit / emanate","Warmth radiated from the stone wall after sunset.","日落後，石牆散發出溫暖。","radiate 指熱、光或情感從中心向外散發。"]],"l6-0755":[["輻射；發光","emission","Workers wore dosimeters while handling the radiation source.","工人處理輻射源時佩戴劑量計。","radiation 指能量以射線或波的形式傳播。"]],"l6-0756":[["散熱器；輻射體","heater / heat exchanger","The mechanic replaced the leaking radiator before the engine overheated.","引擎過熱前，技師更換了漏水的散熱器。","radiator 可指車輛散熱器或室內暖氣裝置。"]],"l6-0757":[["根本的；激進的；根；部首","extreme / fundamental","The proposal calls for radical changes to the city’s transit system.","這項提案要求對城市運輸系統進行激進改革。","radical 作形容詞可指根本或激進，名詞另有數學與文字義。"]],"l6-0758":[["橡皮艇；木筏","inflatable boat","The rescuers crossed the flooded street in an inflatable raft.","救援人員乘橡皮艇穿越淹水街道。","raft 指用浮材組成的簡易筏，也可指橡皮艇。"]],"l6-0759":[["襲擊；劫掠","attack / assault","Police raided the warehouse after obtaining a search warrant.","警方取得搜索票後突襲那座倉庫。","raid 指突然且有組織的襲擊或搜查。"]],"l6-0760":[["任意行動；隨機的","arbitrary","The software selects a random sample from the customer database.","軟體從客戶資料庫隨機選取樣本。","random 表示沒有特定模式或預先選定。"]],"l6-0761":[["贖金","payment / extortion money","The kidnappers demanded a ransom before releasing the journalist.","綁匪要求贖金後才釋放那名記者。","ransom 是為釋放被扣押者而支付的錢。"]],"l6-0762":[["疹子；輕率的","skin eruption / hasty","He developed a rash after using the new detergent.","他使用新洗衣精後起了疹子。","rash 作名詞是皮膚疹，作形容詞指欠缺考慮。"]],"l6-0763":[["adj：理性的 n.有理數","reasonable / logical","We need a rational approach.","我們需要一個理性的方法。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0764":[["使荒蕪；毀滅","devastate / destroy","The drought ravaged farms across the southern valley.","乾旱摧毀了南部山谷各地的農場。","ravage 強調造成廣泛且嚴重的破壞。"]],"l6-0765":[["現實性","practicality","The novel balances romantic hopes with the realism of daily work.","這部小說在浪漫理想與日常工作的現實性之間取得平衡。","realism 指忠於現實的描寫或務實態度。"]],"l6-0766":[["n：領悟；實現","understanding / achievement","He came to the realization too late that he had made a mistake.","他太晚才領悟到自己犯了錯。","此例句採用 realization 的「領悟」義項；come to the realization that 是自然且常見的搭配。"]],"l6-0767":[["反叛","revolt / insurrection","The rebellion ended after the two sides signed a cease-fire.","雙方簽署停火協議後，這場反叛告終。","rebellion 指反抗政府或權威的行動。"]],"l6-0768":[["n：後退；衰退；經濟衰退","economic decline / downturn / slump","The country is in a recession.","該國正處於經濟衰退。","recession 在本句指經濟衰退或不景氣。"]],"l6-0769":[["n：接受者；收件人","receiver / addressee","Who is the recipient?","誰是收件人？","recipient 是名詞，指收到物品、信件或資訊的人。"]],"l6-0770":[["n：推薦","suggestion","Thanks for your recommendation.","謝謝你的推薦。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0771":[["vt：使和解","resolve / harmonize","They reconciled their differences.","他們調和了彼此的歧見。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0772":[["消遣的","leisure-based / for leisure","The center offers recreational classes in swimming and photography.","中心提供游泳與攝影等消遣課程。","recreational 指為休閒娛樂而做的活動。"]],"l6-0773":[["vt / vi：徵募 n.新兵；新手","hire / enlist","We are recruiting new staff.","我們正在招募新員工。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0774":[["再發生；返回","happen again","If the fever recurs, contact the clinic immediately.","如果發燒再次出現，請立即聯絡診所。","recur 指事件以相似形式再次發生。"]],"l6-0775":[["多餘的","excess / superfluous","The editor removed redundant sentences from the safety manual.","編輯刪除了安全手冊中多餘的句子。","redundant 指重複而不必要的內容。"]],"l6-0776":[["vt / vi：提煉；改善","improve / perfect / sharpen","We need to refine our strategy.","我們需要改進策略。","refine 在本句指逐步改進或完善策略。"]],"l6-0777":[["提煉；改善","polish / improvement","The final refinement of the design made the control panel easier to use.","設計最後的改良讓控制面板更容易使用。","refinement 可指細部改善，也可指提煉純化。"]],"l6-0778":[["形容詞：沉思的","thoughtful / contemplative","She was in a reflective mood.","她當時正陷入沉思。","本句 reflective 表示認真思考；與形容表面反光的 reflective 不同。"]],"l6-0779":[["精力恢復；茶點","drinks / light food","Cold refreshments were served during the afternoon workshop.","下午工作坊期間供應了冰涼茶點。","refreshment 可指恢復精神的事物，也可指飲料點心。"]],"l6-0780":[["n：退款；償還 [rɪ`fʌnd] vt.vi.退款；償還","repayment","I want a full refund.","我想要全額退款。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0781":[["不論；不管","irrespective of / despite","Regardless of the weather, the delivery team follows the same route.","不論天氣如何，配送團隊都走同一條路線。","regardless of 表示即使條件不同，結果仍不受影響。"]],"l6-0782":[["政體；政權","government","The new regime promised to restore the country’s damaged economy.","新政權承諾重振受損的國家經濟。","regime 可中性指政體，也常暗示專制政府。"]],"l6-0783":[["排練","practice","The cast held a full rehearsal on the theater’s main stage.","演員在劇院主舞台進行完整排練。","rehearsal 是正式演出前按流程練習。"]],"l6-0784":[["排練","practice","The actors rehearsed the final scene until every cue was precise.","演員排練最後一幕，直到每個提示都準確無誤。","rehearse 指為正式演出反覆練習。"]],"l6-0785":[["韁繩；駕馭；勒馬","bridle / curb","The rider pulled the rein gently to turn the horse.","騎士輕拉韁繩讓馬轉彎。","rein 作名詞是馬具，作動詞可指控制。"]],"l6-0786":[["vt：強化","strengthen / support","We need to reinforce the structure.","我們需要加強結構。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0787":[["接力賽；轉播","broadcast / handoff","The station relayed the emergency alert to every local channel.","電台把緊急警報轉播到每個地方頻道。","relay 可指接力傳遞，也可指訊息轉播。"]],"l6-0788":[["adj：有關的","pertinent / applicable","Keep the discussion relevant.","讓討論保持切題。","relevant 在本句表示與討論主題直接相關、切合重點。"]],"l6-0789":[["信賴；依靠","dependence / trust","The clinic’s reliance on donations makes budgeting difficult.","診所依靠捐款，讓預算編列變得困難。","reliance 常與 on 連用，表示依賴。"]],"l6-0790":[["滋味；品嚐","savor / flavor","She relished the spicy noodles after a long day at work.","工作一整天後，她細細品嚐辣麵。","relish 作動詞是享受滋味，作名詞可指風味醬料。"]],"l6-0791":[["n：剩餘物","rest / leftover","The remainder of the work will be finished later.","剩餘的工作稍後會完成。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0792":[["移去","elimination / taking away","The removal of the damaged roof took two days.","拆除受損屋頂花了兩天。","removal 指把人或物移走的行動。"]],"l6-0793":[["新生；文藝復興","rebirth / revival","The museum’s Renaissance gallery contains works by Italian masters.","博物館的文藝復興展廳收藏義大利大師作品。","Renaissance 特指歐洲文化藝術復興時期。"]],"l6-0794":[["使成為；付給；提出","provide / make","The judge rendered a decision after reviewing the evidence.","法官審查證據後作出裁決。","render 可依語境表示作成、提供或使成為。"]],"l6-0795":[["adj：有名的","famous / well-known","He is a renowned expert.","他是一位著名的專家。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0796":[["租金；租賃的","rent / lease","The monthly rental includes water, heating, and parking.","每月租金包含水費、暖氣與停車位。","rental 可指租用費，也可修飾供出租的物品。"]],"l6-0797":[["抑制","restrain / suppress","She tried to repress her anger during the negotiation.","談判期間她努力抑制怒氣。","repress 指把情緒或念頭壓下不表露。"]],"l6-0798":[["相似","likeness / similarity","The resemblance between the two paintings surprised the curator.","兩幅畫的相似之處讓策展人驚訝。","resemblance 強調外觀或特徵的相像。"]],"l6-0799":[["蓄水庫","water storage","The reservoir supplies drinking water to three nearby towns.","這座蓄水庫供應附近三個城鎮的飲用水。","reservoir 是儲存大量水的人工或天然水體。"]],"l6-0800":[["居住的","housing / domestic","The council approved a new residential complex near the station.","市議會核准車站附近的新住宅區。","residential 指供人居住而非商業用途。"]],"l6-0801":[["抵抗的；抵抗者","immune","This coating is resistant to salt water and harsh sunlight.","這種塗層能抵抗鹽水與強烈陽光。","resistant 常與 to 連用，表示不易受影響。"]],"l6-0802":[["堅決的；堅定的人","determined / steadfast","The resolute manager refused to cut safety inspections.","那位堅決的經理拒絕刪減安全檢查。","resolute 形容決心堅定、不輕易改變。"]],"l6-0803":[["adj：各自的","individual","They went to their respective offices.","他們回到各自的辦公室。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0804":[["n：恢復；重建","repair / renewal","The restoration of the building is complete.","建築的修復已經完成了。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0805":[["n：抑制；克制","self-control / moderation","He showed great restraint during the argument.","他在爭論中表現出極大的克制。","此處 restraint 指在情緒或行動上的克制、自制；常見搭配為 show restraint。"]],"l6-0806":[["n / vt / vi：零售；零售業 adj：零售的","retailing / sale to consumers","He works in retail.","他從事零售業。","retail 可作名詞指零售業，也可作動詞表示零售，或作形容詞指零售的。"]],"l6-0807":[["報復","get even","The company retaliated against the supplier by ending the contract.","公司終止合約以報復供應商。","retaliate 指針對傷害或攻擊採取報復行動。"]],"l6-0808":[["vt：重獲；挽回 vi.銜回獵物","recover / get back","I need to retrieve my files.","我需要取回我的檔案。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0809":[["揭示；顯示；天啟","disclosure / discovery","The audit led to a revelation about missing inventory.","稽核揭示了庫存短缺的真相。","revelation 指突然揭露的重要真相。"]],"l6-0810":[["n：收入","income / sales","The company increased its revenue.","公司增加了營收。","revenue 指企業或組織從銷售或服務取得的收入。"]],"l6-0811":[["甦醒；重振","resurgence / renewal","The revival of the old theater brought new life to the neighborhood.","老戲院的重振為社區帶來新活力。","revival 指沉寂事物重新活躍或復興。"]],"l6-0812":[["修辭","oratory / persuasive language","The speech relied on rhetoric rather than concrete evidence.","這場演講依賴修辭而非具體證據。","rhetoric 可指說服性語言，也可含空泛言辭之意。"]],"l6-0813":[["有節奏的","metrical","The drummer maintained a rhythmic beat throughout the parade.","鼓手在遊行全程維持有節奏的拍子。","rhythmic 表示有規律重複的節拍或動作。"]],"l6-0814":[["嘲笑","mock / deride","The comedian ridiculed the outdated software during his routine.","喜劇演員在表演中嘲笑過時的軟體。","ridicule 指以言語或行為嘲弄他人或事物。"]],"l6-0815":[["嚴格的","stringent / thorough","The laboratory follows rigorous procedures for handling samples.","實驗室遵循嚴格的樣本處理程序。","rigorous 強調規則嚴密或檢驗徹底。"]],"l6-0816":[["暴亂；喧鬧","uprising / disturbance","Police closed the square after a riot broke out.","暴亂爆發後，警方封鎖了廣場。","riot 指失控的群眾暴力或喧鬧。"]],"l6-0817":[["儀式","ceremony / ritual","The community holds a harvest rite every autumn.","社區每年秋天舉行收穫儀式。","rite 指宗教或傳統中固定的儀式。"]],"l6-0818":[["n / adj：儀式（的）；例行習慣（的）","ceremony / routine","Checking the equipment is part of our daily ritual.","檢查設備是我們每天例行的一部分。","ritual 可指固定、例行的習慣或儀式；此句取「例行習慣」義。"]],"l6-0819":[["競爭","competition","The rivalry between the two firms has lowered prices for customers.","兩家公司之間的競爭降低了顧客支付的價格。","rivalry 強調長期互相較勁的關係。"]],"l6-0820":[["旋轉；輪流","spin / take turns","The machine rotates slowly while the coating dries.","塗層乾燥時，機器緩慢旋轉。","rotate 可指物體轉動，也可指人員輪班。"]],"l6-0821":[["旋轉；輪流","alternation","The nurse’s rotation places her in the emergency ward this month.","護理師這個月輪調到急診病房。","rotation 強調依序輪替或繞軸轉動。"]],"l6-0822":[["n：版稅；特許權使用費","royalty payment / licensing fee","He receives royalty from his book.","他從他的書獲得版稅。","royalty 指著作、專利或品牌授權所產生的版稅或使用費。"]],"l6-0823":[["紅寶石","gemstone","A small ruby was set in the center of the antique ring.","一顆小紅寶石鑲在古董戒指中央。","ruby 是紅色寶石名稱。"]],"l6-0824":[["vt / n：保護","protect / defend","We must safeguard our privacy.","我們必須保護我們的隱私。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0825":[["交誼廳；酒吧","lounge / bar","Guests gathered in the hotel saloon after the conference.","會議後，賓客聚集在飯店交誼廳。","saloon 可指休息廳，也可指酒吧。"]],"l6-0826":[["拯救","rescue / deliverance","The lifeguard’s quick action brought salvation to the stranded swimmer.","救生員迅速行動，拯救了受困的泳客。","salvation 指脫離危險或苦難的拯救。"]],"l6-0827":[["認可；制裁","approve / penalty","The agency sanctioned the project after an environmental review.","該機構完成環境審查後核准了計畫。","sanction 可指正式批准，也可指施加制裁，須看語境。"]],"l6-0828":[["名詞：教堂；庇護所","refuge / shrine","The old church offered sanctuary to travelers during the storm.","暴風雨期間，那座老教堂為旅人提供庇護。","sanctuary 可指聖所或安全避難處。"]],"l6-0829":[["神志正常的；健全的","rational / mentally sound","The doctor confirmed that the patient was sane and understood the risks.","醫師確認病人神志正常並了解風險。","sane 指心理狀態正常，也可指理性務實。"]],"l6-0830":[["公共衛生","public health / hygiene","Improved sanitation sharply reduced disease in the crowded district.","改善公共衛生大幅降低了擁擠地區的疾病。","sanitation 指供水、排污與清潔等公共衛生措施。"]],"l6-0831":[["adj：風景的；風景優美的","picturesque","We stayed in a scenic coastal town.","我們住在風景如畫的海濱小鎮。","scenic 形容與美麗景色有關，常指景色優美的地方或路線。"]],"l6-0832":[["範圍；領域","extent / range","The survey’s scope includes customers from five regions.","這項調查的範圍涵蓋五個地區的顧客。","scope 指活動、研究或責任涵蓋的界限。"]],"l6-0833":[["筆跡；腳本；編為劇本","manuscript / screenplay","The director revised the script after the first rehearsal.","導演在第一次排練後修改了劇本。","script 可指戲劇文字，也可指手寫字跡。"]],"l6-0834":[["n：部門；領域","department / division","The public sector is growing.","公共部門正在擴張。","sector 可指經濟或組織中的部門，也可指某個領域。"]],"l6-0835":[["誘惑","entice / tempt","The advertisement seduced shoppers with an unusually low price.","這則廣告以異常低價誘惑購物者。","seduce 常含以魅力或誘惑引人做某事的意味。"]],"l6-0836":[["adj：有選擇性的","discerning","She is discerning when choosing suppliers.","她挑選供應商時很有眼光。","discerning 形容能看出差異並做出明智選擇的。"]],"l6-0837":[["n：研討班；專題研討會","workshop / conference","She is attending a seminar.","她正在參加一個研討會。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0838":[["參議員","legislator","The senator introduced a bill to expand rural broadband.","這位參議員提出擴大鄉村寬頻的法案。","senator 指參議院議員。"]],"l6-0839":[["感傷的；多愁善感的","emotional / nostalgic","Her sentimental letter preserved every detail of their childhood trips.","她多情的信保留了童年旅行的每個細節。","sentimental 強調感情濃厚，有時帶有感傷意味。"]],"l6-0840":[["n：順序；序列","order / arrangement","Follow the correct sequence.","遵循正確的順序。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0841":[["安詳的；平靜的","calm / tranquil","The lake looked serene beneath the early morning mist.","清晨薄霧下的湖面顯得安詳平靜。","serene 形容外在環境或人的沉著寧靜。"]],"l6-0842":[["晴朗；平靜","peace / calmness","After the storm passed, a deep serenity settled over the village.","暴風雨過後，深沉的平靜籠罩村莊。","serenity 指持久而安寧的平靜狀態。"]],"l6-0843":[["n：服務；(食物)一份","portion","One serving is enough.","一份就夠了。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0844":[["n：會議；開庭；講習班","meeting / period","The training session is at 2 PM.","培訓課程在下午兩點。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0845":[["n：挫折","obstacle / difficulty","The project suffered a setback.","專案遭遇了挫折。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0846":[["污水管；下水道","drain","Leaves blocked the sewer and flooded the street.","落葉堵住下水道，造成街道淹水。","sewer 是輸送污水的地下管道系統。"]],"l6-0847":[["棚；流出；散發","drip / emit","The injured hiker’s knee shed blood through the bandage.","受傷健行者的膝蓋滲血，穿過繃帶流出。","shed 可指液體流出，也可指散發或脫落。"]],"l6-0848":[["adj：全然的 adv.十足地","pure / total","It was sheer luck.","那純粹是運氣。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0849":[["先令","無直接同義詞","The historical ledger lists the ticket price as two shillings.","歷史帳冊把票價記為兩先令。","shilling 是英國舊貨幣單位。"]],"l6-0850":[["在商店內順手牽羊","steal from a store","The teenager was arrested after trying to shoplift headphones.","那名青少年試圖在店內偷耳機後被捕。","shoplift 專指在商店偷竊商品。"]],"l6-0851":[["精明的；狡猾的","astute / crafty","A shrewd negotiator secured better terms without raising his voice.","精明的談判者不提高聲量便爭取到更好的條件。","shrewd 可指敏銳精明，也可帶狡猾意味。"]],"l6-0852":[["躲開","avoid / evade","The witness tried to shun reporters outside the courthouse.","證人在法院外試圖躲開記者。","shun 指有意避開某人或事物。"]],"l6-0853":[["圍攻","besiege / blockade","The army laid siege to the fortress for several weeks.","軍隊圍攻那座堡壘數週。","siege 指軍事包圍，也可比喻持續困擾。"]],"l6-0854":[["vt：表示；意味著","mean / indicate","What does this color signify?","這個顏色意味著什麼？","採用既有原創例句；同義詞依該義項校對。"]],"l6-0855":[["矽","semiconductor material","The chip factory uses purified silicon for its processors.","晶片工廠使用純化矽製造處理器。","silicon 是製造電子元件的重要化學元素。"]],"l6-0856":[["n：簡單；樸素","plainness / straightforwardness","I like the simplicity of the design.","我喜歡這個設計的簡潔。","simplicity 可指設計的簡潔或樸素。"]],"l6-0857":[["vt：簡化","streamline","We need to simplify the process.","我們需要簡化流程。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0858":[["同步的","concurrent","The two cameras recorded simultaneous views of the finish line.","兩台攝影機同步錄下終點線的畫面。","simultaneous 表示在同一時間發生。"]],"l6-0859":[["懷疑的","doubtful / mistrustful","Investors were skeptical of the startup’s promise of instant profits.","投資人對該新創立即獲利的承諾持懷疑態度。","skeptical 常與 of 連用，表示不輕信說法。"]],"l6-0860":[["掠過；瀏覽","glide over / browse","I skimmed the report before the meeting and marked two questions.","我在會議前快速瀏覽報告並標出兩個問題。","skim 指快速閱讀或掠過表面。"]],"l6-0861":[["俚語","colloquialism / informal expression","The translator kept the local slang in the dialogue to preserve its voice.","譯者保留對話中的地方俚語，以維持原有語氣。","slang 是特定群體使用的非正式詞語。"]],"l6-0862":[["砍；鞭打；砍痕；斜線","cut / slash mark","The editor used a slash to separate the two alternatives.","編輯用斜線分隔兩個選項。","slash 可指快速砍擊，也可指斜線符號。"]],"l6-0863":[["奴隸身分；奴役","enslavement / bondage","The museum exhibition documents the history of slavery in the region.","博物館展覽記錄了該地區的奴隸制度歷史。","slavery 指剝奪自由並迫使人受役的制度。"]],"l6-0864":[["n：狹縫；投幣口","opening / time slot","Put the coin in the slot.","把硬幣投入投幣口。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0865":[["貧民窟","shantytown / deprived district","The charity built a clinic in the city’s largest slum.","慈善團體在城內最大的貧民窟興建診所。","slum 指住房破敗、生活條件惡劣的市區。"]],"l6-0866":[["摑巴掌；響吻","slap","The coach smacked the ball over the outfielder’s head.","教練把球猛擊過外野手頭頂。","smack 可指用力拍打，也可表示響亮的一吻或聲音。"]],"l6-0867":[["天花","variola","Smallpox was eradicated through a worldwide vaccination campaign.","透過全球疫苗接種運動，天花已被消滅。","smallpox 是由天花病毒引起的傳染病。"]],"l6-0868":[["窒息","suffocate / stifle","Smoke smothered the room before firefighters reached the apartment.","消防員抵達公寓前，煙霧已使房間幾乎無法呼吸。","smother 可指使人窒息，也可指完全壓制。"]],"l6-0869":[["走私","transport illegally / conceal","Customs officers caught a group trying to smuggle rare reptiles.","海關人員抓到一群企圖走私稀有爬蟲的人。","smuggle 指秘密且非法地運送貨物、人員或動物。"]],"l6-0870":[["圈套；捕捉","trap / entangle","The detective set a snare to catch the thief returning to the warehouse.","偵探設下圈套，捕捉返回倉庫的小偷。","snare 可指捕獸器，也可比喻使人陷入的圈套。"]],"l6-0871":[["鬼鬼祟祟的","sly / furtive","A sneaky employee copied the confidential file before leaving.","一名鬼鬼祟祟的員工離開前複製了機密檔案。","sneaky 指暗中行動且不讓人察覺。"]],"l6-0872":[["嘲諷；冷笑","mock / scoff","The critic sneered at the proposal without offering an alternative.","評論家嘲諷這項提案，卻沒有提出替代方案。","sneer 常伴隨輕蔑的表情或語氣。"]],"l6-0873":[["vi / n：高飛；暴漲","skyrocket / rise","Profits have soared.","利潤大幅上升。","soar 在此表示數值大幅上升。"]],"l6-0874":[["好交際的","friendly / outgoing","Our sociable neighbor invites the whole block to dinner.","我們那位好交際的鄰居邀請整條街的人共進晚餐。","sociable 形容喜歡與人互動。"]],"l6-0875":[["社會主義","collectivism","The lecture examined how socialism shaped the country’s welfare system.","演講探討社會主義如何塑造該國福利制度。","socialism 是政治與經濟思想體系。"]],"l6-0876":[["社會主義者","leftist","The socialist campaigned for public ownership of the railway.","這名社會主義者主張鐵路公有化。","socialist 可指支持社會主義的人或政黨。"]],"l6-0877":[["交際；社會化","mingle / interact","New students socialize at the orientation picnic.","新生在迎新野餐會上彼此交際。","socialize 指與他人社交，也可指融入社會。"]],"l6-0878":[["社會學","無直接同義詞","She is studying sociology to understand workplace inequality.","她研讀社會學以了解職場不平等。","sociology 是研究社會與群體互動的學科。"]],"l6-0879":[["鈉","無直接同義詞","The nutrition label lists the soup’s sodium content per serving.","營養標示列出每份湯的鈉含量。","sodium 是化學元素名稱。"]],"l6-0880":[["團結","unity / cohesion","The workers showed solidarity during the contract negotiations.","勞工在合約談判期間展現團結。","solidarity 指為共同利益互相支持。"]],"l6-0881":[["孤獨","isolation / seclusion","After moving abroad, he struggled with solitude during the holidays.","移居海外後，他在假日期間難以承受孤獨。","solitude 強調獨處狀態，可中性或帶寂寞感。"]],"l6-0882":[["安慰；緩和","comfort / relieve","A warm compress soothed the pain in her shoulder.","溫敷緩和了她肩膀的疼痛。","soothe 可安慰情緒或減輕疼痛、刺激。"]],"l6-0883":[["adj：世故的； 精緻的；複雜的","complex / advanced","It is a sophisticated system.","這是一個複雜的系統。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0884":[["主權；統治權","supreme authority / sovereign power","The treaty recognizes the island’s sovereignty over its coastal waters.","條約承認該島對近海水域的主權。","sovereignty 指國家或統治者對領土行使的最高權力。"]],"l6-0885":[["adj：寬敞的","roomy / large","The office is very spacious.","這間辦公室非常寬敞。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0886":[["n：跨度；一段時間；vt：橫跨；延伸","duration / range","The project spans five years.","這個專案歷時五年。","span 作動詞時可表示持續一段時間或橫跨某段期間。"]],"l6-0887":[["vi：專攻 vt.使專門化","focus on","The company specializes in software.","這家公司專攻軟體。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0888":[["n：特產；專業","forte","Italian food is his specialty.","義大利菜是他的專長。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0889":[["vt：具體指明","state / detail","Please specify the date.","請指定日期。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0890":[["壯觀的","stunning / magnificent","The spectacular fireworks lit up the harbor.","壯觀的煙火照亮了港灣。","spectacular 強調景象非常引人注目。"]],"l6-0891":[["光譜","range","The sensor detects wavelengths across the visible spectrum.","感測器偵測可見光光譜中的各種波長。","spectrum 可指光的波長分布，也可指完整範圍。"]],"l6-0892":[["vi：思索；vt：推測","guess / surmise","They are speculating about the results.","他們正在推測結果。","speculate about + 名詞表示推測、猜測某事；此處不是正式調查。"]],"l6-0893":[["球體；領域","globe / domain","The research explores the sphere of online privacy.","這項研究探討網路隱私的領域。","sphere 可指圓球形體，也可比喻活動範圍。"]],"l6-0894":[["大釘；釘鞋；刺穿；扣殺","nail","The volleyball player spiked the ball past the blockers.","排球選手把球扣殺越過攔網者。","spike 作動詞在排球中指用力扣球。"]],"l6-0895":[["螺旋；盤旋","coil","The smoke spiraled upward from the chimney.","煙霧從煙囪螺旋上升。","spiral 可作名詞、形容詞或動詞，核心是螺旋形。"]],"l6-0896":[["尖塔；聳立","steeple / tower","The church spire was visible above the town’s rooftops.","教堂尖塔在城鎮屋頂上方清晰可見。","spire 指細長尖頂，常見於教堂。"]],"l6-0897":[["發言人","representative / spokesperson","The company spokesperson answered questions about the recall.","公司發言人回答有關召回產品的問題。","spokesperson 是代表組織公開發言的人。"]],"l6-0898":[["n：發起者；贊助者；vt：資助","patron / backer","We are looking for a new sponsor.","我們正在尋找新的贊助商。","sponsor 作名詞可指提供資金或支持的個人、公司或機構。"]],"l6-0899":[["自發的","voluntary / impulsive","The audience gave a spontaneous round of applause.","觀眾自發地鼓起掌來。","spontaneous 指未事先安排、自然發生。"]],"l6-0900":[["n：配偶","husband / wife","Please include your spouse's name.","請填寫配偶的姓名。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0901":[["不及物動詞：伸開四肢躺；蔓生","lie sprawled / spread","After the long flight, he sprawled across the sofa with a book.","長途飛行後，他攤躺在沙發上看書。","本句採伸展四肢躺臥義；植物蔓生是另一用法。"]],"l6-0902":[["小隊","team / unit","A rescue squad searched the ravine before nightfall.","救援小隊在天黑前搜尋山谷。","squad 指為特定任務組成的小型團隊。"]],"l6-0903":[["壓扁；回力球；南瓜","crush / compress","Please squash the empty cans before putting them in the recycling bin.","請先把空罐壓扁再放進回收桶。","squash 作動詞是壓扁，作名詞也可指球類或南瓜。"]],"l6-0904":[["n：穩定(性)","steadiness","We need more stability.","我們需要更多穩定性。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0905":[["穩定","steady / secure","The treatment helped stabilize the patient’s blood pressure.","治療幫助穩定病人的血壓。","stabilize 指使狀態或數值不再劇烈變動。"]],"l6-0906":[["動詞、名詞：悄悄追蹤","follow stealthily","The ranger watched a wolf stalk its prey through the tall grass.","巡護員看著一隻狼悄悄穿過高草追蹤獵物。","stalk 作動詞時指悄悄跟蹤。"]],"l6-0907":[["口吃","stutter","He stammered when asked to explain the missing funds.","被要求解釋資金短缺時，他口吃起來。","stammer 可指說話不流暢，也可作名詞。"]],"l6-0908":[["n：主食；訂書釘；adj：主要的","fastener / main","Use a staple to fasten the paper.","用訂書針把紙張固定好。","staple 作名詞可指訂書針；fasten the paper 表示把紙張固定起來。"]],"l6-0909":[["主要產品經營商；釘書機","office fastener","Use the stapler to attach the receipts to the expense form.","用釘書機把收據釘在費用表上。","stapler 在辦公語境通常指釘書機。"]],"l6-0910":[["澱粉","carbohydrate","Potatoes contain starch that thickens the soup as it cooks.","馬鈴薯含有澱粉，烹煮時會使湯變稠。","starch 是植物儲存能量的碳水化合物。"]],"l6-0911":[["飢餓","famine","The relief agency delivered grain to prevent starvation.","救援機構運送穀物以防止飢餓。","starvation 指長期缺乏食物造成的嚴重飢餓。"]],"l6-0912":[["adj：不動的","fixed / motionless","The car is stationary.","那輛車是靜止的。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0913":[["n：文具[U]","office supplies","We need more stationery.","我們需要更多文具。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0914":[["身高；身材；高度境界","height / standing","Her stature made it easy to spot her in the crowded hall.","她的身高讓人在擁擠大廳中很容易找到她。","stature 可指身高，也可指成就與地位。"]],"l6-0915":[["名詞：汽船；蒸鍋；蒸汽機","steamship","The steamer carried passengers along the coastal route.","那艘汽船沿著海岸航線載運乘客。","本句採汽船義。"]],"l6-0916":[["vt / vi：刺激；促使","encourage / boost","The plan aims to stimulate growth.","該計畫旨在刺激成長。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0917":[["刺激；鼓舞","encouragement / activation","The scholarship provided stimulation for students to pursue research.","獎學金鼓舞學生投入研究。","stimulation 指促使活動、成長或興趣增加的刺激。"]],"l6-0918":[["刺激品","incentive / trigger","The bonus was a strong stimulus for the sales team to exceed its goal.","獎金是促使業務團隊超越目標的強大刺激。","stimulus 指引發反應或行動的事物。"]],"l6-0919":[["名詞：存貨；股票；動詞：備貨","inventory / shares","The shop checked its stock before placing a new order.","商店在下新訂單前先清點存貨。","本句採存貨義。"]],"l6-0920":[["勒死；抑制","stifle","The scarf was tight enough to strangle him, so he loosened it.","圍巾太緊，幾乎勒住他的脖子，因此他把它鬆開。","strangle 指阻斷呼吸，也可比喻壓制發展。"]],"l6-0921":[["adj：戰略的","planned","This is a strategic move.","這是一個策略性的舉動。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0922":[["絕技；阻礙","feat / hamper","The cyclist performed a dangerous stunt for the film.","自行車手為電影表演危險絕技。","stunt 作名詞是特技，作動詞也可指阻礙成長。"]],"l6-0923":[["主觀的；個人的","personal / biased","The review is subjective because it reflects one reader’s taste.","這篇評論很主觀，因為它反映單一讀者的品味。","subjective 依個人感受或觀點，而非客觀測量。"]],"l6-0924":[["adj：下級的；隸屬的","junior / lower-ranking / dependent","The subordinate staff followed the manager's instructions.","下屬員工遵照經理的指示。","例句使用 subordinate 作形容詞，表示下級的、隸屬的。"]],"l6-0925":[["訂閱；登記訂閱","register","I subscribe to this magazine.","我訂閱這本雜誌。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0926":[["n：訂閱；訂閱服務","membership","My subscription expired.","我的訂閱過期了。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0927":[["adj：隨後的","following","The subsequent events were confusing.","隨後的事件令人困惑。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0928":[["代替物","replacement / substitute","The chef used tofu as a substitution for meat in the curry.","主廚在咖哩中用豆腐代替肉類。","substitution 指以一物取代另一物。"]],"l6-0929":[["微妙的；隱約的","delicate / faint","There was a subtle change in the speaker’s tone.","講者的語氣出現微妙變化。","subtle 指細微、不易立即察覺的差異。"]],"l6-0930":[["郊區的；郊外的","residential","A suburban train carries commuters into the city each morning.","郊區列車每天早上載通勤者進城。","suburban 指城市周邊住宅區的事物。"]],"l6-0931":[["n：連續；繼任","sequence / series","They won three games in succession.","他們連續贏了三場比賽。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0932":[["連續的；後繼的","consecutive","Three successive storms damaged the coastal road.","連續三場暴風雨損壞了沿海公路。","successive 強調一個接一個發生。"]],"l6-0933":[["繼承人；接替者","replacement / heir","The director introduced her successor at the annual meeting.","董事在年度會議介紹了她的接班人。","successor 是接替職位或地位的人或事物。"]],"l6-0934":[["窒息","choke","The smoke began to suffocate residents trapped on the upper floor.","煙霧開始使困在樓上的居民窒息。","suffocate 指因缺氧而無法呼吸。"]],"l6-0935":[["n：套房；一套房間","room","They stayed in a hotel suite.","他們住在飯店套房。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0936":[["adj：堂皇的；極好的","excellent / outstanding / wonderful","The food at the restaurant was superb.","那家餐廳的食物非常美味。","superb 表示極好的、卓越的；此處形容食物非常美味。"]],"l6-0937":[["優越","dominance","The team’s superiority was clear from its control of the midfield.","從掌控中場可看出該隊的優越。","superiority 指能力、地位或品質高於他者。"]],"l6-0938":[["超音波的；超音速","sonic","The aircraft reached supersonic speed over the ocean.","飛機在海上達到超音速。","supersonic 指速度超過音速。"]],"l6-0939":[["迷信的","irrational","My superstitious aunt refuses to open an umbrella indoors.","我那位迷信的阿姨拒絕在室內撐傘。","superstitious 指相信缺乏理據的吉凶觀念。"]],"l6-0940":[["n：監督；監管","oversight","The work was done under supervision.","工作是在監督下完成的。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0941":[["n：增補；補給品","addition / add","He takes a vitamin supplement.","他服用維他命補充劑。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0942":[["vt：勝過","exceed / excel","The results surpassed our expectations.","結果超越了我們的預期。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0943":[["n / adj：過剩（的）；剩餘物","excess / remainder","We have a budget surplus.","我們有預算盈餘。","本句使用 surplus 的名詞義，指收入超過支出的預算盈餘。"]],"l6-0944":[["懸而不決；懸念","tension / uncertainty","The courtroom drama kept viewers in suspense until the verdict.","這部法庭劇讓觀眾懸念到判決揭曉。","suspense 指結果未明造成的緊張期待。"]],"l6-0945":[["懸吊；暫停","halt / hanging","The bridge closed during suspension of the inspection work.","檢查工作暫停期間，橋梁關閉。","suspension 可指暫停，也可指懸掛或懸吊系統。"]],"l6-0946":[["vt / vi / n：交換","exchange / trade","Let's swap places.","我們交換位置吧。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0947":[["象徵的","representative / emblematic","The dove is symbolic of peace in many cultures.","在許多文化中，鴿子象徵和平。","symbolic 表示具有象徵意義，而非字面用途。"]],"l6-0948":[["象徵","represent / stand for","The rising sun symbolizes hope in the mural.","壁畫中的旭日象徵希望。","symbolize 指以具體事物代表抽象概念。"]],"l6-0949":[["對稱；對稱性","balance","The architect checked the symmetry of the entrance before finalizing the plan.","建築師定案前檢查入口的對稱性。","symmetry 指兩側或各部分呈現均衡對應。"]],"l6-0950":[["n：症狀","sign / indication","A cough can be a symptom of a cold.","咳嗽可能是感冒的症狀。","以 symptom of 搭配具體疾病，清楚呈現症狀與疾病的關係。"]],"l6-0951":[["同義詞","equivalent","“Begin” is a synonym for “start” in this sentence.","在這個句子中，begin 是 start 的同義字。","synonym 指意義相同或非常接近的詞。"]],"l6-0952":[["合成的","artificial / man-made","The jacket uses synthetic fibers that dry quickly.","這件外套使用快乾的合成纖維。","synthetic 指人工合成而非天然產生。"]],"l6-0953":[["機智；圓融的處事方式","diplomacy","She handled the complaint with tact and kept the customer calm.","她圓滑地處理抱怨，讓顧客保持冷靜。","tact 指在敏感情境中顧及他人感受的分寸。"]],"l6-0954":[["戰術；策略","strategy / maneuver","The coach changed tactics at halftime to stop the counterattack.","教練在中場休息時改變戰術以阻止反擊。","tactic 是達成較大目標的具體做法。"]],"l6-0955":[["關稅；稅率","duty / customs tax","The new tariff raised the price of imported steel.","新的關稅提高了進口鋼材價格。","tariff 是政府對進出口商品課徵的稅。"]],"l6-0956":[["adj：冗長乏味的","boring / dull","The job is tedious.","這份工作很乏味。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0957":[["氣質；性情","disposition / character","Her calm temperament helps her manage difficult negotiations.","她沉著的性情幫助她處理艱難談判。","temperament 指一個人穩定的情緒與性格傾向。"]],"l6-0958":[["暴風雨；騷動","storm / turmoil","The fishing boats returned before the tempest reached the coast.","暴風雨抵達海岸前，漁船都返航了。","tempest 是強烈暴風雨，也可比喻劇烈騷動。"]],"l6-0959":[["vt / vi：(使)終止","end / finish","They terminated the contract.","他們終止了合約。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0960":[["n：紡織品 adj.紡織的","fabric / cloth","They work in the textile industry.","他們在紡織業工作。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0961":[["質地；構造","feel / grain","The fabric’s smooth texture makes the uniform comfortable.","布料的平滑質地讓制服穿起來很舒適。","texture 指表面的觸感或材料的結構。"]],"l6-0962":[["戲劇的；誇張的","dramatic","His theatrical gesture made the short announcement memorable.","他誇張的手勢讓簡短公告令人難忘。","theatrical 可指與戲劇有關，也可指表現過度誇張。"]],"l6-0963":[["n：偷竊","stealing / larceny","He was arrested for theft.","他因竊盜被捕。","theft 指偷竊或竊盜行為；不要與通常涉及暴力或威脅的 robbery 混用。"]],"l6-0964":[["理論的","conceptual / hypothetical","The course covers theoretical models before students run experiments.","課程先講授理論模型，再讓學生進行實驗。","theoretical 關注原理或假設，未必已實際驗證。"]],"l6-0965":[["特定療法技師","counselor / clinician","The therapist taught him exercises to restore movement in his shoulder.","治療師教他恢復肩部活動的運動。","therapist 指提供心理或身體治療的專業人員。"]],"l6-0966":[["治療；療法","treatment / cure","Physical therapy helped the athlete regain strength after surgery.","物理治療幫助運動員在手術後恢復力量。","therapy 是針對疾病或傷勢的治療方法。"]],"l6-0967":[["之後","afterward / subsequently","The files were archived thereafter according to the retention policy.","之後，檔案依保存政策歸檔。","thereafter 指從某一時間點起的後續期間。"]],"l6-0968":[["由此；從而","therefore / consequently","The receipt was unsigned, thereby delaying reimbursement.","收據沒有簽名，因此延誤了費用核銷。","thereby 表示前述行動直接造成後果。"]],"l6-0969":[["溫度計","temperature gauge","The nurse used a thermometer to check the child’s fever.","護理師用溫度計檢查孩子是否發燒。","thermometer 是測量溫度的儀器。"]],"l6-0970":[["門檻；開端","brink","The company is on the threshold of entering a new market.","公司正處於進入新市場的開端。","threshold 可指入口，也可比喻重要轉折點。"]],"l6-0971":[["節儉","frugality / thriftiness","Her thrift allowed the family to pay off the mortgage early.","她的節儉讓全家得以提早還清房貸。","thrift 指明智節省金錢或資源。"]],"l6-0972":[["adj：節儉的","economical / frugal","She is a thrifty shopper who compares prices before buying.","她是個節儉的購物者，買東西前會比較價格。","thrifty 表示節儉、精打細算；本句採購物者語境呈現此義。"]],"l6-0973":[["vi：興旺；繁榮","prosper / flourish","The business is thriving.","這門生意蒸蒸日上。","business is thriving 表示事業蓬勃發展或生意蒸蒸日上。"]],"l6-0974":[["跳動；悸動","pulsate / beat","A dull throb in his knee returned after the long hike.","長途健行後，他的膝蓋又傳來鈍痛悸動。","throb 指有規律的疼痛或強烈跳動。"]],"l6-0975":[["通行費；傷亡；鐘聲","fee","Drivers pay a toll before entering the expressway.","駕駛人在進入高速公路前支付通行費。","toll 也可指傷亡代價或鐘聲。"]],"l6-0976":[["倒塌","collapse / overturn","The old fence toppled when the ground softened in the rain.","大雨使地面變軟，老圍籬隨之倒塌。","topple 指失去平衡而倒下。"]],"l6-0977":[["龍捲風","twister","The tornado destroyed several barns along the rural highway.","龍捲風摧毀鄉間公路旁的幾座穀倉。","tornado 是快速旋轉的猛烈風柱。"]],"l6-0978":[["n：特徵；少許","attribute / feature","Patience is an important trait for a manager.","耐心是經理的重要特質。","trait 指人的性格或行為特徵；本句以管理工作所需的耐心作為例子。"]],"l6-0979":[["平靜的","calm / peaceful","The harbor remained tranquil despite the busy festival nearby.","儘管附近節慶熱鬧，港口仍保持平靜。","tranquil 形容安寧、沒有騷動的狀態。"]],"l6-0980":[["鎮定劑","sedative","The veterinarian gave the dog a mild tranquilizer before surgery.","獸醫在手術前給狗服用溫和鎮定劑。","tranquilizer 是使人或動物鎮靜的藥物。"]],"l6-0981":[["n：交易；辦理","deal / business operation","The transaction was completed.","交易已完成。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0982":[["成績單；正式文字記錄","record","The university requested an official transcript with the application.","大學要求申請附上正式成績單。","transcript 可指逐字記錄或學校成績單。"]],"l6-0983":[["n：轉變；變形","change / conversion","There was a major transformation.","發生了重大的轉變。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0984":[["電晶體；半導體元件","semiconductor","The radio stopped working after a transistor burned out.","電晶體燒壞後，收音機停止運作。","transistor 是放大或切換電子訊號的元件。"]],"l6-0985":[["n：運輸；運輸中；過渡","transportation","The goods are in transit.","貨物在運輸途中。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0986":[["n：過渡；轉變","change / shift","It was a smooth transition.","那是一個順利的過渡。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0987":[["傳輸；傳送","transfer / broadcast","The satellite enables transmission of weather data to ships.","衛星讓氣象資料得以傳送到船隻。","transmission 指訊號、資料或動力的傳遞。"]],"l6-0988":[["vt / vi：傳送；發報","send / transfer","Transmit the data now.","現在傳輸這些數據。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0989":[["移植；移居","relocate / graft","Surgeons transplanted a healthy kidney into the patient.","外科醫師把健康腎臟移植給病人。","transplant 可指器官移植，也可指植物移栽或人口遷移。"]],"l6-0990":[["創傷","shock","The accident left him with lasting emotional trauma.","那場事故讓他留下持久的心理創傷。","trauma 可指身體傷害或嚴重心理打擊。"]],"l6-0991":[["踩；踏","step on","Please tread carefully on the freshly painted floor.","請小心踩踏剛上漆的地板。","tread 強調腳踩在表面上的動作。"]],"l6-0992":[["叛國罪","betrayal","The officer was tried for treason after leaking defense plans.","那名軍官洩露國防計畫後因叛國罪受審。","treason 指背叛國家或君主的重罪。"]],"l6-0993":[["艱苦跋涉；旅行","journey / hike","The researchers trekked through the mountains for ten days.","研究人員在山區艱苦跋涉十天。","trek 強調漫長而辛苦的旅程。"]],"l6-0994":[["顫抖；震動","tremble / shiver","A tremor shook the windows during the distant explosion.","遠處爆炸時，震動使窗戶搖晃。","tremor 可指身體顫抖或輕微地震。"]],"l6-0995":[["vi / n：擅自進入；侵入","intrude","Do not trespass.","不要侵入。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0996":[["n：扳機 vt.扣扳機；引起","cause / activate","Trigger a reaction.","引發反應。","採用既有原創例句；同義詞依該義項校對。"]],"l6-0997":[["勝利的","victorious / celebrating victory","The triumphant team lifted the trophy above its heads.","勝利的隊伍把獎杯高舉過頭。","triumphant 強調公開慶祝勝利的情緒；victorious 僅陳述獲勝。"]],"l6-0998":[["形容詞：瑣碎的；不重要的","minor / unimportant","We should not argue over such a trivial matter.","我們不該為了這麼瑣碎的事爭吵。","trivial 表示事情不重要或不值得過度關注。"]],"l6-0999":[["戰利品；獎杯","prize / cup","The runner placed her first marathon trophy on the shelf.","這名跑者把人生第一座馬拉松獎杯放在架上。","trophy 可指競賽獎杯，也可指象徵勝利的物品。"]],"l6-1000":[["熱帶；回歸線","tropical zone","The Tropic of Cancer crosses several countries in the Northern Hemisphere.","北回歸線穿過北半球數個國家。","tropic 可指地理上的回歸線或熱帶地區。"]],"l6-1001":[["逃學者；逃學的","absentee","The school counselor contacted the parents of a frequent truant.","學校輔導員聯絡了一名經常逃學的學生的家長。","truant 指無故不上學的人或行為。"]],"l6-1002":[["停戰","cease-fire / armistice","The two sides observed a fragile truce for six months.","雙方維持脆弱停戰六個月。","truce 是敵對雙方暫時停止戰鬥的協議。"]],"l6-1003":[["結核病","TB","The clinic screens migrant workers for tuberculosis.","診所為移工篩檢結核病。","tuberculosis 是由細菌引起的傳染病。"]],"l6-1004":[["腫瘤","growth / neoplasm","The scan revealed a benign tumor near the patient’s kidney.","掃描顯示病人腎臟附近有良性腫瘤。","tumor 指細胞異常增生形成的腫塊。"]],"l6-1005":[["騷動；混亂","disorder / upheaval","The sudden resignation caused turmoil inside the department.","突然辭職在部門內引發騷動。","turmoil 指混亂、動盪且難以控制的狀態。"]],"l6-1006":[["名詞：薄暮；黃昏","dusk","We returned to the village at twilight.","我們在黃昏時回到了村莊。","本句 at twilight 表示黃昏時；twilight 也可指日出前的微光時分。"]],"l6-1007":[["暴政；專橫","despotism / oppression","The novel portrays life under a ruler’s tyranny.","小說描寫人民在統治者暴政下的生活。","tyranny 指殘酷專橫的統治。"]],"l6-1008":[["潰瘍；弊病","sore / lesion","The doctor prescribed medicine for the stomach ulcer.","醫師開藥治療胃潰瘍。","ulcer 可指身體潰瘍，也可比喻難以根除的弊病。"]],"l6-1009":[["adj：最終的；極限的","final / supreme","The ultimate goal is to succeed.","最終目標是成功。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1010":[["adj：一致同意的","united / in agreement","The decision was unanimous.","這項決定獲得一致通過。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1011":[["vt：揭露","reveal / discover","They uncovered the truth.","他們揭露了真相。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1012":[["vt：低估","undervalue / underrate","Do not underestimate the problem.","不要低估這個問題。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1013":[["vt：經歷；接受(治療等)","experience / go through","He must undergo surgery.","他必須接受手術。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1014":[["vt：暗中破壞","weaken / compromise","These actions undermine the plan.","這些行為削弱了這個計畫。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1015":[["vt：進行；承擔","take on","He will undertake the project.","他將承擔該專案。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1016":[["解開；取消；破壞","reverse / untie","Clicking this button will undo the last change to the document.","按下此按鈕會取消文件上一個變更。","undo 指撤銷動作，也可解開結或破壞成果。"]],"l6-1017":[["n：失業","joblessness","The unemployment rate is rising.","失業率正在上升。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1018":[["vt / vi：展開","develop / reveal","Watch the story unfold.","看著故事展開。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1019":[["vt / vi：統一","unite / consolidate","They want to unify the country.","他們想要統一這個國家。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1020":[["vt / vi：開…的鎖；解開","unfasten / open","Unlock the office door.","解開辦公室的門鎖。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1021":[["動詞：取出箱中物品","empty / take out","Please unpack the boxes before the inspection.","請在檢查前把箱子裡的東西取出來。","unpack 指從箱、包等容器取出物品，通常不只是打開封口。"]],"l6-1022":[["養育；教養","rearing","Her strict upbringing taught her to value punctuality.","嚴格的教養讓她重視守時。","upbringing 指童年受到的家庭教育與培養。"]],"l6-1023":[["n / vt：升級；提高品質","improve / update","We need to upgrade the system.","我們需要升級系統。","upgrade 可作名詞或動詞，表示提升系統、設備或品質。"]],"l6-1024":[["vt：支持；維持；維護","support / maintain","We uphold the rules.","我們維護這些規則。","uphold 常用於支持法律、原則、決定或維持規範。"]],"l6-1025":[["鈾","radioactive element","The reactor uses uranium as fuel for nuclear fission.","反應爐使用鈾作為核分裂燃料。","uranium 是具放射性的化學元素。"]],"l6-1026":[["緊急；急事","emergency","The urgency of the repair became clear when the pipe burst.","管線爆裂後，維修的緊急性顯而易見。","urgency 指需要立即處理的迫切程度。"]],"l6-1027":[["尿","bodily waste","The nurse collected a urine sample for laboratory testing.","護理師收集尿液樣本送實驗室檢驗。","urine 是腎臟排出的液體。"]],"l6-1028":[["n：引座員 vt.vi.招待；迎接","guide / escort","The usher showed us our seats.","招待員帶我們到座位。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1029":[["名詞：器具；廚房用具","implement","Wash the kitchen utensils after preparing the meal.","備餐後，請把廚房用具洗乾淨。","utensil 指有特定用途的器具，常用於餐具或廚房用具；implement 範圍較廣。"]],"l6-1030":[["n：效用；公用事業；(水、 電、瓦斯類等的)公共設施 adj.實用的","service","Utility bills are high.","水電費用很高。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1031":[["vt：利用","use / employ","We utilize new software.","我們利用新軟體。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1032":[["adj：最大的；極度的；n：最大限度","greatest","Please handle the antique vase with the utmost care.","請以最大的謹慎處理這只古董花瓶。","utmost 表示可達到的最高程度；the utmost care 表示最大的謹慎。"]],"l6-1033":[["n：疫苗","immunization","The clinic offers a vaccine against seasonal influenza.","診所提供預防季節性流感的疫苗。","vaccine 是刺激免疫力以預防疾病的製劑。"]],"l6-1034":[["adj：英勇的","brave / courageous","The valiant firefighter entered the burning house to rescue a child.","英勇的消防員進入燃燒中的房屋救出孩子。","valiant 帶有面對危險仍勇敢行動的意味。"]],"l6-1035":[["adj：有根據的；有效的","effective / legitimate","Your ticket is still valid.","你的票仍然有效。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1036":[["正當；有效性；合法性","soundness","The court questioned the validity of the unsigned contract.","法院質疑未簽名合約的法律效力。","validity 指論點、文件或法律的有效程度。"]],"l6-1037":[["香草；普通的","plain","The bakery filled the cake with vanilla cream.","麵包店在蛋糕中夾入香草奶油。","vanilla 作名詞是香草，作形容詞也可指普通無特色。"]],"l6-1038":[["adj：多變的 n.可變因素","changeable / factor","Weather is a variable factor.","天氣是一個變動的因素。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1039":[["變動；差異","difference / fluctuation","Seasonal variation affects the demand for heating oil.","季節變動會影響暖油需求。","variation 指數值、形式或情況的改變。"]],"l6-1040":[["出售","sell / market","The farmer vends fresh berries at the weekend market.","農夫在週末市集販售新鮮莓果。","vend 是較正式的出售用語，常指攤販販賣。"]],"l6-1041":[["n：賣方；供應商","seller / supplier","Contact the software vendor.","聯繫軟體供應商。","vendor 指販售商品或服務的人、公司或商家。"]],"l6-1042":[["邊緣；處在邊緣","brink / edge","The hikers stood on the verge of the cliff and stepped back.","健行者站在懸崖邊緣後退了回來。","verge 指即將發生之事的邊緣或地理邊界。"]],"l6-1043":[["形容詞：多功能的","multipurpose","This versatile tool can cut wire and tighten screws.","這件多功能工具可以剪斷電線，也能鎖緊螺絲。","本句 versatile 指工具用途多樣；形容人時也可表示多才多藝。"]],"l6-1044":[["版本；說法","edition / account","This software version fixes the security flaw in the previous release.","這個軟體版本修正了前一版的安全漏洞。","version 可指產品版本，也可指事件的不同說法。"]],"l6-1045":[["老兵；老手","experienced person / ex-soldier","A veteran editor spotted the citation error immediately.","一位資深編輯立刻發現引用錯誤。","veteran 可指有經驗的人，也可指退伍軍人。"]],"l6-1046":[["獸醫","animal doctor","The veterinarian examined the injured cat before prescribing antibiotics.","獸醫檢查受傷的貓後開了抗生素。","veterinarian 是治療動物的醫師。"]],"l6-1047":[["顫動；共鳴","oscillation / resonance","The vibration of the bridge increased as more trucks crossed it.","更多卡車通過時，橋梁的顫動加劇。","vibration 指快速往復的晃動，也可指共鳴感。"]],"l6-1048":[["n：惡習；罪惡；（vice-）副職的","deputy","The report describes corruption as a vice that weakens public trust.","報告把貪腐描述為削弱公共信任的弊病。","vice 作名詞可指惡習或罪惡；vice- 作前綴時表示副職。"]],"l6-1049":[["邪惡的；惡性的","evil / malignant","The vicious dog attacked the mail carrier.","那隻兇猛的狗攻擊了郵差。","vicious 可指殘暴、兇猛，也可指疾病或循環惡性。"]],"l6-1050":[["使受害；欺騙","exploit","Scammers victimized elderly customers with fake investment offers.","詐騙者以虛假投資邀約欺騙年長顧客。","victimize 指使某人遭受傷害、剝削或欺騙。"]],"l6-1051":[["勝利者","winner / champion","The victor thanked her coach after accepting the medal.","勝利者領獎後向教練致謝。","victor 指在競賽或衝突中獲勝的人。"]],"l6-1052":[["勝利的","winning / triumphant","The victorious crew waved from the deck as the race ended.","比賽結束時，勝利的船員在甲板上揮手。","victorious 直接表示已取得勝利。"]],"l6-1053":[["別墅","country house","They rented a seaside villa with a private garden.","他們租了一棟有私人花園的海邊別墅。","villa 通常指寬敞的獨立住宅。"]],"l6-1054":[["葡萄園","grape farm","The vineyard harvest begins when the grapes reach full sweetness.","葡萄達到最甜時，葡萄園便開始採收。","vineyard 是種植葡萄以釀酒或食用的農地。"]],"l6-1055":[["adj：實際上的；虛擬的","online","We will host a virtual meeting tomorrow.","我們明天將舉辦一場虛擬會議。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1056":[["vt / vi：使視覺化；想像","imagine","Try to visualize the final outcome.","試著想像最終的結果。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1057":[["活力；生命力","energy","Regular exercise restored her vitality after the illness.","規律運動讓她病後恢復活力。","vitality 指身體或生命旺盛的能量。"]],"l6-1058":[["聲音的；歌唱的","spoken","The singer warmed up her vocal cords before the concert.","歌手在演唱會前讓聲帶熱身。","vocal 可指聲音相關，也可指歌唱或公開發言。"]],"l6-1059":[["n：天職；職業","calling / career","He considers teaching to be his vocation.","他認為教書是他的天職。","vocation 可指適合某人的職業或使命感很強的天職。"]],"l6-1060":[["職業的","occupational","The college offers vocational training in electrical repair.","這所學院提供電氣維修的職業訓練。","vocational 指為特定工作技能而設的教育。"]],"l6-1061":[["n：流行；時尚","fashion / trend","Wide-leg trousers returned to vogue this year.","寬管褲今年重新流行。","vogue 指某時期廣受歡迎的風尚。"]],"l6-1062":[["嘔吐","throw up","The medication made him vomit shortly after breakfast.","藥物讓他早餐後不久嘔吐。","vomit 可作動詞或名詞，指吐出胃內容物。"]],"l6-1063":[["粗俗的；通俗的","coarse / common","The comedian apologized for a vulgar joke that offended the audience.","喜劇演員為冒犯觀眾的粗俗笑話道歉。","vulgar 可指粗鄙失禮，也可指平民通俗。"]],"l6-1064":[["易受傷的","susceptible / exposed","Young plants are vulnerable to frost during the first week outdoors.","幼苗移到戶外的第一週容易受霜害。","vulnerable 常與 to 連用，表示容易受傷或攻擊。"]],"l6-1065":[["n：衣櫥","closet / cabinet","Hang your coat in the wardrobe.","把你的外套掛在衣櫃裡。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1066":[["戰爭","armed conflict / combat","The museum exhibition explains how modern warfare affects civilians.","博物館展覽說明現代戰爭如何影響平民。","warfare 指有組織的戰爭行動與作戰方式。"]],"l6-1067":[["n：保證書；擔保","guarantee","The laptop comes with a one-year warranty.","這台筆記型電腦附有一年保固。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1068":[["防水的","impermeable / watertight","The waterproof jacket kept her dry during the mountain storm.","防水外套讓她在山區暴風雨中保持乾燥。","waterproof 表示水無法穿透；watertight 也可指論點無漏洞。"]],"l6-1069":[["任何事物；無論甚麼","at all / anything","The hikers found no shelter whatsoever before nightfall.","健行者在天黑前完全找不到任何避難處。","whatsoever 通常放在否定詞後以加強語氣。"]],"l6-1070":[["n：擋風玻璃","windscreen","The stone cracked the car's windshield.","石頭砸裂了汽車的擋風玻璃。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1071":[["vt：抵抗；承受","resist / endure","The building was designed to withstand earthquakes.","這棟建築設計用來承受地震。","withstand 主要作及物動詞，表示抵抗或承受壓力、損害等。"]],"l6-1072":[["機智的；說話風趣的","clever / humorous","Her witty reply eased the tension in the crowded meeting room.","她機智的回答緩和了擁擠會議室中的緊張氣氛。","witty 指反應敏捷且風趣，常形容言語。"]],"l6-1073":[["追求；求愛；爭取","court / seek","The nonprofit is wooing corporate sponsors for its literacy program.","這個非營利組織正爭取企業贊助識字計畫。","woo 可指求愛，也可引申為積極爭取支持。"]],"l6-1074":[["猛扭；扭傷","twist / sprain","He wrenched his ankle when the ladder slipped on the wet floor.","梯子在濕地板上滑動時，他猛然扭傷了腳踝。","wrench 指突然用力扭轉，也可指因此造成的傷勢。"]],"l6-1075":[["摔角；搏鬥","grapple / struggle","The two athletes wrestled for control of the final point.","兩名運動員為掌握最後一分而摔角爭鬥。","wrestle 可指正式摔角，也可指與困難搏鬥。"]],"l6-1076":[["影印機；靜電複印法","photocopier / make a copy","Please Xerox the signed contract and file the original.","請把簽署的合約影印一份並歸檔正本。","Xerox 是商標，作動詞時常指影印。"]],"l6-1077":[["vi：思念；渴望","long / desire / crave","Many employees yearn for a better work-life balance.","許多員工渴望有更好的工作與生活平衡。","採用既有原創例句；同義詞依該義項校對。"]],"l6-1078":[["名詞：熱心；熱誠","enthusiasm / fervor","Her zeal for restoring old buildings inspired the entire volunteer team.","她熱心修復老建築，激勵了整個志工團隊。","zeal 指強烈而持久的熱忱。"]]}};
